nonisolated enum FirstRunScreenAnswerPolicy {
    static let timeoutSeconds: TimeInterval = 90

    static func shouldKeepWaiting(
        elapsedSeconds: TimeInterval,
        taskFinished: Bool,
        cancelled: Bool
    ) -> Bool {
        !taskFinished
            && !cancelled
            && elapsedSeconds < timeoutSeconds
    }
}

