nonisolated enum PartnerControlAction: Equatable {
    case screenContext
    case identitySave
    case voicePreview
}

nonisolated enum PartnerControlActionBlocker: Equatable {
    case notEntitled
    case effectsBlocked
    case controllerUnavailable
    case partnerSessionInactive
    case partnerSessionActive
    case screenContentUnavailable
}

/// Pure admission policy for the three Partner controls that previously
/// returned silently. The UI and business action now agree on the exact
/// prerequisite that failed.
nonisolated enum PartnerControlActionAdmission {
    static func blocker(
        for action: PartnerControlAction,
        isEntitled: Bool,
        effectsAreAllowed: Bool,
        controllerIsAvailable: Bool,
        partnerSessionIsActive: Bool,
        screenContentIsReady: Bool
    ) -> PartnerControlActionBlocker? {
        guard isEntitled else { return .notEntitled }
        guard effectsAreAllowed else { return .effectsBlocked }
        guard controllerIsAvailable else {
            return .controllerUnavailable
        }
        switch action {
        case .screenContext:
            guard partnerSessionIsActive else {
                return .partnerSessionInactive
            }
            guard screenContentIsReady else {
                return .screenContentUnavailable
            }
        case .voicePreview:
            guard !partnerSessionIsActive else {
                return .partnerSessionActive
            }
        case .identitySave:
            break
        }
        return nil
    }
}

/// Executes the admitted Partner effect and translates only its verified
/// result into terminal UI state. Both variants are injectable so unit tests
/// can prove that success depends on the real mutation or playback closure.
enum PartnerControlActionExecution {
    @MainActor
    static func perform(
        _ action: PartnerControlAction,
        effect: @MainActor () throws -> Bool
    ) -> AceControlActionOutcome {
        do {
            guard try effect() else {
                return failure(for: action)
            }
            return success(for: action)
        } catch {
            return failure(for: action, error: error)
        }
    }

    @MainActor
    static func performAsync(
        _ action: PartnerControlAction,
        effect: @MainActor () async throws -> Bool
    ) async -> AceControlActionOutcome {
        do {
            guard try await effect() else {
                return failure(for: action)
            }
            return success(for: action)
        } catch {
            return failure(for: action, error: error)
        }
    }

    private static func success(
        for action: PartnerControlAction
    ) -> AceControlActionOutcome {
        let message: String
        switch action {
        case .screenContext:
            message = "Screen context is enabled for this session."
        case .identitySave:
            message = "Partner identity and delivery were saved."
        case .voicePreview:
            message = "Voice preview finished."
        }
        return .succeeded(AceActionSuccess(message: message))
    }

    private static func failure(
        for action: PartnerControlAction,
        error: Error? = nil
    ) -> AceControlActionOutcome {
        let code: String
        let baseMessage: String
        let recoveryTitle: String
        switch action {
        case .screenContext:
            code = "partner.screen_context_enable_failed"
            baseMessage =
                "Ace did not enable screen context for this Partner session."
            recoveryTitle = "Try screen context again"
        case .identitySave:
            code = "partner.identity_save_failed"
            baseMessage =
                "Ace could not save the Partner identity change."
            recoveryTitle = "Try saving again"
        case .voicePreview:
            code = "partner.voice_preview_incomplete"
            baseMessage =
                "The voice preview did not finish playing. Your saved voice is unchanged."
            recoveryTitle = "Play the preview again"
        }
        let detail = error?.localizedDescription
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let message = if let detail, !detail.isEmpty {
            "\(baseMessage) \(detail)"
        } else {
            baseMessage
        }
        return .failed(
            AceActionFailure(
                code: code,
                message: message,
                recoveryTitle: recoveryTitle,
                recovery: .retry
            )
        )
    }
}

