/// One Red run has exactly one terminal authority. Keeping the owner typed
/// prevents direct, Gold, and Partner completion paths from publishing the
/// same process result under different or freshly-minted correlations.
private enum BackgroundTaskTerminalOwner {
    case direct(
        workCorrelationIdentifier: UUID,
        sourceTurnIdentifier: UUID?
    )
    case gold(GoldExecutionRequest)

    var workCorrelationIdentifier: UUID {
        switch self {
        case .direct(let identifier, _): return identifier
        case .gold(let request): return request.workCorrelationIdentifier
        }
    }

    var sourceTurnIdentifier: UUID? {
        switch self {
        case .direct(_, let identifier): return identifier
        case .gold(let request): return request.sourceTurnIdentifier
        }
    }

    func recentLane(
        for executionSlot: BackgroundExecutionSlot
    ) -> RecentOwnerWorkLane {
        executionSlot.recentOwnerWorkLane
    }
}

private struct QueuedBackgroundExecution: Identifiable {
    let instruction: String
    let conversationContext: String
    let providerTurn: AceProviderTurn
    let speakResult: Bool
    let terminalOwner: BackgroundTaskTerminalOwner
    var id: UUID { terminalOwner.workCorrelationIdentifier }
}

private extension BackgroundExecutionSlot {
    var eventSource: AceEventSource {
        self == .red ? .red : .silver
    }

    var voiceLane: VoiceQueue.Lane {
        self == .red ? .red : .green
    }

    var recentOwnerWorkLane: RecentOwnerWorkLane {
        self == .red ? .red : .silver
    }

    var durableLane: String { rawValue }

    var directWorkSlot: DeferredDirectWorkSlot {
        self == .red ? .activeRed : .activeSilver
    }

    var spokenAgentName: String {
        self == .red ? "red agent" : "silver agent"
    }
}

// BEGIN DIRECT_EFFECT_ADMISSION_SUPPORT
/// Pure total-order policy for a direct-effect helper process spawn. The
/// injected form is exercised by the offline race harness with no Process,
/// AppleScript, Spotlight, Chrome, Finder, or other app effect.
nonisolated enum DirectEffectProcessLaunchAdmission {
    enum Outcome: Equatable, Sendable {
        case launched
        case blockedByEffectsWall
        case blockedByStealth
        case launchFailed
    }

    static func commit(
        effectsAreAllowed: @escaping () -> Bool,
        performUnlessRaised:
            (_ body: () -> Outcome) -> Outcome?,
        launchAndPublish: @escaping () -> Bool
    ) -> Outcome {
        guard effectsAreAllowed() else {
            return .blockedByEffectsWall
        }
        return performUnlessRaised {
            guard effectsAreAllowed() else {
                return .blockedByEffectsWall
            }
            return launchAndPublish()
                ? .launched
                : .launchFailed
        } ?? .blockedByStealth
    }
}

/// Pure total-order policy for one already-resolved UI/AX/workspace commit.
/// A fresh visibility check runs inside the same latch raised by Private Mode entry.
nonisolated enum DirectEffectCommitAdmission {
    enum Outcome<Value> {
        case committed(Value)
        case blocked
    }

    static func commit<Value>(
        visibilityIsBlocked: @escaping () -> Bool,
        performUnlessRaised:
            (_ body: () -> Outcome<Value>) -> Outcome<Value>?,
        effect: @escaping () -> Value
    ) -> Outcome<Value> {
        guard !visibilityIsBlocked() else { return .blocked }
        return performUnlessRaised {
            guard !visibilityIsBlocked() else { return .blocked }
            return .committed(effect())
        } ?? .blocked
    }
}

/// Pure callback-generation boundary for the delayed welcome prompt. Every
/// callback carries the generation that created it; teardown or Stealth rotates
/// the current generation before cancelling timers/tasks, so even a callback
/// already queued on the main run loop cannot restore stale prompt state.
nonisolated enum OnboardingPromptCallbackAdmission {
    static func isCurrent(
        expectedGeneration: UUID,
        currentGeneration: UUID,
        taskIsCancelled: Bool,
        stealthIsActive: Bool
    ) -> Bool {
        expectedGeneration == currentGeneration
            && !taskIsCancelled
            && !stealthIsActive
    }
}

/// Synchronous event-tap cutoff installed before an async screen-content
/// proof task is admitted. Task cancellation is bounded and local; every
/// awaited result also checks this generation before it may become proof.
nonisolated final class DirectEffectTaskCutoff: @unchecked Sendable {
    private let lock = NSLock()
    private var task: Task<Void, Never>?
    private var cancellationRequested = false

    @discardableResult
    func register(_ task: Task<Void, Never>) -> Bool {
        let shouldCancel = lock.withLock {
            if cancellationRequested {
                return true
            }
            self.task = task
            return false
        }
        if shouldCancel {
            task.cancel()
            return false
        }
        return true
    }

    func cancelSynchronously() {
        let task = lock.withLock {
            cancellationRequested = true
            return self.task
        }
        task?.cancel()
    }

    /// Atomically initiates one callback-form native operation against Private Mode entry. The
    /// callback may finish later, but cancellation/generation checks reject its
    /// result. The body must only register the callback and return.
    func invokeIfCurrent(
        performUnlessRaised:
            (_ body: () -> Bool) -> Bool?,
        _ body: @escaping () -> Void
    ) -> Bool {
        guard !isCancelled else { return false }
        return performUnlessRaised {
            guard !self.isCancelled else { return false }
            body()
            return true
        } == true
    }

    var isCancelled: Bool {
        lock.withLock { cancellationRequested }
    }

    func clear() {
        lock.withLock {
            task = nil
        }
    }
}

/// Drains a helper pipe without retaining unbounded Spotlight output.
nonisolated private final class BoundedDirectProcessOutputBox:
    @unchecked Sendable
{
    private let lock = NSLock()
    private let limit: Int
    private var data = Data()
    private var truncated = false

    init(limit: Int) {
        self.limit = max(0, limit)
    }

    func append(_ source: Data) {
        guard !source.isEmpty else { return }
        lock.withLock {
            let remaining = max(0, limit - data.count)
            if remaining > 0 {
                data.append(source.prefix(remaining))
            }
            if source.count > remaining {
                truncated = true
            }
        }
    }

    func snapshot() -> (data: Data, truncated: Bool) {
        lock.withLock { (data, truncated) }
    }
}
// END DIRECT_EFFECT_ADMISSION_SUPPORT

/// Event-tap-safe root-process cutoff for one product-tour AppleScript.
/// Killing the root is bounded and immediate; ordinary async cleanup follows
/// with the complete process-tree reap.
nonisolated private final class WalkthroughProcessCutoff: @unchecked Sendable {
    private let lock = NSLock()
    private var processIdentifier: pid_t?
    private var cancellationRequested = false

    nonisolated func register(_ process: Process) {
        let processIdentifier = process.processIdentifier
        let shouldTerminate = lock.withLock {
            if cancellationRequested {
                return true
            }
            self.processIdentifier = processIdentifier
            return false
        }
        if shouldTerminate {
            Darwin.kill(processIdentifier, SIGKILL)
        }
    }

    nonisolated func cancelSynchronously() {
        let processIdentifier = lock.withLock {
            cancellationRequested = true
            return self.processIdentifier
        }
        if let processIdentifier {
            Darwin.kill(processIdentifier, SIGKILL)
        }
    }

    nonisolated func clear() {
        lock.withLock {
            processIdentifier = nil
        }
    }

    nonisolated var isCancelled: Bool {
        lock.withLock { cancellationRequested }
    }
}

    /// Event-tap-safe process-tree cutoff for the app-owned Apple Mail lanes.
///
/// The cutoff is installed before a wrapper is launched. Launch and PID
/// publication are then serialized through `StealthEntryLatch`, so Private Mode entry either
/// wins before launch or sees one published root. On entry, every discovered
/// descendant is stopped before it is inspected and the tree is killed
/// leaf-first using `libproc`; no helper process, pipe read, or process wait is
/// started from the event-tap callback.
nonisolated private final class MailToolProcessCutoff: @unchecked Sendable {
    private static let maximumProcessCount = 128

    private let lock = NSLock()
    private var processIdentifier: pid_t?
    private var cancellationRequested = false

    nonisolated func register(_ process: Process) {
        let processIdentifier = process.processIdentifier
        let shouldTerminate = lock.withLock {
            if cancellationRequested {
                return true
            }
            self.processIdentifier = processIdentifier
            return false
        }
        if shouldTerminate {
            Self.freezeAndKillProcessTree(root: processIdentifier)
        }
    }

    nonisolated func cancelSynchronously() {
        let processIdentifier = lock.withLock {
            cancellationRequested = true
            return self.processIdentifier
        }
        if let processIdentifier {
            Self.freezeAndKillProcessTree(root: processIdentifier)
        }
    }

    nonisolated func clear() {
        lock.withLock {
            processIdentifier = nil
        }
    }

    nonisolated var isCancelled: Bool {
        lock.withLock { cancellationRequested }
    }

    /// Bounded tree discovery. Stopping a parent before enumerating its direct
    /// children prevents it from forking past the snapshot. Each child is
    /// stopped immediately, before it is queued for its own child snapshot.
    nonisolated private static func freezeAndKillProcessTree(root: pid_t) {
        guard root > 1 else { return }
        _ = Darwin.kill(root, SIGSTOP)

        var frozenProcessIdentifiers: [pid_t] = [root]
        var inspectionIndex = 0
        while inspectionIndex < frozenProcessIdentifiers.count,
              frozenProcessIdentifiers.count < maximumProcessCount {
            let parent = frozenProcessIdentifiers[inspectionIndex]
            inspectionIndex += 1

            let remainingCapacity =
                maximumProcessCount - frozenProcessIdentifiers.count
            var children = [pid_t](
                repeating: 0,
                count: remainingCapacity
            )
            let discoveredCount = children.withUnsafeMutableBytes { buffer in
                proc_listchildpids(
                    parent,
                    buffer.baseAddress,
                    Int32(buffer.count)
                )
            }
            guard discoveredCount > 0 else { continue }

            let boundedDiscoveredCount = min(
                Int(discoveredCount),
                remainingCapacity
            )
            for child in children.prefix(
                boundedDiscoveredCount
            ) where child > 1 {
                _ = Darwin.kill(child, SIGSTOP)
                frozenProcessIdentifiers.append(child)
            }
        }

        for processIdentifier in frozenProcessIdentifiers.reversed() {
            _ = Darwin.kill(processIdentifier, SIGKILL)
        }
    }
}

@MainActor
final class CompanionManager: ObservableObject {
    nonisolated enum FirstRunRehearsalResult: Equatable {
        case observed
        case timedOut
        case cancelled
    }

    struct FirstRunRehearsalProofProgress: Equatable {
        private(set) var didObserveEventTapKeyboardPress = false
        private(set) var didReceiveFinalTranscript = false
        private(set) var didRecognizeKnownPhrase = false
        private(set) var didObserveEventTapKeyboardRelease = false

        var isComplete: Bool {
            didObserveEventTapKeyboardPress
                && didReceiveFinalTranscript
                && didRecognizeKnownPhrase
                && didObserveEventTapKeyboardRelease
        }

        mutating func recordEventTapKeyboardPress() {
            didObserveEventTapKeyboardPress = true
        }

        mutating func recordFinalTranscript(_ transcript: String) {
            guard didObserveEventTapKeyboardPress else { return }
            didReceiveFinalTranscript = true
            didRecognizeKnownPhrase =
                CompanionManager.rehearsalTranscriptMatchesKnownPhrase(
                    transcript
                )
        }

        mutating func recordEventTapKeyboardRelease() {
            guard didObserveEventTapKeyboardPress else { return }
            didObserveEventTapKeyboardRelease = true
        }
    }

    @Published private(set) var voiceState: CompanionVoiceState = .idle {
        didSet {
            guard voiceState != oldValue else { return }
            refreshInstallReadinessVoiceState()
            observeWaveformState()
            if voiceState == .idle,
               oldValue != .idle,
               oldValue == .responding || currentResponseTask == nil {
                finishWaveformTurn(reason: .completed)
            }
        }
    }

    /// True while the assistant's background worker (the red gem) is off running a
    /// task. Drives the second cursor so you can see it working while you talk to
    /// the gold one. Wired to the real background agent later.
    @Published var backgroundTaskActive = false {
        didSet {
            guard backgroundTaskActive != oldValue else { return }
            refreshInstallReadinessBackgroundWork()
        }
    }

    /// True while the trailing companion gem should render BLUE (meeting
    /// notetaker capturing) instead of RED (background worker). A running
    /// worker task wins: red while it works, back to blue when it finishes and
    /// the meeting is still being captured. Mirrored from the two owners'
    /// published state so every transition — including the notetaker's own
    /// 3-hour safety stop — recolors the gem without a manual call site.
    @Published var companionGemShowsNotesBlue = false
    private var companionGemColorSubscriptions: Set<AnyCancellable> = []

    /// True while the meeting notetaker's on-device recognizer is provably deaf — it
    /// has refused enough times in a row that Siri/Dictation is off or the speech
    /// service is wedged (not merely hearing silence). Drives the amber deafness cue
    /// on the overlay, so a founder pressing the hotkey into silence finally sees
    /// WHY. Set on the rising edge (which also speaks one line) and cleared when
    /// hearing returns. Software-only signal; it never changes a system setting.
    @Published private(set) var sttDeafnessActive = false

    /// The color the trailing context gem should render, with the full precedence
    /// (a running worker wins red, then an active meeting wins blue, then trading
    /// mode shows purple). The overlay switches on this so the three states are
    /// distinguishable — the old blue/red bool could not express purple.
    enum CompanionTrailingGemColor { case red, blue, purple }
    @Published private(set) var companionTrailingGemColor: CompanionTrailingGemColor = .red

    /// Mirrors `tradingLane.isActive` into a value the SwiftUI overlay (which
    /// observes THIS manager) reacts to — drives the purple context gem. Set
    /// alongside every tradingLane.activate()/deactivate(). Resets on relaunch.
    @Published private(set) var tradingModeActive = false
    @Published private(set) var tradingDataStatus:
        TradingDataStatus = .inactive

    var tradingModeStatusLine: String {
        guard tradingModeActive else { return "Trading Mode is off" }
        switch tradingDataStatus {
        case .inactive:
            return "No current capture-bound chart read — no chart has been captured for this turn yet"
        case let .unavailable(reason):
            return "No current capture-bound chart read — \(reason)"
        case let .available(evidence):
            let formatter = ISO8601DateFormatter()
            return "\(evidence.symbol) \(evidence.timeframe) • \(evidence.source) • \(formatter.string(from: evidence.capturedAt))"
        }
    }

    var tradingModeBadgeDetail: String {
        guard tradingModeActive else { return "" }
        switch tradingDataStatus {
        case .inactive:
            return ""
        case .unavailable:
            return "NO CURRENT CHART READ"
        case let .available(evidence):
            return "\(evidence.symbol) \(evidence.timeframe)"
        }
    }

    /// Mirrors `stealthMode.isActive`. True while ghost mode hides every visible
    /// surface (gem, cursor, menu-bar icon) and Nora is suppressed. The overlay
    /// and the menu-bar manager observe this to disappear.
    @Published private(set) var stealthActive = false

    /// Whether the overlay was visible before stealth, so exit can restore it.
    private var shouldRestoreOverlayAfterStealth = false
    private var shouldResumeAutomationRevalidationAfterStealth = false
    private var shouldResumeScreenContentProofAfterStealth = false
    /// A process relaunched while the owner's durable Stealth intent is still
    /// present starts only the silent exit control. Explicit exit relaunches
    /// the full runtime from a clean process instead of trying to resume
    /// services that were intentionally never started.
    private var restoredDurableStealthAtLaunch = false
    private var normalRuntimeStartupHasBegun = false
    private var stealthHotkeyWasDegraded = false
    private var stealthEntryTransitionInProgress = false {
        didSet { refreshInstallReadinessPrivateModeTransition() }
    }
    private var stealthExitTransitionInProgress = false {
