    /// Screen location (global AppKit coords) of a detected UI element the
    /// buddy should fly to and point at. Parsed from Claude's response;
    /// observed by BlueCursorView to trigger the flight animation.
    @Published var detectedElementScreenLocation: CGPoint? {
        didSet {
            if !isRefreshingPanelInkTarget { stopTrackingPanelInkTarget() }
            detectedElementIsVerified = false
            detectedElementVerifiedTurnID = nil
            // Every publisher, including point-only screen answers, retires any
            // previous control bounds. An equal point is still a new request.
            detectedElementScreenBounds = nil
            detectedElementVisualRevision &+= 1
        }
    }
    /// The display frame (global AppKit coords) of the screen the detected
    /// element is on, so BlueCursorView knows which screen overlay should animate.
    @Published var detectedElementDisplayFrame: CGRect?
    @Published private(set) var detectedElementScreenBounds: CGRect?
    @Published private(set) var detectedElementIsVerified = false
    private(set) var detectedElementVerifiedTurnID: UUID?
    private var detectedElementVisualRevision: UInt64 = 0
    var detectedElementVisualTarget: AceInkTarget? {
        guard let point = detectedElementScreenLocation,
              let displayFrame = detectedElementDisplayFrame else { return nil }
        if detectedElementIsVerified,
           detectedElementVerifiedTurnID != AceEventBus.shared.currentTurnID { return nil }
        return AceInkTarget(revision: detectedElementVisualRevision, point: point,
            displayFrame: displayFrame, verifiedBounds: detectedElementScreenBounds,
            permitsPointing: detectedElementIsVerified)
    }
    private func markDetectedElementAsVerified() {
        guard detectedElementScreenLocation != nil,
              let turnID = AceEventBus.shared.currentTurnID else { return }
        stopScanTheater()
        detectedElementVerifiedTurnID = turnID
        detectedElementIsVerified = true
    }
    private var panelInkTrackingTimer: Timer?
    private var panelInkTrackingGeneration = UUID()
    private var panelInkTrackingTarget: AcePanelVisualTarget?
    private var panelInkTrackingRevision: UInt64?
    private var panelInkTrackingDeadline: TimeInterval = 0
    private var isRefreshingPanelInkTarget = false
    private var panelVisualTargetViews:
        [AcePanelVisualTarget: WeakAcePanelVisualTargetView] = [:]
    /// Custom speech bubble text for the pointing animation. When set,
    /// BlueCursorView uses this instead of a random pointer phrase.
    @Published var detectedElementBubbleText: String?

    /// SwiftUI controls register a non-interactive backing NSView. The weak
    /// reference lets a point request convert the control's CURRENT bounds to
    /// screen coordinates at execution time, including after panel scrolling.
    func registerPanelVisualTarget(
        _ target: AcePanelVisualTarget,
        view: NSView
    ) {
        panelVisualTargetViews[target] =
            WeakAcePanelVisualTargetView(view)
    }

    /// Receipt and speech updates can move a control after the initial point
    /// readback. Track only that request's live view, for a bounded lifetime.
    private func trackPanelInkTarget(_ target: AcePanelVisualTarget) {
        stopTrackingPanelInkTarget()
        guard detectedElementScreenBounds != nil, !stealthActive else { return }
        panelInkTrackingTarget = target
        panelInkTrackingRevision = detectedElementVisualRevision
        panelInkTrackingDeadline = ProcessInfo.processInfo.systemUptime + 8
        let generation = panelInkTrackingGeneration
        let timer = Timer(timeInterval: 1.0 / 30.0, repeats: true) { [weak self] timer in
            let shouldInvalidate = MainActor.assumeIsolated {
                guard let self,
                      self.panelInkTrackingGeneration == generation else { return true }
                self.refreshPanelInkTarget()
                return false
            }
            if shouldInvalidate {
                timer.invalidate()
            }
        }
        panelInkTrackingTimer = timer
        RunLoop.main.add(timer, forMode: .common)
    }

    private func stopTrackingPanelInkTarget() {
        panelInkTrackingGeneration = UUID()
        panelInkTrackingTimer?.invalidate()
        panelInkTrackingTimer = nil
        panelInkTrackingTarget = nil
        panelInkTrackingRevision = nil
    }

    private func refreshPanelInkTarget() {
        guard let target = panelInkTrackingTarget,
              panelInkTrackingRevision == detectedElementVisualRevision else {
            stopTrackingPanelInkTarget()
            return
        }
        guard !stealthActive,
              ProcessInfo.processInfo.systemUptime < panelInkTrackingDeadline,
              let frame = livePanelVisualTargetFrame(for: target),
              let screen = NSScreen.screens.first(where: {
                  $0.frame.contains(CGPoint(x: frame.midX, y: frame.midY))
              }) else {
            clearDetectedElementLocation()
            return
        }
        guard frame != detectedElementScreenBounds
                || screen.frame != detectedElementDisplayFrame else { return }
        isRefreshingPanelInkTarget = true
        detectedElementDisplayFrame = screen.frame
        detectedElementScreenLocation = CGPoint(x: frame.midX, y: frame.midY)
        detectedElementScreenBounds = frame
        markDetectedElementAsVerified()
        panelInkTrackingRevision = detectedElementVisualRevision
        isRefreshingPanelInkTarget = false
    }

    private func livePanelVisualTargetFrame(
        for target: AcePanelVisualTarget
    ) -> CGRect? {
        guard let view = panelVisualTargetViews[target]?.view,
              let window = view.window,
              window.isVisible,
              !view.isHiddenOrHasHiddenAncestor,
              view.alphaValue > 0,
              view.bounds.width > 2,
              view.bounds.height > 2,
              view.visibleRect.insetBy(dx: -0.5, dy: -0.5).contains(view.bounds) else {
            return nil
        }
        let frameInWindow = view.convert(view.bounds, to: nil)
        let screenFrame = window.convertToScreen(frameInWindow)
        guard screenFrame.minX.isFinite,
              screenFrame.minY.isFinite,
              screenFrame.width.isFinite,
              screenFrame.height.isFinite,
              NSScreen.screens.contains(where: {
                  $0.frame.intersects(screenFrame)
              }) else {
            return nil
        }
        return screenFrame
    }

