    private let audioSessionCoordinator = AudioSessionCoordinator()
    private(set) lazy var buddyDictationManager: BuddyDictationManager = {
        let manager = BuddyDictationManager()
        manager.audioSessionCoordinator = audioSessionCoordinator
        manager.onDictationFailure = { [weak self] ownerTurnID, message in
            guard let self,
                  AceEventBus.shared.currentTurnID == ownerTurnID,
                  !AceEventBus.shared.isTurnCancelled(ownerTurnID),
                  self.directEffectsAreAllowed else { return }
            self.appendRouteReceipt("DICTATION failure surfaced turn=\(ownerTurnID.uuidString)")
            self.dictationFailureMessage = message
            MenuBarPanelManager.shared?.showPanelForVoiceInputFailure()
        }
        manager.onAudioSessionRefusal = { [weak self] reason in
            guard let self else { return }
            self.appendRouteReceipt(
                "AUDIO capture refused — \(reason)"
            )
            self.showVisibleResponse(reason)
            // The manager knows EXACTLY which grant is blocking — it sets
            // currentPermissionProblem on every denial — and it owns
            // openRelevantPrivacySettings(), which jumps straight to that
            // pane. Neither ever left the class: currentPermissionProblem had
            // no reader outside BuddyDictationManager and the opener had zero
            // callers tree-wide. So a buyer whose microphone or speech grant
            // was denied got a sentence describing the problem and no way to
            // act on it. The owner has just pressed the chord, so this is a
            // user-initiated moment, not a surprise dialog.
            guard self.buddyDictationManager.currentPermissionProblem != nil
            else { return }
            self.appendRouteReceipt(
                "AUDIO opening the exact privacy pane for the denied grant")
            self.buddyDictationManager.openRelevantPrivacySettings()
        }
        return manager
    }()
