    func prepareVisibleSyllabusForCalendar() async {
        guard partnerModeController?
                .screenContextEnabledForSession == true else {
            syllabusCalendarWorkflow.reportSelectionFailure(
                "Enable screen context for this Partner session, place the syllabus in front, then explicitly select it again."
            )
            return
        }
        do {
            let captures = try await CompanionScreenCaptureUtility
                .captureAllScreensAsJPEG(onlyCursorScreen: true)
            guard let capture = captures.first else {
                syllabusCalendarWorkflow.reportSelectionFailure(
                    "No explicitly selected visible syllabus image was captured."
                )
                return
            }
            await syllabusCalendarWorkflow.prepareVisibleSyllabusImage(
                capture.imageData,
                sourceLabel: "Visible syllabus on \(capture.label)"
            )
        } catch {
            syllabusCalendarWorkflow.reportSelectionFailure(
                "Visible syllabus capture failed: \(error.localizedDescription)"
            )
        }
    }

    @discardableResult
    func submitPartnerComposer(_ typedText: String) -> Bool {
        let typed = typedText.trimmingCharacters(
            in: .whitespacesAndNewlines
        )
        let attachmentContext =
            PartnerComposerAttachmentStore.boundedContext(
                for: partnerComposerAttachments
            )
        guard !typed.isEmpty || !attachmentContext.isEmpty else {
            return false
        }
        let request = [typed, attachmentContext]
            .filter { !$0.isEmpty }
            .joined(separator: "\n\n")
        guard request.count <= 8_000 else {
            showVisibleResponse(
                "This message and its attachment context exceed 8,000 characters. Shorten the message or remove an attachment, then send again. Your draft and selected attachments are still here."
            )
            return false
        }
        if !partnerModeIsActive {
            // The composer already contains the owner's first Partner turn.
            // Speaking the ordinary activation greeting here creates a second
            // mouth job before that turn is routed; the greeting completion can
            // then reopen the microphone over the real response. Open the
            // session silently and let the admitted request own the first
            // response/listening transition.
            activatePartnerMode(speakAcknowledgement: false)
        }
        guard partnerModeIsActive else {
            showVisibleResponse(
                "Partner could not open, so the typed request was not admitted."
            )
            return false
        }
        preparePartnerComposerTurnForRouting()
        let admitted = ingestOwnerUtterance(
            request,
            origin: .directHumanUIAction
        )
        guard admitted else {
            showVisibleResponse(
                "Partner did not admit that request. The draft attachments remain selected so you can retry."
            )
            return false
        }
        partnerComposerAttachments =
            PartnerComposerAttachmentStore.clear(
                partnerComposerAttachments
            )
        return true
    }

    /// A typed Partner turn and an open-microphone Partner turn share the same
    /// admission pipeline, but they cannot own the microphone simultaneously.
    /// Relinquish any silent listening window before sealing the typed turn so
    /// Ace's response is never captured as the owner's next request.
    private func preparePartnerComposerTurnForRouting() {
        // A typed request interrupts queued speech just like a keyboard hold.
        // Retire its completion before the new native/provider turn is admitted.
        partnerResponseGeneration = UUID()
        currentResponseTask?.cancel()
        noraVoice.stopPlayback()
        partnerModeController?.speechWasInterrupted()
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        if !isOnDeviceDictationReady || !hasMicrophonePermission {
            partnerModeController?.mute()
        }
        if partnerModeController?.phase == .listening {
            partnerModeController?.finishSilentListeningWindow()
        } else if partnerModeController?.phase == .error {
            partnerModeController?.resumeAfterMicrophoneHandoff()
        }
        voiceState = .idle
        partnerConsecutiveSilentWindows = 0
        partnerDeafnessSurfacedForThisRun = false
        appendRouteReceipt(
            "PARTNER composer released microphone for admitted turn"
        )
    }

    private struct GoldContextRuntimeState {
        var bundle: AceGoldContextBundle
        var pendingRelaunchRecovery: AceGoldContextBundle?

        static func pendingAceHQWorkIdentifiers() -> Set<UUID> {
            guard let recovered = AceHQPendingDispatchStore.load(
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            ) else {
                return []
            }
            let exactRunningCorrelationID = recovered
                .reconciliationAttempt?.work.correlationID
                ?? recovered.pending.envelope.work.correlationID
            guard let workIdentifier = UUID(
                uuidString: exactRunningCorrelationID
            ) else { return [] }
            return [workIdentifier]
        }

        static func bootstrap() -> GoldContextRuntimeState {
            let pendingHQWorkIdentifiers =
                pendingAceHQWorkIdentifiers()
            let loaded = AceConversationHistory.loadBundleForRelaunch(
                preservingRunningWorkCorrelationIdentifiers:
                    pendingHQWorkIdentifiers,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
            return GoldContextRuntimeState(
                bundle: loaded.bundle,
                pendingRelaunchRecovery: loaded.pendingRecovery
            )
        }
    }

    /// One local, correlated Gold bundle: ten recent exchanges, deterministic
    /// compacted owner history, and durable work lineage. It is refreshed from
    /// the atomic file for every admitted Gold turn and purged from RAM at the
    /// Stealth boundary. Legacy history.json is migrated without invented IDs.
    private var goldContextState = GoldContextRuntimeState.bootstrap()
    private var goldContextBundle: AceGoldContextBundle {
        get { goldContextState.bundle }
        set { goldContextState.bundle = newValue }
    }

    private var conversationHistory: [AceConversationExchange] {
        goldContextBundle.recentExchanges
    }

    /// Startup interruption recovery is retried before admitting owner work.
    /// It is never recomputed during this process, so a normal later turn cannot
    /// misclassify live Red/Partner/Gold work as a relaunch interruption.
    private func commitPendingRelaunchRecoveryIfNeeded() -> Bool {
        guard let pending =
                goldContextState.pendingRelaunchRecovery else {
            return true
        }
        let persisted = AceConversationHistory.saveBundle(
            pending,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        if persisted {
            goldContextState.bundle = pending
            goldContextState.pendingRelaunchRecovery = nil
        }
        appendRouteReceipt(
            "GOLD-CONTEXT relaunch recovery persisted="
                + (persisted ? "true" : "false")
        )
        return persisted
    }

