    private var recentEmailRead: RecentEmailRead? {
        didSet {
            recentEmailReadExpiryTask?.cancel()
            recentEmailReadExpiryTask = nil
            guard let receivedAt = recentEmailRead?.receivedAt else { return }
            let seconds = max(0, 300 - Date().timeIntervalSince(receivedAt))
            recentEmailReadExpiryTask = Task { [weak self] in
                do { try await Task.sleep(for: .seconds(seconds)) } catch { return }
                guard self?.recentEmailRead?.receivedAt == receivedAt else { return }
                self?.recentEmailRead = nil
            }
        }
    }

