    /// The one setup gate: Ace's local capture/input loop is ready. Per-app
    /// Automation grants remain visible and retryable, but a single target
    /// (Mail included) can disable only that target's automation—not Ace.
    var allPermissionsGranted: Bool {
        coreInteractionPermissionsGranted
    }

    /// The five permissions required for the always-available local
    /// interaction loop. Optional bundled-app Automation proof must not make a
    /// returning owner's panel claim that these permissions were revoked.
    var coreInteractionPermissionsGranted: Bool {
        FirstRunRecoveryPolicy.requiredInteractionPermissionsAreReady(
            accessibility: hasAccessibilityPermission,
            screenRecording: hasScreenRecordingPermission,
            microphone: hasMicrophonePermission,
            screenContent: hasScreenContentPermission,
            onDeviceSpeech: isOnDeviceDictationReady
        )
    }

    var panelPermissionsReady: Bool {
        AssistantAvailabilityPolicy.panelPermissionsAreReady(
            hasCompletedOnboarding: hasCompletedOnboarding,
            coreInteractionPermissionsReady:
                coreInteractionPermissionsGranted,
            appAutomationReady:
                permissionWarmup.hasProvenAppAutomation
        )
    }

    /// Setup and panel code must use this complete predicate instead of
    /// `SFSpeechRecognizer.isAvailable`, which omits both consent and the
    /// local-only capability enforced by the live provider.
    var isOnDeviceDictationReady: Bool {
        appleSpeechRecognitionReadiness.isReady
    }

    var hasSpeechRecognitionPermission: Bool {
        appleSpeechRecognitionReadiness.hasSpeechRecognitionAuthorization
    }

    nonisolated static func shouldPersistFirstRunCompletion(
        isRunningFromCanonicalInstall: Bool,
        requiredProofsReady: Bool,
        eventTapOperational: Bool,
        productionScreenAnswerExerciseSucceeded: Bool,
        rehearsalResult: FirstRunRehearsalResult
    ) -> Bool {
        // A timed-out or cancelled rehearsal must never persist a ready
        // state (DOD-2.4): completion requires the event-tap-observed
        // press → known transcript → release transition. The durable
        // pending-proof bit plus the relaunch resume tour is the recovery
        // path, so refusing here cannot strand an unproven install.
        let observedInteraction = rehearsalResult == .observed
        let evidence = AceFirstRunEvidence(
            providerAnsweredLive: requiredProofsReady,
            corePermissionsReady: requiredProofsReady,
            liveScreenAnswerSucceeded:
                productionScreenAnswerExerciseSucceeded,
            shortcutPressObserved: observedInteraction,
            transcriptObserved: observedInteraction,
            shortcutReleaseObserved: observedInteraction
        )
        return isRunningFromCanonicalInstall
            && eventTapOperational
            && AssistantAvailabilityPolicy.mayPersistFirstRunCompletion(
                phase: FirstRunFlowPolicy.phase(for: evidence)
            )
    }

    nonisolated static func shouldBeginNoninteractiveAutomationRevalidation(
        hasCompletedOnboarding: Bool,
        hasPendingOnboardingProof: Bool,
        isRunningFromCanonicalInstall: Bool
    ) -> Bool {
        isRunningFromCanonicalInstall
            && (hasCompletedOnboarding || hasPendingOnboardingProof)
    }

    nonisolated static func screenContentRelaunchStepIsSatisfied(
        screenRecordingWasAuthorizedAtProcessLaunch: Bool,
        hasProcessScopedScreenContentProof: Bool
    ) -> Bool {
        screenRecordingWasAuthorizedAtProcessLaunch
            || hasProcessScopedScreenContentProof
    }

    nonisolated static func shouldBeginProcessScopedScreenContentProof(
        hasCompletedOnboarding: Bool,
        hasPendingOnboardingProof: Bool,
        hasPendingScreenContentProof: Bool,
        isRunningFromCanonicalInstall: Bool,
        hasScreenRecordingPermission: Bool
    ) -> Bool {
        isRunningFromCanonicalInstall
            && hasScreenRecordingPermission
            && (hasCompletedOnboarding
                || hasPendingOnboardingProof
                || hasPendingScreenContentProof)
    }

    nonisolated static var firstRunRehearsalPhrase: String {
        "ready when you are"
    }

    nonisolated static func rehearsalTranscriptMatchesKnownPhrase(
        _ transcript: String
    ) -> Bool {
        normalizedRehearsalTranscript(transcript)
            == normalizedRehearsalTranscript(firstRunRehearsalPhrase)
    }

    nonisolated static func pendingOnboardingProofRetryDelay(
        afterAttempt attempt: Int
    ) -> Duration {
        attempt < 30 ? .seconds(1) : .seconds(5)
    }

    private nonisolated static func normalizedRehearsalTranscript(
        _ transcript: String
    ) -> String {
        transcript
            .lowercased()
            .unicodeScalars
            .map { scalar in
                CharacterSet.alphanumerics.contains(scalar)
                    ? String(scalar)
                    : " "
            }
            .joined()
            .split(whereSeparator: \.isWhitespace)
            .joined(separator: " ")
    }

    /// The app owns the read shape; the model never gets to turn an inbox read
    /// into another tool invocation. The bundled script clamps again at 20.
    static func emailReadArguments(for utterance: String) -> [String] {
        CrossAppActionPolicy.emailReadArguments(for: utterance)
    }

    /// Whether the blue cursor overlay is currently visible on screen.
    /// Used by the panel to show accurate status text ("Active" vs "Ready").
    @Published private(set) var isOverlayVisible: Bool = false {
        didSet {
            guard isOverlayVisible != oldValue else { return }
            observeWaveformState()
        }
    }

    /// The Claude model used for voice responses. Persisted to UserDefaults.
    /// Always one of the closed enum's stored identifiers: reads and writes
    /// coerce through AceClaudeModel, so an invalid persisted value can only
    /// ever mean Sonnet — in the UI and in argv alike.
    @Published var selectedModel: String = AceClaudeModel(
        storedModelID: UserDefaults.standard.string(
            forKey: AceClaudeModel.storedSelectionDefaultsKey
        )
    ).storedModelID

    func setSelectedModel(_ model: String) {
        let selection = AceClaudeModel(storedModelID: model)
        selectedModel = selection.storedModelID
        UserDefaults.standard.set(
            selection.storedModelID,
            forKey: AceClaudeModel.storedSelectionDefaultsKey
        )
        claudeAPI.model = selection.storedModelID
    }

    /// User preference for whether the BlackLabel cursor should be shown.
    /// When toggled off, the overlay is hidden and push-to-talk is disabled.
    /// Persisted to UserDefaults so the choice survives app restarts.
    @Published var isBlackLabelCursorEnabled: Bool = UserDefaults.standard.object(forKey: "isBlackLabelCursorEnabled") == nil
        ? true
        : UserDefaults.standard.bool(forKey: "isBlackLabelCursorEnabled")

    func setBlackLabelCursorEnabled(_ enabled: Bool) {
        isBlackLabelCursorEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "isBlackLabelCursorEnabled")
        transientHideTask?.cancel()
        transientHideTask = nil

        if enabled {
            overlayWindowManager.hasShownOverlayBefore = true
            isOverlayVisible = overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            )
        } else {
            overlayWindowManager.hideOverlay()
            isOverlayVisible = false
        }
    }

    /// Whether the user has completed onboarding at least once. Persisted
    /// to UserDefaults so the Start button only appears on first launch.
    var hasCompletedOnboarding: Bool {
        get { UserDefaults.standard.bool(forKey: "hasCompletedOnboarding") }
        set { UserDefaults.standard.set(newValue, forKey: "hasCompletedOnboarding") }
    }

    var hasViewedFirstRunTour: Bool {
        FirstRunExperienceState.shared.hasViewedFirstRunTour
    }

    /// Whether the user has submitted their email during onboarding.
    // Black Label Assistant has no email capture, so the onboarding email gate
    // is always considered satisfied — the app goes straight to the assistant.
    @Published var hasSubmittedEmail: Bool = true

    /// Retired compatibility hook. It stores only the local completion bit and
    /// never sends the supplied address anywhere.
    func submitEmail(_ email: String) {
        let trimmedEmail = email.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedEmail.isEmpty else { return }

        // Black Label Assistant collects no email and contacts no external
        // service. The captured value is only remembered locally so the
        // onboarding prompt does not reappear.
        hasSubmittedEmail = true
        UserDefaults.standard.set(true, forKey: "hasSubmittedEmail")
    }

    func start(restoringDurableStealth: Bool = false) {
        for retiredKey in [
            "privateModeRestrictsToAllowedApplications",
            "privateModeAllowedBundleIdentifiers",
            "PrivateModeSecurityDefaultsVersion",
        ] {
            UserDefaults.standard.removeObject(forKey: retiredKey)
        }
        if restoringDurableStealth {
            startRecoveredStealthRuntime()
            return
        }
        bindEntitlementAdmissionIfNeeded()
        openPremiumRuntimeIfEntitled()
    }

    private func startPremiumRuntime() {
        refreshBuyerWorkReceiptsFromDurableContext()
        noraVoice.onDeliveryFailure = { [weak self] spokenText in
            guard let self else { return }
            if var transaction = self.responseDeliveryTransaction,
               transaction.responseText == spokenText,
               transaction.advance(
                    .failed(reason: "Speech failed to start or complete."),
                    for: transaction.id
               ) {
                self.responseDeliveryTransaction = transaction
            }
            self.showVisibleResponse(
                spokenText
                    + "\n\nSpeech failed to start or complete. The text answer remains available."
            )
        }
        noraVoice.onDeliveryStarted = { [weak self] spokenText in
            guard let self,
                  var transaction = self.responseDeliveryTransaction,
                  transaction.responseText == spokenText,
                  transaction.advance(
                    .speechStarted,
                    for: transaction.id
                  ) else {
                return
            }
            self.responseDeliveryTransaction = transaction
            self.voiceState = .responding
        }
        noraVoice.prepareMicrophoneForSpeech = { [weak self] in
            guard let self else { return false }
            return await self.preparePartnerMicrophoneForQueuedSpeech()
        }
        noraVoice.onPlaybackActivityChanged = { [weak self] isActive in
            InstallReadinessCoordinator.shared.set(
                .voicePlayback,
                active: isActive
            )
            guard !isActive else { return }
            // Queue callbacks may run under its admission lock. Reopen only
            // after that boundary returns, and after the exact queue drains.
            Task { @MainActor [weak self] in
                guard let self, !self.noraVoice.isPlaying else { return }
                self.resumePartnerListeningAfterNativeLaneIfAllowed()
            }
        }
        // Bind the Private Mode entry sink before any path can install the event tap.
        // A PassthroughSubject has no replay: installing first left a clean-Mac
        // launch window where the tap raised the hard wall but its immutable
        // enter/exit event had no MainActor consumer.
        bindPrivateModeTriggers()
        guard normalRuntimeAdmissionRemainsOpen else {
            startRecoveredStealthRuntime()
            return
        }
        normalRuntimeStartupHasBegun = true
        preparePartnerModeController()
        bindInstallReadinessState()
        refreshAllPermissions()
        // `refreshAllPermissions()` is the first point that installs the Private Mode
        // event tap. Recheck immediately: an entry chord may have raised the latch
        // on that tap thread while this synchronous launch turn was still
        // running, and another Ace instance may have published durable intent
        // after the AppDelegate's initial absence snapshot.
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        // Migration only: a historical boolean is not screen evidence. The
        // current process earns this proof from a fresh SCK image or remains
        // unproven.
        guard performNormalStartupCommit({
            UserDefaults.standard.removeObject(
                forKey: "hasScreenContentPermission"
            )
            permissionWarmupCancellable = permissionWarmup.objectWillChange
                .receive(on: DispatchQueue.main.circuitScheduler)
                .sink { [weak self] _ in self?.objectWillChange.send() }
        }) else {
            return
        }
        let hasPendingOnboardingProof = UserDefaults.standard.bool(
            forKey: Self.pendingOnboardingHotkeyProofKey
        )
        let hasPendingScreenContentProof = UserDefaults.standard.bool(
            forKey: Self.pendingScreenContentProofKey
        )
        if Self.shouldBeginNoninteractiveAutomationRevalidation(
            hasCompletedOnboarding: hasCompletedOnboarding,
            hasPendingOnboardingProof: hasPendingOnboardingProof,
            isRunningFromCanonicalInstall:
                InstallLocation.isRunningFromAllowedStableLocation
        ) {
            // Completed owners start with an intentionally empty Automation
            // verdict. A first run pending its post-relaunch rehearsal has the
            // same need: the previous process's proof is deliberately not
            // trusted. Revalidate current TCC state without prompts before
            // either flow can continue.
            // Revalidation installs its own synchronous Private Mode cutoff before it
            // launches a hidden target application. Do not call it while
            // performNormalStartupCommit holds StealthEntryLatch's
            // nonrecursive lock: the cutoff registration would recursively
            // acquire that lock and deadlock launch before the menu-bar item
            // is created.
            guard normalRuntimeAdmissionRemainsOpen else {
                _ = enforceStealthForLaunchRaceIfNeeded()
                return
            }
            permissionWarmup.beginNoninteractiveRevalidation()
            guard enforceStealthForLaunchRaceIfNeeded() else {
                return
            }
        }
        if Self.shouldBeginProcessScopedScreenContentProof(
            hasCompletedOnboarding: hasCompletedOnboarding,
            hasPendingOnboardingProof: hasPendingOnboardingProof,
            hasPendingScreenContentProof:
                hasPendingScreenContentProof,
            isRunningFromCanonicalInstall:
                InstallLocation.isRunningFromAllowedStableLocation,
            hasScreenRecordingPermission:
                hasScreenRecordingPermission
        ) {
            guard normalRuntimeAdmissionRemainsOpen else {
                _ = enforceStealthForLaunchRaceIfNeeded()
                return
            }
            // The request owns its generation cutoff and latch admission.
            // Calling it from performNormalStartupCommit would recursively
            // take StealthEntryLatch's nonrecursive lock.
            requestScreenContentPermission()
            guard enforceStealthForLaunchRaceIfNeeded() else {
                return
            }
        }
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        print("🔑 BlackLabel start — accessibility: \(hasAccessibilityPermission), screen: \(hasScreenRecordingPermission), mic: \(hasMicrophonePermission), speech: \(appleSpeechRecognitionReadiness), screenContent: \(hasScreenContentPermission), onboarded: \(hasCompletedOnboarding)")
        guard performNormalStartupCommit({
            startPermissionPolling()
        }) else {
            return
        }
        // Some observation roots (VoiceReadiness in particular) register their
        // own synchronous Private Mode cutoff during first construction. Bracket that
        // race-safe registration with fresh checks instead of recursively taking
        // the non-recursive entry-latch commit lock.
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        bindVoiceStateObservation()
        bindAudioPowerLevel()
        bindPlatformHostVoiceWarmup()
        bindShortcutTransitions()
        observeScreenParameterChanges()
        bindCompanionGemColorState()
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        // Self-diagnose the hotkey: a revoked Accessibility grant kills the
        // event tap silently. Check shortly after start, leave a receipt, and
        // SAY it — "the hotkey doesn't work" must never be a mystery.
        guard performNormalStartupCommit({
            DispatchQueue.main.asyncAfter(deadline: .now() + 3.0) {
                [weak self] in
                guard let self else { return }
                guard self.enforceStealthForLaunchRaceIfNeeded() else {
                    return
                }
                if self.globalPushToTalkShortcutMonitor.didInstallEventTap {
                    LifecycleLog.append("HOTKEY event tap installed")
                } else {
                    LifecycleLog.append("HOTKEY event tap NOT installed — accessibility permission likely revoked")
                    // Say nothing during first-run setup. On a clean install
                    // Accessibility is ALWAYS ungranted at this moment, so this line
                    // fired three seconds after launch and talked straight over the
                    // welcome narration — Ace's first words to a new owner were a
                    // complaint about a permission the very next screen asks for.
                    guard self.hasCompletedOnboarding else { return }
                    Task {
                        try? await self.noraVoice.speakText(
                            "heads up — i can't hear the push to talk keys right now. macos dropped my accessibility permission. open system settings, privacy and security, accessibility, then toggle ace off and back on.",
                            priority: .background)
                    }
                }
            }
        }) else {
            return
        }
        // Nora and the meeting boundary register synchronous Private Mode cutoffs in their
        // initializers, so they must not be constructed while the latch's commit
        // lock is held. Fresh checks bracket construction; a concurrent entry request is
        // observed by each race-safe cutoff registration and by the second check.
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        _ = claudeAPI
        _ = noraVoice
        meetingNotetaker.speak = { [weak self] text in
            try? await self?.noraVoice.speakText(text, from: .blue)
        }
        meetingNotetaker.onDeafnessDetected = { [weak self] in
            self?.surfaceSttDeafness()
        }
        meetingNotetaker.onHearingRecovered = { [weak self] in
            self?.clearSttDeafness()
        }
        meetingNotesResultCancellable = meetingNotetaker.$result
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] result in
                self?.latestMeetingNotesResult = result
            }
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        guard performNormalStartupCommit({
            meetingNotetaker.startMeetingAppWatcher()
        }) else {
            return
        }

        // Event-bus lane subscriptions. Each lane is an ISOLATED consumer as
        // well as an isolated producer: a lane that subscribes to "everything"
        // is how a Partner aside ends up in the owner's meeting notes, so the
        // subscription itself is typed and `AceEventSubscription.accepts`
        // decides delivery rather than each lane filtering by hand.
        //
        // Notes receives Ace speech and lane receipts, never Partner advice.
        // Partner receives its own advice and Ace's speech, never Red or Silver
        // internals. Neither can see an inbound event at all.
        AceEventBus.shared.subscribe(
            AceEventSubscriber(
                name: "notes-lane",
                subscription: .notesLane
            ) { [weak self] labeledEvent in
                self?.appendRouteReceipt(
                    "NOTES-SUB accepted src=\(labeledEvent.source.rawValue) "
                        + "type=\(labeledEvent.payloadType.rawValue) "
                        + "state=\(labeledEvent.state.rawValue)"
                )
            }
        )
        AceEventBus.shared.subscribe(
            AceEventSubscriber(
                name: "partner-lane",
                subscription: .partnerLane
            ) { [weak self] labeledEvent in
                self?.appendRouteReceipt(
                    "PARTNER-SUB accepted src=\(labeledEvent.source.rawValue) "
                        + "type=\(labeledEvent.payloadType.rawValue) "
                        + "state=\(labeledEvent.state.rawValue)"
                )
            }
        )

        // Lane bridge (utah port): subsystems report their live state into
        // LaneManager; the mirror below is what the overlay cluster renders.
        backgroundAgent.$isWorking
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] workerIsWorking in
                self?.laneManager.setLane(.red, active: workerIsWorking)
            }
            .store(in: &laneMirrorCancellables)
        meetingNotetaker.$isTakingNotes
            .combineLatest(meetingNotetaker.$isStartingUp)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] notesAreLive, notesAreStarting in
                self?.laneManager.setLane(
                    .blue,
                    active: MeetingLaneVisualState.isActive(
                        isTakingNotes: notesAreLive,
                        isStartingUp: notesAreStarting
                    )
                )
                if !notesAreLive, !notesAreStarting {
                    self?.deliverDeferredBuyerWorkReceiptSpeech()
                    self?.morningLinkBriefRuntime
                        .deliverDeferredSpeechIfPossible()
                }
            }
            .store(in: &laneMirrorCancellables)
        $tradingModeActive
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] tradingIsOn in
                self?.laneManager.setLane(.purple, active: tradingIsOn)
            }
            .store(in: &laneMirrorCancellables)
        // Silver is one exclusive execution slot. It lights for either a
        // workflow planning/build window or the second simultaneous background
        // check, never both. The persisted lane identifier remains green.
        workflowRuntime.$isBuilding
            .combineLatest(
                workflowRuntime.$isPlanning,
                silverBackgroundAgent.$isWorking
            )
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self]
                buildIsRunning,
                buildPlanningIsRunning,
                silverCheckIsRunning in
                self?.laneManager.setLane(
                    .green,
                    active: buildIsRunning
                        || buildPlanningIsRunning
                        || silverCheckIsRunning
                )
            }
            .store(in: &laneMirrorCancellables)
        workflowRuntime.$lastArtifactReceipt
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] receipt in
                guard let self else { return }
                self.latestWorkflowArtifactReceipt = receipt
                self.resolveDirectWorkflowReceiptIfNeeded(receipt)
                self.resolveGoldWorkflowReceiptIfNeeded(receipt)
            }
            .store(in: &laneMirrorCancellables)
        laneManager.$activeLanes
            .combineLatest(laneManager.$stealthActive)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] _, _ in
                guard let self else { return }
                self.litTrailingLanes = self.laneManager.litBackgroundLanes
            }
            .store(in: &laneMirrorCancellables)
        resumeDurableAceHQDispatchAtNormalStartup()
        // Standing tasks: reload the durable store, recover anything missed
        // while the app was closed, and start the fire timer.
        // Store recovery performs filesystem I/O. Do not hold the event-tap
        // latch across it; Private Mode entry raises immediately, detached effects see the entry
        // receipt, and the normal entry transition suspends this runtime before
        // it can fire.
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        standingTaskRuntime.start()
        morningLinkBriefRuntime.start()
        guard enforceStealthForLaunchRaceIfNeeded() else { return }
        // No spoken launch line — "Ace, online." on every launch was self-
        // announcing noise (founder ruling 2026-07-26: the product never says
        // its own name). But that line was also, accidentally, the voice
        // pipeline's warm-up: without it the first real utterance paid the
        // swift-interpreter cold start out loud and stumbled. Warm silently
        // instead — same cost paid, nothing heard, voice-served.log still
        // written at launch.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
            guard let self else {
                return
            }
            guard self.enforceStealthForLaunchRaceIfNeeded() else {
                return
            }
            // Voice warmup may launch the built-in JXA voice daemon. Its own
            // registered synchronous cutoff owns the Private Mode entry race; never hold the
            // global latch across that process work.
            self.noraVoice.warmUpSilently()
        }

        // A clean install may have relaunched immediately after Accessibility
        // was granted. Resume only when this fresh process proves its event tap
        // is live; the persisted onboarding bit remains false until the owner
        // then delivers the rehearsal chord through that tap.
        guard performNormalStartupCommit({
            schedulePendingOnboardingHotkeyProofResume()
            schedulePendingScreenContentProofResume()
        }) else {
            return
        }

        // A returning owner's gem is the recovery surface when a permission or
        // optional app capability needs attention. Keep it visible in degraded
        // states; Stealth and the owner's explicit visibility toggle remain the
        // only launch-time reasons to hide it.
        if AssistantAvailabilityPolicy.shouldShowPersistentGem(
            hasCompletedOnboarding: hasCompletedOnboarding,
            cursorEnabled: isBlackLabelCursorEnabled,
            stealthVisibilityBlocked:
                StealthVisibilityGate.shared.isActive
                    || StealthEntryLatch.shared.isRaised,
            coreInteractionPermissionsReady:
                hasAccessibilityPermission
                    && hasScreenRecordingPermission
                    && hasMicrophonePermission
                    && hasScreenContentPermission,
            appAutomationReady:
                permissionWarmup.hasProvenAppAutomation
        ) {
            guard normalRuntimeAdmissionRemainsOpen else {
                _ = enforceStealthForLaunchRaceIfNeeded()
                return
            }
            overlayWindowManager.hasShownOverlayBefore = true
            guard overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            ) else {
                _ = enforceStealthForLaunchRaceIfNeeded()
                return
            }
            isOverlayVisible = true
        }
        _ = enforceStealthForLaunchRaceIfNeeded()
        captureLaunchScreenBearings()
    }

    private func bindEntitlementAdmissionIfNeeded() {
        guard licenseStateObserverIdentifier == nil else { return }
        lastObservedLicenseState = AceLicense.shared.state
        licenseStateObserverIdentifier =
            AceLicense.shared.addSynchronousEntitlementObserver {
                [weak self] state in
                self?.handleEntitlementStateChange(state)
            }
    }

    private func handleEntitlementStateChange(
        _ state: AceLicenseState
    ) {
        let wasQuiesced = premiumRuntimeIsQuiescedForEntitlement
        let transition = AceEntitlementAdmissionPolicy.runtimeTransition(
            from: lastObservedLicenseState,
            to: state
        )
        lastObservedLicenseState = state
        switch transition {
        case .quiescePremiumRuntime:
            quiescePremiumRuntimeForEntitlementLoss()
        case .openNewPremiumAdmission:
            openPremiumRuntimeIfEntitled()
        case .none:
            if !AceLicense.shared.admits(.premiumRuntimeStartup) {
                quiescePremiumRuntimeForEntitlementLoss()
            }
        }
        if !wasQuiesced, premiumRuntimeIsQuiescedForEntitlement {
            presentEntitlementRecoveryIfVisible()
        }
    }

    private func presentEntitlementRecoveryIfVisible() {
        guard !stealthMode.isActive,
              !StealthVisibilityGate.shared.isActive,
              !StealthEntryLatch.shared.isRaised else { return }
        MenuBarPanelManager.shared?.showPanelForManualOpen()
    }

    private func openPremiumRuntimeIfEntitled() {
        guard AceLicense.shared.admits(.premiumRuntimeStartup) else {
            return
        }
        // A server reactivation may arrive while Private Mode is still up.
        // Keep the newly valid lease, but do not reopen timers, background
        // lanes, permissions, capture watchers, or UI until the owner completes
        // a verified privacy exit. `exitStealthMode` applies this queued reopen.
        guard !StealthEntryLatch.shared.isRaised,
              !StealthVisibilityGate.shared.isActive,
              !stealthMode.isActive else {
            return
        }
        if !premiumRuntimeHasStarted {
            premiumRuntimeHasStarted = true
            premiumRuntimeIsQuiescedForEntitlement = false
            startPremiumRuntime()
            return
        }
        guard premiumRuntimeIsQuiescedForEntitlement else { return }
        premiumRuntimeIsQuiescedForEntitlement = false
        backgroundAgent.resumeNewWorkAfterEntitlementRestored()
        silverBackgroundAgent.resumeNewWorkAfterEntitlementRestored()
        workflowRuntime.resumeNewWorkAfterEntitlementRestored()
        meetingNotetaker.resumeNewWorkAfterEntitlementRestored()
        standingTaskRuntime.resumeNewWorkAfterEntitlementRestored()
        _ = appActionBroker.resumeAfterStealth()
        startPermissionPolling()
        refreshAllPermissions()
        if isBlackLabelCursorEnabled,
           !StealthVisibilityGate.shared.isActive,
           !StealthEntryLatch.shared.isRaised {
            overlayWindowManager.hasShownOverlayBefore = true
            isOverlayVisible = overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            )
        }
        appendRouteReceipt(
            "ENTITLEMENT restored — new premium work admitted; prior work not resumed"
        )
    }

    /// A server refusal/cancellation overrides onboarding, cached permissions,
    /// standing approval, and every already-open product surface. Teardown is
    /// synchronous on MainActor; recovery UI and owner stop/cancel controls do
    /// not depend on this premium admission.
    private func quiescePremiumRuntimeForEntitlementLoss(
        forceRecoveryStop: Bool = false
    ) {
        guard premiumRuntimeHasStarted else { return }
        guard forceRecoveryStop
                || !premiumRuntimeIsQuiescedForEntitlement else { return }
        premiumRuntimeIsQuiescedForEntitlement = true

        cancelAceHQDispatchSynchronouslyForStealth()
        discardPendingDirectEffectConfirmations()
        AceIntroWindowController.shared.close()
        cancelOnboardingPromptStream()
        cancelOnboardingDemoInteraction()
        cancelWalkthroughIfRunning()
        cancelFirstRunTourIfRunning(forceImmediate: true)

        partnerResponseGeneration = UUID()
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        partnerModeController?.suspendSynchronouslyForStealth()
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        currentResponseTask?.cancel()
        currentResponseTask = nil
        goldAnswerInterruption = .shutdown
        claudeAPI.cancelInFlightAnswer()
        noraVoice.stopPlayback()

        backgroundDispatchGeneration = UUID()
        pendingBackgroundExecutions.removeAll()
        backgroundQueueDrainTask?.cancel()
        backgroundQueueDrainTask = nil
        backgroundAgent.suspendForStealth()
        silverBackgroundAgent.suspendForStealth()
        workflowRuntime.suspendSynchronouslyForStealth()
        meetingNotetaker.suspendSynchronouslyForStealth()
        standingTaskRuntime.suspendAndCancelForEntitlementLoss()
        appActionBroker.suspendForStealth()
        permissionWarmup.suspendForStealth()
        permissionWarmupTask?.cancel()
        permissionWarmupTask = nil
        pendingKeyboardShortcutStartTask?.cancel()
        pendingKeyboardShortcutStartTask = nil
        screenContentRelaunchTask?.cancel()
        screenContentRelaunchTask = nil
        failCurrentScreenContentProofRequest()
        stopScanTheater()
        explainAppsChoreographyTask?.cancel()
        explainAppsChoreographyTask = nil
        accessibilityCheckTimer?.invalidate()
        accessibilityCheckTimer = nil
        if !stealthMode.isActive {
            globalPushToTalkShortcutMonitor.stop()
        }

        appActionPlanningGeneration = UUID()
        appActionPlanningTask?.cancel()
        appActionPlanningTask = nil
        appActionReviewExpiryTask?.cancel()
        appActionReviewExpiryTask = nil
        appActionReview = nil

        nativeLocationManager?.cancel()
        nativeLocationManager = nil
        localWeatherSessionContext.clear()
        morningBriefTask?.cancel()
        morningBriefTask = nil
        testEmailGeneration = UUID()
        testEmailTask?.cancel()
        testEmailTask = nil
        isPreparingTestEmailSend = false
        if let process = testEmailProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        testEmailProcess = nil
        recentEmailRead = nil
        emailReadGeneration = UUID()
        emailReadTask?.cancel()
        emailReadTask = nil
        if let process = emailReadProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        emailReadProcess = nil

        if tradingLane.isActive {
            tradingLane.deactivate()
        }
        tradingModeActive = false
        tradingDataStatus = .inactive
        voiceState = .idle
        backgroundTaskActive = false
        overlayWindowManager.hideOverlay()
        isOverlayVisible = false
        appendRouteReceipt(
            "ENTITLEMENT closed — all premium runtime surfaces quiesced"
        )
    }

    /// Ace takes its bearings from the screen the moment it comes up.
    ///
    /// FOUNDER RULING (2026-08-06): "anytime Ace turns on there has to be a
    /// screenshot sent, then from there he gets bearings and proceeds." Waiting
    /// for the first question meant the first answer of every session was
    /// reasoned without ever having looked.
    ///
    /// This is a warm capture, not an answer: nothing is spoken, nothing is
    /// shown, no model is called. It proves ScreenCaptureKit is live and primes
    /// the pipeline so the first real request is not paying cold-start cost.
    /// Stealth wins outright — a hidden Ace never captures — and a failure is
    /// recorded honestly rather than retried into a loop.
    private func captureLaunchScreenBearings() {
        guard !StealthEntryLatch.shared.isRaised else { return }
        guard hasScreenContentPermission else {
            // ASK. Do not skip.
            //
            // Ace cannot answer anything about the owner's screen without this
            // grant, so a missing grant is not a reason to go quiet — it is the
            // one thing Ace must raise immediately. `requestScreenContentPermission()`
            // deliberately refuses to prompt (it guards on
            // CGPreflightScreenCaptureAccess to avoid a surprise SCK dialog), and
            // the only code that ever calls CGRequestScreenCaptureAccess lives in
            // the first-run intro window — so once the grant is lost AFTER
            // onboarding (a rebuild resets it, macOS revokes it) nothing asked
            // ever again and Ace simply answered blind forever.
            requestScreenRecordingGrantFromOwner()
            return
        }
        Task { [weak self] in
            guard let self else { return }
            guard !StealthEntryLatch.shared.isRaised else { return }
            let scope = ScreenContextPolicy.launchBearingsScope
            do {
                let captures = try await CompanionScreenCaptureUtility
                    .captureAllScreensAsJPEG(
                        onlyCursorScreen: scope == .relevantDisplay
                    )
                guard !StealthEntryLatch.shared.isRaised else { return }
                self.appendRouteReceipt(
                    "LAUNCH-BEARINGS captured displays=\(captures.count)"
                )
            } catch {
                self.appendRouteReceipt(
                    "LAUNCH-BEARINGS failed errorType="
                        + String(describing: type(of: error))
                )
            }
        }
    }

    /// Raises the macOS Screen Recording prompt and tells the owner, in words
    /// and on screen, that Ace cannot see until it is granted.
    ///
    /// `CGRequestScreenCaptureAccess()` shows the system dialog the first time
    /// it is called for a given binary; once the owner has answered it, macOS
    /// will not show it again, so the spoken line and the persistent panel
    /// notice carry the instruction from then on. A new grant only takes effect
    /// in a fresh process, which the existing relaunch path already handles.
    private func requestScreenRecordingGrantFromOwner() {
        guard !StealthEntryLatch.shared.isRaised, directEffectsAreAllowed else {
            return
        }
        let screenRecordingAccessIsGranted = CGRequestScreenCaptureAccess()
        appendRouteReceipt(
            "LAUNCH-BEARINGS asking for screen recording — systemPrompt="
                + (screenRecordingAccessIsGranted ? "granted" : "shown-or-denied")
        )
        // Already granted. Say nothing: `hasScreenContentPermission` only turns
        // true after the async capture proof lands, so the launch-time read that
        // sent us here is false even on a fully granted Mac. Publishing the
        // "can't see your screen" text here told the owner to go fix a setting
        // that was never broken, on every single launch after they granted it.
        //
        // A grant made after this process started cannot reach ScreenCaptureKit
        // until a fresh process — the buyer's own onboarding does exactly that
        // (prompt → System Settings → back), so hand that case to the existing
        // relaunch path rather than leaving Ace silently blind for the session.
        if screenRecordingAccessIsGranted {
            if !screenRecordingWasAuthorizedAtProcessLaunch {
                relaunchForFreshScreenContentProof()
            }
            return
        }
        publishFinishSetupOwnerFacingStatus(
            "Ace can't see your screen yet."
                + " Allow Screen Recording for Ace in System Settings →"
                + " Privacy & Security → Screen & System Audio Recording,"
                + " then quit and reopen Ace."
        )
        guard hasCompletedOnboarding else { return }
        Task { [weak self] in
            try? await self?.noraVoice.speakText(
                "i can't see your screen yet. open system settings, privacy and"
                    + " security, screen and system audio recording, and turn ace"
                    + " on. then quit and reopen me and i'll be able to see.",
                priority: .background
            )
        }
    }

    /// A launch snapshot is never a lease. Re-probe the durable names and the
    /// event-tap latch at every startup boundary. If either closes admission,
    /// synchronously switch this partially started instance into the same
    /// fail-hidden runtime as an ordinary Private Mode entry.
    private var normalRuntimeAdmissionRemainsOpen: Bool {
        let restorationState = StealthDurableIntent.restorationState()
        return CompanionAppDelegate.normalRuntimeAdmissionIsOpen(
            restorationState: restorationState,
            entryLatchIsRaised: StealthEntryLatch.shared.isRaised
        )
    }

    @discardableResult
    func enforceStealthForLaunchRaceIfNeeded() -> Bool {
        guard normalRuntimeAdmissionRemainsOpen else {
            bindPrivateModeTriggers()
            if normalRuntimeStartupHasBegun {
                enterStealthMode(silently: true)
            } else {
                startRecoveredStealthRuntime()
            }
            return false
        }
        return true
    }

    /// Linearizes one bounded startup commit against the event-tap latch. The
    /// durable probe handles preexisting intent; `performUnlessRaised` closes
    /// the final instruction-level gap so an entry request that wins first prevents the
    /// timer, watcher, service, or visible surface from being created.
    @discardableResult
    func performNormalStartupCommit(
        _ body: () -> Void
    ) -> Bool {
        guard normalRuntimeAdmissionRemainsOpen else {
            _ = enforceStealthForLaunchRaceIfNeeded()
            return false
        }
        let committed =
            StealthEntryLatch.shared.performUnlessRaised {
                body()
                return true
            } ?? false
        guard committed else {
            _ = enforceStealthForLaunchRaceIfNeeded()
            return false
        }
        return true
    }

    static func stealthBoundaryRepairIsAllowed(
        stealthIsActive: Bool,
        exitTransitionInProgress: Bool
    ) -> Bool {
        stealthIsActive && !exitTransitionInProgress
    }

    /// Crash/relaunch recovery for an owner who never issued the Stealth exit
    /// chord. No menu UI, passive microphone, screen capture, background worker,
    /// scheduler, setup flow, analytics, or voice daemon is started here. The
    /// event-tap PTT sink may open only the explicit on-device exit recognizer.
    private func startRecoveredStealthRuntime() {
        guard !restoredDurableStealthAtLaunch else { return }
        restoredDurableStealthAtLaunch = true
        StealthVisibilityGate.shared.activateLocalWall()
        // `noraVoice` is lazy and its initializer writes the daemon script.
        // The recovered process never starts normal speech, so the raised latch
        // itself is the voice wall and the exit-only recognizer never constructs
        // the mouth at all.
        // Do not touch any lazy normal-runtime subsystem here. None was started
        // on this launch, and the durable latch already blocks every entry point.
        isOverlayVisible = false
        stealthMode.activate()
        // Constructing the capture coordinator does not touch the mic. Apple
        // Speech and AVAudioEngine are created only after the physical PTT press.
        stealthExitOnlyCapture.enterStealth(epoch: UUID())
        // The recovered runtime never touches these lazy normal-runtime owners.
        // A fresh process has no location request or session context to cancel.
        globalPushToTalkShortcutMonitor.privateModeIsActive = true
        stealthActive = true
        bindPrivateModeTriggers()

        hasAccessibilityPermission =
            WindowPositionManager.hasAccessibilityPermission()
        // Start the hotkey path even when permission is currently false.
        // On relaunch, this creates a single, bounded recovery point: a
        // re-prompted or newly granted Accessibility setting naturally restores
        // the silent exit control once possible.
        globalPushToTalkShortcutMonitor.start()
        bindShortcutTransitions()
        stealthHotkeyWasDegraded = !globalPushToTalkShortcutMonitor.isEventTapOperational
        privateModeActivityStatus = stealthHotkeyWasDegraded
            ? "Private Mode is active; enable Accessibility for the silent exit key."
            : "Private Mode is active; silent exit key is ready."
        appendRouteReceipt(
            "STEALTH recovered from durable owner intent; hotkey-operational="
                + String(!stealthHotkeyWasDegraded)
        )

        let externalStatus =
            StealthVisibilityGate.shared.secureExternalBoundary(timeout: 2)
        startStealthHotkeyHealthMonitor()
        appendRouteReceipt(
            "STEALTH restored from durable owner intent; external="
                + String(describing: externalStatus)
        )
    }

    /// Start uses the established provider and permission gates. The screen
    /// demonstration and spoken rehearsal belong to the optional tour.
    func triggerOnboarding() {
        guard !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed,
              !hasCompletedOnboarding,
              startFromPanelTask == nil else {
            return
        }
        cancelFirstRunTourIfRunning(forceImmediate: true)
        isStartingFromPanel = true
        publishFinishSetupOwnerFacingStatus("Starting Ace…")
        startFromPanelTask = Task { [weak self] in
            guard let self else { return }
            defer {
                self.startBrainConnection?.cancelAllWork()
                self.startBrainConnection = nil
                self.startFromPanelTask = nil
                self.isStartingFromPanel = false
            }
            await SetupWalkthrough.shared.cancelForStart()
            guard !Task.isCancelled, self.directEffectsAreAllowed,
                  !StealthEntryLatch.shared.isRaised else { return }
            AceIntroWindowController.shared.close()
            self.refreshAllPermissions()
            guard InstallLocation.isRunningFromAllowedStableLocation,
                  AceLicense.shared.allowsUse,
                  AceLicense.shared.storedKey != nil,
                  self.coreInteractionPermissionsGranted,
                  VoiceReadiness.shared.state == .ready else {
                self.publishFinishSetupOwnerFacingStatus(
                    "Before starting, \(self.firstRunSetupMissingStep). Open Setup to finish that step."
                )
                return
            }
            if !BrainConnectionProof.hasAnsweredRealProbe {
                // Setup receipts expire after fifteen minutes. Recheck the
                // existing account here instead of reopening the entire tour.
                guard AceBrainRoute.current == .customerOwned else {
                    self.publishFinishSetupOwnerFacingStatus(
                        "Open Setup and check your AI connection, then press Start."
                    )
                    return
                }
                let connection = BrainConnectionModel()
                let provider = BrainBackend.selectedCLI
                self.startBrainConnection = connection
                guard connection.canVerifyExistingAuthentication(for: provider) else {
                    self.publishFinishSetupOwnerFacingStatus(
                        "Open Setup to sign in to \(provider.displayName), then press Start."
                    )
                    return
                }
                self.publishFinishSetupOwnerFacingStatus(
                    "Checking your \(provider.displayName) connection…"
                )
                guard connection.connectProvider(provider) else {
                    self.publishFinishSetupOwnerFacingStatus(
                        "The AI connection check did not start. Open Setup to check the connection."
                    )
                    return
                }
                let result = await connection.waitForProviderRepairTerminal(provider)
                guard !Task.isCancelled, self.directEffectsAreAllowed,
                      !StealthEntryLatch.shared.isRaised else { return }
                if case let .failed(failure) = result {
                    self.publishFinishSetupOwnerFacingStatus(
                        "\(failure.message) Open Setup to check the connection, or press Start to retry."
                    )
                    return
                }
            }
            self.activateFromStartIfReady()
        }
    }

    func cancelStartActivation() {
        guard startFromPanelTask != nil else { return }
        startFromPanelTask?.cancel()
        startBrainConnection?.cancelAllWork()
        publishFinishSetupOwnerFacingStatus("Start cancelled. Press Start when you are ready.")
    }

    private func activateFromStartIfReady() {
        guard !Task.isCancelled, directEffectsAreAllowed,
              !StealthEntryLatch.shared.isRaised else { return }
        refreshAllPermissions()
        guard requiredFirstRunSetupProofsReady,
              FirstRunFlowPolicy.mayActivateFromStart(
                isRunningFromCanonicalInstall: InstallLocation.isRunningFromAllowedStableLocation,
                providerAnsweredLive: BrainConnectionProof.hasAnsweredRealProbe,
                corePermissionsReady: coreInteractionPermissionsGranted
              ) else {
            publishFinishSetupOwnerFacingStatus(
                "Before starting, \(firstRunSetupMissingStep). Open Setup to finish that step."
            )
            return
        }
        if !globalPushToTalkShortcutMonitor.isEventTapOperational {
            globalPushToTalkShortcutMonitor.start()
        }
        guard globalPushToTalkShortcutMonitor.isEventTapOperational else {
            publishFinishSetupOwnerFacingStatus(
                "Ace cannot receive the talk shortcut yet. Open Setup to repair Accessibility."
            )
            return
        }
        guard performDirectEffectCommit({
            self.hasCompletedOnboarding = true
            UserDefaults.standard.removeObject(forKey: Self.pendingOnboardingHotkeyProofKey)
            UserDefaults.standard.removeObject(forKey: Self.pendingScreenContentProofKey)
            return true
        }) else { return }
        clearFinishSetupOwnerFacingStatus()
        AceIntroWindowController.shared.close()
        NotificationCenter.default.post(name: .blacklabelDismissPanel, object: nil)
        if isBlackLabelCursorEnabled {
            isOverlayVisible = overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            )
        }
        LifecycleLog.append("ONBOARDING activated from Start — provider, permissions and shortcut ready; tour optional")
    }

    var firstRunSetupPrerequisitesReady: Bool {
        requiredFirstRunSetupProofsReady
    }

    private var firstRunSetupMissingStep: String {
        if !InstallLocation.isRunningFromAllowedStableLocation { return "install Ace in Applications" }
        if !AceLicense.shared.allowsUse || AceLicense.shared.storedKey == nil { return "link your Ace account" }
        if !coreInteractionPermissionsGranted { return "check macOS permissions" }
        if VoiceReadiness.shared.state != .ready { return "check Ace Voice" }
        if !BrainConnectionProof.hasAnsweredRealProbe { return "refresh the live AI connection check" }
        return "finish the live setup check"
    }

    private var requiredFirstRunSetupProofsReady: Bool {
        InstallLocation.isRunningFromAllowedStableLocation
            && AceLicense.shared.allowsUse
            && AceLicense.shared.storedKey != nil
            && FirstRunFlowPolicy.prerequisitesAreReady(
                providerAnsweredLive:
                    BrainConnectionProof.hasAnsweredRealProbe,
                corePermissionsReady: coreInteractionPermissionsGranted
            )
            && VoiceReadiness.shared.state == .ready
    }

    private func currentFirstRunEvidence(
        liveScreenAnswerSucceeded: Bool
    ) -> AceFirstRunEvidence {
        AceFirstRunEvidence(
            providerAnsweredLive:
                BrainConnectionProof.hasAnsweredRealProbe,
            corePermissionsReady: coreInteractionPermissionsGranted,
            liveScreenAnswerSucceeded: liveScreenAnswerSucceeded,
            shortcutPressObserved:
                firstRunRehearsalProofProgress
                    .didObserveEventTapKeyboardPress,
            transcriptObserved:
                firstRunRehearsalProofProgress
                    .didRecognizeKnownPhrase,
            shortcutReleaseObserved:
                firstRunRehearsalProofProgress
                    .didObserveEventTapKeyboardRelease
        )
    }

    /// Current health may expose Repair Ace, but it never clears the sticky
    /// first-run completion bit or re-enters setup automatically.
    var currentSetupProofsReady: Bool {
        guard hasCompletedOnboarding else { return requiredFirstRunSetupProofsReady }
        return InstallLocation.isRunningFromAllowedStableLocation
            && AceLicense.shared.allowsUse
            && AceLicense.shared.storedKey != nil
            && coreInteractionPermissionsGranted
            && VoiceReadiness.shared.state == .ready
            && BrainConnectionProof.hasReusableRuntimeProof
    }

    private func completeOnboardingAfterProof() {
        guard !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return
        }
        refreshAllPermissions()
        guard !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return
        }
        guard requiredFirstRunSetupProofsReady else {
            LifecycleLog.append("ONBOARDING completion refused — a required proof changed")
            SetupWalkthrough.shared.runIfAnythingIsMissing(
                companionManager: self,
                onComplete: { [weak self] in self?.completeOnboardingAfterProof() }
            )
            return
        }

        // Setup is not complete until a fresh process can observe the shortcut
        // through its event tap and the later transcript/release rehearsal can
        // finish. Keep a durable resume bit before any relaunch so a timeout,
        // cancellation, or crash cannot turn an unproven install into a
        // completed one.
        guard performDirectEffectCommit({
            UserDefaults.standard.removeObject(
                forKey: Self.pendingScreenContentProofKey
            )
            UserDefaults.standard.set(
                true,
                forKey: Self.pendingOnboardingHotkeyProofKey
            )
            return true
        }) else {
            return
        }

        // No onboarding soundtrack (founder ruling 2026-07-25). It played a
        // licensed game theme over a product we sell, and it started before the
        // owner had any way to stop it — an app that opens by playing music at
        // you is a worse first impression than silence.

        // The introduction is Ace MOVING: the gem flies to its own menu-bar icon
        // and then around the screen, one spoken line per stop. (The old
        // "onboarding video" this replaced never existed — `onboardingVideoPlayer`
        // was nil in every build, so first run showed a transparent rectangle.)

        // Accessibility granted DURING setup is the normal buyer path — and a
        // CGEvent tap in an already-running process stays deaf until relaunch,
        // even though the TCC bool reads true. Observed live 2026-07-26: the
        // rehearsal waited 45 seconds through a real hold it couldn't hear.
        // So if the tap still won't install after one more attempt, relaunch
        // INTO the show: mark the tour to resume, respawn from the bundle path,
        // and let the fresh process — whose tap installs cleanly — play it.
        if !globalPushToTalkShortcutMonitor.isEventTapOperational {
            // `start()` prepares the latch's external receipt before it
            // installs the first event tap. It must not run while holding the
            // latch because that preparation itself updates latch state.
            globalPushToTalkShortcutMonitor.start()
            guard !StealthEntryLatch.shared.isRaised,
                  directEffectsAreAllowed else {
                return
            }
        }
        if !globalPushToTalkShortcutMonitor.isEventTapOperational {
            guard performDirectEffectCommit({ [weak self] in
                self?.appendRouteReceipt(
                    "TOUR deferred across relaunch — tap dead "
                        + "despite accessibility grant"
                )
                return self != nil
            }) else {
                return
            }
            let bundlePath = Bundle.main.bundlePath
            let relauncher = Process()
            relauncher.executableURL = URL(fileURLWithPath: "/bin/sh")
            // The child outlives us, waits out our exit, then opens the bundle
            // by PATH (never by name — the launch-by-path rule).
            // The path arrives as "$1", never spliced into the script text: a
            // bundle path containing a quote would otherwise end the string and
            // let the remainder run as shell. Ace's own path is not attacker
            // input today, but a rename is all it would take.
            relauncher.arguments = [
                "-c", "sleep 0.8; /usr/bin/open \"$1\"", "--", bundlePath,
            ]

            let processCutoff = MailToolProcessCutoff()
            let cutoffIdentifier =
                StealthEntryLatch.shared
                    .registerSynchronousEntryCutoff {
                        processCutoff.cancelSynchronously()
                    }
            let launchOutcome =
                DirectEffectProcessLaunchAdmission.commit(
                    effectsAreAllowed: { [weak self] in
                        self?.directEffectsAreAllowed == true
                    },
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared
                            .performUnlessRaised(body)
                    },
                    launchAndPublish: {
                        do {
                            try relauncher.run()
                            processCutoff.register(relauncher)
                            return true
                        } catch {
                            return false
                        }
                    }
                )
            guard launchOutcome == .launched else {
                processCutoff.clear()
                StealthEntryLatch.shared
                    .unregisterSynchronousEntryCutoff(
                        cutoffIdentifier
                    )
                return
            }
            Task { @MainActor [weak self] in
                defer {
                    processCutoff.clear()
                    StealthEntryLatch.shared
                        .unregisterSynchronousEntryCutoff(
                            cutoffIdentifier
                        )
                }
                while relauncher.isRunning {
                    guard let self,
                          !processCutoff.isCancelled,
                          !StealthEntryLatch.shared.isRaised,
                          self.directEffectsAreAllowed else {
                        processCutoff.cancelSynchronously()
                        return
                    }
                    try? await Task.sleep(
                        for: .milliseconds(50)
                    )
                }
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {
                guard !processCutoff.isCancelled,
                      !StealthEntryLatch.shared.isRaised else {
                    processCutoff.cancelSynchronously()
                    return
                }
                _ = StealthEntryLatch.shared.performUnlessRaised {
                    guard !processCutoff.isCancelled,
                          !StealthVisibilityGate.shared.isActive else {
                        processCutoff.cancelSynchronously()
                        return false
                    }
                    NSApp.terminate(nil)
                    return true
                }
            }
            return
        }

        pendingOnboardingHotkeyResumeTask?.cancel()
        pendingOnboardingHotkeyResumeTask = nil
        screenContentRelaunchTask?.cancel()
        pendingScreenContentProofResumeTask?.cancel()
        pendingScreenContentProofResumeTask = nil
        screenContentRelaunchTask?.cancel()
        screenContentRelaunchTask = nil
        failCurrentScreenContentProofRequest()
        startFirstRunTour(requiresOnboardingHotkeyProof: true)
    }

    private func persistFirstRunCompletionIfProven(
        productionScreenAnswerExerciseSucceeded: Bool,
        rehearsalResult: FirstRunRehearsalResult
    ) -> Bool {
        refreshAllPermissions()
        let evidence = currentFirstRunEvidence(
            liveScreenAnswerSucceeded:
                productionScreenAnswerExerciseSucceeded
        )
        guard InstallLocation.isRunningFromAllowedStableLocation,
              requiredFirstRunSetupProofsReady,
              globalPushToTalkShortcutMonitor.isEventTapOperational,
              rehearsalResult == .observed,
              AssistantAvailabilityPolicy.mayPersistFirstRunCompletion(
                phase: FirstRunFlowPolicy.phase(for: evidence)
              ) else {
            appendRouteReceipt(
                "ONBOARDING remains incomplete — hotkey rehearsal proof missing or stale")
            return false
        }

        hasCompletedOnboarding = true
        UserDefaults.standard.removeObject(
            forKey: Self.pendingOnboardingHotkeyProofKey
        )
        // Pre-warm the push-to-talk grants while the owner is still in a setup
        // frame of mind. BuddyDictationManager owns a purpose-built routine for
        // this and it had ZERO callers tree-wide, so if Microphone or Speech was
        // still .notDetermined at this point the FIRST hold paid for it: the
        // macOS dialog opened in the middle of the capture and that first
        // utterance was lost. It self-guards on needsInitialPermissionPrompt, so
        // on a Mac whose grants setup already resolved this is a no-op and no
        // dialog appears.
        Task { [weak self] in
            await self?.buddyDictationManager
                .requestInitialPushToTalkPermissionsIfNeeded()
        }
        LifecycleLog.append(
            "ONBOARDING completed — clean-Mac proofs, event tap, and live screen/brain exercise passed")
        return true
    }

    private func schedulePendingOnboardingHotkeyProofResume() {
        guard UserDefaults.standard.bool(
            forKey: Self.pendingOnboardingHotkeyProofKey
        ), !hasCompletedOnboarding, pendingOnboardingHotkeyResumeTask == nil
        else {
            if hasCompletedOnboarding {
                UserDefaults.standard.removeObject(
                    forKey: Self.pendingOnboardingHotkeyProofKey
                )
            }
            return
        }

        // Once the owner has seen the full tour, proof recovery becomes an
        // explicit Finish Setup action. Relaunching must never replay the five
        // stops or start listening/capture work without that action.
        guard !hasViewedFirstRunTour else {
            appendRouteReceipt(
                "ONBOARDING proof pending — Finish Setup remains available"
            )
            return
        }

        pendingOnboardingHotkeyResumeTask = Task { [weak self] in
            do {
                try await Task.sleep(for: .milliseconds(350))
            } catch {
                return
            }
            guard let self, !Task.isCancelled else { return }

            var attempt = 0
            var didOfferGuidedAutomationRepair = false
            while !Task.isCancelled {
                guard UserDefaults.standard.bool(
                    forKey: Self.pendingOnboardingHotkeyProofKey
                ), !self.hasCompletedOnboarding else {
                    self.pendingOnboardingHotkeyResumeTask = nil
                    return
                }
                self.refreshAllPermissions()
                if self.requiredFirstRunSetupProofsReady {
                    if !self.globalPushToTalkShortcutMonitor.isEventTapOperational {
                        self.globalPushToTalkShortcutMonitor.start()
                    }
                    if self.globalPushToTalkShortcutMonitor.isEventTapOperational,
                       !self.stealthMode.isActive,
                       !StealthVisibilityGate.shared.isActive {
                        AceIntroWindowController.shared.close()
                        self.appendRouteReceipt(
                            "TOUR resumed after relaunch — event tap operational")
                        self.pendingOnboardingHotkeyResumeTask = nil
                        self.startFirstRunTour(
                            requiresOnboardingHotkeyProof: true
                        )
                        return
                    }
                }

                if attempt == 15,
                   self.permissionWarmup.isRevalidatingAutomation {
                    self.permissionWarmup
                        .failCurrentNoninteractiveRevalidation()
                    self.appendRouteReceipt(
                        "ONBOARDING post-relaunch Automation recheck timed out — guided retry required"
                    )
                }
                if !didOfferGuidedAutomationRepair,
                   !self.permissionWarmup.isRevalidatingAutomation,
                   !self.permissionWarmup.hasProvenAppAutomation,
                   !self.stealthMode.isActive,
                   !StealthVisibilityGate.shared.isActive {
                    didOfferGuidedAutomationRepair = true
                    SetupWalkthrough.shared.runIfAnythingIsMissing(
                        companionManager: self
                    )
                }

                if attempt == 30 {
                    self.appendRouteReceipt(
                        "ONBOARDING proof still pending after 30 seconds — continuing recovery checks")
                }
                do {
                    try await Task.sleep(
                        for: Self.pendingOnboardingProofRetryDelay(
                            afterAttempt: attempt
                        )
                    )
                } catch {
                    return
                }
                attempt += 1
            }
        }
    }

    private func schedulePendingScreenContentProofResume() {
        guard UserDefaults.standard.bool(
            forKey: Self.pendingScreenContentProofKey
        ), !hasCompletedOnboarding,
           pendingScreenContentProofResumeTask == nil else {
            if hasCompletedOnboarding {
                UserDefaults.standard.removeObject(
                    forKey: Self.pendingScreenContentProofKey
                )
            }
            return
        }

        pendingScreenContentProofResumeTask = Task { [weak self] in
            do {
                try await Task.sleep(for: .milliseconds(500))
            } catch {
                return
            }
            guard let self,
                  !Task.isCancelled,
                  UserDefaults.standard.bool(
                    forKey: Self.pendingScreenContentProofKey
                  ),
                  !StealthVisibilityGate.shared.isActive else {
                self?.pendingScreenContentProofResumeTask = nil
                return
            }
            self.pendingScreenContentProofResumeTask = nil
            SetupWalkthrough.shared.runIfAnythingIsMissing(
                companionManager: self,
                onComplete: { [weak self] in
                    self?.completeOnboardingAfterProof()
                }
            )
        }
    }

    /// The process that first receives Screen Recording cannot be trusted to
    /// prove SCK capture. Publish a dedicated resume marker, launch a new process
    /// from the exact canonical bundle, and terminate only after that new process
    /// is observed. On failure this process stays alive and the marker lets a
    /// later manual reopen resume at the capture step.
    @discardableResult
    func relaunchForFreshScreenContentProof() -> Bool {
        guard screenContentRelaunchTask == nil,
              InstallLocation.isRunningFromAllowedStableLocation,
              CGPreflightScreenCaptureAccess(),
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return false
        }
        guard performDirectEffectCommit({
            UserDefaults.standard.set(
                true,
                forKey: Self.pendingScreenContentProofKey
            )
            return true
        }) else {
            return false
        }
        let bundleIdentifier = Bundle.main.bundleIdentifier
        let processesPresentBeforeLaunch = Set(
            bundleIdentifier.map {
                NSRunningApplication.runningApplications(
                    withBundleIdentifier: $0
                ).map(\.processIdentifier)
            } ?? []
        )

        screenContentRelaunchTask = Task { [weak self] in
            guard let self else { return }
            defer { self.screenContentRelaunchTask = nil }
            guard !Task.isCancelled,
                  !StealthEntryLatch.shared.isRaised,
                  self.directEffectsAreAllowed else {
                return
            }

            let launcher = Process()
            launcher.executableURL = URL(
                fileURLWithPath: "/usr/bin/open"
            )
            launcher.arguments = [
                "-n",
                InstallLocation.allowedBundlePath,
            ]
            let processCutoff = MailToolProcessCutoff()
            let cutoffIdentifier =
                StealthEntryLatch.shared
                    .registerSynchronousEntryCutoff {
                        processCutoff.cancelSynchronously()
                    }
            defer {
                processCutoff.clear()
                StealthEntryLatch.shared
                    .unregisterSynchronousEntryCutoff(
                        cutoffIdentifier
                    )
            }
            // Hand the singleton to the replacement BEFORE launching it. Ace
            // holds an exclusive `flock` for its runtime instance, and a second
            // process that cannot acquire it self-terminates at startup by
            // design. This path ran `open -n` while still holding that lock, so
            // the replacement always died instantly, this process never saw a
            // survivor, and "Restart Ace" reported that the new process "did
            // not stay running" — a button that could not succeed on any Mac.
            // `resumeDeferredStartupAfterEntitlement` already performs exactly
            // this release for exactly this reason; this path was missed.
            // Re-acquired on every branch that does not hand off.
            AceRuntimeInstanceLock.shared.release()
            let launchOutcome =
                DirectEffectProcessLaunchAdmission.commit(
                    effectsAreAllowed: { [weak self] in
                        guard let self else { return false }
                        return !Task.isCancelled
                            && self.directEffectsAreAllowed
                    },
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared
                            .performUnlessRaised(body)
                    },
                    launchAndPublish: {
                        do {
                            try launcher.run()
                            processCutoff.register(launcher)
                            return true
                        } catch {
                            return false
                        }
                    }
                )
            guard launchOutcome == .launched else {
                // Nothing was handed off: take the singleton back so this
                // process stays the legitimate runtime owner.
                _ = AceRuntimeInstanceLock.shared.acquire()
                guard launchOutcome == .launchFailed,
                      !Task.isCancelled,
                      !processCutoff.isCancelled,
                      !StealthEntryLatch.shared.isRaised,
                      self.directEffectsAreAllowed else {
                    return
                }
                self.reportScreenContentRelaunchFailure(
                    detail:
                        "the relaunch helper could not launch"
                )
                return
            }
            let clock = ContinuousClock()
            let launcherDeadline =
                clock.now.advanced(by: .seconds(3))
            while launcher.isRunning,
                  clock.now < launcherDeadline,
                  !Task.isCancelled,
                  !processCutoff.isCancelled,
                  !StealthEntryLatch.shared.isRaised,
                  self.directEffectsAreAllowed {
                do {
                    try await Task.sleep(for: .milliseconds(50))
                } catch {
                    processCutoff.cancelSynchronously()
                    return
                }
            }
            guard !processCutoff.isCancelled else { return }
            guard !launcher.isRunning else {
                processCutoff.cancelSynchronously()
                guard !StealthEntryLatch.shared.isRaised,
                      self.directEffectsAreAllowed else {
                    return
                }
                self.reportScreenContentRelaunchFailure(
                    detail: "/usr/bin/open did not exit within 3 seconds"
                )
                return
            }
            let launcherStatus = launcher.terminationStatus
            guard !StealthEntryLatch.shared.isRaised,
                  !processCutoff.isCancelled,
                  self.directEffectsAreAllowed,
                  launcherStatus == 0,
                  let bundleIdentifier else {
                guard !Task.isCancelled,
                      !processCutoff.isCancelled,
                      !StealthEntryLatch.shared.isRaised,
                      self.directEffectsAreAllowed else {
                    return
                }
                self.reportScreenContentRelaunchFailure(
                    detail:
                        "/usr/bin/open exited \(launcherStatus)"
                )
                return
            }

            let deadline = clock.now.advanced(by: .seconds(10))
            var candidateProcessIdentifier: pid_t?
            var candidateFirstObservedAt: ContinuousClock.Instant?
            while clock.now < deadline,
                  !Task.isCancelled,
                  !processCutoff.isCancelled,
                  !StealthEntryLatch.shared.isRaised,
                  self.directEffectsAreAllowed {
                let candidate =
                    NSRunningApplication.runningApplications(
                        withBundleIdentifier: bundleIdentifier
                    ).first { application in
                        guard !processesPresentBeforeLaunch.contains(
                                application.processIdentifier
                              ),
                              !application.isTerminated,
                              application.isFinishedLaunching,
                              let bundleURL = application.bundleURL else {
                            return false
                        }
                        return bundleURL.path
                                == InstallLocation.allowedBundlePath
                            && bundleURL.resolvingSymlinksInPath().path
                                == InstallLocation.allowedBundlePath
                    }
                if let candidate {
                    if candidateProcessIdentifier
                            != candidate.processIdentifier {
                        candidateProcessIdentifier =
                            candidate.processIdentifier
                        candidateFirstObservedAt = clock.now
                    } else if let candidateFirstObservedAt,
                              candidateFirstObservedAt.duration(
                                to: clock.now
                              ) >= .seconds(1) {
                        _ = self.performDirectEffectCommit {
                            guard !Task.isCancelled,
                                  !processCutoff.isCancelled else {
                                return false
                            }
                            NSApp.terminate(nil)
                            return true
                        }
                        return
                    }
                } else {
                    candidateProcessIdentifier = nil
                    candidateFirstObservedAt = nil
                }
                do {
                    try await Task.sleep(for: .milliseconds(200))
                } catch {
                    processCutoff.cancelSynchronously()
                    return
                }
            }
            guard !processCutoff.isCancelled,
                  !StealthEntryLatch.shared.isRaised,
                  self.directEffectsAreAllowed else {
                return
            }
            self.reportScreenContentRelaunchFailure(
                detail:
                    "the new \(InstallLocation.allowedBundlePath) process did not stay running"
            )
        }
        return true
    }

    private func reportScreenContentRelaunchFailure(detail: String) {
        // Reaching here means no replacement took over, so this process is
        // still the runtime and must hold the singleton it released before
        // attempting the handoff. Idempotent: a lock already held stays held.
        _ = AceRuntimeInstanceLock.shared.acquire()
        _ = performDirectEffectCommit {
            FirstRunFailureReporter.shared.report(
                FirstRunFailure(
                    id: "onboarding.screenContentRelaunch",
                    summary:
                        "Ace could not restart for the screen check.",
                    remedy:
                        "\(detail)\n\nQuit Ace, then open "
                        + "\(InstallLocation.allowedBundlePath) from "
                        + "Applications. Setup resumes at the screen "
                        + "check.",
                    repairButtonTitle: nil
                ),
                interrupt: true
            )
            return true
        }
    }

    /// Replays the onboarding experience from the "Watch Onboarding Again"
    /// footer link. Same flow as triggerOnboarding but the cursor overlay
    /// is already visible so we just restart the welcome animation and video.
    func replayOnboarding() {
        guard !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return
        }
        NotificationCenter.default.post(
            name: .blacklabelDismissPanel,
            object: nil
        )
        goldOwnerInterruptionGeneration = UUID()
        currentResponseTask?.cancel()
        currentResponseTask = nil
        noraVoice.stopPlayback()
        finishWaveformTurn(reason: .turnReplacement)
        let replayTurnID = AceEventBus.shared.beginDirectHumanTurn()
        activeRoutingTurnID = replayTurnID
        beginWaveformTurn(turnID: replayTurnID, source: .replayTour)
        BlackLabelAnalytics.trackOnboardingReplayed()
        startFirstRunTour()
    }

    func clearDetectedElementLocation() {
        detectedElementScreenLocation = nil
        detectedElementDisplayFrame = nil
        detectedElementBubbleText = nil
    }

    func stop() {
        cancelOnboardingPromptStream()
        cancelOnboardingDemoInteraction()
        globalPushToTalkShortcutMonitor.stop()
        // A recovered process never constructed normal subsystems. Do not force
        // lazy microphone, overlay, model, broker, or permission objects into
        // life merely to stop work that was never started.
        if restoredDurableStealthAtLaunch {
            stealthHotkeyHealthTimer?.invalidate()
            stealthHotkeyHealthTimer = nil
            return
        }
        meetingNotetaker.shutdownSynchronouslyForAppExit()
        noraVoice.shutdown()
        finishWaveformTurn(reason: .cancelled)
        buddyDictationManager.cancelCurrentDictation()
        overlayWindowManager.hideOverlay()
        transientHideTask?.cancel()
        clearVisibleResponse()

        goldAnswerInterruption = .shutdown
        currentResponseTask?.cancel()
        currentResponseTask = nil
        appActionPlanningGeneration = UUID()
        appActionPlanningTask?.cancel()
        appActionPlanningTask = nil
        discardPendingDirectEffectConfirmations()
        appActionBroker.cancelCurrentAction()
        appActionWorkCorrelationIdentifier = nil
        appActionVolatileTurnIdentifier = nil
        appActionUsesVolatileTurnContext = false
        claudeAPI.cancelInFlightAnswer()
        shortcutTransitionCancellable?.cancel()
        if let licenseStateObserverIdentifier {
            AceLicense.shared.removeSynchronousEntitlementObserver(
                licenseStateObserverIdentifier
            )
            self.licenseStateObserverIdentifier = nil
        }
        voiceStateCancellable?.cancel()
        audioPowerCancellable?.cancel()
        SpeechProviderSwitchBoundary.handler = nil
        accessibilityCheckTimer?.invalidate()
        accessibilityCheckTimer = nil
        if let screenParametersObserver {
            NotificationCenter.default.removeObserver(screenParametersObserver)
        }
        screenParametersObserver = nil
        screenChangeDebounceTask?.cancel()
        screenChangeDebounceTask = nil
        pendingOnboardingHotkeyResumeTask?.cancel()
        pendingOnboardingHotkeyResumeTask = nil
        testEmailGeneration = UUID()
        testEmailTask?.cancel()
        testEmailTask = nil
        isPreparingTestEmailSend = false
        if let process = testEmailProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        testEmailProcess = nil
        recentEmailRead = nil
        emailReadGeneration = UUID()
        emailReadTask?.cancel()
        emailReadTask = nil
        if let process = emailReadProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        emailReadProcess = nil
    }

    /// The normal teardown already completed synchronously before helper
    /// handoff. Termination must only retire the in-process keyboard repair
    /// machinery; calling `stop()` here would lazily wake normal voice/model/UI
    /// owners and could create a final receipt after Stealth became active.
    func stopForBackgroundServiceStealthHandoff() {
        globalPushToTalkShortcutMonitor.stop()
        stealthHotkeyHealthTimer?.invalidate()
        stealthHotkeyHealthTimer = nil
    }

    /// Rebuilds the overlay windows when the display configuration changes.
    /// Overlay windows freeze each screen's frame at creation, so after a
    /// monitor is plugged/unplugged, rearranged, or rescaled (or a DP display
    /// sleeps/wakes) the gem points at stale coordinates or never appears on a
    /// newly-connected display — and it only self-heals on relaunch. The
    /// notification fires several times per change, so the rebuild is debounced.
    private func observeScreenParameterChanges() {
        screenParametersObserver = NotificationCenter.default.addObserver(
            forName: NSApplication.didChangeScreenParametersNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                self?.handleScreenParametersChange()
            }
        }
    }

    private func handleScreenParametersChange() {
        screenChangeDebounceTask?.cancel()
        screenChangeDebounceTask = Task { [weak self] in
            try? await Task.sleep(for: .milliseconds(300))
            guard let self, !Task.isCancelled else { return }
            // Only rebuild a live overlay, and never mid-onboarding (the welcome
            // video owns the overlay). Set hasShownOverlayBefore so the welcome
            // animation does NOT replay; showOverlay tears down the stale windows
            // first, then recreates one per CURRENT screen.
            guard self.isOverlayVisible, !self.showOnboardingVideo else { return }
            self.overlayWindowManager.hasShownOverlayBefore = true
            self.isOverlayVisible =
                self.overlayWindowManager.showOverlay(
                    onScreens: NSScreen.screens,
                    companionManager: self
                )
        }
    }

    func refreshAllPermissions() {
        guard AceLicense.shared.admits(.permissionRepair) else {
            if !stealthMode.isActive {
                globalPushToTalkShortcutMonitor.stop()
            }
            return
        }
        let previouslyHadAccessibility = hasAccessibilityPermission
        let previouslyHadScreenRecording = hasScreenRecordingPermission
        let previouslyHadMicrophone = hasMicrophonePermission
        let previousAppleSpeechRecognitionReadiness = appleSpeechRecognitionReadiness
        let previouslyHadAll = allPermissionsGranted

        let currentlyHasAccessibility = WindowPositionManager.hasAccessibilityPermission()
        hasAccessibilityPermission = currentlyHasAccessibility

        if currentlyHasAccessibility {
            globalPushToTalkShortcutMonitor.start()
        } else {
            globalPushToTalkShortcutMonitor.stop()
        }
        // `start()` above is the first place this process can observe Private Mode entry. Stop
        // this refresh immediately if that tap raised the latch; permission
        // analytics and failure surfaces below are normal-runtime effects.
        guard normalRuntimeAdmissionRemainsOpen else { return }

        hasScreenRecordingPermission = WindowPositionManager.hasScreenRecordingPermission()

        let micAuthStatus = AVCaptureDevice.authorizationStatus(for: .audio)
        hasMicrophonePermission = micAuthStatus == .authorized
        appleSpeechRecognitionReadiness =
            AppleSpeechTranscriptionProvider.currentReadiness

        reconcileLivePermissionReadbacks()

        // Debug: log permission state on changes
        if previouslyHadAccessibility != hasAccessibilityPermission
            || previouslyHadScreenRecording != hasScreenRecordingPermission
            || previouslyHadMicrophone != hasMicrophonePermission
            || previousAppleSpeechRecognitionReadiness != appleSpeechRecognitionReadiness {
            print("🔑 Permissions — accessibility: \(hasAccessibilityPermission), screen: \(hasScreenRecordingPermission), mic: \(hasMicrophonePermission), speech: \(appleSpeechRecognitionReadiness), screenContent: \(hasScreenContentPermission)")
        }

        // Track individual permission grants as they happen
        if !previouslyHadAccessibility && hasAccessibilityPermission {
            BlackLabelAnalytics.trackPermissionGranted(permission: "accessibility")
        }
        if !previouslyHadScreenRecording && hasScreenRecordingPermission {
            BlackLabelAnalytics.trackPermissionGranted(permission: "screen_recording")
        }
        if !previouslyHadMicrophone && hasMicrophonePermission {
            BlackLabelAnalytics.trackPermissionGranted(permission: "microphone")
        }
        if !previouslyHadAll && allPermissionsGranted {
            BlackLabelAnalytics.trackAllPermissionsGranted()
        }

        reportSilentlyBrokenPermissionsToOwner()
    }

    /// Reconciles every shared setup-control coordinator with the live OS
    /// readbacks this refresh just observed. The panel polls the live grants
    /// beyond the bounded Settings repair timeout, and the intro and panel
    /// rows observe these exact shared coordinators — so a late grant replaces
    /// a stale terminal failure with a fresh observable succeeded generation
    /// and its dwell, while a later revoke removes stale green proof before
    /// either surface can render it next to "Needs approval". Only terminal
    /// receipts reconcile; idle and running attempts are never touched.
    private func reconcileLivePermissionReadbacks() {
        WindowPositionManager.accessibilityPermissionRepairCoordinator
            .reconcilePermissionReadback(
                permission: .accessibility,
                isGranted: hasAccessibilityPermission
            )
        WindowPositionManager.screenRecordingPermissionRepairCoordinator
            .reconcilePermissionReadback(
                permission: .screenRecording,
                isGranted: hasScreenRecordingPermission
            )
        SetupControlCoordinatorBank.shared.microphone
            .reconcilePermissionReadback(
                permission: .microphone,
                isGranted: hasMicrophonePermission
            )
        SetupControlCoordinatorBank.shared.speechRecognition
            .reconcilePermissionReadback(
                permission: .speechRecognition,
                isGranted: isOnDeviceDictationReady
            )
    }

    /// Persistent recovery actions run while ordinary permission polling is
    /// intentionally idle. Read macOS on every bounded repair poll instead of
    /// re-reading the cached panel property that caused a working control to
    /// remain stuck on "checking" until timeout.
    private func refreshAccessibilityPermissionRepairReadback() -> Bool {
        let isGranted = WindowPositionManager.hasAccessibilityPermission()
        hasAccessibilityPermission = isGranted
        if isGranted {
            globalPushToTalkShortcutMonitor.start()
        }
        return isGranted
    }

    private func refreshScreenRecordingPermissionRepairReadback() -> Bool {
        let isGranted = WindowPositionManager.hasScreenRecordingPermission()
        hasScreenRecordingPermission = isGranted
        return isGranted
    }

    private func refreshMicrophonePermissionRepairReadback() -> Bool {
        let isGranted = AVCaptureDevice.authorizationStatus(for: .audio)
            == .authorized
        hasMicrophonePermission = isGranted
        return isGranted
    }

    private func refreshSpeechRecognitionPermissionRepairReadback() -> Bool {
        appleSpeechRecognitionReadiness =
            AppleSpeechTranscriptionProvider.currentReadiness
        return isOnDeviceDictationReady
    }

    /// Tells the owner about the two permissions whose absence breaks Ace with no
    /// symptom on screen.
    ///
    /// Every other first-run failure already had a channel — the voice, the ears,
    /// the brain, the hidden status item, the wrong install location all reach
    /// `FirstRunFailureReporter`. These two never did, even though this very
    /// method detects them and shuts the event tap down over them. A denied
    /// Accessibility grant is indistinguishable from a dead app, and a denied
    /// Screen Recording grant is worse than visible breakage: Ace answers
    /// confidently about a screen it cannot see.
    ///
    /// Only after onboarding. During the intro the permissions step is walking
    /// the owner through exactly these grants in context, and an alert on top of
    /// that window would be noise about something they are already doing. This is
    /// the same gate the brainlessness check uses.
    private func reportSilentlyBrokenPermissionsToOwner() {
        guard hasCompletedOnboarding,
              directEffectsAreAllowed,
              !StealthEntryLatch.shared.isRaised else { return }
        let introWindowIsOnScreen = AceIntroWindowController.shared.isVisible

        // FirstRunFailureReporter performs its own visibility and latch
        // admission before presenting an alert. Do not wrap it in
        // performDirectEffectCommit: report() reads the same nonrecursive
        // latch and would self-deadlock while refreshing permissions.
        do {
            if self.hasAccessibilityPermission {
                FirstRunFailureReporter.shared.clear(
                    identifier: FirstRunFailure.accessibilityDenied.id
                )
            } else {
                FirstRunFailureReporter.shared.report(
                    .accessibilityDenied,
                    interrupt: !introWindowIsOnScreen,
                    repairRevision: "accessibility-settings-v1",
                    verifiedRepair: {
                        await WindowPositionManager
                            .openSettingsAndWaitForReadback(
                                .accessibility,
                                permission: .accessibility,
                                readback: {
                                    self.refreshAccessibilityPermissionRepairReadback()
                                }
                            )
                    }
                )
            }

            if self.hasScreenRecordingPermission {
                FirstRunFailureReporter.shared.clear(
                    identifier:
                        FirstRunFailure.screenRecordingDenied.id
                )
            } else {
                FirstRunFailureReporter.shared.report(
                    .screenRecordingDenied,
                    interrupt: !introWindowIsOnScreen,
                    repairRevision: "screen-recording-settings-v1",
                    verifiedRepair: {
                        await WindowPositionManager
                            .openSettingsAndWaitForReadback(
                                .screenRecording,
                                permission: .screenRecording,
                                readback: {
                                    self.refreshScreenRecordingPermissionRepairReadback()
                                }
                            )
                    }
                )
            }

            if self.hasMicrophonePermission {
                FirstRunFailureReporter.shared.clear(
                    identifier: FirstRunFailure.microphoneDenied.id
                )
            } else {
                FirstRunFailureReporter.shared.report(
                    .microphoneDenied,
                    interrupt: !introWindowIsOnScreen,
                    repairRevision: "microphone-settings-v1",
                    verifiedRepair: {
                        await WindowPositionManager
                            .openSettingsAndWaitForReadback(
                                .microphone,
                                permission: .microphone,
                                readback: {
                                    self.refreshMicrophonePermissionRepairReadback()
                                }
                            )
                    }
                )
            }

            let listeningFailureIdentifier =
                "listening.appleSpeechRefused"
            if self.isOnDeviceDictationReady {
                FirstRunFailureReporter.shared.clear(
                    identifier: listeningFailureIdentifier
                )
            } else {
                let failure = FirstRunFailure.listeningUnavailable(
                    providerMessage:
                        self.appleSpeechRecognitionReadiness
                            .unavailableExplanation
                )
                FirstRunFailureReporter.shared.report(
                    failure,
                    interrupt: !introWindowIsOnScreen,
                    repairRevision: "speech-settings-v1",
                    verifiedRepair: {
                        let destination =
                            SFSpeechRecognizer.authorizationStatus()
                                == .authorized
                                ? PermissionSystemSettingsPane.dictation
                                : PermissionSystemSettingsPane.speechRecognition
                        return await WindowPositionManager
                            .openSettingsAndWaitForReadback(
                                destination,
                                permission: .speechRecognition,
                                readback: {
                                    self.refreshSpeechRecognitionPermissionRepairReadback()
                                }
                            )
                    }
                )
            }
        }
    }

    /// Performs one harmless, low-resolution SCK capture. The resulting proof is
    /// process-scoped: every launch starts false and must produce a fresh image.
    /// Callers that want a no-surprise launch recheck first gate this on
    /// `CGPreflightScreenCaptureAccess()`.
    @Published private(set) var isRequestingScreenContent = false {
        didSet { refreshInstallReadinessSetupAuth() }
    }
    @Published private(set) var screenContentRepairProof:
        PermissionRepairProof?
    private var screenContentPermissionTask: Task<Void, Never>?
    private var screenContentPermissionGeneration = UUID()

    @discardableResult
    func requestScreenContentPermission() -> AceControlActionOutcome {
        if hasScreenContentPermission {
            let outcome = AceControlActionOutcome.succeeded(
                AceActionSuccess(
                    message: "Screen Content access is ready."
                )
            )
            screenContentControlOutcome = outcome
            return outcome
        }
        if isRequestingScreenContent {
            let outcome = AceControlActionOutcome.started(
                message: "Checking Screen Content access…"
            )
            screenContentControlOutcome = outcome
            return outcome
        }
        guard !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            let outcome = AceControlActionOutcome.failed(
                AceActionFailure(
                    code: "screen_content.private_mode",
                    message:
                        "Exit Private Mode before checking Screen Content access.",
                    recoveryTitle: "Exit Private Mode and try again",
                    recovery: .retry
                )
            )
            screenContentControlOutcome = outcome
            return outcome
        }
        // Never use SCK itself to create a surprise prompt. If Screen Recording
        // became authorized after this process started, relaunch the exact
        // canonical bundle first; only the new process may earn capture proof.
        guard CGPreflightScreenCaptureAccess() else {
            let outcome = AceControlActionOutcome.failed(
                AceActionFailure(
                    code: "screen_content.screen_recording_required",
                    message:
                        "Allow Screen Recording for Ace first, then check Screen Content again.",
                    recoveryTitle: "Open Screen Recording Settings",
                    recovery: .openSystemSettings(
                        PermissionSystemSettingsPane.screenRecording.deepLink
                            .absoluteString
                    )
                )
            )
            screenContentControlOutcome = outcome
            publishFinishSetupOwnerFacingStatus(outcome.visibleMessage)
            return outcome
        }
        guard screenRecordingWasAuthorizedAtProcessLaunch else {
            relaunchForFreshScreenContentProof()
            let outcome = AceControlActionOutcome.started(
                message:
                    "Reopening Ace so the new Screen Recording grant can take effect…"
            )
            screenContentControlOutcome = outcome
            return outcome
        }
        let generation = UUID()
        let taskCutoff = DirectEffectTaskCutoff()
        let cutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                taskCutoff.cancelSynchronously()
            }
        let admitted =
            StealthEntryLatch.shared.performUnlessRaised { [weak self] in
                guard let self,
                      self.directEffectsAreAllowed else {
                    return false
                }
                self.screenContentPermissionGeneration = generation
                self.hasScreenContentPermission = false
                self.screenContentRepairProof = nil
                self.isRequestingScreenContent = true
                self.screenContentControlOutcome = .started(
                    message: "Checking Screen Content access…"
                )

                let task = Task { @MainActor [weak self] in
                    defer {
                        taskCutoff.clear()
                        StealthEntryLatch.shared
                            .unregisterSynchronousEntryCutoff(
                                cutoffIdentifier
                            )
                        if let self,
                           self.screenContentPermissionGeneration
                            == generation {
                            self.isRequestingScreenContent = false
                            self.screenContentPermissionTask = nil
                        }
                    }
                    guard let self else { return }
                    do {
                        guard !Task.isCancelled,
                              !taskCutoff.isCancelled,
                              !StealthEntryLatch.shared.isRaised,
                              self.directEffectsAreAllowed else {
                            return
                        }
                        let captureDeadlineUptime =
                            ScreenCaptureOperationBoundary
                                .deadlineUptime()
                        let image: CGImage
                        if #available(macOS 26.0, *) {
                            let mouseLocation = NSEvent.mouseLocation
                            let displays =
                                PrivateModePolicy.currentDisplayTopology()
                            guard let display = displays.first(where: {
                                $0.appKitFrame.contains(mouseLocation)
                            }) ?? displays.first else {
                                self.publishScreenContentFailure(
                                    code: "screen_content.no_display",
                                    message:
                                        "Ace could not find a display to verify Screen Content access.",
                                    generation: generation
                                )
                                return
                            }
                            image = try await self
                                .screenContentDirectProofImage(
                                    displayID:
                                        display.displayIdentifier,
                                    rect: display.coreGraphicsFrame,
                                    cutoff: taskCutoff,
                                    deadlineUptime:
                                        captureDeadlineUptime
                                )
                        } else {
                            let content =
                                try await self
                                    .screenContentShareableContent(
                                        cutoff: taskCutoff,
                                        deadlineUptime:
                                            captureDeadlineUptime
                                    )
                            guard !Task.isCancelled,
                                  !taskCutoff.isCancelled,
                                  !StealthEntryLatch.shared.isRaised,
                                  self.directEffectsAreAllowed,
                                  self.screenContentPermissionGeneration
                                    == generation else {
                                return
                            }
                            guard let display = content.displays.first else {
                                self.publishScreenContentFailure(
                                    code: "screen_content.no_display",
                                    message:
                                        "Ace could not find a display to verify Screen Content access.",
                                    generation: generation
                                )
                                return
                            }
                            let filter = SCContentFilter(
                                display: display,
                                excludingWindows: []
                            )
                            let config = SCStreamConfiguration()
                            config.width = 320
                            config.height = 240
                            image = try await self.screenContentProofImage(
                                contentFilter: filter,
                                configuration: config,
                                cutoff: taskCutoff,
                                deadlineUptime:
                                    captureDeadlineUptime
                            )
                        }
                        guard !Task.isCancelled,
                              !taskCutoff.isCancelled,
                              !StealthEntryLatch.shared.isRaised,
                              self.directEffectsAreAllowed,
                              self.screenContentPermissionGeneration
                                == generation else {
                            return
                        }
                        guard image.width > 0, image.height > 0 else {
                            self.publishScreenContentFailure(
                                code: "screen_content.empty_proof",
                                message:
                                    "Ace received an empty Screen Content proof.",
                                generation: generation
                            )
                            return
                        }

                        let commit =
                            DirectEffectCommitAdmission.commit(
                                visibilityIsBlocked: {
                                    [weak self] in
                                    guard let self else {
                                        return true
                                    }
                                    return Task.isCancelled
                                        || taskCutoff.isCancelled
                                        || self
                                            .screenContentPermissionGeneration
                                            != generation
                                        || !self.directEffectsAreAllowed
                                },
                                performUnlessRaised: { body in
                                    StealthEntryLatch.shared
                                        .performUnlessRaised(body)
                                },
                                effect: { [weak self] in
                                    guard let self else { return false }
                                    self.hasScreenContentPermission = true
                                    self.screenContentRepairProof = .screenCapture(
                                        width: image.width,
                                        height: image.height
                                    )
                                    BlackLabelAnalytics
                                        .trackPermissionGranted(
                                            permission: "screen_content"
                                        )
                                    return true
                                }
                            )
                        guard case .committed(true) = commit else {
                            self.publishScreenContentFailure(
                                code: "screen_content.commit_blocked",
                                message:
                                    "Ace could not finish the Screen Content check.",
                                generation: generation
                            )
                            return
                        }
                        let success = AceControlActionOutcome.succeeded(
                            AceActionSuccess(
                                message: "Screen Content access is ready."
                            )
                        )
                        self.screenContentControlOutcome = success
                        self.clearFinishSetupOwnerFacingStatus()
                        self.appendRouteReceipt(
                            "SCREEN-CONTENT control succeeded"
                        )
                        if AssistantAvailabilityPolicy
                            .shouldShowPersistentGem(
                                hasCompletedOnboarding:
                                    self.hasCompletedOnboarding,
                                cursorEnabled:
                                    self.isBlackLabelCursorEnabled,
                                stealthVisibilityBlocked:
                                    StealthVisibilityGate.shared.isActive
                                        || StealthEntryLatch.shared.isRaised,
                                coreInteractionPermissionsReady:
                                    self.hasAccessibilityPermission
                                        && self
                                            .hasScreenRecordingPermission
                                        && self.hasMicrophonePermission
                                        && self
                                            .hasScreenContentPermission,
                                appAutomationReady:
                                    self.permissionWarmup
                                        .hasProvenAppAutomation
                            )
                            && !self.isOverlayVisible {
                            self.overlayWindowManager
                                .hasShownOverlayBefore = true
                            self.isOverlayVisible =
                                self.overlayWindowManager
                                    .showOverlay(
                                        onScreens: NSScreen.screens,
                                        companionManager: self
                                    )
                        }
                    } catch {
                        guard !taskCutoff.isCancelled,
                              !StealthEntryLatch.shared.isRaised,
                              self.directEffectsAreAllowed else {
                            return
                        }
                        let captureError = error as NSError
                        self.appendRouteReceipt(
                            "SCREEN-CONTENT proof error domain="
                                + captureError.domain
                                + " code=\(captureError.code) detail="
                                + error.localizedDescription
                        )
                        self.publishScreenContentFailure(
                            code: "screen_content.proof_failed",
                            message:
                                "Ace could not verify Screen Content access: "
                                    + error.localizedDescription,
                            generation: generation
                        )
                    }
                }
                guard taskCutoff.register(task) else {
                    task.cancel()
                    self.isRequestingScreenContent = false
                    return false
                }
                self.screenContentPermissionTask = task
                return true
            }
        guard admitted == true else {
            taskCutoff.clear()
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier
            )
            let outcome = AceControlActionOutcome.failed(
                AceActionFailure(
                    code: "screen_content.admission_blocked",
                    message:
                        "Ace could not start the Screen Content check.",
                    recoveryTitle: "Try again",
                    recovery: .retry
                )
            )
            screenContentControlOutcome = outcome
            return outcome
        }
        let outcome = AceControlActionOutcome.started(
            message: "Checking Screen Content access…"
        )
        screenContentControlOutcome = outcome
        return outcome
    }

    private func publishScreenContentFailure(
        code: String,
        message: String,
        generation: UUID
    ) {
        guard screenContentPermissionGeneration == generation else {
            return
        }
        let failure = AceActionFailure(
            code: code,
            message: message,
            recoveryTitle: "Try Screen Content again",
            recovery: .retry
        )
        screenContentControlOutcome = .failed(failure)
        screenContentRepairProof = nil
        publishFinishSetupOwnerFacingStatus(message)
        appendRouteReceipt(
            "SCREEN-CONTENT control failed code=\(code)"
        )
        if directEffectsAreAllowed,
           !StealthEntryLatch.shared.isRaised {
            showVisibleResponse(message)
        }
    }

    @available(macOS 26.0, *)
    private func screenContentDirectProofImage(
        displayID: CGDirectDisplayID,
        rect: CGRect,
        cutoff: DirectEffectTaskCutoff,
        deadlineUptime: TimeInterval
    ) async throws -> CGImage {
        if let image = ScreenCaptureImageProvider
            .captureDisplayImageImmediately(
                displayID: displayID,
                width: 320,
                height: 240
            ) {
            appendRouteReceipt(
                "SCREEN-CONTENT proof route=core-graphics-display"
            )
            return image
        }
        return try await withCheckedThrowingContinuation {
            (continuation: CheckedContinuation<CGImage, Error>) in
            let boundary = BoundedScreenCaptureContinuation(continuation)
            boundary.armTimeout(
                stage: "permission direct image",
                after: ScreenCaptureOperationBoundary.remainingSeconds(
                    untilUptime: deadlineUptime
                )
            )
            let didInvoke = cutoff.invokeIfCurrent(
                performUnlessRaised: { body in
                    StealthEntryLatch.shared
                        .performUnlessRaised(body)
                }
            ) {
                ScreenCaptureImageProvider.captureSystemScreenshot(
                    rect: rect,
                    width: 320,
                    height: 240,
                    timeoutSeconds:
                        ScreenCaptureOperationBoundary.remainingSeconds(
                            untilUptime: deadlineUptime
                        )
                ) { image, error in
                    if let error {
                        boundary.resolve(.failure(error))
                    } else if let image {
                        Task { @MainActor [weak self] in
                            self?.appendRouteReceipt(
                                "SCREEN-CONTENT proof route=system-screencapture"
                            )
                        }
                        boundary.resolve(.success(image))
                    } else {
                        boundary.resolve(
                            .failure(
                                NSError(
                                    domain: "ScreenCaptureImageProvider",
                                    code: -1,
                                    userInfo: [
                                        NSLocalizedDescriptionKey:
                                            "ScreenCaptureKit returned no image."
                                    ]
                                )
                            )
                        )
                    }
                }
            }
            if !didInvoke {
                boundary.resolve(.failure(CancellationError()))
            }
        }
    }

    private func screenContentShareableContent(
        cutoff: DirectEffectTaskCutoff,
        deadlineUptime: TimeInterval
    ) async throws -> SCShareableContent {
        try await withCheckedThrowingContinuation {
            (continuation:
                CheckedContinuation<SCShareableContent, Error>) in
            let boundary = BoundedScreenCaptureContinuation(continuation)
            boundary.armTimeout(
                stage: "permission discovery",
                after: ScreenCaptureOperationBoundary.remainingSeconds(
                    untilUptime: deadlineUptime
                )
            )
            let didInvoke = cutoff.invokeIfCurrent(
                performUnlessRaised: { body in
                    StealthEntryLatch.shared
                        .performUnlessRaised(body)
                }
            ) {
                SCShareableContent.getExcludingDesktopWindows(
                    false,
                    onScreenWindowsOnly: true
                ) { content, error in
                    if let error {
                        boundary.resolve(.failure(error))
                    } else if let content {
                        boundary.resolve(.success(content))
                    } else {
                        boundary.resolve(.failure(CancellationError()))
                    }
                }
            }
            if !didInvoke {
                boundary.resolve(.failure(CancellationError()))
            }
        }
    }

    private func screenContentProofImage(
        contentFilter: SCContentFilter,
        configuration: SCStreamConfiguration,
        cutoff: DirectEffectTaskCutoff,
        deadlineUptime: TimeInterval
    ) async throws -> CGImage {
        try await withCheckedThrowingContinuation {
            (continuation: CheckedContinuation<CGImage, Error>) in
            let boundary = BoundedScreenCaptureContinuation(continuation)
            boundary.armTimeout(
                stage: "permission image",
                after: ScreenCaptureOperationBoundary.remainingSeconds(
                    untilUptime: deadlineUptime
                )
            )
            let didInvoke = cutoff.invokeIfCurrent(
                performUnlessRaised: { body in
                    StealthEntryLatch.shared
                        .performUnlessRaised(body)
                }
            ) {
                ScreenCaptureImageProvider.captureImage(
                    contentFilter: contentFilter,
                    configuration: configuration
                ) { image, error in
                    if let error {
                        boundary.resolve(.failure(error))
                    } else if let image {
                        boundary.resolve(.success(image))
                    } else {
                        boundary.resolve(.failure(CancellationError()))
                    }
                }
            }
            if !didInvoke {
                boundary.resolve(.failure(CancellationError()))
            }
        }
    }

    func failCurrentScreenContentProofRequest() {
        guard isRequestingScreenContent else { return }
        screenContentPermissionGeneration = UUID()
        screenContentPermissionTask?.cancel()
        screenContentPermissionTask = nil
        isRequestingScreenContent = false
        hasScreenContentPermission = false
        LifecycleLog.append(
            "SCREEN-CONTENT proof invalidated before completion"
        )
    }

    // MARK: - Private

    /// Triggers the system microphone prompt if the user has never been asked.
    /// Once granted/denied the status sticks and polling picks it up.
    private func promptForMicrophoneIfNotDetermined() {
        guard AceLicense.shared.admits(.permissionRepair) else { return }
        guard AVCaptureDevice.authorizationStatus(for: .audio) == .notDetermined else { return }
        startPermissionPolling(explicitPromptIsPending: true)
        AVCaptureDevice.requestAccess(for: .audio) { [weak self] granted in
            Task { @MainActor [weak self] in
                self?.hasMicrophonePermission = granted
                self?.finishExplicitPermissionPromptPolling()
            }
        }
    }

    /// Nonblocking setup action. The existing permission poll updates
    /// `appleSpeechRecognitionReadiness` after the system sheet resolves and
    /// continues watching while macOS downloads the on-device model.
    func requestSpeechRecognitionAuthorizationIfNeeded() {
        guard AceLicense.shared.admits(.permissionRepair) else { return }
        startPermissionPolling(explicitPromptIsPending: true)
        Task { @MainActor [weak self] in
            guard AceLicense.shared.admits(.permissionRepair) else { return }
            _ = await AppleSpeechTranscriptionProvider.requestAuthorizationIfNeeded()
            guard AceLicense.shared.admits(.permissionRepair) else { return }
            self?.finishExplicitPermissionPromptPolling()
        }
    }

    /// Panel opening, activation and wake refresh stable permission state.
    /// The 1.5-second observer exists
    /// only while Ace itself owns an unresolved macOS permission prompt.
    private func startPermissionPolling(
        explicitPromptIsPending: Bool = false
    ) {
        accessibilityCheckTimer?.invalidate()
        accessibilityCheckTimer = nil
        explicitPermissionPromptIsPending = explicitPromptIsPending
        let mode = PermissionRefreshPolicy.mode(
            runtimeIsActive:
                AceLicense.shared.admits(.permissionRepair)
                    && !premiumRuntimeIsQuiescedForEntitlement,
            explicitPromptIsPending: explicitPermissionPromptIsPending
        )
        switch mode {
        case .stopped:
            return
        case .stable:
            // Startup calls this while its nonrecursive admission commit is
            // still held. Defer the one stable sample until that commit has
            // returned; a synchronous refresh re-enters the event-tap/Stealth
            // boundary and deadlocks before the menu item can appear.
            DispatchQueue.main.async { [weak self] in
                guard let self,
                      AceLicense.shared.admits(.permissionRepair),
                      !self.premiumRuntimeIsQuiescedForEntitlement else {
                    return
                }
                self.refreshAllPermissions()
            }
        case .pending(let interval):
            accessibilityCheckTimer = Timer.scheduledTimer(
                withTimeInterval: interval,
                repeats: true
            ) { [weak self] _ in
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    guard self.explicitPermissionPromptIsPending else {
                        self.finishExplicitPermissionPromptPolling()
                        return
                    }
                    self.refreshAllPermissions()
                }
            }
        }
    }

    private func finishExplicitPermissionPromptPolling() {
        explicitPermissionPromptIsPending = false
        accessibilityCheckTimer?.invalidate()
        accessibilityCheckTimer = nil
        if AceLicense.shared.admits(.permissionRepair),
           !premiumRuntimeIsQuiescedForEntitlement {
            refreshAllPermissions()
        }
    }

    private func stopPermissionPolling() {
        explicitPermissionPromptIsPending = false
        accessibilityCheckTimer?.invalidate()
        accessibilityCheckTimer = nil
    }

    private func bindAudioPowerLevel() {
        buddyDictationManager.onAudioReplayScrubBoundary = {
            [weak self] boundary in
            guard let self else { return }
            switch boundary {
            case .cancellation:
                self.finishWaveformTurn(reason: .cancelled)
            case .failure:
                self.finishWaveformTurn(reason: .failed)
            case .stop:
                self.finishWaveformTurn(reason: .stop)
            case .providerSwitch:
                self.finishWaveformTurn(reason: .providerSwitch)
            case .privateMode:
                self.finishWaveformTurn(reason: .privateMode)
            case .timeout:
                self.finishWaveformTurn(reason: .timeout)
            case .wrongTurn:
                self.finishWaveformTurn(reason: .turnReplacement)
            case .success, .replayCompletion, .deinitialization:
                break
            }
        }
        audioPowerCancellable = buddyDictationManager.$currentAudioPowerLevel
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] powerLevel in
                self?.currentAudioPowerLevel = powerLevel
            }
        SpeechProviderSwitchBoundary.handler = { [weak self] in
            self?.buddyDictationManager
                .cancelCurrentDictationForProviderSwitch()
        }
    }

    private func beginWaveformTurn(
        turnID: UUID,
        source: WaveformObservationSource
    ) {
        finishWaveformTurn(reason: .turnReplacement)
        waveformObservationSource = source
        waveformShortcutState = source == .commandShift
            ? .pressed : .inactive
        waveformNonzeroSampleCount = 0
        waveformLifecyclePublisher.begin(
            turnID: turnID,
            source: source,
            initialObservation: makeWaveformStateObservation()
        )
    }

    private func observeWaveformState() {
        guard let turnID = waveformLifecyclePublisher.activeTurnID else {
            return
        }
        waveformLifecyclePublisher.observe(
            turnID: turnID,
            observation: makeWaveformStateObservation()
        )
    }

    private func makeWaveformStateObservation()
        -> WaveformStateObservation {
        let recordingState: WaveformRecordingState
        if buddyDictationManager.isFinalizingTranscript {
            recordingState = .finalizing
        } else if buddyDictationManager.isPreparingToRecord {
            recordingState = .preparing
        } else if buddyDictationManager.isActivelyRecordingAudio {
            recordingState = .recording
        } else {
            recordingState = .idle
        }
        let voicePhase: WaveformVoicePhase
        switch voiceState {
        case .idle: voicePhase = .idle
        case .listening: voicePhase = .listening
        case .processing: voicePhase = .processing
        case .responding: voicePhase = .responding
        }
        let displayDescriptors = NSScreen.screens.map { screen in
            WaveformDisplayDescriptor(
                x: screen.frame.origin.x,
                y: screen.frame.origin.y,
                width: screen.frame.width,
                height: screen.frame.height,
                scale: screen.backingScaleFactor
            )
        }
        return WaveformStateObservation(
            source: waveformObservationSource,
            shortcutState: waveformShortcutState,
            recordingState: recordingState,
            voicePhase: voicePhase,
            overlayVisibility:
                overlayWindowManager.liveWaveformVisibility(),
            displayHash: WaveformDisplayFingerprint.make(
                from: displayDescriptors
            ),
            partnerMode: partnerModeIsActive,
            privateMode: stealthMode.isActive
                || stealthActive
                || StealthVisibilityGate.shared.isActive,
            reducedMotion:
                NSWorkspace.shared
                    .accessibilityDisplayShouldReduceMotion,
            nonzeroWaveformSampleCount:
                waveformNonzeroSampleCount
        )
    }

    private func finishWaveformTurn(
        reason: WaveformTerminalReason
    ) {
        guard let turnID = waveformLifecyclePublisher.activeTurnID else {
            return
        }
        observeWaveformState()
        waveformLifecyclePublisher.finish(turnID: turnID, reason: reason)
        waveformShortcutState = .inactive
        waveformNonzeroSampleCount = 0
    }

    private func speechContextualCaptureContext()
        -> SpeechContextualCaptureContext {
        let ownerApprovedName =
            partnerModeController?.profile.userDisplayName

        let backend: SpeechContextualBackendSelection
        switch BrainBackend.selectedCLI {
        case .codex:
            let resolvedModelLabel =
                BrainBackend.resolveCodexExecutable().flatMap {
                    executablePath in
                    BrainBackend.codexAuthFilePath.flatMap { authFilePath in
                        CodexModelCapabilityCache.shared
                            .modelForCurrentCapability(
                                executablePath: executablePath,
                                authFilePath: authFilePath
                            )
                    }
                }
            backend = .codex(resolvedModelLabel: resolvedModelLabel)
        case .claude:
            backend = .claude(currentModelLabel: selectedModel)
        case .qwen:
            backend = .qwen(modelLabel: AceLocalBrain.modelTag)
        }

        let pendingLocalSlot: SpeechContextualPendingLocalSlot?
        if appleMailSenderSelection != nil {
            pendingLocalSlot = .mailSender
        } else if appleMessagesRecipientSelection != nil {
            // Only the content-free slot label is admitted. Recipient handles
            // remain outside the Speech vocabulary.
            pendingLocalSlot = .messageRecipient
        } else if lastLocatedTargetName != nil {
            pendingLocalSlot = .actionTarget
        } else {
            pendingLocalSlot = nil
        }

        var visibleApplications: [String] = []
        for applicationName in NSWorkspace.shared.runningApplications
        where applicationName.activationPolicy == .regular
            && !applicationName.isHidden
            && !applicationName.isTerminated {
            guard let name = applicationName.localizedName else { continue }
            visibleApplications.append(name)
        }
        return SpeechContextualCaptureContext(
            ownerApprovedName: ownerApprovedName,
            backend: backend,
            scope: .owner,
            pendingLocalSlot: pendingLocalSlot,
            visibleApplications: visibleApplications
        )
    }

    /// Every built-in host proof that needs Nora truth publishes one correlated
    /// request. This includes first launch and activation refreshes of the
    /// already-proven platform-host path.
    private func bindPlatformHostVoiceWarmup() {
        platformHostVoiceWarmupCancellable =
            VoiceReadiness.shared.$daemonVerdictRequest
            .compactMap { $0 }
            .removeDuplicates()
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] request in
                self?.noraVoice.beginReadinessVerdict(request)
            }
    }

    private func bindVoiceStateObservation() {
        voiceStateCancellable = buddyDictationManager.$isRecordingFromKeyboardShortcut
            .combineLatest(
                buddyDictationManager.$isFinalizingTranscript,
                buddyDictationManager.$isPreparingToRecord,
                buddyDictationManager
                    .$isRecordingAutomaticPartnerTurn
            )
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink {
                [weak self]
                isRecording,
                isFinalizing,
                isPreparing,
                isRecordingAutomaticPartnerTurn in
                guard let self else { return }
                self.refreshInstallReadinessVoiceState()
                let observedVoiceState = Self
                    .voiceStateForDictationActivity(
                        isRecordingFromKeyboardShortcut:
                            isRecording,
                        isRecordingAutomaticPartnerTurn:
                            isRecordingAutomaticPartnerTurn,
                        isFinalizingTranscript:
                            isFinalizing,
                        isPreparingToRecord:
                            isPreparing
                    )
                // An idle dictation observation must not erase a response that
                // is genuinely still running. Every active microphone state is
                // different: Command-Shift is a barge-in and must immediately
                // replace stale `.responding` presentation with the listening
                // waveform (or processing while the recognizer starts/finishes).
                if self.voiceState == .responding,
                   observedVoiceState == .idle {
                    return
                }
                if InteractiveActionProgressPolicy.shouldHoldProcessing(
                    dictationIsIdle: observedVoiceState == .idle,
                    actionIsRunning: self.appActionPlanningTask != nil
                ) {
                    self.voiceState = .processing
                    return
                }
                self.voiceState = observedVoiceState
                if self.voiceState == .idle {
                    // If the user pressed and released the hotkey without
                    // saying anything, no response task runs — schedule the
                    // transient hide here so the overlay doesn't get stuck.
                    // Only do this when no response is in flight, otherwise
                    // the brief idle gap between recording and processing
                    // would prematurely hide the overlay.
                    if self.currentResponseTask == nil {
                        self.scheduleTransientHideIfNeeded()
                    }
                }
            }
    }

    /// One app-owned state projection for the live installer. The projection
    /// contains only activity names; owner text, notes, transcripts, provider
    /// output, and targets never cross this boundary.
    private func bindInstallReadinessState() {
        installReadinessCancellables.removeAll()

        let pendingNotesReviewPublisher = Publishers.CombineLatest(
            meetingNotetaker.$hasPendingGeneratedNotesReview,
            meetingNotetaker.$hasPendingMeetingNotesRetry
        )
        .map { hasGeneratedReview, hasRawRetry in
            hasGeneratedReview || hasRawRetry
        }
        let notesFinalizationPublisher = Publishers.CombineLatest(
            meetingNotetaker.$isWindingDown,
            meetingNotetaker.$isRetryingMeetingNotes
        )
        .map { isWindingDown, isRetrying in
            isWindingDown || isRetrying
        }

        meetingNotetaker.$isStartingUp
            .combineLatest(
                meetingNotetaker.$isTakingNotes,
                notesFinalizationPublisher,
                pendingNotesReviewPublisher
            )
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self]
                isStartingUp,
                isTakingNotes,
                isFinalizing,
                hasPendingReview in
                let readiness = InstallReadinessCoordinator.shared
                readiness.set(.notesStartup, active: isStartingUp)
                readiness.set(.notesCapture, active: isTakingNotes)
                readiness.set(.notesFinalization, active: isFinalizing)
                readiness.set(.notesReview, active: hasPendingReview)
                self?.refreshInstallReadinessPendingDecision()
            }
            .store(in: &installReadinessCancellables)

        workflowRuntime.$isBuilding
            .combineLatest(workflowRuntime.$isPlanning)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { isBuilding, isPlanning in
                InstallReadinessCoordinator.shared.set(
                    .workflowBuild,
                    active: isBuilding || isPlanning
                )
            }
            .store(in: &installReadinessCancellables)

        backgroundAgent.$isWorking
            .combineLatest(silverBackgroundAgent.$isWorking)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] _, _ in
                self?.refreshInstallReadinessBackgroundWork()
            }
            .store(in: &installReadinessCancellables)

        let dictationChanges: [AnyPublisher<Void, Never>] = [
            buddyDictationManager.$isPreparingToRecord
                .map { _ in () }.eraseToAnyPublisher(),
            buddyDictationManager.$isRecordingFromMicrophoneButton
                .map { _ in () }.eraseToAnyPublisher(),
            buddyDictationManager.$isRecordingFromKeyboardShortcut
                .map { _ in () }.eraseToAnyPublisher(),
            buddyDictationManager.$isRecordingAutomaticPartnerTurn
                .map { _ in () }.eraseToAnyPublisher(),
            buddyDictationManager.$isFinalizingTranscript
                .map { _ in () }.eraseToAnyPublisher(),
        ]
        Publishers.MergeMany(dictationChanges)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] in
                self?.refreshInstallReadinessVoiceState()
            }
            .store(in: &installReadinessCancellables)

        bindInstallReadinessPartnerState()
        refreshInstallReadinessSnapshot()
    }

    private func bindInstallReadinessPartnerState() {
        installReadinessPartnerObservation?.cancel()
        guard let partnerModeController else {
            InstallReadinessCoordinator.shared.set(
                .partnerSession,
                active: false
            )
            return
        }
        installReadinessPartnerObservation = partnerModeController.$phase
            .combineLatest(partnerModeController.$userActivatedSession)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { phase, userActivatedSession in
                InstallReadinessCoordinator.shared.set(
                    .partnerSession,
                    active: userActivatedSession || phase != .inactive
                )
            }
    }

    private func refreshInstallReadinessOwnerWork() {
        InstallReadinessCoordinator.shared.set(
            .ownerWork,
            active: currentResponseTask != nil
                || appActionPlanningTask != nil
                || aceHQDispatchTask != nil
                || morningBriefTask != nil
                || emailReadTask != nil
                || testEmailTask != nil
        )
    }

    private func refreshInstallReadinessBackgroundWork() {
        InstallReadinessCoordinator.shared.set(
            .backgroundWork,
            active: backgroundTaskActive
                || backgroundAgent.isWorking
                || silverBackgroundAgent.isWorking
        )
    }

    private func refreshInstallReadinessVoiceState() {
        InstallReadinessCoordinator.shared.set(
            .voiceCapture,
            active: buddyDictationManager.isDictationInProgress
                || voiceState == .listening
                || voiceState == .processing
        )
        if voiceState == .responding {
            InstallReadinessCoordinator.shared.set(
                .voicePlayback,
                active: true
            )
        }
        // Nora's content-free playback callback is the only owner of the
        // terminal false edge. Do not synchronously query `noraVoice.isPlaying`
        // here: voiceState may change inside StealthEntryLatch's terminal
        // publication admission, and Nora's getter consults that same
        // non-recursive privacy latch. The old query deadlocked the MainActor
        // and daemon-receipt reader after a valid Partner response.
    }

    private func refreshInstallReadinessPrivateModeTransition() {
        InstallReadinessCoordinator.shared.set(
            .privateModeEntry,
            active: stealthEntryTransitionInProgress
                || stealthExitTransitionInProgress
        )
    }

    private func refreshInstallReadinessSetupAuth() {
        InstallReadinessCoordinator.shared.set(
            .setupAuth,
            active: explicitPermissionPromptIsPending
                || isRequestingScreenContent
                || permissionWarmupTask != nil
                || firstRunTourTask != nil
                || firstRunCompletionProofTask != nil
                || startFromPanelTask != nil
        )
    }

    private func refreshInstallReadinessPendingDecision() {
        InstallReadinessCoordinator.shared.set(
            .pendingUserDecision,
            active: appActionReview != nil
                || pendingGoldClarification != nil
                || pendingMemoryWipeConfirmation != nil
                || pendingAgentCapabilityConsent != nil
                || pendingAceHQCapabilityRequest != nil
                || pendingAceHQConfirmation != nil
                || pendingAceHQExecutionConfirmation != nil
                || appleMailSenderSelection != nil
                || appleMessagesRecipientSelection != nil
                || meetingNotetaker.hasPendingGeneratedNotesReview
                || meetingNotetaker.hasPendingMeetingNotesRetry
                || workflowRuntime.hasPendingPlan
        )
    }

    /// Refreshes every direct owner immediately before the app answers a
    /// readiness challenge. Continuous subscriptions preserve generations;
    /// this final projection closes any publisher-delivery gap.
    func refreshInstallReadinessSnapshot() {
        refreshInstallReadinessOwnerWork()
        refreshInstallReadinessBackgroundWork()
        refreshInstallReadinessVoiceState()
        refreshInstallReadinessPrivateModeTransition()
        refreshInstallReadinessSetupAuth()
        refreshInstallReadinessPendingDecision()
        let readiness = InstallReadinessCoordinator.shared
        readiness.set(
            .workflowBuild,
            active: workflowRuntime.isBuilding
                || workflowRuntime.isPlanning
        )
        readiness.set(
            .notesStartup,
            active: meetingNotetaker.isStartingUp
        )
        readiness.set(
            .notesCapture,
            active: meetingNotetaker.isTakingNotes
        )
        readiness.set(
            .notesFinalization,
            active: meetingNotetaker.isWindingDown
                || meetingNotetaker.isRetryingMeetingNotes
        )
        readiness.set(
            .notesReview,
            active: meetingNotetaker.hasPendingGeneratedNotesReview
                || meetingNotetaker.hasPendingMeetingNotesRetry
        )
        readiness.set(
            .privateModeAnswer,
            active: stealthAnswerTask != nil
        )
        readiness.set(
            .partnerSession,
            active: partnerModeController?.userActivatedSession == true
                || (partnerModeController?.phase ?? .inactive) != .inactive
        )
        readiness.set(
            .voicePlayback,
            active: noraVoice.isPlaying || voiceState == .responding
        )
        readiness.set(
            .visiblePanel,
            active: MenuBarPanelManager.shared?.panelIsVisible == true
        )
    }

    static func voiceStateForDictationActivity(
        isRecordingFromKeyboardShortcut: Bool,
        isRecordingAutomaticPartnerTurn: Bool,
        isFinalizingTranscript: Bool,
        isPreparingToRecord: Bool
    ) -> CompanionVoiceState {
        if isFinalizingTranscript || isPreparingToRecord {
            return .processing
        }
        if isRecordingFromKeyboardShortcut
            || isRecordingAutomaticPartnerTurn {
            return .listening
        }
        return .idle
    }

    private func bindShortcutTransitions() {
        shortcutReadinessCancellable = globalPushToTalkShortcutMonitor.objectWillChange
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] _ in self?.objectWillChange.send() }
        shortcutTransitionCancellable = globalPushToTalkShortcutMonitor
            .shortcutTransitionPublisher
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] transition in
                self?.handleShortcutTransition(transition)
            }
    }

    private func handleShortcutTransition(_ transition: BuddyPushToTalkShortcut.ShortcutTransition) {
        switch transition {
        case .pressed:
            // Stealth keeps passive listening and normal dictation closed. A
            // deliberate normal PTT hold may open one separate Apple-on-device
            // session whose only terminal action is an exact local exit match.
            if stealthMode.isActive {
                pendingKeyboardShortcutStartTask?.cancel()
                pendingKeyboardShortcutStartTask = nil
                let started = stealthExitOnlyCapture.beginPushToTalk {
                    [weak self] completion in
                    guard let self else { return }
                    self.appendRouteReceipt(
                        "STEALTH exit-only PTT "
                            + completion.contentFreeReceipt
                    )
                    if completion == .exit {
                        self.exitStealthMode()
                    }
                }
                appendRouteReceipt(
                    started
                        ? "STEALTH exit-only PTT started mode=apple-on-device"
                        : "STEALTH exit-only PTT rejected before capture"
                )
                return
            }
            guard AceLicense.shared.admits(.normalVoice),
                  directEffectsAreAllowed else { return }

            dismissDictationFailure()

            // A physical hold must take over an automatic Partner window;
            // otherwise the busy guard drops the press and its release cannot
            // stop the Partner-owned capture (up to its 90-second cap).
            partnerListeningStartTask?.cancel()
            partnerListeningStartTask = nil
            if buddyDictationManager
                .yieldAutomaticPartnerTurnForKeyboardShortcut() {
                appendRouteReceipt(
                    "PARTNER automatic capture yielded to keyboard hold"
                )
            }

            // A re-press during the previous session's FINALIZE window would be
            // dropped by the isDictationInProgress guard, and since modifier
            // flagsChanged only fires on transitions no further press arrives —
            // the user speaks into a dead mic. Finish the merely-finalizing prior
            // session now (its transcript is submitted, its recognition task torn
            // down) so this press can start fresh; if it's actively recording or
            // preparing, still ignore the press.
            if buddyDictationManager.isDictationInProgress {
                guard buddyDictationManager.finishFinalizingSessionForRestart() else { return }
            }
            // Don't register push-to-talk while the onboarding video is playing
            guard !showOnboardingVideo else { return }

            // While a meeting is being transcribed, push-to-talk must own the
            // single on-device recognition slot for its hold — pause the
            // notetaker's task so the two don't kill each other's recognition
            // (dropping both the meeting words and this command). Resumed on
            // release. The notetaker's mixer keeps buffering during the hold.
            if meetingNotetaker.isTakingNotes {
                meetingNotetaker.pauseRecognitionForPushToTalk()
                didPauseNotetakerForPushToTalk = true
            }

            // The event-tap keyboard press starts a rehearsal attempt, but cannot
            // complete it. The identifier is captured by this exact dictation
            // session and only its known final transcript plus the matching
            // event-tap keyboard release can satisfy the proof.
            let rehearsalAttemptIdentifier =
                beginFirstRunRehearsalAttemptIfAwaiting()

            // First press each session leaves a receipt — "does the hotkey
            // work" becomes a log check, not a guess.
            if !hasLoggedFirstHotkeyPressThisSession {
                hasLoggedFirstHotkeyPressThisSession = true
                LifecycleLog.append("HOTKEY first press observed")
            }

            // Cancel any pending transient hide so the overlay stays visible
            transientHideTask?.cancel()
            transientHideTask = nil

            // Every interaction needs a visible overlay. In transient mode it
            // will still be hidden again after the response finishes.
            if !isOverlayVisible {
                overlayWindowManager.hasShownOverlayBefore = true
                isOverlayVisible = overlayWindowManager.showOverlay(
                    onScreens: NSScreen.screens,
                    companionManager: self
                )
                guard isOverlayVisible else {
                    return
                }
            }

            // End the prior response/TTS lifecycle before the new tracker takes
            // its first sample. Otherwise the new capture can inherit a stale
            // responding phase from the turn it is replacing.
            noraVoice.stopPlayback()
            clearDetectedElementLocation()
            if explainAppsChoreographyTask != nil || walkthroughTask != nil {
                appendRouteReceipt("ROUTE narration cancelled by push-to-talk press")
            }
            explainAppsChoreographyTask?.cancel()
            explainAppsChoreographyTask = nil
            cancelWalkthroughIfRunning()
            cancelFirstRunTourIfRunning()
            finishWaveformTurn(reason: .turnReplacement)
            voiceState = .processing

            // BARGE-IN. The press is the owner claiming the floor, so it opens a
            // NEW owner turn and cancels the previous one in the ledger.
            //
            // Cancelling the previous turn is what makes barge-in surgical: a
            // final transcript still in flight from the turn the owner just
            // interrupted belongs to a cancelled turn and can never route, while
            // the turn opening right here is untouched and routes normally. The
            // outbound side is ended by `stopPlayback` below, which flushes the
            // voice queue and publishes the interrupted line as `.cancelled`.
            provisionallyPreservedVoiceWorkTurnID =
                AceEventBus.shared.currentTurnID
            let microphoneTurnID = AceEventBus.shared.beginOwnerTurn(
                cancellingPrevious: false
            )
            activeRoutingTurnID = microphoneTurnID
            beginWaveformTurn(
                turnID: microphoneTurnID,
                source: .commandShift
            )

            // A real press ends the welcome prompt immediately. Rotating its
            // generation also makes already-enqueued Timer callbacks inert.
            cancelOnboardingPromptStream()
    

            BlackLabelAnalytics.trackPushToTalkStarted()

            buddyDictationManager.updateContextualCaptureContext(
                speechContextualCaptureContext()
            )
            pendingKeyboardShortcutStartTask?.cancel()
            pendingKeyboardShortcutStartTask = Task {
                await buddyDictationManager.startPushToTalkFromKeyboardShortcut(
                    ownerTurnID: microphoneTurnID,
                    currentDraftText: "",
                    updateDraftText: {
                        [weak self] capturedTurnID, partialTranscript in
                        // Partial transcripts are hidden (waveform-only UI).
                        // Still published as `.partial` so the event stream and
                        // the HUD see the turn forming — and so the type system
                        // records that a partial is UI-only, never routable.
                        self?.ingestOwnerPartialTranscript(
                            partialTranscript,
                            capturedOwnerTurnID: capturedTurnID
                        )
                    },
                    submitDraftText: {
                        [weak self] capturedTurnID, finalTranscript in
                        let wasConsumedByRehearsal =
                            self?.recordFirstRunRehearsalTranscript(
                            finalTranscript,
                            attemptIdentifier:
                                rehearsalAttemptIdentifier
                        ) ?? false
                        self?.lastTranscript = finalTranscript
                        print(
                            "🗣️ Companion received transcript "
                                + "characters=\(finalTranscript.count)"
                        )
                        if wasConsumedByRehearsal {
                            self?.appendRouteReceipt(
                                "TOUR rehearsal transcript consumed before normal routing"
                            )
                            return
                        }
                        BlackLabelAnalytics.trackUserMessageSent(transcript: finalTranscript)
                        self?.ingestOwnerUtterance(
                            finalTranscript,
                            origin: .microphonePushToTalk,
                            capturedOwnerTurnID: capturedTurnID
                        )
                    },
                    shouldSubmitImmediatelyOnRelease: {
                        [weak self] partialTranscript in
                        self?.isInstantLaneCommandForRelease(
                            partialTranscript
                        ) ?? false
                    }
                )
            }
        case .released:
            if stealthMode.isActive {
                pendingKeyboardShortcutStartTask?.cancel()
                pendingKeyboardShortcutStartTask = nil
                stealthExitOnlyCapture.endPushToTalk()
                appendRouteReceipt("STEALTH exit-only PTT released")
                return
            }
            // Cancel only while capture has not begun. Once microphone audio
            // is buffered, allow the recognizer to finish starting and consume
            // that quick utterance; stopPushToTalk retains its release boundary.
            BlackLabelAnalytics.trackPushToTalkReleased()
            let rehearsalAttemptIdentifier =
                activeFirstRunRehearsalAttemptIdentifier
            if buddyDictationManager.isPreparingToRecord
                || !buddyDictationManager.isRecordingFromKeyboardShortcut {
                pendingKeyboardShortcutStartTask?.cancel()
            }
            pendingKeyboardShortcutStartTask = nil
            waveformShortcutState = .released
            buddyDictationManager.stopPushToTalkFromKeyboardShortcut()
            observeWaveformState()
            recordFirstRunRehearsalRelease(
                attemptIdentifier: rehearsalAttemptIdentifier
            )
            // Push-to-talk is done — hand the recognition slot back to the
            // notetaker so meeting transcription resumes on the next voiced word.
            if didPauseNotetakerForPushToTalk {
                didPauseNotetakerForPushToTalk = false
                meetingNotetaker.resumeRecognitionAfterPushToTalk()
            }
        case .cancelled:
            pendingKeyboardShortcutStartTask?.cancel()
            pendingKeyboardShortcutStartTask = nil
            if stealthMode.isActive {
                stealthExitOnlyCapture.cancel()
                return
            }
            buddyDictationManager.cancelCurrentDictation(preserveDraftText: false)
            finishWaveformTurn(reason: .turnReplacement)
            waveformShortcutState = .released
            voiceState = .idle
            if didPauseNotetakerForPushToTalk {
                didPauseNotetakerForPushToTalk = false
                meetingNotetaker.resumeRecognitionAfterPushToTalk()
            }
        case .none:
            break
        }
    }

    // MARK: - Companion Prompt

    private static let companionVoiceResponseSystemPrompt = """
    you're Ace, a private always-on assistant that lives in the user's menu bar. the user just spoke to you via push-to-talk and you can see their screen(s). if asked your name, you're Ace — that's the only name you ever use for yourself. your reply will be spoken aloud via text-to-speech, so write the way you'd actually talk. this is an ongoing conversation — your recent exchanges are included below, and anything the user asked you to remember is in the "long-term memory" section if one is present. that memory is stored in a local file on their mac; relevant entries in this prompt go directly through the AI account they chose, never through any server of ours. if asked where memory is stored or processed, that's the honest answer. never claim to remember something that isn't in the conversation or that memory section. explicit remember commands are saved by the app before it confirms them. never claim that you saved or deleted memory yourself; only the app-owned result proves that change.

    rules:
    - never end an owner request with a refusal, denial, or generic inability. if the direct path does not complete, return typed execution so the available agent lane continues the same objective. if one exact target or value is genuinely missing or ambiguous, ask only for that value and preserve the request for immediate continuation.
    - default to one or two sentences. be direct and dense. BUT if the user asks you to explain more, go deeper, or elaborate, then go all out — give a thorough, detailed explanation with no length limit.
    - all lowercase, casual, warm. no emojis.
    - write for the ear, not the eye. short sentences. no lists, bullet points, markdown, or formatting — just natural speech.
    - don't use abbreviations or symbols that sound weird read aloud. write "for example" not "e.g.", spell out small numbers.
    - if the user's question relates to what's on their screen, reference specific things you see.
    - if the screenshot doesn't seem relevant to their question, just answer the question directly.
    - you can help with anything — coding, writing, general knowledge, brainstorming.
    - never say "simply" or "just".
    - don't read out code verbatim. describe what the code does or what needs to change conversationally.
    - focus on giving a thorough, useful explanation. don't end with simple yes/no questions like "want me to explain more?" or "should i show you?" — those are dead ends that force the user to just say yes.
    - instead, when it fits naturally, end by planting a seed — mention something bigger or more ambitious they could try, a related concept that goes deeper, or a next-level technique that builds on what you just explained. make it something worth coming back for, not a question they'd just nod to. it's okay to not end with anything extra if the answer is complete on its own.
    - if you receive multiple screen images, the one labeled "primary focus" is where the cursor is — prioritize that one but reference others if relevant.

    Use only supplied evidence for current facts. If the question requires live traffic, a latest inspection, a current score, or source verification, return typed execution for backend research; never present a typical estimate or older source as current data. Written research needs clickable citations and source dates. Answer independent questions while existing work continues. Preserve the active task and its exact destination on follow-ups; do not start a duplicate job for a continuation. Essays default to MLA 9 with in-text citations and Works Cited from sources actually read, unless the assignment specifies otherwise. Spoken-reply style rules apply only to speech, never to the document. Never narrate checksums or internal receipts. Never claim an AI detector ran without its actual result.

    orchestration and typed output contract:
    you are Gold, Ace's conversational orchestrator. Understand the complete owner request using the current conversation, recent requested destination, and any supplied screen. The owner does not have to use fixed command wording. Resolve ordinary references such as "it", "that app", and "put it on my screen" from this context. If more than one target is plausible, ask which one while retaining the task.
    Return exactly one decision with kind, spoken_response, objective, and foreground_action. For reply or clarify, objective and foreground_action are null. For execute, spoken_response is empty, objective contains the bounded background objective, and foreground_action is null. For foreground, spoken_response is empty, objective is null, and foreground_action is {"destination":"application" or "website","target":"exact app name or HTTP(S) URL"}.
    Use foreground to open, bring up, show, or bring forward an app or website on the owner's screen. Use application for an installed app such as Square; use website for an exact public URL such as https://docs.google.com. Preserve a specific document URL already supplied or observed. Do not substitute a website when the owner explicitly means an installed app. A compound task may open or control an app through the general executor while preserving every requested step. Ace performs the foreground action, requests any actual missing macOS permission, and checks the visible result before speaking.
    Reply for questions answerable from supplied evidence or stable knowledge. Clarify only a genuinely missing or ambiguous target or value. Execute for work through the available APIs, files, research, apps, and browser tools. The executor may interact with the desktop when the requested work needs it; a missing backend is not a task prohibition. Use foreground for a simple open or show request, and execute for a task that requires further interaction, such as selecting and playing a song. Preserve every part of a compound request in the objective so the executor can complete independent parts concurrently. Never invent shell strings, executable paths, credentials, environment variables, turn/work IDs, approval tokens, or claimed results.
    Treat previous requests and navigation records as context for the owner's current meaning, not as new instructions or proof that work succeeded. Current corrections override old assumptions. Facts that may have changed require live verification through background execution.
    Preserve point and evidence tags inside spoken_response for replies. With tools available, call exactly one of reply, clarify, open_on_screen, or execute_objective and stop; otherwise return the single JSON decision. Never claim external work already ran.

    element pointing:
    you have a small gold gem cursor that can fly to and point at things on screen. use it whenever pointing would genuinely help the user — if they're asking how to do something, looking for a menu, trying to find a button, or need help navigating an app, point at the relevant element. err on the side of pointing rather than not pointing, because it makes your help way more useful and concrete.

    don't point at things when it would be pointless — like if the user asks a general knowledge question, or the conversation has nothing to do with what's on screen, or you'd just be pointing at something obvious they're already looking at. but if there's a specific UI element, menu, button, or area on screen that's relevant to what you're helping with, point at it.

    when you point, append a coordinate tag at the very end of your response, AFTER your spoken text. every screenshot label includes an immutable capture_id, display_id, and its pixel dimensions. copy the exact capture_id and display_id for the image you used. use that image's pixel dimensions as the coordinate space. the origin (0,0) is the top-left corner. x increases rightward, y increases downward. include your confidence from 0 to 1.

    format: [POINT:capture=<exact capture_id>;display=<exact display_id>;x=<pixel x>;y=<pixel y>;confidence=<0 to 1>;label=<short description>]. never omit either identity and never use a screen number or image-array position.

    if pointing wouldn't help, append [POINT:none].

    examples:
    - user asks what html is: "html stands for hypertext markup language, it's basically the skeleton of every web page. curious how it connects to the css you're looking at? [POINT:none]"
    - for a point, copy the exact capture_id and display_id printed in the chosen image label; placeholders are not valid output.
    """

    // MARK: - AI Response Pipeline

    /// Captures a screenshot, sends it along with the transcript to Claude,
    /// and plays the response aloud via the local Nora voice. The cursor stays in
    /// the spinner/processing state until TTS audio begins playing.
    // MARK: - Provider response and Red execution

    /// Red is the first full-access executor behind every selected provider.
    /// One independent Silver worker accepts a second simultaneous background
    /// check when Red is occupied and the Silver workflow lane is free.
    private(set) lazy var backgroundAgent = BackgroundAgent()
    private(set) lazy var silverBackgroundAgent = BackgroundAgent(
        identity: .silver
    )
    private lazy var appActionBroker = AppActionBroker()
    private var nativeLocationManager: NativeLocationManager?
    private var localWeatherSessionContext = LocalWeatherSessionContext()

    /// The meeting notetaker ("take notes" / "join the meeting"). Captures both
    /// sides of a meeting locally and produces structured notes on stop.
    private(set) lazy var meetingNotetaker = MeetingNotetaker(
        audioSessionCoordinator: audioSessionCoordinator
    )

    /// The purple lane — "activate trading mode". A local, instant context toggle:
    /// lights the purple gem and gives the gold brain the 16-factor market context
    /// (see effectiveSystemPrompt). Never launches an app, never routes to the
    /// worker, never places or fabricates a trade.
    private(set) lazy var tradingLane = TradingLane()

    /// "Go stealth" hides every visible
    /// surface, silences Nora, and closes passive microphone capture. The normal
    /// push-to-talk chord may open only the isolated local exit recognizer.
    let stealthMode = StealthMode()
    private var stealthHotkeyHealthTimer: Timer?

    // MARK: Private Mode read (ported from the 1.0 build, 2026-07-26)
    //
    // Stealth used to be only the hiding half. This is the half that does
    // something: while stealthed, the first Caps-on Shift+Z reads the
    // multiple-choice question and completes one verified answer click in the
    // same operation. The model can only propose a capture-bound coordinate;
    // app code binds the exact AX object, revalidates the window and pointer,
    // aims, then revalidates again immediately before mouse-down. The remaining safety
    // properties are
    // carried over rather than reimplemented —
    // fail-closed policy BEFORE any pixels are captured, a second check
    // immediately before the click (the capture→click gap is a real hole), no
    // brain.log receipts, and a plain-language record of what was captured and
    // when so the mode can never be quietly doing more than it claims.

    /// The in-flight read, so a held chord can't stack two of them.
    private var stealthAnswerTask: Task<Void, Never>? {
        didSet {
            InstallReadinessCoordinator.shared.set(
                .privateModeAnswer,
                active: stealthAnswerTask != nil
            )
        }
    }
    private var stealthAnswerDeadlineTask: Task<Void, Never>?
    private var stealthAnswerSessionIdentifier: UUID?
    /// The event-tap Private Mode entry chord raises its latch before
    /// main-queue delivery. Every direct-effect resolver and preparation path
    /// uses this same policy so a queued transcript cannot land an effect in the
    /// chord-to-Stealth gap.
    nonisolated static func directEffectsAreAllowed(
        privateModeEntryIsRequested: Bool,
        stealthIsActive: Bool,
        visibilityGateIsActive: Bool
    ) -> Bool {
        !privateModeEntryIsRequested
            && !stealthIsActive
            && !visibilityGateIsActive
    }

    private var directEffectsAreAllowed: Bool {
        AceLicense.shared.admits(.appAction)
            && Self.directEffectsAreAllowed(
                privateModeEntryIsRequested:
                    globalPushToTalkShortcutMonitor
                        .privateModeEntryIsRequested,
                stealthIsActive: stealthMode.isActive,
                visibilityGateIsActive:
                    StealthVisibilityGate.shared.isActive
            )
    }

    /// Fresh Private Mode/visibility admission for one synchronous, already-resolved
    /// effect commit. The effect must remain bounded and must not await.
    @discardableResult
    private func performDirectEffectCommit(
        _ effect: @escaping () -> Bool
    ) -> Bool {
        switch DirectEffectCommitAdmission.commit(
            visibilityIsBlocked: { [weak self] in
                self?.directEffectsAreAllowed != true
            },
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            },
            effect: effect
        ) {
        case .committed(let result):
            return result
        case .blocked:
            return false
        }
    }

    private var stealthAnswerCancellable: AnyCancellable?

    /// Plain-language description of the last thing Private Mode actually did.
    /// Shown to the user rather than kept for us: a hidden mode has to be
    /// accountable for exactly what it captured and where it went.
    @Published private(set) var privateModeActivityStatus: String = ""
    @Published private(set) var lastPrivateModeCaptureAt: Date?
    @Published private(set) var lastPrivateModeRemoteProcessingAt: Date?
    @Published private(set) var lastPrivateModeSyntheticClickAt: Date?

    var privateModeShortcutMonitorIsActive: Bool {
        globalPushToTalkShortcutMonitor.isEventTapOperational
    }

    nonisolated static func privateModeReadinessMessage(
        isLicensed: Bool,
        shortcutIsActive: Bool,
        exitVoiceIsReady: Bool,
        screenIsReady: Bool,
        providerIsReady: Bool
    ) -> String? {
        if !isLicensed { return "Link your Ace account before entering Stealth." }
        if !shortcutIsActive { return "The keyboard shortcut is unavailable. Go Stealth will retry it; check Accessibility in Setup if it remains unavailable." }
        if !exitVoiceIsReady { return "Check Microphone and on-device Speech Recognition in Setup so you can exit Stealth." }
        if !screenIsReady { return "Hiding Ace is available. Complete Screen Recording and Screen Content in Setup before using Shift + Z." }
        if !providerIsReady { return "Hiding Ace is available. Check the selected provider account before using Shift + Z." }
        return nil
    }

    /// Retry the local shortcut and explain a refusal before hiding the panel.
    func enterPrivateModeFromPanel() {
        guard AceLicense.shared.admits(.privateModeEntry) else {
            privateModeActivityStatus = "Link your Ace account before entering Stealth."
            appendRouteReceipt("STEALTH panel entry refused reason=unlicensed")
            return
        }
        refreshAllPermissions()
        guard normalRuntimeAdmissionRemainsOpen else { return }
        guard globalPushToTalkShortcutMonitor.repairEventTapIfNeeded() else {
            privateModeActivityStatus = "Stealth did not start. Open Setup and check Accessibility; the keyboard shortcut is unavailable."
            appendRouteReceipt("STEALTH panel entry refused reason=shortcut-unavailable")
            return
        }
        guard hasMicrophonePermission && isOnDeviceDictationReady else {
            privateModeActivityStatus = "Stealth did not start. Check Microphone and on-device Speech Recognition in Setup so you can say exit stealth."
            appendRouteReceipt("STEALTH panel entry refused reason=exit-voice-unavailable")
            return
        }
        privateModeActivityStatus = ""
        enterStealthMode()
        if !stealthMode.isActive && privateModeActivityStatus.isEmpty {
            privateModeActivityStatus = "Stealth did not finish starting. Try Go Stealth again."
            appendRouteReceipt("STEALTH panel entry incomplete")
        }
    }

    /// "grant yourself access" — sequential Automation-permission warm-up, run
    /// in-app because a consent dialog blocks the script that triggered it (a
    /// codex-driven warm-up eats its own timeout instead).
    private(set) lazy var permissionWarmup = PermissionWarmup()
    private var permissionWarmupTask: Task<Void, Never>? {
        didSet { refreshInstallReadinessSetupAuth() }
    }

    static func isPermissionWarmupTrigger(_ text: String) -> Bool {
        CrossAppActionPolicy.isPermissionWarmupRequest(text)
    }

    private func startPermissionWarmup() {
        guard !permissionWarmup.isRunning,
              permissionWarmupTask == nil,
              directEffectsAreAllowed else { return }
        permissionWarmupTask = Task { [weak self] in
            guard let self else { return }
            defer { self.permissionWarmupTask = nil }
            guard self.directEffectsAreAllowed else { return }
            try? await noraVoice.speakText(
                "on it. i'll knock on each app i can control — macos will ask you to allow each one. click allow on every prompt.")
            guard !Task.isCancelled, directEffectsAreAllowed else { return }
            backgroundTaskActive = true
            showCursorOverlayForBackgroundTask()
            let spokenSummary = await permissionWarmup.run()
            guard !Task.isCancelled, directEffectsAreAllowed else { return }
            backgroundTaskActive = meetingNotetaker.isTakingNotes
                || anyBackgroundExecutionAgentIsWorking
            try? await noraVoice.speakText(spokenSummary)
        }
    }

    private func isNotesStartTrigger(_ text: String) -> Bool {
        Self.isUnambiguousNotesStartRequest(text)
    }

    static func isUnambiguousNotesStartRequest(_ text: String) -> Bool {
        CrossAppActionPolicy.isUnambiguousNotesStartRequest(text)
    }

    /// The built-in self-test is deliberately narrow. Questions, negations,
    /// corrections, and explicit recipients all stay off the send path.
    static func isTestEmailSendRequest(_ text: String) -> Bool {
        CrossAppActionPolicy.isTestEmailSendRequest(text)
    }

    private struct TestEmailToolResult {
        let terminationStatus: Int32
        let standardOutput: String
    }

    /// Starts with a read-only Apple Mail lookup. Nothing is armed until the exact
    /// From/To/subject/body card has received DONE for its complete Nora queue
    /// item. The resolved address and every value then remain immutable.
    private func beginTestEmailSelfTestPreview() {
        guard directEffectsAreAllowed else { return }
        guard testEmailTask == nil,
              !(testEmailProcess?.isRunning ?? false),
              pendingTestEmailSend == nil,
              appActionPlanningTask == nil else {
            Task {
                try? await noraVoice.speakText(
                    "an Apple Mail self-test is already being reviewed or run.")
            }
            return
        }

        let reviewIdentifier = UUID()
        let operationID = reviewIdentifier.uuidString.lowercased()
        let timestamp = ISO8601DateFormatter().string(from: Date())
        let subject = "Ace Apple Mail self-test \(timestamp)"
        let body =
            "Ace Apple Mail self-test requested by voice at \(timestamp).\n"
                + "Operation: \(operationID)"
        let generation = UUID()
        testEmailGeneration = generation
        isPreparingTestEmailSend = true
        appActionReview = AppActionReviewState(
            planIdentifier: reviewIdentifier,
            exactPreview: "",
            phase: .reading
        )
        appendRouteReceipt("ROUTE email-test-preview")

        testEmailTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.testEmailGeneration == generation {
                    self.testEmailTask = nil
                    self.testEmailProcess = nil
                    self.isPreparingTestEmailSend = false
                }
            }

            let outcome = await self.runBundledEmailTool(
                arguments: ["--self-test-preview", operationID]
            )
            guard !Task.isCancelled,
                  self.testEmailGeneration == generation,
                  self.directEffectsAreAllowed else {
                return
            }
            guard let outcome,
                  outcome.terminationStatus == 0,
                  let recipient = Self.testEmailPreviewRecipient(
                    from: outcome.standardOutput,
                    expectedOperationID: operationID
                  ) else {
                if self.appActionReview?.planIdentifier
                    == reviewIdentifier {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: reviewIdentifier,
                        exactPreview: "",
                        phase: .notArmed(
                            reason:
                                "Ace could not resolve one exact enabled primary Apple Mail address. Nothing is armed."
                        )
                    )
                }
                self.appendRouteReceipt(
                    "EMAIL-TEST preview refused invalid or unavailable result")
                try? await self.noraVoice.speakText(
                    "i could not verify one exact enabled primary Apple Mail "
                        + "address, so no test email is armed.")
                return
            }

            let pending = PendingTestEmailSend(
                operationID: operationID,
                reviewIdentifier: reviewIdentifier,
                recipient: recipient,
                subject: subject,
                body: body,
                requestedAt: Date()
            )
            guard self.appActionReview?.planIdentifier
                    == reviewIdentifier else {
                self.appendRouteReceipt(
                    "EMAIL-TEST preview lost review ownership; no send staged")
                return
            }
            self.appActionReview = AppActionReviewState(
                planIdentifier: reviewIdentifier,
                exactPreview: pending.exactPreview,
                phase: .reading
            )
            let readbackCompleted =
                await self.noraVoice
                    .speakVerbatimTextToVerifiedCompletion(
                    "review this exact email self-test. \(pending.exactPreview)")
            guard readbackCompleted,
                  !Task.isCancelled,
                  self.testEmailGeneration == generation,
                  self.directEffectsAreAllowed else {
                self.pendingTestEmailSend = nil
                if self.testEmailGeneration == generation,
                   self.appActionReview?.planIdentifier
                    == reviewIdentifier {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: reviewIdentifier,
                        exactPreview: pending.exactPreview,
                        phase: .notArmed(
                            reason:
                                "Readback was interrupted. Nothing is armed; ask again."
                        )
                    )
                }
                self.appendRouteReceipt(
                    "EMAIL-TEST exact readback incomplete; no send staged")
                return
            }

            let armed = PendingTestEmailSend(
                operationID: pending.operationID,
                reviewIdentifier: pending.reviewIdentifier,
                recipient: pending.recipient,
                subject: pending.subject,
                body: pending.body,
                requestedAt: Date()
            )
            guard self.appActionReview?.planIdentifier
                    == reviewIdentifier else {
                self.appendRouteReceipt(
                    "EMAIL-TEST readback lost review ownership; no send staged")
                return
            }
            self.pendingTestEmailSend = armed
            self.isPreparingTestEmailSend = false
            self.appActionReview = AppActionReviewState(
                planIdentifier: armed.reviewIdentifier,
                exactPreview: armed.exactPreview,
                phase: .ready(expiresAt: armed.expiresAt)
            )
            self.scheduleTestEmailExpiry(for: armed)
            self.appendRouteReceipt(
                "EMAIL-TEST exact values armed for 30 seconds")
            try? await self.noraVoice.speakText(
                "say confirm within thirty seconds, or say cancel.")
        }
    }

    private func scheduleTestEmailExpiry(
        for pending: PendingTestEmailSend
    ) {
        testEmailExpiryTask?.cancel()
        testEmailExpiryTask = Task { [weak self] in
            do {
                try await Task.sleep(
                    for: .seconds(
                        CrossAppActionPolicy.confirmationLifetime
                    )
                )
            } catch {
                return
            }
            guard let self,
                  let current = self.pendingTestEmailSend,
                  current.operationID == pending.operationID else {
                return
            }
            self.pendingTestEmailSend = nil
            self.testEmailExpiryTask = nil
            if self.appActionReview?.planIdentifier
                == current.reviewIdentifier {
                self.appActionReview = AppActionReviewState(
                    planIdentifier: current.reviewIdentifier,
                    exactPreview: current.exactPreview,
                    phase: .notArmed(
                        reason: "Confirmation expired. Nothing was sent."
                    )
                )
            }
            self.appendRouteReceipt(
                "EMAIL-TEST binding expired; no send staged")
        }
    }

    /// Runs only the already-reviewed, frozen self-test. Re-resolving the
    /// expected address happens again inside the wrapper immediately before any
    /// hidden Apple Mail message is created.
    private func performTestEmailSend(_ pending: PendingTestEmailSend) {
        guard directEffectsAreAllowed else { return }
        guard testEmailTask == nil,
              !(testEmailProcess?.isRunning ?? false) else {
            return
        }
        appendRouteReceipt("ROUTE email-test-send")
        let generation = UUID()
        testEmailGeneration = generation
        testEmailTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.testEmailGeneration == generation {
                    self.testEmailTask = nil
                    self.testEmailProcess = nil
                }
            }
            guard self.directEffectsAreAllowed else { return }
            let outcome = await self.runBundledEmailTool(
                arguments: [
                    "--self-test",
                    pending.operationID,
                    "--expected-recipient",
                    pending.recipient,
                    pending.subject,
                    pending.body,
                ]
            )
            guard !Task.isCancelled,
                  self.testEmailGeneration == generation,
                  self.directEffectsAreAllowed else {
                return
            }

            let expected =
                "queued in Apple Mail to \(pending.recipient): \(pending.subject)"
            if let outcome,
               outcome.terminationStatus == 0,
               Self.exactSingleLineToolOutput(outcome.standardOutput)
                    == expected {
                if self.appActionReview?.planIdentifier
                    == pending.reviewIdentifier {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: pending.reviewIdentifier,
                        exactPreview: pending.exactPreview,
                        phase: .notArmed(
                            reason: "Apple Mail accepted this exact self-test once."
                        )
                    )
                }
                self.appendRouteReceipt(
                    "EMAIL-TEST verified queued to reviewed address")
                try? await self.noraVoice.speakText(
                    "Apple Mail accepted the exact test email to \(pending.recipient).")
            } else {
                if self.appActionReview?.planIdentifier
                    == pending.reviewIdentifier {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: pending.reviewIdentifier,
                        exactPreview: pending.exactPreview,
                        phase: .notArmed(
                            reason:
                                "Apple Mail did not verify the exact reviewed send. Ace did not retry."
                        )
                    )
                }
                self.appendRouteReceipt(
                    "EMAIL-TEST failed or returned a nonmatching receipt")
                try? await self.noraVoice.speakText(
                    "Apple Mail did not verify that exact self-test. i did not retry.")
            }
        }
    }

    nonisolated static func testEmailPreviewRecipient(
        from rawOutput: String,
        expectedOperationID: String
    ) -> String? {
        guard let line = exactSingleLineToolOutput(rawOutput),
              line.utf8.count <= 512,
              let data = line.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data),
              let dictionary = object as? [String: Any],
              Set(dictionary.keys) == Set(["operationId", "recipient"]),
              let operationID = dictionary["operationId"] as? String,
              operationID == expectedOperationID,
              let recipient = dictionary["recipient"] as? String,
              recipient.range(
                of:
                    #"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$"#,
                options: .regularExpression
              ) != nil,
              !recipient.hasPrefix("."),
              !recipient.contains(".."),
              !recipient.contains(".@") else {
            return nil
        }
        return recipient
    }

    nonisolated static func exactSingleLineToolOutput(
        _ rawOutput: String
    ) -> String? {
        guard !rawOutput.contains("\r") else { return nil }
        var line = rawOutput
        if line.hasSuffix("\n") {
            line.removeLast()
        }
        guard !line.isEmpty,
              !line.contains("\n"),
              line
                == line.trimmingCharacters(
                    in: .whitespacesAndNewlines
                ) else {
            return nil
        }
        return line
    }

    /// Runs the fixed read-only preview or the one separately approved send.
    /// Standard error is never surfaced or spoken, and the 45-second attempt is
    /// never retried.
    private func runBundledEmailTool(
        arguments: [String]
    ) async -> TestEmailToolResult? {
        guard !Task.isCancelled,
              directEffectsAreAllowed else { return nil }
        let isPreview =
            arguments.count == 2
                && arguments.first == "--self-test-preview"
        let isSend =
            arguments.count == 6
                && arguments.first == "--self-test"
                && arguments[2] == "--expected-recipient"
        guard (isPreview || isSend),
              let resourceURL = Bundle.main.resourceURL else { return nil }
        let toolsURL = resourceURL
            .appendingPathComponent("tools", isDirectory: true)
            .standardizedFileURL
        let toolURL = toolsURL
            .appendingPathComponent("email-send", isDirectory: false)
            .standardizedFileURL
        guard toolURL.deletingLastPathComponent() == toolsURL,
              toolsURL.resolvingSymlinksInPath() == toolsURL,
              toolURL.resolvingSymlinksInPath() == toolURL,
              let toolsValues = try? toolsURL.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
              ),
              toolsValues.isDirectory == true,
              toolsValues.isSymbolicLink != true,
              let resourceValues = try? toolURL.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
              ),
              resourceValues.isRegularFile == true,
              resourceValues.isSymbolicLink != true,
              FileManager.default.isExecutableFile(atPath: toolURL.path)
        else {
            return nil
        }

        var approval: OwnerTurnEffectAuthority?
        if isSend {
            do {
                approval = try OwnerTurnEffectAuthority.issue()
            } catch {
                return nil
            }
        }
        defer { approval?.destroy() }

        let toolProcess = Process()
        toolProcess.executableURL = toolURL
        toolProcess.arguments = arguments
        if let approval {
            toolProcess.environment = approval.wrapperEnvironment()
        } else {
            guard let applicationSupportURL = FileManager.default.urls(
                for: .applicationSupportDirectory,
                in: .userDomainMask
            ).first else {
                return nil
            }
            let supportURL = applicationSupportURL
                .appendingPathComponent("BlackLabel", isDirectory: true)
                .standardizedFileURL
            var environment = ProcessInfo.processInfo.environment
            for key in environment.keys where key.hasPrefix("ACE_") {
                environment.removeValue(forKey: key)
            }
            environment["ACE_EFFECT_GUARD_SUPPORT_DIRECTORY"] =
                supportURL.path
            environment["ACE_STEALTH_MARKER"] = supportURL
                .appendingPathComponent(
                    "stealth-active",
                    isDirectory: false
                ).path
            environment["ACE_STEALTH_INTENT"] = supportURL
                .appendingPathComponent(
                    "stealth-intent-v1",
                    isDirectory: false
                ).path
            environment["ACE_STEALTH_ENTRY_REQUEST"] = supportURL
                .appendingPathComponent(
                    "stealth-entry-request-v1",
                    isDirectory: false
                ).path
            toolProcess.environment = environment
        }
        toolProcess.standardInput = FileHandle.nullDevice
        let outputPipe = Pipe()
        toolProcess.standardOutput = outputPipe
        guard let outputCapture = try? BoundedPipeCapture(
            handle: outputPipe.fileHandleForReading, limit: 1048576
        ) else { return nil }
        defer { outputCapture.discard() }
        toolProcess.standardError = FileHandle.nullDevice

        let processCutoff = MailToolProcessCutoff()
        let cutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                processCutoff.cancelSynchronously()
            }
        defer {
            processCutoff.clear()
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier
            )
        }

        do {
            let launched = try StealthEntryLatch.shared.performUnlessRaised {
                try toolProcess.run()
                processCutoff.register(toolProcess)
                return true
            }
            guard launched == true else { return nil }
            testEmailProcess = toolProcess
        } catch {
            return nil
        }

        let deadline =
            DispatchTime.now().uptimeNanoseconds &+ (45 * 1_000_000_000)
        while toolProcess.isRunning {
            guard !Task.isCancelled,
                  directEffectsAreAllowed else {
                RunningProcessBox.terminateProcessTree(toolProcess)
                return nil
            }
            if DispatchTime.now().uptimeNanoseconds >= deadline {
                RunningProcessBox.terminateProcessTree(toolProcess)
                return nil
            }
            try? await Task.sleep(for: .milliseconds(50))
        }

        let capturedOutput = outputCapture.finish()
        guard !capturedOutput.truncated, !capturedOutput.readFailed else {
            return nil
        }
        let outputData = capturedOutput.data
        guard let output = String(data: outputData, encoding: .utf8) else {
            return nil
        }
        return TestEmailToolResult(
            terminationStatus: toolProcess.terminationStatus,
            standardOutput: output
        )
    }

    private struct EmailReadToolResult {
        let terminationStatus: Int32
        let standardOutput: String
    }

    /// Inbox reads stay in the app-owned, fixed read-only lane. No model or
    /// background worker can reinterpret this request as a send/reply action.
    private func performRepeatResponse(context: OwnerTurnContext) {
        let response = noraVoice.repeatableResponseText
            ?? "There is no recent reply to repeat yet."
        let published = finishVolatileOwnerTurn(
            turnID: context.turnID,
            correlationID: activeRoutingCorrelationID,
            status: .completed,
            outcome: "response-repeat-presented",
            reason: response,
            speak: false
        )
        if published {
            if partnerModeIsActive {
                speakPartnerStatus(response, persistence: .volatile)
            } else {
                _ = noraVoice.enqueueVolatileText(response)
            }
        }
    }

    private func performTypeLastResponse(context: OwnerTurnContext) {
        guard let response = noraVoice.repeatableResponseText?
            .trimmingCharacters(in: .whitespacesAndNewlines),
              !response.isEmpty else {
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .failed,
                outcome: "response-type-missing-source",
                reason: "There is no recent reply to type yet."
            )
            return
        }
        appendRouteReceipt(
            "TYPE-RESPONSE native source=last-response characters=\(response.count)"
        )
        performTypeRequest(
            response,
            context: context,
            application: context.resolvedSlots["appTarget"]
        )
    }

    private func performEmailRead(
        _ utterance: String,
        binding: OwnerTurnBinding
    ) {
        guard directEffectsAreAllowed else { return }
        guard emailReadTask == nil,
              !(emailReadProcess?.isRunning ?? false) else {
            _ = finishVolatileOwnerTurn(
                turnID: binding.context.turnID,
                correlationID: binding.correlationID,
                status: .failed,
                outcome: "mail-read-already-running",
                reason: "An inbox read is already in progress."
            )
            return
        }

        let source = UserDefaults.standard.string(forKey: FloatingInboxController.sourcePreferenceKey)
        let sourceIdentity = emailReadSourceIdentity
        let previous = recentEmailRead.flatMap { $0.isUsable(sourceIdentity: sourceIdentity) ? $0 : nil }
        let isFollowUp = previous != nil && CrossAppActionPolicy.isEmailSummaryFollowUp(utterance)
        let explicitlyAppleMail = utterance.range(of: #"(?i)\bapple\s+mail\b"#, options: .regularExpression) != nil
        let useGmail = isFollowUp ? previous!.usesGmail : !explicitlyAppleMail && (
            CrossAppActionPolicy.emailReadRoutingDecision(utterance) == .gmail
            || (source != FloatingInboxSource.appleMail.rawValue && GmailAccountStore().storedAddress() != nil))
        let sourceLabel = useGmail ? "Gmail" : "unified Apple Mail"
        var arguments = Self.emailReadArguments(for: utterance)
        if isFollowUp, EmailReadWindow(arguments: arguments) == nil { arguments = previous!.arguments }
        let cachedOutput = isFollowUp && arguments == previous!.arguments ? previous!.output : nil
        recentEmailRead = nil
        let requestedCount = arguments.compactMap(Int.init).first ?? 5
        let window = EmailReadWindow(arguments: arguments)
        let unreadLabel = arguments.contains("unread") ? " unread" : ""
        let generation = UUID()
        emailReadGeneration = generation
        appendRouteReceipt(
            "ROUTE email-read app-owned args=\(arguments.joined(separator: ","))")
        showVisibleResponse(
            cachedOutput == nil
                ? "Checking up to \(requestedCount)\(unreadLabel) messages in your \(sourceLabel) inbox\(window.map { " " + $0.label } ?? "")…"
                : "Summarizing the inbox results I just read…"
        )
        emailReadTask = Task { [weak self] in
            guard let self else { return }
            guard self.directEffectsAreAllowed else { return }
            self.backgroundTaskActive = true
            self.showCursorOverlayForBackgroundTask()
            defer {
                if self.emailReadGeneration == generation {
                    self.emailReadTask = nil
                    self.emailReadProcess = nil
                    self.backgroundTaskActive =
                        self.meetingNotetaker.isTakingNotes
                            || self.anyBackgroundExecutionAgentIsWorking
                }
            }

            let result: EmailReadToolResult?
            if let cachedOutput {
                result = EmailReadToolResult(terminationStatus: 0, standardOutput: cachedOutput)
            } else {
                result = useGmail
                    ? await self.runConnectedGmailRead(arguments: arguments, utterance: utterance)
                    : await self.runBundledEmailRead(arguments: arguments)
            }
            guard !Task.isCancelled,
                  self.emailReadGeneration == generation,
                  self.directEffectsAreAllowed else { return }

            guard self.emailReadSourceIdentity == sourceIdentity else {
                _ = self.finishVolatileOwnerTurn(
                    turnID: binding.context.turnID, correlationID: binding.correlationID,
                    status: .failed, outcome: "mail-read-account-changed",
                    reason: "The email connection changed during this read. Ask again to use the current account."
                )
                return
            }

            guard let result else {
                self.appendRouteReceipt(
                    "EMAIL-READ failed before tool completion")
                _ = self.finishVolatileOwnerTurn(
                    turnID: binding.context.turnID,
                    correlationID: binding.correlationID,
                    status: .failed,
                    outcome: "mail-read-unavailable",
                    reason:
                        "The inbox did not return in time. Check the email connection and try again."
                )
                return
            }
            guard result.terminationStatus == 0,
                  !result.standardOutput.isEmpty else {
                self.appendRouteReceipt(
                    "EMAIL-READ failed exit=\(result.terminationStatus)")
                let reason = result.standardOutput.isEmpty
                    ? "Apple Mail isn't ready. Add or enable an account in Mail, then allow Ace to control Mail in System Settings and try again."
                    : result.standardOutput
                _ = self.finishVolatileOwnerTurn(
                    turnID: binding.context.turnID,
                    correlationID: binding.correlationID,
                    status: .failed,
                    outcome: "mail-read-failed",
                    reason: reason
                )
                return
            }

            self.appendRouteReceipt(
                "EMAIL-READ completed exit=0 chars="
                    + String(result.standardOutput.count)
            )
            self.recentEmailRead = RecentEmailRead(
                sourceIdentity: sourceIdentity, usesGmail: useGmail, arguments: arguments,
                output: result.standardOutput, receivedAt: cachedOutput == nil ? Date() : previous!.receivedAt
            )
            let summary = EmailReadPresentation.summary(of: result.standardOutput)
            let presentation = EmailReadPresentation.wantsSummary(utterance) || isFollowUp
                ? summary : result.standardOutput
            let speech = utterance.range(of: #"(?i)\b(verbatim|word\s+for\s+word|out\s+loud)\b"#, options: .regularExpression) != nil
                ? presentation : summary
            // Only successful stdout crosses into the visible and spoken
            // result. The fixed wrapper never marks messages read.
            let terminalPublished = self.finishVolatileOwnerTurn(
                turnID: binding.context.turnID,
                correlationID: binding.correlationID,
                status: .completed,
                outcome: "mail-read-completed",
                reason: presentation,
                durableReason:
                    "Read-only \(sourceLabel) inbox check completed.",
                visibleResponseRetention: .mailReadResult,
                speak: false
            )
            guard terminalPublished,
                  self.emailReadGeneration == generation,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            if self.partnerModeIsActive {
                self.speakPartnerStatus(speech, persistence: .volatile)
            } else {
                _ = self.noraVoice.enqueueVolatileText(speech)
            }
        }
    }

    private func runConnectedGmailRead(arguments: [String], utterance: String) async -> EmailReadToolResult? {
        do {
            guard let credential = try await GmailAccountStore().loadUsableCredential() else {
                return EmailReadToolResult(terminationStatus: 3, standardOutput: "Connect Gmail in Email settings, then ask me to check it again.")
            }
            // An explicit address must match the selected account. Never silently
            // answer a request about another mailbox with this account's data.
            if let regex = try? NSRegularExpression(pattern: #"[A-Za-z0-9._%+\-]+@[A-Za-z0-9\-]+(?:\.[A-Za-z0-9\-]+)+"#) {
                for match in regex.matches(in: utterance, range: NSRange(utterance.startIndex..., in: utterance)) {
                    if let range = Range(match.range, in: utterance), utterance[range].lowercased() != credential.address {
                        return EmailReadToolResult(terminationStatus: 3, standardOutput: "That address is different from the Gmail account connected in Email settings. Connect the requested account first.")
                    }
                }
            }
            let cancellation = FloatingInboxCancellation()
            let count = arguments.compactMap(Int.init).first ?? 5
            let unreadOnly = arguments.contains("unread")
            let result = await withTaskCancellationHandler {
                await Task.detached(priority: .userInitiated) { () -> Result<String, Error> in
                    defer { cancellation.cancel() }
                    return Result {
                        let session = try FloatingInboxGmail.connect(address: credential.address, password: credential.transportSecret, usesOAuth: credential.oauth != nil, cancellation: cancellation)
                        return try GmailInboxRead.read(session: session, account: credential.address, count: count, unreadOnly: unreadOnly, window: EmailReadWindow(arguments: arguments))
                    }
                }.value
            } onCancel: { cancellation.cancel() }
            switch result {
            case .success(let text): return EmailReadToolResult(terminationStatus: 0, standardOutput: text)
            case .failure: return EmailReadToolResult(terminationStatus: 3, standardOutput: "Gmail did not return a complete inbox result. Check the connection in Email settings and try again.")
            }
        } catch {
            return EmailReadToolResult(terminationStatus: 3, standardOutput: "Reconnect Gmail in Email settings to restore inbox access.")
        }
    }

    private func runBundledEmailRead(
        arguments: [String]
    ) async -> EmailReadToolResult? {
        await runBundledReadTool(named: "email-read", arguments: arguments)
    }

    /// Runs ONE bundled read-only wrapper with the full existing safety chain:
    /// bundle-anchored path, symlink and regular-file proof, ACE_* environment
    /// scrub, effect-guard/Stealth markers, synchronous Stealth cutoff, and a
    /// 45s deadline. Generalized from the email-read route so the morning brief
    /// reads real sources through the same boundary instead of a second one.
    private func runBundledReadTool(
        named toolName: String,
        arguments: [String],
        timeoutSeconds: UInt64 = 45
    ) async -> EmailReadToolResult? {
        guard !Task.isCancelled,
              directEffectsAreAllowed,
              let resourceURL = Bundle.main.resourceURL,
              let applicationSupportURL = FileManager.default.urls(
                for: .applicationSupportDirectory,
                in: .userDomainMask
              ).first else {
            return nil
        }
        let toolsURL = resourceURL
            .appendingPathComponent("tools", isDirectory: true)
            .standardizedFileURL
        let toolURL = toolsURL
            .appendingPathComponent(toolName, isDirectory: false)
            .standardizedFileURL
        guard toolURL.deletingLastPathComponent() == toolsURL,
              toolsURL.resolvingSymlinksInPath() == toolsURL,
              toolURL.resolvingSymlinksInPath() == toolURL,
              let toolsValues = try? toolsURL.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
              ),
              toolsValues.isDirectory == true,
              toolsValues.isSymbolicLink != true,
              let toolValues = try? toolURL.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
              ),
              toolValues.isRegularFile == true,
              toolValues.isSymbolicLink != true,
              FileManager.default.isExecutableFile(atPath: toolURL.path) else {
            return nil
        }

        let supportURL = applicationSupportURL
            .appendingPathComponent("BlackLabel", isDirectory: true)
            .standardizedFileURL
        var environment = ProcessInfo.processInfo.environment
        for key in environment.keys where key.hasPrefix("ACE_") {
            environment.removeValue(forKey: key)
        }
        environment["ACE_EFFECT_GUARD_SUPPORT_DIRECTORY"] = supportURL.path
        environment["ACE_STEALTH_MARKER"] = supportURL
            .appendingPathComponent("stealth-active", isDirectory: false).path
        environment["ACE_STEALTH_INTENT"] = supportURL
            .appendingPathComponent(
                StealthDurableIntent.fileName,
                isDirectory: false
            ).path

        let process = Process()
        process.executableURL = toolURL
        process.arguments = arguments
        process.environment = environment
        process.standardInput = FileHandle.nullDevice
        process.standardError = FileHandle.nullDevice
        let outputPipe = Pipe()
        process.standardOutput = outputPipe
        guard let outputCapture = try? BoundedPipeCapture(
            handle: outputPipe.fileHandleForReading, limit: 1048576
        ) else { return nil }
        defer { outputCapture.discard() }

        let processCutoff = MailToolProcessCutoff()
        let cutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                processCutoff.cancelSynchronously()
            }
        defer {
            processCutoff.clear()
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier
            )
        }

        do {
            let launched = try StealthEntryLatch.shared.performUnlessRaised {
                try process.run()
                processCutoff.register(process)
                return true
            }
            guard launched == true else { return nil }
            emailReadProcess = process
        } catch {
            return nil
        }

        let deadline =
            DispatchTime.now().uptimeNanoseconds
                &+ (timeoutSeconds * 1_000_000_000)
        while process.isRunning {
            guard !Task.isCancelled,
                  directEffectsAreAllowed else {
                RunningProcessBox.terminateProcessTree(process)
                return nil
            }
            if DispatchTime.now().uptimeNanoseconds >= deadline {
                RunningProcessBox.terminateProcessTree(process)
                appendRouteReceipt(
                    "READ-TOOL \(toolName) timed out; outcome unknown; "
                        + "no automatic retry"
                )
                return nil
            }
            try? await Task.sleep(for: .milliseconds(50))
        }

        let capturedOutput = outputCapture.finish()
        guard !capturedOutput.truncated, !capturedOutput.readFailed else {
            return nil
        }
        let outputData = capturedOutput.data
        let output = String(data: outputData, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return EmailReadToolResult(
            terminationStatus: process.terminationStatus,
            standardOutput: output
        )
    }

    /// Answers a "put it on the projector" request honestly.
    ///
    /// The failure this exists to prevent is the worst one on a stage: Ace
    /// saying "of course" while the projector stays dark. A missing second
    /// display is reported out loud, and an unnamed request asks what to play
    /// rather than letting Ace choose media in a room full of people.
    private func performSecondDisplayMediaRequest(requestedContent: String) {
        guard directEffectsAreAllowed else {
            appendRouteReceipt("SECOND-DISPLAY deferred — stealth active")
            return
        }
        let attachedDisplayCount = NSScreen.screens.count
        let admission = SecondDisplayMediaPolicy.admit(
            requestedContent: requestedContent,
            attachedDisplayCount: attachedDisplayCount
        )
        let spoken: String
        switch admission {
        case .noSecondDisplay:
            appendRouteReceipt(
                "SECOND-DISPLAY none attached displays=\(attachedDisplayCount)")
            spoken = SecondDisplayMediaPolicy.spokenNoSecondDisplay
        case .askWhatToPlay:
            appendRouteReceipt(
                "SECOND-DISPLAY asked for content displays=\(attachedDisplayCount)")
            spoken = SecondDisplayMediaPolicy.spokenAskWhatToPlay
        case let .play(content):
            // Ace states the destination and hands the naming back to the
            // owner's normal confirmed effect path; it does not silently
            // reach into a media library from here.
            appendRouteReceipt(
                "SECOND-DISPLAY target named displays=\(attachedDisplayCount)")
            spoken = SecondDisplayMediaPolicy.spokenSending(content)
        }
        showVisibleResponse(spoken)
        Task { [weak self] in
            try? await self?.noraVoice.speakText(spoken)
        }
    }

    /// Opens one owner-built dashboard by running its own `run.command`, which
    /// is written by trusted app code at build time and starts Ace's sealed
    /// loopback host. Ace never composes a host command line here: it resolves
    /// one directory inside `~/Ace Projects` and launches the launcher that
    /// already lives there, so the read-tool allowlist stays exactly the one
    /// the owner approved when the dashboard was built.
    /// Waits for the dashboard host's ACE_DASHBOARD_READY stdout line. EOF
    /// before the line means the host exited (bad config, dead port,
    /// entitlement refusal) and the spoken result must say so instead of
    /// announcing a dashboard that never appeared.
    nonisolated private static func waitForDashboardReadyLine(
        on handle: FileHandle,
        timeout: TimeInterval
    ) async -> Bool {
        final class ReadyWait: @unchecked Sendable {
            let lock = NSLock()
            var finished = false
            var buffer = Data()
        }
        let waitState = ReadyWait()
        return await withCheckedContinuation { continuation in
            let finish: @Sendable (Bool) -> Void = { hostIsReady in
                waitState.lock.lock()
                let alreadyFinished = waitState.finished
                waitState.finished = true
                waitState.lock.unlock()
                guard !alreadyFinished else { return }
                handle.readabilityHandler = nil
                continuation.resume(returning: hostIsReady)
            }
            handle.readabilityHandler = { readHandle in
                let chunk = readHandle.availableData
                if chunk.isEmpty {
                    finish(false)
                    return
                }
                waitState.lock.lock()
                waitState.buffer.append(chunk)
                let hostIsReady = String(
                    decoding: waitState.buffer, as: UTF8.self
                ).contains("ACE_DASHBOARD_READY")
                let bufferOverflowed = waitState.buffer.count > 64 * 1024
                waitState.lock.unlock()
                if hostIsReady {
                    finish(true)
                } else if bufferOverflowed {
                    finish(false)
                }
            }
            DispatchQueue.global().asyncAfter(deadline: .now() + timeout) {
                finish(false)
            }
        }
    }

    private func performDashboardOpen(spokenName: String) {
        guard directEffectsAreAllowed else {
            appendRouteReceipt("DASHBOARD deferred — stealth active")
            return
        }
        let fileManager = FileManager.default
        let home = fileManager.homeDirectoryForCurrentUser
        let projectsRoot = home
            .appendingPathComponent("Ace Projects", isDirectory: true)
            .standardizedFileURL

        // A candidate is a directory that carries BOTH the page and the
        // app-written launcher. Anything else is not a runnable dashboard.
        let candidates: [String] = ((try? fileManager.contentsOfDirectory(
            atPath: projectsRoot.path
        )) ?? []).filter { name in
            guard !name.hasPrefix("."),
                  let root = DashboardOpenPolicy.projectRootURL(
                    for: name,
                    homeDirectory: home
                  ) else { return false }
            var isDirectory: ObjCBool = false
            guard fileManager.fileExists(
                atPath: root.path,
                isDirectory: &isDirectory
            ), isDirectory.boolValue else { return false }
            return fileManager.fileExists(
                atPath: root.appendingPathComponent("index.html").path
            ) && fileManager.isExecutableFile(
                atPath: root.appendingPathComponent("run.command").path
            )
        }

        switch DashboardOpenPolicy.resolve(
            spokenName: spokenName,
            availableProjects: candidates
        ) {
        case .none:
            appendRouteReceipt(
                "DASHBOARD none matched spoken=\(spokenName.isEmpty ? "<unqualified>" : spokenName)")
            showVisibleResponse(DashboardOpenPolicy.spokenNoneFound)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(
                    DashboardOpenPolicy.spokenNoneFound
                )
            }
        case let .ambiguous(options):
            let line = DashboardOpenPolicy.spokenAmbiguity(options)
            appendRouteReceipt(
                "DASHBOARD ambiguous count=\(options.count) — asked instead of guessing")
            showVisibleResponse(line)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(line)
            }
        case let .resolved(projectName):
            guard let root = DashboardOpenPolicy.projectRootURL(
                for: projectName,
                homeDirectory: home
            ) else {
                appendRouteReceipt("DASHBOARD refused unsafe project path")
                return
            }
            let launcher = root
                .appendingPathComponent("run.command", isDirectory: false)
                .standardizedFileURL
            guard launcher.deletingLastPathComponent() == root,
                  launcher.resolvingSymlinksInPath() == launcher,
                  fileManager.isExecutableFile(atPath: launcher.path) else {
                appendRouteReceipt("DASHBOARD refused unsafe launcher")
                return
            }
            appendRouteReceipt("DASHBOARD opening project=\(projectName)")
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/bin/zsh")
            process.arguments = [launcher.path]
            process.currentDirectoryURL = root
            process.standardInput = FileHandle.nullDevice
            // The host prints ACE_DASHBOARD_READY once its listener is bound
            // and the browser open was attempted. Discarding stdout meant a
            // host that died on a bad config, dead port, or entitlement was
            // still announced as "opening" with nothing on screen.
            let readinessPipe = Pipe()
            process.standardOutput = readinessPipe
            process.standardError = FileHandle.nullDevice
            do {
                try StealthEntryLatch.shared.performUnlessRaised {
                    try process.run()
                }
            } catch {
                appendRouteReceipt("DASHBOARD launch failed")
                let line = "i couldn't start that dashboard."
                showVisibleResponse(line)
                Task { [weak self] in
                    try? await self?.noraVoice.speakText(line)
                }
                return
            }
            Task { @MainActor [weak self] in
                let readinessHandle = readinessPipe.fileHandleForReading
                let becameReady = await Self.waitForDashboardReadyLine(
                    on: readinessHandle,
                    timeout: 8
                )
                // Keep draining so the host never blocks on a full pipe.
                readinessHandle.readabilityHandler = { handle in
                    if handle.availableData.isEmpty {
                        handle.readabilityHandler = nil
                    }
                }
                guard let self else { return }
                guard becameReady else {
                    self.appendRouteReceipt(
                        "DASHBOARD host never reported ready project=\(projectName)"
                    )
                    let line = "that dashboard didn't come up."
                    self.showVisibleResponse(line)
                    try? await self.noraVoice.speakText(line)
                    return
                }
                self.appendRouteReceipt(
                    "DASHBOARD ready project=\(projectName)"
                )
                let line = "opening \(projectName.lowercased())."
                self.showVisibleResponse(line)
                try? await self.noraVoice.speakText(line)
            }
        }
    }

    private func applyTradingModeState(
        active: Bool,
        interpretedTraining: Bool = false
    ) -> String {
        if active {
            tradingLane.activate()
            tradingDataStatus = .unavailable(
                reason:
                    "No chart has been captured for a turn yet. Screen context is turn-scoped, not continuous surveillance."
            )
            // Publish the mode flag last so SwiftUI never renders the active
            // button beside the previous inactive status text.
            tradingModeActive = true
            return (interpretedTraining
                ? "I interpreted training mode as Trading Mode. " : "")
                + "Trading Mode is active and analysis-only. Ask a chart or "
                + "market question and Ace will capture the selected display "
                + "for that turn. Ace never places trades or bets."
        }

        tradingLane.deactivate()
        tradingModeActive = false
        tradingDataStatus = .inactive
        return interpretedTraining
            ? "I interpreted training mode as Trading Mode. Trading Mode is off."
            : "Trading Mode is off."
    }

    func toggleTradingModeFromPanel() {
        guard directEffectsAreAllowed else { return }
        let entering = !tradingLane.isActive
        let reason = applyTradingModeState(active: entering)
        appendRouteReceipt(
            "TRADING panel state=\(entering ? "active" : "off") executor=none"
        )
        showVisibleResponse(reason)
        Task { [weak self] in
            try? await self?.noraVoice.speakText(reason)
        }
    }

    private func routeTradingModeControlIfPresent(
        _ utterance: String,
        context: OwnerTurnContext
    ) -> Bool {
        guard let command = TradingModeControlPolicy.command(
            for: utterance
        ) else { return false }
        guard bindOwnerTurnContext(context) != nil,
              let workID = activeContextualOwnerRequest?
                .childWorkCorrelationIdentifier else {
            return true
        }
        _ = bindRunningWorkDurably(
            workCorrelationIdentifier: workID,
            lane: .trading,
            durableLane: "trading"
        )
        let interpretedTraining: Bool
        let exitsMode: Bool
        switch command {
        case .enter(let wasTraining):
            interpretedTraining = wasTraining
            exitsMode = false
        case .exit(let wasTraining):
            interpretedTraining = wasTraining
            exitsMode = true
        }
        let reason = applyTradingModeState(
            active: !exitsMode,
            interpretedTraining: interpretedTraining
        )
        _ = persistDirectWorkTerminal(
            workCorrelationIdentifier: workID,
            lane: .trading,
            durableLane: "trading",
            status: .completed,
            outcome: exitsMode
                ? "completed.trading-exit"
                : "completed.trading-enter",
            verification: "app-owned-lane-state",
            reason: reason
        )
        showVisibleResponse(reason)
        Task { [weak self] in
            try? await self?.noraVoice.speakText(reason)
        }
        return true
    }

    /// Creates and manages the buyer's exact three-HTTPS-source briefing from
    /// the same admitted voice/text turn and durable work correlation.
    private func routeMorningLinkBriefIfPresent(
        _ utterance: String,
        context: OwnerTurnContext
    ) -> Bool {
        let configuration = MorningLinkBriefValidation
            .parsedConfiguration(from: utterance)
        let control = MorningLinkBriefValidation.control(from: utterance)
        guard configuration != nil || control != nil else { return false }
        guard bindOwnerTurnContext(context) != nil,
              let workID = activeContextualOwnerRequest?
                .childWorkCorrelationIdentifier else {
            return true
        }
        _ = bindRunningWorkDurably(
            workCorrelationIdentifier: workID,
            lane: .briefing,
            durableLane: "briefing"
        )

        let publishImmediate: (
            AceGoldWorkStatus,
            String,
            String
        ) -> Void = { [weak self] status, outcome, reason in
            guard let self else { return }
            _ = self.persistDirectWorkTerminal(
                workCorrelationIdentifier: workID,
                lane: .briefing,
                durableLane: "briefing",
                status: status,
                outcome: outcome,
                verification: status == .completed
                    ? "app-owned-state-readback" : "none",
                reason: reason
            )
            self.showVisibleResponse(reason)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(reason)
            }
        }

        if let configuration {
            let saved = morningLinkBriefRuntime.configure(
                sourceStrings: configuration.sourceStrings,
                hour: configuration.hour,
                minute: configuration.minute
            )
            publishImmediate(
                saved ? .completed : .failed,
                saved ? "completed.briefing-armed" : "failed.briefing-save",
                saved
                    ? morningLinkBriefRuntime.statusDescription()
                    : (morningLinkBriefRuntime.lastControlError
                        ?? "The briefing was not saved.")
            )
            return true
        }

        guard let control else { return true }
        switch control {
        case .listOrStatus:
            publishImmediate(
                .completed,
                "completed.briefing-status",
                morningLinkBriefRuntime.statusDescription()
            )
        case .pause:
            guard morningLinkBriefRuntime.schedule != nil else {
                publishImmediate(
                    .failed,
                    "failed.briefing-missing",
                    "No three-link morning briefing is configured."
                )
                return true
            }
            morningLinkBriefRuntime.setPaused(true)
            publishImmediate(
                .completed,
                "completed.briefing-paused",
                morningLinkBriefRuntime.statusDescription()
            )
        case .resume:
            guard morningLinkBriefRuntime.schedule != nil else {
                publishImmediate(
                    .failed,
                    "failed.briefing-missing",
                    "No three-link morning briefing is configured."
                )
                return true
            }
            morningLinkBriefRuntime.setPaused(false)
            publishImmediate(
                .completed,
                "completed.briefing-resumed",
                morningLinkBriefRuntime.statusDescription()
            )
        case .delete:
            guard morningLinkBriefRuntime.schedule != nil else {
                publishImmediate(
                    .failed,
                    "failed.briefing-missing",
                    "No three-link morning briefing is configured."
                )
                return true
            }
            morningLinkBriefRuntime.delete()
            publishImmediate(
                .completed,
                "completed.briefing-deleted",
                "The three-link morning briefing and its durable schedule were deleted."
            )
        case .edit:
            MenuBarPanelManager.shared?.showPanelForSettingsCommand()
            publishImmediate(
                .completed,
                "completed.briefing-edit-opened",
                "The editable three-link briefing controls are open in Ace."
            )
        case .runNow:
            let started = morningLinkBriefRuntime.runNow(completion: {
                [weak self]
                (terminalResult: String, allSourcesSucceeded: Bool) in
                guard let self else { return }
                _ = self.persistDirectWorkTerminal(
                    workCorrelationIdentifier: workID,
                    lane: .briefing,
                    durableLane: "briefing",
                    status: allSourcesSucceeded ? .completed : .failed,
                    outcome: allSourcesSucceeded
                        ? "completed.briefing-run"
                        : "failed.briefing-incomplete",
                    verification: allSourcesSucceeded
                        ? "three-source-fetch-and-summary" : "partial",
                    reason: terminalResult
                )
            })
            if started {
                upsertBuyerWorkReceipt(
                    workID: workID,
                    lane: .briefing,
                    phase: .executing,
                    progress:
                        "Fetching the three exact HTTPS sources with bounded GET-only access."
                )
            } else {
                publishImmediate(
                    .failed,
                    "failed.briefing-not-started",
                    morningLinkBriefRuntime.schedule == nil
                        ? "No three-link morning briefing is configured."
                        : "A morning briefing is already running."
                )
            }
        }
        return true
    }

    /// Restores the durable generic standing-task routes through the same
    /// admitted owner turn. The specialized three-link briefing route runs
    /// first and therefore never falls into this no-live-data scheduler.
    private func routeStandingTaskIfPresent(
        _ utterance: String,
        context: OwnerTurnContext
    ) -> Bool {
        let parsed = standingTaskRuntime.parse(utterance)
        let cancel = StandingTaskRuntime.extractCancelRequest(utterance)
        let isList = StandingTaskRuntime.isListRequest(utterance)
        guard parsed != nil || cancel.isCancelRequest || isList else {
            return false
        }
        guard bindOwnerTurnContext(context) != nil,
              let workID = activeContextualOwnerRequest?
                .childWorkCorrelationIdentifier else {
            return true
        }
        _ = bindRunningWorkDurably(
            workCorrelationIdentifier: workID,
            lane: .direct,
            durableLane: "standing-task"
        )

        let result: String
        let outcome: String
        let succeeded: Bool
        if let parsed {
            result = standingTaskRuntime.arm(
                parsed,
                approvedForDestructive: false
            )
            succeeded = result.lowercased().hasPrefix(
                "standing task armed"
            )
            outcome = succeeded
                ? "completed.standing-task-armed"
                : "failed.standing-task-not-armed"
        } else if cancel.isCancelRequest {
            result = standingTaskRuntime.cancelTasks(
                matching: cancel.keywords
            )
            succeeded = result.lowercased().hasPrefix("cancelled")
            outcome = succeeded
                ? "completed.standing-task-cancelled"
                : "failed.standing-task-cancel"
        } else {
            result = standingTaskRuntime.spokenTaskList()
            succeeded = true
            outcome = "completed.standing-task-status"
        }
        _ = persistDirectWorkTerminal(
            workCorrelationIdentifier: workID,
            lane: .direct,
            durableLane: "standing-task",
            status: succeeded ? .completed : .failed,
            outcome: outcome,
            verification: succeeded
                ? "app-owned-standing-task-store" : "none",
            reason: result
        )
        showVisibleResponse(result)
        Task { [weak self] in
            try? await self?.noraVoice.speakText(result)
        }
        return true
    }

    /// Reads every morning-brief source through the bundled read-only wrappers
    /// and speaks ONE assembled brief. No model is involved: the words the
    /// owner hears are the readers' real output, and any reader that fails is
    /// named out loud instead of silently dropped.
    private func performMorningBrief() {
        guard directEffectsAreAllowed else {
            appendRouteReceipt("BRIEF deferred — stealth active")
            return
        }
        appendRouteReceipt("ROUTE morning-brief (app-owned, no model)")
        morningBriefTask?.cancel()
        morningBriefTask = Task { @MainActor [weak self] in
            guard let self else { return }
            // Sources run CONCURRENTLY. Measured 2026-08-07: `email-read` hangs
            // for minutes when Mail automation is ungranted, and a sequential
            // brief would make every other source wait behind it — the whole
            // point of a brief is that it arrives while you're still listening.
            // The brief also uses a much tighter deadline than the 45s inbox
            // route: a reader that cannot answer in time is reported as
            // unavailable, which is information, not a stall.
            let results = await withTaskGroup(
                of: (Int, MorningBriefPolicy.SourceResult).self
            ) { group -> [MorningBriefPolicy.SourceResult] in
                for (index, source) in MorningBriefPolicy.sources.enumerated() {
                    group.addTask { @MainActor [weak self] in
                        guard let self else {
                            return (
                                index,
                                MorningBriefPolicy.SourceResult(
                                    source: source,
                                    succeeded: false,
                                    output: ""
                                )
                            )
                        }
                        let toolResult = await self.runBundledReadTool(
                            named: source.tool,
                            arguments: [],
                            timeoutSeconds:
                                MorningBriefPolicy
                                    .sourceTimeoutSeconds
                        )
                        let succeeded = toolResult?.terminationStatus == 0
                        self.appendRouteReceipt(
                            "BRIEF source=\(source.tool) ok=\(succeeded) "
                                + "chars=\(toolResult?.standardOutput.count ?? 0)"
                        )
                        return (
                            index,
                            MorningBriefPolicy.SourceResult(
                                source: source,
                                succeeded: succeeded,
                                output: toolResult?.standardOutput ?? ""
                            )
                        )
                    }
                }
                var collected: [(Int, MorningBriefPolicy.SourceResult)] = []
                for await entry in group { collected.append(entry) }
                // Spoken order is the declared source order, never whichever
                // reader happened to finish first.
                return collected.sorted { $0.0 < $1.0 }.map(\.1)
            }
            guard !Task.isCancelled, self.directEffectsAreAllowed else { return }
            let spoken = MorningBriefPolicy.spokenBrief(
                from: results,
                greeting: MorningBriefPolicy.greeting(for: Date())
            )
            self.showVisibleResponse(spoken)
            self.appendRouteReceipt(
                "BRIEF spoken sources=\(results.count) "
                    + "failed=\(results.filter { !$0.succeeded }.count)"
            )
            try? await self.noraVoice.speakText(spoken)
        }
    }

    /// A read-only inbox ask: a read verb AND an email word ("check my email",
    /// "read my last three emails", "any new email?", "what's in my inbox").
    /// Send/compose asks carry task verbs and are routed (and floor-gated)
    /// before this is ever consulted.
    static func isEmailReadRequest(_ text: String) -> Bool {
        CrossAppActionPolicy.isEmailReadRequest(text)
    }

    /// Starts the notetaker and confirms out loud. The red gem stays lit for the
    /// whole meeting — a visible "Ace is in the meeting" indicator.
    /// Returns whether the start request was actually ACCEPTED and dispatched.
    ///
    /// This used to return Void while four paths refused silently, and both
    /// handoff callers published `outcome: .completed` with the words "the
    /// note-capture lane accepted the start request" regardless. A refusal for
    /// Private Mode, a pending review, an already-running session, or a failed
    /// durable bind was therefore reported to the owner as acceptance — a
    /// receipt asserting something that had not happened. Callers must branch
    /// on this instead of assuming.
    ///
    /// `true` means accepted and the async start was dispatched; it does NOT
    /// claim capture is running, which only `meetingNotetaker.isTakingNotes`
    /// can say.
    @discardableResult
    private func startMeetingNotes() -> Bool {
        guard directEffectsAreAllowed else {
            appendRouteReceipt("NOTES-ROUTE start refused (private mode)")
            return false
        }
        guard !meetingNotetaker.isRetryingMeetingNotes else {
            appendRouteReceipt(
                "NOTES-ROUTE start refused (notes retry still unwinding)"
            )
            showVisibleResponse(
                "The notes retry is still stopping. Start a new capture after it finishes."
            )
            return false
        }
        guard !meetingNotetaker.hasPendingMeetingNotesRetry else {
            appendRouteReceipt(
                "NOTES-ROUTE start refused (notes retry pending)"
            )
            showVisibleResponse(
                "Retry Notes & Flashcards or explicitly discard the pending "
                    + "in-memory capture before starting another meeting."
            )
            Task {
                try? await noraVoice.speakText(
                    "retry notes and flashcards, or discard the pending "
                        + "meeting capture before starting another one."
                )
            }
            return false
        }
        guard !meetingNotetaker.hasPendingGeneratedNotesReview else {
            appendRouteReceipt(
                "NOTES-ROUTE start refused (previous review pending)")
            Task {
                try? await noraVoice.speakText(
                    "review the last meeting notes first. click save these "
                        + "meeting notes, say save the notes, "
                        + "or say cancel.")
            }
            return false
        }
        guard !meetingNotetaker.isTakingNotes else {
            appendRouteReceipt("NOTES-ROUTE start ignored (already active)")
            showVisibleResponse("I'm already taking notes.")
            return false
        }
        appendRouteReceipt("NOTES-ROUTE start requested")
        var directNotesWorkID: UUID?
        if let request = activeContextualOwnerRequest,
           goldContextBundle.workRecords.first(where: {
               $0.workCorrelationIdentifier
                    == request.childWorkCorrelationIdentifier
           })?.lane == "direct" {
            guard bindRunningWorkDurably(
                workCorrelationIdentifier:
                    request.childWorkCorrelationIdentifier,
                lane: .notes,
                durableLane: "notes"
            ) else {
                appendRouteReceipt(
                    "NOTES-ROUTE start refused (durable work bind failed)")
                return false
            }
            directNotesWorkID = request.childWorkCorrelationIdentifier
            activeDirectNotesWorkCorrelationIdentifier = directNotesWorkID
        }
        Task { [weak self] in
            guard let self else { return }
            guard directEffectsAreAllowed else { return }
            // An explicit Notes start claims the audio session just like push
            // to talk. Flush both current and queued speech before capture
            // acquires its lease; otherwise the failure announcement itself
            // keeps every immediate retry blocked behind voice playback.
            noraVoice.stopPlayback()
            let started = await meetingNotetaker.start()
            guard directEffectsAreAllowed else { return }
            if started {
                backgroundTaskActive = true
                showCursorOverlayForBackgroundTask()
                // A stop may have landed during startup — the notetaker honors
                // it itself; don't announce a session the user already ended.
                if meetingNotetaker.isTakingNotes {
                    let sourceStatus = meetingNotetaker
                        .audioPreflightResult?.summary
                        ?? "Audio sources are ready."
                    let confirmation =
                        "Taking notes. \(sourceStatus) Draft notes will be reviewed before saving in \(meetingNotetaker.intendedNotesFolderPath). Say stop taking notes when you're done."
                    showVisibleResponse(confirmation)
                }
            } else if meetingNotetaker.isWindingDown {
                if let directNotesWorkID {
                    _ = self.finishDirectTextTerminal(
                        workCorrelationIdentifier: directNotesWorkID,
                        lane: .notes,
                        durableLane: "notes",
                        status: .blocked,
                        outcome: "blocked.notes-winding-down",
                        verification: "none",
                        reason:
                            "The previous note session is still wrapping up, so a new capture did not start.",
                        slot: .none,
                        source: .notes,
                        turnIdentifier: self.sourceTurnIdentifier(
                            forWork: directNotesWorkID
                        )
                    )
                    if self.activeDirectNotesWorkCorrelationIdentifier
                        == directNotesWorkID {
                        self.activeDirectNotesWorkCorrelationIdentifier = nil
                    }
                }
                appendRouteReceipt("NOTES-ROUTE start deferred (previous notes still wrapping up)")
                showVisibleResponse(
                    "Still wrapping up the last notes. Ask again in a moment."
                )
                try? await noraVoice.speakText(
                    "still wrapping up the last notes — give me a second, then ask again.")
            } else {
                let failureMessage = meetingNotetaker.startFailureMessage
                    ?? "Meeting Notes did not start. Try starting the capture again."
                if let directNotesWorkID {
                    _ = self.finishDirectTextTerminal(
                        workCorrelationIdentifier: directNotesWorkID,
                        lane: .notes,
                        durableLane: "notes",
                        status: .failed,
                        outcome: "failed.notes-start",
                        verification: "none",
                        reason: failureMessage,
                        slot: .none,
                        source: .notes,
                        turnIdentifier: self.sourceTurnIdentifier(
                            forWork: directNotesWorkID
                        )
                    )
                    if self.activeDirectNotesWorkCorrelationIdentifier
                        == directNotesWorkID {
                        self.activeDirectNotesWorkCorrelationIdentifier = nil
                    }
                }
                appendRouteReceipt("NOTES-ROUTE start FAILED (capture did not come up)")
                showVisibleResponse(failureMessage)
                try? await noraVoice.speakText(failureMessage)
            }
        }
        // Dispatched. Every refusal above returned false before reaching here,
        // so a caller that publishes acceptance on `true` is telling the truth.
        return true
    }

    /// The permanent buyer-visible Meeting Notes control uses the same
    /// admission, capture, and review path as the spoken command. Keeping the
    /// panel action here prevents a second UI-only notes implementation from
    /// drifting away from the production voice route.
    func startMeetingNotesFromPanel() {
        _ = startMeetingNotes()
    }

    func stopMeetingNotesFromPanel() {
        stopMeetingNotes()
    }

    func retryMeetingNotesFromPanel() {
        retryPendingMeetingNotes()
    }

    func discardPendingMeetingNotesRetryFromPanel() {
        guard directEffectsAreAllowed else { return }
        guard meetingNotetaker
            .discardPendingMeetingNotesRetryFromOwner() else {
            let currentState: String
            if meetingNotetaker.hasPendingGeneratedNotesReview {
                currentState =
                    "The captured meeting is already in review. Reopen the notes review to continue."
            } else if meetingNotetaker.result?.title
                == "Meeting capture expired" {
                currentState =
                    "That in-memory meeting capture already expired. Nothing was saved."
            } else {
                currentState =
                    "There is no pending in-memory meeting capture to discard."
            }
            appendRouteReceipt(
                "NOTES RETRY panel discard refused; no pending capture"
            )
            showVisibleResponse(currentState)
            return
        }
        appendRouteReceipt("NOTES RETRY explicitly discarded from panel")
        showVisibleResponse(
            "Discarded the pending in-memory meeting capture. Nothing was saved."
        )
    }

    func reopenMeetingNotesReviewFromPanel() {
        guard directEffectsAreAllowed else { return }
        let reopened = meetingNotetaker
            .reopenPendingGeneratedNotesReview()
        appendRouteReceipt(
            reopened
                ? "NOTES REVIEW reopened from panel"
                : "NOTES REVIEW reopen refused"
        )
        if !reopened {
            showVisibleResponse(
                "The generated notes review is no longer available."
            )
        }
    }

    private func retryPendingMeetingNotes(
        context: OwnerTurnContext? = nil
    ) {
        guard directEffectsAreAllowed,
              meetingNotetaker.hasPendingMeetingNotesRetry else {
            return
        }
        let voiceCorrelationIdentifier: UUID?
        if let context {
            guard let correlationIdentifier = activeRoutingCorrelationID else {
                return
            }
            guard ownerTurnLifecycle.deferManagerDispatch(
                for: context
            ) else {
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationIdentifier,
                    status: .failed,
                    outcome: "notes-retry-lifecycle-unavailable",
                    reason: "The notes retry could not retain its owner-turn lifecycle."
                )
                return
            }
            voiceCorrelationIdentifier = correlationIdentifier
        } else {
            voiceCorrelationIdentifier = nil
        }
        appendRouteReceipt("NOTES RETRY requested")
        showVisibleResponse("Retrying Detailed notes and Q/A Flashcards…")
        Task { [self] in
            guard directEffectsAreAllowed else {
                if let context,
                   let voiceCorrelationIdentifier {
                    _ = ownerTurnLifecycle.finishManagerDispatch(
                        turnID: context.turnID,
                        correlationID: voiceCorrelationIdentifier,
                        status: .cancelled,
                        outcome: "cancelled.notes-retry-privacy-transition"
                    )
                }
                return
            }
            let spokenSummary =
                await meetingNotetaker.retryPendingMeetingNotes()
            backgroundTaskActive = anyBackgroundExecutionAgentIsWorking
            let disposition = MeetingNotesRetryTerminalPolicy.disposition(
                hasGeneratedReview:
                    meetingNotetaker.hasPendingGeneratedNotesReview,
                hasPendingRetry:
                    meetingNotetaker.hasPendingMeetingNotesRetry
            )
            let outcome: String
            if spokenSummary.isEmpty {
                outcome = "cancelled.notes-retry-cancelled"
            } else {
                switch disposition {
                case .completedReview:
                    outcome = "completed.notes-review-produced"
                case .pendingRetry:
                    outcome = "blocked.notes-generation-retry-pending"
                case .failed:
                    outcome = "failed.notes-review-not-produced"
                }
            }
            appendRouteReceipt(
                "NOTES RETRY outcome=\(outcome)"
            )
            if let context,
               let voiceCorrelationIdentifier {
                let eventStatus: AceEventState = spokenSummary.isEmpty
                    ? .cancelled
                    : (disposition == .completedReview
                        ? .completed : .failed)
                let durableStatus: AceGoldWorkStatus
                if spokenSummary.isEmpty {
                    durableStatus = .cancelled
                } else {
                    switch disposition {
                    case .completedReview:
                        durableStatus = .completed
                    case .pendingRetry:
                        durableStatus = .blocked
                    case .failed:
                        durableStatus = .failed
                    }
                }
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: voiceCorrelationIdentifier,
                    status: eventStatus,
                    outcome: outcome,
                    reason: spokenSummary.isEmpty
                        ? "The notes retry was cancelled before a review was produced."
                        : spokenSummary,
                    durableVerification:
                        !spokenSummary.isEmpty
                            && disposition == .completedReview
                        ? "verified" : "none",
                    durableStatusOverride: durableStatus
                )
                return
            }
            guard directEffectsAreAllowed,
                  !spokenSummary.isEmpty else { return }
            showVisibleResponse(spokenSummary)
            try? await noraVoice.speakText(spokenSummary)
        }
    }

    /// Stops the notetaker (or latches a stop onto a session still starting up),
    /// generates the notes, opens the complete no-effect review, and speaks the
    /// exact save instruction. Persistence remains a separate owner action.
    private func stopMeetingNotes(
        commandTurnIdentifier: UUID? = nil,
        commandCorrelationIdentifier: UUID? = nil,
        announce: Bool = true
    ) {
        // A stop while start() is mid-flight must not be dropped — latch it and
        // the notetaker tears the fresh session down as its last startup step.
        if meetingNotetaker.isStartingUp, !meetingNotetaker.isTakingNotes {
            meetingNotetaker.stopRequestedDuringStartup = true
            appendRouteReceipt("NOTES-ROUTE stop latched during startup")
            let reason = "Okay — cancelling the notes."
            if !finishVolatileOwnerTurn(
                turnID: commandTurnIdentifier,
                correlationID: commandCorrelationIdentifier,
                status: .completed,
                outcome: "notes-stop-latched",
                reason: reason,
                showVisible: announce,
                speak: false
            ), announce {
                showVisibleResponse(reason)
            }
            return
        }
        guard meetingNotetaker.isTakingNotes else {
            appendRouteReceipt("NOTES-ROUTE stop ignored (not active)")
            let reason = "I'm not taking notes right now."
            if !finishVolatileOwnerTurn(
                turnID: commandTurnIdentifier,
                correlationID: commandCorrelationIdentifier,
                status: .completed,
                outcome: "notes-not-active",
                reason: reason,
                showVisible: announce,
                speak: announce
            ), announce {
                showVisibleResponse(reason)
                Task { try? await noraVoice.speakText(reason) }
            }
            return
        }
        appendRouteReceipt("NOTES-ROUTE stop requested")
        Task {
            if announce {
                showVisibleResponse("Wrapping up the notes now.")
            }
            let spokenSummary = await meetingNotetaker.stopAndProduceNotes()
            backgroundTaskActive = anyBackgroundExecutionAgentIsWorking
            let hasGeneratedReview =
                meetingNotetaker.hasPendingGeneratedNotesReview
            let hasPendingRetry =
                meetingNotetaker.hasPendingMeetingNotesRetry
            let directTerminalStatus: AceGoldWorkStatus = hasGeneratedReview
                ? .completed
                : (hasPendingRetry ? .blocked : .failed)
            let volatileTerminalStatus: AceEventState = hasGeneratedReview
                ? .completed
                : .failed
            let terminalOutcome = hasGeneratedReview
                ? "notes-review-produced"
                : (hasPendingRetry
                    ? "notes-generation-retry-pending"
                    : "notes-review-not-produced")
            var originalNotesTerminalWasPublished = false
            if let workID = activeDirectNotesWorkCorrelationIdentifier {
                originalNotesTerminalWasPublished = finishDirectTextTerminal(
                    workCorrelationIdentifier: workID,
                    lane: .notes,
                    durableLane: "notes",
                    status: directTerminalStatus,
                    outcome: hasGeneratedReview
                        ? "completed.\(terminalOutcome)"
                        : (hasPendingRetry
                            ? "blocked.\(terminalOutcome)"
                            : "failed.\(terminalOutcome)"),
                    verification: hasGeneratedReview ? "verified" : "none",
                    reason: spokenSummary,
                    slot: .none,
                    source: .notes,
                    turnIdentifier: sourceTurnIdentifier(forWork: workID),
                    speak: announce
                )
                if originalNotesTerminalWasPublished {
                    activeDirectNotesWorkCorrelationIdentifier = nil
                }
            }
            if let commandTurnIdentifier,
               let commandCorrelationIdentifier {
                _ = finishVolatileOwnerTurn(
                    turnID: commandTurnIdentifier,
                    correlationID: commandCorrelationIdentifier,
                    status: volatileTerminalStatus,
                    outcome: terminalOutcome,
                    reason: spokenSummary,
                    durableVerification:
                        hasGeneratedReview ? "verified" : "none",
                    durableStatusOverride: directTerminalStatus,
                    showVisible:
                        announce && !originalNotesTerminalWasPublished,
                    speak:
                        announce && !originalNotesTerminalWasPublished
                )
            } else if announce && !originalNotesTerminalWasPublished {
                showVisibleResponse(spokenSummary)
                try? await noraVoice.speakText(spokenSummary)
            }
        }
    }

    /// Observability: runs a short capture → notes cycle without voice, driven by
    /// the RUN_NOTES flag file, so the whole pipeline can be verified headlessly.
    func debugRunMeetingNotes(seconds: Int) {
        startMeetingNotes()
        Task {
            try? await Task.sleep(for: .seconds(Double(seconds)))
            stopMeetingNotes()
        }
    }

    /// Standing tasks remain limited to non-consequential reasoning. The
    /// complete scheduled-work capability receipt must already exist; an
    /// unattended timer never opens or infers that buyer approval.
    private(set) lazy var standingTaskRuntime = StandingTaskRuntime(
        executeInstruction: { [weak self] instruction, approvedForDestructive in
            guard let self,
                  self.hasCompleteAgentCapabilityConsent() else {
                return "FAILED: scheduled background access is not approved on this Mac. Open Ace and approve the complete access list."
            }
            guard !approvedForDestructive,
                  !CrossAppActionPolicy.requiresConfirmation(
                    instruction
                  ) else {
                return "FAILED: unattended app, file, web, and message actions "
                    + "have no execution authority; ask while present."
            }
            let result = await self.backgroundAgent.run(
                instruction: instruction,
                screenshotPaths: [],
                provider: BrainBackend.selectedCLI
            )
            return result.spokenSummary
                ?? "FAILED: " + result.reason
        },
        isExecutorBusy: { [weak self] in
            // Never stack two reasoning processes; the process box and red gem
            // both assume one task at a time.
            self?.backgroundAgent.isWorking ?? true
        },
        announce: { [weak self] spokenLine in
            guard let self else { return false }
            // A scheduled result must never talk over a meeting capture — the
            // transcript would eat Ace's own voice. The receipt still lands.
            if self.meetingNotetaker.isTakingNotes || self.meetingNotetaker.isStartingUp { return false }
            self.showVisibleResponse(spokenLine)
            Task { try? await self.noraVoice.speakText(spokenLine, from: .red, priority: .background) }
            return true
        },
        mayManage: { [weak self] in
            guard let self else { return false }
            return self.directEffectsAreAllowed
                && !self.stealthMode.isActive
                && !StealthEntryLatch.shared.isRaised
                && !StealthVisibilityGate.shared.isActive
                && AceLicense.shared.admits(.standingTask)
        }
    )

    private(set) lazy var morningLinkBriefRuntime =
        MorningLinkBriefRuntime(
            speak: { [weak self] spokenLine in
                guard let self,
                      self.directEffectsAreAllowed,
                      !self.stealthMode.isActive,
                      !self.meetingCaptureOwnsVoiceOutput else {
                    return false
                }
                self.showVisibleResponse(spokenLine)
                Task {
                    try? await self.noraVoice.speakText(
                        spokenLine,
                        from: .red,
                        priority: .background
                    )
                }
                return true
            },
            summarize: { evidence in
                let isolatedSummarizer = ClaudeAPI(proxyURL: "")
                let response = try await isolatedSummarizer.analyzeImage(
                    images: [],
                    systemPrompt:
                        "You are Ace's no-tools morning-brief summarizer. Use only supplied evidence. Return concise spoken prose. Never claim a failed or absent source was read.",
                    userPrompt: evidence,
                    providerTurn: .capture()
                )
                return response.text
            }
        )

    /// The silver build lane — whole-job workflows. It shares Red's complete
    /// buyer capability approval, then adds one exact per-job confirmation.
    /// Its announcements ride background priority so a running build narrates
    /// without cutting off a foreground answer.
    private(set) lazy var workflowRuntime = WorkflowRuntime(
        announce: { [weak self] spokenLine in
            guard let self, !spokenLine.isEmpty else { return }
            // Same rule the red lane keeps: a build's progress must not talk
            // over a meeting capture and land Ace's own voice in the transcript.
            if self.meetingNotetaker.isTakingNotes
                || self.meetingNotetaker.isStartingUp { return }
            self.showVisibleResponse(spokenLine)
            Task {
                try? await self.noraVoice.speakText(
                    spokenLine, from: .green, priority: .background)
            }
        }
    )

    /// Verbs that mark an utterance as a TASK to perform rather than a question.
    // Conservative fast-path: only unambiguous imperatives dispatch directly.
    // Ambiguous phrasing falls through to the gold overhead, whose output has
    // no authority to start another provider call or task.
    private static let taskVerbPattern =
        #"(?i)^\s*(please\s+)?(i\s+(want|need)\s+you\s+to\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|go\s+ahead\s+and\s+)?(open|reopen|launch|relaunch|restart|go\s+to|switch\s+to|bring\s+up|pull\s+up|take\s+me\s+to|focus\s+on|create|make|build|install|uninstall|run|execute|write|rename|move|download|delete|remove|send|email|compose|reply|forward|organize|configure|set\s+up|generate|draft|change|set|turn\s+(on|off|up|down)|enable|disable|adjust|increase|decrease|raise|lower|mute|unmute|play|pause|skip|close|quit|exit\s+out|clean\s*up|tidy\s*up|declutter|google|research|look\s+up|search\s+(the\s+web|online)(\s+for)?)\b"#

    private func looksLikeTask(_ text: String) -> Bool {
        text.range(of: Self.taskVerbPattern, options: .regularExpression) != nil
    }

    /// Leading "hey ace," / "ace." hail before the actual request. `\b` keeps
    /// words like "aces" intact; anything the strip leaves empty was a pure hail.
    private static let assistantNamePrefixPattern = #"(?i)^\s*(?:hey[,\s]+)?ace\b[,.!\s]*"#

    private func strippingAssistantName(_ text: String) -> String {
        text.replacingOccurrences(
            of: Self.assistantNamePrefixPattern, with: "", options: .regularExpression
        ).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// One leading filler token. "is" is special-cased: it only counts as
    /// filler when what follows is command-shaped ("IS i need you to open…"),
    /// so real questions ("is my wifi on") pass through untouched.
    private static let leadingFillerPattern =
        #"(?i)^(?:(?:so|um|uh|okay|ok|well|yeah|oh|now|and|but|alright)[,\s]+|is[,\s]+(?=(?:i|please|can|could|would|open|find|locate|go|switch|launch|show|take|make|create|set|turn|play|type)\b))"#

    private func strippingLeadingFiller(_ text: String) -> String {
        text.replacingOccurrences(
            of: Self.leadingFillerPattern, with: "", options: .regularExpression
        ).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func isInstantLaneCommandForRelease(
        _ transcript: String
    ) -> Bool {
        var utterance = strippingAssistantName(
            transcript.trimmingCharacters(
                in: .whitespacesAndNewlines
            )
        )
        utterance = strippingLeadingFiller(utterance)
        guard !utterance.isEmpty else { return false }
        return BuddyDictationPartialSubmissionPolicy.admits(utterance)
    }

    /// Whole-utterance silence commands. Anchored to the full utterance so task
    /// phrasing like "stop the music" still reaches task routing.
    private func isStopCommand(_ text: String) -> Bool {
        OwnerTurnCoordinator.isStopRequest(text)
    }

    /// One replacement utterance, lifecycle stop, or privacy transition removes
    /// every direct-effect approval surface. No later generic confirmation may
    /// inherit authority across that boundary.
    private func discardPendingDirectEffectConfirmations() {
        let discardedHQConfirmation = pendingAceHQConfirmation
        let discardedHQExecutionConfirmation =
            pendingAceHQExecutionConfirmation
        let discardedHQCapability = pendingAceHQCapabilityRequest
        pendingAceHQConfirmation = nil
        pendingAceHQExecutionConfirmation = nil
        pendingAceHQCapabilityRequest = nil
        if let discardedHQExecutionConfirmation {
            completeAceHQBeforeDispatch(
                discardedHQExecutionConfirmation.request,
                status: .cancelled,
                message:
                    "The pending HQ exact-execution review was discarded. Nothing ran.",
                speak: false,
                authority: .executeWhitelisted
            )
        } else if let discardedHQConfirmation {
            completeAceHQBeforeDispatch(
                discardedHQConfirmation.request,
                status: .cancelled,
                message:
                    "The pending HQ exact-plan review was discarded. Nothing ran.",
                speak: false
            )
        } else if let discardedHQCapability {
            completeAceHQBeforeDispatch(
                discardedHQCapability.request,
                status: .cancelled,
                message:
                    "The pending HQ capability review was discarded. Nothing ran.",
                speak: false
            )
        }
        let consentDirectWorkIdentifier =
            pendingAgentCapabilityConsent?
                .directWorkCorrelationIdentifier
        let consentLane = pendingAgentCapabilityConsent?.lane
        let directWorkflowWorkIdentifier =
            pendingDirectWorkflowWorkCorrelationIdentifier
                ?? (consentLane == .silver
                    ? consentDirectWorkIdentifier
                    : nil)
        if pendingDirectWorkflowWorkCorrelationIdentifier == nil {
            pendingDirectWorkflowWorkCorrelationIdentifier =
                directWorkflowWorkIdentifier
        }
        directWorkflowConfirmationExpiryTask?.cancel()
        directWorkflowConfirmationExpiryTask = nil
        _ = workflowRuntime.cancelPendingJob()
        if let pending = pendingAgentCapabilityConsent,
           let review = appActionReview,
           review.planIdentifier == pending.reviewIdentifier {
            appActionReview = AppActionReviewState(
                planIdentifier: review.planIdentifier,
                exactPreview: review.exactPreview,
                phase: .notArmed(
                    reason:
                        "Silver workflow approval was cancelled."
                )
            )
        }
        pendingAgentCapabilityConsent = nil
        agentCapabilityConsentExpiryTask?.cancel()
        agentCapabilityConsentExpiryTask = nil
        appActionBroker.discardCurrentPlan()
        appActionReviewExpiryTask?.cancel()
        appActionReviewExpiryTask = nil
        pendingCloseSweep = nil
        pendingMemoryWipeConfirmation = nil
        pendingTestEmailSend = nil
        testEmailExpiryTask?.cancel()
        testEmailExpiryTask = nil
        clearPendingAppleMailDraftRequest()
        clearPendingAppleMessagesRequest()
        completeDurableAppAction(
            status: .cancelled,
            outcome: "approval-discarded",
            verification: "none",
            reason:
                "The pending app action was discarded before execution."
        )
        _ = finishDirectWorkTerminal(
            workCorrelationIdentifier: directWorkflowWorkIdentifier,
            lane: .silver,
            durableLane: "silver",
            status: .cancelled,
            outcome: "cancelled.approval-discarded",
            verification: "none",
            reason:
                "The pending workflow approval was discarded before execution.",
            slot: .pendingWorkflow
        )
    }

    /// A hidden confirmation card carries no authority. Closing the panel,
    /// clicking outside it, or toggling its menu-bar item cancels any readback
    /// or armed plan before the panel disappears.
    func dismissVisibleAppActionReview() {
        if let pending = pendingAceHQExecutionConfirmation {
            pendingAceHQExecutionConfirmation = nil
            pendingAceHQConfirmation = nil
            completeAceHQBeforeDispatch(
                pending.request,
                status: .cancelled,
                message:
                    "The HQ exact-execution review was dismissed. Nothing ran.",
                speak: false,
                authority: .executeWhitelisted
            )
        } else if let pending = pendingAceHQConfirmation {
            pendingAceHQConfirmation = nil
            completeAceHQBeforeDispatch(
                pending.request,
                status: .cancelled,
                message:
                    "The HQ exact-plan review was dismissed. Nothing ran.",
                speak: false
            )
        }
        if let pending = pendingAceHQCapabilityRequest,
           let reviewIdentifier = pending.consentReviewIdentifier,
           appActionReview == nil
            || appActionReview?.planIdentifier == reviewIdentifier {
            pendingAceHQCapabilityRequest = nil
            completeAceHQBeforeDispatch(
                pending.request,
                status: .cancelled,
                message:
                    "The HQ capability review was dismissed. Nothing ran.",
                speak: false
            )
        }
        guard let review = appActionReview else {
            if pendingMailDraftIntentStore.pendingIntent != nil
                || appleMailSenderSelection != nil
                || appleMailNeedsConnection {
                clearPendingAppleMailDraftRequest()
                appendRouteReceipt(
                    "APPLE-MAIL pending sender state dismissed")
            }
            if pendingAppleMessagesIntentStore.pendingIntent != nil
                || appleMessagesRecipientSelection != nil
                || appleMessagesNeedsSignIn {
                clearPendingAppleMessagesRequest()
                appendRouteReceipt(
                    "APPLE-MESSAGES pending recipient state dismissed")
            }
            return
        }
        guard case .notArmed = review.phase else {
            noraVoice.stopPlayback()

            if pendingAgentCapabilityConsent?.reviewIdentifier
                == review.planIdentifier {
                let pendingDirectWork =
                    pendingAgentCapabilityConsent?
                        .directWorkCorrelationIdentifier
                let pendingDirectLane =
                    pendingAgentCapabilityConsent?.lane
                pendingAgentCapabilityConsent = nil
                agentCapabilityConsentExpiryTask?.cancel()
                agentCapabilityConsentExpiryTask = nil
                if pendingDirectLane == .silver {
                    if pendingDirectWorkflowWorkCorrelationIdentifier
                        == nil {
                        pendingDirectWorkflowWorkCorrelationIdentifier =
                            pendingDirectWork
                    }
                    _ = finishDirectWorkTerminal(
                        workCorrelationIdentifier:
                            pendingDirectWork,
                        lane: .silver,
                        durableLane: "silver",
                        status: .cancelled,
                        outcome: "cancelled.review-dismissed",
                        verification: "none",
                        reason:
                            "The full-access review was dismissed. Nothing ran.",
                        slot: .pendingWorkflow
                    )
                }
            }

            appActionPlanningGeneration = UUID()
            appActionPlanningTask?.cancel()
            appActionPlanningTask = nil
            claudeAPI.cancelInFlightAnswer()
            appActionReviewExpiryTask?.cancel()
            appActionReviewExpiryTask = nil
            appActionBroker.discardCurrentPlan()
            clearPendingAppleMailDraftRequest()
            clearPendingAppleMessagesRequest()

            testEmailGeneration = UUID()
            testEmailTask?.cancel()
            testEmailTask = nil
            isPreparingTestEmailSend = false
            pendingTestEmailSend = nil
            testEmailExpiryTask?.cancel()
            testEmailExpiryTask = nil
            if let process = testEmailProcess, process.isRunning {
                RunningProcessBox.terminateProcessTree(process)
            }
            testEmailProcess = nil

            backgroundTaskActive =
                meetingNotetaker.isTakingNotes
                    || anyBackgroundExecutionAgentIsWorking
            appActionReview = nil
            completeDurableAppAction(
                status: .cancelled,
                outcome: "review-dismissed",
                verification: "none",
                reason:
                    "The visible app-action review was dismissed; nothing ran."
            )
            appendRouteReceipt(
                "APP-ACTION visible review dismissed; no action remains armed")
            return
        }

        // A completed/refused card is only status; dismissing it must not
        // interrupt an already-confirmed operation whose result is still due.
        appActionReview = nil
    }

    /// A native-card click is a direct owner confirmation, equivalent to the
    /// exact whole utterance "confirm". SwiftUI keeps this unavailable until
    /// the immutable readback reports DONE.
    var preparedEmailReviewIsVisible: Bool {
        appActionReview?.planIdentifier == appActionPlanningGeneration
            && appActionBroker.hasPreparedEmailSend
    }

    func confirmVisibleAppActionReview() {
        guard AceLicense.shared.admits(.approval),
              directEffectsAreAllowed,
              let review = appActionReview,
              case .ready = review.phase else {
            return
        }

        if let pending = pendingAgentCapabilityConsent,
           pending.reviewIdentifier == review.planIdentifier {
            confirmAgentCapabilityConsent(
                pending,
                review: review
            )
            return
        }

        if resolvePendingAceHQConfirmation(with: "confirm") { return }

        if let pending = pendingTestEmailSend,
           pending.reviewIdentifier == review.planIdentifier {
            guard pending.isCurrent(at: Date()) else {
                pendingTestEmailSend = nil
                testEmailExpiryTask?.cancel()
                testEmailExpiryTask = nil
                appActionReview = AppActionReviewState(
                    planIdentifier: review.planIdentifier,
                    exactPreview: review.exactPreview,
                    phase: .notArmed(
                        reason: "Confirmation expired. Nothing was sent."
                    )
                )
                return
            }
            pendingTestEmailSend = nil
            testEmailExpiryTask?.cancel()
            testEmailExpiryTask = nil
            testEmailGeneration = UUID()
            testEmailTask?.cancel()
            testEmailTask = nil
            testEmailProcess = nil
            noraVoice.stopPlayback()
            appActionReview = AppActionReviewState(
                planIdentifier: review.planIdentifier,
                exactPreview: review.exactPreview,
                phase: .notArmed(
                    reason: "Confirmed once. Verifying Apple Mail now."
                )
            )
            performTestEmailSend(pending)
            return
        }

        if review.planIdentifier == appActionPlanningGeneration,
           appActionBroker.hasPreparedEmailSend {
            executePreparedAppAction(confirmation: "confirm")
            return
        }
        dismissVisibleAppActionReview()
    }

    private func resolvePendingAceHQConfirmation(with utterance: String) -> Bool {
        if let pendingExecution = pendingAceHQExecutionConfirmation {
            pendingAceHQExecutionConfirmation = nil
            let confirmationTime = Date()
            let exactPresentation =
                AceHQCompanionExecutionPolicy.presentation(
                    for: pendingExecution
                )
            guard let review = appActionReview,
                  review.planIdentifier
                    == pendingExecution.reviewIdentifier,
                  review.exactPreview == exactPresentation,
                  case .ready = review.phase,
                  pendingExecution.acceptsConfirmation(
                      reviewIdentifier: review.planIdentifier,
                      exactInstruction:
                        pendingExecution.exactInstruction,
                      executionTarget:
                        pendingExecution.executionTarget,
                      at: confirmationTime
                  ) else {
                completeAceHQBeforeDispatch(
                    pendingExecution.request,
                    status: .blocked,
                    message:
                        "That HQ exact-execution review was not fully presented, changed, or expired. Nothing ran.",
                    authority: .executeWhitelisted
                )
                appActionReview = nil
                return true
            }
            appActionReview = nil
            if CrossAppActionPolicy.isExplicitConfirmation(utterance) {
                guard let consentReceipt =
                        completeAgentCapabilityConsentReceipt(),
                      let intent =
                        AceHQCompanionExecutionPolicy.confirmedIntent(
                            review: pendingExecution,
                            reviewIdentifier:
                                review.planIdentifier,
                            presentedReview: review.exactPreview,
                            durableConsent:
                                durableHQCapabilityConsent(
                                    from: consentReceipt
                                ),
                            at: confirmationTime
                        ) else {
                    completeAceHQBeforeDispatch(
                        pendingExecution.request,
                        status: .blocked,
                        message:
                            "The exact execution target or durable capability approval is no longer valid. Nothing ran.",
                        authority: .executeWhitelisted
                    )
                    return true
                }
                beginAceHQDispatch(intent)
            } else if CrossAppActionPolicy.isExplicitCancellation(
                utterance
            ) {
                completeAceHQBeforeDispatch(
                    pendingExecution.request,
                    status: .cancelled,
                    message:
                        "The company execution request was cancelled. Nothing ran.",
                    authority: .executeWhitelisted
                )
            } else {
                completeAceHQBeforeDispatch(
                    pendingExecution.request,
                    status: .cancelled,
                    message:
                        "The pending company execution request was replaced. Nothing ran.",
                    speak: false,
                    authority: .executeWhitelisted
                )
                rerouteActiveOwnerTurn()
            }
            return true
        }

        if let pendingHQ = pendingAceHQConfirmation {
            pendingAceHQConfirmation = nil
            let confirmationTime = Date()
            guard let review = appActionReview,
                  review.planIdentifier
                    == pendingHQ.reviewIdentifier,
                  review.exactPreview == pendingHQ.exactPlan,
                  case .ready = review.phase,
                  pendingHQ.acceptsConfirmation(
                      reviewIdentifier: review.planIdentifier,
                      exactPlan: review.exactPreview,
                      at: confirmationTime
                  ) else {
                completeAceHQBeforeDispatch(
                    pendingHQ.request,
                    status: .blocked,
                    message:
                        "That HQ exact-plan review was not fully presented, changed, or expired. Nothing ran."
                )
                appActionReview = nil
                return true
            }
            appActionReview = nil
            if CrossAppActionPolicy.isExplicitConfirmation(utterance) {
                guard let consentReceipt =
                        completeAgentCapabilityConsentReceipt() else {
                    completeAceHQBeforeDispatch(
                        pendingHQ.request,
                        status: .blocked,
                        message:
                            "The durable capability approval is no longer valid. Nothing ran."
                    )
                    return true
                }
                let intent = AceHQCompanyWorkPolicy.makeIntent(
                    request: pendingHQ.request,
                    capability: pendingHQ.capability,
                authorizationRequirement: .consequentialPlan,
                durableConsent: durableHQCapabilityConsent(
                    from: consentReceipt
                ),
                    consentValidatedAt: confirmationTime,
                    exactPlanConfirmedAt: confirmationTime
                )
                beginAceHQDispatch(intent)
            } else if CrossAppActionPolicy.isExplicitCancellation(utterance) {
                completeAceHQBeforeDispatch(
                    pendingHQ.request,
                    status: .cancelled,
                    message: "The company-work request was cancelled. Nothing ran."
                )
            } else {
                completeAceHQBeforeDispatch(
                    pendingHQ.request,
                    status: .cancelled,
                    message:
                        "The pending company-work request was replaced. Nothing ran.",
                    speak: false
                )
                rerouteActiveOwnerTurn()
            }
            return true
        }

        return false
    }



    func cancelVisibleAppActionReview() {
        guard let review = appActionReview else { return }
        guard case .notArmed = review.phase else {
            if pendingAgentCapabilityConsent?.reviewIdentifier
                == review.planIdentifier {
                cancelAgentCapabilityConsent(
                    review: review,
                    reason:
                        "Full access was not approved. Company dispatch and silver workflows remain blocked."
                )
                return
            }
            dismissVisibleAppActionReview()
            appActionReview = AppActionReviewState(
                planIdentifier: review.planIdentifier,
                exactPreview: review.exactPreview,
                phase: .notArmed(
                    reason: "Cancelled. Nothing ran or was sent."
                )
            )
            return
        }
    }

    @discardableResult
    func openLatestWorkflowResult() -> AceControlActionOutcome {
        guard AceLicense.shared.admits(.workflow) else {
            let outcome = controlFailure(
                code: "workflow.not_entitled",
                message: "Link this Mac before opening workflow results.",
                recoveryTitle: "Link this Mac",
                recovery: .retry
            )
            workflowOpenControlOutcome = outcome
            return outcome
        }
        guard directEffectsAreAllowed else {
            let outcome = controlFailure(
                code: "workflow.private_mode",
                message: "Exit Private Mode before opening this result.",
                recoveryTitle: "Exit Private Mode and try again",
                recovery: .retry
            )
            workflowOpenControlOutcome = outcome
            return outcome
        }
        guard let receipt = verifiedLatestWorkflowArtifactReceipt() else {
            let outcome = controlFailure(
                code: "workflow.artifact_unavailable",
                message:
                    "That workflow result is missing or changed, so Ace did not open it.",
                recoveryTitle: "Run the workflow again",
                recovery: .retry
            )
            workflowOpenControlOutcome = outcome
            return outcome
        }
        let target = URL(fileURLWithPath: receipt.artifactPath)
        let outcome = AceWorkspaceOpenAction.perform(
            target: target,
            copy: AceWorkspaceOpenCopy(
                successMessage: "Opened the workflow result.",
                failureCode: "workflow.open_failed",
                failureMessage:
                    "macOS did not open the workflow result.",
                recoveryTitle: "Show the result in Finder",
                recovery: .revealFile(target)
            )
        )
        workflowOpenControlOutcome = outcome
        switch outcome {
        case .succeeded:
            appendRouteReceipt(
                "ARTIFACT open operation="
                    + receipt.operationID.uuidString.lowercased()
            )
        case let .failed(failure):
            showVisibleResponse(failure.message)
        case .started:
            break
        }
        return outcome
    }

