    @discardableResult
    func openLatestMeetingNotesFolder() -> AceControlActionOutcome {
        guard AceLicense.shared.admits(.meetingNotes) else {
            let outcome = controlFailure(
                code: "meeting_notes.not_entitled",
                message: "Link this Mac before opening Meeting Notes.",
                recoveryTitle: "Link this Mac",
