        }
        return outcome
    }

    private func controlFailure(
        code: String,
        message: String,
        recoveryTitle: String,
        recovery: AceRecoveryRoute
    ) -> AceControlActionOutcome {
        .failed(
            AceActionFailure(
                code: code,
                message: message,
                recoveryTitle: recoveryTitle,
                recovery: recovery
            )
        )
    }

    private func verifiedLatestWorkflowArtifactReceipt()
        -> ArtifactReceipt? {
        do {
            guard let receipt = try ArtifactReceiptStore.shared
                    .latestVerifiedDone() else {
                throw ArtifactReceiptStoreError.artifactUnavailable
            }
            latestWorkflowArtifactReceipt = receipt
            return receipt
        } catch {
            latestWorkflowArtifactReceipt = nil
            let message =
                "That workflow result is missing or changed, so Ace did not open it. The prior completion receipt is no longer valid."
            showVisibleResponse(message)
            appendRouteReceipt(
                "ARTIFACT open blocked verification-failed errorType="
                    + String(describing: type(of: error))
            )
            Task { try? await noraVoice.speakText(message) }
            return nil
        }
    }

    /// Kills every in-flight output channel: speech, the gold response task,
    /// the scanning act, and any running reasoning or planning task. Silence IS the
    /// reply — a spoken acknowledgment would defeat "be quiet".
    private func terminalizeRunningWorkForExplicitStop() {
        let runningRecords = goldContextBundle.workRecords.filter {
            $0.status == .running
                && $0.workCorrelationIdentifier
                    != activeDirectNotesWorkCorrelationIdentifier
        }
        let terminalReason =
            "Stopped by the owner. Nothing is still running under this work ID."

        for record in runningRecords {
            let lane = buyerLane(for: record.lane)
            let source: AceEventSource
            switch lane {
            case .gold: source = .gold
            case .partner: source = .partner
            case .red: source = .red
            case .silver: source = .silver
            case .notes: source = .notes
            case .direct, .hq, .trading, .briefing:
                source = .system
            }

            let slot: DeferredDirectWorkSlot
            if activeDirectRedWorkCorrelationIdentifier
                    == record.workCorrelationIdentifier {
                slot = .activeRed
            } else if activeDirectSilverWorkCorrelationIdentifier
                        == record.workCorrelationIdentifier {
                slot = .activeSilver
            } else if pendingDirectWorkflowWorkCorrelationIdentifier
                        == record.workCorrelationIdentifier {
                slot = .pendingWorkflow
            } else if activeDirectWorkflowWorkCorrelationIdentifier
                        == record.workCorrelationIdentifier,
                      let operationIdentifier =
                        activeDirectWorkflowOperationIdentifier {
                slot = .activeWorkflow(
                    operationIdentifier: operationIdentifier
                )
            } else {
                slot = .none
            }

            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    record.workCorrelationIdentifier,
                lane: lane,
                durableLane: record.lane,
                status: .cancelled,
                outcome: "cancelled.owner-stop",
                verification: "app-owned-owner-stop",
                reason: terminalReason,
                slot: slot,
                source: source,
                turnIdentifier: record.sourceTurnIdentifier,
                speak: false
            )
        }
        appendRouteReceipt(
            "STOP terminalized-running-work count="
                + "\(runningRecords.count)"
        )
    }

    private func silenceEverything(spokenTrigger: String) {
        // Preparation is cancellable. An already-committed atomic app swap
        // finishes its verified restart/rollback transaction.
        if AceNativeUpdate.shared.isWorking {
            AceNativeUpdate.shared.cancelOrClose()
        }
        AceLicense.shared.cancelPurchaseRecovery()
        nativeConversationContext.clearSession()
        clearDetectedElementLocation()
        clearVisibleResponse()
        if partnerModeIsActive {
            endPartnerMode(reason: .stop)
        }
        goldAnswerInterruption = .explicitStop
        currentResponseTask?.cancel()
        // Task.cancel() cannot interrupt a blocking CLI subprocess, so also
        // terminate the in-flight gold answer — otherwise it runs to completion
        // (up to 150s) after the user said stop.
        claudeAPI.cancelInFlightAnswer()
        noraVoice.stopPlayback()
        stopScanTheater()
        // A running product walkthrough drives the browser, gem, and narration
        // from its own task, which nothing else cancels — "stop" must end it too.
        cancelWalkthroughIfRunning()
        // The explain-apps gem tour is the same kind of self-driving task.
        explainAppsChoreographyTask?.cancel()
        explainAppsChoreographyTask = nil
        // So is the first-run tour — "stop" during the introduction means stop.
        cancelFirstRunTourIfRunning()
        backgroundDispatchGeneration = UUID()
        pendingBackgroundExecutions.removeAll()
        backgroundQueueDrainTask?.cancel()
        backgroundQueueDrainTask = nil
        backgroundAgent.cancelCurrentTask()
        silverBackgroundAgent.cancelCurrentTask()
        _ = morningLinkBriefRuntime.stopActiveRunKeepingSchedule()
        appActionPlanningGeneration = UUID()
        appActionPlanningTask?.cancel()
        appActionPlanningTask = nil
        discardPendingDirectEffectConfirmations()
        appActionBroker.cancelCurrentAction()
        testEmailGeneration = UUID()
        testEmailTask?.cancel()
        testEmailTask = nil
        isPreparingTestEmailSend = false
        if let process = testEmailProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        testEmailProcess = nil
        recentEmailRead = nil
        emailReadGeneration = UUID()
        emailReadTask?.cancel()
        emailReadTask = nil
        if let process = emailReadProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        emailReadProcess = nil
        nativeLocationManager?.cancel()
        nativeLocationManager = nil
        // Cancellation is not complete until every accepted work ID has a
        // durable terminal projection. In particular, a held Gold or Partner
        // clarification owns no subprocess callback that could close its
        // receipt later, so dropping only the continuation leaves the buyer
        // staring at CLARIFYING forever.
        terminalizeRunningWorkForExplicitStop()
        pendingGoldClarification = nil
        pendingPartnerClarification = nil
        clearPendingAppleMailDraftRequest()
        clearPendingAppleMessagesRequest()
        _ = redExecutionService.cancelPrecommitWork(
            sessionID: AceEventBus.shared.sessionID
        )
        activeContextualOwnerRequest = nil
        activeOwnerTurnContext = nil
        receiptOnlyWorkIDBySourceCorrelationID.removeAll(
            keepingCapacity: false
        )
        ownerTurnLifecycle.clear()
        backgroundTaskActive = meetingNotetaker.isTakingNotes
        voiceState = .idle
        appendRouteReceipt(
            "ROUTE stop characters=\(spokenTrigger.count)"
        )
    }

    /// The panel's Stop Work button has the same cancellation semantics as the
    /// owner's bare spoken "stop", plus capture and long-work cancellation. It
    /// deliberately leaves the shortcut monitor, provider connection, and app
    /// lifecycle running so the very next owner turn is admitted normally.
    func stopAllOwnerWork() {
        let notesWereActive = meetingNotetaker.isTakingNotes || meetingNotetaker.isStartingUp
        CodexModelCapabilityPreflight.shared.invalidate(
            reason: .stopWork
        )
        let stoppedTurnID = AceEventBus.shared.currentTurnID
        finishWaveformTurn(reason: .stop)
        buddyDictationManager.cancelCurrentDictationForStop()
        if let turnID = stoppedTurnID {
            AceEventBus.shared.cancelTurn(
                turnID,
                reason: "owner-stop-work-button"
            )
        }
        _ = workflowRuntime.abortActiveJob()
        silenceEverything(spokenTrigger: "panel-stop-work")
        stopMeetingNotes(announce: false)
        activeOwnerTurnContext = nil
        activeContextualOwnerRequest = nil
        ownerTurnLifecycle.clear()
        let stoppedTurnLabel =
            stoppedTurnID.map(AceEventIdentifier.short) ?? "none"
        stopWorkReceipt = "status=stopped turn=" + stoppedTurnLabel
        stopWorkStatusMessage = notesWereActive
            ? "Current work was cancelled. Notes capture is ending; its result will appear in Meeting Notes."
            : "Current work was cancelled. Ace is ready for your next request."
    }

    /// Cancels a running product walkthrough so a new command (or "stop")
    /// supersedes it cleanly, and NILs the handle so the ended task's tail can't
    /// reset voiceState/gem out from under whatever the new command sets.
    private func cancelWalkthroughIfRunning() {
        walkthroughTask?.cancel()
        walkthroughTask = nil
        if let process = walkthroughAutomationProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        walkthroughAutomationProcess = nil
    }

    // MARK: - Typing routes (gold gem types for the user)

    /// "type <text>" / "type out <text>" / "dictate <text>". Kept to explicit
    /// typing verbs — "write" stays with the worker ("write a poem in notes").
    private static let typeRequestPattern =
        #"(?i)^\s*(?:please\s+)?(?:can\s+you\s+)?(?:type\s+out|type|dictate)\s+(.+?)\s*$"#

    private func extractTypeRequest(_ text: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: Self.typeRequestPattern),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)),
              let captureRange = Range(match.range(at: 1), in: text) else { return nil }
        let textToType = String(text[captureRange])
        return textToType.isEmpty ? nil : textToType
    }

    private func beginDesktopActionOwnerTurn(
        _ context: OwnerTurnContext
    ) -> (correlationID: UUID, workID: UUID?)? {
        guard let correlationID = activeRoutingCorrelationID else {
            return nil
        }
        // Typing and other private native effects deliberately have no Gold
        // work record. Their admitted lifecycle still owns the real effect.
        if !context.permitsDurableContext {
            guard ownerTurnLifecycle.deferManagerDispatch(for: context) else {
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationID,
                    status: .failed,
                    outcome: "desktop-action-lifecycle-unavailable",
                    reason: "Ace could not retain this desktop action, so nothing ran."
                )
                return nil
            }
            return (correlationID, nil)
        }
        guard let workID = activeContextualOwnerRequest?
                .childWorkCorrelationIdentifier else {
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: correlationID,
                status: .failed,
                outcome: "desktop-action-missing-work",
                reason: "Ace could not bind this desktop action, so nothing ran."
            )
            return nil
        }
        guard bindRunningWorkDurably(
            workCorrelationIdentifier: workID,
            lane: .direct,
            durableLane: "native"
        ) else {
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: correlationID,
                status: .failed,
                outcome: "desktop-action-bind-failed",
                reason:
                    "Ace could not durably bind this desktop action, so nothing ran."
            )
            return nil
        }
        guard ownerTurnLifecycle.deferManagerDispatch(
            for: context
        ) else {
            _ = finishDirectWorkTerminal(
                workCorrelationIdentifier: workID,
                lane: .direct,
                durableLane: "native",
                status: .failed,
                outcome: "desktop-action-lifecycle-unavailable",
                verification: "none",
                reason:
                    "Ace could not retain the exact desktop-action lifecycle, so nothing ran.",
                slot: .none,
                nativePublication: DeferredNativeTerminalPublication(
                    turnIdentifier: context.turnID,
                    correlationIdentifier: correlationID,
                    eventStatus: .failed,
                    lifecycleOutcome:
                        "desktop-action-lifecycle-unavailable",
                    visibleText:
                        "Ace could not retain the exact desktop-action lifecycle, so nothing ran."
                )
            )
            return nil
        }
        return (correlationID, workID)
    }

    @discardableResult
    private func finishDesktopActionOwnerTurn(
        context: OwnerTurnContext,
        correlationID: UUID,
        workID: UUID?,
        receipt: DesktopActionReceipt,
        verifiedOutcome: String,
        failedOutcome: String,
        verifiedEvidence: String = "app-owned-accessibility-readback"
    ) -> Bool {
        let verified = receipt.status == .verified
        guard let workID else {
            return finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: correlationID,
                status: verified ? .completed : .failed,
                outcome: verified ? verifiedOutcome : failedOutcome,
                reason: receipt.reason,
                durableVerification: verified ? verifiedEvidence : "none"
            )
        }
        return finishDirectWorkTerminal(
            workCorrelationIdentifier: workID,
            lane: .direct,
            durableLane: "native",
            status: verified ? .completed : .failed,
            outcome: verified ? verifiedOutcome : failedOutcome,
            verification: verified ? verifiedEvidence : "none",
            reason: receipt.reason,
            slot: .none,
            nativePublication: DeferredNativeTerminalPublication(
                turnIdentifier: context.turnID,
                correlationIdentifier: correlationID,
                eventStatus: verified ? .completed : .failed,
                lifecycleOutcome:
                    verified ? verifiedOutcome : failedOutcome,
                visibleText: receipt.reason
            )
        )
    }

    /// Points Ace's visible gem at one exact enabled control without clicking
    /// it. Ace's own filmed controls use live app-owned NSView geometry because
    /// a process cannot reliably Accessibility-introspect its own SwiftUI tree.
    /// Other apps retain the twice-resolved Accessibility path.
    private func performPointRequest(
        _ target: String,
        context: OwnerTurnContext
    ) {
        guard directEffectsAreAllowed else { return }
        guard let ownership = beginDesktopActionOwnerTurn(context)
        else { return }

        let pointingApplication = MenuBarPanelManager.shared?
            .applicationForPointing()
        let pointingProcessIdentifier = pointingApplication?.processIdentifier
        let frontmostName = pointingApplication?.localizedName
            ?? "the frontmost application"
        let pointingContextStillMatches: () -> Bool = {
            guard let pointingProcessIdentifier,
                  pointingApplication?.isTerminated == false,
                  pointingApplication?.isHidden == false else { return false }
            return MenuBarPanelManager.shared?.applicationForPointing()?
                .processIdentifier == pointingProcessIdentifier
        }
        let finish: (DesktopActionReceipt, String) -> Void = {
            [weak self] receipt, verifiedEvidence in
            guard let self else { return }
            self.appendRouteReceipt(
                "POINT native \(receipt.status.rawValue): \(receipt.reason)"
            )
            _ = self.finishDesktopActionOwnerTurn(
                context: context,
                correlationID: ownership.correlationID,
                workID: ownership.workID,
                receipt: receipt,
                verifiedOutcome: "desktop-point-verified",
                failedOutcome: "desktop-point-failed",
                verifiedEvidence: verifiedEvidence
            )
        }
        let failure: (String) -> Void = { reason in
            finish(
                DesktopActionReceipt(
                    status: .failed,
                    observedApplication: nil,
                    observedRole: nil,
                    observedValueDigest: nil,
                    reason: reason
                ),
                "none"
            )
        }

        let mapped: (point: CGPoint, screen: NSScreen)
        let verifiedControlBounds: CGRect?
        let verifiedEvidence: String
        let observedApplication: String
        let observedRole: String
        if let panelTarget = AcePanelVisualTargetPolicy.target(
            for: target
        ) {
            guard let firstFrame = livePanelVisualTargetFrame(
                for: panelTarget
            ), let verifiedFrame = livePanelVisualTargetFrame(
                for: panelTarget
            ), hypot(
                verifiedFrame.midX - firstFrame.midX,
                verifiedFrame.midY - firstFrame.midY
            ) <= 1,
            abs(verifiedFrame.width - firstFrame.width) <= 1,
            abs(verifiedFrame.height - firstFrame.height) <= 1,
            let screen = NSScreen.screens.first(where: {
                $0.frame.contains(
                    CGPoint(
                        x: verifiedFrame.midX,
                        y: verifiedFrame.midY
                    )
                )
            }) else {
                failure(
                    "the app-owned ‘\(target)’ control had no stable visible geometry, so Ace did not point"
                )
                return
            }
            mapped = (
                CGPoint(
                    x: verifiedFrame.midX,
                    y: verifiedFrame.midY
                ),
                screen
            )
            verifiedEvidence = "app-owned-visible-control-geometry"
            verifiedControlBounds = verifiedFrame
            observedApplication = "Ace"
            observedRole = "app-owned panel control"
        } else {
            guard pointingContextStillMatches() else {
                failure("The page's application is no longer visible. Select it and ask Ace to point again.")
                return
            }
            let initialResolution = AccessibilityVisualTargetResolver.resolution(
                for: target, includesReadOnlyContent: true,
                applicationProcessIdentifier: pointingProcessIdentifier
            )
            if initialResolution == .missing {
                stopScanTheater()
                voiceState = .processing
                let responseTaskIdentity = UUID()
                currentResponseTaskIdentity = responseTaskIdentity
                currentResponseTask = Task { @MainActor [weak self] in
                    guard let self else { return }
                    defer { self.clearCurrentResponseTask(ifMatching: responseTaskIdentity) }
                    guard AceEventBus.shared.currentTurnID == context.turnID else { return }
                    let point = await self.resolveElementPoint(description: target)
                    guard !Task.isCancelled, self.directEffectsAreAllowed,
                          AceEventBus.shared.currentTurnID == context.turnID else { return }
                    guard pointingContextStillMatches() else {
                        self.clearDetectedElementLocation()
                        failure("The page changed applications before Ace could verify the point.")
                        return
                    }
                    guard point != nil else {
                        failure("I could not locate ‘\(target)’ in the current screen.")
                        return
                    }
                    self.showCursorOverlayForBackgroundTask()
                    self.voiceState = .idle
                    finish(DesktopActionReceipt(status: .verified,
                        observedApplication: frontmostName, observedRole: "capture-bound screen target",
                        observedValueDigest: nil, reason: "Pointed at ‘\(target)’ in the current screen."),
                        "capture-bound-screen-point")
                }
                return
            }
            guard case .unique(let firstPoint) = initialResolution else {
                failure(
                    "no unique enabled Accessibility control matched ‘\(target)’, so Ace did not point"
                )
                return
            }
            guard case .unique(let verifiedPoint) =
                    AccessibilityVisualTargetResolver.resolution(
                        for: target, includesReadOnlyContent: true,
                        applicationProcessIdentifier: pointingProcessIdentifier
                    ), pointingContextStillMatches(), hypot(
                        verifiedPoint.x - firstPoint.x,
                        verifiedPoint.y - firstPoint.y
                    ) <= 1 else {
                failure(
                    "the Accessibility target moved before verification, so Ace did not point"
                )
                return
            }
            guard let accessibilityMapping =
                    Self.appKitPointForAccessibilityPoint(
                        verifiedPoint
                    ) else {
                failure(
                    "the verified Accessibility point was outside every attached display"
                )
                return
            }
            mapped = accessibilityMapping
            verifiedControlBounds = nil
            verifiedEvidence = "app-owned-accessibility-readback"
            observedApplication = frontmostName
            observedRole = "AX control"
        }

        showCursorOverlayForBackgroundTask()
        voiceState = .idle
        detectedElementDisplayFrame = mapped.screen.frame
        detectedElementScreenLocation = mapped.point
        detectedElementScreenBounds = verifiedControlBounds
        markDetectedElementAsVerified()
        if let panelTarget = AcePanelVisualTargetPolicy.target(for: target) {
            trackPanelInkTarget(panelTarget)
        }
        finish(
            DesktopActionReceipt(
                status: .verified,
                observedApplication: observedApplication,
                observedRole: observedRole,
                observedValueDigest: nil,
                reason:
                    "pointed at the verified ‘\(target)’ control in \(observedApplication) without clicking it"
            ),
            verifiedEvidence
        )
    }

    /// AX/CoreGraphics points use a top-left display origin. Overlay points use
    /// AppKit's bottom-left origin. Match by display ID so mixed-height and
    /// left-of-primary monitor layouts convert correctly.
    private static func appKitPointForAccessibilityPoint(
        _ accessibilityPoint: CGPoint
    ) -> (point: CGPoint, screen: NSScreen)? {
        for screen in NSScreen.screens {
            guard let displayID = screen.deviceDescription[
                NSDeviceDescriptionKey("NSScreenNumber")
            ] as? CGDirectDisplayID else { continue }
            let cgFrame = CGDisplayBounds(displayID)
            guard cgFrame.contains(accessibilityPoint) else { continue }
            return (
                CGPoint(
                    x: screen.frame.minX
                        + accessibilityPoint.x - cgFrame.minX,
                    y: screen.frame.maxY
                        - (accessibilityPoint.y - cgFrame.minY)
                ),
                screen
            )
        }
        return nil
    }

