                    self?.directEffectsAreAllowed == true
                        && self?.ownerTurnLifecycle.activeBinding?.context == context
                }
            ).execute(
                DesktopActionRequest(
                    action: application.map {
                        .typeTextInApplication(exactName: $0, exactText: textToType)
                    } ?? .typeText(exactText: textToType),
                    expectedFrontmostBundleIdentifier: expectedBundle,
                    expectedFocusedElementToken: nil
