    // MARK: - Explicit memory commands

    private struct PendingMemoryClear {
        let request: PendingAgentAction
        let sessionID: UUID
        let expectedContents: String
    }
    private var memoryClearExpiryTask: Task<Void, Never>?
    private var pendingMemoryWipeConfirmation: PendingMemoryClear? {
        didSet {
            memoryClearExpiryTask?.cancel()
            memoryClearExpiryTask = nil
            refreshInstallReadinessPendingDecision()
            guard let pending = pendingMemoryWipeConfirmation else { return }
            memoryClearExpiryTask = Task { @MainActor [weak self] in
                try? await Task.sleep(nanoseconds: 30_000_000_000)
                guard !Task.isCancelled, let self,
                      self.pendingMemoryWipeConfirmation?.request == pending.request,
                      self.pendingMemoryWipeConfirmation?.sessionID == pending.sessionID else { return }
                self.pendingMemoryWipeConfirmation = nil
            }
        }
    }

    private static var userMemoryFileURL: URL? {
        FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first?
            .appendingPathComponent("BlackLabel/memory.md")
    }

    private func finishExplicitMemoryCommand(
        context: OwnerTurnContext, status: AceEventState,
        outcome: String, response: String
    ) {
        // Memory readout never enters transcripts, Partner history, or speech
        // persistence. Only the explicit memory file owns the saved content.
        let published = finishVolatileOwnerTurn(
            turnID: context.turnID, correlationID: activeRoutingCorrelationID,
            status: status, outcome: outcome, reason: response, speak: false
        )
        guard published, !meetingCaptureOwnsVoiceOutput else { return }
        if partnerModeIsActive {
            speakPartnerStatus(response, persistence: .volatile)
        } else {
            _ = noraVoice.enqueueVolatileText(response)
        }
    }

    private func performExplicitMemoryCommand(context: OwnerTurnContext) {
        guard directEffectsAreAllowed, !stealthMode.isActive,
              context.selectedRoute == "native.memory",
              let intent = LocalIntentPolicy.explicitMemoryIntent(context.exactInput),
              let fileURL = Self.userMemoryFileURL else { return }
        let store = ExplicitMemoryStore(fileURL: fileURL)
        var response = ""
        var outcome = "memory-operation-failed"
        var status = AceEventState.failed
        let committed = performDirectEffectCommit { [self] in
            do {
                switch intent {
                case .remember(let text):
                    try store.append(text)
                    response = "Saved to explicit memory on this Mac."
                    outcome = "memory-saved-verified"
                case .recall:
                    let entries = try store.contents().split(separator: "\n")
                        .map { $0.replacingOccurrences(of: #"^\s*-\s*\[[^\]]*\]\s*"#, with: "", options: .regularExpression) }
                    let summary = entries.joined(separator: ". ")
                    response = summary.isEmpty
                        ? "No explicit memories are saved. Say remember that, followed by what you want saved."
                        : "Your explicit saved memories: " + String(summary.prefix(600))
                            + (summary.count > 600 ? " — more entries remain in the memory file." : "")
                    outcome = "memory-read-verified"
                case .forgetLast:
                    let removed = try store.forgetLast()
                    response = removed ? "Removed the last explicit saved memory. Conversation history and Partner memory are unchanged."
                        : "There is no explicit saved memory to remove."
                    outcome = removed ? "memory-last-removed-verified" : "memory-already-empty"
                case .clear:
                    let contents = try store.contents()
                    if contents.isEmpty {
                        response = "There are no explicit saved memories to clear. Conversation history and Partner memory are separate."
                        outcome = "memory-already-empty"
                    } else {
                        pendingMemoryWipeConfirmation = PendingMemoryClear(
                            request: PendingAgentAction(instruction: "clear-explicit-memory", requestedAt: Date()),
                            sessionID: context.sessionID, expectedContents: contents
                        )
                        response = "Clear all explicit saved memories? A recoverable backup will remain on this Mac; conversation history and Partner memory stay unchanged. Say confirm within 30 seconds, or cancel."
                        outcome = "memory-clear-review-presented"
                    }
                }
                status = .completed
            } catch {
                response = error.localizedDescription
            }
            return true
        }
        guard committed else { return }
        appendRouteReceipt("MEMORY outcome=\(outcome)")
        finishExplicitMemoryCommand(context: context, status: status, outcome: outcome, response: response)
    }

    /// Resolve only a fresh owner confirmation of the exact reviewed snapshot.
    /// Any other admitted request discards this grant before ordinary routing.
    private func resolveExplicitMemoryClear(context: OwnerTurnContext) -> Bool {
        guard let pending = pendingMemoryWipeConfirmation else { return false }
        pendingMemoryWipeConfirmation = nil
        let utterance = LocalIntentPolicy.normalizedRoutingText(context.exactInput)
        let confirms = CrossAppActionPolicy.isExplicitConfirmation(utterance)
        let cancels = CrossAppActionPolicy.isExplicitCancellation(utterance)
        guard confirms || cancels,
              OwnerTurnDispatchPolicy.permitsHeldOwnerEffectResolution(for: context) else { return false }
        var response = "Cancelled the explicit-memory clear."
        var outcome = "memory-clear-cancelled"
        var status = AceEventState.cancelled
        if confirms {
            guard pending.sessionID == context.sessionID,
                  pending.request.isCurrent(at: Date()) else {
                finishExplicitMemoryCommand(context: context, status: .failed,
                    outcome: "memory-clear-expired",
                    response: "That memory-clear confirmation expired. Ask to forget everything again.")
                return true
            }
            let committed = performDirectEffectCommit {
                do {
                    guard let fileURL = Self.userMemoryFileURL else { throw ExplicitMemoryStore.Failure.unsafePath }
                    let backup = try ExplicitMemoryStore(fileURL: fileURL).clear(expected: pending.expectedContents)
                    response = backup == nil ? "There were no explicit saved memories to clear."
                        : "Cleared the active explicit-memory file. A recoverable backup remains on this Mac. Conversation history and Partner memory are unchanged."
                    outcome = "memory-clear-verified"
                    status = .completed
                } catch {
                    response = error.localizedDescription
                    outcome = "memory-clear-failed"
                    status = .failed
                }
                return true
            }
            guard committed else { return true }
        }
        appendRouteReceipt("MEMORY outcome=\(outcome)")
        finishExplicitMemoryCommand(context: context, status: status, outcome: outcome, response: response)
        return true
    }

    /// Reads the explicit memory source for lexical retrieval, not direct
    /// prompt injection. The whole bounded file is indexed each Gold turn so
    /// an older relevant record can outrank a newer unrelated one. Symlinks,
    /// oversized files, invalid UTF-8, and either Stealth wall return empty.
    private func loadExplicitMemoryForGoldRetrieval() -> String? {
        guard directEffectsAreAllowed,
              !stealthMode.isActive,
              let fileURL = Self.userMemoryFileURL,
              let supportDirectory =
                AceTranscript.supportDirectory(),
              !AceTranscript.stealthBlocksWriting(
                  supportDirectory: supportDirectory
              ),
              let contents = try? ExplicitMemoryStore(fileURL: fileURL).contents(),
              !contents.trimmingCharacters(
                  in: .whitespacesAndNewlines
              ).isEmpty else {
            return nil
        }
        return contents
    }

    /// Same durable receipt channel as the worker and the app switcher
    /// (agent.log) — routing decisions are proven by log, not self-report.
    private func appendRouteReceipt(_ message: String) {
        guard let directory = FileManager.default
            .urls(for: .applicationSupportDirectory, in: .userDomainMask).first?
            .appendingPathComponent("BlackLabel", isDirectory: true) else { return }
        // 0700 or the bundled tools all fail closed — see LifecycleLog.append.
        try? PrivateSupportDirectory.ensure(at: directory)
        let safeMessage = message
            .components(separatedBy: .newlines)
            .joined(separator: "\\n")
            .unicodeScalars
            .map { CharacterSet.controlCharacters.contains($0) ? " " : String($0) }
            .joined()
        // Every routing decision now names the owner turn it belongs to. Without
        // it a reader could see `ROUTE web-open direct → native preview` and had
        // no way to tell WHICH request caused it — or whether a request caused it
        // at all. One tag, ~200 existing receipts correlated for free.
        let turnTag = activeRoutingTurnID
            .map { "turn=\(AceEventIdentifier.short($0)) " } ?? ""
        let line =
            "\(ISO8601DateFormatter().string(from: Date())) \(turnTag)\(safeMessage)\n"
        let fileURL = directory.appendingPathComponent("agent.log")
        if let handle = try? FileHandle(forWritingTo: fileURL) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: Data(line.utf8))
        } else {
            try? Data(line.utf8).write(to: fileURL, options: .atomic)
        }
    }

    /// The deafness surface (founder blocker 3). The notetaker's brake already
    /// collapsed the LOG storm; this closes the SILENT storm — the recognizer being
    /// deaf used to leave the founder pressing the hotkey into silence with zero
    /// indication. Called on the rising edge of a proven refusal streak: say ONE
    /// line and raise the amber gem cue, both in software (never prompt-driven).
    /// Idempotent — the transcriber only fires once per streak, and this guards
    /// again — so a storm of hundreds of refusals produces exactly one signal. It
    /// SIGNALS the condition only; it never touches Siri or Dictation settings
    /// (that decision is the founder's, routed to the HQ Review Inbox).
    private func surfaceSttDeafness() {
        guard !sttDeafnessActive else { return }
        sttDeafnessActive = true
        appendRouteReceipt("STT DEAFNESS surfaced — spoken + amber gem (Siri/Dictation likely off)")
        Task {
            try? await noraVoice.speakText(
                "i can't hear the microphone — speech recognition isn't responding. check that dictation is turned on in system settings.")
        }
    }

    /// Hearing returned (real text after a deaf streak): drop the amber gem cue.
    /// Silent — recovery needs no spoken line, only the visual clearing.
    private func clearSttDeafness() {
        guard sttDeafnessActive else { return }
        sttDeafnessActive = false
        appendRouteReceipt("STT DEAFNESS cleared — hearing recovered")
    }

    /// If the utterance opens with an explicit agent trigger, returns the task
    /// text after it; otherwise nil.
    private func agentTriggeredTask(_ text: String) -> String? {
        CrossAppActionPolicy.explicitAgentTask(text)
    }

    private func preparePartnerModeController() {
        guard partnerModeController == nil,
              !StealthEntryLatch.shared.isRaised,
              !stealthMode.isActive else {
            return
        }
        let profileIdentifier: UUID
        if let storedIdentifier = UserDefaults.standard.string(
            forKey: Self.partnerProfileIdentifierDefaultsKey
        ),
        let parsedIdentifier = UUID(
            uuidString: storedIdentifier
        ) {
            profileIdentifier = parsedIdentifier
        } else {
            profileIdentifier = UUID()
            UserDefaults.standard.set(
                profileIdentifier.uuidString.lowercased(),
                forKey:
                    Self.partnerProfileIdentifierDefaultsKey
            )
        }
        do {
            let controller = try PartnerModeController(
                profileIdentifier: profileIdentifier
            )
            if DeveloperMachine.isDeveloperMachine,
               controller.profile.identityPreferences
                == .genericDefault {
                try controller.updateIdentityPreferences(
                    .founderDefault
                )
            }
            partnerModeController = controller
            bindInstallReadinessPartnerState()
            partnerModeObservation = controller.objectWillChange
                .receive(on: DispatchQueue.main.circuitScheduler)
                .sink { [weak self] _ in
                    self?.objectWillChange.send()
                }
        } catch {
            appendRouteReceipt(
                "PARTNER storage unavailable errorType="
                    + String(describing: type(of: error))
            )
        }
    }

    func setPartnerModeEnabled(_ enabled: Bool) {
        if enabled {
            activatePartnerMode()
        } else {
            endPartnerMode(reason: .userEnded)
        }
    }

    func escapePartnerMode() {
        endPartnerMode(reason: .stop)
        showVisibleResponse("Partner Mode ended. Ace is back to normal.")
    }

    func ensurePartnerProfileReady() {
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed else { return }
        preparePartnerModeController()
    }

    func setPartnerWaiting(_ waiting: Bool) {
        guard let controller = partnerModeController,
              controller.userActivatedSession else {
            return
        }
        let action = PartnerThinkButtonPolicy.action(
            phase: controller.phase,
            temporaryCaption: controller.temporaryCaption
        )
        if !waiting {
            guard action == .resume,
                  AceLicense.shared.admits(.partnerMode),
                  directEffectsAreAllowed else { return }
            controller.resume()
            beginAutomaticPartnerListeningIfAllowed()
            return
        }
        switch action {
        case .finalizeCapturedTurn:
            appendRouteReceipt(
                "PARTNER Think submitted captured owner turn characters="
                    + "\(controller.temporaryCaption.count)"
            )
            buddyDictationManager.stopAutomaticPartnerTurn()
        case .enterWaiting:
            buddyDictationManager.cancelCurrentDictation(
                preserveDraftText: false
            )
            controller.enterWaiting()
            voiceState = .idle
            appendRouteReceipt(
                "PARTNER Think paused empty listening window"
            )
        case .resume:
            guard AceLicense.shared.admits(.partnerMode),
                  directEffectsAreAllowed else { return }
            controller.resume()
            beginAutomaticPartnerListeningIfAllowed()
        case .noAction:
            appendRouteReceipt(
                "PARTNER Think ignored phase=\(controller.phase.rawValue)"
            )
        }
    }

    func setPartnerMuted(_ muted: Bool) {
        guard let controller = partnerModeController,
              controller.userActivatedSession else {
            return
        }
        if muted {
            partnerListeningStartTask?.cancel()
            partnerListeningStartTask = nil
            buddyDictationManager.cancelCurrentDictation(
                preserveDraftText: false
            )
            controller.mute()
            voiceState = .idle
        } else {
            guard AceLicense.shared.admits(.partnerMode),
                  directEffectsAreAllowed else { return }
            controller.resume()
            beginAutomaticPartnerListeningIfAllowed()
        }
    }

    @discardableResult
    func enablePartnerScreenContext() -> AceControlActionOutcome {
        let isEntitled = AceLicense.shared.admits(.partnerMode)
        if isEntitled, directEffectsAreAllowed {
            preparePartnerModeController()
        }
        if let blocker = PartnerControlActionAdmission.blocker(
            for: .screenContext,
            isEntitled: isEntitled,
            effectsAreAllowed: directEffectsAreAllowed,
            controllerIsAvailable: partnerModeController != nil,
            partnerSessionIsActive: partnerModeIsActive,
            screenContentIsReady: hasScreenContentPermission
        ) {
            return partnerControlFailure(
                blocker,
                action: .screenContext
            )
        }
        guard let controller = partnerModeController else {
            return partnerControlFailure(
                .controllerUnavailable,
                action: .screenContext
            )
        }
        let outcome = PartnerControlActionExecution.perform(
            .screenContext
        ) {
            controller.enableScreenContextForSession()
            return controller.screenContextEnabledForSession
        }
        switch outcome {
        case .succeeded:
            appendRouteReceipt(
                "PARTNER screen context enabled by panel"
            )
        case let .failed(failure):
            appendRouteReceipt(
                "PARTNER screen context failed code=\(failure.code)"
            )
            showVisibleResponse(failure.message)
        case .started:
            break
        }
        return outcome
    }

    func undoPartnerMemoryReceipt() {
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed else { return }
        guard let controller = partnerModeController else {
            showVisibleResponse("Partner memory is unavailable on this Mac.")
            return
        }
        do {
            try controller.undoLastMemoryReceipt()
            showVisibleResponse("The last Partner memory change was undone.")
        } catch PartnerModeControllerError.noUndoableReceipt {
            showVisibleResponse("There is no current Partner memory change to undo. Undo ends when the session or receipt closes.")
        } catch {
            showVisibleResponse(PartnerSecureStore.ownerFacingFailure(error))
        }
    }

    var canChangeConversationLanguage: Bool {
        AceLanguage.canChange(
            partnerActive: partnerModeIsActive,
            workActive: backgroundTaskActive || currentResponseTask != nil
                || appActionPlanningTask != nil || aceHQDispatchTask != nil
                || morningBriefTask != nil || emailReadTask != nil || testEmailTask != nil
                || ownerTurnLifecycle.hasPendingAsynchronousManagerDispatch
                || buddyDictationManager.isDictationInProgress,
            notesUnsaved: meetingNotetaker.hasUnsavedNotes,
            privacyActive: StealthEntryLatch.shared.isRaised
        )
    }

    func changeConversationLanguage(_ language: AceLanguage) -> Bool {
        guard canChangeConversationLanguage else {
            showVisibleResponse("End Partner and finish dictation, active work or notes before changing language.")
            return false
        }
        UserDefaults.standard.set(language.rawValue, forKey: AceLanguage.preferenceKey)
        guard AceLanguage.selected() == language else { return false }
        appleSpeechRecognitionReadiness = AppleSpeechTranscriptionProvider.currentReadiness
        noraVoice.applyPartnerVoiceConfiguration(AceVoiceModePolicy.standardConfiguration)
        showVisibleResponse("Language: \(language.resolved().displayName). Dictation uses this language only when its on-device recognizer is available.")
        return true
    }

    func resetPartnerProfile() {
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed else { return }
        preparePartnerModeController()
        guard let controller = partnerModeController else {
            showVisibleResponse(
                "Partner memory is unavailable on this Mac."
            )
            return
        }
        do {
            try controller.resetProfile()
            noraVoice.applyPartnerVoiceConfiguration(
                AceVoiceModePolicy.standardConfiguration
            )
            showVisibleResponse(
                "Partner identity and memory were reset."
            )
        } catch {
            showVisibleResponse(
                PartnerSecureStore.ownerFacingFailure(error)
            )
        }
    }

    @discardableResult
    func updatePartnerIdentityPreferences(
        _ preferences: PartnerIdentityPreferences
    ) -> AceControlActionOutcome {
        let isEntitled = AceLicense.shared.admits(.partnerMode)
        if isEntitled, directEffectsAreAllowed {
            preparePartnerModeController()
        }
        if let blocker = PartnerControlActionAdmission.blocker(
            for: .identitySave,
            isEntitled: isEntitled,
            effectsAreAllowed: directEffectsAreAllowed,
            controllerIsAvailable: partnerModeController != nil,
            partnerSessionIsActive: partnerModeIsActive,
            screenContentIsReady: hasScreenContentPermission
        ) {
            return partnerControlFailure(
                blocker,
                action: .identitySave
            )
        }
        guard let controller = partnerModeController else {
            return partnerControlFailure(
                .controllerUnavailable,
                action: .identitySave
            )
        }
        let outcome = PartnerControlActionExecution.perform(
            .identitySave
        ) {
            try controller.updateIdentityPreferences(preferences)
            if partnerModeIsActive {
                noraVoice.applyPartnerVoiceConfiguration(
                    .from(preferences)
                )
            }
            return true
        }
        switch outcome {
        case .succeeded:
            appendRouteReceipt("PARTNER identity settings saved")
        case let .failed(failure):
            showVisibleResponse(failure.message)
            appendRouteReceipt(
                "PARTNER identity save failed code=\(failure.code)"
            )
        case .started:
            break
        }
        return outcome
    }

    func previewPartnerVoice(
        _ profile: PartnerVoiceProfile
    ) async -> AceControlActionOutcome {
        let isEntitled = AceLicense.shared.admits(.partnerMode)
        if isEntitled, directEffectsAreAllowed {
            preparePartnerModeController()
        }
        if let blocker = PartnerControlActionAdmission.blocker(
            for: .voicePreview,
            isEntitled: isEntitled,
            effectsAreAllowed: directEffectsAreAllowed,
            controllerIsAvailable: partnerModeController != nil,
            partnerSessionIsActive: partnerModeIsActive,
            screenContentIsReady: hasScreenContentPermission
        ) {
            return partnerControlFailure(
                blocker,
                action: .voicePreview
            )
        }
        guard let controller = partnerModeController else {
            return partnerControlFailure(
                .controllerUnavailable,
                action: .voicePreview
            )
        }
        var preferences =
            controller.profile.identityPreferences
        preferences.voiceProfile = profile
        preferences.speakingRate =
            profile.defaultSpeakingRate
        preferences.warmth = profile.defaultWarmth
        preferences.energy = profile.defaultEnergy
        let outcome = await PartnerControlActionExecution.performAsync(
            .voicePreview
        ) {
            let configuration =
                PartnerVoiceConfiguration.from(preferences)
            showVisibleResponse(configuration.previewSentence)
            return await noraVoice
                .previewPartnerVoiceConfiguration(
                    configuration
                )
        }
        switch outcome {
        case .succeeded:
            appendRouteReceipt("PARTNER voice preview completed")
        case let .failed(failure):
            appendRouteReceipt(
                "PARTNER voice preview failed code=\(failure.code)"
            )
            showVisibleResponse(failure.message)
        case .started:
            break
        }
        return outcome
    }

    private func partnerControlFailure(
        _ blocker: PartnerControlActionBlocker,
        action: PartnerControlAction
    ) -> AceControlActionOutcome {
        let failure: AceActionFailure
        switch blocker {
        case .notEntitled:
            failure = AceActionFailure(
                code: "partner.not_entitled",
                message: "Link this Mac before using Partner controls.",
                recoveryTitle: "Link this Mac",
                recovery: .retry
            )
        case .effectsBlocked:
            failure = AceActionFailure(
                code: "partner.private_mode",
                message: "Exit Private Mode before using Partner controls.",
                recoveryTitle: "Exit Private Mode and try again",
                recovery: .retry
            )
        case .controllerUnavailable:
            failure = AceActionFailure(
                code: "partner.profile_unavailable",
                message: "Partner memory is unavailable on this Mac.",
                recoveryTitle: "Try again",
                recovery: .retry
            )
        case .partnerSessionInactive:
            failure = AceActionFailure(
                code: "partner.session_inactive",
                message:
                    "Start Partner Mode before enabling session screen context.",
                recoveryTitle: "Start Partner Mode and try again",
                recovery: .retry
            )
        case .partnerSessionActive:
            failure = AceActionFailure(
                code: "partner.session_active",
                message:
                    "End the active Partner conversation before previewing a voice.",
                recoveryTitle: "End Partner, then preview again",
                recovery: .retry
            )
        case .screenContentUnavailable:
            failure = AceActionFailure(
                code: "partner.screen_content_unavailable",
                message:
                    "Grant Screen Content in Permissions before using your screen in Partner Mode.",
                recoveryTitle: "Grant Screen Content, then try again",
                recovery: .retry
            )
        }
        appendRouteReceipt(
            "PARTNER control blocked action=\(String(describing: action)) "
                + "code=\(failure.code)"
        )
        showVisibleResponse(failure.message)
        return .failed(failure)
    }

    private func activatePartnerMode(
        speakAcknowledgement: Bool = true
    ) {
        guard AceLicense.shared.admits(.partnerMode),
              !StealthEntryLatch.shared.isRaised,
              !stealthMode.isActive,
              directEffectsAreAllowed else {
            appendRouteReceipt(
                "PARTNER activation deferred by Private Mode"
            )
            return
        }
        // Every activation starts a fresh silent run: a previous session's
        // spoken allowance must never suppress the warning in a new one.
        partnerConsecutiveSilentWindows = 0
        partnerDeafnessSurfacedForThisRun = false
        preparePartnerModeController()
        guard let partnerModeController else {
            showVisibleResponse(
                "Partner memory is unavailable on this Mac."
            )
            return
        }
        currentResponseTask?.cancel()
        claudeAPI.cancelInFlightAnswer()
        noraVoice.stopPlayback()
        SetupWalkthrough.shared.suspendForPartnerActivation(
            companionManager: self
        )
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        do {
            // This state change reaches the overlay before the asynchronous
            // microphone admission below.
            try partnerModeController.activate()
            objectWillChange.send()
            noraVoice.applyPartnerVoiceConfiguration(
                .from(
                    partnerModeController.profile
                        .identityPreferences
                )
            )
            appendRouteReceipt("PARTNER activated by user")
            if speakAcknowledgement {
                switch PartnerModePolicy.activationFollowUp {
                case .speakThenListen(let acknowledgement):
                    speakPartnerStatus(acknowledgement)
                }
            } else {
                appendRouteReceipt(
                    "PARTNER composer activation deferred greeting to admitted turn"
                )
            }
        } catch {
            appendRouteReceipt(
                "PARTNER activation failed errorType="
                    + String(describing: type(of: error))
            )
            showVisibleResponse(
                "Partner Mode could not open its private profile."
            )
        }
    }

    private func endPartnerMode(
        reason: PartnerSessionEndReason
    ) {
        nativeConversationContext.clearSession()
        if let pending = pendingPartnerClarification {
            let terminalText =
                reason == .userEnded || reason == .stop
                    ? "The Partner session ended before the requested clarification was answered. Nothing ran."
                    : "Partner lost the active session before the requested clarification was answered. Use Retry on the work receipt."
            if let originalWork = goldContextBundle.workRecords
                    .first(where: {
                        $0.workCorrelationIdentifier
                            == pending.parentWorkCorrelationIdentifier
                    }) {
                _ = finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        originalWork.workCorrelationIdentifier,
                    lane: .partner,
                    durableLane: "partner",
                    status:
                        reason == .userEnded || reason == .stop
                            ? .cancelled : .failed,
                    outcome:
                        reason == .userEnded || reason == .stop
                            ? "partner-clarification-session-ended"
                            : "partner-clarification-session-lost",
                    verification: "none",
                    reason: terminalText,
                    slot: .none,
                    source: .partner,
                    turnIdentifier:
                        originalWork.sourceTurnIdentifier,
                    speak: false
                )
            }
            pendingPartnerClarification = nil
        }
        partnerResponseGeneration = UUID()
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        currentResponseTask?.cancel()
        claudeAPI.cancelInFlightAnswer()
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        partnerModeController?.endSession(reason: reason)
        objectWillChange.send()
        noraVoice.applyPartnerVoiceConfiguration(
            AceVoiceModePolicy.standardConfiguration
        )
        voiceState = .idle
        appendRouteReceipt(
            "PARTNER ended reason=\(reason.rawValue)"
        )
        SetupWalkthrough.shared.resumeAfterPartnerMode(
            companionManager: self
        )
    }

    /// Partner is a VOICE mode: the owner activated it and started talking, not
    /// watching a panel. Every decline reason below reached the owner only as
    /// `lastErrorDescription`, whose single reader is PartnerModePanel — so
    /// Partner went dead silent and was indistinguishable from broken.
    ///
    /// Observed 2026-08-07: two activations 47 seconds apart, both blocked by
    /// Meeting Notes, both ended by the owner within 30 seconds, with nothing
    /// anywhere telling him Notes was holding the microphone.
    ///
    /// Stealth is the one reason that must stay silent. Saying "Private Mode is
    /// active" out loud in the room Stealth exists for would defeat the wall.
    private func announcePartnerListeningDeclined(
        _ explanation: String,
        stealthBlocked: Bool
    ) {
        guard !stealthBlocked,
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else { return }
        Task { [weak self] in
            try? await self?.noraVoice.speakText(
                explanation,
                priority: .background
            )
        }
    }

    private func preparePartnerMicrophoneForQueuedSpeech() async -> Bool {
        while !Task.isCancelled {
            guard directEffectsAreAllowed, !stealthMode.isActive,
                  !StealthEntryLatch.shared.isRaised else { return false }
            let captureOwner = audioSessionCoordinator.snapshot.captureOwner
            if captureOwner == .partner {
                if buddyDictationManager.yieldIdleAutomaticPartnerTurnForSpeech() {
                    partnerListeningStartTask?.cancel()
                    partnerListeningStartTask = nil
                    if partnerModeController?.phase == .listening {
                        partnerModeController?.finishSilentListeningWindow()
                    }
                    appendRouteReceipt("PARTNER idle microphone yielded to queued speech")
                    return true
                }
                // Keep actual words/audio in the capture pipeline. Its normal
                // final callback routes the owner turn and can cancel this line.
                do { try await Task.sleep(nanoseconds: 50_000_000) }
                catch { return false }
                continue
            }
            if captureOwner == nil, partnerModeController?.phase == .listening {
                partnerListeningStartTask?.cancel()
                partnerListeningStartTask = nil
                partnerModeController?.finishSilentListeningWindow()
            }
            // Explicit microphone owners retain the floor; speech never
            // revokes their capture lease.
            return captureOwner == nil
        }
        return false
    }

    private func beginAutomaticPartnerListeningIfAllowed() {
        guard partnerModeController?.isMicrophoneMuted != true,
              PartnerResumePolicy.foregroundWorkAllowsListening(
                answerIsActive: currentResponseTask != nil,
                appActionPlanningIsActive: appActionPlanningTask != nil
              ),
              !ownerTurnLifecycle.hasPendingAsynchronousManagerDispatch,
              !noraVoice.isPlaying,
              !buddyDictationManager.isDictationInProgress else { return }
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed,
              let partnerModeController else {
            return
        }
        let stealthBlocked =
            StealthEntryLatch.shared.isRaised
                || stealthMode.isActive
        guard !meetingNotetaker.isTakingNotes else {
            let explanation =
                "Meeting Notes is using voice input. Stop Notes, then resume Partner Mode."
            partnerModeController.listeningDidNotStart(explanation)
            announcePartnerListeningDeclined(
                explanation,
                stealthBlocked: stealthBlocked
            )
            voiceState = .idle
            appendRouteReceipt(
                "PARTNER listening blocked by Meeting Notes"
            )
            return
        }
        guard partnerModeController.beginListeningIfAllowed(
            stealthBlocked: stealthBlocked,
            microphoneReady: hasMicrophonePermission,
            speechRecognitionReady:
                appleSpeechRecognitionReadiness.isReady
        ) else {
            let explanation: String
            if stealthBlocked {
                explanation =
                    "Private Mode is active."
            } else if !hasMicrophonePermission {
                explanation =
                    "Microphone access is not ready."
            } else if !appleSpeechRecognitionReadiness
                        .isReady {
                explanation =
                    "Speech recognition is not ready."
            } else {
                explanation =
                    "Partner voice input is not ready."
            }
            partnerModeController.listeningDidNotStart(
                explanation
            )
            announcePartnerListeningDeclined(
                explanation,
                stealthBlocked: stealthBlocked
            )
            voiceState = .idle
            appendRouteReceipt(
                "PARTNER listening declined reason="
                    + explanation
            )
            return
        }

        voiceState = .listening
        // Partner's open microphone is the path where Ace's own voice used to
        // come back as a command: nothing here is hardware-attested, so the
        // capture-boundary window is the only thing separating Ace's readback
        // from the owner's next turn. Open a turn as the microphone opens, so
        // that window has an owner turn to report against.
        let partnerTurnID = AceEventBus.shared.beginOwnerTurn()
        activeRoutingTurnID = partnerTurnID
        beginWaveformTurn(turnID: partnerTurnID, source: .partner)
        buddyDictationManager.updateContextualCaptureContext(
            speechContextualCaptureContext()
        )
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = Task { @MainActor [weak self] in
            guard let self, !Task.isCancelled, !self.noraVoice.isPlaying,
                  self.partnerModeController?.isMicrophoneMuted != true else { return }
            await self.buddyDictationManager
                .startAutomaticPartnerTurn(
                    ownerTurnID: partnerTurnID,
                    updateDraftText: {
                        [weak self] capturedTurnID, draftText in
                        guard self?.partnerModeController?.isMicrophoneMuted != true else { return }
                        self?.partnerModeController?
                            .updateTemporaryCaption(draftText)
                        self?.ingestOwnerPartialTranscript(
                            draftText,
                            capturedOwnerTurnID: capturedTurnID
                        )
                    },
                    submitDraftText: {
                        [weak self] capturedTurnID, finalTranscript in
                        guard let self,
                              self.partnerModeController?.isMicrophoneMuted != true else { return }
                        self.lastTranscript = finalTranscript
                        self.preparePartnerCapturedUtteranceForRouting()
                        self.ingestOwnerUtterance(
                            finalTranscript,
                            origin: .microphonePartnerTurn,
                            capturedOwnerTurnID: capturedTurnID
                        )
                    },
                    onTermination: {
                        [weak self] termination in
                        self?
                            .handleAutomaticPartnerTurnTermination(
                                termination
                            )
                    }
                )
            guard !Task.isCancelled,
                  self.partnerModeIsActive else {
                return
            }
            if !self.buddyDictationManager
                .isRecordingAutomaticPartnerTurn {
                self.partnerModeController?
                    .listeningDidNotStart(
                        self.buddyDictationManager
                            .lastErrorMessage
                            ?? "Voice input did not start."
                    )
                self.voiceState = .idle
            }
        }
    }

    /// Automatic Partner capture owns the microphone only until it submits one
    /// transcript. Buddy has already torn that capture down when this callback
    /// runs, so the controller must stop advertising `.listening` before the
    /// utterance enters a native lane. Conversational turns immediately advance
    /// from `.ready` to `.processing`; native lanes explicitly return the mic
    /// after their Nora readback completes.
    private func preparePartnerCapturedUtteranceForRouting() {
        guard partnerModeIsActive,
              let partnerModeController,
              partnerModeController.phase == .listening else {
            return
        }
        partnerModeController.finishSilentListeningWindow()
        voiceState = .idle
        // A captured turn proves the microphone reaches the owner: the silent
        // run and its once-per-run spoken allowance both start over.
        let reset = PartnerSilentWindowPolicy.resetAfterCapturedTurn()
        partnerConsecutiveSilentWindows = reset.consecutiveSilentWindows
        partnerDeafnessSurfacedForThisRun = reset.alreadySurfacedForThisRun
        appendRouteReceipt(
            "PARTNER captured turn released microphone for routing"
        )
    }

    /// Returns Partner's automatic microphone only after a native lane has
    /// finished speaking. This prevents Nora's own readback from being fed back
    /// through Speech Recognition as the owner's next turn.
    private func resumePartnerListeningAfterNativeLaneIfAllowed() {
        guard PartnerResumePolicy.foregroundWorkAllowsListening(
                answerIsActive: currentResponseTask != nil,
                appActionPlanningIsActive: appActionPlanningTask != nil
              ),
              AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed,
              let partnerModeController,
              PartnerResumePolicy.shouldResume(
                userActivatedSession:
                    partnerModeController.userActivatedSession,
                phase: partnerModeController.phase,
                stealthBlocked:
                    StealthEntryLatch.shared.isRaised
                        || stealthMode.isActive,
                notesAreTaking:
                    meetingNotetaker.isTakingNotes,
                notesAreStarting:
                    meetingNotetaker.isStartingUp
              ) else {
            return
        }
        appendRouteReceipt(
            "PARTNER native lane returned microphone"
        )
        beginAutomaticPartnerListeningIfAllowed()
    }

    private func holdPartnerMicrophoneForMeetingNotesIfNeeded() {
        guard partnerModeIsActive,
              let partnerModeController else {
            return
        }
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        partnerModeController.enterWaiting()
        voiceState = .idle
        appendRouteReceipt(
            "PARTNER microphone handed to meeting notes"
        )
    }

    private func releasePartnerMicrophoneFromMeetingNotesIfNeeded() {
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed,
              partnerModeIsActive,
              let partnerModeController else {
            return
        }
        if partnerModeController.phase == .waiting {
            partnerModeController.resumeAfterMicrophoneHandoff()
        }
        resumePartnerListeningAfterNativeLaneIfAllowed()
    }

    private func handleAutomaticPartnerTurnTermination(
        _ termination:
            BuddyAutomaticPartnerTurnTermination
    ) {
        guard AceLicense.shared.admits(.partnerMode),
              directEffectsAreAllowed,
              partnerModeIsActive,
              let partnerModeController else {
            return
        }
        switch termination {
        case .silentWindowExpired:
            guard partnerModeController.phase
                    == .listening else {
                return
            }
            partnerModeController
                .finishSilentListeningWindow()
            voiceState = .idle
            partnerConsecutiveSilentWindows += 1
            appendRouteReceipt(
                "PARTNER silent listening window renewed "
                    + "consecutive=\(partnerConsecutiveSilentWindows)"
            )
            // Sustained silence in a session the owner opened to TALK is a
            // signal, not a state. Say it once, out loud, so "listening
            // perfectly" and "completely broken" stop looking identical.
            if PartnerSilentWindowPolicy.shouldSurfaceDeafness(
                consecutiveSilentWindows: partnerConsecutiveSilentWindows,
                alreadySurfacedForThisRun:
                    partnerDeafnessSurfacedForThisRun,
                userActivatedSession:
                    partnerModeController.userActivatedSession,
                stealthBlocked: StealthEntryLatch.shared.isRaised
                    || stealthMode.isActive
            ) {
                partnerDeafnessSurfacedForThisRun = true
                appendRouteReceipt(
                    "PARTNER deafness surfaced — spoken after "
                        + "\(partnerConsecutiveSilentWindows) silent windows"
                )
                speakPartnerStatus(PartnerSilentWindowPolicy.spokenLine)
            }
            beginAutomaticPartnerListeningIfAllowed()
        case .recognitionFailed(let explanation):
            partnerModeController
                .listeningDidNotStart(explanation)
            voiceState = .idle
            appendRouteReceipt(
                "PARTNER listening failed error="
                    + explanation
            )
        }
    }

    private func routePartnerModeCommand(
        _ command: PartnerModeCommand,
        transcript: String,
        context: OwnerTurnContext? = nil
    ) -> Bool {
        if command == .activate {
            activatePartnerMode(speakAcknowledgement: false)
            let reason: String
            let status: AceGoldWorkStatus
            let outcome: String
            if partnerModeIsActive {
                reason = "I'm here. Let's talk."
                status = .completed
                outcome = "completed.partner-activated"
            } else {
                reason = "Partner Mode could not open its private profile."
                status = .blocked
                outcome = "blocked.partner-activation"
            }
            let persisted = finishPartnerControlTurn(
                context: context,
                status: status,
                outcome: outcome,
                reason: reason,
                speak: false
            )
            if persisted, partnerModeIsActive {
                speakPartnerStatus(reason)
            } else if persisted {
                Task { [weak self] in
                    try? await self?.noraVoice.speakText(reason)
                }
            }
            return true
        }
        guard let partnerModeController,
              partnerModeController.userActivatedSession else {
            return false
        }

        // Owner recovery remains available after cancellation; anything that
        // resumes/listens/mutates/executes must pass a fresh central lease check.
        switch command {
        case .end, .wait, .mute:
            break
        case .activate:
            return true
        case .resume,
             .requestScreenContext,
             .correctMemory,
             .forgetMemory,
             .undoMemory:
            guard AceLicense.shared.admits(.partnerMode),
                  directEffectsAreAllowed else {
                appendRouteReceipt(
                    "PARTNER command refused reason=unlicensed command=\(command)"
                )
                return true
            }
        }

        switch command {
        case .activate:
            return true
        case .end:
            endPartnerMode(reason: .userEnded)
            _ = finishPartnerControlTurn(
                context: context,
                status: .completed,
                outcome: "completed.partner-ended",
                reason: "Partner Mode ended. Ace is back to normal.",
                speak: false,
                allowsVolatileTerminal: true
            )
        case .wait:
            buddyDictationManager.cancelCurrentDictation(
                preserveDraftText: false
            )
            partnerModeController.enterWaiting()
            voiceState = .idle
            _ = finishPartnerControlTurn(
                context: context,
                status: .completed,
                outcome: "completed.partner-waiting",
                reason: "I'll wait.",
                speak: false,
                allowsVolatileTerminal: true
            )
        case .mute:
            setPartnerMuted(true)
            _ = finishPartnerControlTurn(
                context: context,
                status: .completed,
                outcome: "completed.partner-muted",
                reason: "Partner Mode is muted.",
                speak: false,
                allowsVolatileTerminal: true
            )
        case .resume:
            partnerModeController.resume()
            let reason = "Partner Mode is listening again."
            if finishPartnerControlTurn(
                context: context,
                status: .completed,
                outcome: "completed.partner-resumed",
                reason: reason,
                speak: false
            ) {
                speakPartnerStatus(reason)
            }
        case .requestScreenContext:
            partnerModeController
                .enableScreenContextForSession()
            let reason =
                "Screen context is on for this Partner session. What should I look at?"
            if finishPartnerControlTurn(
                context: context,
                status: .completed,
                outcome: "completed.partner-screen-context-enabled",
                reason: reason,
                speak: false
            ) {
                speakPartnerStatus(reason)
            }
        case .correctMemory, .forgetMemory:
            guard let context,
                  let resolved = bindOwnerTurnContext(context) else {
                return true
            }
            sendPartnerTurn(
                transcript: resolved,
                includesExplicitScreenContext: false
            )
        case .undoMemory:
            guard let context,
                  bindOwnerTurnContext(context) != nil,
                  let workIdentifier = activeContextualOwnerRequest?
                    .childWorkCorrelationIdentifier else {
                return true
            }
            do {
                try partnerModeController
                    .undoLastMemoryReceipt()
                let reason = "I undid the last saved memory change."
                _ = finishDirectTextTerminal(
                    workCorrelationIdentifier: workIdentifier,
                    lane: .partner,
                    durableLane: "partner.memory",
                    status: .completed,
                    outcome: "completed.memory-undo",
                    verification: "verified",
                    reason: reason,
                    slot: .none,
                    source: .partner,
                    turnIdentifier: activeRoutingTurnID
                )
            } catch {
                let reason = "There is no current memory receipt to undo."
                _ = finishDirectTextTerminal(
                    workCorrelationIdentifier: workIdentifier,
                    lane: .partner,
                    durableLane: "partner.memory",
                    status: .blocked,
                    outcome: "blocked.no-memory-undo",
                    verification: "none",
                    reason: reason,
                    slot: .none,
                    source: .partner,
                    turnIdentifier: activeRoutingTurnID
                )
            }
        }
        return true
    }

    /// Immediate session controls run before durable work binding so a pending
    /// save or question cannot delay shutdown. Seal their admitted turn without
    /// inventing a work ID; other controls retain their durable work terminal.
    @discardableResult
    private func finishPartnerControlTurn(
        context: OwnerTurnContext?,
        status: AceGoldWorkStatus,
        outcome: String,
        reason: String,
        speak: Bool = true,
        allowsVolatileTerminal: Bool = false
    ) -> Bool {
        if allowsVolatileTerminal,
           activeContextualOwnerRequest == nil,
           let context,
           context.selectedRoute == "native.partner-command",
           context.sessionID == activeRoutingSessionID,
           context.turnID == activeRoutingTurnID,
           status == .completed {
            return finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .completed,
                outcome: outcome,
                reason: reason,
                durableVerification: "app-owned-partner-state",
                speak: speak
            )
        }
        guard let context,
              let request = activeContextualOwnerRequest,
              request.sourceSessionIdentifier == context.sessionID,
              request.sourceTurnIdentifier == context.turnID else {
            appendRouteReceipt(
                "PARTNER control terminal refused missing admitted work"
            )
            return false
        }
        return finishDirectTextTerminal(
            workCorrelationIdentifier:
                request.childWorkCorrelationIdentifier,
            lane: .partner,
            durableLane: "partner.control",
            status: status,
            outcome: outcome,
            verification: status == .completed
                ? "app-owned-partner-state" : "none",
            reason: reason,
            slot: .none,
            source: .partner,
            turnIdentifier: context.turnID,
            speak: speak
        )
    }

    /// Gold selects one typed capability. The app-owned request carries the
    /// admitted owner bytes and identities; execution never waits for an Ace
    /// confirmation.
    private func dispatchGoldDelegation(
        _ request: GoldExecutionRequest,
        providerTurn: AceProviderTurn
    ) async {
        guard request.sourceSessionIdentifier
                == AceEventBus.shared.sessionID else {
            appendRouteReceipt(
                "GOLD delegation refused stale session correlation="
                    + request.workCorrelationIdentifier
                        .uuidString.lowercased()
            )
            return
        }
        AceEventBus.shared.publishOutbound(
            source: .gold,
            state: .routed,
            payloadType: .executionReceipt,
            payload:
                "executor=background-slot sourceCorrelation="
                    + request.sourceCorrelationIdentifier
                        .uuidString.lowercased(),
            turnID: request.sourceTurnIdentifier,
            correlationID: request.workCorrelationIdentifier
        )
        await routeGoldRedTask(
            request,
            providerTurn: providerTurn
        )
    }

    private func completeGoldExecution(
        _ request: GoldExecutionRequest,
        outcome: RedExecutionOutcome,
        verification: RedExecutionVerification,
        spokenResult: String,
        durableOutcome: String? = nil,
        durableVerification: String? = nil,
        durableReason: String? = nil,
        executionSlot: BackgroundExecutionSlot = .red
    ) {
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            deferredGoldTerminals.removeValue(
                forKey: request.workCorrelationIdentifier
            )
            partnerDelegatedWorkIdentifiers.remove(
                request.workCorrelationIdentifier
            )
            return
        }
        // Stop may have already committed the authoritative terminal before
        // the cancelled child returns. Persist that winner and retire the late
        // callback; retrying its conflicting result would block every turn.
        if let committed = goldContextBundle.supersedingTerminal(
            workCorrelationIdentifier: request.workCorrelationIdentifier,
            sourceSessionIdentifier: request.sourceSessionIdentifier,
            sourceTurnIdentifier: request.workSourceTurnIdentifier,
            sourceCorrelationIdentifier: request.workSourceCorrelationIdentifier,
            proposedStatus: AceGoldWorkStatus(rawValue: outcome.rawValue) ?? .failed,
            proposedOutcome: durableOutcome ?? outcome.rawValue,
            proposedVerification: durableVerification ?? verification.rawValue,
            proposedReason: durableReason ?? Self.retainedAppResult(
                spokenResult,
                fallback: "The lane returned no readable terminal result. Completion is not verified."
            )
        ) {
            guard AceConversationHistory.saveBundle(
                goldContextBundle,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            ) else { return }
            deferredGoldTerminals.removeValue(
                forKey: request.workCorrelationIdentifier
            )
            partnerDelegatedWorkIdentifiers.remove(
                request.workCorrelationIdentifier
            )
            _ = redExecutionService.finish(
                turnID: request.sourceTurnIdentifier,
                result: OwnerCapabilityResult(
                    status: committed.status == .cancelled ? .cancelled : .attempted,
                    spokenSummary: committed.terminalReason ?? "Work already ended.",
                    contentFreeReceipt: "gold-terminal:existing-terminal-preserved",
                    recoveryReference: nil
                )
            )
            appendRouteReceipt(
                "GOLD late terminal reconciled with persisted winner work="
                    + request.workCorrelationIdentifier.uuidString.lowercased()
            )
            return
        }
        let proposedTerminal = DeferredGoldTerminal(
            request: request,
            outcome: outcome,
            verification: verification,
            spokenResult: spokenResult,
            durableOutcome: durableOutcome,
            durableVerification: durableVerification,
            durableReason: durableReason,
            executionSlot: executionSlot
        )
        if let existing = deferredGoldTerminals[
            request.workCorrelationIdentifier
        ] {
            guard existing == proposedTerminal else {
                appendRouteReceipt(
                    "GOLD deferred terminal conflict refused correlation="
                        + request.workCorrelationIdentifier
                            .uuidString.lowercased()
                )
                return
            }
        } else {
            deferredGoldTerminals[request.workCorrelationIdentifier] =
                proposedTerminal
        }
        let terminal = deferredGoldTerminals[
            request.workCorrelationIdentifier
        ] ?? proposedTerminal
        let bounded = Self.boundedSpokenAppResult(
            terminal.spokenResult,
            fallback:
                "The lane returned no readable terminal result. Completion is not verified."
        )
        guard recordGoldDelegationConversation(
            request: terminal.request,
            terminalResponse: Self.retainedAppResult(terminal.spokenResult, fallback: bounded),
            outcome: terminal.outcome,
            verification: terminal.verification,
            durableOutcome: terminal.durableOutcome,
            durableVerification: terminal.durableVerification,
            durableReason: terminal.durableReason,
            executionSlot: terminal.executionSlot
        ) else {
            appendRouteReceipt(
                "GOLD terminal deferred until durable-save correlation="
                    + request.workCorrelationIdentifier
                        .uuidString.lowercased()
            )
            return
        }
        guard request.sourceSessionIdentifier
                == AceEventBus.shared.sessionID else {
            deferredGoldTerminals.removeValue(
                forKey: request.workCorrelationIdentifier
            )
            appendRouteReceipt(
                "GOLD durable terminal kept; stale session refused publication correlation="
                    + request.workCorrelationIdentifier
                        .uuidString.lowercased()
            )
            return
        }
        let source = terminal.executionSlot.eventSource
        let state: AceEventState
        switch terminal.outcome {
        case .completed: state = .completed
        case .cancelled: state = .cancelled
        case .failed, .blocked: state = .failed
        }
        let recentWorkStatus: RecentOwnerWorkStatus
        let buyerWorkStatus: AceGoldWorkStatus
        switch terminal.outcome {
        case .completed:
            recentWorkStatus = .completed
            buyerWorkStatus = .completed
        case .cancelled:
            recentWorkStatus = .cancelled
            buyerWorkStatus = .cancelled
        case .failed:
            recentWorkStatus = .failed
            buyerWorkStatus = .failed
        case .blocked:
            recentWorkStatus = .blocked
            buyerWorkStatus = .blocked
        }
        let authoritativeOutcome = terminal.durableOutcome
            ?? terminal.outcome.rawValue
        let authoritativeVerification = terminal.durableVerification
            ?? terminal.verification.rawValue
        let wasPartnerDelegated = partnerDelegatedWorkIdentifiers.contains(
            request.workCorrelationIdentifier
        )
        let partnerSessionOwnsTerminal =
            wasPartnerDelegated && partnerModeIsActive
        guard performTerminalPublicationUnlessStealth({
            guard AceEventBus.shared.publishTerminalWork(
                source: source,
                state: state,
                payloadType: .executionReceipt,
                payload:
                    "outcome=\(authoritativeOutcome) verification=\(authoritativeVerification) sourceCorrelation="
                        + terminal.request.sourceCorrelationIdentifier
                            .uuidString.lowercased(),
                turnID: terminal.request.sourceTurnIdentifier,
                correlationID:
                    terminal.request.workCorrelationIdentifier
            ) else { return false }
            let terminalLane = terminal.executionSlot
                .recentOwnerWorkLane
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier:
                    terminal.request.workCorrelationIdentifier,
                lane: terminalLane,
                status: recentWorkStatus
            )
            let terminalPhase = buyerPhase(
                status: buyerWorkStatus,
                lane: terminalLane
            )
            upsertBuyerWorkReceipt(
                workID: terminal.request.workCorrelationIdentifier,
                lane: terminalLane,
                phase: terminalPhase,
                progress: buyerProgress(phase: terminalPhase, lane: terminalLane),
                terminalResult: bounded,
                recoveryAction: buyerRecoveryAction(
                    status: buyerWorkStatus
                )
            )
            if partnerSessionOwnsTerminal {
                _ = partnerModeController?.recordExecutionTerminal(
                    workerName: "Red",
                    workCorrelationIdentifier:
                        terminal.request.workCorrelationIdentifier,
                    outcome: authoritativeOutcome,
                    verification: authoritativeVerification,
                    exactResult: bounded
                )
            }
            showVisibleResponse(bounded)
            if partnerSessionOwnsTerminal,
               !meetingCaptureOwnsVoiceOutput {
                speakPartnerStatus(bounded)
            } else if !meetingCaptureOwnsVoiceOutput {
                Task { [weak self] in
                    guard let self,
                          self.directEffectsAreAllowed,
                          !self.stealthMode.isActive else { return }
                    let completed = await self.noraVoice
                        .speakTextToVerifiedCompletion(bounded)
                    self.appendRouteReceipt(
                        "GOLD terminal speech "
                            + (completed ? "complete" : "incomplete")
                            + " correlation="
                            + request.workCorrelationIdentifier
                                .uuidString.lowercased()
                    )
                }
            }
            return true
        }) else {
            appendRouteReceipt(
                "GOLD terminal publication refused correlation="
                    + request.workCorrelationIdentifier
                        .uuidString.lowercased()
            )
            return
        }
        deferredGoldTerminals.removeValue(
            forKey: request.workCorrelationIdentifier
        )
        partnerDelegatedWorkIdentifiers.remove(
            request.workCorrelationIdentifier
        )
        appendRouteReceipt(
            "GOLD terminal-receipt lane="
                + terminal.executionSlot.rawValue
                + " outcome=" + authoritativeOutcome
                + " verification=" + authoritativeVerification
                + " correlation="
                + request.workCorrelationIdentifier
                    .uuidString.lowercased()
        )
        let ownerResultStatus: OwnerCapabilityStatus
        switch terminal.outcome {
        case .completed:
            _ = redExecutionService.markCommitted(
                turnID: request.sourceTurnIdentifier
            )
            ownerResultStatus = terminal.verification == .verified
                ? .verified : .attempted
        case .cancelled:
            ownerResultStatus = .cancelled
        case .blocked:
            ownerResultStatus = .unavailable
        case .failed:
            ownerResultStatus = .failed
        }
        _ = redExecutionService.finish(
            turnID: request.sourceTurnIdentifier,
            result: OwnerCapabilityResult(
                status: ownerResultStatus,
                spokenSummary: bounded,
                contentFreeReceipt:
                    "gold-terminal:"
                        + authoritativeOutcome
                        + ":"
                        + authoritativeVerification,
                recoveryReference: nil
            )
        )
    }

    @discardableResult
    private func recordGoldDelegationConversation(
        request: GoldExecutionRequest,
        terminalResponse: String,
        outcome: RedExecutionOutcome,
        verification: RedExecutionVerification,
        durableOutcome: String? = nil,
        durableVerification: String? = nil,
        durableReason: String? = nil,
        executionSlot: BackgroundExecutionSlot = .red
    ) -> Bool {
        let status: AceGoldWorkStatus
        switch outcome {
        case .completed: status = .completed
        case .cancelled: status = .cancelled
        case .failed: status = .failed
        case .blocked: status = .blocked
        }
        let appended = goldContextBundle.appendExchange(
            workCorrelationIdentifier:
                request.workCorrelationIdentifier,
            assistantResponse: terminalResponse,
            status: status,
            lane: executionSlot.durableLane,
            terminalOutcome: durableOutcome ?? outcome.rawValue,
            terminalVerification:
                durableVerification ?? verification.rawValue,
            terminalReason: durableReason ?? terminalResponse
        )
        let persisted = appended
            && AceConversationHistory.saveBundle(
                goldContextBundle,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        appendRouteReceipt(
            "GOLD-CONTEXT terminal persisted="
                + (persisted ? "true" : "false")
                + " work="
                + request.workCorrelationIdentifier
                    .uuidString.lowercased()
        )
        return persisted
    }

    /// One persistent terminal seam shared by every non-model execution lane.
    /// The record contains only exact app-observed outcome/verification/reason
    /// and the already-bound work correlation; it never promotes model prose
    /// into memory unless that prose is itself the visible terminal receipt.
    @discardableResult
    private func persistDurableWorkTerminal(
        workCorrelationIdentifier: UUID,
        lane: String,
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String
    ) -> Bool {
        let boundedOutcome = AceGoldContextBundle
            .boundedTerminalField(
                outcome,
                maximum:
                    AceGoldContextBundle
                        .maximumTerminalOutcomeCharacters
            )
        let boundedVerification = AceGoldContextBundle
            .boundedTerminalField(
                verification,
                maximum:
                    AceGoldContextBundle
                        .maximumTerminalVerificationCharacters
            )
        let boundedReason = AceGoldContextBundle
            .boundedTerminalField(
                reason,
                maximum:
                    AceGoldContextBundle
                        .maximumTerminalReasonCharacters
            )
        if let existing = goldContextBundle.workRecords.first(where: {
            $0.workCorrelationIdentifier
                == workCorrelationIdentifier
        }), existing.status != .running {
            // Terminal receipts are immutable. A repeated identical callback
            // is accepted only as an idempotent save retry; a conflicting late
            // deadline/cancel/result cannot rewrite the first app-owned truth.
            guard existing.status == status,
                  existing.terminalOutcome == boundedOutcome,
                  existing.terminalVerification == boundedVerification,
                  existing.terminalReason == boundedReason,
                  existing.matchesRetainedTerminalResult(reason) else {
                appendRouteReceipt(
                    "DURABLE terminal conflict refused work="
                        + workCorrelationIdentifier
                            .uuidString.lowercased()
                )
                return false
            }
            return AceConversationHistory.saveBundle(
                goldContextBundle,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        }
        let updated = goldContextBundle.transitionWork(
            workCorrelationIdentifier:
                workCorrelationIdentifier,
            lane: lane,
            status: status,
            terminalOutcome: boundedOutcome,
            terminalVerification: boundedVerification,
            terminalReason: reason
        )
        return updated
            && AceConversationHistory.saveBundle(
                goldContextBundle,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
    }

    private func refreshBuyerWorkReceiptsFromDurableContext() {
        buyerWorkReceipts = goldContextBundle.workRecords
            .suffix(12)
            .reversed()
            .map { record in
                let lane = buyerLane(for: record.lane)
                let phase = buyerPhase(
                    status: record.status,
                    lane: lane
                )
                let terminal = record.status == .running
                    ? nil : record.displayTerminalResult
                return AceBuyerWorkReceipt(
                    id: record.workCorrelationIdentifier,
                    boundedTaskDescription:
                        record.appOwnedRequestDescription,
                    owningLane: lane,
                    phase: phase,
                    acceptedAt: record.createdAt,
                    updatedAt: record.updatedAt,
                    mostRecentRealProgress:
                        buyerProgress(
                            phase: phase,
                            lane: lane
                        ),
                    terminalResult: terminal,
                    recoveryAction: buyerRecoveryAction(
                        status: record.status
                    )
                )
            }
    }

    private func buyerLane(for durableLane: String)
        -> RecentOwnerWorkLane {
        switch durableLane.lowercased() {
        case "gold", "app-action": return .gold
        case "partner": return .partner
        case "hq", "ace-hq": return .hq
        case "red": return .red
        case "silver", "workflow": return .silver
        case "notes": return .notes
        case "trading": return .trading
        case "briefing": return .briefing
        default: return .direct
        }
    }

    private func buyerPhase(
        status: AceGoldWorkStatus,
        lane: RecentOwnerWorkLane
    ) -> AceBuyerWorkReceipt.Phase {
        switch status {
        case .completed: return .completed
        case .blocked: return .blocked
        case .failed: return .failed
        case .cancelled: return .cancelled
        case .running:
            switch lane {
            case .direct: return .accepted
            case .gold, .partner: return .processing
            case .hq, .red, .silver, .notes, .trading, .briefing:
                return .executing
            }
        }
    }

    private func buyerProgress(
        phase: AceBuyerWorkReceipt.Phase,
        lane: RecentOwnerWorkLane
    ) -> String {
        switch phase {
        case .accepted: return "Request saved to Ace's durable work ledger."
        case .clarifying: return "Ace is waiting for one required owner value."
        case .processing:
            return "\(lane.buyerLabel) accepted the correlated provider turn."
        case .executing:
            return "\(lane.buyerLabel) owns the correlated execution."
        case .completed: return "A terminal completion receipt was saved."
        case .blocked: return "A terminal blocked receipt was saved."
        case .failed: return "A terminal failure receipt was saved."
        case .cancelled: return "A terminal cancellation receipt was saved."
        }
    }

    private func buyerRecoveryAction(
        status: AceGoldWorkStatus
    ) -> String? {
        switch status {
        case .blocked, .failed:
            return "Use Retry on this receipt to submit the same bounded request as a new correlated attempt."
        case .running, .completed, .cancelled:
            return nil
        }
    }

    private func upsertBuyerWorkReceipt(
        workID: UUID,
        lane: RecentOwnerWorkLane,
        phase: AceBuyerWorkReceipt.Phase,
        progress: String,
        terminalResult: String? = nil,
        recoveryAction: String? = nil
    ) {
        let durable = goldContextBundle.workRecords.first {
            $0.workCorrelationIdentifier == workID
        }
        let existing = buyerWorkReceipts.first { $0.id == workID }
        guard let description = existing?.boundedTaskDescription
                ?? durable?.appOwnedRequestDescription,
              let acceptedAt = existing?.acceptedAt
                ?? durable?.createdAt else { return }
        let receipt = AceBuyerWorkReceipt(
            id: workID,
            boundedTaskDescription: description,
            owningLane: lane,
            phase: phase,
            acceptedAt: acceptedAt,
            updatedAt: Date(),
            mostRecentRealProgress: progress,
            terminalResult: durable?.displayTerminalResult ?? terminalResult,
            recoveryAction: recoveryAction
        )
        buyerWorkReceipts.removeAll { $0.id == workID }
        buyerWorkReceipts.insert(receipt, at: 0)
        if buyerWorkReceipts.count > 12 {
            buyerWorkReceipts.removeLast(
                buyerWorkReceipts.count - 12
            )
        }
    }

    private func publishBuyerWorkAcceptance(
        _ request: ContextualOwnerRequest,
        speak: Bool = false
    ) {
        let workID = request.childWorkCorrelationIdentifier
        upsertBuyerWorkReceipt(
            workID: workID,
            lane: .direct,
            phase: .accepted,
            progress: "Request saved to Ace's durable work ledger."
        )
        guard speak,
              let spoken = buyerWorkReceipts.first(where: {
            $0.id == workID
        })?.spokenAcceptance else { return }
        if meetingCaptureOwnsVoiceOutput {
            deferredBuyerWorkReceiptSpeech[workID] = spoken
            return
        }
        Task { [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            try? await self.noraVoice.speakText(
                spoken,
                priority: .background
            )
        }
    }

    private func publishCurrentWorkStatus(
        includeRecentTerminal: Bool
    ) {
        let unfinishedPhases: Set<AceBuyerWorkReceipt.Phase> = [
            .accepted, .clarifying, .processing, .executing,
        ]
        let unfinished = buyerWorkReceipts
            .filter { unfinishedPhases.contains($0.phase) }
            .sorted { $0.updatedAt > $1.updatedAt }
        let visibleLine: String
        let spokenLine: String
        if let receipt = unfinished.first {
            let elapsedSeconds = max(
                0,
                Int(Date().timeIntervalSince(receipt.acceptedAt))
            )
            visibleLine = "Work \(receipt.durableWorkID). "
                + "Task: \(receipt.boundedTaskDescription). "
                + "Owner: \(receipt.owningLane.buyerLabel). "
                + "Phase: \(receipt.phase.rawValue). "
                + "Elapsed: \(elapsedSeconds) seconds. "
                + "Latest verified progress: "
                + receipt.mostRecentRealProgress
            spokenLine = receipt.spokenStatus()
        } else if let liveLane = currentUnreceiptedWorkLaneDescription() {
            visibleLine = "Ace has active \(liveLane), but its durable work receipt "
                + "is missing. That work is still running; open Work Receipts "
                + "for the exact recovery state."
            spokenLine = "Ace has active \(liveLane), but its work receipt "
                + "is missing. The work is still running."
        } else if includeRecentTerminal,
                  let receipt = buyerWorkReceipts.max(by: {
                      $0.updatedAt < $1.updatedAt
                  }) {
            visibleLine = "Most recent work \(receipt.durableWorkID). "
                + "Task: \(receipt.boundedTaskDescription). "
                + "Owner: \(receipt.owningLane.buyerLabel). "
                + "Terminal phase: \(receipt.phase.rawValue). "
                + (receipt.terminalResult
                    ?? receipt.mostRecentRealProgress)
            spokenLine = receipt.spokenStatus()
        } else {
            visibleLine = "Every Ace work lane is idle. There is no accepted task "
                + "currently running, clarifying, or waiting for recovery."
            spokenLine = "Every Ace work lane is idle."
        }
        appendRouteReceipt(
            "ROUTE work-status active=\(!unfinished.isEmpty)"
        )
        showVisibleResponse(visibleLine)
        Task { [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            try? await self.noraVoice.speakText(spokenLine)
        }
    }

    private func currentUnreceiptedWorkLaneDescription() -> String? {
        if workflowRuntime.isPlanning || workflowRuntime.isBuilding {
            return "Silver workflow work"
        }
        if backgroundAgent.isWorking { return "Red execution" }
        if silverBackgroundAgent.isWorking { return "Silver execution" }
        if appActionPlanningTask != nil { return "app-action planning" }
        if currentResponseTask != nil { return "Default brain processing" }
        if morningLinkBriefRuntime.isRunning {
            return "morning briefing execution"
        }
        if meetingNotetaker.isTakingNotes
            || meetingNotetaker.isStartingUp
            || meetingNotetaker.isWindingDown {
            return "Meeting Notes work"
        }
        if let partnerModeController,
           partnerModeController.phase == .processing
            || partnerModeController.phase == .waiting {
            return "Partner processing"
        }
        return nil
    }

    private func deliverDeferredBuyerWorkReceiptSpeech() {
        guard !meetingCaptureOwnsVoiceOutput,
              !deferredBuyerWorkReceiptSpeech.isEmpty else { return }
        let pending = deferredBuyerWorkReceiptSpeech
            .sorted { $0.key.uuidString < $1.key.uuidString }
            .map(\.value)
        deferredBuyerWorkReceiptSpeech.removeAll()
        Task { [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            for spoken in pending {
                try? await self.noraVoice.speakText(
                    spoken,
                    priority: .background
                )
            }
        }
    }

    func buyerWorkReceiptRetryRefusal(_ workID: UUID) -> String? {
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            return "Leave Private Mode before retrying this task."
        }
        guard let receipt = buyerWorkReceipts.first(where: { $0.id == workID }),
              receipt.phase == .blocked || receipt.phase == .failed,
              let durable = goldContextBundle.workRecords.first(where: {
                  $0.workCorrelationIdentifier == workID
              }) else { return "That work receipt is no longer available." }
        if let reason = goldContextBundle.retryRefusalReason(for: durable.workCorrelationIdentifier) { return reason }
        guard !buyerWorkReceipts.contains(where: { !$0.isTerminal }),
              currentUnreceiptedWorkLaneDescription() == nil else {
            return "Finish or stop the current task before retrying this one."
        }
        return nil
    }

    func retryBuyerWorkReceipt(_ workID: UUID) {
        goldContextBundle = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        if let reason = buyerWorkReceiptRetryRefusal(workID) {
            showVisibleResponse(reason)
            return
        }
        appendRouteReceipt(
            "WORK retry owner-requested prior=" + workID.uuidString.lowercased()
        )
        ingestOwnerUtterance(
            "Retry selected work", origin: .directHumanUIAction,
            selectedReceiptRetryWorkID: workID
        )
    }

    /// Transfers one admitted child from the provisional direct lane to the
    /// route that owns its next asynchronous/effectful step. The candidate is
    /// committed to RAM only after the atomic bundle save succeeds, so a save
    /// refusal cannot leave a non-durable lane or a process-local ghost.
    @discardableResult
    private func bindRunningWorkDurably(
        workCorrelationIdentifier: UUID?,
        lane: RecentOwnerWorkLane,
        durableLane: String
    ) -> Bool {
        guard let workCorrelationIdentifier else { return false }
        var candidateBundle = goldContextBundle
        guard candidateBundle.transitionWork(
            workCorrelationIdentifier:
                workCorrelationIdentifier,
            lane: durableLane,
            status: .running
        ), AceConversationHistory.saveBundle(
            candidateBundle,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        ) else {
            return false
        }
        goldContextBundle = candidateBundle
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier:
                workCorrelationIdentifier,
            lane: lane,
            status: .running
        )
        upsertBuyerWorkReceipt(
            workID: workCorrelationIdentifier,
            lane: lane,
            phase: buyerPhase(status: .running, lane: lane),
            progress: buyerProgress(
                phase: buyerPhase(status: .running, lane: lane),
                lane: lane
            )
        )
        return true
    }

    @discardableResult
    private func persistDirectWorkTerminal(
        workCorrelationIdentifier: UUID?,
        lane: RecentOwnerWorkLane,
        durableLane: String,
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String
    ) -> Bool {
        guard let workCorrelationIdentifier else { return false }
        let recentStatus: RecentOwnerWorkStatus
        switch status {
        case .running: recentStatus = .running
        case .completed: recentStatus = .completed
        case .failed: recentStatus = .failed
        case .blocked: recentStatus = .blocked
        case .cancelled: recentStatus = .cancelled
        }
        let accepted = persistDurableWorkTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: durableLane,
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason
        )
        if accepted {
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier: workCorrelationIdentifier,
                lane: lane,
                status: recentStatus
            )
            let phase = buyerPhase(status: status, lane: lane)
            upsertBuyerWorkReceipt(
                workID: workCorrelationIdentifier,
                lane: lane,
                phase: phase,
                progress: buyerProgress(
                    phase: phase,
                    lane: lane
                ),
                terminalResult: reason,
                recoveryAction: buyerRecoveryAction(status: status)
            )
        }
        return accepted
    }

    @discardableResult
    private func persistDirectWorkTerminal(
        workCorrelationIdentifier: UUID?,
        result: BackgroundAgentTerminalResult
    ) -> Bool {
        let status: AceGoldWorkStatus
        switch result.kind {
        case .completed: status = .completed
        case .blocked: status = .blocked
        case .failed: status = .failed
        case .cancelled: status = .cancelled
        }
        return persistDirectWorkTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: .red,
            durableLane: "red",
            status: status,
            outcome: result.outcome,
            verification: result.verification,
            reason: result.reason
        )
    }

    @discardableResult
    private func finishDirectWorkTerminal(
        workCorrelationIdentifier: UUID?,
        lane: RecentOwnerWorkLane,
        durableLane: String,
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String,
        slot: DeferredDirectWorkSlot,
        redPublication: DeferredRedTerminalPublication? = nil,
        textPublication: DeferredDirectTextPublication? = nil,
        partnerTurnPublication:
            DeferredPartnerTurnPublication? = nil,
        nativePublication:
            DeferredNativeTerminalPublication? = nil
    ) -> Bool {
        guard let workCorrelationIdentifier else { return false }
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            deferredDirectTerminals.removeValue(
                forKey: workCorrelationIdentifier
            )
            return false
        }
        let terminal = DeferredDirectTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: lane,
            durableLane: durableLane,
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason,
            slot: slot,
            redPublication: redPublication,
            textPublication: textPublication,
            partnerTurnPublication: partnerTurnPublication,
            nativePublication: nativePublication
        )
        if let existing = deferredDirectTerminals[
            workCorrelationIdentifier
        ] {
            // First terminal wins even when its disk save is temporarily
            // refused. A later timeout/cancel callback cannot replace the exact
            // completion tuple waiting to retry.
            guard existing == terminal else {
                appendRouteReceipt(
                    "DURABLE deferred terminal conflict refused work="
                        + workCorrelationIdentifier
                            .uuidString.lowercased()
                )
                return false
            }
            return retryDeferredDirectTerminal(existing)
        }
        deferredDirectTerminals[workCorrelationIdentifier] = terminal
        return retryDeferredDirectTerminal(terminal)
    }

    @discardableResult
    private func finishDirectRedTerminal(
        workCorrelationIdentifier: UUID?,
        result: BackgroundAgentTerminalResult,
        turnIdentifier: UUID?,
        correlationIdentifier: UUID,
        speakResult: Bool,
        slot: DeferredDirectWorkSlot = .activeRed,
        executionSlot: BackgroundExecutionSlot = .red
    ) -> Bool {
        let status: AceGoldWorkStatus
        switch result.kind {
        case .completed: status = .completed
        case .blocked: status = .blocked
        case .failed: status = .failed
        case .cancelled: status = .cancelled
        }
        return finishDirectWorkTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: executionSlot.recentOwnerWorkLane,
            durableLane: executionSlot.durableLane,
            status: status,
            outcome: result.outcome,
            verification: result.verification,
            reason: result.reason,
            slot: slot,
            redPublication: DeferredRedTerminalPublication(
                turnIdentifier: turnIdentifier,
                correlationIdentifier: correlationIdentifier,
                result: result,
                speakResult: speakResult,
                executionSlot: executionSlot
            )
        )
    }

    @discardableResult
    private func finishDirectTextTerminal(
        workCorrelationIdentifier: UUID?,
        lane: RecentOwnerWorkLane,
        durableLane: String,
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String,
        slot: DeferredDirectWorkSlot,
        source: AceEventSource,
        turnIdentifier: UUID?,
        speak: Bool = true
    ) -> Bool {
        finishDirectWorkTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: lane,
            durableLane: durableLane,
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason,
            slot: slot,
            textPublication: DeferredDirectTextPublication(
                source: source,
                turnIdentifier: turnIdentifier,
                text: reason,
                speak: speak
            )
        )
    }

    private func retainNativeConversationTerminal(
        turnID: UUID?, correlationID: UUID?,
        status: AceEventState, response: String
    ) {
        guard let exchange = nativeConversationContext.finish(
                turnID: turnID, correlationID: correlationID,
                sessionID: AceEventBus.shared.sessionID,
                partnerSessionID: partnerModeController?.activeSessionID,
                cancelled: status == .cancelled, response: response
              ) else { return }
        if let sessionID = exchange.request.partnerSessionID {
            _ = partnerModeController?.recordNativeExchange(
                sessionIdentifier: sessionID,
                userTranscript: exchange.request.userTranscript,
                assistantResponse: exchange.assistantResponse
            )
        }
        appendRouteReceipt("NATIVE-CONTEXT retained turn="
            + AceEventIdentifier.short(exchange.request.turnID))
    }

    /// Publishes a content-free terminal for routes whose live request values
    /// are prohibited from Gold/recent-work persistence. User-facing detail is
    /// shown and spoken only after the exact admitted correlation seals once.
    @discardableResult
    private func finishVolatileOwnerTurn(
        turnID: UUID?,
        correlationID: UUID?,
        status: AceEventState,
        outcome: String,
        reason: String,
        durableReason: String? = nil,
        durableVerification: String = "app-owned-native-route",
        durableStatusOverride: AceGoldWorkStatus? = nil,
        visibleResponseRetention:
            OwnerVisibleResponseRetention = .standard,
        showVisible: Bool = true,
        speak: Bool = true
    ) -> Bool {
        guard status.isTerminal,
              let correlationID,
              directEffectsAreAllowed,
              !stealthMode.isActive else { return false }
        let receiptOnlyWorkID =
            receiptOnlyWorkIDBySourceCorrelationID[correlationID]
        if let receiptOnlyWorkID {
            let durableStatus: AceGoldWorkStatus
            if let durableStatusOverride {
                durableStatus = durableStatusOverride
            } else {
                switch status {
                case .completed:
                    durableStatus = .completed
                case .failed:
                    durableStatus = .failed
                case .cancelled:
                    durableStatus = .cancelled
                case .partial, .final, .routed, .executing:
                    return false
                }
            }
            guard persistDirectWorkTerminal(
                workCorrelationIdentifier: receiptOnlyWorkID,
                lane: .direct,
                durableLane: AceGoldContextBundle.receiptOnlyLane,
                status: durableStatus,
                outcome: outcome,
                verification: durableVerification,
                reason: durableReason ?? reason
            ) else {
                appendRouteReceipt(
                    "INQUIRY terminal persistence deferred work="
                        + receiptOnlyWorkID.uuidString.lowercased()
                )
                return false
            }
        }
        let published = ownerTurnLifecycle.finishManagerDispatch(
            turnID: turnID,
            correlationID: correlationID,
            status: status,
            outcome: outcome
        )
        guard published else { return false }
        retainNativeConversationTerminal(
            turnID: turnID, correlationID: correlationID,
            status: status, response: reason
        )
        if let receiptOnlyWorkID {
            receiptOnlyWorkIDBySourceCorrelationID.removeValue(
                forKey: correlationID
            )
            if meetingCaptureOwnsVoiceOutput {
                deferredBuyerWorkReceiptSpeech[receiptOnlyWorkID] =
                    reason
            }
        }
        if showVisible,
           speak,
           partnerModeIsActive,
           !meetingCaptureOwnsVoiceOutput {
            // Native results submitted through the Partner composer must own
            // Partner's verified speak -> listen transition. A detached Nora
            // task leaves the controller ready and can reopen capture while a
            // queued response is still playing.
            speakPartnerStatus(reason)
            return true
        }
        if showVisible {
            showVisibleResponse(
                reason,
                retention: visibleResponseRetention
            )
        }
        if speak && !meetingCaptureOwnsVoiceOutput {
            Task { [weak self] in
                guard let self,
                      self.directEffectsAreAllowed,
                      !self.stealthMode.isActive else { return }
                try? await self.noraVoice.speakText(reason)
            }
        }
        return true
    }

    @discardableResult
    private func finishPartnerTurnTerminal(
        workCorrelationIdentifier: UUID?,
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String,
        publication: DeferredPartnerTurnPublication?
    ) -> Bool {
        finishDirectWorkTerminal(
            workCorrelationIdentifier: workCorrelationIdentifier,
            lane: .partner,
            durableLane: "partner",
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason,
            slot: .none,
            partnerTurnPublication: publication
        )
    }

    @discardableResult
    private func retryDeferredDirectTerminal(
        _ terminal: DeferredDirectTerminal
    ) -> Bool {
        guard persistDirectWorkTerminal(
            workCorrelationIdentifier:
                terminal.workCorrelationIdentifier,
            lane: terminal.lane,
            durableLane: terminal.durableLane,
            status: terminal.status,
            outcome: terminal.outcome,
            verification: terminal.verification,
            reason: terminal.reason
        ) else {
            return false
        }
        let published: Bool
        if let redPublication = terminal.redPublication {
            published = publishDeferredRedTerminal(redPublication)
        } else if let textPublication = terminal.textPublication {
            published = publishDeferredDirectTextTerminal(
                terminal,
                publication: textPublication
            )
        } else if let partnerPublication =
                    terminal.partnerTurnPublication {
            published = publishDeferredPartnerTurnTerminal(
                partnerPublication
            )
        } else if let nativePublication =
                    terminal.nativePublication {
            published = publishDeferredNativeTerminal(
                nativePublication
            )
        } else {
            published = true
        }
        guard published else { return false }
        deferredDirectTerminals.removeValue(
            forKey: terminal.workCorrelationIdentifier
        )
        clearDirectWorkSlot(
            terminal.slot,
            workCorrelationIdentifier:
                terminal.workCorrelationIdentifier
        )
        return true
    }

    /// Desktop actions first seal their durable buyer receipt, then close the
    /// exact admitted lifecycle and expose the observed result. This prevents
    /// the top-level fail-closed sweep from showing BLOCKED while an AX action
    /// has already succeeded on screen.
    private func publishDeferredNativeTerminal(
        _ publication: DeferredNativeTerminalPublication
    ) -> Bool {
        guard ownerTurnLifecycle.finishManagerDispatch(
            turnID: publication.turnIdentifier,
            correlationID: publication.correlationIdentifier,
            status: publication.eventStatus,
            outcome: publication.lifecycleOutcome
        ) else { return false }
        retainNativeConversationTerminal(
            turnID: publication.turnIdentifier,
            correlationID: publication.correlationIdentifier,
            status: publication.eventStatus, response: publication.visibleText
        )
        if partnerModeIsActive, !meetingCaptureOwnsVoiceOutput {
            speakPartnerStatus(publication.visibleText)
            return true
        }
        showVisibleResponse(publication.visibleText)
        if !meetingCaptureOwnsVoiceOutput {
            Task { [weak self] in
                guard let self,
                      self.directEffectsAreAllowed,
                      !self.stealthMode.isActive else { return }
                try? await self.noraVoice.speakText(
                    publication.visibleText
                )
            }
        }
        return true
    }

    private func clearDirectWorkSlot(
        _ slot: DeferredDirectWorkSlot,
        workCorrelationIdentifier: UUID
    ) {
        switch slot {
        case .activeRed:
            if activeDirectRedWorkCorrelationIdentifier
                == workCorrelationIdentifier {
                activeDirectRedWorkCorrelationIdentifier = nil
            }
        case .activeSilver:
            if activeDirectSilverWorkCorrelationIdentifier
                == workCorrelationIdentifier {
                activeDirectSilverWorkCorrelationIdentifier = nil
            }
        case .pendingWorkflow:
            if pendingDirectWorkflowWorkCorrelationIdentifier
                == workCorrelationIdentifier {
                pendingDirectWorkflowWorkCorrelationIdentifier = nil
            }
        case .activeWorkflow(let operationIdentifier):
            if activeDirectWorkflowWorkCorrelationIdentifier
                == workCorrelationIdentifier,
               activeDirectWorkflowOperationIdentifier
                == operationIdentifier {
                activeDirectWorkflowWorkCorrelationIdentifier = nil
                activeDirectWorkflowOperationIdentifier = nil
            }
        case .none:
            break
        }
    }

    private func sourceTurnIdentifier(
        forWork workCorrelationIdentifier: UUID?
    ) -> UUID? {
        guard let workCorrelationIdentifier else { return nil }
        return recentOwnerWorkStore.entry(
            workCorrelationIdentifier: workCorrelationIdentifier
        )?.sourceTurnIdentifier
            ?? goldContextBundle.workRecords.first(where: {
                $0.workCorrelationIdentifier
                    == workCorrelationIdentifier
            })?.sourceTurnIdentifier
    }

    private func publishDeferredRedTerminal(
        _ publication: DeferredRedTerminalPublication
    ) -> Bool {
        let terminalState: AceEventState
        switch publication.result.kind {
        case .completed: terminalState = .completed
        case .cancelled: terminalState = .cancelled
        case .blocked, .failed: terminalState = .failed
        }
        guard performTerminalPublicationUnlessStealth({
            guard AceEventBus.shared.publishTerminalWork(
                source: publication.executionSlot.eventSource,
                state: terminalState,
                payloadType: .executionReceipt,
                payload:
                    "outcome=\(publication.result.outcome) verification=\(publication.result.verification)",
                turnID: publication.turnIdentifier,
                correlationID: publication.correlationIdentifier
            ) else { return false }
            if let spokenSummary = publication.result.spokenSummary,
               publication.speakResult {
                showVisibleResponse(spokenSummary)
                if !meetingCaptureOwnsVoiceOutput {
                    Task { [weak self] in
                        guard let self,
                              self.directEffectsAreAllowed,
                              !self.stealthMode.isActive else { return }
                        try? await self.noraVoice.speakText(
                            spokenSummary,
                            from: publication.executionSlot.voiceLane,
                            priority: .background
                        )
                    }
                }
            }
            return true
        }) else { return false }
        return true
    }

    private func publishDeferredDirectTextTerminal(
        _ terminal: DeferredDirectTerminal,
        publication: DeferredDirectTextPublication
    ) -> Bool {
        let state: AceEventState
        switch terminal.status {
        case .completed: state = .completed
        case .cancelled: state = .cancelled
        case .running: state = .executing
        case .failed, .blocked: state = .failed
        }
        guard performTerminalPublicationUnlessStealth({
            guard AceEventBus.shared.publishTerminalWork(
                source: publication.source,
                state: state,
                payloadType: .executionReceipt,
                payload:
                    "outcome=\(terminal.outcome) verification=\(terminal.verification)",
                turnID: publication.turnIdentifier,
                correlationID:
                    terminal.workCorrelationIdentifier
            ) else { return false }
            showVisibleResponse(publication.text)
            if publication.speak && !meetingCaptureOwnsVoiceOutput {
                Task { [weak self] in
                    guard let self,
                          self.directEffectsAreAllowed,
                          !self.stealthMode.isActive else { return }
                    try? await self.noraVoice.speakText(publication.text)
                }
            }
            return true
        }) else { return false }
        return true
    }

    private func publishDeferredPartnerTurnTerminal(
        _ publication: DeferredPartnerTurnPublication
    ) -> Bool {
        guard let controller = partnerModeController,
              controller.userActivatedSession else { return false }
        return PartnerPreparedTurnPublicationBoundary
            .persistThenPublish(
                persist: {
                    if case .completed(let prepared, _, _) =
                            publication {
                        try controller
                            .persistPreparedTurnCompletion(prepared)
                    }
                },
                performUnlessRaised: { body in
                    self.performTerminalPublicationUnlessStealth(body)
                },
                onPersistenceFailure: { error in
                    let message = PartnerSecureStore.ownerFacingFailure(error)
                    controller.turnDidFail(message)
                    self.voiceState = .idle
                    self.showVisibleResponse(message)
                },
                publish: {
            switch publication {
            case .failed(let text):
                controller.turnDidFail(text)
                self.voiceState = .idle
                self.speakPartnerStatus(text)
            case .completed(
                let prepared,
                let spokenText,
                let responseGeneration
            ):
                guard controller.publishPreparedTurnCompletion(
                    prepared
                ) else { return false }
                self.showVisibleResponse(spokenText)
                controller.beginSpeaking()
                self.voiceState = .responding
                let responseTaskIdentity = UUID()
                self.currentResponseTaskIdentity = responseTaskIdentity
                self.currentResponseTask = Task { @MainActor [weak self] in
                    guard let self else { return }
                    defer {
                        self.clearCurrentResponseTask(
                            ifMatching: responseTaskIdentity
                        )
                    }
                    guard self.directEffectsAreAllowed,
                          !self.stealthMode.isActive else { return }
                    let completed = await self.noraVoice
                        .speakTextToVerifiedCompletion(spokenText)
                    guard !Task.isCancelled,
                          responseGeneration
                            == self.partnerResponseGeneration,
                          self.partnerModeIsActive else {
                        return
                    }
                    let controller = self.partnerModeController
                    let mayReopen = PartnerTurnLoopPolicy
                        .shouldReopenMicrophone(
                            speechCompletion: completed
                                ? .completed : .failed,
                            currentPhase: controller?.phase
                                ?? .inactive,
                            userActivatedSession:
                                controller?.userActivatedSession
                                    ?? false,
                            stealthBlocked:
                                StealthEntryLatch.shared.isRaised
                                    || self.stealthMode.isActive,
                            muteRequested:
                                controller?.isMicrophoneMuted == true,
                            waitRequested:
                                controller?.phase == .waiting,
                            sessionIdentifierMatches:
                                responseGeneration
                                    == self.partnerResponseGeneration
                        )
                    if completed {
                        controller?.finishVerifiedSpeech()
                    } else {
                        controller?.speechDidNotComplete()
                    }
                    self.voiceState = .idle
                    if mayReopen {
                        self.beginAutomaticPartnerListeningIfAllowed()
                    }
                }
            }
            return true
                }
            )
    }

    /// The durable save happens first. This final admission contains only
    /// bounded in-process publication; Private Mode entry either closes the wall first or waits
    /// for this small state mutation to finish. No filesystem or awaited work
    /// belongs in the body.
    private func performTerminalPublicationUnlessStealth(
        _ body: () -> Bool
    ) -> Bool {
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            return false
        }
        return StealthEntryLatch.shared.performUnlessRaised {
            guard directEffectsAreAllowed, !stealthMode.isActive else {
                return false
            }
            return body()
        } ?? false
    }

    /// Retries an exact terminal tuple after a Stealth/disk refusal. Identity is
    /// retained until the atomic Gold bundle save succeeds; only then may the
    /// pending/active slot clear or an external terminal become visible.
    @discardableResult
    func retryDeferredDurableTerminalsIfSafe() -> Bool {
        guard directEffectsAreAllowed else { return false }
        for terminal in Array(deferredDirectTerminals.values) {
            _ = retryDeferredDirectTerminal(terminal)
        }
        for terminal in Array(deferredGoldTerminals.values) {
            completeGoldExecution(
                terminal.request,
                outcome: terminal.outcome,
                verification: terminal.verification,
                spokenResult: terminal.spokenResult,
                durableOutcome: terminal.durableOutcome,
                durableVerification: terminal.durableVerification,
                durableReason: terminal.durableReason,
                executionSlot: terminal.executionSlot
            )
        }
        for terminal in Array(deferredGoldAnswerTerminals.values) {
            _ = retryDeferredGoldAnswerTerminal(terminal)
        }
        for terminal in Array(
            deferredAceHQPreDispatchTerminals.values
        ) {
            _ = retryDeferredAceHQPreDispatchTerminal(terminal)
        }
        if let terminal = deferredAppActionTerminal {
            _ = retryDeferredAppActionTerminal(terminal)
        }
        return deferredDirectTerminals.isEmpty
            && deferredGoldTerminals.isEmpty
            && deferredGoldAnswerTerminals.isEmpty
            && deferredAppActionTerminal == nil
    }

    private func speakPartnerStatus(
        _ text: String,
        persistence: VoiceQueue.Persistence = .durableTranscriptAndEvents
    ) {
        // Partner advises; it never acts (`AceLaneAuthority.mayCauseDirectEffect`
        // is false for `.partner`). Publishing its line as `.partnerAdvice`
        // keeps that true in the event stream as well as in the code: the notes
        // subscription refuses this payload type outright, so a Partner aside
        // cannot end up in the owner's meeting notes.
        if persistence == .durableTranscriptAndEvents {
            AceEventBus.shared.publishOutbound(
                source: .partner,
                state: .completed,
                payloadType: .partnerAdvice,
                payload: text,
                turnID: activeRoutingTurnID
            )
        }
        partnerResponseGeneration = UUID()
        let responseGeneration = partnerResponseGeneration
        currentResponseTask?.cancel()
        let responseTaskIdentity = UUID()
        currentResponseTaskIdentity = responseTaskIdentity
        currentResponseTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                self.clearCurrentResponseTask(
                    ifMatching: responseTaskIdentity
                )
            }
            guard let controller = self.partnerModeController else { return }
            // `speakPartnerStatus` can be reached from the terminal publication
            // boundary while StealthEntryLatch.performUnlessRaised owns its
            // nonrecursive admission lock. STOP consults that same latch. Run
            // the mouth handoff in this next MainActor job, after the bounded
            // publication body has returned and released admission, so a
            // Partner response can never deadlock every visible control.
            self.noraVoice.stopPlayback()
            controller.beginSpeaking()
            self.voiceState = .responding
            self.showVisibleResponse(text)
            let completed =
                await self.noraVoice
                    .speakTextToVerifiedCompletion(text, persistence: persistence)
            guard responseGeneration
                    == self.partnerResponseGeneration,
                  self.partnerModeIsActive else {
                return
            }
            if Task.isCancelled {
                controller.speechWasInterrupted()
                self.voiceState =
                    self.buddyDictationManager
                        .isActivelyRecordingAudio
                        ? .listening
                        : .idle
                self.appendRouteReceipt(
                    "PARTNER speech interrupted; session recovered"
                )
                if !self.buddyDictationManager
                    .isDictationInProgress {
                    self.beginAutomaticPartnerListeningIfAllowed()
                }
                return
            }
            if completed {
                controller.finishVerifiedSpeech()
                self.voiceState = .idle
                self.beginAutomaticPartnerListeningIfAllowed()
            } else {
                controller.speechWasInterrupted()
                self.voiceState = .idle
                self.appendRouteReceipt(
                    "PARTNER speech unavailable; opening listening"
                )
                self.beginAutomaticPartnerListeningIfAllowed()
            }
        }
    }

    private func sendPartnerTurn(
        transcript: String,
        includesExplicitScreenContext: Bool
    ) {
        guard let partnerModeController,
              partnerModeController.userActivatedSession,
              let admittedTurnIdentifier = activeRoutingTurnID,
              let admittedSessionIdentifier = activeRoutingSessionID,
              let admittedCorrelationIdentifier =
                activeRoutingCorrelationID,
              let admittedEnvelope =
                ownerTurnLifecycle.activeBinding?.envelope,
              admittedEnvelope.sessionID == admittedSessionIdentifier,
              admittedEnvelope.turnID == admittedTurnIdentifier,
              admittedEnvelope.correlationID
                == admittedCorrelationIdentifier else {
            return
        }
        let admittedProviderTurn = AceProviderTurn.capture()
        // Bind the execution boundary to the lane state of this admitted owner
        // turn. A later panel toggle cannot retroactively grant a model-authored
        // Partner execute decision Red authority.
        let tradingModeWasActive = tradingLane.isActive
        let admittedContextualOwnerRequest =
            activeContextualOwnerRequest
        let admittedWorkCorrelationIdentifier =
            admittedContextualOwnerRequest?
                .childWorkCorrelationIdentifier
        let appOriginalOwnerTranscript =
            admittedContextualOwnerRequest?
                .originalOwnerTranscript
                ?? admittedEnvelope.exactTranscript
        let appResolvedOwnerRequest =
            admittedContextualOwnerRequest?
                .resolvedRequest
                ?? admittedEnvelope.normalizedRequest
        let appCorrectionContext =
            admittedContextualOwnerRequest?
                .correctionContext
        let appExecutionInstruction =
            admittedContextualOwnerRequest?.executionInstruction
                ?? appResolvedOwnerRequest
        let appParentWorkCorrelationIdentifier =
            admittedContextualOwnerRequest?
                .parentWorkCorrelationIdentifier
        if let admittedWorkCorrelationIdentifier {
            var candidateBundle = goldContextBundle
            let bound = candidateBundle.transitionWork(
                workCorrelationIdentifier:
                    admittedWorkCorrelationIdentifier,
                lane: "partner",
                status: .running
            )
            let persisted = bound
                && AceConversationHistory.saveBundle(
                    candidateBundle,
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared
                            .performUnlessRaised(body)
                    }
                )
            guard persisted else {
                showVisibleResponse(
                    "Ace could not safely save this Partner turn, so the brain did not run."
                )
                return
            }
            goldContextBundle = candidateBundle
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier:
                    admittedWorkCorrelationIdentifier,
                lane: .partner,
                status: .running
            )
            upsertBuyerWorkReceipt(
                workID: admittedWorkCorrelationIdentifier,
                lane: .partner,
                phase: .processing,
                progress:
                    "Partner invoked the selected provider for this work ID."
            )
        }
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        buddyDictationManager.cancelCurrentDictation(
            preserveDraftText: false
        )
        currentResponseTask?.cancel()
        claudeAPI.cancelInFlightAnswer()
        noraVoice.stopPlayback()
        partnerResponseGeneration = UUID()
        let responseGeneration = partnerResponseGeneration
        partnerResponseDeadlineGeneration = nil
        partnerModeController.beginProcessing()
        partnerModeController.updateTemporaryCaption(appOriginalOwnerTranscript)
        voiceState = .processing

        let responseTaskIdentity = UUID()
        currentResponseTaskIdentity = responseTaskIdentity
        currentResponseTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                self.clearCurrentResponseTask(
                    ifMatching: responseTaskIdentity
                )
            }
            guard let controller = self.partnerModeController else { return }
            var turnDeadlineWatchdog: Task<Void, Never>?
            // Hoisted so the failure path can state the true number of model
            // calls instead of guessing. Zero means the turn died before the
            // provider was ever reached.
            var providerAttempts = 0
            do {
                let includeScreenContext =
                    includesExplicitScreenContext
                    || controller
                        .screenContextEnabledForSession
                let latencyProfile =
                    InteractiveProviderLatencyPolicy.profile(
                        for: .partner,
                        includesScreenContext: includeScreenContext
                    )
                let labeledImages: [(data: Data, label: String)]
                if includeScreenContext {
                    let captures =
                        try await CompanionScreenCaptureUtility
                            .captureAllScreensAsJPEG()
                    labeledImages = captures.map { capture in
                        (
                            data: capture.imageData,
                            label:
                                capture.label
                                + " (image dimensions: "
                                + "\(capture.screenshotWidthInPixels)"
                                + "x"
                                + "\(capture.screenshotHeightInPixels)"
                                + " pixels)"
                        )
                    }
                } else {
                    labeledImages = []
                }
                guard !Task.isCancelled,
                      responseGeneration
                        == self.partnerResponseGeneration else {
                    throw CancellationError()
                }

                let relevantMemory =
                    PartnerMemoryReducer.relevantContext(
                        for: transcript,
                        in: controller.profile,
                        maximumCharacters: 6_000
                    )
                let partnerInvocation =
                    PartnerPromptBuilder.providerInvocation(
                        provider: admittedProviderTurn.provider,
                        profile: controller.profile,
                        relevantMemoryContext:
                            relevantMemory,
                        agenda: controller.profile.agenda,
                        permittedCompanyContext: nil,
                        screenContextIncluded:
                            includeScreenContext,
                        activeSubject: appExecutionInstruction
                    )
                let systemPrompt = partnerInvocation.systemPrompt
                self.appendRouteReceipt(
                    "PARTNER provider="
                        + partnerInvocation.provider.rawValue
                        + " overlay=active"
                )
                // Partner owns one bounded interactive attempt: visible
                // progress at five seconds, then a real provider/task cutoff at
                // fifteen so a late result cannot execute after the timeout.
                let deadlineGeneration = responseGeneration
                turnDeadlineWatchdog = Task { @MainActor [weak self] in
                    try? await Task.sleep(
                        for: .seconds(
                            InteractiveLatencyPolicy.partnerProgressDeadline
                        )
                    )
                    guard !Task.isCancelled,
                          let self,
                          deadlineGeneration
                            == self.partnerResponseGeneration else {
                        return
                    }
                    self.appendRouteReceipt(
                        "PARTNER still-working "
                            + "deadline=\(Int(InteractiveLatencyPolicy.partnerProgressDeadline))s"
                    )
                    self.showVisibleResponse(
                        "Still working on your Partner response."
                    )
                    try? await Task.sleep(
                        for: .seconds(
                            InteractiveLatencyPolicy
                                .partnerHardFailureDeadline
                                - InteractiveLatencyPolicy
                                    .partnerProgressDeadline
                        )
                    )
                    guard !Task.isCancelled,
                          deadlineGeneration
                            == self.partnerResponseGeneration else {
                        return
                    }
                    self.showVisibleResponse(
                        "Partner reached Ace's conversational "
                            + "\(Int(InteractiveLatencyPolicy.partnerHardFailureDeadline))"
                            + "-second deadline. Saving the correlated failure receipt now."
                    )
                    self.partnerResponseDeadlineGeneration =
                        deadlineGeneration
                    self.appendRouteReceipt(
                        "PARTNER hard-deadline="
                            + "\(Int(InteractiveLatencyPolicy.partnerHardFailureDeadline))s"
                    )
                    self.claudeAPI.cancelInFlightAnswer()
                    self.currentResponseTask?.cancel()
                }
                // A provider failure is Ace's problem, not the owner's. The
                // owner already said the thing. Interactive policy gives that
                // transcript one provider attempt inside the same hard budget;
                // cancellation is never retried.
                let rawResponse: String
                var accumulatedResponse = ""
                while true {
                    providerAttempts += 1
                    do {
                        let (text, _) =
                            try await self.claudeAPI
                                .analyzeImageStreaming(
                                    images: labeledImages,
                                    systemPrompt: systemPrompt,
                                    conversationHistory:
                                        controller.conversationPromptTurns,
                                    userPrompt: appExecutionInstruction,
                                    responseFormat: .partnerJSON,
                                    providerTurn: admittedProviderTurn,
                                    interactiveLatencyProfile:
                                        latencyProfile,
                                    onTextChunk: { _ in }
                                )
                        accumulatedResponse = text
                        break
                    } catch is CancellationError {
                        throw CancellationError()
                    } catch {
                        guard !Task.isCancelled,
                              responseGeneration
                                == self.partnerResponseGeneration,
                              AceReasoningRecoveryPolicy
                                .shouldRetryProviderCall(
                                    completedAttempts: providerAttempts,
                                    isCancellation: false
                                ),
                              providerAttempts
                                < latencyProfile
                                    .maximumProviderAttempts else {
                            throw error
                        }
                        self.appendRouteReceipt(
                            "PARTNER provider retry attempt="
                                + "\(providerAttempts + 1)"
                                + " errorType="
                                + String(
                                    describing: type(of: error)
                                )
                        )
                    }
                }
                rawResponse = accumulatedResponse
                turnDeadlineWatchdog?.cancel()
                guard !Task.isCancelled,
                      responseGeneration
                        == self.partnerResponseGeneration else {
                    throw CancellationError()
                }
                let response: PartnerTurnResponse
                do {
                    response = try PartnerResponseEnvelope.decode(
                        Data(rawResponse.utf8)
                    )
                } catch PartnerResponseEnvelopeError.nonterminalPromise {
                    // The provider already received one actionable, correlated
                    // owner turn. A future promise or redundant Red question
                    // is a routing decision, not a buyer-visible result.
                    response = PartnerTurnResponse(
                        kind: .execute,
                        spokenResponse: "",
                        objective: "execute the admitted owner request",
                        memoryMutations: [],
                        screenContextNeeded: false,
                        sessionSummaryDelta: ""
                    )
                    self.appendRouteReceipt(
                        "PARTNER promise normalized executor=red work="
                            + (admittedWorkCorrelationIdentifier?
                                .uuidString.lowercased() ?? "missing")
                    )
                }
                if response.kind == .reply,
                   OwnerTurnCoordinator.requiresOpenAndTypeExecution(
                       for: appResolvedOwnerRequest
                   ) {
                    let recovery =
                        "Ace returned a conversational reply without running your typing task. Nothing was typed or submitted by this attempt. Use Retry on this work receipt to run the same request."
                    _ = self.finishPartnerTurnTerminal(
                        workCorrelationIdentifier: admittedWorkCorrelationIdentifier,
                        status: .failed,
                        outcome: "failed.execution-not-dispatched",
                        verification: "none",
                        reason: recovery,
                        publication: .failed(text: recovery)
                    )
                    return
                }
                let spokenText = response.spokenResponse
                let prepared = try controller
                    .prepareTurnCompletion(
                    response: response,
                    sourceTurnIdentifier: admittedTurnIdentifier,
                    sourceSessionIdentifier:
                        admittedSessionIdentifier,
                    sourceCorrelationIdentifier:
                        admittedCorrelationIdentifier,
                    userTranscript: appOriginalOwnerTranscript,
                    assistantResponse: spokenText
                )
                if response.kind == .clarify {
                    guard let admittedWorkCorrelationIdentifier,
                          let continuation =
                            GoldClarificationContinuation(
                                sourceSessionIdentifier:
                                    admittedSessionIdentifier,
                                parentWorkCorrelationIdentifier:
                                    admittedWorkCorrelationIdentifier,
                                originalOwnerTranscript:
                                    appOriginalOwnerTranscript,
                                originalResolvedRequest:
                                    appResolvedOwnerRequest,
                                question: spokenText
                            ) else {
                        throw PartnerResponseEnvelopeError.invalidValue
                    }
                    try controller.persistPreparedTurnCompletion(prepared)
                    guard self.performTerminalPublicationUnlessStealth({
                        controller.publishPreparedTurnCompletion(prepared)
                    }) else {
                        throw CancellationError()
                    }
                    self.pendingGoldClarification = nil
                    self.pendingPartnerClarification = continuation
                    _ = self.recentOwnerWorkStore.transition(
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        lane: .partner,
                        status: .running
                    )
                    self.upsertBuyerWorkReceipt(
                        workID: admittedWorkCorrelationIdentifier,
                        lane: .partner,
                        phase: .clarifying,
                        progress:
                            "Waiting for one required owner value: "
                                + spokenText
                    )
                    self.appendRouteReceipt(
                        "PARTNER clarification retained parent="
                            + admittedWorkCorrelationIdentifier
                                .uuidString.lowercased()
                    )
                    self.speakPartnerStatus(spokenText)
                    return
                }
                if response.kind == .execute {
                    if TradingModeExecutionPolicy.decision(
                        isTradingModeActive: tradingModeWasActive,
                        responseRequestsExecution: true
                    ) == .refuseAnalysisOnly {
                        let refusal =
                            "Trading Mode is analysis-only. Partner did not "
                            + "send this request to Red, place a trade, or "
                            + "cause an external action."
                        turnDeadlineWatchdog?.cancel()
                        self.appendRouteReceipt(
                            "TRADING partner execution refused executor=none reason=analysis-only"
                        )
                        _ = self.finishPartnerTurnTerminal(
                            workCorrelationIdentifier:
                                admittedWorkCorrelationIdentifier,
                            status: .blocked,
                            outcome: "blocked.trading-analysis-only",
                            verification:
                                "app-owned-analysis-only-policy",
                            reason: refusal,
                            publication: .failed(text: refusal)
                        )
                        return
                    }
                    guard let modelObjective = response.objective,
                          let admittedWorkCorrelationIdentifier else {
                        throw PartnerResponseEnvelopeError.invalidValue
                    }
                    let validation =
                        GoldDelegationPolicy.validateExecution(
                            response: GoldTurnResponse(
                                kind: .execute,
                                spokenResponse: "",
                                objective: modelObjective
                            ),
                            sourceSessionIdentifier:
                                admittedSessionIdentifier,
                            sourceTurnIdentifier:
                                admittedTurnIdentifier,
                            sourceCorrelationIdentifier:
                                admittedCorrelationIdentifier,
                            originalOwnerTranscript:
                                appOriginalOwnerTranscript,
                            resolvedRequest:
                                appResolvedOwnerRequest,
                            correctionContext:
                                appCorrectionContext,
                            parentWorkCorrelationIdentifier:
                                appParentWorkCorrelationIdentifier,
                            workCorrelationIdentifier:
                                admittedWorkCorrelationIdentifier,
                            workSourceTurnIdentifier:
                                admittedContextualOwnerRequest?
                                    .sourceTurnIdentifier,
                            workSourceCorrelationIdentifier:
                                admittedContextualOwnerRequest?
                                    .sourceCorrelationIdentifier
                        )
                    let request: GoldExecutionRequest
                    switch validation {
                    case .accepted(let acceptedRequest):
                        request = acceptedRequest
                    case .formatFailure:
                        throw PartnerResponseEnvelopeError.invalidValue
                    }
                    guard let executionClaim = try
                            self.redExecutionService.claim(
                                envelope: admittedEnvelope,
                                objective: request.objective,
                                provider: admittedProviderTurn.provider,
                                targetBinding: .none,
                                workID:
                                    request.workCorrelationIdentifier
                            ),
                          executionClaim.workID
                            == request.workCorrelationIdentifier else {
                        throw PartnerResponseEnvelopeError.invalidValue
                    }
                    try controller.persistPreparedTurnCompletion(prepared)
                    guard self.performTerminalPublicationUnlessStealth({
                        controller.publishPreparedTurnCompletion(prepared)
                    }) else {
                        _ = self.redExecutionService.cancelBeforeCommit(
                            turnID: admittedTurnIdentifier
                        )
                        throw CancellationError()
                    }
                    guard controller.recordExecutionAssignment(
                        userTranscript: appOriginalOwnerTranscript,
                        objective: request.objective,
                        workerName: "Red",
                        workCorrelationIdentifier:
                            request.workCorrelationIdentifier
                    ) else {
                        _ = self.redExecutionService.cancelBeforeCommit(
                            turnID: admittedTurnIdentifier
                        )
                        throw PartnerModeControllerError.inactiveSession
                    }
                    self.partnerDelegatedWorkIdentifiers.insert(
                        request.workCorrelationIdentifier
                    )
                    _ = self.redExecutionService.markExecuting(
                        turnID: admittedTurnIdentifier
                    )
                    self.appendRouteReceipt(
                        "PARTNER objective provider="
                            + admittedProviderTurn.provider.rawValue
                            + " executor=red"
                    )
                    await self.dispatchGoldDelegation(
                        request,
                        providerTurn: admittedProviderTurn
                    )
                    // Red now owns the durable work ID. Partner immediately
                    // returns to listening while the same receipt stays live.
                    self.beginAutomaticPartnerListeningIfAllowed()
                    return
                }
                guard self.finishPartnerTurnTerminal(
                    workCorrelationIdentifier:
                        admittedWorkCorrelationIdentifier,
                    status: .completed,
                    outcome: "completed.response-produced",
                    verification: "reported",
                    reason: spokenText,
                    publication: .completed(
                        prepared: prepared,
                        spokenText: spokenText,
                        responseGeneration: responseGeneration
                    )
                ) else { return }
                return
            } catch is CancellationError {
                turnDeadlineWatchdog?.cancel()
                if self.partnerResponseDeadlineGeneration
                        == responseGeneration,
                   let admittedWorkCorrelationIdentifier {
                    self.partnerResponseDeadlineGeneration = nil
                    let recovery =
                        "Partner did not produce an actionable response within \(Int(InteractiveLatencyPolicy.partnerHardFailureDeadline)) seconds. Red never accepted execution. Use Retry on work \(admittedWorkCorrelationIdentifier.uuidString.lowercased()) to submit the same bounded request as a new correlated attempt."
                    _ = self.finishPartnerTurnTerminal(
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        status: .failed,
                        outcome: "failed.conversation-deadline",
                        verification: "none",
                        reason: recovery,
                        publication: .failed(text: recovery)
                    )
                    return
                }
                if let admittedWorkCorrelationIdentifier,
                   self.recentOwnerWorkStore.entry(
                       workCorrelationIdentifier:
                           admittedWorkCorrelationIdentifier
                   )?.status == .running {
                    _ = self.finishDirectWorkTerminal(
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        lane: .partner,
                        durableLane: "partner",
                        status: .cancelled,
                        outcome: "cancelled",
                        verification: "none",
                        reason:
                            "The Partner turn was cancelled before a terminal response was delivered.",
                        slot: .none
                    )
                }
                return
            } catch {
                turnDeadlineWatchdog?.cancel()
                let underlyingTypeName = String(
                    describing: type(of: error)
                )
                // Honest, cause-named, and it never hands the turn back: the
                // session stays live and the microphone reopens behind this
                // line, so the owner keeps talking instead of repeating.
                let recoveryText =
                    (error is PartnerSecureStoreError || error is PromptFreeCredentialStoreError)
                    ? PartnerSecureStore.ownerFacingFailure(error)
                    : AceReasoningRecoveryPolicy
                        .partnerFailureSpokenText(
                            errorTypeName: underlyingTypeName,
                            errorDescription:
                                error.localizedDescription,
                            completedAttempts: providerAttempts
                        )
                let persisted = self.finishPartnerTurnTerminal(
                    workCorrelationIdentifier:
                        admittedWorkCorrelationIdentifier,
                    status: .failed,
                    outcome: "failed." + underlyingTypeName,
                    verification: "none",
                    reason: recoveryText,
                    publication: .failed(text: recoveryText)
                )
                guard persisted else { return }
                self.appendRouteReceipt(
                    "PARTNER turn failed errorType="
                        + underlyingTypeName
                        + " providerAttempts=\(providerAttempts)"
                        + " detail="
                        + error.localizedDescription
                )
            }
        }
    }

    /// Entry point for every spoken utterance. Decides whether the gold overhead
    /// answers, or the red background worker performs a task.
    /// Where an inbound utterance came from.
    ///
    /// READ THE CASES: there is no case for Ace's own output, no case for a
    /// lane, and no case for model-authored text. That absence is the fix. The
    /// old `handleUtterance(_ transcript: String)` was `internal` and took a
    /// bare String, so every caller — including anything that could echo Ace's
    /// words back — carried owner authority by default. Owner authority is now
    /// something a call site must NAME, and the only names available are things
    /// a human physically did.
    enum AceUtteranceOrigin {
        /// The owner held the global push-to-talk chord. Hardware-attested.
        case microphonePushToTalk
        /// Partner's automatic open-microphone turn.
        case microphonePartnerTurn
        /// The owner clicked a live-test button in Ace's own setup window.
        /// Attested by the click, not by speech — labeled distinctly so a
        /// receipt can never present a button press as an utterance.
        case directHumanUIAction
        /// The `RUN_SAY` observability flag. Already `#if DEBUG` at its call
        /// site; `AceInboundAdmission` refuses it in Release as well, so a
        /// shipped build has no synthetic command channel at all.
        case developerInjection

        var payloadType: AceEventPayloadType {
            switch self {
            case .microphonePushToTalk, .microphonePartnerTurn:
                return .microphoneFinalTranscript
            case .directHumanUIAction:
                return .directHumanUIAction
            case .developerInjection:
                return .developerInjection
            }
        }
    }

    /// THE ADMISSION BOUNDARY. Every owner command enters here or does not
    /// happen. Nothing else in the app may reach `handleUtterance`, which is
    /// `private` for exactly that reason.
    ///
    /// What this buys, concretely:
    ///   • Ace's own speech has no origin that reaches this method, and no
    ///     payload type that `AceInboundAdmission` will admit.
    ///   • A duplicate or delayed finalization lands on a turn that is already
    ///     sealed and is refused, so one utterance cannot become two actions.
    ///   • A final that arrives after barge-in belongs to a cancelled turn and
    ///     is refused — while the turn the owner just opened proceeds normally.
    @discardableResult
    func ingestOwnerUtterance(
        _ transcript: String,
        origin: AceUtteranceOrigin,
        capturedOwnerTurnID: UUID? = nil,
        bypassStealthVoiceFragmentAssembly: Bool = false,
        selectedReceiptRetryWorkID: UUID? = nil
    ) -> Bool {
        if case .microphonePartnerTurn = origin,
           partnerModeController?.isMicrophoneMuted == true {
            appendRouteReceipt(
                "INGRESS refused origin=\(origin) reason=partner-muted"
            )
            return false
        }
        let bus = AceEventBus.shared
        let isMicrophoneOrigin: Bool
        switch origin {
        case .microphonePushToTalk, .microphonePartnerTurn:
            isMicrophoneOrigin = true
        case .directHumanUIAction, .developerInjection:
            isMicrophoneOrigin = false
        }
        let admissionTranscript = isMicrophoneOrigin
            ? CrossAppActionPolicy.canonicalizedMicrophonePointRequest(
                StealthMicrophoneTranscriptRepair.canonicalized(transcript)
            )
            : transcript
        if isMicrophoneOrigin {
            guard let capturedOwnerTurnID,
                  bus.currentTurnID == capturedOwnerTurnID,
                  !bus.isTurnCancelled(capturedOwnerTurnID) else {
                appendRouteReceipt(
                    "INGRESS refused origin=\(origin) reason=stale-capture-turn"
                )
                return false
            }
        }
        guard AceLicense.shared.admits(.normalVoice) else {
            let routedRecovery = routeUnlicensedRecoveryUtterance(
                admissionTranscript,
                origin: origin
            )
            appendRouteReceipt(
                "INGRESS refused origin=\(origin) reason=unlicensed"
                    + " recovery=\(routedRecovery)"
            )
            return routedRecovery
        }
        if !bypassStealthVoiceFragmentAssembly,
           routeStealthVoiceFragmentIfNeeded(
               admissionTranscript,
               origin: origin,
               capturedOwnerTurnID: capturedOwnerTurnID
           ) {
            return true
        }
        let admissionOutcome: AceEventBus.InboundOutcome
        switch origin {
        case .directHumanUIAction, .developerInjection:
            // Every explicit human action is a new turn. Reusing currentTurnID
            // here drops the second setup/reconnect click after the first turn
            // has sealed its final event.
            let isWorkStatusQuery =
                LocalIntentPolicy.classify(admissionTranscript)
                    == .workStatus
            let turnID = isWorkStatusQuery
                ? bus.beginOwnerTurn(cancellingPrevious: false)
                : bus.beginDirectHumanTurn()
            admissionOutcome = bus.admitInbound(
                bus.ownerEvent(
                    turnID: turnID,
                    state: .final,
                    payloadType: origin.payloadType,
                    payload: admissionTranscript
                )
            )
        case .microphonePushToTalk, .microphonePartnerTurn:
            // Partial/final callbacks for one capture keep the turn opened by
            // that capture boundary so the ledger can reject duplicate finals.
            guard let capturedOwnerTurnID else { return false }
            admissionOutcome = CapturedOwnerSpeechIngress(eventBus: bus)
                .admitFinal(
                    admissionTranscript,
                    ownerTurnID: capturedOwnerTurnID
                )
        }

        switch admissionOutcome {
        case let .route(admittedEvent):
            // A new admitted owner generation retires any prior transient card,
            // including a longer-lived local inbox preview, before new routing.
            clearVisibleResponse()
            let isWorkStatusQuery =
                LocalIntentPolicy.classify(admittedEvent.payload)
                    == .workStatus
            if let preservedTurnID =
                    provisionallyPreservedVoiceWorkTurnID {
                if !isWorkStatusQuery {
                    bus.cancelTurn(
                        preservedTurnID,
                        reason: "owner replacement classified"
                    )
                }
                provisionallyPreservedVoiceWorkTurnID = nil
            }
            let preservedRoutingTurnID = activeRoutingTurnID
            let preservedRoutingSessionID = activeRoutingSessionID
            let preservedRoutingCorrelationID =
                activeRoutingCorrelationID
            let preservedOwnerTurnContext = activeOwnerTurnContext
            let preservedContextualRequest =
                activeContextualOwnerRequest
            if !isWorkStatusQuery {
                nativeLocationManager?.cancel()
                nativeLocationManager = nil
            }
            activeRoutingTurnID = admittedEvent.turnID
            activeRoutingSessionID = admittedEvent.sessionID
            activeRoutingCorrelationID = admittedEvent.correlationID
            if !isWorkStatusQuery {
                activeContextualOwnerRequest = nil
            }
            let binding = resolveAdmittedOwnerTurn(
                admittedEvent, selectedReceiptRetryWorkID: selectedReceiptRetryWorkID
            )
            let context = binding.context
            activeOwnerTurnContext = context
            ownerTurnLifecycle.beginManagerDispatch(for: binding)
            handleUtterance(context)
            ownerTurnLifecycle.finishManagerDispatchIfSynchronous(
                for: binding
            )
            if isWorkStatusQuery {
                activeRoutingTurnID = preservedRoutingTurnID
                activeRoutingSessionID = preservedRoutingSessionID
                activeRoutingCorrelationID =
                    preservedRoutingCorrelationID
                activeOwnerTurnContext = preservedOwnerTurnContext
                activeContextualOwnerRequest =
                    preservedContextualRequest
            }
            return true
        case .uiOnly:
            return false
        case let .dropped(reason):
            appendRouteReceipt(
                "INGRESS refused origin=\(origin) reason="
                    + AceEventDiagnostics.sanitize(reason)
                    + " (contents deliberately not logged)"
            )
            return false
        }
    }

    /// A rapid second push-to-talk can turn “go stealth” into two final
    /// transcripts. Hold only the ambiguous lead, then recover the exact local
    /// privacy command from the next fragment. Nothing held here reaches Gold.
    private func routeStealthVoiceFragmentIfNeeded(
        _ transcript: String,
        origin: AceUtteranceOrigin,
        capturedOwnerTurnID: UUID?
    ) -> Bool {
        switch origin {
        case .microphonePushToTalk, .microphonePartnerTurn:
            break
        case .directHumanUIAction, .developerInjection:
            return false
        }

        let now = ProcessInfo.processInfo.systemUptime
        _ = stealthVoiceFragmentAssembler.takeExpired(at: now)
        switch stealthVoiceFragmentAssembler.ingest(
            transcript,
            at: now
        ) {
        case .route(let routedTranscript):
            stealthVoiceFragmentDeadlineTask?.cancel()
            stealthVoiceFragmentDeadlineTask = nil
            guard routedTranscript != transcript else { return false }
            appendRouteReceipt(
                "STEALTH voice fragments recovered route=native.stealth-enter"
            )
            ingestOwnerUtterance(
                routedTranscript,
                origin: origin,
                capturedOwnerTurnID: capturedOwnerTurnID,
                bypassStealthVoiceFragmentAssembly: true
            )
            return true

        case .hold:
            stealthVoiceFragmentDeadlineTask?.cancel()
            let heldOrigin = origin
            let heldTurnIdentifier = capturedOwnerTurnID
            stealthVoiceFragmentDeadlineTask = Task {
                try? await Task.sleep(
                    nanoseconds: UInt64(
                        (StealthVoiceFragmentAssembler
                            .maximumGapSeconds + 0.05)
                            * 1_000_000_000
                    )
                )
                guard !Task.isCancelled,
                      let expired = self
                        .stealthVoiceFragmentAssembler
                        .takeExpired(
                            at: ProcessInfo.processInfo.systemUptime
                        ) else {
                    return
                }
                self.stealthVoiceFragmentDeadlineTask = nil
                self.appendRouteReceipt(
                    "STEALTH voice fragment expired route=ordinary"
                )
                self.ingestOwnerUtterance(
                    expired,
                    origin: heldOrigin,
                    capturedOwnerTurnID: heldTurnIdentifier,
                    bypassStealthVoiceFragmentAssembly: true
                )
            }
            appendRouteReceipt(
                "STEALTH voice fragment held route=local deadline=4s"
            )
            return true
        }
    }

    /// Recovery is intentionally outside the premium event bus: an unlicensed
    /// utterance may stop work or reach Account, but is never persisted as a
    /// transcript, routed to a model, or allowed to consume an approval.
    @discardableResult
    private func routeUnlicensedRecoveryUtterance(
        _ transcript: String,
        origin: AceUtteranceOrigin
    ) -> Bool {
        guard let action =
                AceUnlicensedRecoveryVoicePolicy.action(
                    for: transcript
                ) else {
            return false
        }

        switch action {
        case .stopAll:
            quiescePremiumRuntimeForEntitlementLoss(
                forceRecoveryStop: true
            )
        case .mute:
            buddyDictationManager.cancelCurrentDictation(
                preserveDraftText: false
            )
            noraVoice.stopPlayback()
            voiceState = .idle
        case .endSession:
            endPartnerMode(reason: .userEnded)
        case .discardMeetingNotes:
            meetingNotetaker.discardPendingGeneratedNotesReview(
                reason: "owner recovery after entitlement closed"
            )
            meetingNotetaker.suspendSynchronouslyForStealth()
        case .cancelWorkflow:
            _ = workflowRuntime.abortActiveJob()
        case .privateModeExit:
            // A late ordinary microphone final must never lower Private Mode.
            // Its isolated exit-only PTT path is admitted before licensing in
            // `handleShortcutTransition`. Direct UI recovery may exit here.
            guard stealthMode.isActive else { return true }
            guard case .directHumanUIAction = origin else { return true }
            exitStealthMode()
        case .activation:
            AceLicense.shared.presentKeyEntry()
        case .account:
            _ = AceLicense.shared.openAccountPage()
        case .subscriptionCancellation:
            _ = AceLicense.shared.openSubscriptionCancellation()
        case .support:
            _ = AceLicense.shared.contactSupport()
        case .quit:
            NSApp.terminate(nil)
        }
        return true
    }

    /// A live, still-changing transcript. It may light the waveform and the
    /// caption. It may not route, invoke a tool, or reach Gold — enforced by
    /// `AceInboundAdmission`, not by the caller remembering.
    func ingestOwnerPartialTranscript(
        _ transcript: String,
        capturedOwnerTurnID: UUID
    ) {
        let bus = AceEventBus.shared
        _ = CapturedOwnerSpeechIngress(eventBus: bus).admitPartial(
            transcript,
            ownerTurnID: capturedOwnerTurnID
        )
    }

    /// The turn currently being routed. Set once by the admission boundary and
    /// read by every receipt and every re-route below, so a replacement
    /// utterance stays inside the SAME owner turn instead of minting a new one
    /// and quietly defeating the one-final-per-turn seal.
    private var activeRoutingTurnID: UUID?
    private var activeRoutingSessionID: UUID?
    private var activeRoutingCorrelationID: UUID?
    private var provisionallyPreservedVoiceWorkTurnID: UUID?
    private var activeOwnerTurnContext: OwnerTurnContext?
    private var activeContextualOwnerRequest: ContextualOwnerRequest?
    private var currentRouteOwnsContextualWork = false
    private var recentOwnerWorkStore = RecentOwnerWorkStore()
    private var foregroundNavigationContext = GoldForegroundContext()
    private var nativeConversationContext = NativeConversationContext()
    /// Product-owned inquiries are durable buyer receipts without becoming
    /// continuation candidates. The source correlation remains the lifecycle
    /// identity; this map binds it to the separately persisted work identity.
    private var receiptOnlyWorkIDBySourceCorrelationID: [UUID: UUID] = [:]
    private let ownerTurnLifecycle = OwnerTurnLifecycleCoordinator()
    private let redExecutionService = RedExecutionService()

    /// Expiry removes execution authority and closes the original receipt.
    /// Use the existing deferred save boundary without publishing new speech
    /// or replacing the incoming command's visible result.
    private func clarificationRemainsCurrent(
        _ pending: GoldClarificationContinuation?,
        sessionIdentifier: UUID,
        lane: RecentOwnerWorkLane,
        durableLane: String
    ) -> Bool {
        guard let pending else { return false }
        guard pending.isCurrent(sessionIdentifier: sessionIdentifier) else {
            _ = finishDirectWorkTerminal(
                workCorrelationIdentifier:
                    pending.parentWorkCorrelationIdentifier,
                lane: lane,
                durableLane: durableLane,
                status: .failed,
                outcome: "\(durableLane)-clarification-expired",
                verification: "none",
                reason: "This clarification expired before a new answer was accepted. Use Retry on this work receipt to reopen the original request.",
                slot: .none
            )
            appendRouteReceipt(
                "CLARIFICATION retired expired lane=\(durableLane) work="
                    + pending.parentWorkCorrelationIdentifier.uuidString.lowercased()
            )
            return false
        }
        return true
    }

    /// Snapshots every candidate and typed pending slot at the admission wall.
    /// No later parser may change this turn's scope, slot, or route.
    private func resolveAdmittedOwnerTurn(
        _ admittedEvent: AceEvent,
        selectedReceiptRetryWorkID: UUID? = nil
    ) -> OwnerTurnBinding {
        let goldClarificationIsPending: Bool
        if clarificationRemainsCurrent(
            pendingGoldClarification,
            sessionIdentifier: admittedEvent.sessionID,
            lane: .gold,
            durableLane: "gold"
        ) {
            goldClarificationIsPending = true
        } else {
            pendingGoldClarification = nil
            goldClarificationIsPending = false
        }
        let partnerClarificationIsPending: Bool
        if clarificationRemainsCurrent(
            pendingPartnerClarification,
            sessionIdentifier: admittedEvent.sessionID,
            lane: .partner,
            durableLane: "partner"
        ) {
            partnerClarificationIsPending = true
        } else {
            pendingPartnerClarification = nil
            partnerClarificationIsPending = false
        }
        var candidates = goldContextBundle.nonauthoritativeCandidates(
            sourceSessionIdentifier: admittedEvent.sessionID
        )
        var candidateIDs = Set(candidates.map(\.workCorrelationID))
        for candidate in recentOwnerWorkStore.nonauthoritativeCandidates(
            sourceSessionIdentifier: admittedEvent.sessionID
        ) where candidateIDs.insert(candidate.workCorrelationID).inserted {
            candidates.append(candidate)
        }
        let selectedReceiptRetry = selectedReceiptRetryWorkID.flatMap { identifier in
            goldContextBundle.workRecords.first {
                $0.workCorrelationIdentifier == identifier
            }?.continuationCandidate
        }

        let pending: OwnerPendingSlotState?
        if let selection = appleMailSenderSelection {
            pending = OwnerPendingSlotState(
                slot: .mailSender,
                allowedValues: selection.senderAddresses
            )
        } else if let selection = appleMessagesRecipientSelection {
            pending = OwnerPendingSlotState(
                slot: .messageRecipient,
                allowedValues: selection.recipientHandles
            )
        } else {
            pending = nil
        }
        let actionTargets = lastLocatedTargetName.map { [$0] } ?? []
        let requiredCandidateWorkID: UUID? = retryableAceHQDispatch.flatMap {
            retryable in
            UUID(
                uuidString: retryable.reconciliationAttempt?.work
                    .correlationID ?? retryable.intent.work.correlationID
            )
        }
        let privateMailReply = CrossAppActionPolicy.isExplicitCancellation(
            admittedEvent.payload
        ) ? nil : privateMailClarification?.resuming(
            answer: admittedEvent.payload,
            sessionID: admittedEvent.sessionID,
            currentSender: GmailAccountStore().storedAddress()
        )
        let binding = ownerTurnLifecycle.admit(
            admittedEvent,
            pending: pending,
            goldClarificationIsPending:
                goldClarificationIsPending
                    || partnerClarificationIsPending,
            privateMailClarificationRequest: privateMailReply,
            candidates: candidates,
            actionTargets: actionTargets,
            requiredCandidateWorkID: requiredCandidateWorkID,
            selectedReceiptRetry: selectedReceiptRetry,
            allowsImplicitLocateFollowUp: lastRouteWasLocate,
            partnerModeIsActive: partnerModeIsActive,
            stealthIsActive: stealthMode.isActive,
            stealthEnterMatched:
                stealthMode.isEnterTrigger(admittedEvent.payload),
            stealthExitMatched:
                stealthMode.isExitTrigger(admittedEvent.payload),
            notesCaptureIsActive:
                meetingNotetaker.isTakingNotes
                    || meetingNotetaker.isStartingUp,
            hasRecentEmailRead: recentEmailRead?.isUsable(sourceIdentity: emailReadSourceIdentity) == true
        )
        let context = binding.context
        if !context.isNonDestructiveInquiry {
            privateMailClarification = nil
        }
        if context.selectedRoute != "native.mail.read" && context.selectedRoute != "native.response-repeat" {
            recentEmailRead = nil
        }
        let scopeLabel: String
        switch context.scope {
        case .ownerPersonal: scopeLabel = "owner-personal"
        case .client: scopeLabel = "client"
        case .deviceCurrent: scopeLabel = "device-current"
        case .unspecified: scopeLabel = "unspecified"
        }
        appendRouteReceipt(
            "TURN-CONTEXT route=" + context.selectedRoute
                + " scope=" + scopeLabel
                + " slot="
                + (context.pendingSlot?.rawValue ?? "none")
        )
        return binding
    }

    /// Creates durable work lineage from the already-resolved immutable
    /// context. Gold and recent work are reloaded/recorded here, but they are
    /// no longer called as parsers and cannot change this turn's decision.
    private func bindReceiptOnlyOwnerTurn(
        _ context: OwnerTurnContext,
        sourceCorrelationIdentifier: UUID
    ) -> Bool {
        if let existing = receiptOnlyWorkIDBySourceCorrelationID[
            sourceCorrelationIdentifier
        ] {
            return goldContextBundle.workRecords.contains {
                $0.workCorrelationIdentifier == existing
            }
        }
        goldContextBundle = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        let request = ContextualOwnerRequest(
            originalOwnerTranscript: String(
                context.exactInput.prefix(8_000)
            ),
            resolvedRequest: String(
                context.routingInput.prefix(1_200)
            ),
            correctionContext: nil,
            sourceSessionIdentifier: context.sessionID,
            sourceTurnIdentifier: context.turnID,
            sourceCorrelationIdentifier: sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier: nil,
            childWorkCorrelationIdentifier: UUID(),
            referenceKind: .none,
            resolutionStatus: .direct
        )
        var candidateBundle = goldContextBundle
        let recorded = candidateBundle.recordWork(
            request: request,
            lane: AceGoldContextBundle.receiptOnlyLane,
            status: .running
        )
        let persisted = recorded && AceConversationHistory.saveBundle(
            candidateBundle,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        guard persisted else {
            appendRouteReceipt(
                "INQUIRY receipt bind refused correlation="
                    + sourceCorrelationIdentifier.uuidString.lowercased()
            )
            showVisibleResponse(
                "Ace could not save this request's work receipt, so the request was not accepted. Retry after checking Ace's private support directory."
            )
            return false
        }
        goldContextBundle = candidateBundle
        receiptOnlyWorkIDBySourceCorrelationID[
            sourceCorrelationIdentifier
        ] = request.childWorkCorrelationIdentifier
        publishBuyerWorkAcceptance(request, speak: false)
        appendRouteReceipt(
            "INQUIRY receipt persisted work="
                + request.childWorkCorrelationIdentifier
                    .uuidString.lowercased()
        )
        return true
    }

    private func bindOwnerTurnContext(
        _ context: OwnerTurnContext
    ) -> String? {
        if let correlationID = activeRoutingCorrelationID {
            nativeConversationContext.admit(
                sessionID: context.sessionID,
                partnerSessionID: partnerModeController?.activeSessionID,
                turnID: context.turnID, correlationID: correlationID,
                route: context.selectedRoute, userTranscript: context.exactInput
            )
        }
        guard let sourceCorrelationIdentifier =
                activeRoutingCorrelationID else {
            return context.routingInput
        }
        if let activeContextualOwnerRequest,
           activeContextualOwnerRequest.sourceSessionIdentifier
                == context.sessionID,
           activeContextualOwnerRequest.sourceTurnIdentifier
                == context.turnID,
           activeContextualOwnerRequest.sourceCorrelationIdentifier
                == sourceCorrelationIdentifier {
            return activeContextualOwnerRequest.resolvedRequest
        }

        if context.selectedRoute.hasSuffix("clarification") {
            let question: String
            switch context.pendingSlot {
            case .locality:
                question = "Which city and state should I use for this weather request?"
            case .mailSender:
                question = "Choose one of the exact Apple Mail senders shown in the Ace panel."
            case .messageRecipient:
                question = "Choose one of the exact Messages recipients shown in the Ace panel."
            case .actionTarget, .goldClarification, .none:
                question = context.resolvedSlots["clarificationQuestion"]
                    ?? "Which recent request or target do you mean?"
            }
            appendRouteReceipt(
                "CONTEXT ambiguous turn="
                    + context.turnID.uuidString.lowercased()
                    + " execution=none"
            )
            showVisibleResponse(question)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(question)
            }
            return nil
        }

        if context.requiresDurableReceiptWithoutContinuation {
            guard bindReceiptOnlyOwnerTurn(
                context,
                sourceCorrelationIdentifier:
                    sourceCorrelationIdentifier
            ) else {
                return nil
            }
            return context.routingInput
        }

        // Mail, Messages, location, weather, provider account controls, and
        // Stop retain only live turn state. Their exact content must never
        // enter recent work or the durable Gold bundle.
        guard context.permitsDurableContext else {
            if !context.isNonDestructiveInquiry {
                activeContextualOwnerRequest = nil
            }
            return context.routingInput
        }

        goldContextBundle = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        let parentWorkCorrelationIdentifier = context.resolvedSlots[
            "parentWorkCorrelationIdentifier"
        ].flatMap(UUID.init(uuidString:))
        let referenceKind: OwnerWorkReferenceKind
        switch context.resolvedSlots["referenceKind"] {
        case "lastThing": referenceKind = .lastThing
        case "pronoun": referenceKind = .pronoun
        default: referenceKind = .none
        }
        let correctionContext: OwnerCorrectionContext?
        if let rawKind = context.resolvedSlots["correctionKind"],
           let kind = OwnerCorrectionKind(rawValue: rawKind) {
            correctionContext = OwnerCorrectionContext(
                kind: kind,
                ownerCorrection: context.exactInput,
                priorTerminalOutcome:
                    context.resolvedSlots["priorTerminalOutcome"],
                priorTerminalVerification:
                    context.resolvedSlots["priorTerminalVerification"],
                priorTerminalReason:
                    context.resolvedSlots["priorTerminalReason"]
            )
        } else {
            correctionContext = nil
        }
        guard correctionContext?.isValid ?? true else {
            showVisibleResponse("This correction is too long. Keep it within 8,000 characters; nothing was submitted.")
            return nil
        }
        if correctionContext?.kind == .retry {
            guard let parentID = parentWorkCorrelationIdentifier,
                  let parent = goldContextBundle.workRecords.first(where: {
                      $0.workCorrelationIdentifier == parentID
                  }), parent.exactExecutionRequest == context.routingInput else {
                showVisibleResponse("The exact original instructions are unavailable. Enter the full remaining request; nothing was retried.")
                return nil
            }
            if let reason = goldContextBundle.retryRefusalReason(for: parentID) {
                showVisibleResponse(reason)
                return nil
            }
        }
        let contextualRequest = ContextualOwnerRequest(
            // Execution retains the exact request. The history stores apply
            // their own display/retrieval bounds after this live binding.
            originalOwnerTranscript: context.exactInput,
            resolvedRequest: context.routingInput,
            correctionContext: correctionContext,
            sourceSessionIdentifier: context.sessionID,
            sourceTurnIdentifier: context.turnID,
            sourceCorrelationIdentifier:
                sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier:
                parentWorkCorrelationIdentifier,
            childWorkCorrelationIdentifier: UUID(),
            referenceKind: referenceKind,
            resolutionStatus:
                referenceKind == .none ? .direct : .resolved
        )
        var candidateRecentOwnerWorkStore = recentOwnerWorkStore
        let recentRecorded = candidateRecentOwnerWorkStore.recordExecution(
            originalOwnerTranscript:
                contextualRequest.originalOwnerTranscript,
            resolvedRequest: contextualRequest.resolvedRequest,
            sourceSessionIdentifier:
                contextualRequest.sourceSessionIdentifier,
            sourceTurnIdentifier:
                contextualRequest.sourceTurnIdentifier,
            sourceCorrelationIdentifier:
                contextualRequest.sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier:
                contextualRequest.parentWorkCorrelationIdentifier,
            workCorrelationIdentifier:
                contextualRequest.childWorkCorrelationIdentifier,
            lane: .direct,
            status: .running
        )
        var candidateBundle = goldContextBundle
        let retryClaimed: Bool
        if correctionContext?.kind == .retry,
           let parentID = parentWorkCorrelationIdentifier {
            retryClaimed = candidateBundle.claimRetry(
                parentID: parentID, childID: contextualRequest.childWorkCorrelationIdentifier
            )
        } else {
            retryClaimed = true
        }
        let durableRecorded = retryClaimed && candidateBundle.recordWork(
            request: contextualRequest,
            lane: "direct",
            status: .running
        )
        let persisted = recentRecorded && durableRecorded
            && AceConversationHistory.saveBundle(
                candidateBundle,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        appendRouteReceipt(
            "CONTEXT route kind="
                + contextualRequest.referenceKind.rawValue
                + " status="
                + contextualRequest.resolutionStatus.rawValue
                + " child="
                + contextualRequest.childWorkCorrelationIdentifier
                    .uuidString.lowercased()
        )
        appendRouteReceipt(
            "GOLD-CONTEXT work persisted="
                + (persisted ? "true" : "false")
                + " child="
                + contextualRequest.childWorkCorrelationIdentifier
                    .uuidString.lowercased()
        )
        guard persisted else {
            activeContextualOwnerRequest = nil
            appendRouteReceipt(
                "CONTEXT refused durable-bind-save turn="
                    + context.turnID.uuidString.lowercased()
            )
            showVisibleResponse(
                "Ace could not save this request's work context, so nothing ran. "
                    + "That write is refused while Stealth is raised or Ace's private "
                    + "support directory is unwritable."
            )
            return nil
        }
        goldContextBundle = candidateBundle
        recentOwnerWorkStore = candidateRecentOwnerWorkStore
        activeContextualOwnerRequest = contextualRequest
        publishBuyerWorkAcceptance(contextualRequest)
        return contextualRequest.resolvedRequest
    }

    /// THE ROUTING CORE. Private on purpose — see `ingestOwnerUtterance`.
    ///
    /// Reached only from that boundary and from this file's own replacement
    /// re-routes, which re-run an utterance that was ALREADY admitted and
    /// therefore must not be re-sealed.
    private func handleUtterance(_ context: OwnerTurnContext) {
        let transcript = context.exactInput
        let isTopLevelRoute = !currentRouteOwnsContextualWork
        if isTopLevelRoute {
            currentRouteOwnsContextualWork = true
        }
        defer {
            if isTopLevelRoute {
                terminalizeUnclaimedContextualWorkIfNeeded()
                currentRouteOwnsContextualWork = false
            }
        }
        let trimmed = transcript.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }

        // Stealth is the first wall, before history, licence, setup, routing, or
        // any transformation that could persist the words. Even an
        // already-finalizing transcript is discarded: only the isolated local
        // exit recognizer may lower the wall.
        if stealthMode.isActive {
            appendRouteReceipt(
                "STEALTH dropped an utterance (contents deliberately not logged)"
            )
            return
        }

        // The Private Mode entry chord raises this latch synchronously on the event-tap
        // thread, before its main-queue toggle can run. A final transcript already
        // queued on main must not resolve a confirmation or prepare a new effect
        // after the owner has requested Private Mode.
        guard Self.directEffectsAreAllowed(
            privateModeEntryIsRequested:
                globalPushToTalkShortcutMonitor
                    .privateModeEntryIsRequested,
            stealthIsActive: stealthMode.isActive,
            visibilityGateIsActive:
                StealthVisibilityGate.shared.isActive
        ) else {
            appendRouteReceipt(
                "PRIVATE-MODE entry pending — utterance dropped before routing "
                    + "(contents deliberately not logged)")
            return
        }
        guard AceLicense.shared.admits(.normalVoice) else {
            appendRouteReceipt(
                "ROUTE refused — entitlement closed during admitted turn"
            )
            return
        }
        if context.selectedRoute == "owner.stop" {
            silenceEverything(spokenTrigger: context.exactInput)
            return
        }
        // Privacy entry is a control, like Stop. Registering it as ordinary
        // work makes its own teardown recover it as an interrupted task and
        // lets an unrelated pending receipt delay the privacy wall.
        if context.selectedRoute == "native.stealth-enter" {
            enterStealthMode()
            return
        }
        if context.selectedRoute == "native.partner-command",
           let command = PartnerModePolicy.routableCommand(
               for: OwnerRequestNormalizer.makeEnvelope(
                   sessionID: context.sessionID, turnID: context.turnID,
                   correlationID: activeRoutingCorrelationID ?? context.turnID,
                   origin: .microphone, exactTranscript: context.exactInput,
                   admittedAt: Date(), recentExactTarget: nil
               ).normalizedRequest,
               sessionIsActive: partnerModeIsActive
           ), [.end, .mute, .wait].contains(command) {
            if context.permitsDurableContext { AceTranscript.record(role: .you, text: trimmed) }
            _ = routePartnerModeCommand(command, transcript: trimmed, context: context)
            return
        }
        let dispatchDestination = OwnerTurnDispatchPolicy.destination(
            for: context
        )
        if dispatchDestination == .refused {
            appendRouteReceipt(
                "CONTEXT refused route/scope mismatch route="
                    + context.selectedRoute
            )
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .failed,
                outcome: "route-scope-refused",
                reason:
                    "Ace refused that route because its frozen scope does not authorize the requested effect."
            )
            return
        }
        guard retryDeferredDurableTerminalsIfSafe() else {
            appendRouteReceipt(
                "ROUTE deferred terminal must persist before a new owner turn"
            )
            showVisibleResponse(
                "Ace is safely finishing the last work receipt. Ask again after it saves."
            )
            return
        }
        guard commitPendingRelaunchRecoveryIfNeeded() else {
            showVisibleResponse(
                "Ace is finishing interrupted-work recovery. Ask again after it saves."
            )
            return
        }

        // Every utterance the owner actually gets to make lands here, past both
        // Stealth walls above — including the ones that never reach the model
        // ("open safari", "what do you remember", "what can you do"). Recorded
        // BEFORE the name strip, because the transcript is what the owner said,
        // not what routing needed.
        if context.permitsDurableContext {
            AceTranscript.record(role: .you, text: trimmed)
        }

        if resolveExplicitMemoryClear(context: context) { return }

        // A pending Partner or Gold clarification owns the next admitted
        // value before ordinary hail stripping. A required value can itself
        // be "Ace", so treating that exact answer as a name-only greeting
        // would detach it from the original work ID and leave the receipt
        // stuck in Clarifying. Native Stop and status controls were already
        // preserved by the immutable admission context above.
        if resumePendingPartnerClarificationIfNeeded(
            trimmed,
            context: context
        ) {
            return
        }
        if resumePendingGoldClarificationIfNeeded(
            trimmed,
            context: context
        ) {
            return
        }
        if context.selectedRoute == "native.mail.compose",
           context.resolvedSlots["privateMailContinuation"] == "true" {
            beginAppleMailDraftRouting(context.routingInput)
            return
        }

        // STT often prefixes the assistant's name ("ace, open safari", "hey
        // ace stop"). Strip the hail once so every route below matches the
        // bare request; a name-only utterance gets a short spoken ack.
        var utterance = strippingAssistantName(trimmed)
        guard !utterance.isEmpty else {
            Task { try? await noraVoice.speakText("yeah?") }
            return
        }

        // One leading STT filler token ("IS i need you to open…", "so find…")
        // breaks every ANCHORED route pattern and dumps real commands on the
        // brain. Strip exactly one — negations ("don't") are never stripped.
        utterance = strippingLeadingFiller(utterance)
        guard !utterance.isEmpty else { return }

        // A status query observes the existing work contract. It returns
        // before any held Gold, Partner, workflow, or app-action state can be
        // treated as replaced by the words used to ask about it.
        if context.selectedRoute == "native.response-repeat" {
            performRepeatResponse(context: context)
            return
        }
        if context.selectedRoute == "native.response-type" {
            performTypeLastResponse(context: context)
            return
        }
        if context.selectedRoute == "native.work-status" {
            publishCurrentWorkStatus(
                includeRecentTerminal:
                    context.exactInput.lowercased().contains(
                        "have you been doing"
                    )
            )
            return
        }
        if context.selectedRoute == "native.context-clarification",
           let question = context.resolvedSlots["clarificationQuestion"] {
            showVisibleResponse(question)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(question)
            }
            return
        }
        if context.selectedRoute == "native.pending-selection",
           let selectedValue = context.resolvedSlots["pendingExactValue"] {
            let accepted: Bool
            switch context.pendingSlot {
            case .mailSender:
                accepted = selectAppleMailSender(selectedValue)
            case .messageRecipient:
                accepted = selectAppleMessagesRecipient(selectedValue)
            case .actionTarget, .goldClarification, .locality, .none:
                accepted = false
            }
            let result = accepted
                ? "Selected \(selectedValue). The original request is continuing."
                : "That selection is no longer current. Choose one of the values now shown in Ace."
            showVisibleResponse(result)
            Task { [weak self] in
                try? await self?.noraVoice.speakText(result)
            }
            return
        }
        if context.selectedRoute == "native.locate.follow-up" {
            handleLocateAsk(context.routingInput)
            return
        }
        if routeMorningLinkBriefIfPresent(
            utterance,
            context: context
        ) {
            return
        }
        if routeStandingTaskIfPresent(
            utterance,
            context: context
        ) {
            return
        }

        // Client/device provider turns bypass every held owner-confirmation
        // parser. Their frozen scope cannot approve or replace an earlier
        // memory, workflow, typing, permission, dashboard, or tool effect.
        if dispatchDestination == .provider,
           !OwnerTurnDispatchPolicy.permitsHeldOwnerEffectResolution(
               for: context
           ) {
            guard let contextualRequest = bindOwnerTurnContext(context) else {
                return
            }
            sendTranscriptToClaudeWithScreenshot(
                transcript:
                    context.resolvedSlots["resolvedInstruction"]
                        ?? contextualRequest,
                context: context
            )
            return
        }

        // Company dispatch and silver workflows share one complete buyer-owned
        // capability grant. Resolve that grant before any mode or task route
        // can consume a generic confirmation. A missing, interrupted, denied,
        // or expired grant always remains visible and never falls through to a
        // weaker background lane.
        if preparedEmailReviewIsVisible {
            if CrossAppActionPolicy.isExplicitConfirmation(utterance) {
                confirmVisibleAppActionReview()
                return
            }
            cancelVisibleAppActionReview()
            if CrossAppActionPolicy.isExplicitCancellation(utterance) { return }
        }

        if resolvePendingAgentCapabilityConsent(with: utterance) {
            return
        }

        // A new utterance supersedes a plan that has not reached its exact
        // preview yet. Kill the isolated parser process and invalidate its
        // generation before interpreting the new words.
        if appActionPlanningTask != nil {
            let cancelledGeneration = appActionPlanningGeneration
            let priorReview = appActionReview
            let requiresDurableTerminal =
                appActionWorkCorrelationIdentifier != nil
            appActionPlanningGeneration = UUID()
            appActionPlanningTask?.cancel()
            appActionPlanningTask = nil
            appActionReviewExpiryTask?.cancel()
            appActionReviewExpiryTask = nil
            appActionBroker.discardCurrentPlan()
            claudeAPI.cancelInFlightAnswer()
            backgroundTaskActive =
                meetingNotetaker.isTakingNotes
                    || anyBackgroundExecutionAgentIsWorking
            appendRouteReceipt("APP-ACTION planning cancelled by new utterance")
            let reason =
                "A new owner utterance replaced app-action planning before execution."
            let persisted = completeDurableAppAction(
                status: .cancelled,
                outcome: "replaced",
                verification: "none",
                reason: reason,
                showVisible: true
            )
            if persisted, let priorReview,
               priorReview.planIdentifier == cancelledGeneration {
                appActionReview = AppActionReviewState(
                    planIdentifier: priorReview.planIdentifier,
                    exactPreview: priorReview.exactPreview,
                    phase: .notArmed(reason: reason)
                )
            }
            // Private pre-preview planning has no broker work receipt. Its
            // admitted turn was already retired by the replacement admission.
            guard !requiresDurableTerminal || persisted else { return }
        }

        // A sender-selection sheet has no approval authority. Any spoken
        // cancellation or replacement drops its exact pending mail request;
        // only the native sender button may resume it.
        if pendingMailDraftIntentStore.pendingIntent != nil,
           appActionPlanningTask == nil {
            clearPendingAppleMailDraftRequest()
            appendRouteReceipt(
                "APPLE-MAIL pending sender selection cancelled by utterance")
            if CrossAppActionPolicy.isExplicitCancellation(utterance) {
                Task { try? await noraVoice.speakText("okay, cancelled.") }
                return
            }
        }

        // Signed-out recovery and recipient choices carry no execution
        // authority. A replacement turn scrubs the exact in-memory request;
        // only a native recipient choice may advance it to the shared broker.
        if pendingAppleMessagesIntentStore.pendingIntent != nil,
           appActionPlanningTask == nil {
            clearPendingAppleMessagesRequest()
            appendRouteReceipt(
                "APPLE-MESSAGES pending recipient state cancelled by utterance")
            if CrossAppActionPolicy.isExplicitCancellation(utterance) {
                Task { try? await noraVoice.speakText("okay, cancelled.") }
                return
            }
        }

        // Any utterance during address lookup or exact readback replaces that
        // self-test in full. Its operation/address/content binding can never be
        // inherited by the replacement request.
        if isPreparingTestEmailSend {
            let priorReview = appActionReview
            testEmailGeneration = UUID()
            testEmailTask?.cancel()
            testEmailTask = nil
            isPreparingTestEmailSend = false
            pendingTestEmailSend = nil
            testEmailExpiryTask?.cancel()
            testEmailExpiryTask = nil
            if let process = testEmailProcess, process.isRunning {
                RunningProcessBox.terminateProcessTree(process)
            }
            testEmailProcess = nil
            if let priorReview {
                appActionReview = AppActionReviewState(
                    planIdentifier: priorReview.planIdentifier,
                    exactPreview: priorReview.exactPreview,
                    phase: .notArmed(
                        reason:
                            "Replaced by a new request. Nothing is armed."
                    )
                )
            }
            appendRouteReceipt(
                "EMAIL-TEST preview binding cancelled by replacement utterance")
        }

        // Mid-find continuation: after a locate, a verb-less noun phrase ("the
        // black label studio") lost its "find" to STT — restore it so it routes
        // back to locate instead of the slow brain path. Reads lastRouteWasLocate
        // (set by the PREVIOUS utterance); reset it now so THIS utterance's route
        // owns the flag (handleLocateAsk sets it true again if we locate).
        lastRouteWasLocate = false

        // A new utterance always ends any scanning act in progress, and
        // supersedes any running product walkthrough or first-run tour — the
        // new command wins.
        stopScanTheater()
        cancelWalkthroughIfRunning()
        // The exact rehearsal callback already consumes its own proof input.
        // Anything reaching normal routing is a new owner command and must
        // interrupt setup immediately, including Stop and Go Stealth.
        cancelFirstRunTourIfRunning(forceImmediate: true)

        // 0a. A populated capture whose provider generation failed remains only
        // in memory. Exact retry/discard phrases act on that visible pending
        // referent; unrelated utterances cannot replace or destroy it.
        if meetingNotetaker.hasPendingMeetingNotesRetry {
            if MeetingNotetaker.isPendingMeetingNotesRetryVoiceRequest(
                utterance
            ) {
                appendRouteReceipt(
                    "NOTES RETRY explicit voice retry received"
                )
                retryPendingMeetingNotes(context: context)
                return
            }
            if MeetingNotetaker.isPendingMeetingNotesDiscardVoiceRequest(
                utterance
            ) {
                let didDiscard = meetingNotetaker
                    .discardPendingMeetingNotesRetryFromOwner()
                guard didDiscard else {
                    let hasGeneratedReview =
                        meetingNotetaker.hasPendingGeneratedNotesReview
                    let reason = hasGeneratedReview
                        ? "The captured meeting is already in review. Reopen the notes review to continue."
                        : "There is no pending in-memory meeting capture to discard."
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: hasGeneratedReview ? .completed : .failed,
                        outcome: hasGeneratedReview
                            ? "notes-review-already-produced"
                            : "notes-retry-discard-refused",
                        reason: reason,
                        durableVerification:
                            hasGeneratedReview ? "verified" : "none",
                        durableStatusOverride:
                            hasGeneratedReview ? .completed : .failed
                    )
                    return
                }
                appendRouteReceipt(
                    "NOTES RETRY explicitly discarded by voice"
                )
                let reason =
                    "Discarded the pending in-memory meeting capture. Nothing was saved."
                if !finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .cancelled,
                    outcome: "notes-retry-discarded",
                    reason: reason,
                    durableVerification: "none",
                    durableStatusOverride: .cancelled
                ) {
                    showVisibleResponse(reason)
                }
                return
            }
            appendRouteReceipt(
                "NOTES RETRY retained across unrelated utterance"
            )
        }

        // 0b. Generated meeting content is only a proposal. The full text is
        // already visible in Ace's review window. Only a bounded, explicit
        // save phrase (or the physical button) can write the local files and
        // create the Apple Note. Generic assent never saves it. An unrelated
        // question leaves the review pending until its five-minute expiry so
        // asking Ace something cannot destroy the notes the owner just made.
        if meetingNotetaker.hasPendingGeneratedNotesReview {
            if MeetingNotesReviewIntentPolicy.isExplicitSave(utterance) {
                appendRouteReceipt(
                    "NOTES REVIEW explicit voice save received")
                Task {
                    guard directEffectsAreAllowed else { return }
                    let result =
                        await meetingNotetaker
                            .savePendingGeneratedNotesAfterExactVoiceConfirmation()
                    backgroundTaskActive = anyBackgroundExecutionAgentIsWorking
                    if !result.isEmpty {
                        try? await noraVoice.speakText(result)
                    }
                }
                return
            }
            if CrossAppActionPolicy.isExplicitCancellation(utterance) {
                meetingNotetaker.discardPendingGeneratedNotesReview(
                    reason: "direct user cancellation")
                appendRouteReceipt("NOTES REVIEW cancelled by user")
                Task {
                    try? await noraVoice.speakText(
                        "cancelled. those generated meeting notes were not saved.")
                }
                return
            }
            appendRouteReceipt(
                "NOTES REVIEW retained across unrelated utterance")
        }

        // Every retry is a new local correction child with exact typed prior
        // failure evidence. Before HQ acceptance it receives a fresh authorized
        // dispatch. After acceptance it may only reconcile the immutable remote
        // cursor; it never creates a second HQ session or revives the parent ID.
        if AceHQCompanyWorkPolicy.isExactRetryRequest(utterance),
           OwnerTurnDispatchPolicy.authorizesNativeRoute(
               "native.company-work",
               for: context
           ),
           retryableAceHQDispatch != nil {
            switch prepareAceHQRetry(context) {
            case let .newDispatch(request, capability):
                routeAceHQCompanyWork(
                    request: request,
                    capability: capability
                )
                return
            case let .reconcile(retryable):
                appendRouteReceipt(
                    "HQ accepted-cursor retry child="
                        + (retryable.reconciliationAttempt?.work
                            .correlationID ?? "missing")
                        + " parent="
                        + (retryable.reconciliationAttempt?.work
                            .parentCorrelationID ?? "missing")
                )
                beginAceHQDispatch(
                    retryable.intent,
                    resuming: retryable.acceptedDispatch,
                    reconciliationAttempt:
                        retryable.reconciliationAttempt
                )
                return
            case .refused:
                return
            case .notSpecial:
                break
            }
        }

        if resolvePendingAceHQConfirmation(with: utterance) { return }

        // 0b3. THE BUILD LANE'S KILL WORD. Checked before every other route so
        // nothing can eat it: while a job runs, Ace holds full machine
        // authority, and a grant the owner cannot revoke on a plain "stop" is
        // not a grant. Kills the whole process tree, then says so.
        if workflowRuntime.isBuilding,
           WorkflowRequestPolicy.isAbortRequest(utterance) {
            appendRouteReceipt("ROUTE workflow-kill")
            let directWorkCorrelationIdentifier =
                activeDirectWorkflowWorkCorrelationIdentifier
            let directOperationIdentifier =
                activeDirectWorkflowOperationIdentifier
            let goldWorkflowIsActive = activeGoldWorkflowRequest != nil
            workflowRuntime.abortActiveJob()
            if let directWorkCorrelationIdentifier,
               let directOperationIdentifier {
                _ = finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        directWorkCorrelationIdentifier,
                    lane: .silver,
                    durableLane: "silver",
                    status: .cancelled,
                    outcome: "cancelled.owner-stop",
                    verification: "none",
                    reason:
                        "Stopped. The workflow was killed; partial files may remain.",
                    slot: .activeWorkflow(
                        operationIdentifier:
                            directOperationIdentifier
                    ),
                    source: .silver,
                    turnIdentifier: sourceTurnIdentifier(
                        forWork: directWorkCorrelationIdentifier
                    ),
                    speak: !goldWorkflowIsActive
                )
            }
            return
        }

        // 0b4. "how's that build going" — answered from lane state, never from
        // the job's own output, which can contain the owner's data.
        if workflowRuntime.isBuilding,
           WorkflowRequestPolicy.isProgressRequest(utterance) {
            appendRouteReceipt("ROUTE workflow-progress")
            let spokenProgress = workflowRuntime.spokenProgress()
            Task { try? await noraVoice.speakText(spokenProgress) }
            return
        }

        // 0b5. Arm or drop a held build. This is the ONLY place a job gains
        // authority. The runtime revalidates the unchanged plan and its
        // 30-second window itself; a stale or replaced plan is consumed and
        // produces no build.
        if workflowRuntime.hasPendingPlan {
            if WorkflowRequestPolicy.isExplicitConfirmation(utterance) {
                appendRouteReceipt("ROUTE workflow-confirm")
                guard workflowRuntime.pendingPlanIsCurrent() else {
                    appendRouteReceipt(
                        "ROUTE workflow-confirm refused window=not-open"
                    )
                    let directWorkCorrelationIdentifier =
                        pendingDirectWorkflowWorkCorrelationIdentifier
                    directWorkflowConfirmationExpiryTask?.cancel()
                    directWorkflowConfirmationExpiryTask = nil
                    _ = workflowRuntime.cancelPendingJob()
                    _ = finishDirectTextTerminal(
                        workCorrelationIdentifier:
                            directWorkCorrelationIdentifier,
                        lane: .silver,
                        durableLane: "silver",
                        status: .blocked,
                        outcome: "blocked.confirmation-expired",
                        verification: "none",
                        reason:
                            "The exact workflow confirmation window was not open. Nothing ran.",
                        slot: .pendingWorkflow,
                        source: .silver,
                        turnIdentifier: sourceTurnIdentifier(
                            forWork: directWorkCorrelationIdentifier
                        )
                    )
                    return
                }
                let goldRequest = pendingGoldWorkflowRequest
                pendingGoldWorkflowRequest = nil
                let directWorkCorrelationIdentifier =
                    pendingDirectWorkflowWorkCorrelationIdentifier
                goldWorkflowConfirmationExpiryTask?.cancel()
                goldWorkflowConfirmationExpiryTask = nil
                directWorkflowConfirmationExpiryTask?.cancel()
                directWorkflowConfirmationExpiryTask = nil
                let spokenResult = workflowRuntime.confirmPendingJob(
                    suppressTerminalAnnouncement: goldRequest != nil
                )
                if let goldRequest {
                    if let operationIdentifier =
                            workflowRuntime.activeOperationIdentifier {
                        activeGoldWorkflowRequest = goldRequest
                        activeGoldWorkflowOperationIdentifier =
                            operationIdentifier
                        AceEventBus.shared.publishOutbound(
                            source: .silver,
                            state: .executing,
                            payloadType: .executionReceipt,
                            payload:
                                "typed-lane=green operation="
                                    + operationIdentifier
                                        .uuidString.lowercased(),
                            turnID:
                                goldRequest.sourceTurnIdentifier,
                            correlationID:
                                goldRequest.workCorrelationIdentifier
                        )
                        appendRouteReceipt(
                            "GOLD workflow started operation="
                                + operationIdentifier
                                    .uuidString.lowercased()
                                + " correlation="
                                + goldRequest
                                    .workCorrelationIdentifier
                                    .uuidString.lowercased()
                        )
                    } else {
                        completeGoldExecution(
                            goldRequest,
                            outcome: .blocked,
                            verification: .none,
                            spokenResult: spokenResult.isEmpty
                                ? "The exact workflow confirmation did not start a job. Nothing ran."
                                : spokenResult
                        )
                        return
                    }
                }
                if goldRequest == nil,
                   let directWorkCorrelationIdentifier {
                    if let operationIdentifier =
                            workflowRuntime.activeOperationIdentifier {
                        activeDirectWorkflowWorkCorrelationIdentifier =
                            directWorkCorrelationIdentifier
                        activeDirectWorkflowOperationIdentifier =
                            operationIdentifier
                        if pendingDirectWorkflowWorkCorrelationIdentifier
                            == directWorkCorrelationIdentifier {
                            pendingDirectWorkflowWorkCorrelationIdentifier = nil
                        }
                        _ = goldContextBundle.transitionWork(
                            workCorrelationIdentifier:
                                directWorkCorrelationIdentifier,
                            lane: "silver",
                            status: .running
                        )
                        _ = AceConversationHistory.saveBundle(
                            goldContextBundle,
                            performUnlessRaised: { body in
                                StealthEntryLatch.shared
                                    .performUnlessRaised(body)
                            }
                        )
                    } else {
                        _ = finishDirectTextTerminal(
                            workCorrelationIdentifier:
                                directWorkCorrelationIdentifier,
                            lane: .silver,
                            durableLane: "silver",
                            status: .blocked,
                            outcome: "blocked.no-operation",
                            verification: "none",
                            reason: spokenResult.isEmpty
                                ? "The exact workflow confirmation did not start a job. Nothing ran."
                                : spokenResult,
                            slot: .pendingWorkflow,
                            source: .silver,
                            turnIdentifier: sourceTurnIdentifier(
                                forWork: directWorkCorrelationIdentifier
                            )
                        )
                        return
                    }
                }
                if !spokenResult.isEmpty {
                    Task { try? await noraVoice.speakText(spokenResult) }
                }
                return
            }
            if WorkflowRequestPolicy.isExplicitCancellation(utterance) {
                appendRouteReceipt("ROUTE workflow-cancel")
                let goldRequest = pendingGoldWorkflowRequest
                pendingGoldWorkflowRequest = nil
                let directWorkCorrelationIdentifier =
                    pendingDirectWorkflowWorkCorrelationIdentifier
                goldWorkflowConfirmationExpiryTask?.cancel()
                goldWorkflowConfirmationExpiryTask = nil
                directWorkflowConfirmationExpiryTask?.cancel()
                directWorkflowConfirmationExpiryTask = nil
                _ = workflowRuntime.cancelPendingJob()
                if let goldRequest {
                    completeGoldExecution(
                        goldRequest,
                        outcome: .cancelled,
                        verification: .none,
                        spokenResult:
                            "The exact workflow plan was cancelled. Nothing ran."
                    )
                    return
                }
                _ = finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        directWorkCorrelationIdentifier,
                    lane: .silver,
                    durableLane: "silver",
                    status: .cancelled,
                    outcome: "cancelled",
                    verification: "none",
                    reason:
                        "The exact workflow plan was cancelled. Nothing ran.",
                    slot: .pendingWorkflow,
                    source: .silver,
                    turnIdentifier: sourceTurnIdentifier(
                        forWork: directWorkCorrelationIdentifier
                    )
                )
                return
            }
            // Anything else is ordinary conversation and must not inherit the
            // grant. The plan stays held until its window expires on its own.
        }

        // 0c. Resolve a pending close-sweep confirmation.
        if let pendingSweep = pendingCloseSweep {
            let sweepExceptions = pendingSweep.exceptions
            pendingCloseSweep = nil
            let confirmationAge =
                Date().timeIntervalSince(pendingSweep.requestedAt)
            let confirmationIsCurrent =
                confirmationAge >= 0
                    && confirmationAge
                        <= CrossAppActionPolicy.confirmationLifetime
            if confirmationIsCurrent,
               CrossAppActionPolicy.isExplicitConfirmation(utterance) {
                performCloseSweep(keeping: sweepExceptions)
            } else if !confirmationIsCurrent {
                Task {
                    try? await noraVoice.speakText(
                        "that close-apps confirmation expired. ask me to close them again.")
                }
            } else {
                Task { try? await noraVoice.speakText("okay, leaving everything open.") }
                if !CrossAppActionPolicy.isExplicitCancellation(utterance) {
                    rerouteActiveOwnerTurn()
                }
            }
            return
        }

        // 0e. The only automatic email send is a one-message self-test. It has
        // its own exact, expiring confirmation and never rides the model worker.
        if let pendingTest = pendingTestEmailSend {
            pendingTestEmailSend = nil
            testEmailExpiryTask?.cancel()
            testEmailExpiryTask = nil
            if !pendingTest.isCurrent(at: Date()) {
                appActionReview = AppActionReviewState(
                    planIdentifier: pendingTest.reviewIdentifier,
                    exactPreview: pendingTest.exactPreview,
                    phase: .notArmed(
                        reason: "Confirmation expired. Nothing was sent."
                    )
                )
                Task {
                    try? await noraVoice.speakText(
                        "that test-email confirmation expired. ask me to send the test again.")
                }
            } else if CrossAppActionPolicy.isExplicitConfirmation(utterance) {
                appActionReview = AppActionReviewState(
                    planIdentifier: pendingTest.reviewIdentifier,
                    exactPreview: pendingTest.exactPreview,
                    phase: .notArmed(
                        reason: "Confirmed once. Verifying Apple Mail now."
                    )
                )
                performTestEmailSend(pendingTest)
            } else if CrossAppActionPolicy.isExplicitCancellation(utterance) {
                appActionReview = AppActionReviewState(
                    planIdentifier: pendingTest.reviewIdentifier,
                    exactPreview: pendingTest.exactPreview,
                    phase: .notArmed(
                        reason: "Cancelled. Nothing was sent."
                    )
                )
                Task { try? await noraVoice.speakText("okay, no test email.") }
            } else {
                appActionReview = AppActionReviewState(
                    planIdentifier: pendingTest.reviewIdentifier,
                    exactPreview: pendingTest.exactPreview,
                    phase: .notArmed(
                        reason:
                            "Replaced by different wording. Nothing was sent."
                    )
                )
                Task { try? await noraVoice.speakText("okay, i cancelled the test email.") }
                rerouteActiveOwnerTurn()
            }
            return
        }

        // Bind bounded recent-work references only after the exhaustive
        // route/scope gate. A client/device/provider context therefore cannot
        // persist or execute through an owner-only native route.
        guard let contextualRequest = bindOwnerTurnContext(context) else {
            return
        }
        utterance = context.resolvedSlots["resolvedInstruction"]
            ?? contextualRequest

        // Exhaustive context dispatch. Every branch returns; no downstream
        // parser can replace the scope or route selected at admission.
        switch dispatchDestination {
        case .stop:
            return

        case .provider:
            if partnerModeIsActive,
               !ScreenContextPolicy.requiresGoldPointerRoute(
                    for: utterance
               ) {
                sendPartnerTurn(
                    transcript: utterance,
                    includesExplicitScreenContext: false
                )
            } else {
                if partnerModeIsActive {
                    appendRouteReceipt(
                        "POINTER explicit request retained coordinate-capable Gold route"
                    )
                }
                routeProviderOnce(
                    utterance,
                    context: context
                )
            }
            return

        case .refused:
            return

        case let .native(selectedRoute):
            switch selectedRoute {
            case "native.memory":
                performExplicitMemoryCommand(context: context)
                return
            case "native.response-repeat":
                performRepeatResponse(context: context)
                return
            case "native.response-type":
                performTypeLastResponse(context: context)
                return
            case "native.mail.setup":
                let setupSurface = LocalMailAccessController.shared
                    .openMailAccountSetup()
                switch setupSurface {
                case .internetAccounts:
                    appendRouteReceipt(
                        "ROUTE mail-account-setup app-owned surface=internet-accounts"
                    )
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: .completed,
                        outcome: "mail-account-setup-opened",
                        reason:
                            "Opened macOS Internet Accounts. Add your email account there; your credentials stay with macOS."
                    )
                case .appleMail:
                    appendRouteReceipt(
                        "ROUTE mail-account-setup app-owned surface=apple-mail-fallback"
                    )
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: .completed,
                        outcome: "mail-account-setup-opened",
                        reason:
                            "Opened Apple Mail. Choose Add Account there; your credentials stay with macOS."
                    )
                case nil:
                    appendRouteReceipt(
                        "ROUTE mail-account-setup failed surface=unavailable"
                    )
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: .failed,
                        outcome: "mail-account-setup-unavailable",
                        reason:
                            "Ace could not open Internet Accounts or Apple Mail. Open System Settings → Internet Accounts to add your account."
                    )
                }

            case "native.mail.compose":
                appendRouteReceipt(
                    "ROUTE Apple Mail compose (owner-private)"
                )
                beginAppleMailDraftRouting(context.routingInput)

            case "native.mail.read":
                guard let binding = ownerTurnLifecycle.activeBinding,
                      binding.context == context,
                      ownerTurnLifecycle.deferManagerDispatch(
                          for: binding
                      ) else {
                    appendRouteReceipt(
                        "EMAIL-READ refused missing frozen binding"
                    )
                    return
                }
                performEmailRead(utterance, binding: binding)

            case "provider.sign-in":
                let provider =
                    context.resolvedSlots["provider"] ?? "provider"
                MenuBarPanelManager.shared?
                    .showPanelForSettingsCommand()
                let reason =
                    "Open the \(provider) connection card in Ace and complete sign-in in the provider's browser window."
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .completed,
                    outcome: "provider-sign-in-panel-opened",
                    reason: reason
                )

            case "native.capabilities":
                appendRouteReceipt("ROUTE capabilities (product-owned)")
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .completed,
                    outcome: "capabilities-reported",
                    reason: LocalIntentPolicy.capabilityVisibleResponse
                )

            case "native.stealth-help":
                appendRouteReceipt("ROUTE stealth-help (product-owned)")
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .completed,
                    outcome: "stealth-help-reported",
                    reason: LocalIntentPolicy.stealthHelpResponse
                )

            case "native.presence":
                appendRouteReceipt("ROUTE presence (product-owned)")
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .completed,
                    outcome: "presence-reported",
                    reason: LocalIntentPolicy.presenceSpokenResponse
                )

            case "native.work-status":
                publishCurrentWorkStatus(
                    includeRecentTerminal:
                        LocalIntentPolicy.shouldIncludeRecentTerminal(
                            context.exactInput
                        )
                )

            case "native.installed-identity":
                appendRouteReceipt(
                    "ROUTE installed-identity (product-owned)"
                )
                let identity = AceUpdateCheck.currentInstalledIdentity()
                let version = identity.version?
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                let build = identity.build?
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if let version, !version.isEmpty,
                   let build, !build.isEmpty {
                    let bundlePath = Bundle.main.bundleURL
                        .resolvingSymlinksInPath().path
                    let installDescription = bundlePath == "/Applications/Ace.app"
                        ? "the authoritative /Applications/Ace.app"
                        : "\(bundlePath). The authoritative install is /Applications/Ace.app"
                    let sourceDescription: String
                    if let source = identity.sourceSha256,
                       !source.isEmpty {
                        sourceDescription =
                            " Source identity \(source.prefix(12))."
                    } else {
                        sourceDescription = ""
                    }
                    let reason =
                        "This Mac is running Ace \(version), Build \(build), from \(installDescription)."
                            + sourceDescription
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: .completed,
                        outcome: "installed-identity-reported",
                        reason: reason
                    )
                } else {
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: activeRoutingCorrelationID,
                        status: .failed,
                        outcome: "installed-identity-unavailable",
                        reason: "Ace could not read its sealed version and build. Open Ace from the menu bar, then Buyer Recovery to inspect the authoritative /Applications/Ace.app installation."
                    )
                }

            case "native.update-download":
                appendRouteReceipt("ROUTE update-download (product-owned)")
                if LocalIntentPolicy.requestsUpdateBrowserPage(context.exactInput) {
                    let correlationID = activeRoutingCorrelationID
                    _ = AceLicense.shared.openAccountPage { [weak self] opened in
                        guard let self else { return }
                        _ = self.finishVolatileOwnerTurn(
                            turnID: context.turnID,
                            correlationID: correlationID,
                            status: opened ? .completed : .failed,
                            outcome: opened ? "update-page-handoff-unverified" : "update-page-handoff-failed",
                            reason: AceLicense.shared.purchaseRecoveryStatus
                                ?? "Use the private download or billing link on your original purchase receipt."
                        )
                    }
                    return
                }
                let updateCorrelationID = activeRoutingCorrelationID
                let handoffStarted = AceUpdateCheck.shared
                    .openDownloadPageFromOwnerRequest { [weak self] result in
                        guard let self else { return }
                        let status: AceEventState
                        let outcome: String
                        let reason: String
                        switch result {
                        case .updated:
                            status = .completed
                            outcome = "update-runtime-verified"
                            reason = "Ace installed the selected release and verified the restarted app."
                        case .current:
                            status = .completed
                            outcome = "update-no-newer-release"
                            reason = "No newer verified release is available for this copy of Ace."
                        case .cancelled:
                            status = .cancelled
                            outcome = "update-cancelled"
                            reason = "The update was cancelled."
                        case .failed(let detail):
                            status = .failed
                            outcome = "update-failed"
                            reason = detail
                        }
                        _ = self.finishVolatileOwnerTurn(
                            turnID: context.turnID,
                            correlationID: updateCorrelationID,
                            status: status, outcome: outcome, reason: reason,
                            showVisible: false, speak: false
                        )
                    }
                if !handoffStarted {
                    _ = finishVolatileOwnerTurn(
                        turnID: context.turnID,
                        correlationID: updateCorrelationID,
                        status: .failed,
                        outcome: "update-transaction-not-admitted",
                        reason: "The update window is unavailable during setup or Private Mode. Finish setup or leave Private Mode, then try Update & Restart again."
                    )
                }

            case "native.weather.spoken-locality",
                 "native.weather.explicit-locality",
                 "native.weather.device-current",
                 "native.location.access":
                _ = routeNativeLocationIntentIfPresent(context)

            case "native.stealth-exit":
                if stealthMode.isActive {
                    exitStealthMode()
                }

            case "native.partner-command":
                guard let command = PartnerModePolicy.routableCommand(
                    for: utterance,
                    sessionIsActive: partnerModeIsActive
                ) else { return }
                _ = routePartnerModeCommand(
                    command,
                    transcript: utterance,
                    context: context
                )

            case "native.trading-mode":
                _ = routeTradingModeControlIfPresent(context.routingInput, context: context)
                return

            case "native.notes-start":
                guard startMeetingNotes() else {
                    if let workCorrelationIdentifier =
                            activeContextualOwnerRequest?
                                .childWorkCorrelationIdentifier {
                        _ = finishDirectWorkTerminal(
                            workCorrelationIdentifier:
                                workCorrelationIdentifier,
                            lane: .notes,
                            durableLane: "notes",
                            status: .blocked,
                            outcome: "blocked.notes-start-not-accepted",
                            verification: "none",
                            reason:
                                "The meeting-notes lane did not accept this start request.",
                            slot: .none
                        )
                    }
                    return
                }

            case "native.notes-stop":
                let commandCorrelationIdentifier =
                    activeRoutingCorrelationID
                _ = ownerTurnLifecycle.deferManagerDispatch(for: context)
                stopMeetingNotes(
                    commandTurnIdentifier: context.turnID,
                    commandCorrelationIdentifier:
                        commandCorrelationIdentifier
                )

            case "native.web-open":
                guard let url = context.resolvedSlots["url"] else {
                    return
                }
                _ = ownerTurnLifecycle.deferManagerDispatch(for: context)
                performInstantWebsiteOpen(url, context: context)

            case "native.web-search":
                guard let query = context.resolvedSlots["query"] else {
                    return
                }
                let opensTopResult =
                    context.resolvedSlots["opensTopResult"] == "true"
                let arguments = opensTopResult
                    ? ["--open-first", query]
                    : [query]
                appendRouteReceipt(
                    "WEB-SEARCH native query-characters=\(query.count) "
                        + "open-first=\(opensTopResult)"
                )
                beginDirectAppActionPreview(
                    PlannedAppAction(
                        tool: .webSearch,
                        arguments: arguments
                    )
                )

            case "native.app-switch":
                guard let target = context.resolvedSlots["appTarget"] else {
                    return
                }
                _ = ownerTurnLifecycle.deferManagerDispatch(for: context)
                performInstantAppSwitch(target, context: context)

            case "native.open-and-type":
                guard let target = context.resolvedSlots["appTarget"],
                      let instruction =
                        context.resolvedSlots["instruction"] else {
                    return
                }
                performOpenAndTypeRequest(
                    application: target,
                    text: instruction,
                    context: context
                )

            case "native.point":
                guard let target = context.resolvedSlots["target"] else {
                    return
                }
                performPointRequest(target, context: context)

            case "native.click":
                guard let target = context.resolvedSlots["target"] else {
                    return
                }
                performClickRequest(target, context: context)

            case "native.type":
                guard let text = context.resolvedSlots["instruction"] else {
                    return
                }
                performTypeRequest(text, context: context)

            case "native.window-close-all":
                performCloseAllWindowsRequest(context: context)

            case "native.key-press":
                guard let key = context.resolvedSlots["key"] else {
                    return
                }
                performKeyRequest(key, context: context)

            default:
                appendRouteReceipt(
                    "CONTEXT refused unknown local process control="
                        + selectedRoute
                )
                _ = finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID,
                    status: .failed,
                    outcome: "local-control-unhandled",
                    reason:
                        "Ace could not resolve that local process control."
                )
            }
            return
        }

    }
    /// Replacement handling stays inside the immutable admitted context. It
    /// may revisit execution gates after cancelling prior pending work, but it
    /// cannot parse a different input or select a different route.
    private func rerouteActiveOwnerTurn() {
        guard let activeOwnerTurnContext else { return }
        handleUtterance(activeOwnerTurnContext)
    }

    /// Every admitted turn is initially a durable, correlated running record.
    /// A deterministic route that returns without binding an asynchronous owner
    /// must not strand that record. Fail closed: without a route-owned typed
    /// receipt Ace records that no terminal proof was captured, never a guessed
    /// success. Routes with asynchronous ownership first move the record away
    /// from the initial `direct` lane.
    private func terminalizeUnclaimedContextualWorkIfNeeded() {
        guard let request = activeContextualOwnerRequest,
              let work = goldContextBundle.workRecords.first(where: {
                  $0.workCorrelationIdentifier
                    == request.childWorkCorrelationIdentifier
              }),
              work.status == .running,
              work.lane == "direct" else { return }
        _ = finishDirectWorkTerminal(
            workCorrelationIdentifier:
                request.childWorkCorrelationIdentifier,
            lane: .gold,
            durableLane: "native",
            status: .blocked,
            outcome: "blocked.native-terminal-missing",
            verification: "none",
            reason:
                "Ace's deterministic native route returned without a correlated terminal receipt; completion is unknown.",
            slot: .none
        )
    }

    // MARK: - First-run tour

    /// The gem's walk around the Mac, run once when setup finishes.
    private var firstRunTourTask: Task<Void, Never>? {
        didSet { refreshInstallReadinessSetupAuth() }
    }
    private var lastScreenAnswerExerciseSucceeded = false
    private var firstRunCompletionProofTask: Task<Void, Never>? {
        didSet { refreshInstallReadinessSetupAuth() }
    }
    private var firstRunTourRequiresOnboardingHotkeyProof = false
    /// Set only when the tour itself changed Trading Mode from off to on. A
    /// replay that begins while the owner already has Trading Mode active must
    /// demonstrate the purple lane without taking ownership of that state.
    /// The UUID prevents a cancelled tour's delayed defer from cleaning up a
    /// newer presentation.
    private var firstRunTourTradingDemoOwner: UUID?
    /// Dev-Mac filming override: when set (RUN_TOUR flag content), the tour
    /// stages on the display whose name contains this hint instead of the
    /// mouse's screen. Nil for every real buyer.
    var tourScreenHint: String?

    /// Lane coordination + display truth (ported from utah-Ace 2026-07-26).
    /// Bridged below from the subsystems' own publishers; `litTrailingLanes` is
    /// the flat mirror the overlay's trailing gem CLUSTER renders — each active
    /// background lane gets its own gem instead of red XOR blue XOR purple.
    private(set) lazy var laneManager = LaneManager()
    @Published private(set) var litTrailingLanes: [LaneID] = []
    private var laneMirrorCancellables: Set<AnyCancellable> = []
    private var licenseStateObserverIdentifier: UUID?
    private var lastObservedLicenseState: AceLicenseState = .unknown
    private var premiumRuntimeHasStarted = false
    private var premiumRuntimeIsQuiescedForEntitlement = false

    /// One stop on the tour: where the gem lands, what Nora says there, and the
    /// short label that stop leaves behind as a star in the constellation.
    private struct FirstRunTourStop {
        let gemLocation: CGPoint
        let spokenLine: String
        let constellationLabel: String
        /// When set, the gem dives in at this point and comes out at
        /// `gemLocation` — it reads as crawling behind whatever window is there.
        var crawlEntryLocation: CGPoint?
        /// Turns trading mode ON for this stop (gem goes purple, the lane's
        /// analyst context is genuinely active) and back off after. The mode is
        /// demonstrated, not described.
        var demonstratesTradingMode: Bool = false
        /// The colour the gem wears at this stop. Blue for notes, red for
        /// background work, purple for trading — the same colours that will
        /// appear during real use, shown while they're being explained.
        var accent: AceGemAccent = .gold
        /// After this stop's line, the gem reads the buyer's REAL screen and
        /// flies to one specific thing on it with a dry observation — the live
        /// demo. Skipped silently if the brain or capture isn't ready.
        var performsLiveDemoAfterLine: Bool = false
    }

    private func beginFirstRunTourTradingDemo(owner: UUID) {
        guard !tradingLane.isActive else {
            appendRouteReceipt(
                "TOUR trading-mode preserved (owner state already active)"
            )
            return
        }
        firstRunTourTradingDemoOwner = owner
        tradingLane.activate()
        tradingDataStatus = .unavailable(
            reason: "tour demonstration; no current chart capture"
        )
        tradingModeActive = true
        appendRouteReceipt(
            "TOUR trading-mode ON (gem purple, tour-owned lane active)"
        )
    }

    private func endFirstRunTourTradingDemoIfOwned(
        by owner: UUID? = nil,
        reason: String
    ) {
        guard let activeOwner = firstRunTourTradingDemoOwner,
              owner == nil || owner == activeOwner else { return }
        firstRunTourTradingDemoOwner = nil
        tradingLane.deactivate()
        tradingModeActive = false
        tradingDataStatus = .inactive
        appendRouteReceipt(
            "TOUR trading-mode OFF (tour-owned demo \(reason))"
        )
    }

    /// True while the tour is waiting for one complete rehearsal interaction:
    /// an event-tap keyboard press, the known phrase from that dictation session,
    /// and its matching event-tap keyboard release. Key-down by itself is not
    /// sufficient.
    @Published private(set) var isAwaitingFirstRunRehearsal = false
    private var firstRunRehearsalContinuation:
        CheckedContinuation<FirstRunRehearsalResult, Never>?
    private var activeFirstRunRehearsalAttemptIdentifier: UUID?
    private var firstRunRehearsalProofProgress =
        FirstRunRehearsalProofProgress()
    private var firstRunRehearsalTranscriptTimeoutTask:
        Task<Void, Never>?
    private var firstRunRehearsalOverallTimeoutTask:
        Task<Void, Never>?
    private var firstRunRehearsalWaitIdentifier: UUID?

    /// Until this moment passes, the introduction cannot be cancelled by an
    /// utterance. The rehearsal asks the user to hold the keys — which starts a
    /// dictation session, which produces a transcript, which cancelled the tour
    /// two seconds later. Observed 18:36:32 → `TOUR cancelled` 18:36:34: doing
    /// exactly what Ace asked killed the celebration and the menu-bar landing.
    private var rehearsalGraceDeadline: Date?

    /// True while the hold the rehearsal itself provoked is still settling.
    private var isInsideRehearsalGrace: Bool {
        guard let deadline = rehearsalGraceDeadline else { return false }
        return Date() < deadline
    }

    /// Starts a proof attempt on the event-tap keyboard press. The returned
    /// identifier is captured by that exact dictation callback, preventing a
    /// later session's transcript from completing an earlier press.
    private func beginFirstRunRehearsalAttemptIfAwaiting() -> UUID? {
        guard isAwaitingFirstRunRehearsal,
              firstRunRehearsalContinuation != nil,
              activeFirstRunRehearsalAttemptIdentifier == nil else {
            return nil
        }

        let attemptIdentifier = UUID()
        activeFirstRunRehearsalAttemptIdentifier = attemptIdentifier
        firstRunRehearsalProofProgress =
            FirstRunRehearsalProofProgress()
        firstRunRehearsalProofProgress.recordEventTapKeyboardPress()
        // Keep the rehearsal's own finalized transcript from cancelling the
        // tour before its proof can be evaluated.
        rehearsalGraceDeadline = Date().addingTimeInterval(70)
        appendRouteReceipt(
            "TOUR rehearsal event-tap keyboard press observed — phrase and event-tap keyboard release still required")
        return attemptIdentifier
    }

    private func recordFirstRunRehearsalRelease(
        attemptIdentifier: UUID?
    ) {
        guard let attemptIdentifier,
              attemptIdentifier
                == activeFirstRunRehearsalAttemptIdentifier else {
            return
        }
        firstRunRehearsalProofProgress.recordEventTapKeyboardRelease()
        evaluateFirstRunRehearsalAttempt()

        guard activeFirstRunRehearsalAttemptIdentifier
                == attemptIdentifier,
              !firstRunRehearsalProofProgress
                .didReceiveFinalTranscript else {
            return
        }
        firstRunRehearsalTranscriptTimeoutTask?.cancel()
        firstRunRehearsalTranscriptTimeoutTask = Task { [weak self] in
            do {
                try await Task.sleep(for: .seconds(5))
            } catch {
                return
            }
            guard let self,
                  self.activeFirstRunRehearsalAttemptIdentifier
                    == attemptIdentifier,
                  !self.firstRunRehearsalProofProgress
                    .didReceiveFinalTranscript else {
                return
            }
            self.appendRouteReceipt(
                "TOUR rehearsal released without a final transcript — retry required")
            self.resetFirstRunRehearsalAttemptForRetry()
            self.remindOwnerOfRehearsalPhrase()
        }
    }

    @discardableResult
    private func recordFirstRunRehearsalTranscript(
        _ transcript: String,
        attemptIdentifier: UUID?
    ) -> Bool {
        guard let attemptIdentifier,
              attemptIdentifier
                == activeFirstRunRehearsalAttemptIdentifier else {
            return false
        }
        if stealthMode.isEnterTrigger(transcript)
            || stealthMode.isExitTrigger(transcript)
            || CrossAppActionPolicy.isExplicitCancellation(transcript) {
            cancelFirstRunTourIfRunning(forceImmediate: true)
            return false
        }
        firstRunRehearsalProofProgress.recordFinalTranscript(
            transcript
        )
        evaluateFirstRunRehearsalAttempt()
        return true
    }

    private func evaluateFirstRunRehearsalAttempt() {
        guard activeFirstRunRehearsalAttemptIdentifier != nil else {
            return
        }
        if firstRunRehearsalProofProgress.isComplete {
            guard let continuation =
                    firstRunRehearsalContinuation else {
                return
            }
            firstRunRehearsalTranscriptTimeoutTask?.cancel()
            firstRunRehearsalTranscriptTimeoutTask = nil
            firstRunRehearsalOverallTimeoutTask?.cancel()
            firstRunRehearsalOverallTimeoutTask = nil
            firstRunRehearsalWaitIdentifier = nil
            isAwaitingFirstRunRehearsal = false
            firstRunRehearsalContinuation = nil
            activeFirstRunRehearsalAttemptIdentifier = nil
            rehearsalGraceDeadline = nil
            appendRouteReceipt(
                "TOUR rehearsal completed — event-tap keyboard press, known transcript, and event-tap keyboard release observed")
            continuation.resume(returning: .observed)
            return
        }

        if firstRunRehearsalProofProgress.didObserveEventTapKeyboardRelease,
           firstRunRehearsalProofProgress.didReceiveFinalTranscript,
           !firstRunRehearsalProofProgress.didRecognizeKnownPhrase {
            appendRouteReceipt(
                "TOUR rehearsal transcript did not match the known phrase — retry required")
            resetFirstRunRehearsalAttemptForRetry()
            remindOwnerOfRehearsalPhrase()
        }
    }

    private func resetFirstRunRehearsalAttemptForRetry() {
        firstRunRehearsalTranscriptTimeoutTask?.cancel()
        firstRunRehearsalTranscriptTimeoutTask = nil
        activeFirstRunRehearsalAttemptIdentifier = nil
        firstRunRehearsalProofProgress =
            FirstRunRehearsalProofProgress()
    }

    private func remindOwnerOfRehearsalPhrase() {
        Task { [weak self] in
            do {
                try await Task.sleep(for: .milliseconds(250))
            } catch {
                return
            }
            guard let self,
                  self.isAwaitingFirstRunRehearsal,
                  self.activeFirstRunRehearsalAttemptIdentifier
                    == nil else {
                return
            }
            try? await self.noraVoice.speakText(
                "try again. hold command and shift, say ready when you are, then let go."
            )
        }
    }

    /// Waits (bounded) for the complete event-tap keyboard
    /// press/transcript/release proof. The result is explicit so timeout or
    /// cancellation cannot masquerade as it.
    private func waitForFirstRunRehearsal(
        timeoutSeconds: Double,
        announceAfterArming: @escaping @MainActor () async -> Void
    ) async -> FirstRunRehearsalResult {
        await withCheckedContinuation {
            (continuation:
                CheckedContinuation<FirstRunRehearsalResult, Never>) in
            firstRunRehearsalOverallTimeoutTask?.cancel()
            resetFirstRunRehearsalAttemptForRetry()
            let waitIdentifier = UUID()
            firstRunRehearsalWaitIdentifier = waitIdentifier
            isAwaitingFirstRunRehearsal = true
            // The rehearsal needs FOUR things (see FirstRunRehearsalAttempt
            // .isComplete): the tap-observed key press, a final transcript, the
            // EXACT phrase, and the release. Holding the chord silently can
            // never satisfy it. Say so in a place that survives the spoken line.
            publishFinishSetupOwnerFacingStatus(
                "Finishing setup: hold Command and Shift, say \u{201C}"
                    + Self.firstRunRehearsalSpokenPhrase
                    + "\u{201D}, then let go."
            )
            firstRunRehearsalContinuation = continuation
            appendRouteReceipt(
                "TOUR rehearsal armed before owner instruction"
            )
            Task { @MainActor [weak self] in
                guard let self,
                      self.firstRunRehearsalWaitIdentifier
                        == waitIdentifier,
                      self.isAwaitingFirstRunRehearsal else {
                    return
                }
                await announceAfterArming()
                guard self.firstRunRehearsalWaitIdentifier
                        == waitIdentifier,
                      self.isAwaitingFirstRunRehearsal,
                      self.firstRunRehearsalContinuation != nil else {
                    return
                }
                self.firstRunRehearsalOverallTimeoutTask = Task {
                    @MainActor [weak self] in
                    do {
                        try await Task.sleep(
                            for: .seconds(timeoutSeconds)
                        )
                    } catch {
                        return
                    }
                    guard let self,
                          self.firstRunRehearsalWaitIdentifier
                            == waitIdentifier,
                          self.isAwaitingFirstRunRehearsal,
                          let pendingContinuation =
                            self.firstRunRehearsalContinuation else {
                        return
                    }
                    self.isAwaitingFirstRunRehearsal = false
                    self.publishFinishSetupOwnerFacingStatus(
                        "Setup did not finish: Ace never heard \u{201C}"
                            + Self.firstRunRehearsalSpokenPhrase
                            + "\u{201D} while Command and Shift were held."
                            + " Press Start to try again."
                    )
                    self.firstRunRehearsalContinuation = nil
                    self.firstRunRehearsalWaitIdentifier = nil
                    self.firstRunRehearsalOverallTimeoutTask = nil
                    self.resetFirstRunRehearsalAttemptForRetry()
                    self.rehearsalGraceDeadline = nil
                    self.appendRouteReceipt(
                        "TOUR rehearsal timed out — onboarding remains incomplete"
                    )
                    pendingContinuation.resume(returning: .timedOut)
                }
            }
        }
    }

    /// Real on-screen windows big enough to crawl behind, nearest-to-center
    /// first. Read-only enumeration — no Accessibility call, no window is
    /// touched, and Ace's own surfaces are excluded so it never "crawls behind"
    /// its own gem.
    private func onScreenWindowsForTour(on screen: NSScreen) -> [CGRect] {
        guard let windowList = CGWindowListCopyWindowInfo(
            [.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]]
        else { return [] }

        let primaryDisplayHeight = WindowTiler.primaryDisplayHeightInPoints()
        let ownProcessIdentifier = ProcessInfo.processInfo.processIdentifier

        var frames: [CGRect] = []
        for windowInfo in windowList {
            guard let layer = windowInfo[kCGWindowLayer as String] as? Int, layer == 0,
                  let ownerPID = windowInfo[kCGWindowOwnerPID as String] as? Int32,
                  ownerPID != ownProcessIdentifier,
                  let boundsDictionary = windowInfo[kCGWindowBounds as String] as? [String: Any],
                  let x = boundsDictionary["X"] as? CGFloat,
                  let y = boundsDictionary["Y"] as? CGFloat,
                  let width = boundsDictionary["Width"] as? CGFloat,
                  let height = boundsDictionary["Height"] as? CGFloat,
                  width > 420, height > 260,
                  // Not a near-full-width window. Crawling "behind" one of those
                  // sent the gem 3,392 pixels across the monitor in a single
                  // fade (observed: in (41,599) → out (3433,599)) — a jump cut,
                  // not something moving behind a window.
                  width < screen.frame.width * 0.55
            else { continue }
            // CoreGraphics is top-left origin; the gem lives in AppKit's
            // bottom-left world.
            let appKitFrame = CGRect(
                x: x, y: primaryDisplayHeight - y - height, width: width, height: height)
            guard screen.frame.intersects(appKitFrame) else { continue }
            frames.append(appKitFrame)
        }

        let screenCenter = CGPoint(x: screen.frame.midX, y: screen.frame.midY)
        return frames.sorted { first, second in
            func distance(_ rect: CGRect) -> CGFloat {
                hypot(rect.midX - screenCenter.x, rect.midY - screenCenter.y)
            }
            return distance(first) < distance(second)
        }
    }

    /// Ace introduces itself by MOVING — the gold gem flies to the menu-bar icon,
    /// then out into the middle of the screen, speaking one line per stop. Read
    /// text teaches nobody where an invisible menu-bar app lives; watching the
    /// thing fly to its own icon does it in two seconds. Stops are computed from
    /// the real status-item frame and the real screen, so this is correct on a
    /// notched laptop, an external display, or a crowded menu bar.
    ///
    /// Cancelled by "stop" and by any new utterance, like every other
    /// choreography — the tour never holds the app hostage.
    func startFirstRunTour(
        requiresOnboardingHotkeyProof: Bool = false
    ) {
        guard !stealthMode.isActive, !StealthVisibilityGate.shared.isActive else {
            appendRouteReceipt("TOUR deferred — stealth active")
            return
        }
        guard !requiresOnboardingHotkeyProof
                || globalPushToTalkShortcutMonitor.isEventTapOperational else {
            appendRouteReceipt(
                "TOUR deferred — onboarding event tap is not operational")
            schedulePendingOnboardingHotkeyProofResume()
            return
        }
        let tourRequest: FirstRunTourRequest =
            requiresOnboardingHotkeyProof
                ? .automatic
                : .explicitReplay
        switch FirstRunExperienceState.shared.beginTourPresentation(
            request: tourRequest
        ) {
        case .alreadyActive:
            appendRouteReceipt("TOUR ignored — presentation already active")
            return
        case .alreadyViewed:
            appendRouteReceipt(
                "TOUR not replayed — continuing with Finish Setup proof"
            )
            startFirstRunCompletionProof()
            return
        case .acquired:
            break
        }
        if let pendingContinuation =
            firstRunRehearsalContinuation {
            isAwaitingFirstRunRehearsal = false
            firstRunRehearsalContinuation = nil
            resetFirstRunRehearsalAttemptForRetry()
            pendingContinuation.resume(returning: .cancelled)
        }
        rehearsalGraceDeadline = nil
        firstRunTourTask?.cancel()
        firstRunTourRequiresOnboardingHotkeyProof =
            requiresOnboardingHotkeyProof
        let tourRequiresOnboardingHotkeyProof =
            requiresOnboardingHotkeyProof

        // The tour must run on the display the user is LOOKING AT. `NSScreen.main`
        // is the screen with the key window — and a menu-bar app has no key
        // window, so it resolved to whichever display macOS felt like: the whole
        // introduction ran off on a second monitor at x = -864 while the owner
        // watched an empty screen and concluded the gem was broken. The mouse is
        // where attention is; the primary display (which owns the menu bar) is
        // the fallback.
        let mouseLocation = NSEvent.mouseLocation
        let stageHint = tourScreenHint ?? UserDefaults.standard.string(forKey: "StageScreenHint")
        let hintedScreen = stageHint.flatMap { hint in
            NSScreen.screens.first { $0.localizedName.localizedCaseInsensitiveContains(hint) }
        }
        let tourScreen = hintedScreen
            ?? NSScreen.screens.first { $0.frame.contains(mouseLocation) }
            ?? NSScreen.screens.first
            ?? NSScreen.main
        guard let screen = tourScreen else {
            FirstRunExperienceState.shared.endTourPresentation()
            return
        }
        let screenFrame = screen.frame

        let menuBarIconLocation = MenuBarPanelManager.shared?.statusItemCenterInAppKitCoordinates()
            // Fallback if the icon can't be located: just under the menu bar on
            // the right, which is where it lives even when we can't measure it.
            ?? CGPoint(x: screenFrame.maxX - 60, y: screenFrame.maxY - 12)

        // Real windows to crawl behind. If the desktop is empty the tour still
        // works — those stops just become open-screen positions.
        let crawlableWindows = onScreenWindowsForTour(on: screen)
        func crawlStop(
            windowIndex: Int,
            fallback: CGPoint,
            line: String,
            label: String,
            accent: AceGemAccent
        ) -> FirstRunTourStop {
            guard windowIndex < crawlableWindows.count else {
                return FirstRunTourStop(
                    gemLocation: fallback, spokenLine: line, constellationLabel: label,
                    accent: accent)
            }
            let window = crawlableWindows[windowIndex]
            // In at one edge, out the other — but never more than a short hop.
            // A crawl only reads as one gesture if both points are close.
            let crawlSpan = min(window.width - 48, 420)
            let entryX = window.minX + 24
            return FirstRunTourStop(
                gemLocation: CGPoint(x: entryX + crawlSpan, y: window.midY),
                spokenLine: line,
                constellationLabel: label,
                crawlEntryLocation: CGPoint(x: entryX, y: window.midY),
                accent: accent
            )
        }

        // The script (rewritten 2026-07-26, founder ruling): no self-announcing,
        // no name-dropping, no filler. Short declaratives about what the OWNER
        // can do. The first stop is followed by the LIVE DEMO — the one beat
        // upstream Clicky had that we lacked: the gem reads the buyer's actual
        // screen and reacts to something real on it, mid-introduction. Telling
        // someone their computer can see is nothing; showing them is everything.
        let stops: [FirstRunTourStop] = [
            FirstRunTourStop(
                gemLocation: CGPoint(x: screenFrame.midX, y: screenFrame.midY + screenFrame.height * 0.12),
                spokenLine: "hold command and shift. ask about anything on screen. "
                    + "let go — i answer.",
                constellationLabel: "hold to talk",
                performsLiveDemoAfterLine: true
            ),
            crawlStop(
                windowIndex: 0,
                fallback: CGPoint(x: screenFrame.midX - screenFrame.width * 0.28, y: screenFrame.midY),
                line: "in a meeting, say: take notes. audio stays local. "
                    + "the summary uses your ai account.",
                label: "meeting notes",
                accent: .blue
            ),
            crawlStop(
                windowIndex: 1,
                fallback: CGPoint(x: screenFrame.midX + screenFrame.width * 0.28, y: screenFrame.midY),
                line: "hand me a job and keep working. "
                    + "i run it back here — red until it's done.",
                label: "background work",
                accent: .red
            ),
            FirstRunTourStop(
                gemLocation: CGPoint(x: screenFrame.midX + screenFrame.width * 0.14,
                                     y: screenFrame.midY - screenFrame.height * 0.16),
                spokenLine: "watching a chart? say: trading mode. "
                    + "structure, volume, where it breaks. never a price target, never a trade.",
                constellationLabel: "trading mode",
                demonstratesTradingMode: true,
                accent: .purple
            ),
            FirstRunTourStop(
                gemLocation: CGPoint(x: screenFrame.midX - screenFrame.width * 0.14,
                                     y: screenFrame.midY - screenFrame.height * 0.18),
                spokenLine: "need me gone? say: go stealth, or turn caps lock on and press shift and z once. "
                    + "that one gesture enters stealth and answers the visible multiple choice question while i stay hidden. "
                    + "to return, hold command and shift and say exit stealth.",
                constellationLabel: "stealth"
            ),
        ]

        overlayWindowManager.hasShownOverlayBefore = true
        guard overlayWindowManager.showOverlay(
            onScreens: NSScreen.screens,
            companionManager: self
        ) else {
            firstRunTourRequiresOnboardingHotkeyProof = false
            FirstRunExperienceState.shared.endTourPresentation()
            return
        }
        isOverlayVisible = true
        appendRouteReceipt(
            "TOUR start stops=\(stops.count) "
                + "crawlableWindows=\(crawlableWindows.count) "
                + "screen=(\(Int(screenFrame.minX)),"
                + "\(Int(screenFrame.minY)) "
                + "\(Int(screenFrame.width))x"
                + "\(Int(screenFrame.height)))"
        )

        let tradingDemoOwner = UUID()
        firstRunTourTask = Task {
            defer {
                endFirstRunTourTradingDemoIfOwned(
                    by: tradingDemoOwner,
                    reason: "task ended"
                )
                FirstRunExperienceState.shared.endTourPresentation()
                firstRunTourTask = nil
                firstRunTourRequiresOnboardingHotkeyProof = false
            }
            guard !Task.isCancelled,
                  !StealthEntryLatch.shared.isRaised,
                  directEffectsAreAllowed else {
                return
            }
            voiceState = .responding
            let stage = AceStageOverlayController.shared
            var productionScreenAnswerExerciseSucceeded = false
            lastScreenAnswerExerciseSucceeded = false

            // ── 1. THE ARRIVAL ────────────────────────────────────────────
            // Keep first run compact. The former full-display galaxy and white
            // ignition changed every screen at once and read as a flash. The
            // same small touring gem now appears at center and immediately
            // begins the walkthrough without covering the owner's work.
            stage.present()
            stage.model.galaxyIntensity = 0
            stage.model.showsArrivalGem = false
            stage.model.ignitionProgress = 0
            stage.model.gemScale = 1
            stage.model.gemLocation = CGPoint(
                x: screenFrame.midX,
                y: screenFrame.midY
            )
            withAnimation(.easeIn(duration: 0.2)) {
                stage.model.constellationOpacity = 1
            }
            appendRouteReceipt("TOUR compact arrival gem")
            try? await Task.sleep(for: .milliseconds(200))
            if !Task.isCancelled {
                try? await noraVoice.speakText("there we go. much better.")
                await waitForSpeechPlaybackToFinishOrCancellation()
            }
            stage.model.addImpactRing(
                at: CGPoint(
                    x: screenFrame.midX,
                    y: screenFrame.midY
                )
            )
            try? await Task.sleep(for: .milliseconds(150))

            // ── 2. THE WALK-AROUND ────────────────────────────────────────
            for (stopIndex, stop) in stops.enumerated() {
                if Task.isCancelled { break }

                // The gem wears this stop's colour BEFORE it flies there, so
                // the change is part of the move rather than an afterthought.
                withAnimation(.easeInOut(duration: 0.4)) { stage.model.gemAccent = stop.accent }
                if stop.demonstratesTradingMode {
                    // Actually switch the lane on — the purple gem the buyer sees
                    // here is the real trading mode, not a mock-up of it. The
                    // tour only owns the activation when the owner did not
                    // already have Trading Mode enabled before this stop.
                    beginFirstRunTourTradingDemo(
                        owner: tradingDemoOwner
                    )
                }

                if let entryLocation = stop.crawlEntryLocation {
                    // Fly to the near edge of the window — and wait for the
                    // LANDING, not a guessed 700ms. A long approach used to
                    // out-live the guess, so the gem shrank mid-air and then
                    // teleported in the open. That was the "jumpy" cut.
                    let approach = stage.model.flyGem(to: entryLocation)
                    detectedElementScreenLocation = entryLocation
                    detectedElementDisplayFrame = screenFrame
                    clickFlashTrigger += 1
                    try? await Task.sleep(for: .milliseconds(Int(approach * 1000) + 150))
                    if Task.isCancelled { break }
                    // …a ripple collapsing inward as it goes under…
                    stage.model.addImpactRing(at: entryLocation, collapsing: true)
                    withAnimation { stage.model.gemScale = 0.05 }
                    try? await Task.sleep(for: .milliseconds(330))
                    appendRouteReceipt(
                        "TOUR-CRAWL in (\(Int(entryLocation.x)),\(Int(entryLocation.y))) "
                        + "→ out (\(Int(stop.gemLocation.x)),\(Int(stop.gemLocation.y)))")
                    // …and surface on the far side with a ripple of its own, no
                    // flight in between, so it reads as having gone behind.
                    stage.model.placeGem(at: stop.gemLocation)
                    stage.model.addImpactRing(at: stop.gemLocation)
                    try? await Task.sleep(for: .milliseconds(120))
                    withAnimation { stage.model.gemScale = 1 }
                }

                if stop.crawlEntryLocation == nil { stage.model.flyGem(to: stop.gemLocation) }
                detectedElementScreenLocation = stop.gemLocation
                detectedElementDisplayFrame = screenFrame
                clickFlashTrigger += 1
                appendRouteReceipt(
                    "TOUR-STEP \(stopIndex + 1)/\(stops.count) at "
                    + "(\(Int(stop.gemLocation.x)),\(Int(stop.gemLocation.y)))")

                withAnimation(.spring(response: 0.5, dampingFraction: 0.7)) {
                    stage.model.constellationStars.append(
                        AceConstellationStar(
                            id: stopIndex,
                            location: stop.gemLocation,
                            label: stop.constellationLabel
                        )
                    )
                }

                // Let the gem land before the line starts — the whole effect is
                // that it's talking about the thing it just flew to. The arc
                // flight owns its own duration, so wait for it, then ring.
                try? await Task.sleep(for: .milliseconds(760))
                stage.model.addImpactRing(at: stop.gemLocation)
                if Task.isCancelled { break }
                let exactLineCompleted =
                    await noraVoice.speakTextToVerifiedCompletion(
                        stop.spokenLine
                    )
                guard TourSpeechAdvancePolicy.shouldAdvance(
                    exactLineCompleted: exactLineCompleted,
                    taskIsCancelled: Task.isCancelled
                ) else {
                    if stop.demonstratesTradingMode {
                        endFirstRunTourTradingDemoIfOwned(
                            by: tradingDemoOwner,
                            reason: "speech stopped"
                        )
                    }
                    appendRouteReceipt(
                        "TOUR stopped — exact speech line did not complete"
                    )
                    showVisibleResponse(
                        "Ace could not finish that tour line. Choose Replay Tour to retry."
                    )
                    break
                }

                if stop.demonstratesTradingMode {
                    // The demo leaves nothing switched on behind it — a buyer
                    // who never asked for trading mode must not be left in it.
                    endFirstRunTourTradingDemoIfOwned(
                        by: tradingDemoOwner,
                        reason: "completed"
                    )
                }

                // ── THE LIVE DEMO ─────────────────────────────────────────
                // Right after "let go — i answer", prove it: read the buyer's
                // actual screen, fly to one real thing on it, and react. This
                // is the beat that makes the introduction THEIRS instead of a
                // performance that plays the same on every machine. During
                // required onboarding this production capture + Claude answer
                // is a hard proof, not an optional flourish.
                if stop.performsLiveDemoAfterLine && !Task.isCancelled {
                    if let demo = await performFirstRunDemoObservation() {
                        productionScreenAnswerExerciseSucceeded = true
                        lastScreenAnswerExerciseSucceeded = true
                        // One breath before speaking: the brain subprocess that
                        // just returned (claude + two screenshots) leaves the
                        // CPU hot, and a line started inside that spike is the
                        // one line of the show that stuttered.
                        try? await Task.sleep(for: .milliseconds(450))
                        try? await noraVoice.speakText("watch.")
                        await waitForSpeechPlaybackToFinishOrCancellation()
                        if !Task.isCancelled {
                            let pointFlight = stage.model.flyGem(to: demo.appKitLocation)
                            detectedElementScreenLocation = demo.appKitLocation
                            detectedElementDisplayFrame = screenFrame
                            markDetectedElementAsVerified()
                            try? await Task.sleep(for: .milliseconds(Int(pointFlight * 1000) + 150))
                            stage.model.addImpactRing(at: demo.appKitLocation)
                            appendRouteReceipt(
                                "TOUR-DEMO pointed at (\(Int(demo.appKitLocation.x)),\(Int(demo.appKitLocation.y)))")
                            try? await noraVoice.speakText(demo.spokenObservation)
                            await waitForSpeechPlaybackToFinishOrCancellation()
                        }
                    } else if tourRequiresOnboardingHotkeyProof {
                        appendRouteReceipt(
                            "ONBOARDING blocked — production screen capture and Claude answer exercise failed")
                    } else {
                        appendRouteReceipt("TOUR-DEMO skipped (no observation)")
                    }
                }

                withAnimation(.easeInOut(duration: 0.4)) { stage.model.gemAccent = .gold }

                if Task.isCancelled { break }
                if tourRequiresOnboardingHotkeyProof,
                   !productionScreenAnswerExerciseSucceeded {
                    break
                }
                try? await Task.sleep(for: .milliseconds(250))
            }

            // ── 3. THE REHEARSAL ──────────────────────────────────────────
            // The screen/answer production exercise comes first. If it failed,
            // setup stops here and offers a direct retry; it never logs the
            // failure and continues into a completion-capable rehearsal.
            var rehearsalResult: FirstRunRehearsalResult = .cancelled
            if tourRequiresOnboardingHotkeyProof,
               !productionScreenAnswerExerciseSucceeded,
               !Task.isCancelled {
                try? await noraVoice.speakText(
                    "the live screen check didn't finish, so setup is still unfinished. use try again after this window closes."
                )
                await waitForSpeechPlaybackToFinishOrCancellation()
            } else if tourRequest.requiresOwnerRehearsal
                && !Task.isCancelled
                && globalPushToTalkShortcutMonitor.isEventTapOperational {
                stage.model.flyGem(to: CGPoint(x: screenFrame.midX, y: screenFrame.midY))
                detectedElementScreenLocation = CGPoint(x: screenFrame.midX, y: screenFrame.midY)
                detectedElementDisplayFrame = screenFrame
                clickFlashTrigger += 1
                if !Task.isCancelled {
                    appendRouteReceipt(
                        "TOUR rehearsal waiting for event-tap keyboard press, known transcript, and event-tap keyboard release")
                    rehearsalResult = await waitForFirstRunRehearsal(
                        timeoutSeconds: 15,
                        announceAfterArming: { [weak self] in
                            guard let self else { return }
                            try? await self.noraVoice.speakText(
                                "your turn. hold command and shift, say "
                                    + Self.firstRunRehearsalSpokenPhrase
                                    + ", then let go."
                            )
                            await self
                                .waitForSpeechPlaybackToFinishOrCancellation()
                        }
                    )
                    if rehearsalResult == .observed,
                       !Task.isCancelled {
                        let proofWasAccepted =
                            !tourRequiresOnboardingHotkeyProof
                            || persistFirstRunCompletionIfProven(
                                productionScreenAnswerExerciseSucceeded:
                                    productionScreenAnswerExerciseSucceeded,
                                rehearsalResult: rehearsalResult
                            )
                        clickFlashTrigger += 1
                        try? await noraVoice.speakText(
                            proofWasAccepted
                                ? "that's it. that's the whole thing."
                                : "i heard the keys, but the hotkey lost its "
                                    + "connection. setup is still unfinished.")
                        await waitForSpeechPlaybackToFinishOrCancellation()
                    } else if rehearsalResult == .timedOut,
                              !Task.isCancelled {
                        try? await noraVoice.speakText(
                            "i didn't catch the phrase in time, so setup "
                                + "isn't finished yet. it picks up right "
                                + "here on the next launch.")
                        await waitForSpeechPlaybackToFinishOrCancellation()
                    }
                }
            } else if !Task.isCancelled {
                appendRouteReceipt(
                    "TOUR rehearsal skipped — event tap is not operational")
            }

            if tourRequiresOnboardingHotkeyProof,
               !hasCompletedOnboarding {
                appendRouteReceipt(
                    "ONBOARDING remains incomplete — productionExercise="
                        + "\(productionScreenAnswerExerciseSucceeded) rehearsal="
                        + String(describing: rehearsalResult)
                )
            }

            // ── 4. MOVING IN ──────────────────────────────────────────────
            // Ace goes home: up to the menu-bar icon, and stays there.
            if !Task.isCancelled {
                withAnimation(.easeOut(duration: 0.8)) { stage.model.constellationOpacity = 0 }
                let homeFlight = stage.model.flyGem(to: menuBarIconLocation)
                detectedElementScreenLocation = menuBarIconLocation
                detectedElementDisplayFrame = screenFrame
                clickFlashTrigger += 1
                try? await Task.sleep(for: .milliseconds(Int(homeFlight * 1000) + 150))
                try? await noraVoice.speakText(
                    (!tourRequiresOnboardingHotkeyProof
                        || productionScreenAnswerExerciseSucceeded)
                        ? "i'll be up here. hold the keys when you need me."
                        : "i'll be up here. setup is still waiting on the live screen check."
                )
                await waitForSpeechPlaybackToFinishOrCancellation()
                // Ace moves in: the gem shrinks into the menu-bar icon and stays
                // there. The app physically puts itself where it lives.
                stage.model.addImpactRing(at: menuBarIconLocation, collapsing: true)
                withAnimation(.easeIn(duration: 0.55)) { stage.model.gemScale = 0.02 }
                try? await Task.sleep(for: .milliseconds(600))
                clickFlashTrigger += 1
            }

            stage.dismiss()
            let shouldOfferScreenAnswerExerciseRetry =
                tourRequiresOnboardingHotkeyProof
                && !productionScreenAnswerExerciseSucceeded
                && !Task.isCancelled
            appendRouteReceipt(Task.isCancelled ? "TOUR cancelled" : "TOUR done")
            if !Task.isCancelled {
                voiceState = .idle
                clearDetectedElementLocation()
                // Release the handle on natural completion. A finished task left
                // in the property made the NEXT utterance's cancel call believe
                // a tour was still running and fire the concede path against a
                // dismissed stage — stale 'TOUR conceded' receipt 13s after
                // 'TOUR done' (observed live 2026-07-26 17:41:47).
                firstRunTourTask = nil
                firstRunTourRequiresOnboardingHotkeyProof = false
            }
            if shouldOfferScreenAnswerExerciseRetry {
                FirstRunFailureReporter.shared.report(
                    FirstRunFailure(
                        id: "onboarding.screenAnswerExercise",
                        summary:
                            "Ace could not complete the live screen-and-answer check.",
                        remedy:
                            "Setup remains unfinished. Keep Screen Recording on and make sure the Codex or Claude account selected in Setup is connected, then press Try Again. Ace must capture the real screen and receive a real account answer before setup can finish.",
                        repairButtonTitle: "Try Again"
                    ),
                    interrupt: true,
                    repairRevision: "screen-answer-exercise-v1",
                    verifiedRepair: { [weak self] in
                        guard let self else {
                            return .failed(
                                PermissionRepairFailure(
                                    code: "screen_exercise.owner_released",
                                    message: "The screen exercise controller is no longer available."
                                )
                            )
                        }
                        self.lastScreenAnswerExerciseSucceeded = false
                        self.startFirstRunTour(
                            requiresOnboardingHotkeyProof: true
                        )
                        guard let admittedExercise = self.firstRunTourTask else {
                            return .failed(
                                PermissionRepairFailure(
                                    code: "screen_exercise.not_admitted",
                                    message: "A new screen-and-answer exercise was not admitted for this repair attempt."
                                )
                            )
                        }
                        await admittedExercise.value
                        if !self.lastScreenAnswerExerciseSucceeded {
                            return .failed(
                                PermissionRepairFailure(
                                    code: "screen_exercise.not_verified",
                                    message: "The live screen capture and real provider answer were not both verified."
                                )
                            )
                        }
                        return .succeeded(
                            .verifiedOperation("live_screen_and_answer")
                        )
                    }
                )
            }
        }
    }

    /// After the one-time tour has been seen, readiness retries use only the
    /// two proofs that can complete setup. This keeps the repair actionable
    /// without making the owner watch the five-stop product tour again.
    private func startFirstRunCompletionProof() {
        guard firstRunCompletionProofTask == nil,
              firstRunTourTask == nil else {
            appendRouteReceipt(
                "ONBOARDING proof ignored — another presentation is active"
            )
            return
        }
        guard globalPushToTalkShortcutMonitor.isEventTapOperational else {
            showVisibleResponse(
                "Finish Setup: Accessibility must be enabled before Ace can verify the push-to-talk keys."
            )
            appendRouteReceipt(
                "ONBOARDING Finish Setup blocked — event tap unavailable"
            )
            return
        }

        showVisibleResponse(
            "Finish Setup: checking one live screen answer, then the push-to-talk keys."
        )
        appendRouteReceipt("ONBOARDING Finish Setup proof started")
        firstRunCompletionProofTask = Task { [weak self] in
            guard let self else { return }
            defer {
                self.firstRunCompletionProofTask = nil
                if !self.hasCompletedOnboarding {
                    self.voiceState = .idle
                }
            }

            self.voiceState = .responding
            guard await self.performFirstRunDemoObservation() != nil,
                  !Task.isCancelled else {
                if !Task.isCancelled {
                    self.showVisibleResponse(
                        "Finish Setup could not verify a live screen answer. Check Screen Recording and your selected AI account, then try again."
                    )
                    self.appendRouteReceipt(
                        "ONBOARDING Finish Setup blocked — live screen answer failed"
                    )
                }
                return
            }

            self.showVisibleResponse(
                "Screen check passed. Hold Command and Shift, say “ready when you are,” then let go."
            )
            let rehearsalResult = await self.waitForFirstRunRehearsal(
                timeoutSeconds: 15,
                announceAfterArming: { [weak self] in
                    guard let self else { return }
                    try? await self.noraVoice.speakText(
                        "screen check passed. hold command and shift, say "
                            + Self.firstRunRehearsalSpokenPhrase
                            + ", then let go."
                    )
                    await self
                        .waitForSpeechPlaybackToFinishOrCancellation()
                }
            )
            let didComplete = self.persistFirstRunCompletionIfProven(
                productionScreenAnswerExerciseSucceeded: true,
                rehearsalResult: rehearsalResult
            )
            if didComplete {
                self.showVisibleResponse(
                    "Setup complete. Ace is ready."
                )
                try? await self.noraVoice.speakText(
                    "setup complete. ace is ready."
                )
                self.appendRouteReceipt(
                    "ONBOARDING Finish Setup proof completed"
                )
            } else if !Task.isCancelled {
                self.showVisibleResponse(
                    "Finish Setup is still waiting for the push-to-talk proof. Try again from the Ace menu."
                )
                self.appendRouteReceipt(
                    "ONBOARDING Finish Setup proof remains pending"
                )
            }
        }
    }

    /// Ends the tour — called by "stop" and by any new utterance.
    func cancelFirstRunTourIfRunning(forceImmediate: Bool = false) {
        cancelStartActivation()
        // The hold the rehearsal asked for must not end the rehearsal.
        guard forceImmediate || !isInsideRehearsalGrace else { return }
        if let proofTask = firstRunCompletionProofTask {
            proofTask.cancel()
            firstRunCompletionProofTask = nil
            appendRouteReceipt("ONBOARDING Finish Setup proof cancelled")
        }
        // Release the rehearsal independently of the full tour. Finish Setup
        // owns this same continuation without owning `firstRunTourTask`.
        if let pendingContinuation =
            firstRunRehearsalContinuation {
            firstRunRehearsalOverallTimeoutTask?.cancel()
            firstRunRehearsalOverallTimeoutTask = nil
            firstRunRehearsalWaitIdentifier = nil
            isAwaitingFirstRunRehearsal = false
            firstRunRehearsalContinuation = nil
            resetFirstRunRehearsalAttemptForRetry()
            pendingContinuation.resume(returning: .cancelled)
        }
        guard let runningTour = firstRunTourTask else { return }
        runningTour.cancel()
        firstRunTourTask = nil
        endFirstRunTourTradingDemoIfOwned(
            reason: "cancelled"
        )
        if firstRunTourRequiresOnboardingHotkeyProof {
            appendRouteReceipt(
                "ONBOARDING remains incomplete — rehearsal tour cancelled")
        }
        firstRunTourRequiresOnboardingHotkeyProof = false

        let stage = AceStageOverlayController.shared
        if forceImmediate {
            rehearsalGraceDeadline = nil
            stage.dismiss()
            clearDetectedElementLocation()
            appendRouteReceipt("TOUR stopped immediately — stealth boundary")
            return
        }

        // The show CONCEDES instead of vanishing. Both live runs of the buyer
        // walkthrough ended the same way: the buyer tried the hotkey the moment
        // the show taught it, and the whole spectacle blinked out mid-sentence —
        // which reads as a crash, when it's actually the show's mission
        // accomplished early. So: stop talking immediately (the buyer's answer
        // owns the voice now), fade the constellation, fly the gem home to the
        // menu bar, and only then take the stage down. No speech — Ace is
        // already mid-conversation with them.
        appendRouteReceipt("TOUR conceded to a live utterance — gem heading home")
        Task { @MainActor in
            withAnimation(.easeOut(duration: 0.5)) { stage.model.constellationOpacity = 0 }
            if let menuBarIconLocation = MenuBarPanelManager.shared?.statusItemCenterInAppKitCoordinates(),
               stage.model.gemLocation != nil {
                let concedeFlight = stage.model.flyGem(to: menuBarIconLocation)
                try? await Task.sleep(for: .milliseconds(Int(concedeFlight * 1000) + 100))
                withAnimation(.easeIn(duration: 0.4)) { stage.model.gemScale = 0.02 }
                try? await Task.sleep(for: .milliseconds(450))
            }
            stage.dismiss()
        }
        clearDetectedElementLocation()
    }

    /// Speaks one line of the setup window out loud. Narration needs no
    /// permission — only listening does — so Ace can talk a buyer through setup
    /// before the microphone has ever been granted, which also demos the voice
    /// they are about to rely on.
    func speakSetupNarration(_ line: String) {
        guard !stealthMode.isActive, !StealthVisibilityGate.shared.isActive else { return }
        Task { try? await noraVoice.speakText(line) }
    }

    /// Setup's slow poll after the owner installs/downloads voice components.
    /// Kept here because NoraVoice is intentionally private to the one-mouth
    /// coordinator.
    func recheckVoiceReadinessForSetup() {
        guard AceLicense.shared.admits(.onboarding),
              !stealthMode.isActive,
              !StealthVisibilityGate.shared.isActive else { return }
        noraVoice.recheckVoiceAssetForSetup()
    }

    /// Wires the single Private Mode chord. Caps-on Shift+Z enters when needed
    /// and owns one private read/click operation while the wall stays raised.
    private func bindPrivateModeTriggers() {
        stealthAnswerCancellable = globalPushToTalkShortcutMonitor
            .stealthAnswerTriggerPublisher
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink { [weak self] _ in
                self?.handlePrivateModeReadShortcut()
            }
    }

    private func handlePrivateModeReadShortcut() {
        if !stealthMode.isActive {
            guard AceLicense.shared.admits(.privateModeEntry) else {
                globalPushToTalkShortcutMonitor
                    .resolvePrivateModeEntryRequest()
                appendRouteReceipt(
                    "STEALTH enter/read refused reason=unlicensed"
                )
                return
            }
            appendRouteReceipt("STEALTH enter via read chord")
            enterStealthMode(silently: true)
        }
        guard stealthMode.isActive else {
            globalPushToTalkShortcutMonitor
                .resolvePrivateModeEntryRequest()
            return
        }
        stealthAnswerVisibleQuestion()
    }

    /// Qwen receives on-device OCR rather than image pixels, and its transport
    /// is already grammar-constrained to the local pointing JSON envelope.
    /// Giving it the remote providers' `[POINT:...]` contract at the same time
    /// created two contradictory output formats and let it point at a question
    /// box before it had solved the question. Keep solving and coordinate
    /// selection ordered explicitly for the local lane.
    private static func privateModeAnswerSystemPrompt(
        for provider: BrainCLI
    ) -> String {
        switch provider {
        case .qwen:
            return """
            Solve exactly one visible single-answer multiple-choice question from private on-device OCR. If it requires multiple selections, return no final answer target.

            Follow this order before giving the final answer:
            1. Reconstruct the complete question from the OCR text.
            2. Determine the correct answer from subject knowledge. Compare every listed option and double-check the governing definition, calculation, or fact.
            3. Explain the reasoning needed to distinguish the answer from the distractors.
            4. End with exactly one final line: FINAL_ANSWER: <option letter or number>

            Never choose or copy coordinates; app code maps the final option identifier to the exact OCR option box and never uses the question's coordinates. Do not claim any click occurred. Your temporary reasoning is neither spoken nor persisted.
            """
        case .codex:
            return """
            Inspect every attached display for a visible single-answer multiple-choice question, regardless of browser, app or focused window. Select the first fully visible unanswered question in display order, then top to bottom. Ignore any partial neighboring question. Reconstruct the selected question, determine the correct answer, compare every option directly beneath it, and double-check the governing definition, calculation, or fact. If one complete question and its full option set are readable, do not reject it merely because part of another question is visible. If the question says select all, choose all, multiple answers, or otherwise requires more than one selection, set has_point false; one gesture may never silently reduce it to one answer. Return the one JSON object required by the native output schema. Set spoken_response to an empty string and label to "answer"; neither field is displayed in Private Mode. For a supported answer, set has_point true and put x/y at the clickable center of that answer control in the attached image's pixel space; copy the exact capture UUID and display ID from the image label. The point must be inside an answer box, never on question text. Use has_point false when there is no complete readable single-answer question with a determinable answer. App code owns every input event.
            """
        case .claude:
            return """
            Inspect every attached display for a visible single-answer multiple-choice question, regardless of browser, app or focused window. Select the first fully visible unanswered question in display order, then top to bottom. Ignore any partial neighboring question. Reconstruct the selected question, determine the correct answer, compare every option directly beneath it, and double-check the governing definition, calculation, or fact. If one complete question and its full option set are readable, do not reject it merely because part of another question is visible. If the question says select all, choose all, multiple answers, or otherwise requires more than one selection, output exactly [POINT:none]; one gesture may never silently reduce it to one answer. Then output ONLY one tag at the CLICKABLE center of that answer control: [POINT:capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;x=<pixel x>;y=<pixel y>;confidence=<0 to 1>;label=answer]. Coordinates use that exact image's pixel space. The point must be inside one of the answer boxes, never on question text or a neighboring question. Never omit or alter either identity. If no complete readable single-answer question has a determinable answer, output exactly [POINT:none]. Output nothing else. App code owns every input event.
            """
        }
    }


    /// Stealth: one Caps-on Shift+Z reads one multiple-choice question and
    /// completes one display-coordinate answer click without an AX target gate.
    private func stealthAnswerVisibleQuestion() {
        guard stealthMode.isActive else { return }
        // A press that lands while the previous read is still thinking is
        // dropped on purpose — but dropping it WITHOUT a receipt is how a
        // 45-second brain call reads as a dead chord. The owner pressed it;
        // the log has to be able to say what happened to that press.
        guard stealthAnswerTask == nil else {
            appendRouteReceipt("PRIVATE-MODE read ignored — a read is already in flight")
            return
        }
        // Receipts, deliberately contentless: a mode that captures the screen and
        // may later move the mouse has to be auditable, and "what did it do"
        // must be answerable without recording WHAT WAS ON SCREEN. So the request,
        // the refusal reason, and the click coordinates are logged — never the
        // question, the answer, or the image.
        appendRouteReceipt("PRIVATE-MODE read requested")
        let sessionIdentifier = UUID()
        stealthAnswerSessionIdentifier = sessionIdentifier
        stealthAnswerTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let providerTurn = AceProviderTurn.capture()
            defer {
                if self.stealthAnswerSessionIdentifier == sessionIdentifier {
                    self.stealthAnswerDeadlineTask?.cancel()
                    self.stealthAnswerDeadlineTask = nil
                    self.stealthAnswerTask = nil
                    self.stealthAnswerSessionIdentifier = nil
                }
            }
            self.stealthAnswerDeadlineTask?.cancel()
            self.stealthAnswerDeadlineTask = Task { @MainActor [weak self] in
                try? await Task.sleep(
                    for: .seconds(
                        InteractiveLatencyPolicy.privateModeHardFailureDeadline
                    )
                )
                guard !Task.isCancelled,
                      let self,
                      self.stealthAnswerSessionIdentifier
                        == sessionIdentifier else {
                    return
                }
                self.privateModeActivityStatus =
                    "The answer hit Ace's \(Int(InteractiveLatencyPolicy.privateModeHardFailureDeadline))-second limit; nothing was clicked."
                self.appendRouteReceipt(
                    "PRIVATE-MODE hard-deadline="
                        + "\(Int(InteractiveLatencyPolicy.privateModeHardFailureDeadline))s"
                        + " — no click sent"
                )
                self.privateModeClaudeAPI.cancelInFlightAnswer()
                self.stealthAnswerTask?.cancel()
            }

            let capturedContext = PrivateModePolicy.currentContext()
            guard let captureCapability = PrivateModePolicy.makeVisibleDisplaysCapability(
                sessionIdentifier: sessionIdentifier,
                context: capturedContext
            ) else {
                self.privateModeActivityStatus = PrivateModePolicy.decision(
                    for: capturedContext, requireFocusedWindow: false
                ).userFacingReason
                self.appendRouteReceipt("PRIVATE-MODE refused before capture: protected app or field")
                return
            }

            let captures: [CompanionScreenCapture]
            do {
                captures = try await CompanionScreenCaptureUtility.captureAllScreensAsJPEG(
                    onlyCursorScreen: false,
                    excludingSensitiveApplications: true,
                    privateModeCapability: captureCapability
                )
            } catch {
                guard !Task.isCancelled, self.stealthMode.isActive,
                      self.stealthAnswerSessionIdentifier == sessionIdentifier else { return }
                let failure = PrivateModeCaptureFailure.classified(error)
                self.privateModeActivityStatus = failure.userFacingReason
                self.appendRouteReceipt(
                    "PRIVATE-MODE capture failed reason=\(failure.rawValue) "
                        + "code=\((error as NSError).code) — no click sent"
                )
                return
            }
            guard !captures.isEmpty,
                  captures.allSatisfy({ $0.privateModeBinding?.sessionIdentifier == sessionIdentifier }) else {
                self.privateModeActivityStatus = PrivateModeCaptureFailure.invalidBinding.userFacingReason
                self.appendRouteReceipt("PRIVATE-MODE capture failed reason=invalid-binding — no click sent")
                return
            }
            for capture in captures {
                self.appendRouteReceipt(
                    "PRIVATE-MODE capture ready image="
                        + "\(capture.screenshotWidthInPixels)x\(capture.screenshotHeightInPixels)"
                        + " display=\(capture.displayIdentifier) scope=visible-displays")
            }
            self.lastPrivateModeCaptureAt = Date()
            guard !Task.isCancelled, self.stealthMode.isActive else { return }
            let labeledImages = captures.map { capture in
                (data: capture.imageData,
                 label: capture.label + " (image dimensions: \(capture.screenshotWidthInPixels)x\(capture.screenshotHeightInPixels) pixels)")
            }
            let systemPrompt = Self.privateModeAnswerSystemPrompt(for: providerTurn.provider)
            let userPrompt = "identify the correct answer location."
            self.lastPrivateModeRemoteProcessingAt = Date()
            self.privateModeActivityStatus =
                "Processing the visible displays remotely. No prompt or "
                + "answer is logged; its private temporary image is deleted "
                + "when this request finishes and purged on the next launch "
                + "after a hard kill."
            let response: String
            do {
                (response, _) = try await self.privateModeClaudeAPI.analyzeImageStreaming(
                    images: labeledImages,
                    systemPrompt: systemPrompt,
                    conversationHistory: [],
                    userPrompt: userPrompt,
                    responseFormat: .localMultipleChoicePointing,
                    providerTurn: providerTurn,
                    interactiveLatencyProfile:
                        InteractiveProviderLatencyPolicy.profile(
                            for: .privateMode,
                            includesScreenContext: true
                        ),
                    persistLogs: false,
                    onTextChunk: { _ in }
                )
            } catch {
                // A deadline or owner exit already owns its terminal status.
                guard !Task.isCancelled,
                      self.stealthAnswerSessionIdentifier == sessionIdentifier,
                      self.stealthMode.isActive else { return }
                let cause = AceReasoningRecoveryPolicy.failureCause(
                    errorTypeName: String(describing: type(of: error)),
                    errorDescription: error.localizedDescription
                )
                self.privateModeActivityStatus =
                    "Private answer failed because \(cause). Nothing was clicked."
                self.appendRouteReceipt(
                    "PRIVATE-MODE brain call failed provider=\(providerTurn.provider.rawValue) reason=\(cause) — no click sent"
                )
                return
            }
            guard !Task.isCancelled, self.stealthMode.isActive else {
                self.appendRouteReceipt("PRIVATE-MODE abandoned — stealth ended before the click")
                return
            }
            let parseResult = Self.parsePointingCoordinates(
                from: response,
                captures: captures
            )
            guard let coordinate = parseResult.coordinate,
                  let captureIdentity = parseResult.captureIdentity,
                  let capturedScreen = captures.first(where: { $0.identity == captureIdentity }),
                  let captureBinding = capturedScreen.privateModeBinding else {
                self.privateModeActivityStatus = "No answer could be identified; nothing was clicked."
                let outcome: String
                if parseResult.rejectionReason != nil {
                    outcome = "decode-rejected"
                } else if parseResult.elementLabel == "none" {
                    outcome = "model-none"
                } else {
                    outcome = "capture-identity-mismatch"
                }
                self.appendRouteReceipt(
                    "PRIVATE-MODE no answer identified outcome=\(outcome) "
                        + "provider=\(providerTurn.provider.rawValue) "
                        + "reason=\(parseResult.rejectionReason ?? outcome) — nothing clicked"
                )
                return
            }
            guard let cg = PrivateModePolicy.resolvedCandidatePoint(
                      imagePoint: coordinate,
                      binding: captureBinding
                  ) else {
                self.privateModeActivityStatus =
                    "The proposed point was outside the captured display; nothing was clicked."
                self.appendRouteReceipt(
                    "PRIVATE-MODE candidate rejected — outside captured display")
                return
            }
            guard !Task.isCancelled, self.stealthMode.isActive else { return }

            let currentContext = PrivateModePolicy.currentContext()
            let clickDecision = PrivateModePolicy.decision(
                for: currentContext, requireFocusedWindow: false
            )
            guard clickDecision.isAllowed else {
                self.privateModeActivityStatus = clickDecision.userFacingReason
                self.appendRouteReceipt("PRIVATE-MODE refused before click: \(clickDecision.userFacingReason)")
                return
            }
            let currentDisplayTopology =
                PrivateModePolicy.currentDisplayTopology()
            guard PrivateModePolicy.captureBindingIsCurrent(
                captureBinding,
                context: currentContext,
                displayTopology: currentDisplayTopology
            ) else {
                self.privateModeActivityStatus =
                    "The display layout changed after capture; no click was sent."
                self.appendRouteReceipt(
                    "PRIVATE-MODE refused before staging: display layout changed")
                return
            }
            guard let pointerAtStaging = currentPrivateModePointerSnapshot() else {
                self.privateModeActivityStatus =
                    "The pointer state could not be verified after capture; no click was sent."
                self.appendRouteReceipt(
                    "PRIVATE-MODE refused before staging: pointer snapshot unavailable")
                return
            }
            guard let pointerAfterAim = self.movePointerAtCG(
                cg,
                captureBinding: captureBinding,
                expectedPointerState: pointerAtStaging,
                sessionIdentifier: sessionIdentifier
            ) else {
                self.privateModeActivityStatus =
                    "The pointer, display, or Private Mode session changed before aim; nothing was clicked."
                self.appendRouteReceipt(
                    "PRIVATE-MODE answer blocked at aim boundary (\(Int(cg.x)),\(Int(cg.y)))")
                return
            }
            guard await self.clickAtCG(
                cg,
                captureBinding: captureBinding,
                expectedPointerState: pointerAfterAim,
                sessionIdentifier: sessionIdentifier
            ) else {
                self.privateModeActivityStatus =
                    "The click could not finish because the pointer, display, or Private Mode session changed. It was not retried."
                self.appendRouteReceipt(
                    "PRIVATE-MODE answer blocked at click boundary")
                return
            }
            self.appendRouteReceipt(
                "PRIVATE-MODE answer click delivered "
                    + "(\(Int(cg.x)),\(Int(cg.y)))")
            self.lastPrivateModeSyntheticClickAt = Date()
            self.privateModeActivityStatus =
                "Mouse click sent to the captured screen coordinates. This does not verify the app's response."
        }
    }

    // MARK: - Stealth (ghost) mode

    /// Enter ghost mode: stand down every lane, hide every visible surface (gem,
    /// cursor, menu-bar icon), suppress Nora, and keep the microphone closed.
    /// Privacy always wins: active or partially-started meeting capture is
    /// synchronously stopped and its unsaved transcript is discarded instead
    /// of vetoing this transition.
    private func enterStealthMode(silently: Bool = false) {
        stealthVoiceFragmentDeadlineTask?.cancel()
        stealthVoiceFragmentDeadlineTask = nil
        stealthVoiceFragmentAssembler.reset()
        guard !stealthMode.isActive else {
            // Already-active is also a fully resolved privacy state.
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }

        // Voice entry may be refused while the silent exit control is already
        // known dead. A chord-delivered entry is different: its event-tap
        // transition already occurred, so privacy intent wins even if macOS
        // invalidates the tap before the main queue handles it.
        guard silently
                || globalPushToTalkShortcutMonitor.isEventTapOperational else {
            privateModeActivityStatus =
                "Private Mode needs Accessibility so its silent exit key can work."
            appendRouteReceipt("STEALTH refused — silent exit hotkey is unavailable")
            Task {
                try? await noraVoice.speakText(
                    "private mode needs accessibility before its exit key can work.")
            }
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }
        guard let stealthEntryEpoch = stealthMode.beginEntry() else {
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }
        stealthEntryTransitionInProgress = true
        defer { stealthEntryTransitionInProgress = false }

        // Voice and panel entry raise the same process/external latch as the Z
        // callback before cancelling work on the main actor. For a Z entry this
        // is idempotent; every route closes the direct-effect race before any
        // asynchronous teardown begins.
        let entryReceiptPublished =
            StealthEntryLatch.shared.raiseSynchronously()
        CodexModelCapabilityPreflight.shared.invalidate(
            reason: .privateMode
        )
        cancelAceHQDispatchSynchronouslyForStealth()
        if !entryReceiptPublished {
            appendRouteReceipt(
                "STEALTH entry latch raised; external request receipt unavailable")
        }
        discardPendingDirectEffectConfirmations()
        cancelOnboardingPromptStream()
        cancelOnboardingDemoInteraction()
        screenContentRelaunchTask?.cancel()

        shouldRestoreOverlayAfterStealth = isOverlayVisible
        shouldResumeAutomationRevalidationAfterStealth =
            hasCompletedOnboarding
                && InstallLocation.isRunningFromAllowedStableLocation
                && permissionWarmup.isRevalidatingAutomation
        shouldResumeScreenContentProofAfterStealth =
            hasCompletedOnboarding
                && InstallLocation.isRunningFromAllowedStableLocation
                && isRequestingScreenContent

        // Phase one cannot fail and performs no cross-process wait. From this
        // line onward a delayed window or direct-effect callback is contained.
        StealthVisibilityGate.shared.activateLocalWall()
        // A visible response can contain a local-only inbox preview. Clear its
        // cache synchronously with the visibility wall so exiting Stealth can
        // never restore text that was on screen before entry.
        visibleResponseHideTask?.cancel()
        visibleResponseHideTask = nil
        visibleResponseGeneration = UUID()
        visibleResponseText = ""
        stealthExitOnlyCapture.enterStealth(epoch: UUID())
        nativeLocationManager?.cancel()
        nativeLocationManager = nil
        localWeatherSessionContext.clear()
        goldContextBundle.purgeVolatileForStealth()
        goldContextState.pendingRelaunchRecovery = nil
        deferredDirectTerminals.removeAll(keepingCapacity: false)
        deferredGoldTerminals.removeAll(keepingCapacity: false)
        deferredGoldAnswerTerminals.removeAll(keepingCapacity: false)
        // A pre-dispatch tuple whose save lost the Private Mode entry race belongs to the exact
        // interrupted-work recovery path. Retaining its prose would replay a
        // conflicting terminal against the immutable interrupted.stealth truth.
        AceHQPreDispatchStealthPurge.purge(
            &deferredAceHQPreDispatchTerminals
        )
        deferredAppActionTerminal = nil
        appActionWorkCorrelationIdentifier = nil
        appActionVolatileTurnIdentifier = nil
        appActionUsesVolatileTurnContext = false
        recentOwnerWorkStore = RecentOwnerWorkStore()
        foregroundNavigationContext = GoldForegroundContext()
        nativeConversationContext.clearSession()
        receiptOnlyWorkIDBySourceCorrelationID.removeAll(
            keepingCapacity: false
        )
        activeContextualOwnerRequest = nil
        activeOwnerTurnContext = nil
        ownerTurnLifecycle.clear()
        activeRoutingSessionID = nil
        activeRoutingTurnID = nil
        activeRoutingCorrelationID = nil
        globalPushToTalkShortcutMonitor.privateModeIsActive = true
        stealthActive = true
        finishWaveformTurn(reason: .privateMode)
        laneManager.enterStealth()
        overlayWindowManager.setStealthModeActive(true)
        isOverlayVisible = false

        // Close capture/audio delivery before any filesystem or helper wait.
        partnerResponseGeneration = UUID()
        partnerListeningStartTask?.cancel()
        partnerListeningStartTask = nil
        partnerModeController?
            .suspendSynchronouslyForStealth()
        buddyDictationManager.cancelCurrentDictationForStealth()
        noraVoice.isSuppressed = true
        meetingNotetaker.suspendSynchronouslyForStealth()
        permissionWarmup.suspendForStealth()
        failCurrentScreenContentProofRequest()

        // A distinct owner-intent receipt keeps the wall raised across crash,
        // updater relaunch, force quit, and manual reopen. Failure degrades
        // recovery but never lowers the already-active local wall.
        let durableIntentRecorded = StealthDurableIntent.record()

        // Setup is never allowed to veto the event-tap privacy chord. An Apple
        // consent surface already owned by macOS may finish, but Ace cannot
        // present, listen, speak, capture, or advance another setup step.
        backgroundDispatchGeneration = UUID()
        pendingBackgroundExecutions.removeAll()
        backgroundQueueDrainTask?.cancel()
        backgroundQueueDrainTask = nil
        backgroundAgent.suspendForStealth()
        silverBackgroundAgent.suspendForStealth()
        appActionPlanningGeneration = UUID()
        appActionPlanningTask?.cancel()
        appActionPlanningTask = nil
        appActionReviewExpiryTask?.cancel()
        appActionReviewExpiryTask = nil
        appActionReview = nil
        appActionBroker.suspendForStealth()
        pendingGoldClarification = nil
        pendingPartnerClarification = nil
        clearPendingAppleMailDraftRequest()
        clearPendingAppleMessagesRequest()
        claudeAPI.cancelInFlightAnswer()
        testEmailGeneration = UUID()
        testEmailTask?.cancel()
        testEmailTask = nil
        isPreparingTestEmailSend = false
        if let process = testEmailProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        testEmailProcess = nil
        recentEmailRead = nil
        emailReadGeneration = UUID()
        emailReadTask?.cancel()
        emailReadTask = nil
        if let process = emailReadProcess, process.isRunning {
            RunningProcessBox.terminateProcessTree(process)
        }
        emailReadProcess = nil
        backgroundTaskActive = false

        // Stand down anything in flight so nothing surfaces after we disappear.
        goldAnswerInterruption = .stealth
        currentResponseTask?.cancel()
        currentResponseTask = nil
        permissionWarmupTask?.cancel()
        permissionWarmupTask = nil
        pendingKeyboardShortcutStartTask?.cancel()
        pendingKeyboardShortcutStartTask = nil
        stopScanTheater()
        cancelWalkthroughIfRunning()
        explainAppsChoreographyTask?.cancel()
        explainAppsChoreographyTask = nil
        cancelFirstRunTourIfRunning(forceImmediate: true)
        if tradingLane.isActive {
            tradingLane.deactivate()
            tradingModeActive = false
            tradingDataStatus = .inactive
        }
        // The build lane is KILLED, not suspended. A standing task can wait for
        // the wall to come down; a job holding full machine authority cannot be
        // allowed to keep writing to this Mac inside a mode whose whole purpose
        // is that Ace is doing nothing observable. Synchronous, before Stealth
        // reports active, and it never vetoes the transition.
        workflowRuntime.suspendSynchronouslyForStealth()
        // Suspended, not cancelled — due work runs on the first tick after
        // explicit exit.
        standingTaskRuntime.suspend()
        morningLinkBriefRuntime.suspend()

        // Phase two coordinates detached wrappers. A timeout or marker failure
        // is a degraded Stealth state, never an instruction to reveal Ace.
        let externalStatus =
            StealthVisibilityGate.shared.secureExternalBoundary(timeout: 2)
        stealthHotkeyWasDegraded =
            !globalPushToTalkShortcutMonitor.isEventTapOperational
        startStealthHotkeyHealthMonitor()
        if !durableIntentRecorded {
            privateModeActivityStatus =
                "Private Mode is active, but crash recovery could not be sealed."
        } else if !externalStatus.isSecured {
            privateModeActivityStatus =
                "Private Mode is active; detached-effect protection is degraded."
        } else if stealthHotkeyWasDegraded {
            privateModeActivityStatus =
                "Private Mode is active; restoring the silent exit key."
        }
        guard stealthMode.completeEntry(epoch: stealthEntryEpoch) else {
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            appendRouteReceipt(
                "STEALTH entry epoch changed; privacy wall remains raised"
            )
            return
        }
        appendRouteReceipt(
            "STEALTH on durable=\(durableIntentRecorded)"
                + " external=\(String(describing: externalStatus))"
                + " hotkey=\(!stealthHotkeyWasDegraded)"
        )
        // Private Mode is now one process and one privacy gate. Keep the
        // already-quiesced Ace process alive so the normal PTT event tap can
        // admit only its isolated local exit recognizer. No login item, second
        // Accessibility identity, XPC endpoint, or helper handoff is involved.
        globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
    }

    /// Leave ghost mode: unsuppress the voice, restore the overlay if it was up,
    /// and let the menu-bar icon reappear. Exit is deliberately silent: even a
    /// short acknowledgement would publish an Ace speech event and leave a
    /// durable timestamped trace of an otherwise private session.
    /// Opening Ace is an explicit owner request to restore its visible UI.
    /// Use the same exit transaction as speech so recovery also works when
    /// recognition failed. A recovered minimal runtime relaunches itself.
    @discardableResult
    func exitPrivateModeForManualOpen() -> Bool {
        if stealthMode.isActive { exitStealthMode() }
        return !stealthMode.isActive && !stealthActive
            && !StealthEntryLatch.shared.isRaised
            && !StealthVisibilityGate.shared.isActive
    }

    private func exitStealthMode() {
        // Past the guard, not before it: a stray exit trigger while not stealthed
        // used to clear the lane manager's stealth flag on its own, leaving the
        // two halves of the mode disagreeing about whether Ace is a ghost.
        guard stealthMode.isActive else {
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }
        guard !stealthExitTransitionInProgress else { return }
        guard let stealthExitEpoch = stealthMode.beginExit() else {
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }
        stealthExitTransitionInProgress = true
        guard StealthDurableIntent.clear() else {
            _ = stealthMode.cancelExit(epoch: stealthExitEpoch)
            stealthExitTransitionInProgress = false
            privateModeActivityStatus =
                "Private Mode stayed active because its crash-recovery seal could not be cleared."
            appendRouteReceipt(
                "STEALTH exit blocked — durable owner intent could not be cleared"
            )
            globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
            return
        }
        _ = AceHQPendingDispatchStore.suspendCurrent(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        stealthExitOnlyCapture.leaveStealth()
        // Stop repair before launching a replacement process. A queued repair
        // tick must not recreate the intent after the owner committed exit and
        // race the replacement's final launch admission probe.
        stealthHotkeyHealthTimer?.invalidate()
        stealthHotkeyHealthTimer = nil
        if restoredDurableStealthAtLaunch {
            let retiringMarkerRemoved = StealthVisibilityGate.shared
                .retireExternalMarkerForProcessExit()
            appendRouteReceipt(
                "STEALTH recovered exit retiring live marker="
                    + (retiringMarkerRemoved ? "removed" : "not-owned")
            )
            // The replacement cannot become a second normal runtime while this
            // recovered process still owns the singleton lease. Release only
            // after durable intent is cleared and this process's live receipt
            // is removed or proven to belong to another active process.
            AceRuntimeInstanceLock.shared.release()
            relaunchNormalRuntimeAfterRecoveredStealthExit(
                exitEpoch: stealthExitEpoch
            )
            return
        }
        stealthAnswerTask?.cancel()
        stealthAnswerTask = nil
        stealthAnswerDeadlineTask?.cancel()
        stealthAnswerDeadlineTask = nil
        stealthAnswerSessionIdentifier = nil
        privateModeClaudeAPI.cancelInFlightAnswer()
        claudeAPI.cancelInFlightAnswer()
        laneManager.exitStealth()
        guard stealthMode.completeExit(epoch: stealthExitEpoch) else {
            appendRouteReceipt(
                "STEALTH exit epoch changed; recovery remains closed"
            )
            return
        }
        StealthVisibilityGate.shared.deactivate()
        let postStealthLoad =
            AceConversationHistory.loadBundleForRelaunch(
                interruptionCause: .stealth,
                preservingRunningWorkCorrelationIdentifiers:
                    GoldContextRuntimeState
                        .pendingAceHQWorkIdentifiers(),
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        goldContextState = GoldContextRuntimeState(
            bundle: postStealthLoad.bundle,
            pendingRelaunchRecovery:
                postStealthLoad.pendingRecovery
        )
        // Private Mode intentionally purges all volatile terminal prose. The
        // durable reload above converts every still-running work record into
        // one content-free interrupted.stealth result. Re-project that exact
        // durable truth immediately so the visible receipt cannot remain
        // Processing until Ace relaunches or the owner submits another turn.
        refreshBuyerWorkReceiptsFromDurableContext()
        discardAceHQRetryIfDurablyTerminal()
        globalPushToTalkShortcutMonitor.privateModeIsActive = false
        stealthActive = false
        overlayWindowManager.setStealthModeActive(false)
        noraVoice.isSuppressed = false

        guard AceLicense.shared.admits(.backgroundResume) else {
            shouldRestoreOverlayAfterStealth = false
            shouldResumeAutomationRevalidationAfterStealth = false
            shouldResumeScreenContentProofAfterStealth = false
            quiescePremiumRuntimeForEntitlementLoss(
                forceRecoveryStop: true
            )
            appendRouteReceipt(
                "STEALTH off recovery-only — entitlement remains closed"
            )
            stealthExitTransitionInProgress = false
            globalPushToTalkShortcutMonitor
                .resolvePrivateModeEntryRequest()
            return
        }

        // If access was restored while the privacy wall was raised, its
        // observer deliberately left every lane quiesced. Apply that admission
        // only now, after the durable and process-wide walls are down. The
        // ordinary Stealth resumes below are idempotent for already-open lanes.
        openPremiumRuntimeIfEntitled()
        meetingNotetaker.resumeAfterStealth()
        if shouldRestoreOverlayAfterStealth && isBlackLabelCursorEnabled {
            overlayWindowManager.hasShownOverlayBefore = true
            isOverlayVisible = overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            )
        }
        shouldRestoreOverlayAfterStealth = false
        standingTaskRuntime.resume()
        morningLinkBriefRuntime.resume()
        // Restores the lane's ability to accept a NEW job only. The killed one
        // is never resurrected — authority does not survive the wall.
        workflowRuntime.resumeAfterStealth()
        backgroundAgent.resumeAfterStealth()
        silverBackgroundAgent.resumeAfterStealth()
        _ = appActionBroker.resumeAfterStealth()
        _ = retryDeferredDurableTerminalsIfSafe()
        appendRouteReceipt("STEALTH off")
        if shouldResumeAutomationRevalidationAfterStealth
            || shouldResumeScreenContentProofAfterStealth {
            shouldResumeAutomationRevalidationAfterStealth = false
            shouldResumeScreenContentProofAfterStealth = false
            resumePermissionRevalidationAfterStealth()
        } else {
            SetupWalkthrough.shared.resumeAfterStealth(
                companionManager: self
            )
        }
        // Clear any stale entry serialization only after normal operation is restored.
        stealthExitTransitionInProgress = false
        globalPushToTalkShortcutMonitor.resolvePrivateModeEntryRequest()
    }

    /// A crash-recovery launch deliberately initialized only the event-tap exit
    /// control. After the owner explicitly exits, start a fresh exact copy so
    /// the full runtime follows its normal one-time launch path.
    private func relaunchNormalRuntimeAfterRecoveredStealthExit(
        exitEpoch: UUID
    ) {
        let currentProcessIdentifier =
            ProcessInfo.processInfo.processIdentifier
        let bundleURL = Bundle.main.bundleURL.standardizedFileURL
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.createsNewApplicationInstance = true
        configuration.activates = true
        let relaunchRequest: Void = NSWorkspace.shared.openApplication(
            at: bundleURL,
            configuration: configuration
        ) { [weak self] launchedApplication, error in
            Task { @MainActor [weak self] in
                guard let self else { return }
                let launchedURL =
                    launchedApplication?.bundleURL?.standardizedFileURL
                guard error == nil,
                      let launchedApplication,
                      launchedApplication.processIdentifier
                          != currentProcessIdentifier,
                      launchedApplication.isTerminated == false,
                      launchedURL == bundleURL else {
                    let recovery =
                        RecoveredStealthRelaunchFailureRecovery.restore(
                            acquireRuntimeLease: {
                                AceRuntimeInstanceLock.shared.acquire()
                            },
                            recordDurableIntent: {
                                StealthDurableIntent.record()
                            },
                            secureExternalBoundary: {
                                StealthVisibilityGate.shared
                                    .secureExternalBoundary(timeout: 2)
                            }
                        )
                    guard case let .restored(
                        durableIntentRecorded,
                        externalBoundary
                    ) = recovery else {
                        self.appendRouteReceipt(
                            "STEALTH recovered exit relaunch callback failed "
                                + "after another Ace acquired the runtime lease"
                        )
                        self.globalPushToTalkShortcutMonitor
                            .resolvePrivateModeEntryRequest()
                        NSApp.terminate(nil)
                        return
                    }
                    _ = self.stealthMode.cancelExit(
                        epoch: exitEpoch
                    )
                    self.stealthExitTransitionInProgress = false
                    self.startStealthHotkeyHealthMonitor()
                    self.privateModeActivityStatus =
                        "Private Mode stayed active because the normal Ace process could not be relaunched."
                    self.appendRouteReceipt(
                        "STEALTH recovered exit relaunch failed; "
                            + "durable=\(durableIntentRecorded) "
                            + "external=\(String(describing: externalBoundary))"
                    )
                    self.globalPushToTalkShortcutMonitor
                        .resolvePrivateModeEntryRequest()
                    return
                }
                self.appendRouteReceipt(
                    "STEALTH recovered exit launched exact new pid="
                        + String(launchedApplication.processIdentifier)
                )
                self.globalPushToTalkShortcutMonitor
                    .resolvePrivateModeEntryRequest()
                NSApp.terminate(nil)
            }
        }
        _ = relaunchRequest
    }

    /// Stealth can interrupt either no-prompt launch proof. Restart both after
    /// the visibility wall is down and defer setup until their bounded verdict.
    /// Otherwise a healthy owner would see setup solely because Stealth
    /// correctly cancelled an in-flight check.
    private func resumePermissionRevalidationAfterStealth() {
        guard hasCompletedOnboarding,
              InstallLocation.isRunningFromAllowedStableLocation,
              !StealthVisibilityGate.shared.isActive else {
            SetupWalkthrough.shared.resumeAfterStealth(
                companionManager: self
            )
            return
        }

        permissionWarmup.beginNoninteractiveRevalidation()
        if CGPreflightScreenCaptureAccess() {
            requestScreenContentPermission()
        }
        Task { @MainActor [weak self] in
            guard let self else { return }
            for _ in 0..<150 {
                let automationIsPending =
                    self.permissionWarmup.isRevalidatingAutomation
                let screenContentIsPending =
                    self.isRequestingScreenContent
                guard automationIsPending || screenContentIsPending else {
                    break
                }
                do {
                    try await Task.sleep(for: .milliseconds(100))
                } catch {
                    return
                }
            }

            if self.permissionWarmup.isRevalidatingAutomation {
                self.permissionWarmup
                    .failCurrentNoninteractiveRevalidation()
            }
            if self.isRequestingScreenContent {
                self.failCurrentScreenContentProofRequest()
            }
            guard !StealthVisibilityGate.shared.isActive else {
                return
            }

            if AssistantAvailabilityPolicy.shouldShowPersistentGem(
                hasCompletedOnboarding:
                    self.hasCompletedOnboarding,
                cursorEnabled:
                    self.isBlackLabelCursorEnabled,
                stealthVisibilityBlocked:
                    StealthVisibilityGate.shared.isActive
                        || StealthEntryLatch.shared.isRaised,
                coreInteractionPermissionsReady:
                    self.hasAccessibilityPermission
                        && self.hasScreenRecordingPermission
                        && self.hasMicrophonePermission
                        && self.hasScreenContentPermission,
                appAutomationReady:
                    self.permissionWarmup.hasProvenAppAutomation
            ), !self.isOverlayVisible {
                self.overlayWindowManager.hasShownOverlayBefore = true
                self.isOverlayVisible =
                    self.overlayWindowManager.showOverlay(
                        onScreens: NSScreen.screens,
                        companionManager: self
                    )
            }
            if !self.allPermissionsGranted {
                self.appendRouteReceipt(
                    "PERMISSION-REVALIDATE post-stealth proof failed or timed out — guided retry required"
                )
                SetupWalkthrough.shared.resumeAfterStealth(
                    companionManager: self
                )
            }
        }
    }

    /// Accessibility can be revoked while Stealth is active, or macOS can
    /// invalidate the event-tap port. Privacy fails closed: remain hidden,
    /// continuously repair the silent owner control, and retry any degraded
    /// durable/external boundary. A hotkey fault is never permission to reveal,
    /// speak, capture, or resume work.
    private func startStealthHotkeyHealthMonitor() {
        stealthHotkeyHealthTimer?.invalidate()
        stealthHotkeyHealthTimer = Timer.scheduledTimer(
            withTimeInterval: 1,
            repeats: true
        ) { [weak self] _ in
            Task { @MainActor [weak self] in
                guard let self,
                      Self.stealthBoundaryRepairIsAllowed(
                        stealthIsActive: self.stealthMode.isActive,
                        exitTransitionInProgress:
                      self.stealthExitTransitionInProgress
                      ) else {
                    return
                }

                self.hasAccessibilityPermission =
                    WindowPositionManager.hasAccessibilityPermission()
                if !StealthDurableIntent.isRecorded() {
                    let restored = StealthDurableIntent.record()
                    if restored {
                        self.appendRouteReceipt(
                            "STEALTH durable owner intent repair succeeded"
                        )
                    }
                }

                if !StealthVisibilityGate.shared
                        .externalBoundaryStatus.isSecured {
                    _ = StealthVisibilityGate.shared
                        .secureExternalBoundary(timeout: 0.05)
                }

                let hotkeyIsOperational =
                    self.globalPushToTalkShortcutMonitor
                        .repairEventTapIfNeeded()
                if !hotkeyIsOperational {
                    if !self.stealthHotkeyWasDegraded {
                        let repairReason = self.hasAccessibilityPermission
                            ? "the event tap was lost"
                            : "Accessibility permission is off"
                        self.appendRouteReceipt(
                            "STEALTH silent exit hotkey unavailable (\(repairReason)); wall remains active"
                        )
                    }
                    self.stealthHotkeyWasDegraded = true
                    self.privateModeActivityStatus = self.hasAccessibilityPermission
                        ? "Private Mode remains active while Ace restores the silent exit key."
                        : "Private Mode remains active; enable Accessibility to restore the silent exit key."
                } else if self.stealthHotkeyWasDegraded {
                    self.stealthHotkeyWasDegraded = false
                    self.privateModeActivityStatus =
                        "Private Mode is active; the silent exit key is restored."
                    self.appendRouteReceipt(
                        "STEALTH silent exit hotkey restored"
                    )
                }
            }
        }
    }

    /// "find/where is/locate <X>". If X resolves to an installed or running
    /// APP, activate it in software — instant, cannot mislocate ("find the
    /// obsidian app" once pointed at linkedin's dock icon via the vision
    /// path). Everything else falls through to the vision locate as before.
    // Stops at the FIRST sentence terminator, not end-of-string — "find the
    // business app. nothing counts unless…" must yield "business", never the
    // whole trailing sentence (which can match no app and skip the fast path).
    private static let locateTargetExtractionPattern =
        #"(?i)(?:find|locate|where\s+is|where's|highlight|point\s+(?:at|to|out)|show\s+me)\s+(?:the\s+|my\s+)?(.+?)(?:\s+app(?:lication)?)?\s*(?:[.!?,;]|$)"#

    private func extractLocateTarget(_ text: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: Self.locateTargetExtractionPattern),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)),
              let captureRange = Range(match.range(at: 1), in: text) else { return nil }
        let target = String(text[captureRange]).trimmingCharacters(in: .whitespacesAndNewlines)
        return target.isEmpty ? nil : target
    }

    /// "don't open / do not open / without opening / just find / just show"
    /// — an explicit instruction that locate must NOT activate anything.
    private static let noOpenPattern =
        #"(?i)\b(?:don'?t\s+open|do\s+not\s+open|without\s+opening|just\s+(?:find|locate|show))\b"#

    /// Executes only the app candidate frozen at admission. This method
    /// accepts no instruction text, consults no parser or Red route, and its
    /// actual effect outcome closes the admitted lifecycle correlation.
    private func performInstantAppSwitch(
        _ frozenTarget: String,
        context: OwnerTurnContext
    ) {
        guard directEffectsAreAllowed else { return }
        foregroundNavigationContext.remember(
            GoldForegroundAction(destination: .application, target: frozenTarget),
            ownerRequest: context.exactInput, sessionID: context.sessionID
        )
        let correlationID = activeRoutingCorrelationID
        let admittedBinding = ownerTurnLifecycle.activeBinding
        Task { @MainActor [weak self] in
            guard let self else { return }
            let displayRequest = context.resolvedSlots["displayTarget"]
            let placementScreen = displayRequest.flatMap { WindowTiler.placementScreen(named: $0) }
            if let displayRequest, placementScreen == nil {
                _ = self.finishVolatileOwnerTurn(turnID: context.turnID, correlationID: correlationID,
                    status: .failed, outcome: "app-display-not-unique",
                    reason: "I could not identify one attached \(displayRequest) display. Available displays: "
                        + NSScreen.screens.map(\.localizedName).joined(separator: ", ") + ".")
                return
            }
            if NativeAppSwitchIntentPolicy.isAcePanelCandidate(frozenTarget) {
                let visible = await MenuBarPanelManager.shared?
                    .openPanelForOwnerRequest(on: placementScreen) { [weak self] in
                        guard let self else { return false }
                        return self.directEffectsAreAllowed
                            && self.ownerTurnLifecycle.activeBinding == admittedBinding
                            && AceEventBus.shared.currentTurnID == context.turnID
                    } ?? false
                guard self.ownerTurnLifecycle.activeBinding == admittedBinding,
                      AceEventBus.shared.currentTurnID == context.turnID else { return }
                self.appendRouteReceipt("APP-SWITCH Ace panel visible=\(visible)")
                _ = self.finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationID,
                    status: visible ? .completed : .failed,
                    outcome: visible ? "ace-panel-verified-visible" : "ace-panel-not-visible",
                    reason: visible ? "Ace's control panel is open and visible\(placementScreen.map { " on " + $0.localizedName } ?? "")."
                        : "Ace's control panel did not become visible."
                )
                return
            }
            let receipt = await DesktopActionExecutor(
                backend: DesktopActionSystemBackend()
            ).execute(
                DesktopActionRequest(
                    action: .openApplication(exactName: frozenTarget),
                    expectedFrontmostBundleIdentifier: nil,
                    expectedFocusedElementToken: nil
                )
            )
            guard let admittedBinding,
                  self.ownerTurnLifecycle.activeBinding == admittedBinding,
                  AceEventBus.shared.currentTurnID == context.turnID else {
                self.appendRouteReceipt("APP-SWITCH retired replaced callback")
                _ = self.finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationID,
                    status: .cancelled,
                    outcome: "app-switch-superseded",
                    reason: "App switching was superseded by a newer owner turn.",
                    showVisible: false,
                    speak: false
                )
                return
            }
            guard receipt.status == .verified else {
                self.appendRouteReceipt("APP-SWITCH failed; closing the original native receipt")
                _ = self.finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationID,
                    status: .failed,
                    outcome: "app-switch-not-visible",
                    reason: receipt.reason
                )
                return
            }
            var completionReason = receipt.reason
            if let placementScreen {
                guard let frame = await WindowTiler.placeFrontmostWindow(
                    on: placementScreen,
                    expectedApplication: receipt.observedApplication ?? frozenTarget,
                    isCurrent: { [weak self] in
                        guard let self else { return false }
                        return self.directEffectsAreAllowed
                            && self.ownerTurnLifecycle.activeBinding == admittedBinding
                            && AceEventBus.shared.currentTurnID == context.turnID
                    }
                ) else {
                    _ = self.finishVolatileOwnerTurn(turnID: context.turnID, correlationID: correlationID,
                        status: .failed, outcome: "app-display-placement-unverified",
                        reason: "\(receipt.observedApplication ?? frozenTarget) opened, but its window was not verified on \(placementScreen.localizedName).")
                    return
                }
                self.appendRouteReceipt("WINDOW-MOVE verified display=\(placementScreen.localizedName) frame=(\(frame.minX),\(frame.minY),\(frame.width),\(frame.height))")
                completionReason = "\(receipt.observedApplication ?? frozenTarget) is open on \(placementScreen.localizedName)."
            }
            self.lastLocatedTargetName = receipt.observedApplication
            self.appendRouteReceipt(
                "APP-SWITCH native resolved="
                    + (receipt.observedApplication ?? frozenTarget)
                    + " visible=true"
            )
            _ = self.finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: correlationID,
                status: .completed,
                outcome: "app-switch-verified-visible",
                reason: completionReason
            )
        }
    }

    /// Website opens are direct reversible owner effects. Success requires the
    /// frozen host to appear in a frontmost, on-screen browser window.
    private func performInstantWebsiteOpen(
        _ frozenURL: String,
        context: OwnerTurnContext
    ) {
        guard directEffectsAreAllowed else { return }
        foregroundNavigationContext.remember(
            GoldForegroundAction(destination: .website, target: frozenURL),
            ownerRequest: context.exactInput, sessionID: context.sessionID
        )
        let correlationID = activeRoutingCorrelationID
        Task { @MainActor [weak self] in
            guard let self else { return }
            guard let result = await AppSwitcher.openFrozenWebsite(
                frozenURL,
                browserBundleIdentifier: context.resolvedSlots["browserBundleIdentifier"]
            ) else {
                _ = self.finishVolatileOwnerTurn(
                    turnID: context.turnID,
                    correlationID: correlationID,
                    status: .failed,
                    outcome: "web-open-unresolved",
                    reason:
                        "I could not issue that exact website navigation, so nothing opened."
                )
                return
            }
            self.appendRouteReceipt(
                "WEB-OPEN native verified="
                    + String(result.verifiedVisibleTarget)
                    + " browser="
                    + (result.browserName ?? "unobserved")
            )
            _ = self.finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: correlationID,
                status: result.verifiedVisibleTarget
                    ? .completed : .failed,
                outcome: result.verifiedVisibleTarget
                    ? "web-open-verified-visible"
                    : "web-open-not-verified",
                reason: result.spokenConfirmation
            )
        }
    }

    private func performGoldForegroundNavigation(
        _ action: GoldForegroundAction,
        isCurrent: @escaping @MainActor () -> Bool
    ) async -> (verified: Bool, reason: String) {
        guard action.isValid, isCurrent() else { return (false, "The request was cancelled.") }
        switch action.destination {
        case .application:
            if NativeAppSwitchIntentPolicy.isAcePanelCandidate(action.target) {
                let visible = await MenuBarPanelManager.shared?.openPanelForOwnerRequest(isCurrent: isCurrent) ?? false
                return (visible, visible ? "Ace's controls are open on your screen." : "Ace's controls did not become visible.")
            }
            guard let result = await AppSwitcher.handleFrozenCandidate(action.target) else {
                return (false, "I did not find one installed app named \(action.target). Where is it installed on this Mac?")
            }
            guard isCurrent() else { return (false, "The request was cancelled.") }
            if result.verifiedVisible { lastLocatedTargetName = result.resolvedApplicationName }
            return (result.verifiedVisible, result.spokenConfirmation)
        case .website:
            // Accessibility is needed to read back the requested browser URL.
            // Request the real app permission and retain this same destination.
            if !WindowPositionManager.hasAccessibilityPermission() {
                _ = WindowPositionManager.beginAccessibilityPermissionRepair()
                showVisibleResponse("Enable Accessibility for Ace so I can verify the requested page on your screen. I will continue this request when access is granted.")
                let deadline = Date().addingTimeInterval(90)
                while !WindowPositionManager.hasAccessibilityPermission(), Date() < deadline, isCurrent() {
                    do { try await Task.sleep(for: .milliseconds(250)) }
                    catch { return (false, "The request was cancelled.") }
                }
                guard isCurrent() else { return (false, "The request was cancelled.") }
                guard WindowPositionManager.hasAccessibilityPermission() else {
                    return (false, "Accessibility access for Ace is still off. The requested page is retained; enable access and ask me to open it again.")
                }
            }
            guard isCurrent(), let result = await AppSwitcher.openFrozenWebsite(action.target) else {
                return (false, "The browser did not accept the requested page.")
            }
            return (result.verifiedVisibleTarget, result.spokenConfirmation)
        }
    }

    private func handleLocateAsk(_ locateUtterance: String) {
        guard directEffectsAreAllowed else { return }
        // This is the single locate funnel — remember it so admission can type
        // a verb-less noun follow-up as `native.locate.follow-up` next turn.
        lastRouteWasLocate = true
        // "find agent zero on my right monitor" — the display qualifier must
        // not bloat the app-name candidate, and when present it becomes a
        // placement instruction after activation.
        let requestedDisplay = extractNamedDisplay(locateUtterance)
        let utteranceForAppResolution = strippingDisplayQualifier(locateUtterance)

        // Explicit "don't open" wins over everything: point at a running
        // app's real window (AX coordinates — no vision, no focus steal), or
        // say where an installed app lives and ask, but never activate.
        if locateUtterance.range(of: Self.noOpenPattern, options: .regularExpression) != nil {
            let cleanedTarget = extractLocateTarget(
                utteranceForAppResolution.replacingOccurrences(
                    of: Self.noOpenPattern, with: "", options: .regularExpression))
            if let cleanedTarget, pointAtRunningApp(named: cleanedTarget) { return }
            if let cleanedTarget, let installedName = AppSwitcher.installedAppName(matching: cleanedTarget) {
                appendRouteReceipt("LOCATE no-open: \(installedName) installed, not launched")
                Task {
                    try? await noraVoice.speakText(
                        "\(installedName) is installed but not running — i won't open it since you said not to. say open if you want it up.")
                }
                lastLocatedTargetName = installedName
                return
            }
            // Not an app — fall through to the vision locate below.
            sendTranscriptToClaudeWithScreenshot(transcript: locateUtterance)
            startScanTheater()
            return
        }

        // Locate is read-only by default. Point at an existing window or name
        // the installed app; only an explicit "open/switch/launch" route may
        // activate it or move one of its windows.
        if let target = extractLocateTarget(utteranceForAppResolution),
           pointAtRunningApp(named: target) {
            return
        }
        if let target = extractLocateTarget(utteranceForAppResolution),
           let installedName = AppSwitcher.installedAppName(matching: target) {
            lastLocatedTargetName = installedName
            appendRouteReceipt(
                "LOCATE app read-only resolved=\(installedName)"
            )
            let displayQualifier = requestedDisplay.map {
                " i didn't move it to the \($0) screen because find is read-only."
            } ?? ""
            Task {
                try? await noraVoice.speakText(
                    "\(installedName) is installed but not running.\(displayQualifier) say open \(installedName) if you want it up.")
            }
            return
        }
        // File-ish targets: Spotlight is ground truth — reveal the newest
        // match in Finder rather than letting vision guess at pixels.
        if let target = extractLocateTarget(utteranceForAppResolution),
           target.range(of: Self.fileWordPattern, options: .regularExpression) != nil,
           revealFileViaSpotlight(target) {
            return
        }
        sendTranscriptToClaudeWithScreenshot(transcript: locateUtterance)
        startScanTheater()
    }

    /// Points the gem at a RUNNING app's front-window center using AX ground
    /// truth — exact coordinates, no vision call, no activation. Returns false
    /// when the app isn't running or exposes no window.
    private func pointAtRunningApp(named targetName: String) -> Bool {
        let runningCandidates: [(String, NSRunningApplication)] =
            NSWorkspace.shared.runningApplications.compactMap { app in
                guard app.activationPolicy == .regular,
                      let name = app.localizedName else { return nil }
                return (name, app)
            }
        guard let resolved = AppSwitcher.bestMatch(
            runningCandidates,
            wanted: targetName
        ) else { return false }
        let resolvedName = resolved.0
        guard let windowFrame = frontWindowCGFrame(ofAppNamed: resolvedName) else { return false }
        // AX gives top-left-origin global coords; the overlay wants AppKit
        // (bottom-left origin, primary display height as the axis).
        let primaryScreenHeight = NSScreen.screens.first(where: { $0.frame.origin == .zero })?.frame.height
            ?? NSScreen.screens.first?.frame.height ?? 0
        let centerCG = CGPoint(x: windowFrame.midX, y: windowFrame.midY)
        let centerAppKit = CGPoint(x: centerCG.x, y: primaryScreenHeight - centerCG.y)
        let containingScreen = NSScreen.screens.first(where: { $0.frame.contains(centerAppKit) })
        detectedElementScreenLocation = centerAppKit
        detectedElementDisplayFrame = containingScreen?.frame ?? NSScreen.screens[0].frame
        markDetectedElementAsVerified()
        lastLocatedTargetName = resolvedName
        let displayWord = (containingScreen?.frame.origin.x ?? 0) < 0 ? "left" : "right"
        appendRouteReceipt("LOCATE ax-point \(resolvedName) at \(Int(centerCG.x)),\(Int(centerCG.y)) (\(displayWord) screen)")
        Task {
            try? await noraVoice.speakText(
                "right there — \(resolvedName) is on your \(displayWord) screen. not opening anything.")
        }
        return true
    }

    /// File-ish locate targets get Spotlight ground truth before any vision
    /// guess: newest matching file is revealed in Finder. Deterministic.
    private static let fileWordPattern =
        #"(?i)\b(file|files|folder|pdf|document|doc|screenshot|photo|image|picture|invoice|receipt|zip|csv|video|spreadsheet|download)\b"#

    private func revealFileViaSpotlight(_ target: String) -> Bool {
        guard directEffectsAreAllowed else { return false }
        let residualNameWords = target.replacingOccurrences(
            of: #"(?i)\b(file|files|my|most|recent|latest|newest|the|a|screenshot|photo|image|picture|pdf|video|folder)\b"#,
            with: " ", options: .regularExpression
        ).replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)

        // Match by what the file IS, not just what it's named — a name-only
        // query for "screenshot" surfaced a shell script called
        // screenshot-take. Spotlight knows real screenshots, images, pdfs.
        var queryClauses: [String] = []
        let lowercasedTarget = target.lowercased()
        if lowercasedTarget.contains("screenshot") {
            queryClauses.append("kMDItemIsScreenCapture == 1")
        } else if lowercasedTarget.range(of: #"photo|image|picture"#, options: .regularExpression) != nil {
            queryClauses.append("kMDItemContentTypeTree == \"public.image\"")
        } else if lowercasedTarget.contains("pdf") {
            queryClauses.append("kMDItemContentType == \"com.adobe.pdf\"")
        } else if lowercasedTarget.contains("video") {
            queryClauses.append("kMDItemContentTypeTree == \"public.movie\"")
        } else if lowercasedTarget.contains("folder") {
            queryClauses.append("kMDItemContentType == \"public.folder\"")
        }
        for nameWord in residualNameWords.split(separator: " ") where nameWord.count >= 3 {
            queryClauses.append("kMDItemFSName == \"*\(nameWord)*\"c")
        }
        guard !queryClauses.isEmpty else { return false }
        let query = queryClauses.joined(separator: " && ")
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/mdfind")
        process.arguments = [query]
        let outputPipe = Pipe()
        process.standardOutput = outputPipe
        process.standardError = FileHandle.nullDevice
        let completion = DispatchSemaphore(value: 0)
        process.terminationHandler = { _ in completion.signal() }

        let processCutoff = MailToolProcessCutoff()
        let cutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                processCutoff.cancelSynchronously()
            }
        defer {
            processCutoff.clear()
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier
            )
        }

        let launchOutcome =
            DirectEffectProcessLaunchAdmission.commit(
                effectsAreAllowed: { [weak self] in
                    self?.directEffectsAreAllowed == true
                },
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                },
                launchAndPublish: {
                    do {
                        try process.run()
                        processCutoff.register(process)
                        return true
                    } catch {
                        return false
                    }
                }
            )
        guard launchOutcome == .launched else { return false }

        let output = BoundedDirectProcessOutputBox(limit: 1_048_576)
        let readerFinished = DispatchSemaphore(value: 0)
        DispatchQueue.global(qos: .utility).async {
            let handle = outputPipe.fileHandleForReading
            while let chunk = try? handle.read(upToCount: 65_536),
                  !chunk.isEmpty {
                output.append(chunk)
            }
            readerFinished.signal()
        }
        guard completion.wait(timeout: .now() + 3) == .success else {
            processCutoff.cancelSynchronously()
            _ = completion.wait(timeout: .now() + 0.25)
            return false
        }
        guard readerFinished.wait(timeout: .now() + 0.25)
                == .success else {
            processCutoff.cancelSynchronously()
            return false
        }
        let outputSnapshot = output.snapshot()
        guard process.terminationReason == .exit,
              process.terminationStatus == 0,
              !outputSnapshot.truncated,
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return false
        }
        let matchedPaths = (
            String(data: outputSnapshot.data, encoding: .utf8) ?? ""
        )
            .split(separator: "\n").prefix(200).map(String.init)
        let newestMatch = matchedPaths.compactMap { path -> (path: String, modified: Date)? in
            guard !StealthEntryLatch.shared.isRaised,
                  directEffectsAreAllowed else {
                return nil
            }
            guard let attributes = try? FileManager.default.attributesOfItem(atPath: path),
                  let modified = attributes[.modificationDate] as? Date else { return nil }
            return (path, modified)
        }.max(by: { $0.modified < $1.modified })
        guard let newestMatch,
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else {
            return false
        }
        let fileName = (newestMatch.path as NSString).lastPathComponent
        guard performDirectEffectCommit({ [weak self] in
            guard let self else { return false }
            NSWorkspace.shared.activateFileViewerSelecting([
                URL(fileURLWithPath: newestMatch.path)
            ])
            self.lastLocatedTargetName = fileName
            self.appendRouteReceipt(
                "LOCATE file via spotlight matched=true"
            )
            return true
        }) else {
            return false
        }
        Task { try? await noraVoice.speakText("found \(fileName) — showing it in finder.") }
        return true
    }

    // MARK: - Right-display tiling + explain (Features A / B, our fork 2026-07-17)

    /// A reference to the right display in speech: "right screen" / "right monitor"
    /// / "right display" (and "right hand/side …"). Shared by BOTH the tile and
    /// explain routes so they agree on what "right screen" means.
    private static let rightDisplayReferencePattern =
        #"(?i)\bright(?:[\s-]+(?:hand|side))?[\s-]+(?:screen|monitor|display)\b"#

    /// Verbs/adjectives that mean "lay the windows out in a symmetrical grid":
    /// tile, arrange, even out, make symmetrical, grid, square up, two-by-two.
    private static let tilingKeywordPattern =
        #"(?i)\b(?:til(?:e|ed|ing)|arrang\w*|even(?:\s+(?:out|up))?|evenly|symmetr\w*|grid|square(?:d|\s+up)?|quadrants?|two[\s-]+by[\s-]+two|2\s*(?:x|by)\s*2)\b"#

    /// Feature A trigger: a tiling verb AND a right-display reference, in any order
    /// ("tile the apps on the right screen", "make the apps on my right screen
    /// symmetrical", "even out the apps on my right monitor", "arrange the right
    /// screen"). Requiring both keeps it off plain placement asks ("open safari on
    /// the right screen" has no tiling verb) and off the explain route.
    private func isTileRightScreenRequest(_ text: String) -> Bool {
        guard text.range(of: Self.rightDisplayReferencePattern, options: .regularExpression) != nil else { return false }
        return text.range(of: Self.tilingKeywordPattern, options: .regularExpression) != nil
    }

    /// Feature B trigger: an explain/query intent AND the word "apps" AND a
    /// right-display reference ("explain all the apps on the right screen", "what
    /// are the apps on my right screen", "explain the apps on my right monitor").
    /// Requiring "apps" keeps a bare "what's on my right screen" on the gold
    /// vision path, and the intent word keeps the tiling phrasings out.
    /// ALSO fires without a display word for the canonical group phrasings —
    /// "explain the four apps", "go over these apps" — the founder's "Explain
    /// the four apps" fell to a text-only brain answer with no tour
    /// (2026-07-18 00:05Z); the four apps ARE the right-screen products.
    private func isExplainRightScreenAppsRequest(_ text: String) -> Bool {
        let explainIntentPattern =
            #"(?i)\b(explain|describe|what\s+are|what\s+apps|which\s+apps|what'?s|whats|tell\s+me\s+about|summari[sz]e|go\s+over|list|what\s+do\s+i\s+have|walk\s+me\s+through)\b"#
        guard text.range(of: explainIntentPattern, options: .regularExpression) != nil else { return false }
        let referencesRightDisplay =
            text.range(of: Self.rightDisplayReferencePattern, options: .regularExpression) != nil
            && text.range(of: #"(?i)\bapps?\b"#, options: .regularExpression) != nil
        let referencesTheAppGroup = text.range(
            of: #"(?i)\b(?:(?:the|those|these|my|all\s+(?:the\s+)?)\s*)?four\s+apps\b|\b(?:these|those)\s+apps\b|\ball\s+(?:the\s+)?apps\b"#,
            options: .regularExpression) != nil
        return referencesRightDisplay || referencesTheAppGroup
    }

    /// Feature A — arranges the right display's app windows into an equal 2×2 grid,
    /// then PROVES the move landed by re-reading each window's AX frame into the
    /// receipt (a spoken/logged "done" alone can't tell a real move from an app
    /// that refused to resize).
    private func performRightScreenTile() {
        guard directEffectsAreAllowed else { return }
        guard WindowPositionManager.hasAccessibilityPermission() else {
            guard performDirectEffectCommit({ [weak self] in
                self?.appendRouteReceipt(
                    "TILE right 2x2 refused: no accessibility permission"
                )
                return self != nil
            }) else {
                return
            }
            Task {
                try? await noraVoice.speakText(
                    "i need accessibility access to move windows — turn it on for me in system settings, then ask again.")
            }
            return
        }
        let tilingAdmission = DirectEffectCommitAdmission.commit(
            visibilityIsBlocked: { [weak self] in
                self?.directEffectsAreAllowed != true
            },
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            },
            effect: {
                WindowTiler.tileRightDisplayIntoTwoByTwoGrid()
            }
        )
        let tilingOutcome: WindowTiler.TilingOutcome
        switch tilingAdmission {
        case .blocked:
            return
        case .committed(.none):
            guard performDirectEffectCommit({ [weak self] in
                self?.appendRouteReceipt(
                    "TILE right 2x2 refused: no right display resolved"
                )
                return self != nil
            }) else {
                return
            }
            Task { try? await noraVoice.speakText("i couldn't find a right screen to arrange.") }
            return
        case .committed(.some(let outcome)):
            tilingOutcome = outcome
        }
        guard !tilingOutcome.arrangedWindows.isEmpty else {
            guard performDirectEffectCommit({ [weak self] in
                self?.appendRouteReceipt(
                    "TILE right 2x2 count=0 apps=[] "
                        + "(no tileable windows on right display)"
                )
                return self != nil
            }) else {
                return
            }
            Task {
                try? await noraVoice.speakText(
                    "there aren't any app windows on your right screen to arrange.")
            }
            return
        }

        let arrangedApplicationNames = tilingOutcome.arrangedWindows.map { $0.applicationName }
        let visibleFrame = tilingOutcome.rightDisplayVisibleFrameInAppKitCoordinates
        guard performDirectEffectCommit({ [weak self] in
            self?.appendRouteReceipt(
                "TILE right 2x2 count="
                    + "\(tilingOutcome.arrangedWindows.count) "
                    + "apps=[\(arrangedApplicationNames.joined(separator: ", "))] "
                    + "visibleFrame=(\(Int(visibleFrame.minX)),"
                    + "\(Int(visibleFrame.minY)),"
                    + "\(Int(visibleFrame.width)),"
                    + "\(Int(visibleFrame.height)))"
            )
            return self != nil
        }) else {
            return
        }

        // Re-read the landed AX frames after a short settle — some apps apply the
        // resize a beat after the set returns — and log expected vs actual so the
        // receipt itself proves the windows moved into their quadrants.
        Task {
            try? await Task.sleep(nanoseconds: 500_000_000)
            for arrangedWindow in tilingOutcome.arrangedWindows {
                guard !StealthEntryLatch.shared.isRaised,
                      directEffectsAreAllowed else {
                    return
                }
                let expectedPosition = arrangedWindow.expectedPositionTopLeftInCoreGraphicsCoordinates
                let expectedSize = arrangedWindow.expectedSizeInPoints
                let receipt: String
                if let landed = WindowTiler.currentGeometry(of: arrangedWindow.accessibilityWindowElement) {
                    receipt =
                        "TILE landed \(arrangedWindow.applicationName) "
                        + "expected=(\(Int(expectedPosition.x)),\(Int(expectedPosition.y)) \(Int(expectedSize.width))x\(Int(expectedSize.height))) "
                        + "actual=(\(Int(landed.positionTopLeftInCoreGraphics.x)),\(Int(landed.positionTopLeftInCoreGraphics.y)) \(Int(landed.sizeInPoints.width))x\(Int(landed.sizeInPoints.height)))"
                } else {
                    receipt =
                        "TILE landed \(arrangedWindow.applicationName) "
                        + "actual=unreadable"
                }
                guard performDirectEffectCommit({ [weak self] in
                    self?.appendRouteReceipt(receipt)
                    return self != nil
                }) else {
                    return
                }
            }
        }

        let spokenCount = Self.spokenCountWord(for: tilingOutcome.arrangedWindows.count)
        let appNoun = tilingOutcome.arrangedWindows.count == 1 ? "app" : "apps"
        Task {
            try? await noraVoice.speakText(
                "arranged \(spokenCount) \(appNoun) in a two-by-two grid on your right screen.")
        }
    }

    /// The running explain choreography, so "stop", a new walkthrough, or a
    /// fresh explain can cancel the tour mid-hop.
    private var explainAppsChoreographyTask: Task<Void, Never>?

    /// Feature B — a per-app gem TOUR of the right display, entirely in software.
    /// v1 spoke one wall of text and never moved the gem — the founder rejected
    /// it ("he didn't go to each one"). Now: real AX inventory → product apps
    /// when present → reading order (top row left-to-right, then bottom row) →
    /// for EACH app the gem flies to that window's center, pulses, and Nora
    /// speaks a canned one-liner while hovering there. Canned lines, never
    /// codex: instant, accurate for our own products, and immune to the
    /// barge-in kill that ended the v1 brain call with exit 15.
    private func performExplainRightScreenApps() {
        guard !stealthMode.isActive, !StealthVisibilityGate.shared.isActive else {
            appendRouteReceipt("EXPLAIN deferred — stealth active")
            return
        }
        guard let inventory = WindowTiler.rightDisplayInventory(),
              !inventory.windowsOnRightDisplay.isEmpty else {
            appendRouteReceipt("EXPLAIN right-screen apps=[] (none found)")
            Task {
                try? await noraVoice.speakText(
                    "i don't see any app windows on your right screen right now.")
            }
            return
        }

        let primaryDisplayHeight = WindowTiler.primaryDisplayHeightInPoints()
        // One (largest) window per app; skip desktop clutter that nobody means
        // when they say "the apps". Product apps own the tour when present —
        // "the four apps on my right screen" is Marketing, Academy, Sovereign,
        // Real Estate, not Otter and System Settings (v1 explained 11 apps).
        let desktopClutterApplicationNames: Set<String> = ["Finder", "System Settings"]
        let largestWindowPerApp = WindowTiler
            .largestWindowPerApplication(in: inventory.windowsOnRightDisplay)
            .filter { !desktopClutterApplicationNames.contains($0.owningApplicationName) }
        let productApplicationWindows = largestWindowPerApp
            .filter { WindowTiler.isPreferredProductApplication(named: $0.owningApplicationName) }
        let chosenWindows = productApplicationWindows.count >= 2
            ? productApplicationWindows
            : largestWindowPerApp

        // Reading order: top row first, left to right, then the bottom row — the
        // gem walks the grid the way the founder reads it.
        let rightDisplayFrame = inventory.rightDisplayScreen.frame
        let screenVerticalMidline = rightDisplayFrame.midY
        let orderedWindows = Array(
            chosenWindows.sorted { firstWindow, secondWindow in
                let firstCenter = WindowTiler.appKitCenter(
                    of: firstWindow, primaryDisplayHeightInPoints: primaryDisplayHeight)
                let secondCenter = WindowTiler.appKitCenter(
                    of: secondWindow, primaryDisplayHeightInPoints: primaryDisplayHeight)
                let firstIsTopRow = firstCenter.y >= screenVerticalMidline
                let secondIsTopRow = secondCenter.y >= screenVerticalMidline
                if firstIsTopRow != secondIsTopRow { return firstIsTopRow }
                return firstCenter.x < secondCenter.x
            }.prefix(6)
        )

        let orderedApplicationNames = orderedWindows.map { $0.owningApplicationName }
        appendRouteReceipt("EXPLAIN right-screen apps=[\(orderedApplicationNames.joined(separator: ", "))]")

        cancelWalkthroughIfRunning()
        explainAppsChoreographyTask?.cancel()
        showCursorOverlayForBackgroundTask()
        explainAppsChoreographyTask = Task {
            voiceState = .responding
            let introLine = orderedWindows.count == 4
                ? "here are the four apps on your right screen."
                : "here's what's on your right screen."
            try? await noraVoice.speakText(introLine)
            await waitForSpeechPlaybackToFinishOrCancellation()

            for window in orderedWindows {
                if Task.isCancelled { return }
                let gemTargetInAppKit = WindowTiler.appKitCenter(
                    of: window, primaryDisplayHeightInPoints: primaryDisplayHeight)
                // Same gem-flight mechanism as the demo finale: set the detected
                // element location and the display frame it belongs to, pulse.
                detectedElementScreenLocation = gemTargetInAppKit
                detectedElementDisplayFrame = rightDisplayFrame
                markDetectedElementAsVerified()
                clickFlashTrigger += 1
                appendRouteReceipt(
                    "EXPLAIN-STEP \(window.owningApplicationName) "
                    + "at (\(Int(gemTargetInAppKit.x)),\(Int(gemTargetInAppKit.y)))")
                // Let the gem land before its line begins so speech and position
                // stay in sync — the whole point of the tour.
                try? await Task.sleep(for: .milliseconds(700))
                if Task.isCancelled { return }
                try? await noraVoice.speakText(
                    Self.cannedExplanationLine(forApplicationNamed: window.owningApplicationName))
                await waitForSpeechPlaybackToFinishOrCancellation()
                if Task.isCancelled { return }
                try? await Task.sleep(for: .milliseconds(250))
            }

            appendRouteReceipt("EXPLAIN done count=\(orderedWindows.count)")
            if !Task.isCancelled {
                voiceState = .idle
                clearDetectedElementLocation()
            }
        }
    }

    /// Wires the trailing gem's color to the live state of its three owners, in
    /// precedence order: a background worker mid-task → red, else the notetaker
    /// capturing → blue, else trading mode on → purple. Combine mirror, not manual
    /// call sites, so every transition (the notetaker's safety auto-stop, a
    /// worker finishing while trading mode stays on) recolors the gem on its own.
    private func bindCompanionGemColorState() {
        meetingNotetaker.$isTakingNotes
            .combineLatest(meetingNotetaker.$isStartingUp)
            .combineLatest(backgroundAgent.$isWorking, $tradingModeActive)
            .receive(on: DispatchQueue.main.circuitScheduler)
            .sink {
                [weak self] notesState, workerIsBusy, tradingModeIsActive in
                guard let self else { return }
                let notetakerIsActive =
                    MeetingLaneVisualState.isActive(
                        isTakingNotes: notesState.0,
                        isStartingUp: notesState.1
                    )
                if workerIsBusy {
                    self.companionTrailingGemColor = .red
                } else if notetakerIsActive {
                    self.companionTrailingGemColor = .blue
                } else if tradingModeIsActive {
                    self.companionTrailingGemColor = .purple
                }
                // Legacy blue/red flag kept in sync for any external reader.
                self.companionGemShowsNotesBlue =
                    notetakerIsActive && !workerIsBusy
            }
            .store(in: &companionGemColorSubscriptions)
    }

    /// Polls TTS playback to completion, returning early on task cancellation —
    /// the same wait the demo steps use, shared by the explain tour.
    private func waitForSpeechPlaybackToFinishOrCancellation() async {
        while noraVoice.isPlaying {
            if Task.isCancelled { return }
            try? await Task.sleep(for: .milliseconds(200))
        }
    }

    /// One spoken line per app for the explain tour. Canned and honest — our own
    /// products get real descriptions, everything else gets a neutral line.
    /// Never codex: canned lines are instant and can't be killed mid-tour by a
    /// hotkey press the way the v1 brain call was (exit 15).
    private static func cannedExplanationLine(forApplicationNamed applicationName: String) -> String {
        switch applicationName {
        case "Black Label Marketing":
            return "black label marketing — the marketing studio. it builds promo reels and generates full websites from your own assets."
        case "Black Label Academy":
            return "black label academy — the course builder. it turns what you know into structured courses you can sell."
        case "Black Label Sovereign":
            return "black label sovereign — your private autonomous assistant. it runs on your own claude login."
        case "Black Label Real Estate":
            return "black label real estate — the deal finder. it sources probate and teardown properties and runs the comps and after-repair numbers."
        case "Black Label Trading":
            return "black label trading — the signals app. it reads the market and flags setups. it never trades for you."
        case "Black Label HQ":
            return "black label h q — the company dashboard. everything across the business in one place."
        case "Google Chrome":
            return "google chrome — your browser."
        case "Claude":
            return "claude — the coding assistant."
        case "Otter", "Otter.ai":
            return "otter — meeting transcription."
        case "Photos":
            return "photos — your photo library."
        default:
            return "\(applicationName)."
        }
    }

    /// Small-number spoken word so the confirmation reads naturally ("arranged
    /// four apps …"); falls back to the digit above four (the tiler never places
    /// more than four, but this keeps the helper honest).
    private static func spokenCountWord(for count: Int) -> String {
        switch count {
        case 1: return "one"
        case 2: return "two"
        case 3: return "three"
        case 4: return "four"
        default: return "\(count)"
        }
    }

    // MARK: - Native close sweep ("close everything except …")

    /// Set while a close-sweep awaits its spoken confirmation; holds the
    /// names the user asked to keep.
    private var pendingCloseSweep: (exceptions: [String], requestedAt: Date)?

    /// "close/quit everything (except X and Y)" — returns the names to KEEP,
    /// or nil when this isn't a sweep (a single "close safari" stays with the
    /// normal task routing).
    private static let closeSweepPattern =
        #"(?i)^\s*(?:please\s+)?(?:go\s+ahead\s+and\s+)?(?:close|quit|cancel|exit\s+out\s+of)\s+(?:everything|all(?:\s+of\s+(?:them|it))?(?:\s+(?:my\s+)?(?:apps|applications|windows))?)\s*(?:(?:except|other\s+than|but(?:\s+not)?|besides|keep)\s+(.+?))?[\s.!?]*$"#

    private func extractCloseSweepRequest(_ text: String) -> [String]? {
        guard let regex = try? NSRegularExpression(pattern: Self.closeSweepPattern),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) else { return nil }
        var exceptionNames: [String] = ["terminal"]
        if let exceptionsRange = Range(match.range(at: 1), in: text) {
            exceptionNames = String(text[exceptionsRange])
                .replacingOccurrences(of: #"(?i)\b(the|my|apps?|applications?|windows?|open)\b"#, with: " ", options: .regularExpression)
                .split(whereSeparator: { ",;".contains($0) })
                .flatMap { $0.components(separatedBy: " and ") }
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { $0.count >= 2 }
        }
        return exceptionNames
    }

    /// Gracefully terminates every regular app except the kept names, Ace
    /// itself, and Finder. terminate() is the polite quit — apps with unsaved
    /// changes show their own save dialogs rather than losing work.
    private func performCloseSweep(keeping exceptionNames: [String]) {
        guard directEffectsAreAllowed else { return }
        let lowercasedExceptions = exceptionNames.map { $0.lowercased() }
        let alwaysKept = ["finder", "black label assistant", "ace", "terminal", "iterm2", "iterm"]
        var closeRequests: [(name: String, app: NSRunningApplication)] = []
        var keptNames: [String] = []
        for app in NSWorkspace.shared.runningApplications where app.activationPolicy == .regular {
            guard directEffectsAreAllowed else { break }
            guard let appName = app.localizedName?.lowercased(), app != NSRunningApplication.current else { continue }
            let isKept = alwaysKept.contains(appName)
                || lowercasedExceptions.contains(where: { appName.contains($0) || $0.contains(appName) })
            if isKept {
                keptNames.append(app.localizedName ?? appName)
            } else {
                let displayName = app.localizedName ?? appName
                guard performDirectEffectCommit({ [weak self] in
                    guard let self else { return false }
                    if app.terminate() {
                        closeRequests.append((displayName, app))
                        self.appendRouteReceipt(
                            "CLOSE requested \(displayName)"
                        )
                    }
                    return true
                }) else {
                    return
                }
            }
        }
        Task {
            try? await Task.sleep(for: .seconds(2))
            guard !StealthEntryLatch.shared.isRaised,
                  directEffectsAreAllowed else {
                return
            }
            let verifiedClosed = closeRequests.filter { $0.app.isTerminated }
            let stillOpen = closeRequests.filter { !$0.app.isTerminated }
            guard performDirectEffectCommit({ [weak self] in
                self?.appendRouteReceipt(
                    "CLOSE-SWEEP verified-closed="
                        + "\(verifiedClosed.count) "
                        + "still-open=\(stillOpen.count) "
                        + "kept=\(keptNames.joined(separator: ","))"
                )
                return self != nil
            }) else {
                return
            }
            let keptSpoken = keptNames.isEmpty
                ? "no named exceptions"
                : keptNames.prefix(4).joined(separator: ", ")
            if stillOpen.isEmpty {
                try? await noraVoice.speakText(
                    "verified \(verifiedClosed.count) apps closed. kept "
                        + "\(keptSpoken).")
            } else {
                let unresolved = stillOpen.prefix(4).map(\.name)
                    .joined(separator: ", ")
                try? await noraVoice.speakText(
                    "verified \(verifiedClosed.count) apps closed. "
                        + "\(stillOpen.count) are still open or waiting for "
                        + "a save decision: \(unresolved). kept \(keptSpoken).")
            }
        }
    }

    // MARK: - Named-display placement (uses the bundled window-move tool)

    private static let namedDisplayPattern =
        #"(?i)\bon\s+(?:my\s+|the\s+)?(left|right|main)(?:[-\s]hand)?(?:\s+side)?\s+(?:monitor|screen|display)\b"#

    /// "on my right monitor" → "right"; nil when no display is named.
    private func extractNamedDisplay(_ text: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: Self.namedDisplayPattern),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)),
              let captureRange = Range(match.range(at: 1), in: text) else { return nil }
        return String(text[captureRange]).lowercased()
    }

    private func strippingDisplayQualifier(_ text: String) -> String {
        text.replacingOccurrences(
            of: Self.namedDisplayPattern, with: "", options: .regularExpression
        ).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// A display-qualified app open is one compound mutation: resolve the app
    /// without touching NSWorkspace, then stage only the exact move. Preparing
    /// the plan must never launch or focus the app before the owner hears and
    /// confirms the full move. The current window tool intentionally accepts
    /// only an already-running app, so installed-only targets fail explicitly.
    @discardableResult
    private func stageDisplayQualifiedAppOpen(
        _ appSwitchUtterance: String,
        display: String
    ) -> Bool {
        switch AppSwitcher.resolveWithoutActivation(appSwitchUtterance) {
        case .notAppSwitchRequest:
            return false

        case .running(let target):
            lastLocatedTargetName = target.applicationName
            appendRouteReceipt(
                "APP-SWITCH passive resolve running=\(target.applicationName) "
                    + "pid=\(target.processIdentifier) "
                    + "window=\(target.windowNumber) display=\(display); "
                    + "no pre-confirm activation")
            beginDirectAppActionPreview(
                PlannedAppAction(
                    tool: .windowMove,
                    arguments: [
                        target.applicationName,
                        String(target.processIdentifier),
                        String(target.windowNumber),
                        display,
                    ]
                )
            )
            return true

        case .runningWithoutWindowIdentity(let applicationName):
            appendRouteReceipt(
                "APP-SWITCH display request refused unbound-window="
                    + applicationName)
            Task {
                try? await noraVoice.speakText(
                    "\(applicationName) is running, but i could not bind one "
                        + "exact window to the confirmation. i did not focus "
                        + "or move anything. make sure Ace has Accessibility "
                        + "permission and the app has an open window, then "
                        + "ask again.")
            }
            return true

        case .installed(let applicationName):
            appendRouteReceipt(
                "APP-SWITCH display request refused nonrunning="
                    + applicationName)
            Task {
                try? await noraVoice.speakText(
                    "\(applicationName) is installed but is not running, so "
                        + "i did not open or move it. open it normally, then "
                        + "ask me to move it to the \(display) display.")
            }
            return true

        case .ambiguous:
            appendRouteReceipt(
                "APP-SWITCH display request refused ambiguous identity")
            Task {
                try? await noraVoice.speakText(
                    "more than one app matched that name, so i did not open, "
                        + "focus, or move anything. use the app's full exact "
                        + "name and ask again.")
            }
            return true

        case .notFound:
            appendRouteReceipt(
                "APP-SWITCH display request refused unresolved identity")
            Task {
                try? await noraVoice.speakText(
                    "i could not resolve one installed or running app with "
                        + "that name, so i did not open, focus, or move "
                        + "anything. use the app's full exact name and ask "
                        + "again.")
            }
            return true
        }
    }

    private func routeAceHQCompanyWorkIfPresent() -> Bool {
        guard let request = activeContextualOwnerRequest,
              let capability = AceHQCompanyWorkPolicy.capability(
                  for: request
              ) else {
            return false
        }
        routeAceHQCompanyWork(request: request, capability: capability)
        return true
    }

    private func routeAceHQCompanyWork(
        request: ContextualOwnerRequest,
        capability: AceHQRequestedCapability
    ) {
        guard AceLicense.shared.admits(.companyDispatch),
              directEffectsAreAllowed else {
            completeAceHQBeforeDispatch(
                request,
                status: .blocked,
                message:
                    "Ace company dispatch is not currently unlocked. Nothing ran."
            )
            return
        }
        guard let consentReceipt =
                completeAgentCapabilityConsentReceipt() else {
            pendingAceHQCapabilityRequest =
                AceHQCapabilityConsentContinuation(
                request: request,
                capability: capability,
                consentReviewIdentifier: nil,
                consentSourceSessionIdentifier: nil,
                consentSourceTurnIdentifier: nil,
                consentSourceCorrelationIdentifier: nil,
                consentWorkCorrelationIdentifier: nil
                )
            requestAgentCapabilityConsent(
                for: .company,
                request: request.resolvedRequest,
                executionInstruction: request.executionInstruction,
                directWorkCorrelationIdentifier: nil
            )
            return
        }
        let consentValidatedAt = Date()

        let executionReviewIdentifier = UUID()
        switch AceHQCompanionExecutionPolicy.decision(
            request: request,
            capability: capability,
            reviewIdentifier: executionReviewIdentifier,
            at: consentValidatedAt
        ) {
        case .requiresExecutionConfirmation(let pendingReview):
            let exactPresentation =
                AceHQCompanionExecutionPolicy.presentation(
                    for: pendingReview
                )
            pendingAceHQConfirmation = nil
            pendingAceHQExecutionConfirmation = pendingReview
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier:
                    request.childWorkCorrelationIdentifier,
                lane: .hq,
                status: .awaitingConfirmation
            )
            appActionReview = AppActionReviewState(
                planIdentifier: executionReviewIdentifier,
                exactPreview: exactPresentation,
                phase: .reading
            )
            Task { [weak self] in
                guard let self else { return }
                let completed = await self.noraVoice
                    .speakVerbatimTextToVerifiedCompletion(
                        exactPresentation
                    )
                guard !Task.isCancelled,
                      self.directEffectsAreAllowed,
                      completed,
                      let current =
                        self.pendingAceHQExecutionConfirmation,
                      current == pendingReview,
                      let armed = current.arming(
                          reviewIdentifier:
                            executionReviewIdentifier,
                          presentedExactInstruction:
                            pendingReview.exactInstruction,
                          presentedExecutionTarget:
                            pendingReview.executionTarget,
                          at: Date()
                      ),
                      case let .ready(expiresAt) = armed.phase,
                      self.appActionReview?.planIdentifier
                        == executionReviewIdentifier,
                      self.appActionReview?.exactPreview
                        == exactPresentation else {
                    if self.pendingAceHQExecutionConfirmation?
                        .reviewIdentifier
                        == executionReviewIdentifier {
                        self.pendingAceHQExecutionConfirmation = nil
                        self.appActionReview = nil
                        self.completeAceHQBeforeDispatch(
                            pendingReview.request,
                            status: .blocked,
                            message:
                                "The full HQ exact-execution readback did not complete. Nothing ran.",
                            authority: .executeWhitelisted
                        )
                    }
                    return
                }
                self.pendingAceHQExecutionConfirmation = armed
                self.appActionReview = AppActionReviewState(
                    planIdentifier: executionReviewIdentifier,
                    exactPreview: exactPresentation,
                    phase: .ready(expiresAt: expiresAt)
                )
                try? await self.noraVoice.speakText(
                    "the exact HQ execution is ready. say confirm within thirty seconds, or say cancel."
                )
            }
            return
        case .planOnly:
            pendingAceHQExecutionConfirmation = nil
            break
        }

        if CrossAppActionPolicy.requiresConfirmation(
            request.executionInstruction
        ) {
            let reviewIdentifier = UUID()
            let requestedAt = Date()
            let pendingReview = AceHQExactPlanReview(
                reviewIdentifier: reviewIdentifier,
                request: request,
                capability: capability,
                requestedAt: requestedAt,
                phase: .presenting
            )
            pendingAceHQConfirmation = pendingReview
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier:
                    request.childWorkCorrelationIdentifier,
                lane: .hq,
                status: .awaitingConfirmation
            )
            appActionReview = AppActionReviewState(
                planIdentifier: reviewIdentifier,
                exactPreview: pendingReview.exactPlan,
                phase: .reading
            )
            Task { [weak self] in
                guard let self else { return }
                let completed = await self.noraVoice
                    .speakVerbatimTextToVerifiedCompletion(
                        pendingReview.exactPlan
                    )
                guard !Task.isCancelled,
                      self.directEffectsAreAllowed,
                      completed,
                      let current = self.pendingAceHQConfirmation,
                      let armed = current.arming(
                          reviewIdentifier: reviewIdentifier,
                          presentedExactPlan: pendingReview.exactPlan,
                          at: Date()
                      ),
                      case let .ready(expiresAt) = armed.phase,
                      self.appActionReview?.planIdentifier
                        == reviewIdentifier,
                      self.appActionReview?.exactPreview
                        == pendingReview.exactPlan else {
                    if self.pendingAceHQConfirmation?.reviewIdentifier
                        == reviewIdentifier {
                        self.pendingAceHQConfirmation = nil
                        self.appActionReview = nil
                        self.completeAceHQBeforeDispatch(
                            pendingReview.request,
                            status: .blocked,
                            message:
                                "The full HQ exact-plan readback did not complete. Nothing ran."
                        )
                    }
                    return
                }
                self.pendingAceHQConfirmation = armed
                self.appActionReview = AppActionReviewState(
                    planIdentifier: reviewIdentifier,
                    exactPreview: armed.exactPlan,
                    phase: .ready(
                        expiresAt: expiresAt
                    )
                )
                try? await self.noraVoice.speakText(
                    "the exact HQ planning handoff is ready. say confirm within thirty seconds, or say cancel."
                )
            }
            return
        }

        beginAceHQDispatch(
            AceHQCompanyWorkPolicy.makeIntent(
                request: request,
                capability: capability,
                authorizationRequirement: .nonconsequentialPlan,
                durableConsent: durableHQCapabilityConsent(
                    from: consentReceipt
                ),
                consentValidatedAt: consentValidatedAt,
                exactPlanConfirmedAt: nil
            )
        )
    }

    private func beginAceHQDispatch(
        _ intent: AceHQDispatchIntent,
        resuming acceptedDispatch: AceHQPendingDispatch? = nil,
        reconciliationAttempt: AceHQReconciliationAttempt? = nil
    ) {
        guard AceLicense.shared.admits(.companyDispatch),
              directEffectsAreAllowed else {
            if let acceptedDispatch {
                retryableAceHQDispatch = RetryableAceHQDispatch(
                    intent: intent,
                    acceptedDispatch: acceptedDispatch,
                    reconciliationAttempt: reconciliationAttempt
                )
                _ = persistAceHQPendingDispatch(
                    acceptedDispatch,
                    state: .ownerSuspended,
                    reconciliationAttempt: reconciliationAttempt
                )
            } else {
                completeAceHQBeforeDispatch(
                    intent,
                    status: .blocked,
                    message:
                        "Ace company dispatch is not currently unlocked. Nothing ran."
                )
            }
            return
        }
        guard aceHQDispatchTask == nil else {
            let message =
                "One HQ company handoff is already in progress. This request did not start."
            completeAceHQBeforeDispatch(
                intent,
                status: .blocked,
                message: message
            )
            return
        }
        guard let client = aceHQDispatchClient else {
            handleAceHQBlocked(
                intent: intent,
                acceptedDispatch: acceptedDispatch,
                code: .hqUnavailable,
                message: "The local HQ company-work client is unavailable.",
                retryable: true,
                reconciliationAttempt: reconciliationAttempt
            )
            return
        }

        // The contextual resolver initially owns every admitted request as
        // `direct`. Persist the HQ handoff before any network call so a crash
        // cannot let generic relaunch recovery convert an accepted HQ turn into
        // an immutable synthetic interruption that rejects its real terminal.
        let localWorkCorrelationID = reconciliationAttempt?.work
            .correlationID ?? intent.work.correlationID
        guard let workID = UUID(
            uuidString: localWorkCorrelationID
        ), goldContextBundle.transitionWork(
            workCorrelationIdentifier: workID,
            lane: reconciliationAttempt == nil ? "hq" : "hq.reconcile",
            status: .running
        ), AceConversationHistory.saveBundle(
            goldContextBundle,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        ) else {
            retryableAceHQDispatch = RetryableAceHQDispatch(
                intent: intent,
                acceptedDispatch: acceptedDispatch,
                reconciliationAttempt: reconciliationAttempt
            )
            if let acceptedDispatch {
                _ = persistAceHQPendingDispatch(
                    acceptedDispatch,
                    state: .ownerSuspended,
                    reconciliationAttempt: reconciliationAttempt
                )
            }
            showVisibleResponse(
                "The HQ handoff could not persist its recovery identity. Nothing ran."
            )
            return
        }

        retryableAceHQDispatch = nil
        aceHQActiveReconciliationAttempt = reconciliationAttempt
        let generation = UUID()
        aceHQDispatchGeneration = generation
        let stealthBoundary = AceHQDispatchStealthBoundary()
        guard stealthBoundary.begin(
            generation: generation,
            intent: intent,
            acceptedDispatch: acceptedDispatch
        ) else { return }
        aceHQDispatchStealthBoundary = stealthBoundary
        aceHQDispatchStealthCutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                stealthBoundary.cancelSynchronously()
            }
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier: workID,
            lane: .hq,
            status: .running
        )
        let dispatchTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                if self.aceHQDispatchGeneration == generation {
                    _ = self.retainAceHQInterruptedRetry(
                        from: stealthBoundary,
                        receipt:
                            "HQ dispatch ended before durable terminal publication; exact retry preserved"
                    )
                    self.aceHQDispatchTask = nil
                    if let cutoffIdentifier =
                        self.aceHQDispatchStealthCutoffIdentifier {
                        StealthEntryLatch.shared
                            .unregisterSynchronousEntryCutoff(
                                cutoffIdentifier
                            )
                        self.aceHQDispatchStealthCutoffIdentifier = nil
                    }
                    self.aceHQDispatchStealthBoundary = nil
                    self.aceHQActiveReconciliationAttempt = nil
                }
            }

            var pending: AceHQPendingDispatch
            if let acceptedDispatch {
                guard AceLicense.shared.admits(.companyDispatch),
                      self.directEffectsAreAllowed else {
                    self.retryableAceHQDispatch = RetryableAceHQDispatch(
                        intent: intent,
                        acceptedDispatch: acceptedDispatch,
                        reconciliationAttempt: reconciliationAttempt
                    )
                    _ = self.persistAceHQPendingDispatch(
                        acceptedDispatch,
                        state: .ownerSuspended,
                        reconciliationAttempt: reconciliationAttempt
                    )
                    return
                }
                pending = acceptedDispatch
                let shouldContinue = stealthBoundary.recordPending(
                    acceptedDispatch,
                    generation: generation
                )
                guard shouldContinue else {
                    _ = self.retainAceHQInterruptedRetry(
                        from: stealthBoundary,
                        receipt:
                            "HQ reconciliation was interrupted; exact accepted cursor preserved"
                    )
                    return
                }
                guard self.persistAceHQPendingDispatch(
                    acceptedDispatch,
                    reconciliationAttempt: reconciliationAttempt
                ) else {
                    stealthBoundary.cancelSynchronously()
                    _ = self.retainAceHQInterruptedRetry(
                        from: stealthBoundary,
                        receipt:
                            "HQ accepted cursor was not durably refreshed; exact retry preserved"
                    )
                    return
                }
            } else {
                guard AceLicense.shared.admits(.companyDispatch),
                      self.directEffectsAreAllowed,
                      stealthBoundary.isCurrent(
                        generation: generation
                      ) else {
                    stealthBoundary.cancelSynchronously()
                    self.completeAceHQBeforeDispatch(
                        intent,
                        status: .blocked,
                        message:
                            "Ace company dispatch closed before HQ accepted the request. Nothing ran."
                    )
                    _ = stealthBoundary.consumeInterruptedRetry()
                    return
                }
                switch await client.start(
                    intent,
                    mapping: AceHQCompanyWorkPolicy.seatMapping
                ) {
                case let .accepted(accepted):
                    pending = accepted
                    let shouldContinue = stealthBoundary.recordPending(
                        accepted,
                        generation: generation
                    )
                    if !shouldContinue,
                       let interrupted =
                        stealthBoundary.consumeInterruptedRetry() {
                        self.retryableAceHQDispatch =
                            RetryableAceHQDispatch(
                                intent: interrupted.intent,
                                acceptedDispatch:
                                    interrupted.acceptedDispatch,
                                reconciliationAttempt:
                                    reconciliationAttempt
                            )
                    }
                    guard shouldContinue else {
                        return
                    }
                    guard self.persistAceHQPendingDispatch(
                        accepted,
                        reconciliationAttempt: reconciliationAttempt
                    ) else {
                        stealthBoundary.cancelSynchronously()
                        _ = self.retainAceHQInterruptedRetry(
                            from: stealthBoundary,
                            receipt:
                                "HQ accepted cursor was not durably saved; exact retry preserved"
                        )
                        return
                    }
                    let claim = stealthBoundary
                        .claimAcknowledgementIfCurrent(
                        generation: generation,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        }
                    )
                    guard let claim,
                          let turnID = UUID(
                            uuidString: intent.source.turnID
                          ), let workID = UUID(
                            uuidString: intent.work.correlationID
                          ), stealthBoundary
                            .commitAcknowledgementPublicationIfCurrent(
                        claim,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        },
                        publish: {
                        guard self.directEffectsAreAllowed,
                              AceLicense.shared.admits(
                                .companyDispatch
                              ) else { return false }
                        return AceEventBus.shared.publishOutbound(
                            source: .system,
                            state: .routed,
                            payloadType: .laneReceipt,
                            payload:
                                "hq-handoff=accepted authority="
                                    + accepted.envelope.authority.rawValue
                                    + " seat="
                                    + accepted.envelope.selectedSeat.seatID,
                            turnID: turnID,
                            correlationID: workID
                        )
                        }
                    ) else {
                        _ = self.retainAceHQInterruptedRetry(
                            from: stealthBoundary,
                            receipt:
                                "HQ acceptance publication was interrupted; exact accepted cursor preserved"
                        )
                        return
                    }
                case let .blocked(blocked):
                    let claim = stealthBoundary.claimTerminalIfCurrent(
                        generation: generation,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        }
                    )
                    _ = self.finalizeAceHQTerminalClaim(
                        boundary: stealthBoundary,
                        claim: claim,
                        receipt:
                            "HQ blocked receipt was not durably saved; exact retry preserved",
                        persist: {
                        self.persistAceHQBlocked(
                            intent: blocked.request,
                            acceptedDispatch: nil,
                            code: blocked.code,
                            message: blocked.message,
                            retryable: blocked.retryable,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        },
                        publish: {
                        self.publishAceHQBlocked(
                            intent: blocked.request,
                            acceptedDispatch: nil,
                            code: blocked.code,
                            message: blocked.message,
                            retryable: blocked.retryable,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        }
                    )
                    return
                }
            }

            for _ in 0..<300 {
                guard !Task.isCancelled,
                      AceLicense.shared.admits(.companyDispatch),
                      self.directEffectsAreAllowed,
                      stealthBoundary.isCurrent(
                        generation: generation
                      ),
                      self.aceHQDispatchGeneration == generation else {
                    stealthBoundary.cancelSynchronously()
                    _ = self.persistAceHQPendingDispatch(
                        pending,
                        state: .ownerSuspended,
                        reconciliationAttempt: reconciliationAttempt
                    )
                    _ = self.retainAceHQInterruptedRetry(
                        from: stealthBoundary,
                        receipt:
                            "HQ polling was interrupted; exact accepted cursor preserved"
                    )
                    return
                }
                switch await client.reconcile(pending) {
                case let .running(updated):
                    let previous = pending
                    pending = updated
                    let shouldContinue = stealthBoundary.recordPending(
                        updated,
                        generation: generation
                    )
                    if !shouldContinue,
                       let interrupted =
                        stealthBoundary.consumeInterruptedRetry() {
                        self.retryableAceHQDispatch =
                            RetryableAceHQDispatch(
                                intent: interrupted.intent,
                                acceptedDispatch:
                                    interrupted.acceptedDispatch,
                                reconciliationAttempt:
                                    reconciliationAttempt
                            )
                    }
                    guard shouldContinue else {
                        return
                    }
                    guard self.persistAceHQPendingDispatch(
                        updated,
                        reconciliationAttempt: reconciliationAttempt
                    ) else {
                        stealthBoundary.cancelSynchronously()
                        _ = self.retainAceHQInterruptedRetry(
                            from: stealthBoundary,
                            receipt:
                                "HQ running cursor was not durably saved; exact retry preserved"
                        )
                        return
                    }
                    guard self.publishAceHQExecutionProgress(
                        previous: previous,
                        updated: updated,
                        generation: generation,
                        boundary: stealthBoundary,
                        reconciliationAttempt: reconciliationAttempt
                    ) else {
                        stealthBoundary.cancelSynchronously()
                        _ = self.retainAceHQInterruptedRetry(
                            from: stealthBoundary,
                            receipt:
                                "HQ execution progress publication was interrupted; exact accepted cursor preserved"
                        )
                        return
                    }
                    do {
                        try await Task.sleep(for: .seconds(1))
                    } catch {
                        _ = self.retainAceHQInterruptedRetry(
                            from: stealthBoundary,
                            receipt:
                                "HQ polling was interrupted; exact accepted cursor preserved"
                        )
                        return
                    }
                case let .succeeded(receipt):
                    let claim = stealthBoundary.claimTerminalIfCurrent(
                        generation: generation,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        }
                    )
                    _ = self.finalizeAceHQTerminalClaim(
                        boundary: stealthBoundary,
                        claim: claim,
                        receipt:
                            "HQ success receipt was not durably saved; exact accepted cursor preserved",
                        persist: {
                        self.persistAceHQTerminal(
                            receipt,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        },
                        publish: {
                        self.publishAceHQTerminal(
                            receipt,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        }
                    )
                    return
                case let .failed(receipt):
                    let claim = stealthBoundary.claimTerminalIfCurrent(
                        generation: generation,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        }
                    )
                    _ = self.finalizeAceHQTerminalClaim(
                        boundary: stealthBoundary,
                        claim: claim,
                        receipt:
                            "HQ failure receipt was not durably saved; exact accepted cursor preserved",
                        persist: {
                        self.persistAceHQTerminal(
                            receipt,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        },
                        publish: {
                        self.publishAceHQTerminal(
                            receipt,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        }
                    )
                    return
                case let .blocked(blocked):
                    let claim = stealthBoundary.claimTerminalIfCurrent(
                        generation: generation,
                        performUnlessRaised: {
                            StealthEntryLatch.shared.performUnlessRaised($0)
                        }
                    )
                    _ = self.finalizeAceHQTerminalClaim(
                        boundary: stealthBoundary,
                        claim: claim,
                        receipt:
                            "HQ blocked receipt was not durably saved; exact accepted cursor preserved",
                        persist: {
                        self.persistAceHQBlocked(
                            intent: blocked.request,
                            acceptedDispatch: pending,
                            code: blocked.code,
                            message: blocked.message,
                            retryable: blocked.retryable,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        },
                        publish: {
                        self.publishAceHQBlocked(
                            intent: blocked.request,
                            acceptedDispatch: pending,
                            code: blocked.code,
                            message: blocked.message,
                            retryable: blocked.retryable,
                            reconciliationAttempt:
                                reconciliationAttempt
                        )
                        }
                    )
                    return
                }
            }

            let claim = stealthBoundary.claimTerminalIfCurrent(
                generation: generation,
                performUnlessRaised: {
                    StealthEntryLatch.shared.performUnlessRaised($0)
                }
            )
            _ = self.finalizeAceHQTerminalClaim(
                boundary: stealthBoundary,
                claim: claim,
                receipt:
                    "HQ timeout receipt was not durably saved; exact accepted cursor preserved",
                persist: {
                self.persistAceHQBlocked(
                    intent: intent,
                    acceptedDispatch: pending,
                    code: .hqUnavailable,
                    message:
                        intent.executionTarget == nil
                            ? "HQ has not reported a terminal planning receipt yet."
                            : "HQ has not reported a terminal execution receipt yet.",
                    retryable: true,
                    reconciliationAttempt: reconciliationAttempt
                )
                },
                publish: {
                self.publishAceHQBlocked(
                    intent: intent,
                    acceptedDispatch: pending,
                    code: .hqUnavailable,
                    message:
                        intent.executionTarget == nil
                            ? "HQ has not reported a terminal planning receipt yet."
                            : "HQ has not reported a terminal execution receipt yet.",
                    retryable: true,
                    reconciliationAttempt: reconciliationAttempt
                )
                }
            )
        }
        aceHQDispatchTask = dispatchTask
        guard stealthBoundary.register(
            dispatchTask,
            generation: generation
        ) else {
            aceHQDispatchTask = nil
            return
        }
    }

    /// A normal relaunch resumes only the already-accepted HQ session/turn.
    /// Owner-suspended work remains an explicit retry and is never redispatched.
    private func resumeDurableAceHQDispatchAtNormalStartup() {
        let recovered = recoveredAceHQDispatch
            ?? AceHQPendingDispatchStore.load(
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        recoveredAceHQDispatch = nil
        guard let recovered else { return }
        let reconciliationAttempt = recovered.reconciliationAttempt
        let localWorkCorrelationID = reconciliationAttempt?.work
            .correlationID ?? recovered.pending.intent.work.correlationID
        guard let localWorkIdentifier = UUID(
            uuidString: localWorkCorrelationID
        ) else {
            _ = AceHQPendingDispatchStore.clear(
                expectedWorkCorrelationID:
                    recovered.pending.intent.work.correlationID,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
            return
        }
        let reloaded = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        goldContextBundle = reloaded
        guard let durableWork = reloaded.workRecords.first(where: {
            $0.workCorrelationIdentifier == localWorkIdentifier
        }) else {
            _ = AceHQPendingDispatchStore.clear(
                expectedWorkCorrelationID:
                    recovered.pending.intent.work.correlationID,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
            appendRouteReceipt(
                "HQ stale recovery cursor cleared — local Gold identity missing"
            )
            return
        }
        if durableWork.status != .running {
            if durableWork.status == .blocked,
               durableWork.terminalOutcome?.hasPrefix("blocked.") == true {
                retryableAceHQDispatch = RetryableAceHQDispatch(
                    intent: recovered.pending.intent,
                    acceptedDispatch: recovered.pending,
                    reconciliationAttempt: reconciliationAttempt
                )
                _ = AceHQPendingDispatchStore.save(
                    recovered.pending,
                    state: .ownerSuspended,
                    reconciliationAttempt: reconciliationAttempt,
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared.performUnlessRaised(body)
                    }
                )
                appendRouteReceipt(
                    "HQ blocked accepted cursor recovered for explicit correction child work="
                        + localWorkCorrelationID
                )
            } else {
                retryableAceHQDispatch = nil
                _ = AceHQPendingDispatchStore.clear(
                    expectedWorkCorrelationID:
                        recovered.pending.intent.work.correlationID,
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared.performUnlessRaised(body)
                    }
                )
                appendRouteReceipt(
                    "HQ stale accepted cursor cleared — durable terminal already exists work="
                        + localWorkCorrelationID
                )
            }
            return
        }
        guard AceLicense.shared.admits(.companyDispatch),
              directEffectsAreAllowed,
              aceHQDispatchTask == nil else {
            retryableAceHQDispatch = RetryableAceHQDispatch(
                intent: recovered.pending.intent,
                acceptedDispatch: recovered.pending,
                reconciliationAttempt: reconciliationAttempt
            )
            _ = AceHQPendingDispatchStore.save(
                recovered.pending,
                state: .ownerSuspended,
                reconciliationAttempt: reconciliationAttempt,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
            appendRouteReceipt(
                "HQ relaunch reconciliation held for explicit owner retry work="
                    + recovered.pending.envelope.work.correlationID
            )
            return
        }
        switch recovered.state {
        case .reconciling:
            appendRouteReceipt(
                "HQ relaunch reconciliation resumed work="
                    + recovered.pending.envelope.work.correlationID
            )
            beginAceHQDispatch(
                recovered.pending.intent,
                resuming: recovered.pending,
                reconciliationAttempt: reconciliationAttempt
            )
        case .ownerSuspended:
            retryableAceHQDispatch = RetryableAceHQDispatch(
                intent: recovered.pending.intent,
                acceptedDispatch: recovered.pending,
                reconciliationAttempt: reconciliationAttempt
            )
            appendRouteReceipt(
                "HQ owner-suspended retry recovered work="
                    + recovered.pending.envelope.work.correlationID
            )
        }
    }

    private func persistAceHQPendingDispatch(
        _ pending: AceHQPendingDispatch,
        state: AceHQPendingDispatchRecoveryState = .reconciling,
        reconciliationAttempt: AceHQReconciliationAttempt? = nil
    ) -> Bool {
        AceHQPendingDispatchStore.save(
            pending,
            state: state,
            reconciliationAttempt: reconciliationAttempt,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
    }

    /// The client has already validated phase order and immutable receipt
    /// identity. This surface publishes only after the updated cursor is
    /// durable, and never treats progress as a terminal completion.
    private func publishAceHQExecutionProgress(
        previous: AceHQPendingDispatch,
        updated: AceHQPendingDispatch,
        generation: UUID,
        boundary: AceHQDispatchStealthBoundary,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        guard let progress = AceHQCompanionExecutionPolicy.progress(
            previous: previous,
            updated: updated
        ) else {
            return true
        }
        guard let turnID = UUID(
            uuidString: reconciliationAttempt?.source.turnID
                ?? updated.envelope.source.turnID
        ), let workID = UUID(
            uuidString: reconciliationAttempt?.work.correlationID
                ?? updated.envelope.work.correlationID
        ) else {
            return false
        }
        return performTerminalPublicationUnlessStealth {
            guard boundary.isCurrent(generation: generation),
                  self.aceHQDispatchGeneration == generation else {
                return false
            }
            return AceEventBus.shared.publishOutbound(
                source: .system,
                state: .executing,
                payloadType: .executionReceipt,
                payload:
                    "hq-execution=progress authority="
                        + updated.envelope.authority.rawValue
                        + " execution_id=" + progress.executionID
                        + " phase=" + progress.phase.rawValue
                        + " seat="
                        + updated.envelope.selectedSeat.seatID,
                turnID: turnID,
                correlationID: workID
            )
        }
    }

    private func makeAceHQReconciliationAttempt(
        from request: ContextualOwnerRequest,
        acceptedIntent: AceHQDispatchIntent
    ) -> AceHQReconciliationAttempt? {
        guard let parent = request.parentWorkCorrelationIdentifier,
              let correction = request.correctionContext,
              correction.kind == .retry else { return nil }
        let typedCorrection = AceHQCorrectionContext(
            kind: .retry,
            ownerCorrection: correction.ownerCorrection,
            priorTerminalOutcome: correction.priorTerminalOutcome,
            priorTerminalVerification:
                correction.priorTerminalVerification,
            priorTerminalReason: correction.priorTerminalReason
        )
        let attempt = AceHQReconciliationAttempt(
            acceptedWorkCorrelationID:
                acceptedIntent.work.correlationID,
            source: AceHQSourceTurnIdentity(
                sessionID: request.sourceSessionIdentifier
                    .uuidString.lowercased(),
                turnID: request.sourceTurnIdentifier
                    .uuidString.lowercased(),
                correlationID: request.sourceCorrelationIdentifier
                    .uuidString.lowercased()
            ),
            work: AceHQWorkCorrelation(
                correlationID: request.childWorkCorrelationIdentifier
                    .uuidString.lowercased(),
                parentCorrelationID: parent.uuidString.lowercased(),
                hqWorkID: nil
            ),
            exactOwnerTranscript: request.originalOwnerTranscript,
            resolvedRequest: request.resolvedRequest,
            executionInstruction: request.executionInstruction,
            correctionContext: typedCorrection
        )
        return attempt.isValid(for: acceptedIntent) ? attempt : nil
    }

    /// Binds an exact owner retry to the immutable blocked attempt. A new child
    /// is persisted before either a fresh authorized dispatch or accepted-cursor
    /// reconciliation can begin.
    private func prepareAceHQRetry(
        _ context: OwnerTurnContext
    ) -> PreparedAceHQRetry {
        guard let retryable = retryableAceHQDispatch else {
            return .notSpecial
        }
        let parentCorrelationID = retryable.reconciliationAttempt?.work
            .correlationID ?? retryable.intent.work.correlationID
        guard let parentIdentifier = UUID(
            uuidString: parentCorrelationID
        ) else {
            retryableAceHQDispatch = nil
            return .refused
        }

        goldContextBundle = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        guard var parent = goldContextBundle.workRecords.first(where: {
            $0.workCorrelationIdentifier == parentIdentifier
        }) else {
            retryableAceHQDispatch = nil
            showVisibleResponse(
                "Ace could not reload the exact blocked HQ attempt, so no retry ran."
            )
            return .refused
        }

        // Private Mode entry or entitlement loss may preserve an accepted cursor before a block
        // receipt can be written. The next explicit owner retry first seals that
        // attempt as app-observed interrupted, then creates its child.
        if parent.status == .running {
            let reason =
                "HQ accepted the request, but Ace's reconciliation was interrupted before a terminal receipt was persisted."
            guard persistDurableWorkTerminal(
                workCorrelationIdentifier: parentIdentifier,
                lane: "hq",
                status: .blocked,
                outcome: "blocked.interrupted",
                verification: "none",
                reason: reason
            ), let sealed = goldContextBundle.workRecords.first(where: {
                $0.workCorrelationIdentifier == parentIdentifier
            }) else {
                showVisibleResponse(
                    "Ace could not safely seal the interrupted HQ attempt, so no retry ran."
                )
                return .refused
            }
            parent = sealed
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier: parentIdentifier,
                lane: .hq,
                status: .blocked
            )
        }

        guard parent.status == .blocked,
              parent.terminalOutcome?.hasPrefix("blocked.") == true,
              parent.terminalVerification == "none",
              parent.terminalReason != nil else {
            retryableAceHQDispatch = nil
            _ = AceHQPendingDispatchStore.clear(
                expectedWorkCorrelationID:
                    retryable.intent.work.correlationID,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
            appendRouteReceipt(
                "HQ stale retry cursor cleared — parent is already terminal work="
                    + parentCorrelationID
            )
            showVisibleResponse(
                "That HQ attempt already has a durable terminal result, so it was not retried."
            )
            return .refused
        }

        guard let sourceCorrelationIdentifier =
                activeRoutingCorrelationID else {
            showVisibleResponse(
                "Ace could not bind this retry to one exact HQ attempt, so nothing ran."
            )
            return .refused
        }
        let child = ContextualOwnerRequest(
            originalOwnerTranscript: context.exactInput,
            resolvedRequest: retryable.intent.resolvedRequest,
            correctionContext: OwnerCorrectionContext(
                kind: .retry,
                ownerCorrection: context.exactInput,
                priorTerminalOutcome: parent.terminalOutcome,
                priorTerminalVerification: parent.terminalVerification,
                priorTerminalReason: parent.terminalReason
            ),
            sourceSessionIdentifier: context.sessionID,
            sourceTurnIdentifier: context.turnID,
            sourceCorrelationIdentifier: sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier: parentIdentifier,
            childWorkCorrelationIdentifier: UUID(),
            referenceKind: .pronoun,
            resolutionStatus: .resolved
        )
        let lane = retryable.acceptedDispatch == nil
            ? "hq.retry" : "hq.reconcile"
        guard goldContextBundle.recordWork(
            request: child,
            lane: lane,
            status: .running
        ), AceConversationHistory.saveBundle(
            goldContextBundle,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        ) else {
            showVisibleResponse(
                "Ace could not persist the HQ correction child, so nothing ran."
            )
            return .refused
        }
        _ = recentOwnerWorkStore.recordExecution(
            originalOwnerTranscript: child.originalOwnerTranscript,
            resolvedRequest: child.resolvedRequest,
            sourceSessionIdentifier: child.sourceSessionIdentifier,
            sourceTurnIdentifier: child.sourceTurnIdentifier,
            sourceCorrelationIdentifier:
                child.sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier:
                child.parentWorkCorrelationIdentifier,
            workCorrelationIdentifier:
                child.childWorkCorrelationIdentifier,
            lane: .hq,
            status: .running
        )
        activeContextualOwnerRequest = child

        guard let accepted = retryable.acceptedDispatch else {
            retryableAceHQDispatch = nil
            return .newDispatch(
                request: child,
                capability: retryable.intent.requestedCapability
            )
        }
        guard let attempt = makeAceHQReconciliationAttempt(
            from: child,
            acceptedIntent: retryable.intent
        ), persistAceHQPendingDispatch(
            accepted,
            state: .ownerSuspended,
            reconciliationAttempt: attempt
        ) else {
            completeAceHQBeforeDispatch(
                child,
                status: .blocked,
                message:
                    "Ace could not persist the accepted HQ cursor with its correction child. Nothing ran."
            )
            return .refused
        }
        let prepared = RetryableAceHQDispatch(
            intent: retryable.intent,
            acceptedDispatch: accepted,
            reconciliationAttempt: attempt
        )
        retryableAceHQDispatch = prepared
        return .reconcile(prepared)
    }

    private func discardAceHQRetryIfDurablyTerminal() {
        guard let retryable = retryableAceHQDispatch else { return }
        let localCorrelationID = retryable.reconciliationAttempt?.work
            .correlationID ?? retryable.intent.work.correlationID
        guard let localIdentifier = UUID(
            uuidString: localCorrelationID
        ) else {
            retryableAceHQDispatch = nil
            return
        }
        let reloaded = AceConversationHistory.loadBundle(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        guard let work = reloaded.workRecords.first(where: {
            $0.workCorrelationIdentifier == localIdentifier
        }) else { return }
        goldContextBundle = reloaded
        guard work.status != .running,
              !(work.status == .blocked
                && work.terminalOutcome?.hasPrefix("blocked.") == true) else {
            return
        }
        retryableAceHQDispatch = nil
        _ = AceHQPendingDispatchStore.clear(
            expectedWorkCorrelationID:
                retryable.intent.work.correlationID,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
    }

    /// A terminal reservation establishes ordering only. Durable truth must be
    /// saved before the boundary consumes the exact intent/cursor identity.
    @discardableResult
    private func finalizeAceHQTerminalClaim(
        boundary: AceHQDispatchStealthBoundary,
        claim: AceHQDispatchTerminalClaim?,
        receipt: String,
        persist: () -> Bool,
        publish: @escaping () -> Bool
    ) -> Bool {
        guard let claim else {
            _ = retainAceHQInterruptedRetry(
                from: boundary,
                receipt: receipt
            )
            return false
        }
        let persisted = AceHQDispatchTerminalFinalizer.finalize(
            claim: claim,
            body: persist
        ) ?? false
        let finalized = boundary.finalizeTerminalClaim(
            claim,
            persisted: persisted
        )
        guard finalized else {
            _ = retainAceHQInterruptedRetry(
                from: boundary,
                receipt: receipt
            )
            return false
        }
        _ = boundary.commitTerminalPublicationIfFinalized(
            claim,
            performUnlessRaised: {
                StealthEntryLatch.shared.performUnlessRaised($0)
            },
            publish: {
                guard self.directEffectsAreAllowed,
                      AceLicense.shared.admits(.companyDispatch) else {
                    return false
                }
                return publish()
            }
        )
        return true
    }

    /// Consumes a boundary snapshot before the task's defer releases it. A
    /// later owner retry resumes the exact accepted cursor and never fabricates
    /// a terminal result whose durable save was blocked by Stealth.
    @discardableResult
    private func retainAceHQInterruptedRetry(
        from boundary: AceHQDispatchStealthBoundary,
        receipt: String
    ) -> Bool {
        guard let interrupted = boundary.consumeInterruptedRetry() else {
            return false
        }
        retryableAceHQDispatch = RetryableAceHQDispatch(
            intent: interrupted.intent,
            acceptedDispatch: interrupted.acceptedDispatch,
            reconciliationAttempt:
                aceHQActiveReconciliationAttempt
        )
        if let workID = UUID(
            uuidString: aceHQActiveReconciliationAttempt?.work
                .correlationID
                ?? interrupted.intent.work.correlationID
        ) {
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier: workID,
                lane: .hq,
                status: .blocked
            )
        }
        appendRouteReceipt(receipt)
        return true
    }

    /// X invokes the boundary directly on the event-tap thread; this MainActor
    /// reconciliation preserves the exact accepted request as an explicit retry
    /// and never resumes polling automatically when Stealth later exits.
    private func cancelAceHQDispatchSynchronouslyForStealth() {
        aceHQDispatchStealthBoundary?.cancelSynchronously()
        aceHQDispatchGeneration = UUID()
        aceHQDispatchTask?.cancel()
        aceHQDispatchTask = nil

        if let boundary = aceHQDispatchStealthBoundary {
            _ = retainAceHQInterruptedRetry(
                from: boundary,
                receipt:
                    "HQ dispatch suspended by STEALTH; exact retry preserved"
            )
        }
        // Under a real Private Mode entry this returns immediately because the latch is raised.
        // Entitlement shutdown uses the same cancellation path while the latch
        // is open, so it can durably convert an accepted cursor into an explicit
        // owner retry rather than allowing automatic relaunch reconciliation.
        _ = AceHQPendingDispatchStore.suspendCurrent(
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
        if let cutoffIdentifier = aceHQDispatchStealthCutoffIdentifier {
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier
            )
            aceHQDispatchStealthCutoffIdentifier = nil
        }
        aceHQDispatchStealthBoundary = nil
    }

    @discardableResult
    private func handleAceHQBlocked(
        intent: AceHQDispatchIntent,
        acceptedDispatch: AceHQPendingDispatch?,
        code: AceHQDispatchBlockCode,
        message: String,
        retryable: Bool,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        guard persistAceHQBlocked(
            intent: intent,
            acceptedDispatch: acceptedDispatch,
            code: code,
            message: message,
            retryable: retryable,
            reconciliationAttempt: reconciliationAttempt
        ) else { return false }
        if retryable {
            retryableAceHQDispatch = RetryableAceHQDispatch(
                intent: intent,
                acceptedDispatch: acceptedDispatch,
                reconciliationAttempt: reconciliationAttempt
            )
        }
        return performTerminalPublicationUnlessStealth { [weak self] in
            guard let self,
                  AceLicense.shared.admits(.companyDispatch) else {
                return false
            }
            return self.publishAceHQBlocked(
                intent: intent,
                acceptedDispatch: acceptedDispatch,
                code: code,
                message: message,
                retryable: retryable,
                reconciliationAttempt: reconciliationAttempt
            )
        }
    }

    private func persistAceHQBlocked(
        intent: AceHQDispatchIntent,
        acceptedDispatch: AceHQPendingDispatch?,
        code: AceHQDispatchBlockCode,
        message: String,
        retryable: Bool,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        let bounded = Self.retainedAppResult(
            message,
            fallback: intent.executionTarget == nil
                ? "The HQ planning handoff is blocked."
                : "The HQ execution handoff is blocked."
        )
        guard let workID = UUID(
            uuidString: reconciliationAttempt?.work.correlationID
                ?? intent.work.correlationID
        ) else {
            return false
        }
        let status: AceGoldWorkStatus = retryable ? .blocked : .failed
        let outcome = (retryable ? "blocked." : "failed.")
            + code.rawValue
        guard persistDurableWorkTerminal(
            workCorrelationIdentifier: workID,
            lane: reconciliationAttempt == nil ? "hq" : "hq.reconcile",
            status: status,
            outcome: outcome,
            verification: "none",
            reason: bounded
        ) else { return false }
        if retryable, let acceptedDispatch {
            return persistAceHQPendingDispatch(
                acceptedDispatch,
                state: .ownerSuspended,
                reconciliationAttempt: reconciliationAttempt
            )
        } else {
            return AceHQPendingDispatchStore.clear(
                expectedWorkCorrelationID: intent.work.correlationID,
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                }
            )
        }
    }

    private func publishAceHQBlocked(
        intent: AceHQDispatchIntent,
        acceptedDispatch: AceHQPendingDispatch?,
        code: AceHQDispatchBlockCode,
        message: String,
        retryable: Bool,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        guard directEffectsAreAllowed,
              AceLicense.shared.admits(.companyDispatch) else {
            return false
        }
        let bounded = Self.boundedSpokenAppResult(
            message,
            fallback: intent.executionTarget == nil
                ? "The HQ planning handoff is blocked."
                : "The HQ execution handoff is blocked."
        )
        guard let turnID = UUID(
            uuidString: reconciliationAttempt?.source.turnID
                ?? intent.source.turnID
        ), let workID = UUID(
            uuidString: reconciliationAttempt?.work.correlationID
                ?? intent.work.correlationID
        ) else {
            return false
        }
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier: workID,
            lane: .hq,
            status: retryable ? .blocked : .failed
        )
        if retryable {
            retryableAceHQDispatch = RetryableAceHQDispatch(
                intent: intent,
                acceptedDispatch: acceptedDispatch,
                reconciliationAttempt: reconciliationAttempt
            )
        }
        guard AceEventBus.shared.publishTerminalWork(
            source: .system,
            state: .failed,
            payloadType: .laneReceipt,
            payload:
                "hq-handoff=blocked authority="
                    + (intent.executionTarget == nil
                        ? AceHQDispatchAuthority.planOnly.rawValue
                        : AceHQDispatchAuthority.executeWhitelisted
                            .rawValue)
                    + " retryable="
                    + (retryable ? "true" : "false")
                    + " code=" + code.rawValue,
            turnID: turnID,
            correlationID: workID
        ) else { return false }
        let spoken = retryable
            ? "\(bounded) The exact request is preserved; say retry that."
            : bounded
        showVisibleResponse(spoken)
        Task { @MainActor [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive,
                  !StealthEntryLatch.shared.isRaised,
                  AceLicense.shared.admits(.companyDispatch) else {
                return
            }
            _ = await self.noraVoice.speakTextToVerifiedCompletion(spoken)
        }
        return true
    }

    private func persistAceHQTerminal(
        _ receipt: AceHQTerminalReceipt,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        let disposition =
            AceHQCompanionExecutionPolicy.terminalDisposition(receipt)
        guard disposition != .invalid else { return false }
        guard let workID = UUID(
            uuidString: reconciliationAttempt?.work.correlationID
                ?? receipt.work.correlationID
        ) else {
            return false
        }
        let succeeded = disposition == .reportedPlanSuccess
            || disposition == .verifiedExecutionSuccess
        let output = Self.retainedAppResult(
            receipt.output,
            fallback: receipt.executionTarget == nil
                ? "HQ returned no readable planning report."
                : "HQ returned no readable execution report."
        )
        let persisted = persistDurableWorkTerminal(
            workCorrelationIdentifier: workID,
            lane: "hq.\(receipt.selectedSeat.seatID)",
            status: succeeded ? .completed : .failed,
            outcome: receipt.outcome.rawValue,
            verification: receipt.verificationState.rawValue,
            reason: output
        )
        guard persisted else { return false }
        return AceHQPendingDispatchStore.clear(
            expectedWorkCorrelationID: receipt.work.correlationID,
            performUnlessRaised: { body in
                StealthEntryLatch.shared.performUnlessRaised(body)
            }
        )
    }

    private func publishAceHQTerminal(
        _ receipt: AceHQTerminalReceipt,
        reconciliationAttempt: AceHQReconciliationAttempt?
    ) -> Bool {
        guard directEffectsAreAllowed,
              AceLicense.shared.admits(.companyDispatch) else {
            return false
        }
        let disposition =
            AceHQCompanionExecutionPolicy.terminalDisposition(receipt)
        guard disposition != .invalid else { return false }
        guard let turnID = UUID(
            uuidString: reconciliationAttempt?.source.turnID
                ?? receipt.source.turnID
        ), let workID = UUID(
            uuidString: reconciliationAttempt?.work.correlationID
                ?? receipt.work.correlationID
        ) else {
            return false
        }
        let succeeded = disposition == .reportedPlanSuccess
            || disposition == .verifiedExecutionSuccess
        let state: AceEventState = succeeded ? .completed : .failed
        let output = Self.boundedSpokenAppResult(
            receipt.output,
            fallback: receipt.executionTarget == nil
                ? "HQ returned no readable planning report."
                : "HQ returned no readable execution report."
        )
        let authority = receipt.executionTarget == nil
            ? AceHQDispatchAuthority.planOnly
            : AceHQDispatchAuthority.executeWhitelisted
        let targetLabel = receipt.executionTarget?.id.rawValue
            ?? "the canonical target"
        let spoken: String
        switch disposition {
        case .reportedPlanSuccess:
            spoken =
                "HQ's plan-only \(receipt.selectedSeat.seatID) reported: \(output)"
        case .reportedPlanFailure:
            spoken =
                "HQ's plan-only \(receipt.selectedSeat.seatID) reported a failure: \(output)"
        case .verifiedExecutionSuccess:
            spoken =
                "HQ's \(receipt.selectedSeat.seatID) verified the execution on \(targetLabel): \(output)"
        case .reportedExecutionFailure:
            spoken =
                "HQ's \(receipt.selectedSeat.seatID) reported an execution failure on \(targetLabel): \(output)"
        case .invalid:
            return false
        }
        retryableAceHQDispatch = nil
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier: workID,
            lane: .hq,
            status: succeeded ? .completed : .failed
        )
        guard AceEventBus.shared.publishTerminalWork(
            source: .system,
            state: state,
            payloadType: .laneReceipt,
            payload:
                "hq-handoff=terminal authority="
                    + authority.rawValue
                    + " outcome="
                    + receipt.outcome.rawValue
                    + " verification=" + receipt.verificationState.rawValue
                    + " seat=" + receipt.selectedSeat.seatID
                    + (receipt.executionTarget.map {
                        " target=" + $0.id.rawValue
                    } ?? ""),
            turnID: turnID,
            correlationID: workID
        ) else { return false }
        showVisibleResponse(spoken)
        Task { @MainActor [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive,
                  !StealthEntryLatch.shared.isRaised,
                  AceLicense.shared.admits(.companyDispatch) else {
                return
            }
            let completed = await self.noraVoice
                .speakTextToVerifiedCompletion(spoken)
            if completed, self.partnerModeIsActive {
                self.beginAutomaticPartnerListeningIfAllowed()
            }
        }
        return true
    }

    private func completeAceHQBeforeDispatch(
        _ request: ContextualOwnerRequest,
        status: RecentOwnerWorkStatus,
        message: String,
        speak: Bool = true,
        authority: AceHQDispatchAuthority = .planOnly
    ) {
        finishAceHQPreDispatchTerminal(
            DeferredAceHQPreDispatchTerminal(
                turnIdentifier: request.sourceTurnIdentifier,
                workCorrelationIdentifier:
                    request.childWorkCorrelationIdentifier,
                authority: authority,
                status: status,
                message: message,
                speak: speak,
                persistenceCompleted: false
            )
        )
    }

    private func completeAceHQBeforeDispatch(
        _ intent: AceHQDispatchIntent,
        status: RecentOwnerWorkStatus,
        message: String,
        speak: Bool = true
    ) {
        guard let turnIdentifier = UUID(
            uuidString: intent.source.turnID
        ), let workCorrelationIdentifier = UUID(
            uuidString: intent.work.correlationID
        ) else {
            appendRouteReceipt(
                "HQ pre-dispatch terminal refused malformed identity"
            )
            return
        }
        finishAceHQPreDispatchTerminal(
            DeferredAceHQPreDispatchTerminal(
                turnIdentifier: turnIdentifier,
                workCorrelationIdentifier: workCorrelationIdentifier,
                authority: intent.executionTarget == nil
                    ? .planOnly
                    : .executeWhitelisted,
                status: status,
                message: message,
                speak: speak,
                persistenceCompleted: false
            )
        )
    }

    private func finishAceHQPreDispatchTerminal(
        _ terminal: DeferredAceHQPreDispatchTerminal
    ) {
        if let existing = deferredAceHQPreDispatchTerminals[
            terminal.workCorrelationIdentifier
        ] {
            guard existing.turnIdentifier == terminal.turnIdentifier,
                  existing.authority == terminal.authority,
                  existing.status == terminal.status,
                  existing.message == terminal.message,
                  existing.speak == terminal.speak else {
                appendRouteReceipt(
                    "HQ deferred pre-dispatch terminal conflict refused work="
                        + terminal.workCorrelationIdentifier
                            .uuidString.lowercased()
                )
                return
            }
            _ = retryDeferredAceHQPreDispatchTerminal(existing)
            return
        }
        deferredAceHQPreDispatchTerminals[
            terminal.workCorrelationIdentifier
        ] = terminal
        _ = retryDeferredAceHQPreDispatchTerminal(terminal)
    }

    @discardableResult
    private func retryDeferredAceHQPreDispatchTerminal(
        _ terminal: DeferredAceHQPreDispatchTerminal
    ) -> Bool {
        let candidate = terminal
        let outcome = AceHQDurablePublicationGate.finish(
            persistenceCompleted: candidate.persistenceCompleted,
            persist: { [weak self] in
                guard let self else { return false }
                return self.persistDurableWorkTerminal(
                    workCorrelationIdentifier:
                        candidate.workCorrelationIdentifier,
                    lane: "hq",
                    status: self.durableAceHQStatus(candidate.status),
                    outcome: candidate.status.rawValue,
                    verification: "none",
                    reason: candidate.message
                )
            },
            publishUnlessRaised: { [weak self] publication in
                guard let self,
                      AceLicense.shared.admits(.companyDispatch) else {
                    return false
                }
                return self.performTerminalPublicationUnlessStealth(
                    publication
                )
            },
            publish: { [weak self] in
                guard let self else { return false }
                let state: AceEventState =
                    candidate.status == .cancelled
                        ? .cancelled
                        : .failed
                guard AceEventBus.shared.publishTerminalWork(
                    source: .system,
                    state: state,
                    payloadType: .laneReceipt,
                    payload:
                        "hq-handoff=not-started authority="
                            + candidate.authority.rawValue,
                    turnID: candidate.turnIdentifier,
                    correlationID:
                        candidate.workCorrelationIdentifier
                ) else { return false }
                _ = self.recentOwnerWorkStore.transition(
                    workCorrelationIdentifier:
                        candidate.workCorrelationIdentifier,
                    lane: .hq,
                    status: candidate.status
                )
                return true
            }
        )
        switch outcome {
        case .persistenceDeferred:
            var retained = candidate
            retained.persistenceCompleted = false
            deferredAceHQPreDispatchTerminals[
                retained.workCorrelationIdentifier
            ] = retained
            return false
        case .publicationDeferred:
            var retained = candidate
            retained.persistenceCompleted = true
            deferredAceHQPreDispatchTerminals[
                retained.workCorrelationIdentifier
            ] = retained
            return false
        case .published:
            deferredAceHQPreDispatchTerminals.removeValue(
                forKey: candidate.workCorrelationIdentifier
            )
            _ = performTerminalPublicationUnlessStealth { [weak self] in
                self?.showVisibleResponse(candidate.message)
                return self != nil
            }
            if candidate.speak {
                Task { @MainActor [weak self] in
                    guard let self,
                          self.directEffectsAreAllowed,
                          !self.stealthMode.isActive,
                          !StealthEntryLatch.shared.isRaised,
                          AceLicense.shared.admits(.companyDispatch) else {
                        return
                    }
                    _ = await self.noraVoice
                        .speakTextToVerifiedCompletion(candidate.message)
                }
            }
            return true
        }
    }

    private func durableAceHQStatus(
        _ status: RecentOwnerWorkStatus
    ) -> AceGoldWorkStatus {
        switch status {
        case .completed: return .completed
        case .cancelled: return .cancelled
        case .failed: return .failed
        case .blocked, .awaitingConfirmation, .running:
            return .blocked
        }
    }

    private var agentCapabilityConsentPreview: String {
        """
        Full access for company dispatch and silver workflows

        File access: Every mounted folder and file this macOS account can access, including personal files, removable drives, and hidden configuration.

        Capabilities:
        \(AgentCapabilityConsentPolicy.buyerFacingScopeList)

        This approval is stored on this Mac. Company and whole-job workflow operations may still require an exact plan confirmation. Red Agent uses the selected CLI's full-access mode immediately for an admitted owner turn and is not gated by this review.
        """
    }

    private func hasCompleteAgentCapabilityConsent() -> Bool {
        completeAgentCapabilityConsentReceipt() != nil
    }

    private func completeAgentCapabilityConsentReceipt()
        -> AgentCapabilityConsentReceipt? {
        do {
            let receipt = try AgentCapabilityConsentStore.shared.load()
            guard AgentCapabilityConsentPolicy.decision(
                receipt: receipt,
                requestedPaths: ["/"],
                consequential: false,
                taskConfirmed: false
            ) == .allowed else {
                return nil
            }
            return receipt
        } catch {
            appendRouteReceipt(
                "AGENT-CONSENT receipt rejected errorType="
                    + String(describing: type(of: error))
            )
            return nil
        }
    }

    private func durableHQCapabilityConsent(
        from receipt: AgentCapabilityConsentReceipt
    ) -> AceHQDurableCapabilityConsent {
        AceHQDurableCapabilityConsent(
            receiptReference:
                AceHQCapabilityConsentEvidence.durableReceiptReference,
            receiptSchemaVersion: receipt.schemaVersion,
            approvedScopes:
                receipt.approvedScopes.map(\.rawValue).sorted(),
            approvedWorkspaceRoots:
                receipt.approvedWorkspaceRoots.sorted(),
            approvedAt: receipt.approvedAt
        )
    }

    @discardableResult
    private func requireAgentCapabilityConsent(
        for lane: PendingAgentCapabilityLane,
        request: String,
        executionInstruction: String? = nil,
        directWorkCorrelationIdentifier: UUID? = nil
    ) -> Bool {
        guard hasCompleteAgentCapabilityConsent() else {
            requestAgentCapabilityConsent(
                for: lane,
                request: request,
                executionInstruction:
                    executionInstruction ?? request,
                directWorkCorrelationIdentifier:
                    directWorkCorrelationIdentifier
            )
            return false
        }
        return true
    }

    private func requestAgentCapabilityConsent(
        for lane: PendingAgentCapabilityLane,
        request: String,
        executionInstruction: String,
        directWorkCorrelationIdentifier: UUID?
    ) {
        guard directEffectsAreAllowed else { return }

        agentCapabilityConsentExpiryTask?.cancel()
        let reviewIdentifier = UUID()
        if let hqContinuation = pendingAceHQCapabilityRequest,
           hqContinuation.consentReviewIdentifier == nil {
            pendingAceHQCapabilityRequest =
                hqContinuation.bound(to: reviewIdentifier)
        }
        let pending = PendingAgentCapabilityConsent(
            reviewIdentifier: reviewIdentifier,
            lane: lane,
            request: request,
            executionInstruction: executionInstruction,
            directWorkCorrelationIdentifier:
                directWorkCorrelationIdentifier,
            requestedAt: Date()
        )
        pendingAgentCapabilityConsent = pending
        let preview = agentCapabilityConsentPreview
        appActionReview = AppActionReviewState(
            planIdentifier: reviewIdentifier,
            exactPreview: preview,
            phase: .reading
        )
        appendRouteReceipt(
            "AGENT-CONSENT review started lane=\(lane.rawValue)"
        )

        agentCapabilityConsentExpiryTask = Task { [weak self] in
            guard let self else { return }
            let completed =
                await self.noraVoice
                    .speakVerbatimTextToVerifiedCompletion(
                        "review this complete access request. \(preview)"
                    )
            guard !Task.isCancelled,
                  self.directEffectsAreAllowed,
                  self.pendingAgentCapabilityConsent?.reviewIdentifier
                    == reviewIdentifier,
                  self.appActionReview?.planIdentifier
                    == reviewIdentifier else {
                return
            }
            guard completed else {
                _ = self.finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        pending.directWorkCorrelationIdentifier,
                    lane: lane == .company ? .gold : .silver,
                    durableLane: lane == .company ? "company" : "silver",
                    status: .blocked,
                    outcome: "blocked.consent-readback-incomplete",
                    verification: "none",
                    reason:
                        "The full-access consent readback did not complete. Nothing ran.",
                    slot: .none,
                    source: lane == .company ? .gold : .silver,
                    turnIdentifier: self.sourceTurnIdentifier(
                        forWork: pending.directWorkCorrelationIdentifier
                    )
                )
                self.pendingAgentCapabilityConsent = nil
                self.cancelPendingAceHQCapabilityContinuation(
                    reviewIdentifier: reviewIdentifier,
                    message:
                        "The HQ capability readback did not complete. Nothing ran."
                )
                self.agentCapabilityConsentExpiryTask = nil
                // Fail closed — an unfinished readback never arms consent. But
                // say WHY and what to do: a silent "blocked" card with a dead
                // button is indistinguishable from a broken app, and the buyer
                // is left re-asking forever with no idea a readback is owed.
                self.appActionReview = AppActionReviewState(
                    planIdentifier: reviewIdentifier,
                    exactPreview: preview,
                    phase: .notArmed(
                        reason:
                            "The full access review was cut off before it finished reading."
                            + " Nothing was approved and company dispatch stays blocked."
                            + " Ask again to hear the full review — approve it once"
                            + " and Ace will not ask again."
                    )
                )
                self.appendRouteReceipt(
                    "AGENT-CONSENT readback incomplete lane=\(lane.rawValue)"
                )
                Task { [weak self] in
                    try? await self?.noraVoice.speakText(
                        "that full access review got cut off, so nothing was approved."
                            + " consent only counts when you hear the whole review,"
                            + " so say the word and i'll read it from the top."
                    )
                }
                return
            }

            let armed = PendingAgentCapabilityConsent(
                reviewIdentifier: reviewIdentifier,
                lane: lane,
                request: request,
                executionInstruction: executionInstruction,
                directWorkCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                requestedAt: Date()
            )
            self.pendingAgentCapabilityConsent = armed
            self.appActionReview = AppActionReviewState(
                planIdentifier: reviewIdentifier,
                exactPreview: preview,
                phase: .ready(expiresAt: armed.expiresAt)
            )
            self.appendRouteReceipt(
                "AGENT-CONSENT review complete lane=\(lane.rawValue) window=30s"
            )
            self.agentCapabilityConsentExpiryTask = Task { [weak self] in
                do {
                    try await Task.sleep(
                        for: .seconds(
                            CrossAppActionPolicy.confirmationLifetime
                        )
                    )
                } catch {
                    return
                }
                guard let self,
                      self.pendingAgentCapabilityConsent?.reviewIdentifier
                        == reviewIdentifier else {
                    return
                }
                _ = self.finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        armed.directWorkCorrelationIdentifier,
                    lane: lane == .company ? .gold : .silver,
                    durableLane: lane == .company ? "company" : "silver",
                    status: .blocked,
                    outcome: "blocked.capability-consent-expired",
                    verification: "none",
                    reason: "Full-access consent expired. Nothing ran.",
                    slot: .none,
                    source: lane == .company ? .gold : .silver,
                    turnIdentifier: self.sourceTurnIdentifier(
                        forWork: armed.directWorkCorrelationIdentifier
                    )
                )
                self.pendingAgentCapabilityConsent = nil
                self.cancelPendingAceHQCapabilityContinuation(
                    reviewIdentifier: reviewIdentifier,
                    message:
                        "The HQ capability approval expired. Nothing ran."
                )
                self.agentCapabilityConsentExpiryTask = nil
                self.appActionReview = AppActionReviewState(
                    planIdentifier: reviewIdentifier,
                    exactPreview: preview,
                    phase: .notArmed(
                        reason:
                            "Full access approval expired. Company dispatch and silver workflows remain blocked."
                    )
                )
                self.appendRouteReceipt(
                    "AGENT-CONSENT expired lane=\(lane.rawValue)"
                )
            }
            try? await self.noraVoice.speakText(
                "the complete access list is ready. say confirm within thirty seconds, or say cancel."
            )
        }
    }

    private func resolvePendingAgentCapabilityConsent(
        with utterance: String
    ) -> Bool {
        guard let pending = pendingAgentCapabilityConsent else {
            return false
        }
        guard let review = appActionReview,
              review.planIdentifier == pending.reviewIdentifier else {
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    pending.directWorkCorrelationIdentifier,
                lane: pending.lane == .company ? .gold : .silver,
                durableLane:
                    pending.lane == .company ? "company" : "silver",
                status: .blocked,
                outcome: "blocked.consent-review-missing",
                verification: "none",
                reason:
                    "The full-access review was no longer visible. Nothing ran.",
                slot: .none,
                source: pending.lane == .company ? .gold : .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: pending.directWorkCorrelationIdentifier
                )
            )
            pendingAgentCapabilityConsent = nil
            cancelPendingAceHQCapabilityContinuation(
                reviewIdentifier: pending.reviewIdentifier,
                message:
                    "The HQ capability review was no longer visible. Nothing ran."
            )
            agentCapabilityConsentExpiryTask?.cancel()
            agentCapabilityConsentExpiryTask = nil
            appendRouteReceipt(
                "AGENT-CONSENT blocked missing visible review"
            )
            return false
        }

        if CrossAppActionPolicy.isExplicitConfirmation(utterance) {
            guard case .ready = review.phase else {
                cancelAgentCapabilityConsent(
                    review: review,
                    reason:
                        "The complete access review had not finished. Company dispatch and silver workflows remain blocked."
                )
                return true
            }
            confirmAgentCapabilityConsent(pending, review: review)
            return true
        }
        if CrossAppActionPolicy.isExplicitCancellation(utterance) {
            cancelAgentCapabilityConsent(
                review: review,
                reason:
                    "Full access was not approved. Company dispatch and silver workflows remain blocked."
            )
            Task { try? await noraVoice.speakText("okay. full access remains off.") }
            return true
        }

        cancelAgentCapabilityConsent(
            review: review,
            reason:
                "The wording changed. Full access was not approved; company dispatch and silver workflows remain blocked."
        )
        rerouteActiveOwnerTurn()
        return true
    }

    private func confirmAgentCapabilityConsent(
        _ pending: PendingAgentCapabilityConsent,
        review: AppActionReviewState
    ) {
        guard pending.isCurrent(at: Date()) else {
            cancelAgentCapabilityConsent(
                review: review,
                reason:
                    "Full access approval expired. Company dispatch and silver workflows remain blocked."
            )
            Task {
                try? await noraVoice.speakText(
                    "that full access approval expired before it was confirmed,"
                        + " so nothing was approved and nothing ran."
                        + " say the word and i'll put the review back up."
                )
            }
            return
        }

        do {
            try AgentCapabilityConsentStore.shared.save(
                .complete(workspaceRoots: ["/"])
            )
        } catch {
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    pending.directWorkCorrelationIdentifier,
                lane: pending.lane == .company ? .gold : .silver,
                durableLane:
                    pending.lane == .company ? "company" : "silver",
                status: .blocked,
                outcome: "blocked.consent-save-failed",
                verification: "none",
                reason:
                    "Ace could not store full-access consent securely. Nothing ran.",
                slot: .none,
                source: pending.lane == .company ? .gold : .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: pending.directWorkCorrelationIdentifier
                )
            )
            pendingAgentCapabilityConsent = nil
            cancelPendingAceHQCapabilityContinuation(
                reviewIdentifier: review.planIdentifier,
                message:
                    "The HQ capability approval could not be stored. Nothing ran."
            )
            agentCapabilityConsentExpiryTask?.cancel()
            agentCapabilityConsentExpiryTask = nil
            appActionReview = AppActionReviewState(
                planIdentifier: review.planIdentifier,
                exactPreview: review.exactPreview,
                phase: .notArmed(
                    reason:
                        "Ace could not store the full access approval privately. Company dispatch and silver workflows remain blocked."
                )
            )
            appendRouteReceipt(
                "AGENT-CONSENT save failed errorType="
                    + String(describing: type(of: error))
            )
            Task {
                try? await noraVoice.speakText(
                    "i could not save that approval securely, so full access remains off."
                )
            }
            return
        }

        pendingAgentCapabilityConsent = nil
        agentCapabilityConsentExpiryTask?.cancel()
        agentCapabilityConsentExpiryTask = nil
        noraVoice.stopPlayback()
        appActionReview = AppActionReviewState(
            planIdentifier: review.planIdentifier,
            exactPreview: review.exactPreview,
            phase: .notArmed(
                reason:
                    "Full access approved on this Mac. Resuming the original \(pending.lane.rawValue) request."
            )
        )
        appendRouteReceipt(
            "AGENT-CONSENT approved lane=\(pending.lane.rawValue)"
        )

        switch pending.lane {
        case .company:
            if let hqRequest = pendingAceHQCapabilityRequest,
               hqRequest.matches(
                   reviewIdentifier: review.planIdentifier,
                   request: pending.request,
                   sourceSessionIdentifier:
                       hqRequest.request.sourceSessionIdentifier,
                   sourceTurnIdentifier:
                       hqRequest.request.sourceTurnIdentifier,
                   sourceCorrelationIdentifier:
                       hqRequest.request.sourceCorrelationIdentifier,
                   workCorrelationIdentifier:
                       hqRequest.request.childWorkCorrelationIdentifier
               ) {
                pendingAceHQCapabilityRequest = nil
                routeAceHQCompanyWork(
                    request: hqRequest.request,
                    capability: hqRequest.capability
                )
            }
        case .silver:
            routeWorkflowRequest(
                pending.request,
                executionInstruction:
                    pending.executionInstruction,
                directWorkCorrelationIdentifier:
                    pending.directWorkCorrelationIdentifier
            )
        }
    }

    private func cancelAgentCapabilityConsent(
        review: AppActionReviewState,
        reason: String
    ) {
        let directWorkCorrelationIdentifier =
            pendingAgentCapabilityConsent?
                .directWorkCorrelationIdentifier
        let directLane = pendingAgentCapabilityConsent?.lane
        pendingAgentCapabilityConsent = nil
        cancelPendingAceHQCapabilityContinuation(
            reviewIdentifier: review.planIdentifier,
            message: "The HQ capability approval was cancelled. Nothing ran."
        )
        agentCapabilityConsentExpiryTask?.cancel()
        agentCapabilityConsentExpiryTask = nil
        noraVoice.stopPlayback()
        appActionReview = AppActionReviewState(
            planIdentifier: review.planIdentifier,
            exactPreview: review.exactPreview,
            phase: .notArmed(reason: reason)
        )
        appendRouteReceipt("AGENT-CONSENT blocked reason=not-approved")
        if let directWorkCorrelationIdentifier,
           let directLane {
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                lane: directLane == .company ? .gold : .silver,
                durableLane:
                    directLane == .company ? "company" : "silver",
                status: .blocked,
                outcome: "blocked.capability-not-approved",
                verification: "none",
                reason: reason,
                slot: .none,
                source: directLane == .company ? .gold : .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: directWorkCorrelationIdentifier
                )
            )
        }
    }

    private func cancelPendingAceHQCapabilityContinuation(
        reviewIdentifier: UUID,
        message: String
    ) {
        guard let pending = pendingAceHQCapabilityRequest,
              pending.consentReviewIdentifier == reviewIdentifier else {
            return
        }
        pendingAceHQCapabilityRequest = nil
        completeAceHQBeforeDispatch(
            pending.request,
            status: .cancelled,
            message: message,
            speak: false
        )
    }

    private func routeWorkflowRequest(
        _ buildRequest: String,
        executionInstruction: String? = nil,
        directWorkCorrelationIdentifier suppliedWorkIdentifier: UUID? = nil
    ) {
        let currentContext = activeContextualOwnerRequest
        let directWorkCorrelationIdentifier = suppliedWorkIdentifier
            ?? currentContext?.childWorkCorrelationIdentifier
        let executableInstruction = executionInstruction
            ?? currentContext?.executionInstruction
            ?? buildRequest
        guard let directWorkCorrelationIdentifier else {
            appendRouteReceipt(
                "ROUTE workflow refused missing durable work identity"
            )
            showVisibleResponse(
                "Ace could not bind this workflow request to its owner turn, so nothing ran."
            )
            return
        }
        guard bindRunningWorkDurably(
            workCorrelationIdentifier:
                directWorkCorrelationIdentifier,
            lane: .silver,
            durableLane: "silver"
        ) else {
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                lane: .silver,
                durableLane: "silver",
                status: .failed,
                outcome: "failed.durable-bind-save",
                verification: "none",
                reason:
                    "Ace could not safely save workflow ownership, so no plan or effect started.",
                slot: .none,
                source: .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: directWorkCorrelationIdentifier
                )
            )
            return
        }
        guard directEffectsAreAllowed else {
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                lane: .silver,
                durableLane: "silver",
                status: .blocked,
                outcome: "blocked.direct-effects",
                verification: "none",
                reason:
                    "Whole-job execution is unavailable while direct effects are blocked. Nothing ran.",
                slot: .none,
                source: .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: directWorkCorrelationIdentifier
                )
            )
            return
        }
        guard requireAgentCapabilityConsent(
            for: .silver,
            request: buildRequest,
            executionInstruction: executableInstruction,
            directWorkCorrelationIdentifier:
                directWorkCorrelationIdentifier
        ) else {
            return
        }
        guard !workflowRuntime.isPlanning,
              !workflowRuntime.isBuilding,
              !silverBackgroundAgent.isWorking,
              !reservedBackgroundExecutionSlots.contains(.silver) else {
            appendRouteReceipt("ROUTE workflow-busy")
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                lane: .silver,
                durableLane: "silver",
                status: .blocked,
                outcome: "blocked.busy",
                verification: "none",
                reason:
                    "The Silver slot is already handling another workflow or background check. Nothing new ran.",
                slot: .none,
                source: .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: directWorkCorrelationIdentifier
                )
            )
            return
        }
        appendRouteReceipt("ROUTE workflow-plan full-access-approved")
        Task { [weak self] in
            guard let self else { return }
            let decoding = await self.workflowRuntime.planJob(
                from: executableInstruction
            )
            switch decoding {
            case let .plan(plan):
                let readback = self.workflowRuntime.armPendingJob(plan)
                guard self.workflowRuntime.hasPendingPlan else {
                    _ = self.finishDirectTextTerminal(
                        workCorrelationIdentifier:
                            directWorkCorrelationIdentifier,
                        lane: .silver,
                        durableLane: "silver",
                        status: .blocked,
                        outcome: "blocked.plan-refused",
                        verification: "none",
                        reason: readback.isEmpty
                            ? "The workflow plan was refused. Nothing ran."
                            : readback,
                        slot: .none,
                        source: .silver,
                        turnIdentifier: self.sourceTurnIdentifier(
                            forWork: directWorkCorrelationIdentifier
                        )
                    )
                    return
                }
                self.appendRouteReceipt(
                    "ROUTE workflow-armed steps=\(plan.steps.count) "
                        + "systems=\(plan.systems.count) "
                        + "external=\(plan.externalSources.count)"
                )
                self.pendingDirectWorkflowWorkCorrelationIdentifier =
                    directWorkCorrelationIdentifier
                let readbackCompleted = await self.noraVoice
                    .speakTextToVerifiedCompletion(
                        readback,
                        from: .green
                    )
                guard readbackCompleted,
                      self.workflowRuntime
                        .markPendingPlanReadbackCompleted(plan) else {
                    _ = self.workflowRuntime.cancelPendingJob(
                        ifMatching: plan
                    )
                    _ = self.finishDirectTextTerminal(
                        workCorrelationIdentifier:
                            directWorkCorrelationIdentifier,
                        lane: .silver,
                        durableLane: "silver",
                        status: .blocked,
                        outcome: "blocked.readback-incomplete",
                        verification: "none",
                        reason:
                            "The exact workflow readback did not finish. The confirmation window never opened and nothing ran.",
                        slot: .pendingWorkflow,
                        source: .silver,
                        turnIdentifier: self.sourceTurnIdentifier(
                            forWork: directWorkCorrelationIdentifier
                        )
                    )
                    self.appendRouteReceipt(
                        "ROUTE workflow readback failed-before-confirmation"
                    )
                    return
                }
                self.appendRouteReceipt(
                    "ROUTE workflow confirmation-open after-readback-DONE"
                )
                self.scheduleDirectWorkflowConfirmationExpiry(
                    workCorrelationIdentifier:
                        directWorkCorrelationIdentifier
                )
            case let .clarification(message):
                self.appendRouteReceipt("ROUTE workflow-clarify")
                _ = self.finishDirectTextTerminal(
                    workCorrelationIdentifier:
                        directWorkCorrelationIdentifier,
                    lane: .silver,
                    durableLane: "silver",
                    status: .blocked,
                    outcome: "blocked.needs-clarification",
                    verification: "none",
                    reason: message.isEmpty
                        ? "The workflow planner returned no valid plan. Nothing ran."
                        : message,
                    slot: .none,
                    source: .silver,
                    turnIdentifier: self.sourceTurnIdentifier(
                        forWork: directWorkCorrelationIdentifier
                    )
                )
            }
        }
    }

    private func scheduleDirectWorkflowConfirmationExpiry(
        workCorrelationIdentifier: UUID?
    ) {
        directWorkflowConfirmationExpiryTask?.cancel()
        directWorkflowConfirmationExpiryTask = Task {
            try? await Task.sleep(
                for: .seconds(
                    WorkflowRequestPolicy.confirmationLifetime + 0.1
                )
            )
            guard !Task.isCancelled,
                  pendingDirectWorkflowWorkCorrelationIdentifier
                    == workCorrelationIdentifier,
                  !workflowRuntime.pendingPlanIsCurrent() else {
                return
            }
            directWorkflowConfirmationExpiryTask = nil
            _ = workflowRuntime.cancelPendingJob()
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier: workCorrelationIdentifier,
                lane: .silver,
                durableLane: "silver",
                status: .blocked,
                outcome: "blocked.confirmation-expired",
                verification: "none",
                reason:
                    "The exact workflow confirmation expired. Nothing ran.",
                slot: .pendingWorkflow,
                source: .silver,
                turnIdentifier: sourceTurnIdentifier(
                    forWork: workCorrelationIdentifier
                )
            )
        }
    }

    private func routeGoldWorkflowRequest(
        _ request: GoldExecutionRequest
    ) {
        guard directEffectsAreAllowed else {
            completeGoldExecution(
                request,
                outcome: .blocked,
                verification: .none,
                spokenResult:
                    "Whole-job execution is unavailable while direct effects are blocked. Nothing ran."
            )
            return
        }
        guard !workflowRuntime.isPlanning,
              !workflowRuntime.isBuilding,
              !silverBackgroundAgent.isWorking,
              !reservedBackgroundExecutionSlots.contains(.silver) else {
            completeGoldExecution(
                request,
                outcome: .blocked,
                verification: .none,
                spokenResult:
                    "The Silver slot is already handling another workflow or background check. Nothing new ran."
            )
            return
        }
        appendRouteReceipt(
            "GOLD workflow planning correlation="
                + request.workCorrelationIdentifier
                    .uuidString.lowercased()
        )
        Task { [weak self] in
            guard let self else { return }
            let decoding = await self.workflowRuntime.planJob(
                from: request.executionInstruction
            )
            switch decoding {
            case let .plan(plan):
                let startResult = self.workflowRuntime
                    .startPlannedJobImmediately(
                        plan,
                        suppressTerminalAnnouncement: true
                    )
                guard let operationIdentifier = self.workflowRuntime
                    .activeOperationIdentifier else {
                    self.completeGoldExecution(
                        request,
                        outcome: .blocked,
                        verification: .none,
                        spokenResult: startResult.isEmpty
                            ? "The validated workflow did not start. Nothing ran."
                            : startResult
                    )
                    return
                }
                self.activeGoldWorkflowRequest = request
                self.activeGoldWorkflowOperationIdentifier =
                    operationIdentifier
                AceEventBus.shared.publishOutbound(
                    source: .silver,
                    state: .executing,
                    payloadType: .executionReceipt,
                    payload:
                        "typed-lane=green operation="
                            + operationIdentifier.uuidString.lowercased(),
                    turnID: request.sourceTurnIdentifier,
                    correlationID:
                        request.workCorrelationIdentifier
                )
                self.appendRouteReceipt(
                    "GOLD workflow started immediately operation="
                        + operationIdentifier.uuidString.lowercased()
                        + " correlation="
                        + request.workCorrelationIdentifier
                            .uuidString.lowercased()
                )
            case let .clarification(message):
                self.completeGoldExecution(
                    request,
                    outcome: .blocked,
                    verification: .none,
                    spokenResult: message.isEmpty
                        ? "The workflow planner returned no valid plan. Nothing ran."
                        : message
                )
            }
        }
    }

    private func scheduleGoldWorkflowConfirmationExpiry(
        _ request: GoldExecutionRequest
    ) {
        goldWorkflowConfirmationExpiryTask?.cancel()
        goldWorkflowConfirmationExpiryTask = Task {
            try? await Task.sleep(
                for: .seconds(
                    WorkflowRequestPolicy.confirmationLifetime + 0.1
                )
            )
            guard !Task.isCancelled,
                  pendingGoldWorkflowRequest == request,
                  !workflowRuntime.pendingPlanIsCurrent() else {
                return
            }
            pendingGoldWorkflowRequest = nil
            _ = workflowRuntime.cancelPendingJob()
            completeGoldExecution(
                request,
                outcome: .blocked,
                verification: .none,
                spokenResult:
                    "The exact workflow confirmation expired. Nothing ran."
            )
        }
    }

    private func resolveDirectWorkflowReceiptIfNeeded(
        _ receipt: ArtifactReceipt?
    ) {
        guard let receipt,
              let workCorrelationIdentifier =
                activeDirectWorkflowWorkCorrelationIdentifier,
              let operationIdentifier =
                activeDirectWorkflowOperationIdentifier,
              receipt.operationID == operationIdentifier else {
            return
        }
        switch receipt.state {
        case .started, .step:
            return
        case .done:
            do {
                guard let verified = try ArtifactReceiptStore.shared
                    .verifiedDone(operationID: operationIdentifier),
                      verified == receipt else {
                    _ = finishDirectWorkTerminal(
                        workCorrelationIdentifier:
                            workCorrelationIdentifier,
                        lane: .silver,
                        durableLane: "silver",
                        status: .failed,
                        outcome: "failed.receipt-unverified",
                        verification: "none",
                        reason:
                            "The workflow produced a DONE record, but its exact artifact receipt did not verify. Completion is not claimed.",
                        slot: .activeWorkflow(
                            operationIdentifier:
                                operationIdentifier
                        )
                    )
                    return
                }
                _ = finishDirectWorkTerminal(
                    workCorrelationIdentifier:
                        workCorrelationIdentifier,
                    lane: .silver,
                    durableLane: "silver",
                    status: .completed,
                    outcome: "completed",
                    verification: "verified",
                    reason:
                        "The workflow completed with a verified artifact at \(verified.artifactPath).",
                    slot: .activeWorkflow(
                        operationIdentifier: operationIdentifier
                    )
                )
            } catch {
                _ = finishDirectWorkTerminal(
                    workCorrelationIdentifier:
                        workCorrelationIdentifier,
                    lane: .silver,
                    durableLane: "silver",
                    status: .failed,
                    outcome: "failed.receipt-missing",
                    verification: "none",
                    reason:
                        "The workflow completion receipt was missing or changed. Completion is not claimed.",
                    slot: .activeWorkflow(
                        operationIdentifier: operationIdentifier
                    )
                )
            }
        case let .failed(reason):
            _ = finishDirectWorkTerminal(
                workCorrelationIdentifier:
                    workCorrelationIdentifier,
                lane: .silver,
                durableLane: "silver",
                status: .failed,
                outcome: "failed",
                verification: "none",
                reason: "The workflow failed: \(reason)",
                slot: .activeWorkflow(
                    operationIdentifier: operationIdentifier
                )
            )
        }
    }

    private func resolveGoldWorkflowReceiptIfNeeded(
        _ receipt: ArtifactReceipt?
    ) {
        guard let receipt,
              let request = activeGoldWorkflowRequest,
              let operationIdentifier =
                activeGoldWorkflowOperationIdentifier,
              receipt.operationID == operationIdentifier else {
            return
        }
        switch receipt.state {
        case .started, .step:
            return
        case .done:
            activeGoldWorkflowRequest = nil
            activeGoldWorkflowOperationIdentifier = nil
            do {
                guard let verified = try ArtifactReceiptStore.shared
                    .verifiedDone(operationID: operationIdentifier),
                      verified == receipt else {
                    completeGoldExecution(
                        request,
                        outcome: .failed,
                        verification: .none,
                        spokenResult:
                            "The workflow produced a DONE record, but its exact artifact receipt did not verify. Completion is not claimed."
                    )
                    return
                }
                completeGoldExecution(
                    request,
                    outcome: .completed,
                    verification: .verified,
                    spokenResult:
                        "The workflow completed with a verified artifact at \(verified.artifactPath)."
                )
            } catch {
                completeGoldExecution(
                    request,
                    outcome: .failed,
                    verification: .none,
                    spokenResult:
                        "The workflow completion receipt was missing or changed. Completion is not claimed."
                )
            }
        case let .failed(reason):
            activeGoldWorkflowRequest = nil
            activeGoldWorkflowOperationIdentifier = nil
            completeGoldExecution(
                request,
                outcome: .failed,
                verification: .none,
                spokenResult: "The workflow failed: \(reason)"
            )
        }
    }

    private func frontWindowCGFrame(ofAppNamed applicationName: String) -> CGRect? {
        let runningCandidates: [(String, NSRunningApplication)] =
            NSWorkspace.shared.runningApplications.compactMap { app in
                guard app.activationPolicy == .regular,
                      let name = app.localizedName else { return nil }
                return (name, app)
            }
        guard let runningApp = AppSwitcher.bestMatch(
            runningCandidates,
            wanted: applicationName
        )?.1 else { return nil }
        let appElement = AXUIElementCreateApplication(runningApp.processIdentifier)
        var windowsValue: CFTypeRef?
        AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute as CFString, &windowsValue)
        guard let windows = windowsValue as? [AXUIElement], let frontWindow = windows.first else { return nil }
        var positionValue: CFTypeRef?, sizeValue: CFTypeRef?
        AXUIElementCopyAttributeValue(frontWindow, kAXPositionAttribute as CFString, &positionValue)
        AXUIElementCopyAttributeValue(frontWindow, kAXSizeAttribute as CFString, &sizeValue)
        var windowOrigin = CGPoint.zero, windowSize = CGSize.zero
        if let positionValue { AXValueGetValue(positionValue as! AXValue, .cgPoint, &windowOrigin) }
        if let sizeValue { AXValueGetValue(sizeValue as! AXValue, .cgSize, &windowSize) }
        guard windowSize.width > 0 else { return nil }
        return CGRect(origin: windowOrigin, size: windowSize)
    }

    /// Red Agent is a full-access service on every buyer Mac. An admitted owner
    /// turn reaches the selected provider directly, with no extra Red approval.
    private func routeTask(
        _ task: String,
        executionInstruction: String? = nil,
        directWorkCorrelationIdentifier suppliedWorkIdentifier: UUID? = nil
    ) {
        let currentContext = activeContextualOwnerRequest
        let directWorkCorrelationIdentifier = suppliedWorkIdentifier
            ?? currentContext?.childWorkCorrelationIdentifier
        let executableInstruction = executionInstruction
            ?? currentContext?.executionInstruction
            ?? task
        guard let directWorkCorrelationIdentifier else {
            appendRouteReceipt(
                "ROUTE red refused missing durable work identity"
            )
            showVisibleResponse(
                "Ace could not bind this Red Agent request to its owner turn, so nothing ran."
            )
            return
        }
        let executionSlot = nextBackgroundExecutionSlot()
        dispatchBackgroundTask(
            executableInstruction,
            providerTurn: AceProviderTurn.capture(),
            terminalOwner: .direct(
                workCorrelationIdentifier:
                    directWorkCorrelationIdentifier,
                sourceTurnIdentifier:
                    currentContext?.sourceTurnIdentifier
            ),
            preselectedExecutionSlot: executionSlot
        )
    }

    /// Partner clarification consumes one owner answer under the original
    /// immutable work ID. The answer can arrive from the open microphone or
    /// the composer because both cross the same admission boundary above.
    private func resumePendingPartnerClarificationIfNeeded(
        _ ownerAnswer: String,
        context: OwnerTurnContext
    ) -> Bool {
        guard context.pendingSlot == .goldClarification,
              let pending = pendingPartnerClarification else {
            return false
        }
        pendingPartnerClarification = nil

        guard let originalWork = goldContextBundle.workRecords
                .first(where: {
                    $0.workCorrelationIdentifier
                        == pending.parentWorkCorrelationIdentifier
                }) else {
            let reason =
                "That Partner clarification is no longer attached to a visible work receipt. Please state the full request again."
            showVisibleResponse(reason)
            speakPartnerStatus(reason)
            appendRouteReceipt(
                "PARTNER clarification refused missing original work"
            )
            return true
        }

        if CrossAppActionPolicy.isExplicitCancellation(ownerAnswer) {
            let reason =
                "Okay, I cancelled that Partner request. Nothing ran."
            let persisted = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    originalWork.workCorrelationIdentifier,
                lane: .partner,
                durableLane: "partner",
                status: .cancelled,
                outcome: "partner-clarification-cancelled",
                verification: "none",
                reason: reason,
                slot: .none,
                source: .partner,
                turnIdentifier: originalWork.sourceTurnIdentifier,
                speak: false
            )
            if persisted { speakPartnerStatus(reason) }
            appendRouteReceipt(
                "PARTNER clarification cancelled work="
                    + originalWork.workCorrelationIdentifier
                        .uuidString.lowercased()
            )
            return true
        }

        guard pending.isCurrent(
                  sessionIdentifier: context.sessionID
              ),
              let sourceCorrelationIdentifier =
                  activeRoutingCorrelationID,
              let resolution = pending.resolve(
                  ownerAnswer: context.exactInput,
                  sourceTurnIdentifier: context.turnID,
                  sourceCorrelationIdentifier:
                      sourceCorrelationIdentifier,
                  childWorkCorrelationIdentifier:
                      originalWork.workCorrelationIdentifier
              ) else {
            let reason =
                "That Partner clarification expired or the answer was too long. Please state the full request again."
            let persisted = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    originalWork.workCorrelationIdentifier,
                lane: .partner,
                durableLane: "partner",
                status: .failed,
                outcome: "partner-clarification-invalid",
                verification: "none",
                reason: reason,
                slot: .none,
                source: .partner,
                turnIdentifier: originalWork.sourceTurnIdentifier,
                speak: false
            )
            if persisted { speakPartnerStatus(reason) }
            appendRouteReceipt(
                "PARTNER clarification refused expired-or-unbounded"
            )
            return true
        }

        let resumedRequest = ContextualOwnerRequest(
            originalOwnerTranscript:
                originalWork.originalOwnerTranscript,
            resolvedRequest: resolution.resolvedRequest,
            sourceSessionIdentifier:
                originalWork.sourceSessionIdentifier,
            sourceTurnIdentifier:
                originalWork.sourceTurnIdentifier,
            sourceCorrelationIdentifier:
                originalWork.sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier:
                originalWork.parentWorkCorrelationIdentifier,
            childWorkCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            referenceKind: .pronoun,
            resolutionStatus: .resolved
        )
        var candidateGoldContextBundle = goldContextBundle
        let durableRecorded = candidateGoldContextBundle.transitionWork(
            workCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            lane: "partner",
            status: .running
        )
        guard durableRecorded,
              AceConversationHistory.saveBundle(
                  candidateGoldContextBundle,
                  performUnlessRaised: { body in
                      StealthEntryLatch.shared.performUnlessRaised(body)
                  }
              ) else {
            let reason =
                "Ace could not safely save the Partner clarification, so nothing new ran."
            let persisted = finishDirectTextTerminal(
                workCorrelationIdentifier:
                    originalWork.workCorrelationIdentifier,
                lane: .partner,
                durableLane: "partner",
                status: .failed,
                outcome: "partner-clarification-save-failed",
                verification: "none",
                reason: reason,
                slot: .none,
                source: .partner,
                turnIdentifier: originalWork.sourceTurnIdentifier,
                speak: false
            )
            if persisted { speakPartnerStatus(reason) }
            appendRouteReceipt(
                "PARTNER clarification refused durable continuation save"
            )
            return true
        }
        goldContextBundle = candidateGoldContextBundle
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            lane: .partner,
            status: .running
        )
        activeContextualOwnerRequest = resumedRequest
        upsertBuyerWorkReceipt(
            workID: originalWork.workCorrelationIdentifier,
            lane: .partner,
            phase: .processing,
            progress:
                "Owner clarification was attached to the original Partner work ID; provider processing resumed."
        )
        appendRouteReceipt(
            "PARTNER clarification resumed work="
                + originalWork.workCorrelationIdentifier
                    .uuidString.lowercased()
        )
        sendPartnerTurn(
            transcript: resolution.resolvedRequest,
            includesExplicitScreenContext: false
        )
        return true
    }

    /// Every non-local owner request reaches the selected provider exactly
    /// once. Gold may answer, clarify one missing value, or return one bounded
    /// objective for the shared Red executor.
    private func resumePendingGoldClarificationIfNeeded(
        _ ownerAnswer: String,
        context: OwnerTurnContext
    ) -> Bool {
        guard context.pendingSlot == .goldClarification else {
            return false
        }
        guard let pending = pendingGoldClarification else {
            appendRouteReceipt(
                "GOLD clarification refused missing pending binding"
            )
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .failed,
                outcome: "gold-clarification-missing",
                reason:
                    "That clarification is no longer current. Please state the full request again."
            )
            return true
        }
        pendingGoldClarification = nil

        if CrossAppActionPolicy.isExplicitCancellation(ownerAnswer) {
            appendRouteReceipt("GOLD clarification cancelled by owner")
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .cancelled,
                outcome: "gold-clarification-cancelled",
                reason: "Okay, I cancelled that clarification. Nothing ran."
            )
            return true
        }

        guard pending.isCurrent(
                  sessionIdentifier: context.sessionID
              ),
              let sourceCorrelationIdentifier =
                  activeRoutingCorrelationID,
              let originalWork = goldContextBundle.workRecords
                .first(where: {
                    $0.workCorrelationIdentifier
                        == pending.parentWorkCorrelationIdentifier
                }),
              let resolution = pending.resolve(
                  ownerAnswer: context.exactInput,
                  sourceTurnIdentifier: context.turnID,
                  sourceCorrelationIdentifier:
                      sourceCorrelationIdentifier,
                  childWorkCorrelationIdentifier:
                      pending.parentWorkCorrelationIdentifier
              ) else {
            appendRouteReceipt(
                "GOLD clarification refused expired-or-unbounded"
            )
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .failed,
                outcome: "gold-clarification-invalid",
                reason:
                    "That clarification expired or was too long. Please state the full request again."
            )
            return true
        }

        // Clarification advances the original work. It does not mint a second
        // task identity or turn a question into a terminal block.
        let resumedRequest = ContextualOwnerRequest(
            originalOwnerTranscript:
                originalWork.originalOwnerTranscript,
            resolvedRequest: resolution.resolvedRequest,
            sourceSessionIdentifier:
                originalWork.sourceSessionIdentifier,
            sourceTurnIdentifier:
                originalWork.sourceTurnIdentifier,
            sourceCorrelationIdentifier:
                originalWork.sourceCorrelationIdentifier,
            parentWorkCorrelationIdentifier:
                originalWork.parentWorkCorrelationIdentifier,
            childWorkCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            referenceKind: .pronoun,
            resolutionStatus: .resolved,
            continuationAdmission: OwnerWorkContinuationAdmission(
                turnIdentifier: context.turnID,
                correlationIdentifier: sourceCorrelationIdentifier
            )
        )
        var candidateGoldContextBundle = goldContextBundle
        let durableRecorded = candidateGoldContextBundle.transitionWork(
            workCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            lane: "gold",
            status: .running
        )
        guard durableRecorded,
              AceConversationHistory.saveBundle(
                  candidateGoldContextBundle,
                  performUnlessRaised: { body in
                      StealthEntryLatch.shared.performUnlessRaised(body)
                  }
              ) else {
            appendRouteReceipt(
                "GOLD clarification refused durable continuation save"
            )
            _ = finishVolatileOwnerTurn(
                turnID: context.turnID,
                correlationID: activeRoutingCorrelationID,
                status: .failed,
                outcome: "gold-clarification-save-failed",
                reason:
                    "Ace could not safely save the clarified request, so nothing ran."
            )
            return true
        }
        goldContextBundle = candidateGoldContextBundle
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier:
                originalWork.workCorrelationIdentifier,
            lane: .gold,
            status: .running
        )
        activeContextualOwnerRequest = resumedRequest
        upsertBuyerWorkReceipt(
            workID: originalWork.workCorrelationIdentifier,
            lane: .gold,
            phase: .processing,
            progress:
                "Owner clarification was attached to the original work ID; provider processing resumed."
        )
        appendRouteReceipt(
            "GOLD clarification resumed work="
                + originalWork.workCorrelationIdentifier
                    .uuidString.lowercased()
        )
        sendTranscriptToClaudeWithScreenshot(
            transcript: resolution.resolvedRequest,
            context: context,
            providerPromptOverride: pending.providerPrompt(
                ownerAnswer: context.exactInput
            )
        )
        return true
    }

    private func routeProviderOnce(
        _ utterance: String,
        context: OwnerTurnContext
    ) {
        sendTranscriptToClaudeWithScreenshot(
            transcript:
                ownerTurnLifecycle.activeBinding?.envelope
                    .normalizedRequest ?? utterance,
            context: context
        )
    }

    private func routeGoldRedTask(
        _ request: GoldExecutionRequest,
        providerTurn: AceProviderTurn
    ) async {
        guard !Task.isCancelled,
              request.sourceSessionIdentifier
                == AceEventBus.shared.sessionID else {
            return
        }
        appendRouteReceipt(
            "GOLD objective continuing to the first free full-capability background slot"
        )
        routeGoldRedAgent(
            request,
            providerTurn: providerTurn
        )
    }

    private func routeGoldRedAgent(
        _ request: GoldExecutionRequest,
        providerTurn: AceProviderTurn
    ) {
        guard directEffectsAreAllowed else {
            completeGoldExecution(
                request,
                outcome: .blocked,
                verification: .none,
                spokenResult:
                    "Direct effects are currently blocked. Nothing ran."
            )
            return
        }
        dispatchBackgroundTask(
            request.executionInstruction,
            providerTurn: providerTurn,
            terminalOwner: .gold(request)
        )
    }

    /// Email drafting begins with an app-owned Apple Mail identity lookup. The
    /// model never sees an unbound sender choice and no Google/Gmail token is
    /// involved in this local enumeration.
    private func beginAppleMailDraftRouting(_ userRequest: String) {
        guard directEffectsAreAllowed,
              let turnID = activeRoutingTurnID else { return }
        if let context = activeOwnerTurnContext {
            _ = ownerTurnLifecycle.deferManagerDispatch(for: context)
        }
        clearPendingAppleMailDraftRequest()
        pendingAppleMailRouteBinding = ownerTurnLifecycle.activeBinding
        // Email drafts bind the buyer's own Gmail identity (GmailAccount.swift) instead of
        // enumerating Apple Mail accounts: a Mac with no Mail account configured used to
        // dead-end every email request here.
        if let sender = GmailAccountStore().storedAddress() {
            gmailNeedsAppPassword = false
            appleMailNeedsConnection = false
            appleMailSenderSelection = nil
            appendRouteReceipt("GMAIL sender bound; exact request resumed")
            _ = resumePrivateMailDraftRequest(
                userRequest,
                sender: sender,
                ownerTurnBinding: pendingAppleMailRouteBinding
            )
            return
        }
        let pending = pendingMailDraftIntentStore.retain(
            turnID: turnID,
            exactRequest: userRequest
        )
        scheduleAppleMailPendingIntentExpiry(pending)
        observeGmailAccountReadiness(for: pending)
    }

    /// Holds the exact request in memory while the buyer adds an app password
    /// in the Ace panel, then resumes it once. Nothing is written to disk and
    /// the intent still expires on its own schedule.
    private func observeGmailAccountReadiness(
        for pending: PendingMailDraftIntent
    ) {
        appleMailAccountLookupGeneration = UUID()
        let generation = appleMailAccountLookupGeneration
        let intentID = pending.id
        let createdAt = pending.createdAt
        appleMailAccountLookupTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.appleMailAccountLookupGeneration == generation {
                    self.appleMailAccountLookupTask = nil
                }
            }
            var didAsk = false
            while !Task.isCancelled,
                  self.directEffectsAreAllowed,
                  self.appleMailAccountLookupGeneration == generation,
                  self.pendingMailDraftIntentStore.pendingIntent?.id
                    == intentID {
                let now = Date()
                let age = now.timeIntervalSince(createdAt)
                guard age >= 0,
                      age <= PendingMailDraftIntent.lifetime else {
                    self.clearPendingAppleMailDraftRequest()
                    self.appendRouteReceipt(
                        "GMAIL pending account recovery expired")
                    return
                }
                if let sender = GmailAccountStore().storedAddress() {
                    guard let resumed = self.pendingMailDraftIntentStore
                        .resumeIfAccountReady(true, now: now) else { return }
                    self.gmailNeedsAppPassword = false
                    self.appendRouteReceipt(
                        "GMAIL account ready; exact request resumed")
                    _ = self.resumePrivateMailDraftRequest(
                        resumed.exactRequest,
                        sender: sender,
                        ownerTurnBinding: self.pendingAppleMailRouteBinding
                    )
                    return
                }
                if !didAsk {
                    didAsk = true
                    self.gmailNeedsAppPassword = true
                    self.appendRouteReceipt("GMAIL waiting for app password")
                    try? await self.noraVoice.speakText(
                        "i need your Gmail app password before i can draft email. add it in the Ace panel; i'll keep this exact request in memory and pick it up as soon as it's in."
                    )
                }
                do {
                    try await Task.sleep(for: .seconds(2))
                } catch {
                    return
                }
            }
        }
    }

    private func scheduleAppleMailPendingIntentExpiry(
        _ pending: PendingMailDraftIntent
    ) {
        appleMailPendingIntentExpiryTask?.cancel()
        let intentID = pending.id
        appleMailPendingIntentExpiryTask = Task { [weak self] in
            do {
                try await Task.sleep(
                    for: .seconds(PendingMailDraftIntent.lifetime)
                )
            } catch {
                return
            }
            guard let self,
                  self.pendingMailDraftIntentStore.pendingIntent?.id
                    == intentID else { return }
            self.finishPendingPrivateRoute(
                self.pendingAppleMailRouteBinding,
                status: .failed,
                outcome: "mail-readiness-expired"
            )
            self.clearPendingAppleMailDraftRequest()
            self.appendRouteReceipt(
                "APPLE-MAIL pending recovery expired")
        }
    }

    /// Polls only local Apple Mail account readiness for the bounded lifetime
    /// of one exact in-memory intent. No request text enters a log or artifact.
    private func observeAppleMailAccountReadiness(
        for pending: PendingMailDraftIntent
    ) {
        appleMailAccountLookupGeneration = UUID()
        let generation = appleMailAccountLookupGeneration
        let intentID = pending.id
        let createdAt = pending.createdAt
        appleMailAccountLookupTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.appleMailAccountLookupGeneration == generation {
                    self.appleMailAccountLookupTask = nil
                }
            }
            var didPresentConnectionRecovery = false
            var didPresentAutomationRecovery = false
            while !Task.isCancelled,
                  self.directEffectsAreAllowed,
                  self.appleMailAccountLookupGeneration == generation,
                  self.pendingMailDraftIntentStore.pendingIntent?.id
                    == intentID {
                let now = Date()
                let age = now.timeIntervalSince(createdAt)
                guard age >= 0,
                      age <= PendingMailDraftIntent.lifetime else {
                    self.clearPendingAppleMailDraftRequest()
                    self.appendRouteReceipt(
                        "APPLE-MAIL pending account recovery expired")
                    return
                }
                let snapshot = await self.appleMailAccountProvider
                    .enabledSenderAddresses()
                guard !Task.isCancelled,
                      self.directEffectsAreAllowed,
                      self.appleMailAccountLookupGeneration == generation,
                      self.pendingMailDraftIntentStore.pendingIntent?.id
                        == intentID else {
                    return
                }
                switch snapshot {
                case .unavailable:
                    if !didPresentAutomationRecovery {
                        didPresentAutomationRecovery = true
                        self.appleMailNeedsConnection = false
                        self.appleMailSenderSelection = nil
                        self.appendRouteReceipt(
                            "APPLE-MAIL Automation unavailable; recovery pending")
                        try? await self.noraVoice.speakText(
                            "Mail Automation is not available yet. use the optional Mail Automation control in the Ace panel; i'll keep this exact request only in memory."
                        )
                    }
                    do {
                        try await Task.sleep(for: .seconds(2))
                    } catch {
                        return
                    }
                    continue
                case .available(let addresses):
                    switch AppleMailAccountPolicy.nextStep(
                        for: addresses,
                        requestedBy: pending.exactRequest
                    ) {
                    case .connectAppleMail:
                        if !didPresentConnectionRecovery {
                            didPresentConnectionRecovery = true
                            self.appleMailNeedsConnection = true
                            self.appleMailSenderSelection = nil
                            self.appendRouteReceipt(
                                "APPLE-MAIL waiting for enabled sender")
                            try? await self.noraVoice.speakText(
                                "i need an enabled sender in Apple Mail. select Connect Apple Mail; i'll keep this exact request in memory and resume it after the account is ready."
                            )
                        }

                    case .bindSender(let sender):
                        guard let resumed = self.pendingMailDraftIntentStore
                            .resumeIfAccountReady(true, now: now) else { return }
                        self.appleMailNeedsConnection = false
                        self.appleMailSenderSelection = nil
                        self.appendRouteReceipt(
                            "APPLE-MAIL account ready; exact request resumed")
                        if let exact = ExactAppleMailDraftRequest.parse(
                            resumed.exactRequest
                        ), exact.sender == sender {
                            self.appendRouteReceipt(
                                "APPLE-MAIL exact fields bound; deterministic draft path"
                            )
                            _ = self.beginDirectAppActionPreview(
                                PlannedAppAction(
                                    tool: .emailDraft,
                                    arguments: [
                                        "--from",
                                        exact.sender,
                                        exact.recipient,
                                        exact.subject,
                                        exact.body,
                                    ]
                                ),
                                ownerTurnBinding:
                                    self.pendingAppleMailRouteBinding
                            )
                            return
                        }
                        _ = self.resumePrivateMailDraftRequest(
                            resumed.exactRequest,
                            sender: sender,
                            ownerTurnBinding:
                                self.pendingAppleMailRouteBinding
                        )
                        return

                    case .chooseSender(let senders):
                        guard let resumed = self.pendingMailDraftIntentStore
                            .resumeIfAccountReady(true, now: now) else { return }
                        self.appleMailNeedsConnection = false
                        self.appleMailSenderSelection = AppleMailSenderSelectionState(
                            requestIdentifier: resumed.id,
                            senderAddresses: senders
                        )
                        self.appendRouteReceipt(
                            "APPLE-MAIL account ready; sender choice required")
                        try? await self.noraVoice.speakText(
                            "choose the exact Apple Mail sender in the Ace panel. i have not sent the draft request to the model."
                        )
                        return
                    }
                }
                do {
                    try await Task.sleep(for: .seconds(2))
                } catch {
                    return
                }
            }
        }
    }

    @discardableResult
    func selectAppleMailSender(_ sender: String) -> Bool {
        guard directEffectsAreAllowed,
              let pending = pendingMailDraftIntentStore.pendingIntent,
              pending.isCurrent(at: Date()),
              let selection = appleMailSenderSelection,
              selection.requestIdentifier == pending.id,
              selection.senderAddresses.contains(sender) else {
            return false
        }
        guard resumePrivateMailDraftRequest(
            pending.exactRequest,
            sender: sender,
            ownerTurnBinding: pendingAppleMailRouteBinding
        ) else { return false }
        appleMailSenderSelection = nil
        appleMailNeedsConnection = false
        appendRouteReceipt("APPLE-MAIL buyer selected exact sender before planning")
        return true
    }

    private func ownerEmailAction(_ exact: ExactAppleMailDraftRequest, send: Bool) -> PlannedAppAction {
        if send {
            return PlannedAppAction(tool: .emailSend, arguments: [
                "--send-reviewed", UUID().uuidString.lowercased(), "--from",
                exact.sender, exact.recipient, exact.subject, exact.body,
            ])
        }
        return PlannedAppAction(tool: .emailDraft, arguments: [
            "--from", exact.sender, exact.recipient, exact.subject, exact.body,
        ])
    }

    @discardableResult
    private func resumePrivateMailDraftRequest(
        _ request: String,
        sender: String,
        ownerTurnBinding: OwnerTurnBinding?
    ) -> Bool {
        guard directEffectsAreAllowed,
              appActionPlanningTask == nil,
              let binding = ownerTurnLifecycle.startedPrivateRecoveryBinding(
                ownerTurnBinding
              ) else { return false }
        if let requestedSender = AppleMailAccountPolicy
            .requestedSenderAddress(in: request), requestedSender != sender {
            _ = finishVolatileOwnerTurn(
                turnID: binding.context.turnID,
                correlationID: binding.correlationID,
                status: .failed, outcome: "mail-draft.sender-mismatch",
                reason: "The requested sender does not match the connected email account. Choose the intended sender before creating this draft."
            )
            return false
        }
        if let exact = ExactAppleMailDraftRequest.parse(request),
           exact.sender == sender {
            return beginDirectAppActionPreview(
                ownerEmailAction(exact,
                    send: ExactAppleMailDraftRequest.explicitlyRequestsSending(request)),
                ownerTurnBinding: binding
            )
        }
        let generation = UUID()
        let providerTurn = AceProviderTurn.capture()
        appActionPlanningGeneration = generation
        backgroundTaskActive = true
        voiceState = .processing
        appendRouteReceipt("MAIL private draft planning started; durable content disabled")
        appActionPlanningTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.appActionPlanningGeneration == generation {
                    self.appActionPlanningTask = nil
                    self.backgroundTaskActive = self.meetingNotetaker.isTakingNotes
                        || self.anyBackgroundExecutionAgentIsWorking
                }
            }
            do {
                let (response, _) = try await self.claudeAPI.analyzeImageStreaming(
                    images: [],
                    systemPrompt: PrivateMailDraftPlanningResponse.systemPrompt,
                    conversationHistory: [],
                    userPrompt: request,
                    responseFormat: .strictJSON,
                    providerTurn: providerTurn,
                    interactiveLatencyProfile: InteractiveProviderLatencyPolicy.profile(
                        for: .gold, includesScreenContext: false
                    ),
                    persistLogs: false,
                    onTextChunk: { _ in }
                )
                guard !Task.isCancelled, self.directEffectsAreAllowed,
                      self.appActionPlanningGeneration == generation,
                      self.ownerTurnLifecycle.startedPrivateRecoveryBinding(binding)
                        == binding else { return }
                let plan = try JSONDecoder().decode(
                    PrivateMailDraftPlanningResponse.self, from: Data(response.utf8)
                )
                if plan.kind == .clarify {
                    let question = try plan.clarification()
                    self.privateMailClarification = PrivateMailClarification(
                        sessionID: binding.context.sessionID,
                        sender: sender,
                        request: request,
                        question: question,
                        createdAt: Date()
                    )
                    self.voiceState = .idle
                    _ = self.finishVolatileOwnerTurn(
                        turnID: binding.context.turnID,
                        correlationID: binding.correlationID,
                        status: .failed, outcome: "mail-draft.fields-required",
                        reason: question
                    )
                    self.appendRouteReceipt("MAIL private draft requires owner details; nothing created")
                    return
                }
                let exact = try plan.exactDraft(sender: sender, ownerRequest: request)
                // The existing broker revalidates the original private turn
                // and owns the draft's observed result. No Gold work is invented.
                self.appActionPlanningTask = nil
                self.voiceState = .idle
                _ = self.beginDirectAppActionPreview(
                    self.ownerEmailAction(exact, send: plan.delivery == .send),
                    ownerTurnBinding: binding
                )
            } catch {
                guard !Task.isCancelled, self.directEffectsAreAllowed,
                      self.ownerTurnLifecycle.startedPrivateRecoveryBinding(binding)
                        == binding else { return }
                self.appendRouteReceipt("MAIL private draft planning failed; content omitted")
                self.voiceState = .idle
                _ = self.finishVolatileOwnerTurn(
                    turnID: binding.context.turnID,
                    correlationID: binding.correlationID,
                    status: .failed, outcome: "mail-draft.planning-failed",
                    reason: "The email draft could not be prepared. Please give the recipient, subject, and final body together. Nothing was sent."
                )
            }
        }
        return true
    }

    func selectAppleMailSenderFromUI(_ sender: String) {
        guard let lineage = beginIntegrationControlAction(
            .appleMailSenderChoice,
            preservingPrivateRouteBinding: pendingAppleMailRouteBinding
        ) else { return }
        let accepted = selectAppleMailSender(sender)
        completeIntegrationControlAction(
            lineage,
            outcome: accepted ? .completed : .failed
        )
    }

    @discardableResult
    func connectAppleMail() -> AceControlActionOutcome {
        guard directEffectsAreAllowed else {
            let outcome = controlFailure(
                code: "apple_mail.private_mode",
                message: "Exit Private Mode before opening Apple Mail.",
                recoveryTitle: "Exit Private Mode and try again",
                recovery: .retry
            )
            appleMailControlOutcome = outcome
            return outcome
        }
        let outcome = AceWorkspaceOpenAction.perform(
            target: PendingMailDraftIntent.accountSetupDestination,
            copy: AceWorkspaceOpenCopy(
                successMessage:
                    "Apple Mail opened. Add or enable a sender, then return to Ace.",
                failureCode: "apple_mail.open_failed",
                failureMessage: "macOS did not open Apple Mail.",
                recoveryTitle: "Try opening Apple Mail again",
                recovery: .retry
            )
        )
        appleMailControlOutcome = outcome
        switch outcome {
        case .succeeded:
            // Opening Mail is not proof that the owner added an enabled
            // sender. Keep the recovery card visible until the next account
            // snapshot actually returns one.
            appleMailNeedsConnection = true
            appendRouteReceipt("APPLE-MAIL app opened")
        case let .failed(failure):
            appleMailNeedsConnection = true
            showVisibleResponse(failure.message)
        case .started:
            break
        }
        return outcome
    }

    func connectAppleMailFromUI() {
        guard let lineage = beginIntegrationControlAction(
            .appleMailConnect,
            preservingPrivateRouteBinding: pendingAppleMailRouteBinding
        ) else { return }
        let outcome = connectAppleMail()
        completeIntegrationControlAction(
            lineage,
            outcome: Self.directUIOutcome(for: outcome)
        )
    }

    func cancelPendingAppleMailFromUI() {
        let binding = pendingAppleMailRouteBinding
        guard let lineage = beginIntegrationControlAction(
            .appleMailPendingCancel,
            preservingPrivateRouteBinding: binding
        ) else { return }
        finishPendingPrivateRoute(
            binding,
            status: .cancelled,
            outcome: "mail-recovery-cancelled"
        )
        dismissVisibleAppActionReview()
        completeIntegrationControlAction(lineage, outcome: .cancelled)
    }

    private func clearPendingAppleMailDraftRequest() {
        privateMailClarification = nil
        appleMailAccountLookupTask?.cancel()
        appleMailAccountLookupTask = nil
        appleMailPendingIntentExpiryTask?.cancel()
        appleMailPendingIntentExpiryTask = nil
        appleMailAccountLookupGeneration = UUID()
        pendingMailDraftIntentStore.cancel()
        pendingAppleMailRouteBinding = nil
        appleMailSenderSelection = nil
        appleMailNeedsConnection = false
    }

    private func beginAppleMessagesRouting(
        _ intent: AppleMessagesIntent
    ) {
        guard directEffectsAreAllowed,
              let turnID = activeRoutingTurnID else { return }
        if let context = activeOwnerTurnContext {
            _ = ownerTurnLifecycle.deferManagerDispatch(for: context)
        }
        clearPendingAppleMessagesRequest()
        pendingAppleMessagesRouteBinding =
            ownerTurnLifecycle.activeBinding
        let pending = pendingAppleMessagesIntentStore.retain(
            turnID: turnID,
            intent: intent
        )
        scheduleAppleMessagesPendingIntentExpiry(pending)
        observeAppleMessagesReadiness(for: pending)
    }

    private func scheduleAppleMessagesPendingIntentExpiry(
        _ pending: PendingAppleMessagesIntent
    ) {
        appleMessagesPendingIntentExpiryTask?.cancel()
        let intentID = pending.id
        appleMessagesPendingIntentExpiryTask = Task { [weak self] in
            do {
                try await Task.sleep(
                    for: .seconds(PendingAppleMessagesIntent.lifetime)
                )
            } catch {
                return
            }
            guard let self,
                  self.pendingAppleMessagesIntentStore.pendingIntent?.id
                    == intentID else { return }
            self.finishPendingPrivateRoute(
                self.pendingAppleMessagesRouteBinding,
                status: .failed,
                outcome: "messages-readiness-expired"
            )
            self.clearPendingAppleMessagesRequest()
            self.appendRouteReceipt(
                "APPLE-MESSAGES pending recovery expired")
        }
    }

    /// Readiness and lookup are local Apple Events with no mutation. The exact
    /// content stays in the bounded store until the shared broker reaches a
    /// terminal state or a lifecycle boundary scrubs it.
    private func observeAppleMessagesReadiness(
        for pending: PendingAppleMessagesIntent
    ) {
        appleMessagesReadinessGeneration = UUID()
        let generation = appleMessagesReadinessGeneration
        let intentID = pending.id
        appleMessagesReadinessTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.appleMessagesReadinessGeneration == generation {
                    self.appleMessagesReadinessTask = nil
                }
            }
            var didPresentSignInRecovery = false
            var didPresentConnectionRecovery = false
            var didPresentAutomationRecovery = false
            while !Task.isCancelled,
                  self.directEffectsAreAllowed,
                  self.appleMessagesReadinessGeneration == generation,
                  self.pendingAppleMessagesIntentStore.pendingIntent?.id
                    == intentID {
                let now = Date()
                guard let current = self.pendingAppleMessagesIntentStore
                    .current(now: now), current.id == intentID else {
                    self.clearPendingAppleMessagesRequest()
                    self.appendRouteReceipt(
                        "APPLE-MESSAGES pending recovery expired")
                    return
                }
                let plan = await self.appleMessagesActionProvider.plan(
                    recipient: current.intent.recipient,
                    body: current.intent.body
                )
                guard !Task.isCancelled,
                      self.directEffectsAreAllowed,
                      self.appleMessagesReadinessGeneration == generation,
                      self.pendingAppleMessagesIntentStore.pendingIntent?.id
                        == intentID else { return }
                switch plan {
                case .needsSignIn:
                    if !didPresentSignInRecovery {
                        didPresentSignInRecovery = true
                        self.appleMessagesNeedsSignIn = true
                        self.appleMessagesConnectionIsPending = false
                        self.appleMessagesRecipientSelection = nil
                        self.appendRouteReceipt(
                            "APPLE-MESSAGES waiting for signed-in account")
                        try? await self.noraVoice.speakText(
                            "Messages needs a signed-in iMessage account. select Open Messages; i'll keep this exact request only in memory and resume after sign-in is ready."
                        )
                    }

                case .waitingForConnection:
                    if !didPresentConnectionRecovery {
                        didPresentConnectionRecovery = true
                        self.appleMessagesNeedsSignIn = false
                        self.appleMessagesConnectionIsPending = true
                        self.appleMessagesRecipientSelection = nil
                        self.appendRouteReceipt(
                            "APPLE-MESSAGES waiting for connected account")
                        try? await self.noraVoice.speakText(
                            "Messages is signed in but not connected yet. i'll keep this exact request only in memory and resume after it reconnects."
                        )
                    }

                case .needsRecipientDisambiguation(let handles):
                    self.appleMessagesNeedsSignIn = false
                    self.appleMessagesConnectionIsPending = false
                    self.appleMessagesRecipientSelection =
                        AppleMessagesRecipientSelectionState(
                            requestIdentifier: intentID,
                            recipientHandles: handles
                        )
                    self.appendRouteReceipt(
                        "APPLE-MESSAGES exact recipient choice required")
                    try? await self.noraVoice.speakText(
                        "choose the exact Messages recipient in the Ace panel. nothing has been sent."
                    )
                    return

                case .ready(let request):
                    self.appleMessagesNeedsSignIn = false
                    self.appleMessagesConnectionIsPending = false
                    self.appleMessagesRecipientSelection = nil
                    self.appendRouteReceipt(
                        "APPLE-MESSAGES exact recipient resolved; preview started")
                    self.beginDirectAppActionPreview(
                        PlannedAppAction(
                            tool: .messages,
                            arguments: [request.handle, request.body]
                        ),
                        ownerTurnBinding:
                            self.pendingAppleMessagesRouteBinding
                    )
                    return

                case .blocked(let reason)
                    where reason
                        == AppleMessagesActionProvider
                            .automationUnavailableReason:
                    if !didPresentAutomationRecovery {
                        didPresentAutomationRecovery = true
                        self.appleMessagesNeedsSignIn = false
                        self.appleMessagesConnectionIsPending = false
                        self.appleMessagesRecipientSelection = nil
                        self.appendRouteReceipt(
                            "APPLE-MESSAGES Automation unavailable; recovery pending")
                        try? await self.noraVoice.speakText(
                            "Messages Automation is not available yet. use the optional Messages Automation control in the Ace panel; i'll keep this exact request only in memory."
                        )
                    }

                case .blocked:
                    self.finishPendingPrivateRoute(
                        self.pendingAppleMessagesRouteBinding,
                        status: .failed,
                        outcome: "messages-recipient-resolution-blocked"
                    )
                    self.clearPendingAppleMessagesRequest()
                    self.appendRouteReceipt(
                        "APPLE-MESSAGES recipient resolution blocked")
                    self.showVisibleResponse(
                        "Messages could not resolve one exact recipient. Nothing was sent."
                    )
                    try? await self.noraVoice.speakText(
                        "i couldn't resolve one exact Messages recipient, so nothing was sent."
                    )
                    return
                }
                do {
                    try await Task.sleep(for: .seconds(2))
                } catch {
                    return
                }
            }
        }
    }

    @discardableResult
    func selectAppleMessagesRecipient(_ handle: String) -> Bool {
        guard directEffectsAreAllowed,
              let pending = pendingAppleMessagesIntentStore.current(),
              let selection = appleMessagesRecipientSelection,
              selection.requestIdentifier == pending.id,
              selection.recipientHandles.contains(handle) else {
            return false
        }
        guard beginDirectAppActionPreview(
            PlannedAppAction(
                tool: .messages,
                arguments: [handle, pending.intent.body]
            ),
            ownerTurnBinding: pendingAppleMessagesRouteBinding
        ) else { return false }
        appleMessagesRecipientSelection = nil
        appleMessagesNeedsSignIn = false
        appendRouteReceipt(
            "APPLE-MESSAGES buyer selected exact recipient before preview")
        return true
    }

    func selectAppleMessagesRecipientFromUI(_ handle: String) {
        guard let lineage = beginIntegrationControlAction(
            .appleMessagesRecipientChoice,
            preservingPrivateRouteBinding:
                pendingAppleMessagesRouteBinding
        ) else { return }
        let accepted = selectAppleMessagesRecipient(handle)
        completeIntegrationControlAction(
            lineage,
            outcome: accepted ? .completed : .failed
        )
    }

    @discardableResult
    func connectAppleMessages() -> AceControlActionOutcome {
        guard directEffectsAreAllowed else {
            let outcome = controlFailure(
                code: "apple_messages.private_mode",
                message: "Exit Private Mode before opening Messages.",
                recoveryTitle: "Exit Private Mode and try again",
                recovery: .retry
            )
            appleMessagesControlOutcome = outcome
            return outcome
        }
        let outcome = AceWorkspaceOpenAction.perform(
            target: AppleMessagesActionProvider.signInDestination,
            copy: AceWorkspaceOpenCopy(
                successMessage:
                    "Messages opened. Sign in to iMessage, then return to Ace.",
                failureCode: "apple_messages.open_failed",
                failureMessage: "macOS did not open Messages.",
                recoveryTitle: "Try opening Messages again",
                recovery: .retry
            )
        )
        appleMessagesControlOutcome = outcome
        switch outcome {
        case .succeeded:
            appleMessagesNeedsSignIn = true
            appendRouteReceipt("APPLE-MESSAGES app opened")
        case let .failed(failure):
            appleMessagesNeedsSignIn = true
            showVisibleResponse(failure.message)
        case .started:
            break
        }
        return outcome
    }

    func connectAppleMessagesFromUI() {
        guard let lineage = beginIntegrationControlAction(
            .appleMessagesOpen,
            preservingPrivateRouteBinding:
                pendingAppleMessagesRouteBinding
        ) else { return }
        let outcome = connectAppleMessages()
        completeIntegrationControlAction(
            lineage,
            outcome: Self.directUIOutcome(for: outcome)
        )
    }

    func cancelPendingAppleMessagesFromUI() {
        let binding = pendingAppleMessagesRouteBinding
        guard let lineage = beginIntegrationControlAction(
            .appleMessagesPendingCancel,
            preservingPrivateRouteBinding: binding
        ) else { return }
        finishPendingPrivateRoute(
            binding,
            status: .cancelled,
            outcome: "messages-recovery-cancelled"
        )
        dismissVisibleAppActionReview()
        completeIntegrationControlAction(lineage, outcome: .cancelled)
    }

    func requestAutomationTargetFromUI(
        _ target: PermissionAutomationTarget
    ) {
        guard let lineage = beginIntegrationControlAction(
            .optionalAutomationTarget,
            preservingPrivateRouteBinding:
                pendingAppleMessagesRouteBinding
                    ?? pendingAppleMailRouteBinding
        ) else { return }
        Task { @MainActor [weak self] in
            guard let self else { return }
            let status: PermissionAutomationTargetStatus?
            if lineage.lifecycle.preservedPrivateParent != nil {
                status = await self.ownerTurnLifecycle
                    .performPrivateRecoveryAutomationLaunch(
                        for: lineage.lifecycle
                    ) { _ in
                        await self.permissionWarmup
                            .requestAndProveAutomation(for: target)
                    }
            } else {
                status = await self.permissionWarmup
                    .requestAndProveAutomation(for: target)
            }
            guard let status else {
                if self.completeIntegrationControlAction(
                    lineage,
                    outcome: .failed
                ) {
                    self.showVisibleResponse(
                        "That private recovery is no longer active. Nothing ran."
                    )
                }
                return
            }
            let outcome: AceDirectHumanUIActionOutcome
            switch status {
            case .allowed:
                outcome = .completed
            case .notRequested:
                outcome = .cancelled
            case .checking, .denied, .targetCrashed, .checkFailed:
                outcome = .failed
            }
            self.completeIntegrationControlAction(
                lineage,
                outcome: outcome
            )
        }
    }

    private func beginIntegrationControlAction(
        _ action: AceDirectHumanUIAction,
        preservingPrivateRouteBinding privateBinding:
            OwnerTurnBinding? = nil
    ) -> IntegrationControlActionBinding? {
        let bus = AceEventBus.shared
        guard let lineage = bus.beginDirectHumanUIAction(action) else {
            return nil
        }
        let lifecycle = ownerTurnLifecycle.admitDirectControl(
            sessionID: bus.sessionID,
            turnID: lineage.turnID,
            correlationID: lineage.correlationID,
            controlID: action.rawValue,
            preservingPrivateParent: privateBinding
        )
        let binding = IntegrationControlActionBinding(
            lineage: lineage,
            lifecycle: lifecycle
        )
        activeRoutingTurnID = lineage.turnID
        activeRoutingSessionID = bus.sessionID
        activeRoutingCorrelationID = lineage.correlationID
        activeContextualOwnerRequest = nil
        activeOwnerTurnContext = lifecycle.control.context
        if privateBinding != nil,
           lifecycle.preservedPrivateParent == nil {
            _ = completeIntegrationControlAction(
                binding,
                outcome: .failed
            )
            appendRouteReceipt(
                "PRIVATE-RECOVERY stale control rejected"
            )
            showVisibleResponse(
                "That private recovery is no longer active. Nothing ran."
            )
            return nil
        }
        return binding
    }

    @discardableResult
    private func completeIntegrationControlAction(
        _ binding: IntegrationControlActionBinding,
        outcome: AceDirectHumanUIActionOutcome
    ) -> Bool {
        let published = ownerTurnLifecycle.finishDirectControl(
            binding.lifecycle,
            status: outcome.eventState,
            outcome: "control." + outcome.rawValue
        )
        if published,
           let parent = binding.lifecycle.preservedPrivateParent,
           ownerTurnLifecycle.startedPrivateRecoveryBinding(parent)
                == parent {
            activeRoutingTurnID = parent.context.turnID
            activeRoutingSessionID = parent.context.sessionID
            activeRoutingCorrelationID = parent.correlationID
            activeOwnerTurnContext = parent.context
        }
        return published
    }

    private static func directUIOutcome(
        for outcome: AceControlActionOutcome
    ) -> AceDirectHumanUIActionOutcome {
        switch outcome {
        case .started, .succeeded:
            return .completed
        case .failed:
            return .failed
        }
    }

    private func clearPendingAppleMessagesRequest() {
        appleMessagesReadinessTask?.cancel()
        appleMessagesReadinessTask = nil
        appleMessagesPendingIntentExpiryTask?.cancel()
        appleMessagesPendingIntentExpiryTask = nil
        appleMessagesReadinessGeneration = UUID()
        pendingAppleMessagesIntentStore.cancel()
        pendingAppleMessagesRouteBinding = nil
        appleMessagesRecipientSelection = nil
        appleMessagesNeedsSignIn = false
        appleMessagesConnectionIsPending = false
    }

    /// Readiness prompts are terminal manager outcomes for the original
    /// private compose turn. The exact request remains only in Task 5's
    /// bounded in-memory store; this receipt carries a fixed content-free ID.
    private func finishPendingPrivateRoute(
        _ binding: OwnerTurnBinding?,
        status: AceEventState,
        outcome: String
    ) {
        guard let binding else { return }
        _ = ownerTurnLifecycle.finishManagerDispatch(
            turnID: binding.context.turnID,
            correlationID: binding.correlationID,
            status: status,
            outcome: outcome
        )
    }

    /// Native location never goes through Gold. This route owns the system
    /// prompt and the session-only weather context; the existing broker still
    /// owns the exact wrapper preview and execution receipt.
    private func routeNativeLocationIntentIfPresent(
        _ context: OwnerTurnContext
    ) -> Bool {
        switch context.selectedRoute {
        case "native.location.access":
            guard directEffectsAreAllowed else { return true }
            guard let binding = ownerTurnLifecycle.activeBinding,
                  binding.context == context,
                  binding.correlationID == activeRoutingCorrelationID else {
                appendRouteReceipt(
                    "LOCATION native request refused missing frozen binding"
                )
                return true
            }
            appendRouteReceipt("LOCATION native request started")
            let manager = nativeLocationManager ?? NativeLocationManager()
            nativeLocationManager = manager
            ownerTurnLifecycle.startLocationRequest(
                for: binding,
                request: { completion in
                    manager.requestCurrentFixJustInTime(
                        completion: completion
                    )
                },
                receive: { [weak self] frozenBinding, outcome in
                guard let self else { return }
                self.nativeLocationManager = nil
                guard self.directEffectsAreAllowed,
                      !self.stealthMode.isActive else { return }
                if case let .ready(fix) = outcome {
                    self.localWeatherSessionContext.rememberDeviceFix(
                        fix,
                        sessionID: frozenBinding.context.sessionID
                    )
                }
                let resultLabel: String
                switch outcome {
                case .ready: resultLabel = "ready"
                case .denied: resultLabel = "denied"
                case .restricted: resultLabel = "restricted"
                case .servicesUnavailable: resultLabel = "services-unavailable"
                case .locationUnavailable: resultLabel = "fix-unavailable"
                case .authorizationTimedOut: resultLabel = "authorization-timeout"
                case .locationTimedOut: resultLabel = "fix-timeout"
                }
                self.appendRouteReceipt(
                    "LOCATION native request completed result=\(resultLabel)"
                )
                let terminalState: AceEventState
                if case .ready = outcome {
                    terminalState = .completed
                } else {
                    terminalState = .failed
                }
                _ = self.finishVolatileOwnerTurn(
                    turnID: frozenBinding.context.turnID,
                    correlationID: frozenBinding.correlationID,
                    status: terminalState,
                    outcome: "location.\(resultLabel)",
                    reason: outcome.ownerFacingLine
                )
                },
                stale: { [weak self] frozenBinding in
                    self?.appendRouteReceipt(
                        "LOCATION stale callback rejected turn="
                            + AceEventIdentifier.short(
                                frozenBinding.context.turnID
                            )
                    )
                }
            )
            return true

        case "native.weather.spoken-locality",
             "native.weather.explicit-locality":
            guard directEffectsAreAllowed,
                  let locality = context.resolvedSlots["locality"] else {
                return true
            }
            appendRouteReceipt(
                "LOCATION weather source=spoken-locality characters=\(locality.count)"
            )
            beginDirectAppActionPreview(
                PlannedAppAction(tool: .weather, arguments: [locality])
            )
            return true

        case "native.weather.locality-clarification":
            _ = bindOwnerTurnContext(context)
            return true

        case "native.weather.device-current":
            guard directEffectsAreAllowed else { return true }
            let resolution = localWeatherSessionContext.weatherResolution(
                explicitLocality: nil,
                sessionID: context.sessionID
            )
            switch resolution {
            case let .spokenLocality(locality):
                beginDirectAppActionPreview(
                    PlannedAppAction(tool: .weather, arguments: [locality])
                )
            case let .deviceLocation(coordinates):
                appendRouteReceipt("LOCATION weather source=native-fix")
                beginDirectAppActionPreview(
                    PlannedAppAction(tool: .weather, arguments: [coordinates])
                )
            case .needsSpokenLocality:
                _ = ownerTurnLifecycle.transitionToSpokenLocality(
                    for: context
                )
                askForSpokenWeatherLocality(
                    turnID: context.turnID,
                    correlationID: activeRoutingCorrelationID
                )
            case .needsDeviceLocationRecovery:
                requestWeatherLocationJustInTime(for: context)
            }
            return true
        default:
            return false
        }
    }

    private func requestWeatherLocationJustInTime(
        for context: OwnerTurnContext
    ) {
        guard let binding = ownerTurnLifecycle.activeBinding,
              binding.context == context,
              binding.correlationID == activeRoutingCorrelationID else {
            appendRouteReceipt(
                "LOCATION weather request refused missing frozen binding"
            )
            return
        }
        appendRouteReceipt("LOCATION weather just-in-time fix started")
        let manager = nativeLocationManager ?? NativeLocationManager()
        nativeLocationManager = manager
        ownerTurnLifecycle.startLocationRequest(
            for: binding,
            requiringSpokenLocalityOnFailure: true,
            request: { completion in
                manager.requestCurrentFixJustInTime(completion: completion)
            },
            receive: { [weak self] frozenBinding, outcome in
            guard let self else { return }
            self.nativeLocationManager = nil
            guard self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            switch outcome {
            case let .ready(fix):
                self.localWeatherSessionContext.rememberDeviceFix(
                    fix,
                    sessionID: frozenBinding.context.sessionID
                )
                self.appendRouteReceipt(
                    "LOCATION weather just-in-time fix ready"
                )
                self.beginDirectAppActionPreview(
                    PlannedAppAction(
                        tool: .weather,
                        arguments: [fix.weatherQuery]
                    )
                )
            case .denied, .restricted, .servicesUnavailable,
                 .locationUnavailable, .authorizationTimedOut,
                 .locationTimedOut:
                self.localWeatherSessionContext
                    .rememberDeviceLocationUnavailable(
                        sessionID: frozenBinding.context.sessionID
                    )
                self.appendRouteReceipt(
                    "LOCATION weather just-in-time fix unavailable"
                )
                self.askForSpokenWeatherLocality(
                    turnID: frozenBinding.context.turnID,
                    correlationID: frozenBinding.correlationID
                )
            }
            },
            stale: { [weak self] frozenBinding in
                self?.appendRouteReceipt(
                    "LOCATION stale callback rejected turn="
                        + AceEventIdentifier.short(
                            frozenBinding.context.turnID
                        )
                )
            }
        )
    }

    private func askForSpokenWeatherLocality(
        turnID: UUID,
        correlationID: UUID?
    ) {
        let question =
            "I couldn't read a current Mac location. Which city and state should I use for this weather request?"
        _ = finishVolatileOwnerTurn(
            turnID: turnID,
            correlationID: correlationID,
            status: .failed,
            outcome: "weather.locality-required",
            reason: question
        )
    }

    @discardableResult
    private func beginDirectAppActionPreview(
        _ action: PlannedAppAction,
        ownerTurnBinding: OwnerTurnBinding? = nil
    ) -> Bool {
        guard appActionPlanningTask == nil,
              !isPreparingTestEmailSend,
              pendingTestEmailSend == nil,
              testEmailTask == nil,
              !(testEmailProcess?.isRunning ?? false),
              directEffectsAreAllowed else {
            finishActiveAppActionRequest(
                status: .blocked,
                outcome: "blocked.app-action-busy",
                verification: "none",
                reason:
                    "A different app action or Apple Mail self-test was already active, so this request did not start."
            )
            return false
        }
        let generation = UUID()
        guard bindCurrentWorkToAppAction(
            ownerTurnBinding: ownerTurnBinding
        ) else {
            rejectUnboundAppAction(
                isPrivateRecovery: ownerTurnBinding != nil
            )
            return false
        }
        appActionPlanningGeneration = generation
        backgroundTaskActive = true
        showCursorOverlayForBackgroundTask()
        appActionPlanningTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.appActionPlanningGeneration == generation {
                    self.appActionPlanningTask = nil
                    self.backgroundTaskActive =
                        self.meetingNotetaker.isTakingNotes
                            || self.anyBackgroundExecutionAgentIsWorking
                }
            }
            do {
                let prepared = try self.appActionBroker.prepare(action)
                guard !Task.isCancelled,
                      self.appActionPlanningGeneration == generation,
                      self.directEffectsAreAllowed else {
                    throw CancellationError()
                }
                if action.tool == .emailSend {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: generation, exactPreview: prepared.preview,
                        phase: .ready(expiresAt: prepared.expiresAt)
                    )
                    self.appActionReviewExpiryTask?.cancel()
                    self.appActionReviewExpiryTask = Task { [weak self] in
                        do { try await Task.sleep(for: .seconds(max(0, prepared.expiresAt.timeIntervalSinceNow))) }
                        catch { return }
                        guard let self, self.appActionReview?.planIdentifier == generation,
                              self.appActionPlanningGeneration == generation else { return }
                        self.cancelVisibleAppActionReview()
                    }
                    self.showVisibleResponse("Your email is ready. Review the exact message and select Send.")
                    return
                }
                self.appendRouteReceipt(
                    "APP-ACTION prepared-for-immediate-execution tool="
                        + action.tool.rawValue
                )
                self.executePreparedAppAction()
            } catch {
                guard !Task.isCancelled,
                      self.appActionPlanningGeneration == generation,
                      self.directEffectsAreAllowed else {
                    return
                }
                self.appActionBroker.discardCurrentPlan()
                self.appendRouteReceipt(
                    "APP-ACTION direct plan could not be staged"
                )
                let reason = "The exact app action could not be staged."
                if self.completeDurableAppAction(
                    status: .failed,
                    outcome: "staging-failed",
                    verification: "none",
                    reason: reason,
                    showVisible: true,
                    speak: true
                ) {
                    self.appActionReview = AppActionReviewState(
                        planIdentifier: generation,
                        exactPreview: "",
                        phase: .notArmed(reason: reason)
                    )
                }
            }
        }
        return true
    }
    private func executePreparedAppAction(confirmation: String? = nil) {
        appActionReviewExpiryTask?.cancel()
        appActionReviewExpiryTask = nil
        guard directEffectsAreAllowed else {
            appActionBroker.discardCurrentPlan()
            let reason =
                "The privacy wall blocked the prepared app action before execution. Nothing ran."
            let priorPreview = appActionReview?.exactPreview ?? ""
            if completeDurableAppAction(
                status: .blocked,
                outcome: "blocked.privacy-wall",
                verification: "none",
                reason: reason,
                showVisible: true,
                speak: true
            ) {
                appActionReview = AppActionReviewState(
                    planIdentifier: appActionPlanningGeneration,
                    exactPreview: priorPreview,
                    phase: .notArmed(reason: reason)
                )
            }
            return
        }
        appActionReview = nil
        backgroundTaskActive = true
        showCursorOverlayForBackgroundTask()
        Task { [weak self] in
            guard let self else { return }
            defer {
                self.backgroundTaskActive =
                    self.meetingNotetaker.isTakingNotes
                        || self.anyBackgroundExecutionAgentIsWorking
            }
            guard self.directEffectsAreAllowed else {
                self.appActionBroker.discardCurrentPlan()
                self.completeDurableAppAction(
                    status: .blocked,
                    outcome: "blocked.privacy-wall",
                    verification: "none",
                    reason:
                        "The privacy wall blocked the prepared app action before execution. Nothing ran.",
                    showVisible: true,
                    speak: true
                )
                return
            }
            let outcome: AppActionOutcome
            if let confirmation {
                outcome = await self.appActionBroker.executeCurrentPlan(
                    afterDirectUserConfirmation: confirmation
                )
            } else {
                outcome = await self.appActionBroker.executePrepared()
            }
            guard !Task.isCancelled,
                  self.directEffectsAreAllowed else {
                self.completeDurableAppAction(
                    status: .cancelled,
                    outcome: "cancelled.execution-interrupted",
                    verification: "none",
                    reason:
                        "App-action execution was interrupted before its terminal receipt could be accepted.",
                    showVisible: true,
                    speak: true
                )
                return
            }

            switch outcome {
            case .verified(let receipt):
                let terminalReason = Self.retainedAppResult(
                    receipt.standardOutput,
                    fallback:
                        "The app action completed and was verified."
                )
                self.appendRouteReceipt(
                    "APP-ACTION verified tool=\(receipt.tool.rawValue) "
                        + "exit=\(receipt.exitStatus)")
                self.completeDurableAppAction(
                    status: .completed,
                    outcome: "verified",
                    verification: "verified",
                    reason: terminalReason,
                    showVisible: true,
                    speak: true
                )

            case .attempted(let receipt):
                let terminalReason = Self.retainedAppResult(
                    receipt.standardOutput,
                    fallback:
                        "macOS accepted the request, but Ace could not independently verify the visual result."
                )
                self.appendRouteReceipt(
                    "APP-ACTION attempted-unverified "
                        + "tool=\(receipt.tool.rawValue) "
                        + "exit=\(receipt.exitStatus)")
                self.completeDurableAppAction(
                    status: .completed,
                    outcome: "attempted",
                    verification: "attempted",
                    reason: terminalReason,
                    showVisible: true,
                    speak: true
                )

            case .failed(let failure):
                let terminalReason = Self.retainedAppResult(
                    failure.message,
                    fallback:
                        "The app action failed; no success was claimed."
                )
                self.appendRouteReceipt(
                    "APP-ACTION failed tool="
                        + (failure.tool?.rawValue ?? "none")
                        + " exit="
                        + (failure.exitStatus.map(String.init) ?? "none"))
                self.completeDurableAppAction(
                    status: .failed,
                    outcome: "failed."
                        + (failure.tool?.rawValue ?? "unknown-tool")
                        + (failure.exitStatus.map {
                            ".exit-\($0)"
                        } ?? ".launch"),
                    verification: "none",
                    reason: terminalReason,
                    showVisible: true,
                    speak: true
                )

            case .blocked(let block):
                self.appendRouteReceipt(
                    "APP-ACTION blocked reason=\(block.reason.rawValue)")
                let fallback = block.reason == .confirmationExpired
                    ? "that app-action confirmation expired before it ran, so nothing happened. "
                        + "say the word and i'll put the confirmation back up."
                    : "the app-action safety boundary blocked it."
                let terminalReason = Self.retainedAppResult(
                    block.message,
                    fallback: fallback
                )
                self.completeDurableAppAction(
                    status: .blocked,
                    outcome: "blocked.\(block.reason.rawValue)",
                    verification: "none",
                    reason: terminalReason,
                    showVisible: true,
                    speak: true
                )
            }
        }
    }

    @discardableResult
    private func bindCurrentWorkToAppAction(
        ownerTurnBinding: OwnerTurnBinding? = nil
    ) -> Bool {
        if let ownerTurnBinding {
            var acceptedBinding: OwnerTurnBinding?
            guard ownerTurnLifecycle.dispatchPrivateRecoveryAppAction(
                for: ownerTurnBinding,
                execute: { acceptedBinding = $0 }
            ), let acceptedBinding else {
                return false
            }
            appActionWorkCorrelationIdentifier =
                acceptedBinding.correlationID
            appActionVolatileTurnIdentifier =
                acceptedBinding.context.turnID
            appActionUsesVolatileTurnContext = true
            return true
        }
        if let context = activeOwnerTurnContext,
           !context.permitsDurableContext,
           let correlationID = activeRoutingCorrelationID {
            guard ownerTurnLifecycle.deferManagerDispatch(
                for: context
            ) else {
                return false
            }
            appActionWorkCorrelationIdentifier = correlationID
            appActionVolatileTurnIdentifier = context.turnID
            appActionUsesVolatileTurnContext = true
            return true
        }
        guard let request = activeContextualOwnerRequest else {
            return false
        }
        appActionUsesVolatileTurnContext = false
        appActionVolatileTurnIdentifier = nil
        let persisted = bindRunningWorkDurably(
            workCorrelationIdentifier:
                request.childWorkCorrelationIdentifier,
            lane: .gold,
            durableLane: "app-action"
        )
        if persisted {
            appActionWorkCorrelationIdentifier =
                request.childWorkCorrelationIdentifier
        }
        return persisted
    }

    /// A stale private recovery never starts a provider/tool task. Its
    /// content-free refusal is visible while the bounded Mail/Messages values
    /// are scrubbed from their in-memory stores.
    private func rejectUnboundAppAction(
        isPrivateRecovery: Bool
    ) {
        let reason = isPrivateRecovery
            ? "That private recovery is no longer active. Nothing ran."
            : "Ace could not bind this app action to its owner request, so nothing ran."
        if isPrivateRecovery {
            clearPendingAppleMailDraftRequest()
            clearPendingAppleMessagesRequest()
            appendRouteReceipt(
                "PRIVATE-RECOVERY app action rejected stale binding"
            )
        } else {
            appendRouteReceipt("APP-ACTION context binding rejected")
        }
        showVisibleResponse(reason)
        Task {
            try? await noraVoice.speakText(reason)
        }
    }

    @discardableResult
    private func completeDurableAppAction(
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String,
        showVisible: Bool = false,
        speak: Bool = false
    ) -> Bool {
        // Private compose/message values are execution inputs, not receipt
        // recovery state. Scrub them as soon as any app-action terminal is
        // known, even if its content-free durable receipt must retry later.
        clearPendingAppleMailDraftRequest()
        clearPendingAppleMessagesRequest()
        guard let workID = appActionWorkCorrelationIdentifier else {
            return false
        }
        if appActionUsesVolatileTurnContext {
            let eventState: AceEventState
            switch status {
            case .completed:
                eventState = .completed
            case .cancelled:
                eventState = .cancelled
            case .blocked, .failed, .running:
                eventState = .failed
            }
            let terminalReview = appActionReview.map {
                AppActionReviewState(
                    planIdentifier: $0.planIdentifier,
                    exactPreview: $0.exactPreview,
                    phase: .notArmed(reason: reason)
                )
            }
            let published = finishVolatileOwnerTurn(
                turnID: appActionVolatileTurnIdentifier,
                correlationID: workID,
                status: eventState,
                outcome: "app-action." + outcome,
                reason: reason,
                showVisible: showVisible,
                speak: speak
            )
            guard published else { return false }
            if let terminalReview {
                appActionReview = terminalReview
            }
            appActionWorkCorrelationIdentifier = nil
            appActionVolatileTurnIdentifier = nil
            appActionUsesVolatileTurnContext = false
            return true
        }
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            deferredAppActionTerminal = nil
            return false
        }
        let proposed = DeferredAppActionTerminal(
            workCorrelationIdentifier: workID,
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason,
            showVisible: showVisible,
            speak: speak,
            terminalReview: appActionReview.map {
                AppActionReviewState(
                    planIdentifier: $0.planIdentifier,
                    exactPreview: $0.exactPreview,
                    phase: .notArmed(reason: reason)
                )
            }
        )
        if let existing = deferredAppActionTerminal {
            guard existing == proposed else {
                appendRouteReceipt(
                    "APP-ACTION deferred terminal conflict refused work="
                        + workID.uuidString.lowercased()
                )
                return false
            }
        } else {
            deferredAppActionTerminal = proposed
        }
        return retryDeferredAppActionTerminal(
            deferredAppActionTerminal ?? proposed
        )
    }

    @discardableResult
    private func retryDeferredAppActionTerminal(
        _ terminal: DeferredAppActionTerminal
    ) -> Bool {
        let persisted = persistDurableWorkTerminal(
            workCorrelationIdentifier:
                terminal.workCorrelationIdentifier,
            lane: "app-action",
            status: terminal.status,
            outcome: terminal.outcome,
            verification: terminal.verification,
            reason: terminal.reason
        )
        guard persisted else { return false }
        guard performTerminalPublicationUnlessStealth({
            if let work = goldContextBundle.workRecords.first(where: {
                $0.workCorrelationIdentifier == terminal.workCorrelationIdentifier
            }) {
                retainNativeConversationTerminal(
                    turnID: work.sourceTurnIdentifier,
                    correlationID: work.sourceCorrelationIdentifier,
                    status: terminal.status == .cancelled ? .cancelled : .completed,
                    response: terminal.reason
                )
            }
            if let terminalReview = terminal.terminalReview {
                appActionReview = terminalReview
            }
            if terminal.showVisible {
                showVisibleResponse(terminal.reason)
            }
            if terminal.speak {
                Task { [weak self] in
                    guard let self,
                          self.directEffectsAreAllowed,
                          !self.stealthMode.isActive else { return }
                    try? await self.noraVoice.speakText(
                        terminal.reason
                    )
                }
            }
            return true
        }) else {
            return false
        }
        deferredAppActionTerminal = nil
        if appActionWorkCorrelationIdentifier
            == terminal.workCorrelationIdentifier {
            appActionWorkCorrelationIdentifier = nil
        }
        return true
    }

    @discardableResult
    private func finishGoldAnswerTerminal(
        _ terminal: DeferredGoldAnswerTerminal
    ) -> Bool {
        guard directEffectsAreAllowed, !stealthMode.isActive else {
            deferredGoldAnswerTerminals.removeValue(
                forKey: terminal.workCorrelationIdentifier
            )
            return false
        }
        if let existing = deferredGoldAnswerTerminals[
            terminal.workCorrelationIdentifier
        ] {
            guard existing == terminal else {
                appendRouteReceipt(
                    "GOLD answer terminal conflict refused work="
                        + terminal.workCorrelationIdentifier
                            .uuidString.lowercased()
                )
                return false
            }
            return retryDeferredGoldAnswerTerminal(existing)
        }
        deferredGoldAnswerTerminals[
            terminal.workCorrelationIdentifier
        ] = terminal
        return retryDeferredGoldAnswerTerminal(terminal)
    }

    @discardableResult
    private func retryDeferredGoldAnswerTerminal(
        _ terminal: DeferredGoldAnswerTerminal
    ) -> Bool {
        // An unbound fallback used to enqueue an invented UUID forever. It
        // owns no durable work and must never prevent the next owner turn.
        guard let record = goldContextBundle.workRecords.first(where: {
            $0.workCorrelationIdentifier == terminal.workCorrelationIdentifier
        }) else {
            deferredGoldAnswerTerminals.removeValue(forKey: terminal.workCorrelationIdentifier)
            appendRouteReceipt("GOLD unbound answer terminal retired work=" + terminal.workCorrelationIdentifier.uuidString.lowercased())
            return false
        }
        if let request = terminal.request,
           goldContextBundle.supersedingTerminal(
                workCorrelationIdentifier: terminal.workCorrelationIdentifier,
                sourceSessionIdentifier: request.sourceSessionIdentifier,
                sourceTurnIdentifier: request.sourceTurnIdentifier,
                sourceCorrelationIdentifier: request.sourceCorrelationIdentifier,
                proposedStatus: terminal.status,
                proposedOutcome: terminal.outcome,
                proposedVerification: terminal.verification,
                proposedReason: terminal.reason
           ) != nil {
            guard AceConversationHistory.saveBundle(
                goldContextBundle,
                performUnlessRaised: { body in StealthEntryLatch.shared.performUnlessRaised(body) }
            ) else { return false }
            deferredGoldAnswerTerminals.removeValue(forKey: terminal.workCorrelationIdentifier)
            appendRouteReceipt("GOLD stale answer retired status=" + record.status.rawValue)
            return false
        }
        let updated: Bool
        if let response = terminal.assistantResponse {
            updated = goldContextBundle.appendExchange(
                workCorrelationIdentifier:
                    terminal.workCorrelationIdentifier,
                assistantResponse: response,
                status: terminal.status,
                lane: "gold",
                terminalOutcome: terminal.outcome,
                terminalVerification: terminal.verification,
                terminalReason: terminal.reason
            )
        } else {
            updated = goldContextBundle.transitionWork(
                workCorrelationIdentifier:
                    terminal.workCorrelationIdentifier,
                lane: "gold",
                status: terminal.status,
                terminalOutcome: terminal.outcome,
                terminalVerification: terminal.verification,
                terminalReason: terminal.reason
            )
        }
        guard updated,
              AceConversationHistory.saveBundle(
                  goldContextBundle,
                  performUnlessRaised: { body in
                      StealthEntryLatch.shared.performUnlessRaised(body)
                  }
              ) else {
            return false
        }
        let recentStatus: RecentOwnerWorkStatus
        switch terminal.status {
        case .running: recentStatus = .running
        case .completed: recentStatus = .completed
        case .failed: recentStatus = .failed
        case .blocked: recentStatus = .blocked
        case .cancelled: recentStatus = .cancelled
        }
        guard performTerminalPublicationUnlessStealth({
            _ = recentOwnerWorkStore.transition(
                workCorrelationIdentifier:
                    terminal.workCorrelationIdentifier,
                lane: .gold,
                status: recentStatus
            )
            switch terminal.publication {
            case .answer(let text):
                publishDurableGoldAnswer(text)
            case .pipelineFailure(let failureReason):
                speakBrainErrorFallback(failureReason: failureReason)
            case .none:
                break
            }
            let terminalPhase = self.buyerPhase(
                status: terminal.status,
                lane: .gold
            )
            self.upsertBuyerWorkReceipt(
                workID: terminal.workCorrelationIdentifier,
                lane: .gold,
                phase: terminalPhase,
                progress: terminal.status == .running
                    ? terminal.reason : self.buyerProgress(phase: terminalPhase, lane: .gold),
                terminalResult: terminal.status == .running
                    ? nil : terminal.reason,
                recoveryAction: self.buyerRecoveryAction(
                    status: terminal.status
                )
            )
            return true
        }) else { return false }
        deferredGoldAnswerTerminals.removeValue(
            forKey: terminal.workCorrelationIdentifier
        )
        return true
    }

    private func publishDurableGoldAnswer(_ text: String) {
        BlackLabelAnalytics.trackAIResponseReceived(response: text)
        var delivery = ResponseDeliveryTransaction(responseText: text)
        let identifier = delivery.id
        showVisibleResponse(text)
        _ = delivery.advance(.visible, for: identifier)
        _ = delivery.advance(.speechQueued, for: identifier)
        responseDeliveryTransaction = delivery
        Task { [weak self] in
            guard let self,
                  self.directEffectsAreAllowed,
                  !self.stealthMode.isActive else { return }
            let completed = await self.noraVoice
                .speakTextToVerifiedCompletion(text)
            guard self.responseDeliveryTransaction?.id == identifier else {
                return
            }
            delivery = self.responseDeliveryTransaction ?? delivery
            if completed {
                if delivery.phase == .speechQueued {
                    _ = delivery.advance(.speechStarted, for: identifier)
                }
                _ = delivery.advance(.completed, for: identifier)
            } else {
                _ = delivery.advance(
                    .failed(
                        reason:
                            "Speech failed to start or complete."
                    ),
                    for: identifier
                )
                self.showVisibleResponse(
                    text
                        + "\n\nSpeech failed to start or complete. The text answer remains available."
                )
            }
            self.responseDeliveryTransaction = delivery
        }
    }

    private func finishActiveAppActionRequest(
        status: AceGoldWorkStatus,
        outcome: String,
        verification: String,
        reason: String
    ) {
        guard let workID = activeContextualOwnerRequest?
                .childWorkCorrelationIdentifier else {
            return
        }
        _ = finishDirectTextTerminal(
            workCorrelationIdentifier: workID,
            lane: .gold,
            durableLane: "app-action",
            status: status,
            outcome: outcome,
            verification: verification,
            reason: reason,
            slot: .none,
            source: .system,
            turnIdentifier: sourceTurnIdentifier(forWork: workID),
            speak: false
        )
    }

    private static func retainedAppResult(_ value: String, fallback: String) -> String {
        value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? fallback : value
    }

    private static func boundedSpokenAppResult(
        _ value: String,
        fallback: String
    ) -> String {
        let singleLine = value
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        guard !singleLine.isEmpty else { return fallback }
        guard singleLine.count > 700 else { return singleLine }
        return String(singleLine.prefix(699)) + "… More is available in Work Receipts."
    }

    private var anyBackgroundExecutionAgentIsWorking: Bool {
        backgroundAgent.isWorking || silverBackgroundAgent.isWorking
            || !pendingBackgroundExecutions.isEmpty
    }

    private var meetingCaptureOwnsVoiceOutput: Bool {
        meetingNotetaker.isTakingNotes || meetingNotetaker.isStartingUp
    }

    private var silverWorkflowReservesExecutionSlot: Bool {
        workflowRuntime.isPlanning
            || workflowRuntime.isBuilding
            || workflowRuntime.hasPendingPlan
    }

    private func nextBackgroundExecutionSlot()
        -> BackgroundExecutionSlot?
    {
        BackgroundExecutionSlotPolicy.select(
            redAgentIsActive: backgroundAgent.isWorking
                || reservedBackgroundExecutionSlots.contains(.red),
            silverAgentIsActive: silverBackgroundAgent.isWorking
                || reservedBackgroundExecutionSlots.contains(.silver),
            silverWorkflowIsActive:
                silverWorkflowReservesExecutionSlot,
            privacyWallIsActive: !directEffectsAreAllowed
                || stealthMode.isActive
        )
    }

    private func backgroundExecutionAgent(
        for executionSlot: BackgroundExecutionSlot
    ) -> BackgroundAgent {
        executionSlot == .red
            ? backgroundAgent
            : silverBackgroundAgent
    }

    private func enqueueBackgroundExecution(_ request: QueuedBackgroundExecution) {
        guard directEffectsAreAllowed, !stealthMode.isActive,
              pendingBackgroundExecutions.append(request) else { return }
        upsertBuyerWorkReceipt(
            workID: request.id, lane: .red, phase: .accepted,
            progress: "Queued; starts automatically when a worker is available."
        )
        backgroundTaskActive = true
        appendRouteReceipt("EXECUTION queued work=\(request.id) pending=\(pendingBackgroundExecutions.count)")
        guard backgroundQueueDrainTask == nil else { return }
        let generation = backgroundDispatchGeneration
        backgroundQueueDrainTask = Task { [weak self] in
            defer {
                if self?.backgroundDispatchGeneration == generation {
                    self?.backgroundQueueDrainTask = nil
                }
            }
            while !Task.isCancelled {
                guard let self, self.backgroundDispatchGeneration == generation,
                      self.directEffectsAreAllowed, !self.stealthMode.isActive,
                      let next = self.pendingBackgroundExecutions.first else { return }
                let slot = self.nextBackgroundExecutionSlot()
                let ownerRequest: String
                switch next.terminalOwner {
                case .gold(let request): ownerRequest = request.resolvedRequest
                case .direct: ownerRequest = next.instruction
                }
                let paired = PairedAgentReviewPolicy.isRequested(in: ownerRequest)
                if let slot, !paired || PairedAgentReviewPolicy.canReserveBoth(
                    primarySlot: slot,
                    silverAgentIsActive: self.silverBackgroundAgent.isWorking,
                    silverWorkflowIsActive: self.silverWorkflowReservesExecutionSlot,
                    silverIsReserved: self.reservedBackgroundExecutionSlots.contains(.silver)
                ) {
                    _ = self.pendingBackgroundExecutions.removeFirst()
                    self.dispatchBackgroundTask(
                        next.instruction, providerTurn: next.providerTurn,
                        speakResult: next.speakResult, terminalOwner: next.terminalOwner,
                        preselectedExecutionSlot: slot,
                        conversationContext: next.conversationContext
                    )
                } else {
                    do { try await Task.sleep(for: .milliseconds(250)) }
                    catch { return }
                }
            }
        }
    }

    /// Hands a task to the first free background execution slot, lights that
    /// slot's gem, and speaks the result without blocking the gold cursor.
    private func dispatchBackgroundTask(
        _ instruction: String,
        providerTurn: AceProviderTurn,
        speakResult: Bool = true,
        terminalOwner: BackgroundTaskTerminalOwner,
        preselectedExecutionSlot: BackgroundExecutionSlot? = nil,
        conversationContext: String? = nil
    ) {
        let retainedConversation = conversationContext ?? goldContextBundle.executionContext(for: instruction)
            + "\n" + foregroundNavigationContext.prompt(for: AceEventBus.shared.sessionID)
            + "\n" + nativeConversationContext.prompt(for: AceEventBus.shared.sessionID)
        let ownerRequest: String
        switch terminalOwner {
        case .gold(let request): ownerRequest = request.resolvedRequest
        case .direct: ownerRequest = instruction
        }
        let pairedReview = PairedAgentReviewPolicy.isRequested(in: ownerRequest)
        let proposedSlot = preselectedExecutionSlot ?? nextBackgroundExecutionSlot()
        guard let executionSlot = proposedSlot,
              !pairedReview || PairedAgentReviewPolicy.canReserveBoth(
                  primarySlot: proposedSlot,
                  silverAgentIsActive: silverBackgroundAgent.isWorking,
                  silverWorkflowIsActive: silverWorkflowReservesExecutionSlot,
                  silverIsReserved: reservedBackgroundExecutionSlots.contains(.silver)
              ),
              reservedBackgroundExecutionSlots.insert(executionSlot).inserted else {
            enqueueBackgroundExecution(QueuedBackgroundExecution(
                instruction: instruction, conversationContext: retainedConversation,
                providerTurn: providerTurn, speakResult: speakResult, terminalOwner: terminalOwner
            ))
            return
        }
        if case .direct(let identifier, let sourceTurn) = terminalOwner,
           !bindRunningWorkDurably(
                workCorrelationIdentifier: identifier,
                lane: executionSlot.recentOwnerWorkLane,
                durableLane: executionSlot.durableLane
           ) {
            reservedBackgroundExecutionSlots.remove(executionSlot)
            _ = finishDirectTextTerminal(
                workCorrelationIdentifier: identifier,
                lane: executionSlot.recentOwnerWorkLane,
                durableLane: executionSlot.durableLane,
                status: .failed, outcome: "failed.durable-bind-save",
                verification: "none",
                reason: "Ace could not save ownership of this request. Nothing started.",
                slot: .none, source: executionSlot.eventSource,
                turnIdentifier: sourceTurn
            )
            return
        }
        if pairedReview { reservedBackgroundExecutionSlots.insert(.silver) }
        let dispatchGeneration = backgroundDispatchGeneration
        let executionAgent = backgroundExecutionAgent(
            for: executionSlot
        )
        // ONE correlation for this unit of work, minted here and carried by
        // every event this dispatch produces. It is what lets a Red completion
        // that lands two turns later attach to the request that caused it
        // instead of to whatever turn happens to be current — the
        // background-completion ordering rule, made mechanical.
        let redWorkCorrelationID =
            terminalOwner.workCorrelationIdentifier
        let dispatchingTurnID = terminalOwner.sourceTurnIdentifier
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier: redWorkCorrelationID,
            lane: terminalOwner.recentLane(for: executionSlot),
            status: .running
        )
        upsertBuyerWorkReceipt(
            workID: redWorkCorrelationID,
            lane: terminalOwner.recentLane(for: executionSlot),
            phase: .executing,
            progress:
                "\(executionSlot.spokenAgentName) accepted execution under the original work ID."
        )
        if case .direct(let directWorkCorrelationIdentifier, _) =
                terminalOwner {
            if executionSlot == .red {
                activeDirectRedWorkCorrelationIdentifier =
                    directWorkCorrelationIdentifier
            } else {
                activeDirectSilverWorkCorrelationIdentifier =
                    directWorkCorrelationIdentifier
            }
        }
        // Gold selected and delegated. Published as `.gold` — a routing
        // decision, not speech, and never as the owner.
        if case .direct = terminalOwner {
            AceEventBus.shared.publishOutbound(
                source: .gold,
                state: .routed,
                payloadType: .executionReceipt,
                payload: instruction,
                turnID: dispatchingTurnID,
                correlationID: redWorkCorrelationID
            )
        }
        AceEventBus.shared.publishOutbound(
            source: executionSlot.eventSource,
            state: .executing,
            payloadType: .executionReceipt,
            payload:
                {
                    switch terminalOwner {
                    case .direct: return instruction
                    case .gold:
                        return "typed-lane=\(executionSlot.rawValue) verification=pending"
                    }
                }(),
            turnID: dispatchingTurnID,
            correlationID: redWorkCorrelationID
        )
        backgroundTaskActive = true
        // Force the overlay visible so the red gem is actually seen while the
        // worker runs, even if the cursor had faded out.
        showCursorOverlayForBackgroundTask()
        // Narrated hand-off + the gem sweep as the "working" visual: the user
        // hears WHO got the job and sees Ace visibly busy until it's done.
        if !meetingCaptureOwnsVoiceOutput {
            Task {
                guard backgroundDispatchGeneration == dispatchGeneration,
                      directEffectsAreAllowed else { return }
                try? await noraVoice.speakText(
                    pairedReview
                        ? "Red and Silver are reviewing that independently."
                        : "\(executionSlot.spokenAgentName) is working on that.",
                    from: executionSlot.voiceLane,
                    priority: .background
                )
            }
        }
        startScanTheater(speakIntro: false)
        Task {
            let isCurrent = { @MainActor [weak self] in
                guard let self else { return false }
                return self.backgroundDispatchGeneration == dispatchGeneration
                    && self.directEffectsAreAllowed && !self.stealthMode.isActive
            }
            let result: BackgroundAgentTerminalResult
            if pairedReview {
                result = await PairedAgentReviewRunner.run(
                    isCurrent: isCurrent,
                    red: { [self] in
                        appendRouteReceipt("PAIRED-REVIEW start lane=red work=\(redWorkCorrelationID)")
                        let result = await backgroundAgent.run(
                            instruction: PairedAgentReviewPolicy.instruction(ownerRequest: ownerRequest, slot: .red),
                            screenshotPaths: [], provider: providerTurn.provider
                        )
                        appendRouteReceipt("PAIRED-REVIEW terminal lane=red kind=\(result.kind.rawValue) work=\(redWorkCorrelationID)")
                        return result
                    },
                    silver: { [self] in
                        AceEventBus.shared.publishOutbound(
                            source: .silver, state: .executing,
                            payloadType: .executionReceipt,
                            payload: "paired-review=independent verification=pending",
                            turnID: dispatchingTurnID, correlationID: redWorkCorrelationID
                        )
                        appendRouteReceipt("PAIRED-REVIEW start lane=silver work=\(redWorkCorrelationID)")
                        let result = await silverBackgroundAgent.run(
                            instruction: PairedAgentReviewPolicy.instruction(ownerRequest: ownerRequest, slot: .silver),
                            screenshotPaths: [], provider: providerTurn.provider
                        )
                        appendRouteReceipt("PAIRED-REVIEW terminal lane=silver kind=\(result.kind.rawValue) work=\(redWorkCorrelationID)")
                        return result
                    }
                )
            } else if isCurrent() {
                result = await executionAgent.run(
                    instruction: retainedConversation + "\n\nCURRENT OWNER REQUEST:\n" + instruction,
                    screenshotPaths: [],
                    provider: providerTurn.provider
                )
            } else {
                result = BackgroundAgentDeliveryPolicy.cancelled()
            }
            if backgroundDispatchGeneration == dispatchGeneration {
                reservedBackgroundExecutionSlots.remove(executionSlot)
                if pairedReview { reservedBackgroundExecutionSlots.remove(.silver) }
            }
            // Keep the red gem lit if the meeting notetaker is still running.
            backgroundTaskActive = meetingNotetaker.isTakingNotes
                || anyBackgroundExecutionAgentIsWorking
            stopScanTheater()
            // A cancelled task returns an empty summary — the user said stop,
            // so nothing is spoken. The one-mouth VoiceQueue serializes this
            // behind whatever is speaking (the old manual isPlaying wait-loop
            // this replaces existed to stop the summary guillotining the
            // hand-off narration); .background means a live gold answer that
            // arrives meanwhile jumps ahead of it.
        // The selected slot's terminal receipt, on the same correlation the dispatch
            // opened. `publishTerminalWork` admits it exactly once, so a retry
            // or a duplicated completion cannot deliver the work twice.
            //
            // Note what this is NOT: it is outbound, sourced `.red`, and carries
            // an `.executionReceipt` payload type. There is no admission path
            // that turns it back into an owner command, so Red completing while
            // Ace is mid-sentence stays a receipt.
            switch terminalOwner {
            case .direct(
                let directWorkCorrelationIdentifier,
                let sourceTurnIdentifier
            ):
                _ = self.finishDirectRedTerminal(
                    workCorrelationIdentifier:
                        directWorkCorrelationIdentifier,
                    result: result,
                    turnIdentifier: sourceTurnIdentifier,
                    correlationIdentifier: redWorkCorrelationID,
                    speakResult: speakResult,
                    executionSlot: executionSlot
                )
            case .gold(let goldRequest):
                let outcome: RedExecutionOutcome
                switch result.kind {
                case .completed: outcome = .completed
                case .blocked: outcome = .blocked
                case .failed: outcome = .failed
                case .cancelled: outcome = .cancelled
                }
                self.completeGoldExecution(
                    goldRequest,
                    outcome: outcome,
                    verification: result.verification == "reported"
                        ? .reported : .none,
                    spokenResult:
                        result.spokenSummary ?? result.reason,
                    durableOutcome: result.outcome,
                    durableVerification: result.verification,
                    durableReason: result.reason,
                    executionSlot: executionSlot
                )
            }
        }
    }

    /// Makes the cursor overlay appear so the red background-worker gem is visible.
    private func showCursorOverlayForBackgroundTask() {
        guard directEffectsAreAllowed else { return }
        transientHideTask?.cancel()
        transientHideTask = nil
        if !isOverlayVisible {
            overlayWindowManager.hasShownOverlayBefore = true
            isOverlayVisible = overlayWindowManager.showOverlay(
                onScreens: NSScreen.screens,
                companionManager: self
            )
        }
    }

    /// Every completed lane has a readable channel independent of Nora. Voice
    /// remains the primary output, but a missing/downloaded voice can no longer
    /// turn a successful brain or background job into apparent silence.
    private func clearVisibleResponse() {
        dismissDictationFailure()
        visibleResponseGeneration = UUID()
        visibleResponseHideTask?.cancel()
        visibleResponseHideTask = nil
        visibleResponseText = ""
    }

    private func showVisibleResponse(
        _ text: String,
        retention: OwnerVisibleResponseRetention = .standard
    ) {
        guard directEffectsAreAllowed,
              let response =
                FirstRunRecoveryPolicy.visibleResponse(text) else {
            return
        }
        showCursorOverlayForBackgroundTask()
        visibleResponseHideTask?.cancel()
        let generation = UUID()
        visibleResponseGeneration = generation
        visibleResponseText = String(response.prefix(2_000))
        visibleResponseHideTask = Task { [weak self] in
            let seconds = OwnerVisibleResponseRetentionPolicy.seconds(
                for: retention
            )
            try? await Task.sleep(for: .seconds(Int64(seconds)))
            guard let self,
                  !Task.isCancelled,
                  self.visibleResponseGeneration == generation else {
                return
            }
            self.visibleResponseText = ""
            self.visibleResponseHideTask = nil
        }
    }

    // MARK: - Product walkthrough ("walk me through …")

    /// The site the walkthrough tours.
    private static let walkthroughSite = "https://blacklabeltec.com"

    /// One scripted stop on the guided demo. `clickLabel` is the on-page nav
    /// element the cursor clicks to reach this stop (nil = the opening page, already
    /// on screen). `narration` is the curated, source-true line spoken there.
    struct DemoStep: Sendable {
        let name: String
        let url: String          // the active browser tab is navigated here (real anchor, in-tab)
        let narration: String
    }

    /// Where the demo opens.
    private static let walkthroughStartURL = "https://blacklabeltec.com/platform"

    /// Tight demo: intro, three flagship modules, then Products — navigated in the
    /// same tab to the site's REAL anchors, so it scrolls to each product reliably.
    private static let demoSteps: [DemoStep] = [
        DemoStep(name: "Black Label Tech", url: "https://blacklabeltec.com/platform",
                 narration: "hey, i'm ace. let me walk you through what we've built. this is black label tech, the operating system for modern businesses. instead of paying for a dozen different tools that don't talk to each other, this is one platform that runs your whole company. let me show you a few of the pieces."),
        DemoStep(name: "CRM Core", url: "https://blacklabeltec.com/platform#crm",
                 narration: "first, crm core. this is the shared customer layer everything else is built on. every contact, every job, and every conversation lives in one place, so nothing falls through the cracks and your whole team sees the same picture."),
        DemoStep(name: "Scheduling", url: "https://blacklabeltec.com/platform#scheduling",
                 narration: "next, scheduling. appointments, jobs, shifts, and dispatch, all on one calendar the whole team can see. you book a customer, assign the right person, and it's on their schedule instantly. no double booking, no back and forth."),
        DemoStep(name: "Quoting", url: "https://blacklabeltec.com/platform#quoting",
                 narration: "and quoting. one pricing engine for any trade. you build a professional estimate in seconds, send it over, and the moment the customer says yes, it turns straight into a scheduled job. no retyping, nothing lost."),
        DemoStep(name: "Products", url: "https://blacklabeltec.com/products",
                 narration: "and these are the products. every one of these is already built and ready to install for your own business, from sales and support all the way to entire industries. we also make apps for everyday people, like vigil for home security, academy for online courses, and black label estate for real estate."),
    ]

    // The demo is LOCAL (never codex), so fire it liberally: any mention of "demo",
    // "tour", or "walkthrough" — plus the speech-to-text mis-hearings of "tour"
    // ("toy"/"soil"/"tore"), and "show me around/the products". This keeps demo
    // requests off the codex path entirely (where they time out and feel like a hang).
    private static let walkthroughTriggerPattern =
        #"(?i)(\b(demo|demos|tour|walkthrough)\b|walk ?me ?through|walk ?through|give (me )?(a|the) (toy|soil|tore|tor)|run (a|the) (toy|soil)|show me (around|the site|the website|the platform|the product|the products|our products)|show (me )?around|show (our|the) products)"#

    /// The trigger words stay liberal (any "demo"/"tour"/"walkthrough" runs the
    /// SALES tour — founder intent). But those exact words also show up when the
    /// user is asking about their OWN environment ("run the demo on screen two",
    /// "play the demo video", "find the demo folder", "give me a tour of this
    /// codebase"). When the utterance references the user's own screen/file/app,
    /// it is NOT a request for our marketing tour — let it fall through to the
    /// real route. Sales phrasing ("give me a demo", "show me the products",
    /// "walk me through it") contains none of these words and still fires.
    private static let walkthroughEnvironmentExclusionPattern =
        #"(?i)\b(screen|monitor|display|window|folder|file|video|desktop|this\s+(code|repo|app|file))\b"#

    private var walkthroughTask: Task<Void, Never>?
    private var walkthroughAutomationProcess: Process?

    private func isWalkthroughTrigger(_ text: String) -> Bool {
        guard text.range(of: Self.walkthroughTriggerPattern, options: .regularExpression) != nil else {
            return false
        }
        if text.range(of: Self.walkthroughEnvironmentExclusionPattern, options: .regularExpression) != nil {
            return false
        }
        return true
    }

    // MARK: - Scanning theater ("highlight / where is / find …")

    /// Locate-style asks get the scanning act: Ace says "i'll begin scanning",
    /// then the gold gem physically sweeps waypoint to waypoint across every
    /// screen — pulsing at each stop — while the brain works. Pure software
    /// choreography (a Swift animation task, nothing prompt-driven): it fills
    /// the brain's think-time with visible searching, and is cancelled the
    /// moment the answer arrives so the gem flies to the REAL target.
    private static let scanTriggerPattern =
        #"(?i)\b(highlight|where\s+is|where'?s|find|locate|point\s+(at|to|out)|scan\s+for|look\s+for|search\s+for)\b"#

    /// Asks about the web/internet — or common web/knowledge/task idioms — are
    /// NOT on-screen locate asks, so they must not trigger the scanning theater
    /// (Ace sweeping the gem and answering "i couldn't pin that down on screen").
    /// "look for"/"search for"/"find out"/"figure out" plus buy/book/order/
    /// flight/recipe/price/weather/news overwhelmingly mean a web or knowledge
    /// question; excluding them keeps the on-screen "look for the save button"
    /// locate working while sending these to the gold brain instead.
    private static let scanExclusionPattern =
        #"(?i)\b(web|internet|online|google|browser|find\s+out|figure\s+out|buy|book|order|flights?|recipes?|prices?|weather|news)\b"#

    private var scanTheaterTask: Task<Void, Never>?

    /// The last target derived from direct user text or deterministic app/file
    /// inventory. Model-authored [POINT] labels are never stored here. Lets a
    /// follow-up like "open it" mean a safely resolved target.
    private var lastLocatedTargetName: String?

    /// True when the previous exchange was a locate. Admission consumes this
    /// once to select a typed `native.locate.follow-up` context.
    private var lastRouteWasLocate = false

    private func isScanTrigger(_ text: String) -> Bool {
        text.range(of: Self.scanTriggerPattern, options: .regularExpression) != nil
            && text.range(of: Self.scanExclusionPattern, options: .regularExpression) == nil
    }

    private func startScanTheater(speakIntro: Bool = true) {
        scanTheaterTask?.cancel()
        guard !detectedElementIsVerified else { return }
        showCursorOverlayForBackgroundTask()
        scanTheaterTask = Task {
            if speakIntro {
                try? await noraVoice.speakText("i'll begin scanning.")
            }
            // Raster-ish sweep: top band → middle → bottom on each screen, a
            // gold pulse per stop, looping across screens until cancelled.
            let sweepStops: [(CGFloat, CGFloat)] = [
                (0.15, 0.80), (0.50, 0.82), (0.85, 0.78),
                (0.80, 0.50), (0.45, 0.48), (0.12, 0.52),
                (0.18, 0.20), (0.52, 0.16), (0.86, 0.22),
            ]
            // Outlives the red agent's 150s task timeout so the sweep covers a
            // full background job when used as the "working" visual.
            let scanDeadline = Date().addingTimeInterval(170)
            while !Task.isCancelled, Date() < scanDeadline {
                for screen in NSScreen.screens {
                    for (fractionX, fractionY) in sweepStops {
                        if Task.isCancelled || Date() >= scanDeadline { return }
                        // The spinner state hides the gem — hold idle so the
                        // sweep stays visible while the brain works. Only the
                        // processing spinner is overridden: a live gold
                        // listen or response keeps its own state (this loop
                        // was resetting gold's waveform twice a second).
                        let frame = screen.frame
                        detectedElementScreenLocation = CGPoint(
                            x: frame.origin.x + frame.width * fractionX,
                            y: frame.origin.y + frame.height * fractionY
                        )
                        detectedElementDisplayFrame = frame
                        clickFlashTrigger += 1
                        try? await Task.sleep(for: .milliseconds(650))
                    }
                }
            }
        }
    }

    private func stopScanTheater() {
        scanTheaterTask?.cancel()
        scanTheaterTask = nil
    }

    /// Runs the scripted product demo: the red agent opens the site in the
    /// background, then the gold gem moves stop to stop — navigating to each
    /// product, flying to point at it, and speaking its curated line.
    func startWalkthrough() {
        // Founder gate (2026-08-12): the choreographed tour narrates a sibling-brand
        // site. Buyer Macs (customer-owned route) must never reach it.
        guard AceBrainRoute.current == .founderHosted else {
            appendRouteReceipt("WALKTHROUGH refused — founder-hosted route only")
            Task { [weak self] in
                try? await self?.noraVoice.speakText(
                    "that walkthrough isn't available on this Mac.")
            }
            return
        }
        guard directEffectsAreAllowed else {
            appendRouteReceipt("WALKTHROUGH deferred — stealth active")
            return
        }
        walkthroughTask?.cancel()
        // The explain tour and the walkthrough fight over the same gem — a new
        // walkthrough supersedes a running explain.
        explainAppsChoreographyTask?.cancel()
        explainAppsChoreographyTask = nil
        showCursorOverlayForBackgroundTask()
        walkthroughTask = Task {
            guard directEffectsAreAllowed else { return }
            // A prior tour may own one exact Chrome window. Close only that
            // verified id; never discover or scan the owner's other tabs.
            await closePreviousDemoWindowIfOpen()
            guard !Task.isCancelled, directEffectsAreAllowed else { return }
            // Starts from an unopened state: open the platform page (lists every
            // module top to bottom), give the browser time to launch and load.
            backgroundTaskActive = true
            guard await openDemoWindow(url: Self.walkthroughStartURL) else {
                backgroundTaskActive = meetingNotetaker.isTakingNotes
                appendRouteReceipt(
                    "WALKTHROUGH stopped — exact demo window unavailable")
                return
            }
            try? await Task.sleep(for: .seconds(3))
            guard await maximizeFrontBrowserWindow() else {
                backgroundTaskActive = meetingNotetaker.isTakingNotes
                appendRouteReceipt(
                    "WALKTHROUGH stopped — exact demo window changed")
                return
            }
            try? await Task.sleep(for: .seconds(1))
            // Don't darken the red gem if a meeting is still being recorded — it
            // is the "Ace is in the meeting" indicator, not just the demo's.
            backgroundTaskActive = meetingNotetaker.isTakingNotes

            for step in Self.demoSteps {
                if Task.isCancelled { break }
                let completedStep = await runDemoStep(step)
                if !completedStep { break }
            }
            // Finale — click "Work With Us" and close on the call to action.
            if !Task.isCancelled { await finishWithWorkWithUs() }
            // Only reset voiceState/gem if we ran to the end. If a new command
            // (or "stop") cancelled the tour, IT owns these now — clobbering them
            // here would race and reset the state the new command just set.
            if !Task.isCancelled {
                voiceState = .idle
                clearDetectedElementLocation()
            }
        }
    }

    /// One demo stop. A nav step flies the gold gem to the link and clicks it
    /// (one vision call); a product step just scrolls to its anchor (instant). Then
    /// the gem hops to the content and the scripted line is spoken. No per-step
    /// vision calls on product steps, so it moves briskly with no stalls.
    private func runDemoStep(_ step: DemoStep) async -> Bool {
        guard !Task.isCancelled,
              directEffectsAreAllowed,
              await navigateActiveTab(to: step.url) else { return false }
        try? await Task.sleep(for: .milliseconds(1600))       // let it navigate / scroll into place
        // A "stop" that lands during the navigate sleep should end the tour here,
        // before speaking the next line — otherwise one trailing narration leaks.
        if Task.isCancelled || !directEffectsAreAllowed { return false }
        clickFlashTrigger += 1                                // gold pulse — flashy
        moveGemToContentSpot()                                // gem to where the anchor lands, fast, not the mouse
        voiceState = .responding
        try? await noraVoice.speakText(step.narration)
        while noraVoice.isPlaying {
            if Task.isCancelled { return false }
            try? await Task.sleep(for: .milliseconds(200))
        }
        try? await Task.sleep(for: .milliseconds(200))
        return !Task.isCancelled && directEffectsAreAllowed
    }

    /// Opens the demo's OWN dedicated Chrome window on `url`, so the demo never
    /// touches the user's other windows (WealthCharts, Claude, etc.). Captures
    /// the created window's id so later steps target THAT exact window instead of
    /// scanning by URL substring — which could match one of the user's own
    /// blacklabeltec windows if they happened to have the marketing site open.
    private func openDemoWindow(url: String) async -> Bool {
        guard directEffectsAreAllowed else { return false }
        let script = """
        tell application "Google Chrome"
          activate
          set demoWindow to make new window
          set URL of active tab of demoWindow to "\(url)"
          return id of demoWindow
        end tell
        """
        if let output = await runWalkthroughOSAScript(script),
           let windowID = Int(output),
           windowID > 0 {
            demoWindowID = windowID
            return true
        } else {
            demoWindowID = nil
            return false
        }
    }

    /// Closes a demo window left over from a previous walkthrough run.
    private func closePreviousDemoWindowIfOpen() async {
        guard directEffectsAreAllowed else { return }
        guard let windowID = demoWindowID else { return }
        demoWindowID = nil
        _ = await runWalkthroughOSAScript("""
        tell application "Google Chrome"
          if not (exists window id \(windowID)) then error "demo window missing"
          close (window id \(windowID))
          return "closed"
        end tell
        """)
    }

    /// Navigates only the demo's captured window id. If that identity is lost,
    /// the tour stops; it never scans URLs or adopts one of the owner's tabs.
    private func navigateActiveTab(to url: String) async -> Bool {
        guard directEffectsAreAllowed,
              let windowID = demoWindowID else { return false }
        let output = await runWalkthroughOSAScript("""
        tell application "Google Chrome"
          if not (exists window id \(windowID)) then error "demo window missing"
          set demoWindow to window id \(windowID)
          set URL of active tab of demoWindow to "\(url)"
          set index of demoWindow to 1
          return id of demoWindow
        end tell
        """)
        return output == String(windowID)
    }

    /// Runs one bounded product-tour AppleScript. Private Mode entry has a direct synchronous
    /// root cutoff; cancellation/timeout then reap the whole tree off the main
    /// actor. Output is a tiny fixed receipt (window id or "closed").
    private func runWalkthroughOSAScript(
        _ script: String,
        timeout: Duration = .seconds(10)
    ) async -> String? {
        guard !Task.isCancelled,
              directEffectsAreAllowed else { return nil }
        if let current = walkthroughAutomationProcess, current.isRunning {
            await Task.detached {
                RunningProcessBox.terminateProcessTree(current)
            }.value
        }

        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
        process.arguments = ["-e", script]
        let outputPipe = Pipe()
        process.standardOutput = outputPipe
        guard let outputCapture = try? BoundedPipeCapture(
            handle: outputPipe.fileHandleForReading, limit: 65536
        ) else { return nil }
        defer { outputCapture.discard() }
        process.standardError = FileHandle.nullDevice

        let cutoff = WalkthroughProcessCutoff()
        let cutoffIdentifier =
            StealthEntryLatch.shared.registerSynchronousEntryCutoff {
                cutoff.cancelSynchronously()
            }
        defer {
            cutoff.clear()
            StealthEntryLatch.shared.unregisterSynchronousEntryCutoff(
                cutoffIdentifier)
            if walkthroughAutomationProcess === process {
                walkthroughAutomationProcess = nil
            }
        }

        let launchOutcome =
            DirectEffectProcessLaunchAdmission.commit(
                effectsAreAllowed: { [weak self] in
                    guard let self else { return false }
                    return !Task.isCancelled
                        && self.directEffectsAreAllowed
                },
                performUnlessRaised: { body in
                    StealthEntryLatch.shared.performUnlessRaised(body)
                },
                launchAndPublish: {
                    do {
                        try process.run()
                        cutoff.register(process)
                        return true
                    } catch {
                        return false
                    }
                }
            )
        guard launchOutcome == .launched else {
            return nil
        }
        walkthroughAutomationProcess = process

        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: timeout)
        while process.isRunning, clock.now < deadline {
            guard !Task.isCancelled,
                  !cutoff.isCancelled,
                  directEffectsAreAllowed else {
                cutoff.cancelSynchronously()
                await Task.detached {
                    RunningProcessBox.terminateProcessTree(process)
                }.value
                return nil
            }
            try? await Task.sleep(for: .milliseconds(50))
        }

        guard !cutoff.isCancelled else { return nil }
        guard !process.isRunning else {
            cutoff.cancelSynchronously()
            await Task.detached {
                RunningProcessBox.terminateProcessTree(process)
            }.value
            return nil
        }
        guard process.terminationStatus == 0,
              !cutoff.isCancelled,
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else { return nil }
        let capturedOutput = outputCapture.finish()
        guard !capturedOutput.truncated, !capturedOutput.readFailed else {
            return nil
        }
        let data = capturedOutput.data
        let trimmed = String(data: data, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return (trimmed?.isEmpty == false) ? trimmed : nil
    }

    /// The demo's finale: navigate (in-tab) to the real "Work With Us" page
    /// (/contact) and close on the call to action.
    private func finishWithWorkWithUs() async {
        guard !Task.isCancelled,
              directEffectsAreAllowed,
              await navigateActiveTab(
                to: "https://blacklabeltec.com/contact"
              ) else { return }
        try? await Task.sleep(for: .milliseconds(1800))
        guard !Task.isCancelled,
              directEffectsAreAllowed,
              await maximizeFrontBrowserWindow() else { return }
        clickFlashTrigger += 1
        // Point the gem at the "contact us" headline on the contact page.
        if let screen = demoScreen {
            let f = screen.frame
            detectedElementScreenLocation = CGPoint(x: f.origin.x + f.width * 0.24,
                                                    y: f.origin.y + f.height * 0.72)
            detectedElementDisplayFrame = f
        }
        voiceState = .responding
        try? await noraVoice.speakText("and when you're ready, this is where you get in touch. black label tech, one system that replaces a dozen. let's build.")
        while noraVoice.isPlaying {
            if Task.isCancelled { return }
            try? await Task.sleep(for: .milliseconds(200))
        }
    }

    /// The display the demo runs on — the primary (menu-bar) screen at origin
    /// (0,0). On this Mac that's the ultra-wide, not the built-in.
    private var demoScreen: NSScreen? {
        NSScreen.screens.first(where: { $0.frame.origin == .zero }) ?? NSScreen.main ?? NSScreen.screens.first
    }

    /// Fills the primary display using only the captured demo window id.
    private func maximizeFrontBrowserWindow() async -> Bool {
        guard directEffectsAreAllowed,
              let screen = demoScreen,
              let windowID = demoWindowID else { return false }
        let width = Int(screen.frame.width), height = Int(screen.frame.height)
        let output = await runWalkthroughOSAScript("""
        tell application "Google Chrome"
          if not (exists window id \(windowID)) then error "demo window missing"
          set demoWindow to window id \(windowID)
          set bounds of demoWindow to {0, 0, \(width), \(height)}
          set index of demoWindow to 1
          return id of demoWindow
        end tell
        """)
        return output == String(windowID)
    }

    private var demoGemStep = 0

    /// Moves the gold gem to a varied spot over the page so it visibly travels
    /// around, instead of returning to the same place each time.
    private func moveGemToContentSpot() {
        guard let screen = demoScreen else { return }
        let frame = screen.frame
        // Anchor navigation lands the product near the TOP of the viewport, so
        // keep the gem in the upper band (AppKit origin is bottom-left → high y).
        let xs: [CGFloat] = [0.40, 0.54, 0.46, 0.58]
        let ys: [CGFloat] = [0.76, 0.70, 0.78, 0.72]
        let x = frame.origin.x + frame.width * xs[demoGemStep % xs.count]
        let y = frame.origin.y + frame.height * ys[demoGemStep % ys.count]
        detectedElementScreenLocation = CGPoint(x: x, y: y)
        detectedElementDisplayFrame = frame
        demoGemStep += 1
    }

    private struct ResolvedPoint { let cg: CGPoint; let appKit: CGPoint }

    // MARK: - First-Run Live Demo

    /// What the live demo found on the buyer's screen: a dry ≤6-word reaction
    /// and where to fly. Contentless in receipts — the observation derives from
    /// the buyer's screen and is spoken once, never written down.
    private struct FirstRunDemoObservation {
        let spokenObservation: String
        let appKitLocation: CGPoint
    }

    /// Ported from upstream Clicky's onboarding demo and re-voiced: the brain
    /// picks ONE specific centered thing on the real screen and reacts in six
    /// lowercase words or fewer. The centre-band rule keeps it off the menu
    /// bar, dock, and edges, where a wrong point looks broken.
    private static let firstRunDemoSystemPrompt = """
    you are a small gold gem on the user's screen, one minute into knowing them. look at the screenshot and pick ONE specific thing to point at — a named app icon, a filename, a button label, a tab title, a phrase you can actually read. never anything vague like "a window" or "some text".

    react to the thing you picked in AT MOST six lowercase words — dry, sharp, a little amused. never quote screen text verbatim, no emojis, never mention screenshots or being an ai.

    coordinate rule: x must be between 20% and 80% of the image width, y between 20% and 80% of the image height. nothing near an edge, no menu bar, no dock. if only edges are interesting, pick something boring in the centre instead.

    respond with ONLY the comment followed by this tag, nothing else: comment [POINT:capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;x=<pixel x>;y=<pixel y>;confidence=<0 to 1>;label=<short label>]
    never omit or alter either identity.
    the label is two or three plain words naming the thing — no punctuation.
    the screenshots are labeled with their pixel dimensions — that is your coordinate space, origin top-left.
    """

    /// Captures the screens, asks the gold brain for one observation, and maps
    /// its coordinate into AppKit space. A clean-Mac CLI can need materially
    /// longer than a warm developer login, so this uses the same bounded
    /// cold-start envelope as the live authentication probe.
    private func performFirstRunDemoObservation() async -> FirstRunDemoObservation? {
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        // One retry after 800ms, same as the gold path: ScreenCaptureKit fails
        // transiently right after launch, and the first run IS right after
        // launch — without the retry the demo dies exactly when it matters.
        var capturedScreens: [CompanionScreenCapture]?
        do {
            capturedScreens = try await CompanionScreenCaptureUtility
                .captureAllScreensAsJPEG(onlyCursorScreen: true)
        } catch {
            if ScreenCaptureOperationBoundary.isTimeout(error) {
                appendRouteReceipt("TOUR-DEMO capture timed out")
                return nil
            }
        }
        if capturedScreens == nil || capturedScreens?.isEmpty == true {
            try? await Task.sleep(for: .milliseconds(800))
            guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
                return nil
            }
            do {
                capturedScreens = try await CompanionScreenCaptureUtility
                    .captureAllScreensAsJPEG(onlyCursorScreen: true)
            } catch {
                capturedScreens = nil
            }
        }
        guard let captures = capturedScreens, !captures.isEmpty else {
            appendRouteReceipt("TOUR-DEMO capture failed twice")
            return nil
        }
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        let labeledImages = captures.map { capture in
            (data: capture.imageData,
             label: capture.label + " (image dimensions: \(capture.screenshotWidthInPixels)x\(capture.screenshotHeightInPixels) pixels)")
        }

        let brainCall: Task<(text: String, duration: TimeInterval), Error> = Task { [claudeAPI] in
            guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
                throw CancellationError()
            }
            return try await claudeAPI.analyzeImageStreaming(
                images: labeledImages,
                systemPrompt: Self.firstRunDemoSystemPrompt,
                conversationHistory: [],
                userPrompt: "find one thing on this screen and react to it.",
                responseFormat:
                    AcePointingProviderPolicy.encoding(
                        for: BrainBackend.selectedCLI
                    ) == .localJSON
                        ? .localPointingJSON : .conversational,
                interactiveLatencyProfile:
                    InteractiveProviderLatencyPolicy.profile(
                        for: .screenAnswer,
                        includesScreenContext: true
                    ),
                persistLogs: false,
                onTextChunk: { _ in }
            )
        }
        let timeout = Task {
            try await Task.sleep(
                for: .seconds(
                    FirstRunScreenAnswerPolicy.timeoutSeconds
                )
            )
            brainCall.cancel()
        }
        defer {
            timeout.cancel()
            brainCall.cancel()
        }

        // Reasoned skip receipts, deliberately CONTENTLESS: the failure class is
        // logged so the beat is debuggable, but the brain's words and anything
        // read off the buyer's screen are never written down.
        let response: String
        do {
            response = try await brainCall.value.text
        } catch {
            appendRouteReceipt("TOUR-DEMO brain call failed (\(Task.isCancelled ? "cancelled" : "error"))")
            return nil
        }
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        let parsed = Self.parsePointingCoordinates(
            from: response,
            captures: captures
        )
        guard let coordinate = parsed.coordinate else {
            appendRouteReceipt("TOUR-DEMO no [POINT] tag in response (length \(response.count))")
            return nil
        }
        let observation = parsed.spokenText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !observation.isEmpty else {
            appendRouteReceipt("TOUR-DEMO tag without comment")
            return nil
        }

        // Same pixel→point→AppKit mapping as resolveElementPoint.
        let target: CompanionScreenCapture? = {
            guard let identity = parsed.captureIdentity else { return nil }
            return captures.first { $0.identity == identity }
        }()
        guard let t = target else { return nil }
        let sw = CGFloat(t.screenshotWidthInPixels), sh = CGFloat(t.screenshotHeightInPixels)
        let dw = CGFloat(t.displayWidthInPoints), dh = CGFloat(t.displayHeightInPoints)
        let clampedX = max(0, min(coordinate.x, sw)), clampedY = max(0, min(coordinate.y, sh))
        let localX = clampedX * (dw / sw), localY = clampedY * (dh / sh)
        let appKit = CGPoint(x: localX + t.displayFrame.origin.x,
                             y: (dh - localY) + t.displayFrame.origin.y)
        return FirstRunDemoObservation(spokenObservation: observation, appKitLocation: appKit)
    }

    /// Locates an element via the brain, flies the gold gem to it, and returns both
    /// the overlay (AppKit) point and the CoreGraphics point used for clicking.
    @discardableResult
    private func resolveElementPoint(description: String) async -> ResolvedPoint? {
        let ownerTurnID = AceEventBus.shared.currentTurnID
        guard ownerTurnID != nil, !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        guard let captures = try? await CompanionScreenCaptureUtility.captureAllScreensAsJPEG() else { return nil }
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        let labeledImages = captures.map { capture in
            (data: capture.imageData,
             label: capture.label + " (image dimensions: \(capture.screenshotWidthInPixels)x\(capture.screenshotHeightInPixels) pixels)")
        }
        let prompt = "on screen, locate \(description). respond with ONLY [POINT:capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;x=<pixel x>;y=<pixel y>;confidence=<0 to 1>;label=target] at its center. never omit or alter either identity. If the requested target is absent or ambiguous, return [POINT:none]. Do not navigate or act. output nothing else."
        guard let (response, _) = try? await claudeAPI.analyzeImageStreaming(
            images: labeledImages,
            systemPrompt: "you output only one immutable point tag using the exact capture_id and display_id printed in the chosen image label, with image-pixel x/y, confidence from 0 to 1, and a short label; or [POINT:none]. output no other words.",
            conversationHistory: [],
            userPrompt: prompt,
            responseFormat:
                AcePointingProviderPolicy.encoding(
                    for: BrainBackend.selectedCLI
                ) == .localJSON
                    ? .localPointingJSON : .conversational,
            interactiveLatencyProfile:
                InteractiveProviderLatencyPolicy.profile(
                    for: .screenAnswer,
                    includesScreenContext: true
                ),
            onTextChunk: { _ in }
        ) else { return nil }
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive else {
            return nil
        }
        let parseResult = Self.parsePointingCoordinates(
            from: response,
            captures: captures
        )
        guard let coordinate = parseResult.coordinate else { return nil }
        let target: CompanionScreenCapture? = {
            guard let identity = parseResult.captureIdentity else {
                return nil
            }
            return captures.first { $0.identity == identity }
        }()
        guard let t = target else { return nil }
        let sw = CGFloat(t.screenshotWidthInPixels), sh = CGFloat(t.screenshotHeightInPixels)
        let dw = CGFloat(t.displayWidthInPoints), dh = CGFloat(t.displayHeightInPoints)
        let clampedX = max(0, min(coordinate.x, sw)), clampedY = max(0, min(coordinate.y, sh))
        let localX = clampedX * (dw / sw), localY = clampedY * (dh / sh)
        let appKit = CGPoint(x: localX + t.displayFrame.origin.x, y: (dh - localY) + t.displayFrame.origin.y)
        let mainHeight = NSScreen.screens.first?.frame.height ?? dh
        let cg = CGPoint(x: t.displayFrame.origin.x + localX, y: (mainHeight - t.displayFrame.maxY) + localY)
        guard !Task.isCancelled, !StealthVisibilityGate.shared.isActive,
              AceEventBus.shared.currentTurnID == ownerTurnID else { return nil }
        detectedElementScreenLocation = appKit
        detectedElementDisplayFrame = t.displayFrame
        markDetectedElementAsVerified()
        return ResolvedPoint(cg: cg, appKit: appKit)
    }

    private func currentPrivateModePointerSnapshot()
        -> PrivateModePointerSnapshot? {
        guard let pointerEvent = CGEvent(source: nil) else { return nil }
        return PrivateModePointerSnapshot(
            location: pointerEvent.location,
            mouseMovedCount: CGEventSource.counterForEventType(
                .combinedSessionState,
                eventType: .mouseMoved
            ),
            leftDraggedCount: CGEventSource.counterForEventType(
                .combinedSessionState,
                eventType: .leftMouseDragged
            ),
            rightDraggedCount: CGEventSource.counterForEventType(
                .combinedSessionState,
                eventType: .rightMouseDragged
            ),
            otherDraggedCount: CGEventSource.counterForEventType(
                .combinedSessionState,
                eventType: .otherMouseDragged
            )
        )
    }

    private func privateModeBoundaryStillMatches(
        captureBinding: PrivateModeCaptureBinding,
        point: CGPoint,
        sessionIdentifier: UUID,
        expectedPointerState: PrivateModePointerSnapshot?
    ) -> Bool {
        guard stealthAnswerSessionIdentifier == sessionIdentifier,
              captureBinding.sessionIdentifier == sessionIdentifier,
              stealthMode.isActive,
              StealthVisibilityGate.shared.isActive,
              !Task.isCancelled,
              PrivateModePolicy.captureBindingStrictlyContains(
                  point,
                  binding: captureBinding
              ) else {
            return false
        }
        let currentContext = PrivateModePolicy.currentContext()
        let decision = PrivateModePolicy.decision(
            for: currentContext, requireFocusedWindow: !captureBinding.includesAllDisplays
        )
        guard decision.isAllowed,
              PrivateModePolicy.captureBindingIsCurrent(
                  captureBinding,
                  context: currentContext,
                  displayTopology: PrivateModePolicy.currentDisplayTopology()
              ) else {
            return false
        }
        guard let expectedPointerState else { return true }
        guard let currentPointerState =
            currentPrivateModePointerSnapshot() else {
            return false
        }
        return PrivateModePolicy.pointerStayedStill(
            from: expectedPointerState,
            to: currentPointerState,
            expectedLocation: point
        )
    }

    /// The model supplies a point on a captured display, not an AX control.
    /// Canvas/custom-rendered apps therefore use the same mouse path as native
    /// controls. The session, display and owner-pointer checks remain.
    private func movePointerAtCG(
        _ point: CGPoint,
        captureBinding: PrivateModeCaptureBinding,
        expectedPointerState: PrivateModePointerSnapshot,
        sessionIdentifier: UUID
    ) -> PrivateModePointerSnapshot? {
        guard privateModeBoundaryStillMatches(
            captureBinding: captureBinding,
            point: point,
            sessionIdentifier: sessionIdentifier,
            expectedPointerState: nil
        ),
        let currentPointerState = currentPrivateModePointerSnapshot(),
        PrivateModePolicy.pointerStayedStill(
            from: expectedPointerState,
            to: currentPointerState,
            expectedLocation: expectedPointerState.location
        ),
        // `CGEvent.post(.mouseMoved)` is delivered asynchronously. Reading the
        // pointer immediately afterward can therefore observe its old location
        // and reject a valid Quizlet target. The cursor warp is synchronous;
        // the same display, session, and physical-movement gates
        // still run immediately before it and before mouse-down.
        CGWarpMouseCursorPosition(point) == .success else {
            return nil
        }
        guard privateModeBoundaryStillMatches(
            captureBinding: captureBinding,
            point: point,
            sessionIdentifier: sessionIdentifier,
            expectedPointerState: nil
        ),
        let pointerAfterAim = currentPrivateModePointerSnapshot(),
        hypot(
            pointerAfterAim.location.x - point.x,
            pointerAfterAim.location.y - point.y
        ) <= 1 else {
            return nil
        }
        return pointerAfterAim
    }

    /// Posts a coordinate click while the Private Mode session, display
    /// and pointer still match. There is no control-level AX
    /// requirement and no browser-specific route. There is no
    /// cursor-move dwell: the former 120 ms sleep let an external focus change
    /// receive a click intended for the old window and blocked the exit chord.
    private func clickAtCG(
        _ point: CGPoint,
        captureBinding: PrivateModeCaptureBinding,
        expectedPointerState: PrivateModePointerSnapshot,
        sessionIdentifier: UUID
    ) async -> Bool {
        guard let source = CGEventSource(stateID: .combinedSessionState),
              let mouseDown = CGEvent(
                  mouseEventSource: source,
                  mouseType: .leftMouseDown,
                  mouseCursorPosition: point,
                  mouseButton: .left
              ),
              let mouseUp = CGEvent(
                  mouseEventSource: source,
                  mouseType: .leftMouseUp,
                  mouseCursorPosition: point,
                  mouseButton: .left
              ),
              privateModeBoundaryStillMatches(
                  captureBinding: captureBinding,
                  point: point,
                  sessionIdentifier: sessionIdentifier,
                  expectedPointerState: expectedPointerState
              ) else {
            return false
        }

        mouseDown.post(tap: .cghidEventTap)
        try? await Task.sleep(for: .milliseconds(50))
        // Do not semantically revalidate after mouse-down: the target is
        // allowed to change as a direct result of that event. The remaining
        // nonsemantic boundary check only protects OS button state and decides
        // whether the mandatory mouse-up is an authorized completion or repair.
        guard privateModeBoundaryStillMatches(
            captureBinding: captureBinding,
            point: point,
            sessionIdentifier: sessionIdentifier,
            expectedPointerState: expectedPointerState
        ) else {
            // Once a down event has been posted, releasing the button is a
            // mandatory OS-state repair even though the click authorization has
            // failed. Never leave the owner with a synthetically held button.
            mouseUp.post(tap: .cghidEventTap)
            return false
        }
        mouseUp.post(tap: .cghidEventTap)
        return true
    }

    /// The CLI response may include an immutable capture-bound [POINT:...] tag
    /// which triggers
    /// the buddy to fly to that element on screen.
    private func sendTranscriptToClaudeWithScreenshot(
        transcript: String,
        context: OwnerTurnContext? = nil,
        providerPromptOverride: String? = nil
    ) {
        let admittedProviderTurn = AceProviderTurn.capture()
        let admittedOwnerTurnContext = context ?? activeOwnerTurnContext
        let admittedSessionIdentifier = activeRoutingSessionID
        let admittedTurnIdentifier = activeRoutingTurnID
        let admittedCorrelationIdentifier = activeRoutingCorrelationID
        let admittedContextualOwnerRequest =
            activeContextualOwnerRequest
        let admittedOwnerRequestEnvelope =
            ownerTurnLifecycle.activeBinding?.envelope
        let appResolvedOwnerRequest =
            admittedContextualOwnerRequest?.resolvedRequest
                ?? admittedOwnerRequestEnvelope?.normalizedRequest
                ?? admittedOwnerTurnContext?.exactInput
                ?? transcript
        let appExecutionInstruction =
            providerPromptOverride
                ?? admittedContextualOwnerRequest?
                    .executionInstruction
                ?? admittedOwnerRequestEnvelope?.normalizedRequest
                ?? admittedOwnerTurnContext?.exactInput
                ?? transcript
        guard let admittedWorkCorrelationIdentifier =
                goldContextBundle.admittedGoldAnswerWorkIdentifier(
                    request: admittedContextualOwnerRequest,
                    sourceSessionIdentifier: admittedSessionIdentifier,
                    sourceTurnIdentifier: admittedTurnIdentifier,
                    sourceCorrelationIdentifier: admittedCorrelationIdentifier
                ),
              admittedOwnerTurnContext?.turnID == admittedTurnIdentifier else {
            appendRouteReceipt("GOLD admission refused missing-or-stale-bound-work; no provider started")
            if let admittedTurnIdentifier {
                _ = finishVolatileOwnerTurn(
                    turnID: admittedTurnIdentifier,
                    correlationID: admittedCorrelationIdentifier,
                    status: .failed,
                    outcome: "gold-admission-failed",
                    reason: "Ace lost the connection to this request before processing it. Please retry the full request."
                )
            }
            return
        }
        _ = recentOwnerWorkStore.transition(
            workCorrelationIdentifier:
                admittedWorkCorrelationIdentifier,
            lane: .gold,
            status: .running
        )
        if let admittedContextualOwnerRequest {
            let recorded: Bool
            if goldContextBundle.workRecords.contains(where: {
                $0.workCorrelationIdentifier
                    == admittedWorkCorrelationIdentifier
            }) {
                recorded = goldContextBundle.transitionWork(
                    workCorrelationIdentifier:
                        admittedWorkCorrelationIdentifier,
                    lane: "gold",
                    status: .running
                )
            } else {
                recorded = goldContextBundle.recordWork(
                    request: admittedContextualOwnerRequest,
                    lane: "gold",
                    status: .running
                )
            }
            let persisted = recorded
                && AceConversationHistory.saveBundle(
                    goldContextBundle,
                    performUnlessRaised: { body in
                        StealthEntryLatch.shared.performUnlessRaised(body)
                    }
                )
            appendRouteReceipt(
                "GOLD-CONTEXT running persisted="
                    + (persisted ? "true" : "false")
                    + " work="
                    + admittedWorkCorrelationIdentifier
                        .uuidString.lowercased()
            )
            if persisted {
                upsertBuyerWorkReceipt(
                    workID: admittedWorkCorrelationIdentifier,
                    lane: .gold,
                    phase: .processing,
                    progress:
                        "Default brain invocation started for this work ID."
                )
            }
        }
        currentResponseTask?.cancel()
        // Kill any prior in-flight gold Claude process before spawning the next — a
        // Task.cancel() alone can't interrupt the blocking subprocess, so without
        // this a rapid re-ask stacks concurrent model processes.
        claudeAPI.cancelInFlightAnswer()
        noraVoice.stopPlayback()
        let deadlineGeneration = armInteractiveResponseDeadline(
            transcript: transcript
        )
        let responseOwnerGeneration =
            goldOwnerInterruptionGeneration
        goldAnswerInterruption = nil
        let expectedAnswerIdentity: GoldAnswerIdentity? = {
            guard let admittedSessionIdentifier,
                  let admittedTurnIdentifier,
                  let admittedCorrelationIdentifier else {
                return nil
            }
            return GoldAnswerIdentity(
                sourceSessionIdentifier:
                    admittedSessionIdentifier,
                sourceTurnIdentifier:
                    admittedTurnIdentifier,
                sourceCorrelationIdentifier:
                    admittedCorrelationIdentifier,
                ownerGeneration: responseOwnerGeneration
            )
        }()
        var answerDeliveryGate = expectedAnswerIdentity.map {
            GoldAnswerDeliveryGate(expected: $0)
        }

        let responseTaskIdentity = UUID()
        currentResponseTaskIdentity = responseTaskIdentity
        currentResponseTask = Task {
            defer {
                self.clearCurrentResponseTask(
                    ifMatching: responseTaskIdentity
                )
            }
            // Stay in processing (spinner) state — no streaming text displayed
            voiceState = .processing

            do {
                // Decide from the raw request before touching ScreenCaptureKit.
                // Stable knowledge stays text-only. Visual requests default to
                // one foreground/cursor display; all displays require explicit
                // cross-monitor wording.
                let homeworkNeedsScreen =
                    HomeworkScreenEvidence.requiresReadableProblem(
                        transcript
                    )
                let tradingModeWasActive = tradingLane.isActive
                let tradingNeedsCurrentCapture =
                    tradingModeWasActive
                        && tradingLane.requiresMarketData(for: transcript)
                let requestedScreenScope =
                    ScreenContextPolicy.scope(for: transcript)
                let screenScope: ScreenContextScope
                if homeworkNeedsScreen {
                    screenScope = .relevantDisplay
                } else if TradingScreenCapturePolicy
                    .shouldForceRelevantDisplay(
                        isTradingModeActive: tradingModeWasActive,
                        requiresCurrentCapture:
                            tradingNeedsCurrentCapture,
                        explicitlyRequestedAllDisplays:
                            requestedScreenScope == .allDisplays
                    ) {
                    screenScope = .relevantDisplay
                } else {
                    screenScope = requestedScreenScope
                }
                let screenCaptures: [CompanionScreenCapture]
                switch screenScope {
                case .none:
                    screenCaptures = []
                    appendRouteReceipt("GOLD screen-context none")
                case .relevantDisplay, .allDisplays:
                    do {
                        screenCaptures = try await
                            CompanionScreenCaptureUtility
                                .captureAllScreensAsJPEG(
                                    onlyCursorScreen:
                                        screenScope == .relevantDisplay
                                )
                    } catch {
                        appendRouteReceipt(
                            "GOLD capture retry errorType="
                                + String(describing: type(of: error))
                        )
                        if ScreenCaptureOperationBoundary.isTimeout(error) {
                            throw error
                        }
                        try await Task.sleep(nanoseconds: 800_000_000)
                        screenCaptures = try await
                            CompanionScreenCaptureUtility
                                .captureAllScreensAsJPEG(
                                    onlyCursorScreen:
                                        screenScope == .relevantDisplay
                                )
                    }
                    appendRouteReceipt(
                        "GOLD screen-context "
                            + (screenScope == .relevantDisplay
                                ? "relevant-display"
                                : "all-displays")
                            + " count=\(screenCaptures.count)"
                    )
                }
                let captureTimestamp = Date()

                guard !Task.isCancelled else {
                    throw CancellationError()
                }

                // Build image labels with the actual screenshot pixel dimensions
                // so Claude's coordinate space matches the image it sees. We
                // scale from screenshot pixels to display points ourselves.
                let labeledImages = screenCaptures.map { capture in
                    let dimensionInfo = " (image dimensions: \(capture.screenshotWidthInPixels)x\(capture.screenshotHeightInPixels) pixels)"
                    return (data: capture.imageData, label: capture.label + dimensionInfo)
                }

                // Reload the atomic context bundle on every Gold turn. The
                // projection carries ten recent exchanges plus deterministic
                // compaction and lexical retrieval from older owner statements
                // and explicit memory.md records. Assistant answers are never
                // promoted into the durable fact section.
                guard directEffectsAreAllowed,
                      !stealthMode.isActive else {
                    throw CancellationError()
                }
                goldContextBundle =
                    AceConversationHistory.loadBundle(
                        performUnlessRaised: { body in
                            StealthEntryLatch.shared
                                .performUnlessRaised(body)
                        }
                    )
                let promptContext = goldContextBundle.promptContext(
                    for: appResolvedOwnerRequest,
                    explicitMemoryText:
                        loadExplicitMemoryForGoldRetrieval(),
                    maximumCharacters: 6_000
                )
                let historyForAPI = promptContext.recentExchanges.map {
                    entry in
                    (
                        userPlaceholder: entry.userTranscript,
                        assistantResponse:
                            entry.assistantResponse
                    )
                }

                var effectiveSystemPrompt =
                    Self.companionVoiceResponseSystemPrompt
                        + "\n\n" + AceLanguage.current.responseInstruction
                        + "\n\n"
                        + (admittedOwnerTurnContext?
                            .providerBoundaryPrompt ?? "")
                        + "\n\n"
                        + promptContext.systemPromptSection
                        + "\n\n"
                        + foregroundNavigationContext.prompt(for: AceEventBus.shared.sessionID)
                        + "\n\n" + nativeConversationContext.prompt(for: AceEventBus.shared.sessionID)
                appendRouteReceipt(
                    "GOLD-CONTEXT projected recent="
                        + String(
                            promptContext.recentExchanges.count
                        )
                        + " compactedCharacters="
                        + String(
                            promptContext.compactedSummary.count
                        )
                        + " retrievedCharacters="
                        + String(
                            promptContext.retrievedOwnerContext.count
                        )
                )
                if screenCaptures.isEmpty {
                    effectiveSystemPrompt += """

                    No screen image was requested or captured for this turn. You may choose a foreground action from the owner's request and recent conversation. Do not claim to see the current screen or invent a selected document. For a spoken reply, end with [POINT:none].
                    """
                }
                // agent.log is a human/debug audit channel, not model context.
                // Keeping the boundary one-way prevents any historical
                // model-authored or user-authored text from becoming trusted
                // instructions or claimed self-knowledge in a later turn.
                // Trading mode (the purple lane): while active, give the gold brain
                // the 16-factor market context + no-fabrication framing so a chart
                // question on the existing screenshot is answered as a disciplined
                // trading analyst. Receipted so the injection is provable without
                // reading the constructed prompt.
                if tradingModeWasActive {
                    effectiveSystemPrompt += "\n\n" + tradingLane.systemOverlay
                    if tradingNeedsCurrentCapture {
                        effectiveSystemPrompt += """

                        This request requires current market data. Use only a readable chart in the supplied images. If symbol, timeframe, and visible values are all readable, append this exact evidence tag before the final point tag:
                        [TRADING:status=available;capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;symbol=<visible symbol>;timeframe=<visible timeframe>;values=<concise exact visible values>]
                        If any required field or chart data is missing, append [TRADING:status=unavailable]. Never state a price, quote, indicator value, or chart conclusion without the available tag.
                        """
                    }
                    appendRouteReceipt("BRAIN trading-context injected (\(tradingLane.systemOverlay.count) chars)")
                }
                if homeworkNeedsScreen {
                    effectiveSystemPrompt += """

                    HOMEWORK VISIBILITY GATE: Explain or solve the assignment only if one complete, readable problem is visible. A course page, activity list, assignment title, obscured problem, or multiple ambiguous problems is not enough. For one readable problem, append this tag before the final point tag:
                    [HOMEWORK:status=clear;capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;problem=<short exact problem fingerprint>]
                    Otherwise append exactly one of [HOMEWORK:status=list-only], [HOMEWORK:status=obscured], or [HOMEWORK:status=ambiguous]. Never imply you inspected problem text unless the clear tag is valid.
                    """
                }

                let (fullResponseText, _) = try await claudeAPI.analyzeImageStreaming(
                    images: labeledImages,
                    systemPrompt: effectiveSystemPrompt,
                    conversationHistory: historyForAPI,
                    userPrompt: appExecutionInstruction,
                    responseFormat: .typedDelegationJSON,
                    providerTurn: admittedProviderTurn,
                    interactiveLatencyProfile:
                        InteractiveProviderLatencyPolicy.profile(
                            for: .gold,
                            includesScreenContext:
                                !labeledImages.isEmpty
                        ),
                    onTextChunk: { _ in
                        // No streaming text display — spinner stays until TTS plays
                    }
                )

                guard !Task.isCancelled else {
                    throw CancellationError()
                }

                // Every response kind crosses the same owner-identity gate.
                // A native replacement must retire old questions and actions
                // before either can publish or enter an execution lane.
                guard let currentSessionIdentifier =
                        activeRoutingSessionID,
                      let currentTurnIdentifier =
                        activeRoutingTurnID,
                      let currentCorrelationIdentifier =
                        activeRoutingCorrelationID,
                      var gate = answerDeliveryGate else {
                    appendRouteReceipt(
                        "GOLD answer discarded reason=sourceMismatch"
                    )
                    throw CancellationError()
                }
                let answerDecision = gate.claim(
                    current: GoldAnswerIdentity(
                        sourceSessionIdentifier:
                            currentSessionIdentifier,
                        sourceTurnIdentifier:
                            currentTurnIdentifier,
                        sourceCorrelationIdentifier:
                            currentCorrelationIdentifier,
                        ownerGeneration:
                            goldOwnerInterruptionGeneration
                    ),
                    interruption: goldAnswerInterruption
                )
                answerDeliveryGate = gate
                guard answerDecision == .deliver else {
                    appendRouteReceipt(
                        "GOLD answer discarded reason="
                            + String(describing: answerDecision)
                    )
                    throw CancellationError()
                }
                let goldResponse: GoldTurnResponse
                do {
                    goldResponse = try GoldResponseEnvelope.decode(
                        Data(fullResponseText.utf8)
                    )
                } catch GoldResponseEnvelopeError.nonterminalPromise {
                    // Preserve this exact admitted work lineage and route it
                    // once. The provider's "I'll start" or "Should I give it
                    // to Red?" is never displayed as success and never becomes
                    // a second Gold loop.
                    goldResponse = GoldTurnResponse(
                        kind: .execute,
                        spokenResponse: "",
                        objective: "execute the admitted owner request"
                    )
                    appendRouteReceipt(
                        "GOLD promise normalized executor=red work="
                            + admittedWorkCorrelationIdentifier
                                .uuidString.lowercased()
                    )
                } catch GoldResponseEnvelopeError.nonterminalRefusal {
                    // Provider-authored denial is not a terminal owner result.
                    // Preserve the admitted request byte-for-byte and continue
                    // it through the app-owned executor without exposing the
                    // refusal or making the owner ask twice.
                    goldResponse = GoldTurnResponse(
                        kind: .execute,
                        spokenResponse: "",
                        objective: "execute the admitted owner request"
                    )
                    appendRouteReceipt(
                        "GOLD refusal normalized executor=red work="
                            + admittedWorkCorrelationIdentifier
                                .uuidString.lowercased()
                    )
                } catch let envelopeError as GoldResponseEnvelopeError {
                    // The generic catch below records only the error TYPE. For
                    // an envelope reject the case and a bounded sample of the
                    // discarded text are the whole diagnosis — without them a
                    // finished answer that fails admission reads as a routing
                    // mystery (2026-08-08, and again 2026-08-12 when two real
                    // answers were dropped as snags).
                    appendRouteReceipt(
                        "GOLD envelope rejected case=\(envelopeError) "
                            + "answerCharacters=\(fullResponseText.count) "
                            + "sample=\(String(fullResponseText.prefix(220)))"
                    )
                    throw envelopeError
                }

                if TradingModeExecutionPolicy.decision(
                    isTradingModeActive: tradingModeWasActive,
                    responseRequestsExecution:
                        goldResponse.kind == .execute || goldResponse.kind == .foreground
                            || goldResponse.objective != nil
                ) == .refuseAnalysisOnly {
                    let refusal =
                        "Trading Mode is analysis-only. I did not send this "
                        + "request to Red, place a trade, or cause an external action."
                    appendRouteReceipt(
                        "TRADING execution refused executor=none reason=analysis-only"
                    )
                    disarmInteractiveResponseDeadline(
                        generation: deadlineGeneration
                    )
                    stopScanTheater()
                    voiceState = .idle
                    _ = finishGoldAnswerTerminal(
                        DeferredGoldAnswerTerminal(
                            request: admittedContextualOwnerRequest,
                            workCorrelationIdentifier:
                                admittedWorkCorrelationIdentifier,
                            status: .blocked,
                            outcome: "blocked.trading-analysis-only",
                            verification: "app-owned-analysis-only-policy",
                            reason: refusal,
                            assistantResponse: refusal,
                            publication: .answer(refusal)
                        )
                    )
                    return
                }
                if let action = goldResponse.foregroundAction {
                    guard let sessionID = admittedSessionIdentifier,
                          let turnID = admittedTurnIdentifier,
                          !Task.isCancelled,
                          directEffectsAreAllowed,
                          AceEventBus.shared.sessionID == sessionID,
                          AceEventBus.shared.currentTurnID == turnID else { throw CancellationError() }
                    foregroundNavigationContext.remember(
                        action, ownerRequest: admittedOwnerRequestEnvelope?.exactTranscript ?? transcript,
                        sessionID: sessionID
                    )
                    disarmInteractiveResponseDeadline(generation: deadlineGeneration)
                    stopScanTheater()
                    voiceState = .idle
                    let result = await performGoldForegroundNavigation(action) { [weak self] in
                        self?.directEffectsAreAllowed == true && !Task.isCancelled
                            && AceEventBus.shared.sessionID == sessionID
                            && AceEventBus.shared.currentTurnID == turnID
                    }
                    guard !Task.isCancelled, directEffectsAreAllowed,
                          AceEventBus.shared.currentTurnID == turnID else { throw CancellationError() }
                    appendRouteReceipt("GOLD foreground destination=\(action.destination.rawValue) verified=\(result.verified)")
                    _ = finishGoldAnswerTerminal(DeferredGoldAnswerTerminal(
                        request: admittedContextualOwnerRequest,
                        workCorrelationIdentifier: admittedWorkCorrelationIdentifier,
                        status: result.verified ? .completed : .failed,
                        outcome: result.verified ? "foreground-open-verified" : "foreground-open-unverified",
                        verification: result.verified ? "observed-visible-target" : "none",
                        reason: result.reason, assistantResponse: result.reason,
                        publication: .answer(result.reason)
                    ))
                    return
                }
                var validatedResponseText =
                    goldResponse.spokenResponse
                if tradingModeWasActive,
                   tradingNeedsCurrentCapture {
                    let contexts = screenCaptures.map {
                        TradingCaptureContext(
                            generation: $0.identity.generation,
                            displayID: $0.identity.displayID,
                            source: "Ace screen capture",
                            capturedAt: captureTimestamp
                        )
                    }
                    switch TradingDataEvidenceDecoder.decode(
                        validatedResponseText,
                        captures: contexts
                    ) {
                    case let .available(spokenText, evidence):
                        tradingDataStatus = .available(evidence)
                        validatedResponseText = spokenText
                        appendRouteReceipt(
                            "TRADING chart read capture-bound symbol=\(evidence.symbol) timeframe=\(evidence.timeframe) display=\(evidence.source)"
                        )
                    case .unavailable:
                        tradingDataStatus = .unavailable(
                            reason: "the current screen has no readable chart data"
                        )
                        validatedResponseText =
                            "Open a readable chart showing the symbol, timeframe, and values. I will continue this same analysis from that current capture. [POINT:none]"
                        appendRouteReceipt(
                            "TRADING unavailable — model reported no readable data"
                        )
                    case let .rejected(_, reason):
                        tradingDataStatus = .unavailable(reason: reason)
                        validatedResponseText =
                            "Show the chart source, symbol, timeframe, and values clearly. I will continue this same analysis from a current capture-bound chart read. [POINT:none]"
                        appendRouteReceipt(
                            "TRADING evidence rejected — \(reason)"
                        )
                    }
                }

                if homeworkNeedsScreen {
                    let contexts = screenCaptures.map {
                        HomeworkCaptureContext(
                            generation: $0.identity.generation,
                            displayID: $0.identity.displayID
                        )
                    }
                    switch HomeworkScreenEvidence.decode(
                        validatedResponseText,
                        captures: contexts
                    ) {
                    case let .clear(spokenText, fingerprint):
                        validatedResponseText = spokenText
                        appendRouteReceipt(
                            "HOMEWORK readable problem verified characters=\(fingerprint.count)"
                        )
                    case let .notReadable(visibility):
                        let visibilityMessage =
                            visibility == .listOnly
                            ? "the course or activity list, but not the actual problem"
                            : "that the problem is not clearly readable"
                        validatedResponseText =
                            "I can see \(visibilityMessage). Open or select one complete assignment problem, then ask again. [POINT:none]"
                        appendRouteReceipt(
                            "HOMEWORK refused visibility=\(visibility.rawValue)"
                        )
                    case let .rejected(reason):
                        validatedResponseText =
                            "Open or select one complete readable assignment problem. I will continue this same request from that screen. [POINT:none]"
                        appendRouteReceipt(
                            "HOMEWORK evidence rejected — \(reason)"
                        )
                    }
                }

                if goldResponse.kind == .clarify {
                    let clarificationText = Self
                        .parsePointingCoordinates(
                            from: validatedResponseText,
                            captures: screenCaptures
                        )
                        .spokenText
                    guard let admittedSessionIdentifier,
                          let admittedContextualOwnerRequest,
                          let continuation =
                            GoldClarificationContinuation(
                                sourceSessionIdentifier:
                                    admittedSessionIdentifier,
                                parentWorkCorrelationIdentifier:
                                    admittedWorkCorrelationIdentifier,
                                originalOwnerTranscript:
                                    admittedContextualOwnerRequest
                                        .originalOwnerTranscript,
                                originalResolvedRequest:
                                    admittedContextualOwnerRequest
                                        .resolvedRequest,
                                question: clarificationText
                            ) else {
                        throw GoldResponseEnvelopeError.invalidValue
                    }
                    disarmInteractiveResponseDeadline(
                        generation: deadlineGeneration
                    )
                    stopScanTheater()
                    voiceState = .idle
                    let persisted = goldContextBundle.appendExchange(
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        assistantResponse: clarificationText,
                        status: .running,
                        lane: "gold"
                    ) && AceConversationHistory.saveBundle(
                        goldContextBundle,
                        performUnlessRaised: { body in
                            StealthEntryLatch.shared
                                .performUnlessRaised(body)
                        }
                    )
                    if persisted {
                        pendingGoldClarification = continuation
                        upsertBuyerWorkReceipt(
                            workID:
                                admittedWorkCorrelationIdentifier,
                            lane: .gold,
                            phase: .clarifying,
                            progress:
                                "Waiting for one required owner value: \(clarificationText)"
                        )
                        showVisibleResponse(clarificationText)
                        Task { [weak self] in
                            try? await self?.noraVoice
                                .speakText(clarificationText)
                        }
                        appendRouteReceipt(
                            "GOLD clarification retained parent="
                                + admittedWorkCorrelationIdentifier
                                    .uuidString.lowercased()
                        )
                    } else {
                        appendRouteReceipt(
                            "GOLD clarification refused pending durable save"
                        )
                    }
                    return
                }

                if let objective = goldResponse.objective {
                    guard let admittedSessionIdentifier,
                          let admittedTurnIdentifier,
                          let admittedCorrelationIdentifier,
                          let admittedOwnerRequestEnvelope,
                          AceEventBus.shared.sessionID
                            == admittedSessionIdentifier,
                          admittedOwnerRequestEnvelope.sessionID
                            == admittedSessionIdentifier,
                          admittedOwnerRequestEnvelope.turnID
                            == admittedTurnIdentifier else {
                        throw GoldResponseEnvelopeError.invalidValue
                    }
                    let validation =
                        GoldDelegationPolicy.validateExecution(
                            response: GoldTurnResponse(
                                kind: .execute,
                                spokenResponse: "",
                                objective: objective
                            ),
                            sourceSessionIdentifier:
                                admittedSessionIdentifier,
                            sourceTurnIdentifier:
                                admittedTurnIdentifier,
                            sourceCorrelationIdentifier:
                                admittedCorrelationIdentifier,
                            originalOwnerTranscript:
                                admittedContextualOwnerRequest?
                                    .originalOwnerTranscript
                                    ?? admittedOwnerRequestEnvelope
                                        .exactTranscript,
                            resolvedRequest:
                                admittedContextualOwnerRequest?
                                    .resolvedRequest
                                    ?? admittedOwnerRequestEnvelope
                                        .normalizedRequest,
                            correctionContext:
                                admittedContextualOwnerRequest?
                                    .correctionContext,
                            parentWorkCorrelationIdentifier:
                                admittedContextualOwnerRequest?
                                    .parentWorkCorrelationIdentifier,
                            workCorrelationIdentifier:
                                admittedWorkCorrelationIdentifier,
                            workSourceTurnIdentifier:
                                admittedContextualOwnerRequest?
                                    .sourceTurnIdentifier,
                            workSourceCorrelationIdentifier:
                                admittedContextualOwnerRequest?
                                    .sourceCorrelationIdentifier
                        )
                    let request: GoldExecutionRequest
                    switch validation {
                    case .accepted(let acceptedRequest):
                        request = acceptedRequest
                    case .formatFailure(let message):
                        disarmInteractiveResponseDeadline(
                            generation: deadlineGeneration
                        )
                        stopScanTheater()
                        voiceState = .idle
                        appendRouteReceipt(
                            "GOLD format failure; Red was not claimed"
                        )
                        _ = finishGoldAnswerTerminal(
                            DeferredGoldAnswerTerminal(
                                request:
                                    admittedContextualOwnerRequest,
                                workCorrelationIdentifier:
                                    admittedWorkCorrelationIdentifier,
                                status: .failed,
                                outcome: "model-format-failed",
                                verification: "none",
                                reason: message,
                                assistantResponse: nil,
                                publication:
                                    .pipelineFailure(message)
                            )
                        )
                        return
                    }
                    guard let executionClaim = try
                            redExecutionService.claim(
                                envelope:
                                    admittedOwnerRequestEnvelope,
                                objective: request.objective,
                                provider: admittedProviderTurn.provider,
                                targetBinding: .none,
                                workID:
                                    request.workCorrelationIdentifier
                            ),
                          executionClaim.workID
                            == request.workCorrelationIdentifier else {
                        throw GoldResponseEnvelopeError.invalidValue
                    }
                    _ = redExecutionService.markExecuting(
                        turnID: admittedTurnIdentifier
                    )
                    disarmInteractiveResponseDeadline(
                        generation: deadlineGeneration
                    )
                    stopScanTheater()
                    voiceState = .idle
                    appendRouteReceipt(
                        "GOLD objective executor=red"
                            + " ownerBytes="
                            + String(
                                request.originalOwnerTranscript.utf8.count
                            )
                            + " turn="
                            + request.sourceTurnIdentifier
                                .uuidString.lowercased()
                            + " correlation="
                            + request.workCorrelationIdentifier
                                .uuidString.lowercased()
                    )
                    await dispatchGoldDelegation(
                        request,
                        providerTurn: admittedProviderTurn
                    )
                    return
                }
                // The answer is here — end the scanning act so the gem is free
                // to fly to the real target.
                stopScanTheater()

                // Parse the [POINT:...] tag from Claude's response
                let parseResult = Self.parsePointingCoordinates(
                    from: validatedResponseText,
                    captures: screenCaptures
                )
                let spokenText = parseResult.spokenText
                // A model-authored [POINT:...:label] is display text only. Never
                // remember it as an action target: otherwise a later physical
                // "open it" could turn an untrusted label into an immediate app
                // launch. Pronoun follow-ups retain only targets resolved from
                // direct user text or deterministic app/file inventory.

                // Handle element pointing if Claude returned coordinates.
                // Switch to idle BEFORE setting the location so the triangle
                // becomes visible and can fly to the target. Without this, the
                // spinner hides the triangle and the flight animation is invisible.
                let hasPointCoordinate = parseResult.coordinate != nil
                if hasPointCoordinate {
                    voiceState = .idle
                }

                // Bind only to the exact immutable capture identity echoed by
                // the model. Missing or stale identity never points anywhere.
                let targetScreenCapture: CompanionScreenCapture? = {
                    guard let identity = parseResult.captureIdentity else {
                        return nil
                    }
                    return screenCaptures.first {
                        $0.identity == identity
                    }
                }()

                if let pointCoordinate = parseResult.coordinate,
                   let targetScreenCapture {
                    // Claude's coordinates are in the screenshot's pixel space
                    // (top-left origin, e.g. 1280x831). Scale to the display's
                    // point space (e.g. 1512x982), then convert to AppKit global coords.
                    let screenshotWidth = CGFloat(targetScreenCapture.screenshotWidthInPixels)
                    let screenshotHeight = CGFloat(targetScreenCapture.screenshotHeightInPixels)
                    let displayWidth = CGFloat(targetScreenCapture.displayWidthInPoints)
                    let displayHeight = CGFloat(targetScreenCapture.displayHeightInPoints)
                    let displayFrame = targetScreenCapture.displayFrame

                    // Clamp to screenshot coordinate space
                    let clampedX = max(0, min(pointCoordinate.x, screenshotWidth))
                    let clampedY = max(0, min(pointCoordinate.y, screenshotHeight))

                    // Scale from screenshot pixels to display points
                    let displayLocalX = clampedX * (displayWidth / screenshotWidth)
                    let displayLocalY = clampedY * (displayHeight / screenshotHeight)

                    // Convert from top-left origin (screenshot) to bottom-left origin (AppKit)
                    let appKitY = displayHeight - displayLocalY

                    // Convert display-local coords to global screen coords
                    let globalLocation = CGPoint(
                        x: displayLocalX + displayFrame.origin.x,
                        y: appKitY + displayFrame.origin.y
                    )

                    detectedElementScreenLocation = globalLocation
                    detectedElementDisplayFrame = displayFrame
                    markDetectedElementAsVerified()
                    appendRouteReceipt(
                        "POINT target accepted display=\(targetScreenCapture.displayIdentifier) "
                            + "pixel=(\(Int(pointCoordinate.x)),\(Int(pointCoordinate.y)))"
                    )
                    BlackLabelAnalytics.trackElementPointed(elementLabel: parseResult.elementLabel)
                    print(
                        "🎯 Element pointing: "
                            + "(\(Int(pointCoordinate.x)), "
                            + "\(Int(pointCoordinate.y))) "
                            + "labelPresent=\(parseResult.elementLabel != nil)"
                    )
                } else {
                    print(
                        "🎯 Element pointing: no coordinate "
                            + "labelPresent=\(parseResult.elementLabel != nil)"
                    )
                    if let rejectionReason = parseResult.rejectionReason {
                        appendRouteReceipt(
                            "POINT rejected — \(rejectionReason)"
                        )
                    }
                }

                // Commit the correlated exchange. Overflow is compacted into
                // owner text + app-observed status only; model-authored prose
                // remains in the ten-turn conversational window and never
                // becomes a durable fact.
                let contextPersisted = finishGoldAnswerTerminal(
                    DeferredGoldAnswerTerminal(
                        request: admittedContextualOwnerRequest,
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        status: .completed,
                        outcome: "answered",
                        verification: "reported",
                        reason:
                            "Gold committed a visible text answer.",
                        assistantResponse: spokenText,
                        publication: .answer(spokenText)
                    )
                )
                appendRouteReceipt(
                    "GOLD-CONTEXT answer persisted="
                        + (contextPersisted ? "true" : "false")
                        + " work="
                        + admittedWorkCorrelationIdentifier
                            .uuidString.lowercased()
                )
                guard contextPersisted else { return }
                print(
                    "🧠 Gold context: "
                        + "\(conversationHistory.count) recent exchanges"
                )

                disarmInteractiveResponseDeadline(
                    generation: deadlineGeneration
                )
            } catch is CancellationError {
                disarmInteractiveResponseDeadline(
                    generation: deadlineGeneration
                )
                if activeRoutingSessionID == admittedSessionIdentifier,
                   activeRoutingTurnID == admittedTurnIdentifier,
                   activeRoutingCorrelationID == admittedCorrelationIdentifier {
                    stopScanTheater()
                    voiceState = .idle
                }
                let cancellationReason = String(
                    describing:
                        goldAnswerInterruption ?? .explicitStop
                )
                let deadlineExpired =
                    goldAnswerInterruption == .deadline
                let terminalReason = deadlineExpired
                    ? "Default brain did not return an actionable response within \(Int(InteractiveLatencyPolicy.hardFailureDeadline)) seconds. Red never accepted execution. Use Retry on work \(admittedWorkCorrelationIdentifier.uuidString.lowercased()) to submit the same bounded request as a new correlated attempt."
                    : cancellationReason
                let contextPersisted = finishGoldAnswerTerminal(
                    DeferredGoldAnswerTerminal(
                        request: admittedContextualOwnerRequest,
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        status: deadlineExpired
                            ? .failed : .cancelled,
                        outcome: deadlineExpired
                            ? "failed.conversation-deadline"
                            : "cancelled",
                        verification: "none",
                        reason: terminalReason,
                        assistantResponse: nil,
                        publication: deadlineExpired
                            ? .pipelineFailure(terminalReason)
                            : .none
                    )
                )
                appendRouteReceipt(
                    "GOLD cancelled reason="
                        + String(
                            describing:
                                goldAnswerInterruption
                                    ?? (responseOwnerGeneration
                                        != goldOwnerInterruptionGeneration
                                        ? .explicitStop
                                        : nil)
                        )
                        + " contextPersisted="
                        + (contextPersisted ? "true" : "false")
                )
            } catch {
                disarmInteractiveResponseDeadline(
                    generation: deadlineGeneration
                )
                stopScanTheater()
                let failureReason = String(
                    describing: type(of: error)
                ) + ": " + error.localizedDescription
                let contextPersisted = finishGoldAnswerTerminal(
                    DeferredGoldAnswerTerminal(
                        request: admittedContextualOwnerRequest,
                        workCorrelationIdentifier:
                            admittedWorkCorrelationIdentifier,
                        status: .failed,
                        outcome: "pipeline-failed",
                        verification: "none",
                        reason: failureReason,
                        assistantResponse: nil,
                        publication:
                            .pipelineFailure(failureReason)
                    )
                )
                BlackLabelAnalytics.trackResponseError(error: error.localizedDescription)
                print("⚠️ Companion response error: \(error)")
                // Receipt for failures BEFORE the brain call (screen capture,
                // etc.) — without this line the utterance vanishes with no
                // REQUEST anywhere, which reads as a routing mystery.
                appendRouteReceipt(
                    "GOLD pipeline error transcriptCharacters="
                        + "\(transcript.count) errorType="
                        + String(describing: type(of: error))
                        + " contextPersisted="
                        + (contextPersisted ? "true" : "false")
                )
            }

            if !Task.isCancelled {
                voiceState = .idle
                scheduleTransientHideIfNeeded()
            }
        }
    }

    /// One visible deadline owner for the entire capture + encode + CLI path.
    /// The generation prevents an old watchdog from cancelling or overwriting a
    /// newer request.
    private func armInteractiveResponseDeadline(
        transcript: String
    ) -> UUID {
        responseStillWorkingTask?.cancel()
        responseHardDeadlineTask?.cancel()
        let generation = UUID()
        responseDeadlineGeneration = generation

        let acknowledgedText = transcript.trimmingCharacters(
            in: .whitespacesAndNewlines
        )
        showVisibleResponse(
            acknowledgedText.isEmpty
                ? "Heard you. Working on it."
                : "Heard: \(acknowledgedText)"
        )

        responseStillWorkingTask = Task { @MainActor [weak self] in
            try? await Task.sleep(
                for: .seconds(
                    InteractiveLatencyPolicy.stillWorkingDeadline
                )
            )
            guard !Task.isCancelled,
                  let self,
                  self.responseDeadlineGeneration == generation else {
                return
            }
            self.showVisibleResponse("Still working on your request…")
            self.appendRouteReceipt(
                "GOLD still-working deadline="
                    + "\(Int(InteractiveLatencyPolicy.stillWorkingDeadline))s"
            )
        }

        responseHardDeadlineTask = Task { @MainActor [weak self] in
            try? await Task.sleep(
                for: .seconds(
                    InteractiveLatencyPolicy.hardFailureDeadline
                )
            )
            guard !Task.isCancelled,
                  let self,
                  self.responseDeadlineGeneration == generation else {
                return
            }
            self.showVisibleResponse(
                "The default brain reached Ace's conversational "
                    + "\(Int(InteractiveLatencyPolicy.hardFailureDeadline))"
                    + "-second deadline. Saving the correlated failure receipt now."
            )
            self.goldAnswerInterruption = .deadline
            self.claudeAPI.cancelInFlightAnswer()
            self.currentResponseTask?.cancel()
            self.responseHardDeadlineTask = nil
            self.appendRouteReceipt(
                "GOLD hard-deadline="
                    + "\(Int(InteractiveLatencyPolicy.hardFailureDeadline))s"
                    + " provider-termination-pending"
            )
        }
        return generation
    }

    private func disarmInteractiveResponseDeadline(
        generation: UUID
    ) {
        guard responseDeadlineGeneration == generation else { return }
        responseDeadlineGeneration = UUID()
        responseStillWorkingTask?.cancel()
        responseStillWorkingTask = nil
        responseHardDeadlineTask?.cancel()
        responseHardDeadlineTask = nil
    }

    /// If the cursor is in transient mode (user toggled "Show BlackLabel" off),
    /// waits for TTS playback and any pointing animation to finish, then
    /// fades out the overlay after a 1-second pause. Cancelled automatically
    /// if the user starts another push-to-talk interaction.
    private func scheduleTransientHideIfNeeded() {
        guard !isBlackLabelCursorEnabled && isOverlayVisible else { return }

        transientHideTask?.cancel()
        transientHideTask = Task {
            // Wait for TTS audio to finish playing
            while noraVoice.isPlaying {
                try? await Task.sleep(nanoseconds: 200_000_000)
                guard !Task.isCancelled else { return }
            }

            // Wait for pointing animation to finish (location is cleared
            // when the buddy flies back to the cursor)
            while detectedElementScreenLocation != nil {
                try? await Task.sleep(nanoseconds: 200_000_000)
                guard !Task.isCancelled else { return }
            }

            // Pause 1s after everything finishes, then fade out
            try? await Task.sleep(nanoseconds: 1_000_000_000)
            guard !Task.isCancelled else { return }
            overlayWindowManager.fadeOutAndHideOverlay()
            isOverlayVisible = false
        }
    }

    /// Speaks an honest error message when the brain call or TTS fails. The
    /// upstream base spoke a canned "out of credits" line blaming its original
    /// author for EVERY failure — a misdiagnosis (a codex timeout isn't a credit
    /// problem). Always speaks through Nora (the subprocess TTS), never the raw
    /// system synthesizer — see the inline note below for why, even here on the
    /// path where the TTS call itself may have just failed.
    private func speakBrainErrorFallback(failureReason: String) {
        // Was: "Sorry, I hit a snag answering that one. Give me a second and
        // ask me again." It named no cause and ordered the owner to re-say a
        // question Ace had already heard. The real failure reason travels with
        // the terminal now, so the spoken line can name it.
        let utterance = AceReasoningRecoveryPolicy
            .goldFailureSpokenText(failureReason: failureReason)
        showVisibleResponse(utterance)
        voiceState = .responding
        // Speak errors in NORA (the subprocess TTS), never NSSpeechSynthesizer — the
        // raw synthesizer only has the low-quality default voice, so a brain hiccup
        // would jarringly drop Ace into the wrong voice. If Nora itself can't render,
        // silence is better than that voice.
        Task { try? await noraVoice.speakText(utterance) }
    }

    // MARK: - Point Tag Parsing

    /// Result of parsing a [POINT:...] tag from Claude's response.
    struct PointingParseResult {
        /// The response text with the [POINT:...] tag removed — this is what gets spoken.
        let spokenText: String
        /// The parsed pixel coordinate, or nil if Claude said "none" or no tag was found.
        let coordinate: CGPoint?
        /// Short label describing the element (e.g. "run button"), or "none".
        let elementLabel: String?
        /// Immutable capture identity echoed by the brain and matched locally.
        let captureIdentity: ScreenCaptureIdentity?
        let confidence: Double?
        let rejectionReason: String?
    }

    /// Accepts only a current immutable capture UUID + display ID, bounded
    /// coordinates, and confidence at or above the local threshold. Legacy
    /// screen-array indices and missing identities produce no pointer.
    static func parsePointingCoordinates(
        from responseText: String,
        captures: [CompanionScreenCapture]
    ) -> PointingParseResult {
        switch PointTargetDecoder.decode(
            responseText,
            captures: captures.map(\.identity)
        ) {
        case let .target(spokenText, target):
            return PointingParseResult(
                spokenText: spokenText,
                coordinate: CGPoint(
                    x: target.imageX,
                    y: target.imageY
                ),
                elementLabel: target.label,
                captureIdentity: target.capture,
                confidence: target.confidence,
                rejectionReason: nil
            )
        case let .none(spokenText):
            return PointingParseResult(
                spokenText: spokenText,
                coordinate: nil,
                elementLabel: "none",
                captureIdentity: nil,
                confidence: nil,
                rejectionReason: nil
            )
        case let .rejected(spokenText, reason):
            return PointingParseResult(
                spokenText: spokenText,
                coordinate: nil,
                elementLabel: nil,
                captureIdentity: nil,
                confidence: nil,
                rejectionReason: reason
            )
        }
    }

    // MARK: - Onboarding Video

    /// Black Label Assistant ships no onboarding video. The upstream base streamed
    /// a personal intro clip from a third-party host (Mux); this product contacts
    /// no external service, so we skip straight to the prompt that invites the user
    /// to try the push-to-talk shortcut.
    func setupOnboardingVideo() {
        showOnboardingVideo = false
        cancelOnboardingPromptStream()
        guard !StealthEntryLatch.shared.isRaised,
              !StealthVisibilityGate.shared.isActive,
              !stealthMode.isActive else {
            return
        }
        let generation = onboardingPromptGeneration
        onboardingPromptStartTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(300))
            guard let self,
                  OnboardingPromptCallbackAdmission.isCurrent(
                    expectedGeneration: generation,
                    currentGeneration: self.onboardingPromptGeneration,
                    taskIsCancelled: Task.isCancelled,
                    stealthIsActive:
                        StealthEntryLatch.shared.isRaised
                            || StealthVisibilityGate.shared.isActive
                            || self.stealthMode.isActive
                  ) else {
                return
            }
            self.onboardingPromptStartTask = nil
            self.startOnboardingPromptStream(generation: generation)
        }
    }

    func tearDownOnboardingVideo() {
        cancelOnboardingPromptStream()
        cancelOnboardingDemoInteraction()
        showOnboardingVideo = false
        if let timeObserver = onboardingDemoTimeObserver {
            onboardingVideoPlayer?.removeTimeObserver(timeObserver)
            onboardingDemoTimeObserver = nil
        }
        onboardingVideoPlayer?.pause()
        onboardingVideoPlayer = nil
        if let observer = onboardingVideoEndObserver {
            NotificationCenter.default.removeObserver(observer)
            onboardingVideoEndObserver = nil
        }
    }

    private func cancelOnboardingPromptStream() {
        onboardingPromptGeneration = UUID()
        onboardingPromptStartTask?.cancel()
        onboardingPromptStartTask = nil
        onboardingPromptDismissTask?.cancel()
        onboardingPromptDismissTask = nil
        onboardingPromptTimer?.invalidate()
        onboardingPromptTimer = nil
        onboardingPromptCharacterIndex = 0
        onboardingPromptOpacity = 0.0
        showOnboardingPrompt = false
        onboardingPromptText = ""
    }

    private func startOnboardingPromptStream(generation: UUID) {
        guard OnboardingPromptCallbackAdmission.isCurrent(
            expectedGeneration: generation,
            currentGeneration: onboardingPromptGeneration,
            taskIsCancelled: false,
            stealthIsActive:
                StealthEntryLatch.shared.isRaised
                    || StealthVisibilityGate.shared.isActive
                    || stealthMode.isActive
        ) else {
            return
        }
        let message =
            "hold \(BuddyPushToTalkShortcut.pushToTalkDisplayText) "
                + "and introduce yourself"
        onboardingPromptText = ""
        showOnboardingPrompt = true
        onboardingPromptOpacity = 0.0
        onboardingPromptCharacterIndex = 0

        withAnimation(.easeIn(duration: 0.4)) {
            onboardingPromptOpacity = 1.0
        }

        onboardingPromptTimer = Timer.scheduledTimer(
            withTimeInterval: 0.03,
            repeats: true
        ) { [weak self] timer in
            let shouldInvalidate = MainActor.assumeIsolated {
                guard let self,
                      OnboardingPromptCallbackAdmission.isCurrent(
                        expectedGeneration: generation,
                        currentGeneration:
                            self.onboardingPromptGeneration,
                        taskIsCancelled: false,
                        stealthIsActive:
                            StealthEntryLatch.shared.isRaised
                                || StealthVisibilityGate.shared.isActive
                                || self.stealthMode.isActive
                      ) else {
                    return true
                }
                guard self.onboardingPromptCharacterIndex
                        < message.count else {
                    self.onboardingPromptTimer = nil
                    self.onboardingPromptDismissTask =
                        Task { @MainActor [weak self] in
                            try? await Task.sleep(for: .seconds(10))
                            guard let self,
                                  OnboardingPromptCallbackAdmission
                                    .isCurrent(
                                        expectedGeneration: generation,
                                        currentGeneration:
                                            self
                                                .onboardingPromptGeneration,
                                        taskIsCancelled:
                                            Task.isCancelled,
                                        stealthIsActive:
                                            StealthEntryLatch.shared
                                                .isRaised
                                                || StealthVisibilityGate
                                                    .shared.isActive
                                                || self.stealthMode
                                                    .isActive
                                    ),
                                  self.showOnboardingPrompt else {
                                return
                            }
                            withAnimation(.easeOut(duration: 0.3)) {
                                self.onboardingPromptOpacity = 0.0
                            }
                            try? await Task.sleep(
                                for: .milliseconds(350)
                            )
                            guard OnboardingPromptCallbackAdmission
                                .isCurrent(
                                    expectedGeneration: generation,
                                    currentGeneration:
                                        self.onboardingPromptGeneration,
                                    taskIsCancelled: Task.isCancelled,
                                    stealthIsActive:
                                        StealthEntryLatch.shared.isRaised
                                            || StealthVisibilityGate
                                                .shared.isActive
                                            || self.stealthMode.isActive
                                ) else {
                                    return
                                }
                            self.showOnboardingPrompt = false
                            self.onboardingPromptText = ""
                            self.onboardingPromptDismissTask = nil
                        }
                    return true
                }
                let index = message.index(
                    message.startIndex,
                    offsetBy: self.onboardingPromptCharacterIndex
                )
                self.onboardingPromptText.append(message[index])
                self.onboardingPromptCharacterIndex += 1
                return false
            }
            if shouldInvalidate {
                timer.invalidate()
            }
        }
    }

    /// Gradually raises an AVPlayer's volume from its current level to the
    /// target over the specified duration, creating a smooth audio fade-in.
    private func fadeInVideoAudio(player: AVPlayer, targetVolume: Float, duration: Double) {
        let steps = 20
        let stepInterval = duration / Double(steps)
        let volumeIncrement = (targetVolume - player.volume) / Float(steps)
        var stepsRemaining = steps

        Timer.scheduledTimer(withTimeInterval: stepInterval, repeats: true) { timer in
            let shouldInvalidate = MainActor.assumeIsolated {
                stepsRemaining -= 1
                player.volume += volumeIncrement

                if stepsRemaining <= 0 {
                    player.volume = targetVolume
                    return true
                }
                return false
            }
            if shouldInvalidate {
                timer.invalidate()
            }
        }
    }

    // MARK: - Onboarding Demo Interaction

    private static let onboardingDemoSystemPrompt = """
    you're Ace, a small gold gem cursor living on the user's screen. you're showing off during onboarding — look at their screen and find ONE specific, concrete thing to point at. pick something with a clear name or identity: a specific app icon (say its name), a specific word or phrase of text you can read, a specific filename, a specific button label, a specific tab title, a specific image you can describe. do NOT point at vague things like "a window" or "some text" — be specific about exactly what you see.

    make a short quirky 3-6 word observation about the specific thing you picked — something fun, playful, or curious that shows you actually read/recognized it. no emojis ever. NEVER quote or repeat text you see on screen — just react to it. keep it to 6 words max, no exceptions.

    CRITICAL COORDINATE RULE: you MUST only pick elements near the CENTER of the screen. your x coordinate must be between 20%-80% of the image width. your y coordinate must be between 20%-80% of the image height. do NOT pick anything in the top 20%, bottom 20%, left 20%, or right 20% of the screen. no menu bar items, no dock icons, no sidebar items, no items near any edge. only things clearly in the middle area of the screen. if the only interesting things are near the edges, pick something boring in the center instead.

    respond with ONLY your short comment followed by the coordinate tag. nothing else. all lowercase.

    format: your comment [POINT:capture=<exact capture_id from the image label>;display=<exact display_id from the image label>;x=<pixel x>;y=<pixel y>;confidence=<0 to 1>;label=<short label>]

    never omit or alter either identity. never use a screen number or image-array position.

    the screenshot images are labeled with their pixel dimensions. use those dimensions as the coordinate space. origin (0,0) is top-left. x increases rightward, y increases downward.
    """

    /// Captures a screenshot and asks Claude to find something interesting to
    /// point at, then triggers the buddy's flight animation. Used during
    /// onboarding to demo the pointing feature while the intro video plays.
    func performOnboardingDemoInteraction() {
        // Don't interrupt an active voice response
        guard (voiceState == .idle || voiceState == .responding),
              !StealthEntryLatch.shared.isRaised,
              directEffectsAreAllowed else { return }

        cancelOnboardingDemoInteraction()
        let generation = onboardingDemoInteractionGeneration
        onboardingDemoInteractionTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                if self.onboardingDemoInteractionGeneration
                    == generation {
                    self.onboardingDemoInteractionTask = nil
                }
            }
            do {
                guard self.onboardingDemoInteractionIsCurrent(
                    generation
                ) else {
                    return
                }
                let screenCaptures = try await
                    CompanionScreenCaptureUtility
                        .captureAllScreensAsJPEG()
                guard self.onboardingDemoInteractionIsCurrent(
                    generation
                ) else {
                    return
                }

                // Only send the cursor screen so Claude can't pick something
                // on a different monitor that we can't point at.
                guard let cursorScreenCapture = screenCaptures.first(where: { $0.isCursorScreen }) else {
                    print("🎯 Onboarding demo: no cursor screen found")
                    return
                }

                let dimensionInfo = " (image dimensions: \(cursorScreenCapture.screenshotWidthInPixels)x\(cursorScreenCapture.screenshotHeightInPixels) pixels)"
                let labeledImages = [(data: cursorScreenCapture.imageData, label: cursorScreenCapture.label + dimensionInfo)]

                guard self.onboardingDemoInteractionIsCurrent(
                    generation
                ) else {
                    return
                }
                let (fullResponseText, _) = try await self.claudeAPI
                    .analyzeImageStreaming(
                    images: labeledImages,
                    systemPrompt: Self.onboardingDemoSystemPrompt,
                    userPrompt: "look around my screen and find something interesting to point at",
                    responseFormat:
                        AcePointingProviderPolicy.encoding(
                            for: BrainBackend.selectedCLI
                        ) == .localJSON
                            ? .localPointingJSON : .conversational,
                    interactiveLatencyProfile:
                        InteractiveProviderLatencyPolicy.profile(
                            for: .screenAnswer,
                            includesScreenContext: true
                        ),
                    onTextChunk: { _ in }
                )
                guard self.onboardingDemoInteractionIsCurrent(
                    generation
                ) else {
                    return
                }

                let parseResult = Self.parsePointingCoordinates(
                    from: fullResponseText,
                    captures: [cursorScreenCapture]
                )

                guard let pointCoordinate = parseResult.coordinate else {
                    print("🎯 Onboarding demo: no element to point at")
                    return
                }

                let screenshotWidth = CGFloat(cursorScreenCapture.screenshotWidthInPixels)
                let screenshotHeight = CGFloat(cursorScreenCapture.screenshotHeightInPixels)
                let displayWidth = CGFloat(cursorScreenCapture.displayWidthInPoints)
                let displayHeight = CGFloat(cursorScreenCapture.displayHeightInPoints)
                let displayFrame = cursorScreenCapture.displayFrame

                let clampedX = max(0, min(pointCoordinate.x, screenshotWidth))
                let clampedY = max(0, min(pointCoordinate.y, screenshotHeight))
                let displayLocalX = clampedX * (displayWidth / screenshotWidth)
                let displayLocalY = clampedY * (displayHeight / screenshotHeight)
                let appKitY = displayHeight - displayLocalY
                let globalLocation = CGPoint(
                    x: displayLocalX + displayFrame.origin.x,
                    y: appKitY + displayFrame.origin.y
                )

                // Set custom bubble text so the pointing animation uses Claude's
                // comment instead of a random phrase
                guard self.performDirectEffectCommit({
                    [weak self] in
                    guard let self,
                          self
                            .onboardingDemoInteractionGeneration
                            == generation,
                          !Task.isCancelled else {
                        return false
                    }
                    self.detectedElementBubbleText =
                        parseResult.spokenText
                    self.detectedElementScreenLocation =
                        globalLocation
                    self.detectedElementDisplayFrame = displayFrame
                    self.markDetectedElementAsVerified()
                    print(
                        "🎯 Onboarding demo: point selected "
                            + "labelPresent="
                            + "\(parseResult.elementLabel != nil) "
                            + "spokenCharacters="
                            + "\(parseResult.spokenText.count)"
                    )
                    return true
                }) else {
                    return
                }
            } catch {
                guard self.onboardingDemoInteractionIsCurrent(
                    generation
                ) else {
                    return
                }
                print(
                    "⚠️ Onboarding demo errorType="
                        + String(describing: type(of: error))
                )
            }
        }
    }

    private func onboardingDemoInteractionIsCurrent(
        _ generation: UUID
    ) -> Bool {
        !Task.isCancelled
            && onboardingDemoInteractionGeneration == generation
            && !StealthEntryLatch.shared.isRaised
            && directEffectsAreAllowed
    }

    private func cancelOnboardingDemoInteraction() {
        onboardingDemoInteractionGeneration = UUID()
        onboardingDemoInteractionTask?.cancel()
        onboardingDemoInteractionTask = nil
    }
}
#endif // circuit-convert
